#!/usr/bin/env bash
set -euo pipefail

# vfio-gpu-passthrough-setup.sh
# Interactive multi-vendor (AMD/NVIDIA/Intel) GPU passthrough helper.
#
# Design goals (safety first):
# - Bind ONLY the selected guest GPU (and selected associated PCI functions) to vfio-pci.
# - Prefer PCI addresses (BDF) over vendor:device IDs to avoid repeated-ID traps.
#   Example: BOTH AMD HDMI audio controllers can share the same PCI ID (1002:ab28).
# - Optional driver blacklisting (explicit user choice).
# - Adaptive kernel IOMMU params (intel_iommu=on vs amd_iommu=on).
# - Optional user-systemd unit to force the host default audio sink after login.
#
# “Bulletproof” behaviors:
# - Atomic writes for generated files (no partial writes).
# - GRUB edits: modify ONLY the existing cmdline line (no adding new lines), and avoid dup params.
# - Sanity checks before writing config / enabling services.

SCRIPT_NAME="$(basename "$0")"

# --- Configuration ---
CONF_FILE="/etc/vfio-gpu-passthrough.conf"
BIND_SCRIPT="/usr/local/sbin/vfio-bind-selected-gpu.sh"
AUDIO_SCRIPT="/usr/local/bin/vfio-set-host-audio.sh"
OPENBOX_MONITOR_SCRIPT="/usr/local/bin/vfio-openbox-activate-monitors.sh"
OPENBOX_AUTOSTART_FILE="/etc/xdg/openbox/autostart"
SYSTEMD_UNIT="/etc/systemd/system/vfio-bind-selected-gpu.service"
MODULES_LOAD="/etc/modules-load.d/vfio.conf"
BLACKLIST_FILE="/etc/modprobe.d/vfio-optional-blacklist.conf"
SOFTDEP_FILE="/etc/modprobe.d/vfio-softdep.conf"
DRACUT_VFIO_CONF="/etc/dracut.conf.d/10-vfio.conf"
UDEV_ISOLATION_RULE="/etc/udev/rules.d/99-vfio-isolation.rules"
USB_BT_SCRIPT="/usr/local/sbin/vfio-usb-bluetooth.sh"
USB_BT_SYSTEMD_UNIT="/etc/systemd/system/vfio-disable-usb-bluetooth.service"
USB_BT_UDEV_RULE="/etc/udev/rules.d/99-vfio-disable-usb-bluetooth.rules"
USB_BT_MATCH_CONF="/etc/vfio-usb-bluetooth-match.conf"
USB_BT_STATE_FILE="/var/lib/vfio-usb-bt-mitigation.state"
LIGHTDM_FALLBACK_CONF="/etc/lightdm/lightdm.conf.d/90-vfio-greeter-fallback.conf"
XORG_HOST_GPU_CONF="/etc/X11/xorg.conf.d/20-vfio-host-gpu.conf"
LIGHTDM_HOST_GPU_CONF="/etc/lightdm/lightdm.conf.d/90-vfio-host-gpu.conf"
GRAPHICS_DAEMON_SCRIPT="/usr/local/sbin/vfio-graphics-protocold.sh"
GRAPHICS_DAEMON_UNIT="/etc/systemd/system/vfio-graphics-protocold.service"
GRAPHICS_DAEMON_WANTS_LINK="/etc/systemd/system/multi-user.target.wants/vfio-graphics-protocold.service"
LIBVIRT_HOOK_DIR="/etc/libvirt/hooks"
LIBVIRT_HOOK_ENTRY="$LIBVIRT_HOOK_DIR/qemu"
LIBVIRT_HOOK_SCRIPT="/usr/local/sbin/vfio-libvirt-hook.sh"
# Plasma/KWin Wayland session env drop-in that pins the compositor's render
# device to the HOST GPU. Without this, on a dual-GPU setup where the guest GPU
# is Boot VGA (boot_vga=1), KWin renders on the guest GPU and binding it to
# vfio-pci at VM start crashes the compositor mid-frame (kwin_wayland SEGV in
# GLVertexBuffer::endOfFrame). See install_wayland_render_device_pin().
KWIN_RENDER_PIN_FILE="/etc/xdg/plasma-workspace/env/vfio-kwin-render-device.sh"
# Generic login-shell env drop-in (sourced by /etc/profile.d) that pins BOTH
# KWin (KWIN_DRM_DEVICES) and wlroots-based compositors (WLR_DRM_DEVICES:
# sway/hyprland/labwc/wlroots) to the HOST GPU. Covers compositors launched
# from a login shell (TTY start); the Plasma drop-in above covers DM-launched
# Plasma. Same rationale as KWIN_RENDER_PIN_FILE.
WLR_RENDER_PIN_FILE="/etc/profile.d/vfio-wayland-render-device.sh"
# Reboot-FLR monitor: a systemd service that watches libvirt for guest reboot
# lifecycle events and does a soft function-level reset on the guest GPU to
# clear the display wedge that otherwise freezes the screen on a warm reboot
# (on_reboot=restart). On RX 9070 / RDNA4 the card SURVIVES a warm reboot
# (qemu never releases the vfio device, so the PCIe link stays up), but the
# GPU's display engine wedges in the old guest's framebuffer and OVMF cannot
# re-POST (frozen screen). A soft FLR clears the display wedge without
# dropping the link, so OVMF can re-POST and the guest reboots cleanly.
# Removed by --reset and by --install-early-binding (early binding doesn't
# keep the VM running through a reboot the same way).
REBOOT_FLR_SCRIPT="/usr/local/sbin/vfio-reboot-flr-monitor.sh"
REBOOT_FLR_UNIT="/etc/systemd/system/vfio-reboot-flr.service"
# Park-keepalive monitor: a systemd service (dynamic binding only) that
# periodically checks whether the guest GPU parked on vfio-pci between VM
# sessions (VFIO_DYNAMIC_REBIND_HOST=0, the default) is still alive, and
# proactively runs the same remove+rescan bus recovery used at --release time
# if it has died (RX 9070 / RDNA4 reset bug). This is the PROACTIVE complement
# to the reactive release-time zombie recovery in the bind script: it catches
# a card that dies while parked BETWEEN VM stop/start events, not just at the
# moment of VM stop. Installed and enabled automatically (instant on) whenever
# dynamic binding is installed; disable via VFIO_DYNAMIC_PARK_KEEPALIVE=0 in
# $CONF_FILE. Removed by --install-early-binding and by --reset.
PARK_KEEPALIVE_SCRIPT="/usr/local/sbin/vfio-gpu-park-keepalive.sh"
PARK_KEEPALIVE_UNIT="/etc/systemd/system/vfio-gpu-park-keepalive.service"
# Park-keepalive extensions (all instant on, same rationale as above):
# - STATE_FILE: persists the consecutive-failure streak across daemon restarts
#   and one-shot invocations (udev/resume-triggered), so backoff + the
#   one-time notify threshold work correctly regardless of trigger source.
# - RESUME_HOOK: a systemd-sleep drop-in that runs one immediate check right
#   after resume from suspend/hibernate (S3/S4 sleep is a common D3cold
#   trigger), instead of waiting up to the full poll interval.
# - CHECK_UNIT: a oneshot systemd service (ExecStart=... --once) triggered
#   on-demand by the udev rule below; shares all logic with the daemon.
# - UDEV_RULE: best-effort supplementary trigger. CAVEAT: the RX 9070/RDNA4
#   zombie state does NOT emit a PCI "remove" uevent (that is the bug — the
#   kernel does not know the device died), so this only helps for state
#   changes that DO emit uevents (e.g. driver bind/unbind, our own
#   remove+rescan). The poll + resume hook remain the primary defenses.
PARK_KEEPALIVE_STATE_FILE="/var/lib/vfio-dynamic/park-keepalive.state"
PARK_KEEPALIVE_RESUME_HOOK="/usr/lib/systemd/system-sleep/vfio-gpu-park-keepalive-resume.sh"
PARK_KEEPALIVE_CHECK_UNIT="/etc/systemd/system/vfio-gpu-park-keepalive-check.service"
PARK_KEEPALIVE_UDEV_RULE="/etc/udev/rules.d/99-vfio-park-keepalive.rules"
# vBIOS ROM auto-injection (dynamic binding only): QEMU/vfio-pci reads the
# guest GPU's option ROM live from sysfs at VM start, which can be unreliable
# after a reset (dmesg: "Invalid PCI ROM header signature"), leaving the guest
# with a black screen even though the PCI device itself is alive and bound.
# install_vbios_romfile() auto-detects a matching *.rom dump in a VBIOS/ folder
# next to this script (matched by the ROM's own embedded PCI Vendor:Device ID,
# so a non-matching dump is never used), copies it to this stable runtime
# location, and pins it via <rom file='...'/> in each shut-off guest-GPU VM's
# hostdev. Removed by --install-early-binding and by --reset.
VBIOS_RUNTIME_DIR="/var/lib/libvirt/vbios"
# Live-attach (hotplug GPU) support: an optional binding method where the VM
# starts WITHOUT the GPU (Windows boots on a virtual display), and after a
# configurable delay the GPU is bound to vfio-pci and hot-attached to the
# running VM via `virsh attach-device --live`. This sidesteps qemu's
# attach-time bus reset on a parked (previously-used) card — the reset bug
# that kills the RX 9070 / RDNA4 on the second VM start. With live-attach,
# the GPU is hot-added to a running Windows that has already loaded the AMD
# driver, so the card is properly initialized before qemu's attach reset
# fires. The VM XML is modified to REMOVE the PCI GPU hostdevs (so libvirt
# starts without the GPU); the GPU device XML is saved separately and
# hot-attached by the live-attach helper after the delay.
LIVE_ATTACH_HELPER="/usr/local/sbin/vfio-live-attach.sh"
LIVE_ATTACH_GPU_XML="/var/lib/vfio-dynamic/live-attach-gpu.xml"
LIVE_ATTACH_AUDIO_XML="/var/lib/vfio-dynamic/live-attach-audio.xml"
LIVE_ATTACH_VM_LIST="/var/lib/vfio-dynamic/live-attach-vms"
# Reboot-persistent hugepages re-reserve (ultimate-perf only): after a host
# reboot /proc/sys/vm/nr_hugepages resets to 0, but the per-VM ownership files
# (*_perf_hugepages_owned.txt) persist in the perf backup dir. Without a
# boot-time re-reserve, a hugepages-backed VM (memoryBacking/hugepages) fails
# to start with "unable to map backing store for guest RAM: Cannot allocate
# memory" until the operator manually re-runs --install-ultimate-perf-vm-tuning.
# This oneshot service reads the registry of perf backup dirs (one owned-file
# dir per line in PERF_HP_DIRS_FILE), sums the owned counts, and re-reserves the
# pool at boot before libvirt starts autostart VMs. Installed/enabled
# automatically when hugepages is opted in during --install-ultimate-perf-vm-tuning;
# removed by --reset-ultimate-perf-vm-tuning (when no owned files remain) and --reset.
PERF_HP_BOOT_SCRIPT="/usr/local/sbin/vfio-perf-hugepages-reserve.sh"
PERF_HP_BOOT_UNIT="/etc/systemd/system/vfio-perf-hugepages-reserve.service"
PERF_HP_DIRS_FILE="/var/lib/vfio-dynamic/perf-hugepages-dirs"
# virtio-win guest-agent support (smart live-attach handoff). The live-attach
# helper polls the qemu guest agent (guest-ping) so the GPU hot-attaches the
# MOMENT Windows is up instead of after a blind fixed delay; that needs the
# virtio-win guest agent installed INSIDE Windows. These constants let
# --install-virtio-win-guest-agent resolve the driver ISO: the distro package
# (dnf/zypper) drops it at VIRTIO_WIN_ISO_PATH; on distros without the package
# the stable ISO is downloaded to VIRTIO_WIN_FALLBACK_ISO from VIRTIO_WIN_STABLE_URL.
# The helper's fixed-delay FALLBACK still works until the agent is installed.
VIRTIO_WIN_ISO_PATH="/usr/share/virtio-win/virtio-win.iso"
VIRTIO_WIN_FALLBACK_ISO="/var/lib/vfio-dynamic/virtio-win.iso"
VIRTIO_WIN_STABLE_URL="https://fedorapeople.org/groups/virt/virtio-win/direct-downloads/stable-virtio/virtio-win.iso"
# Archive of EVERY released virtio-win ISO (directory listing sorted by
# modification date). Surfaced during dynamic-binding setup and in
# --install-virtio-win-guest-agent output so the operator can pick a specific
# version instead of only the stable ISO.
VIRTIO_WIN_ARCHIVE_URL="https://fedorapeople.org/groups/virt/virtio-win/direct-downloads/archive-virtio/?C=M;O=A"
# The fedorapeople virtio-win repo file. On Fedora/RHEL-family, virtio-win is NOT
# in the default repos, so --install-virtio-win-guest-agent adds this repo to
# /etc/yum.repos.d/virtio-win.repo before `dnf install virtio-win` (the proven fix).
VIRTIO_WIN_REPO_URL="https://fedorapeople.org/groups/virt/virtio-win/virtio-win.repo"
# Stable virtio-win RPM (for the openSUSE manual-install fallback when zypper has no
# matching repo): download it and `sudo rpm -iv virtio-win.noarch.rpm`.
VIRTIO_WIN_RPM_URL="https://fedorapeople.org/groups/virt/virtio-win/direct-downloads/stable-virtio/virtio-win.noarch.rpm"
# Self-install: --install-self copies this script to /usr/local/bin/vfio (on
# PATH for both root and users; the generated boot-time helpers stay in
# /usr/local/sbin) and drops the
# shell completions into the vendor auto-load directories so they load with no
# 'source' step. --uninstall-self removes both (separate from --reset, which
# stays scoped to VFIO config). The repo copy is never touched.
SELF_INSTALL_BIN="/usr/local/bin/vfio"
FISH_COMPLETION_DIR="/usr/share/fish/vendor_completions.d"
BASH_COMPLETION_DIR="/usr/share/bash-completion/completions"
ZSH_COMPLETION_DIR="/usr/share/zsh/site-functions"

DEBUG=0
DRY_RUN=0
JSON_OUTPUT=0
DEBUG_CMDLINE_TOKENS=0
DEBUG_CMDLINE_TOKENS_ENTRY_FILTER=""
MODE="install"   # install | verify | detect | sync-bls-only | debug-cmdline-tokens | verify-bls-sync | verify-bls-nosnapper | create-fallback-entry | self-test | health-check | reset | reset-usb-mitigation | usb-mitigation-status | disable-bootlog | install-bootlog | install-graphics-daemon | install-dynamic-binding | install-early-binding | install-stealth-vm-tuning | install-live-attach | install-virtio-win-guest-agent | install-ultimate-perf-vm-tuning | reset-ultimate-perf-vm-tuning | menu | install-self | uninstall-self | completion printers
BOOT_VGA_POLICY_OVERRIDE=""   # AUTO | STRICT (empty = use script default)
GRAPHICS_PROTOCOL_OVERRIDE="" # AUTO | X11 | WAYLAND (empty = auto-detect)
AMD_RUNPM_OVERRIDE=""         # 1=force add, 0=force skip, empty=prompt (install mode only)
AMD_NORETRY_OVERRIDE=""       # 1=force add, 0=force skip, empty=prompt (install mode only)
AMD_D3_OVERRIDE=""            # 1=force add, 0=force skip, empty=prompt (install mode only)
AMD_PORTPM_OVERRIDE=""        # 1=force add, 0=force skip, empty=prompt (install mode only)
STEALTH_VM_TUNING_OVERRIDE="" # 1=force on, 0=force skip, empty=prompt (dynamic install: stealth/perf VM XML tuning)
ULTIMATE_PERF_HUGEPAGES_OVERRIDE="" # 1=force on, 0=force off, empty=prompt (ultimate-perf VM tuning: host hugepages reservation)
ULTIMATE_PERF_VIRTIO_DISK_OVERRIDE="" # 1=force on, 0=force off, empty=prompt (ultimate-perf VM tuning: SATA->virtio disk conversion)
ULTIMATE_PERF_VM_TUNING_OVERRIDE="" # 1=force on, 0=force skip, empty=prompt (dynamic install: ultimate-perf VM XML tuning)
VBIOS_INJECTION_OVERRIDE=""   # 1=force on, 0=force skip+remove, empty=prompt (dynamic install: vBIOS ROM pin)
BINDING_MODE_OVERRIDE=""      # early | dynamic (empty = auto-detect / prompt in install mode)
INSTALL_GRAPHICS_DAEMON=1     # 1=install graphics protocol daemon, 0=skip
GRAPHICS_DAEMON_INTERVAL_DEFAULT=1
GRAPHICS_WATCHDOG_RETENTION_DAYS_DEFAULT=10
GRAPHICS_WATCHDOG_MAX_LINES_DEFAULT=5000
GRAPHICS_DAEMON_INTERVAL_OVERRIDE="" # positive integer seconds (empty = default)
RUN_TS="$(date +%Y%m%d-%H%M%S)"

# Global context structure used to separate detection, user selection and
# application logic. Keys are documented near detect_system/user_selection.
# Example keys:
#   CTX[bootloader]           - detected bootloader (grub/systemd-boot/...) 
#   CTX[guest_gpu]            - selected guest GPU BDF
#   CTX[host_gpu]             - selected host GPU BDF
#   CTX[guest_audio_csv]      - CSV of guest audio BDFs
#   CTX[host_audio_bdfs_csv]  - CSV of host audio BDFs
#   CTX[host_audio_node_name] - PipeWire node name for host default sink
#   CTX[guest_vendor]         - guest GPU vendor ID (e.g. 1002)
#
# This keeps the wizard's state explicit and makes it easier to extend.
declare -Ag CTX=()

# Color output (ANSI). Set NO_COLOR=1 to disable.
ENABLE_COLOR=1
if [[ -n "${NO_COLOR:-}" ]]; then
  ENABLE_COLOR=0
fi

CSI=$'\033['
C_RESET="${CSI}0m"
C_BOLD="${CSI}1m"
C_DIM="${CSI}2m"
C_RED="${CSI}31m"
C_GREEN="${CSI}32m"
C_YELLOW="${CSI}33m"
C_BLUE="${CSI}34m"
C_CYAN="${CSI}36m"

# Track backups for rollback script generation
declare -A BACKUP_MAP=()
BACKUP_ENTRIES=()
# Regression guard: tracks attempted writes to snapper-* BLS entries.
VFIO_BLS_SNAPPER_WRITE_ATTEMPTS=0
declare -ag VFIO_BLS_SNAPPER_WRITE_ATTEMPT_PATHS=()

say() { printf '%s\n' "$*"; }
die() { say "ERROR: $*" >&2; exit 1; }

need_cmd() { command -v "$1" >/dev/null 2>&1 || die "Missing required command: $1"; }

have_cmd() { command -v "$1" >/dev/null 2>&1; }

# Optional TUI support (whiptail/dialog-style). If not available, we fall back
# to the existing plain-text prompts. This keeps the script usable everywhere
# while offering a nicer UI when possible.
HAS_TUI=0
if command -v whiptail >/dev/null 2>&1; then
  HAS_TUI=1
fi

run() {
  # Print commands in debug mode; honor DRY_RUN.
  if (( DEBUG )); then
    say "+ $*"
  fi
  if (( DRY_RUN )); then
    return 0
  fi
  "$@"
}

# Print a clickable file:// hyperlink for $1 (an absolute path). Uses the OSC 8
# terminal hyperlink escape so modern terminals (Warp, iTerm2, kitty, etc.) make
# the path clickable to open the file. Falls back to plain text when color is
# disabled or the path does not exist. $2 (optional) overrides the display text
# (defaults to the path itself).
_link() {
  local _path="$1" _text="${2:-$1}"
  if (( ! ENABLE_COLOR )) || [[ ! -e "$_path" ]]; then
    printf '%s' "$_text"
    return 0
  fi
  local _abs
  _abs="$(readlink -f "$_path" 2>/dev/null || echo "$_path")"
  # The \\ in the printf below is intentional: it emits the OSC 8 hyperlink
  # ST (String Terminator) byte. It is NOT a mis-escaped single quote.
  # shellcheck disable=SC1003
  printf '\033]8;;file://%s\033\\%s\033]8;;\033\\' "$_abs" "$_text"
}
# Like _link but prints with a trailing newline (for use with `say`-style lines).
_saylink() {
  say "$(_link "$@")"
}
normalize_display_manager_name() {
  # Normalize service/script names to canonical display-manager IDs.
  # Examples:
  #   sddm.service -> sddm
  #   /usr/lib/X11/displaymanagers/sddm -> sddm
  local raw="${1:-}"
  raw="${raw##*/}"
  raw="${raw%.service}"
  raw="${raw,,}"
  case "$raw" in
    lightdm|sddm|lxdm|xdm|plasmalogin) printf '%s\n' "$raw"; return 0 ;;
    gdm|gdm3) printf '%s\n' "gdm"; return 0 ;;
  esac
  return 1
}


detect_display_manager() {
  # Return one of: lightdm | sddm | gdm | lxdm | xdm | none
  # Prefer the active display-manager.service symlink when present.
  local dm_link base dm
  if [[ -L /etc/systemd/system/display-manager.service ]]; then
    dm_link="$(readlink -f /etc/systemd/system/display-manager.service 2>/dev/null || true)"
    base="$(basename "$dm_link")"
    if dm="$(normalize_display_manager_name "$base")"; then
      echo "$dm"
      return 0
    fi
    case "$dm_link" in
      *lightdm*) echo "lightdm"; return 0;;
      *sddm*) echo "sddm"; return 0;;
      *gdm*) echo "gdm"; return 0;;
      *lxdm*) echo "lxdm"; return 0;;
      *xdm*) echo "xdm"; return 0;;
      *plasmalogin*) echo "plasmalogin"; return 0;;
    esac
  fi

  # openSUSE frequently points display-manager.service to a wrapper script.
  # In that case resolve the active DM through alternatives.
  if [[ -L /usr/lib/X11/displaymanagers/default-displaymanager ]]; then
    dm_link="$(readlink -f /usr/lib/X11/displaymanagers/default-displaymanager 2>/dev/null || true)"
    base="$(basename "$dm_link")"
    if dm="$(normalize_display_manager_name "$base")"; then
      echo "$dm"
      return 0
    fi
  fi

  # Fall back to installed unit files / config presence.
  if have_cmd systemctl; then
    if systemctl list-unit-files 2>/dev/null | grep -q '^lightdm\.service'; then echo "lightdm"; return 0; fi
    if systemctl list-unit-files 2>/dev/null | grep -q '^sddm\.service'; then echo "sddm"; return 0; fi
    if systemctl list-unit-files 2>/dev/null | grep -Eq '^gdm(3)?\.service'; then echo "gdm"; return 0; fi
    if systemctl list-unit-files 2>/dev/null | grep -q '^lxdm\.service'; then echo "lxdm"; return 0; fi
    if systemctl list-unit-files 2>/dev/null | grep -q '^xdm\.service'; then echo "xdm"; return 0; fi
    if systemctl list-unit-files 2>/dev/null | grep -q '^plasmalogin\.service'; then echo "plasmalogin"; return 0; fi
  fi

  if have_cmd lightdm || [[ -d /etc/lightdm ]]; then echo "lightdm"; return 0; fi
  if have_cmd sddm || [[ -d /etc/sddm.conf.d || -f /etc/sddm.conf ]]; then echo "sddm"; return 0; fi
  if have_cmd gdm || have_cmd gdm3 || [[ -d /etc/gdm || -d /etc/gdm3 ]]; then echo "gdm"; return 0; fi
  if have_cmd lxdm || [[ -d /etc/lxdm ]]; then echo "lxdm"; return 0; fi
  if have_cmd xdm || [[ -f /etc/X11/xdm/xdm-config ]]; then echo "xdm"; return 0; fi
  if have_cmd plasmalogin || [[ -f /usr/lib/systemd/system/plasmalogin.service ]]; then echo "plasmalogin"; return 0; fi

  echo "none"
  return 1
}

lightdm_is_present() {
  [[ "$(detect_display_manager 2>/dev/null || true)" == "lightdm" ]]
}

display_manager_dependency_status() {
  # Tri-state status for display-manager dependency readiness:
  # WORKS | NOT_WORK | NOT_PRESENT
  local dm="${1:-none}"
  case "$dm" in
    lightdm)
      if accountsservice_is_present; then
        echo "WORKS"
      else
        echo "NOT_WORK"
      fi
      ;;
    sddm|gdm|lxdm|xdm|plasmalogin)
      echo "WORKS"
      ;;
    none|"")
      echo "NOT_PRESENT"
      ;;
    *)
      echo "WORKS"
      ;;
  esac
}

xorg_stack_status() {
  # WORKS if both Xorg server and X11 session files are present.
  # NOT_PRESENT if neither is present.
  # NOT_WORK for partial/incomplete state.
  local has_server=0 has_sessions=0
  if have_cmd Xorg || [[ -x /usr/bin/Xorg || -x /usr/libexec/Xorg || -x /usr/bin/X ]]; then
    has_server=1
  fi
  if compgen -G "/usr/share/xsessions/*.desktop" >/dev/null 2>&1; then
    has_sessions=1
  fi
  if have_cmd startx || have_cmd xinit; then
    has_sessions=1
  fi

  if (( has_server && has_sessions )); then
    echo "WORKS"
  elif (( ! has_server && ! has_sessions )); then
    echo "NOT_PRESENT"
  else
    echo "NOT_WORK"
  fi
}

wayland_stack_status() {
  # WORKS if Wayland session files are present and at least one session
  # Exec target resolves to an installed command/binary.
  # Fallback: common compositor/launcher command detection.
  # NOT_PRESENT if neither is present.
  # NOT_WORK for partial/incomplete state.
  local has_sessions=0 has_runtime=0
  local f exec_line exec_cmd exec_base
  if compgen -G "/usr/share/wayland-sessions/*.desktop" >/dev/null 2>&1; then
    has_sessions=1
    for f in /usr/share/wayland-sessions/*.desktop; do
      [[ -f "$f" ]] || continue
      exec_line="$(grep -m1 -E '^Exec=' "$f" 2>/dev/null || true)"
      exec_line="${exec_line#Exec=}"
      exec_cmd="$(printf '%s\n' "$exec_line" | sed -E 's/[[:space:]]+--.*$//; s/[[:space:]].*$//; s/%[fFuUdDnNickvm]//g' | tr -d '"' | head -n1)"
      exec_base="$(basename "${exec_cmd:-}")"
      if [[ -n "$exec_cmd" ]] && { command -v "$exec_cmd" >/dev/null 2>&1 || command -v "$exec_base" >/dev/null 2>&1 || [[ -x "$exec_cmd" ]]; }; then
        has_runtime=1
        break
      fi
    done
  fi
  if have_cmd gnome-shell || have_cmd kwin_wayland || have_cmd startplasma-wayland || have_cmd weston || have_cmd sway || have_cmd hyprland || have_cmd wayfire || have_cmd labwc || have_cmd river || have_cmd niri || have_cmd cage || have_cmd hikari || have_cmd qtile; then
    has_runtime=1
    has_sessions=1
  fi

  if (( has_sessions && has_runtime )); then
    echo "WORKS"
  elif (( ! has_sessions && ! has_runtime )); then
    echo "NOT_PRESENT"
  else
    echo "NOT_WORK"
  fi
}
x11_wayland_support_status() {
  # Overall graphics protocol support gate for this helper.
  # WORKS: at least one of X11(Xorg) or Wayland stacks is WORKS.
  # NOT_PRESENT: both stacks are NOT_PRESENT.
  # NOT_WORK: partial/broken state where neither stack is WORKS.
  local xorg_status="$1"
  local wayland_status="$2"
  if [[ "$xorg_status" == "WORKS" || "$wayland_status" == "WORKS" ]]; then
    echo "WORKS"
  elif [[ "$xorg_status" == "NOT_PRESENT" && "$wayland_status" == "NOT_PRESENT" ]]; then
    echo "NOT_PRESENT"
  else
    echo "NOT_WORK"
  fi
}
x11_wayland_supported_mode() {
  # Return BOTH | X11 | WAYLAND | NONE | PARTIAL
  local xorg_status="$1"
  local wayland_status="$2"
  if [[ "$xorg_status" == "WORKS" && "$wayland_status" == "WORKS" ]]; then
    echo "BOTH"
  elif [[ "$xorg_status" == "WORKS" ]]; then
    echo "X11"
  elif [[ "$wayland_status" == "WORKS" ]]; then
    echo "WAYLAND"
  elif [[ "$xorg_status" == "NOT_PRESENT" && "$wayland_status" == "NOT_PRESENT" ]]; then
    echo "NONE"
  else
    echo "PARTIAL"
  fi
}

openbox_stack_status() {
  # WORKS if Openbox binary and an X session entry are present.
  # NOT_PRESENT if neither is present.
  # NOT_WORK for partial/incomplete state.
  local has_openbox=0 has_session=0
  if have_cmd openbox || [[ -x /usr/bin/openbox || -x /usr/local/bin/openbox ]]; then
    has_openbox=1
  fi
  if compgen -G "/usr/share/xsessions/openbox*.desktop" >/dev/null 2>&1 || compgen -G "/usr/share/xsessions/*openbox*.desktop" >/dev/null 2>&1; then
    has_session=1
  fi

  if (( has_openbox && has_session )); then
    echo "WORKS"
  elif (( ! has_openbox && ! has_session )); then
    echo "NOT_PRESENT"
  else
    echo "NOT_WORK"
  fi
}
openbox_connected_outputs_from_xrandr_query() {
  # Read xrandr --query output from stdin and print output names that are
  # currently connected.
  awk '$2 == "connected" { print $1 }'
}
openbox_activate_all_connected_monitors() {
  # Enable all currently connected outputs via xrandr.
  # Accept an optional xrandr binary path for regression testing.
  local xrandr_bin="${1:-xrandr}"
  command -v "$xrandr_bin" >/dev/null 2>&1 || return 0
  [[ -n "${DISPLAY:-}" ]] || return 0

  local query
  query="$("$xrandr_bin" --query 2>/dev/null || true)"
  [[ -n "$query" ]] || return 0

  local -a outputs=()
  mapfile -t outputs < <(printf '%s\n' "$query" | openbox_connected_outputs_from_xrandr_query)
  (( ${#outputs[@]} > 0 )) || return 0

  local output
  for output in "${outputs[@]}"; do
    "$xrandr_bin" --output "$output" --auto >/dev/null 2>&1 || true
  done
}
