    '--debug-cmdline-tokens[Trace BLS root/rootflags token source selection (read-only)]' \\
    '--entry=[Filter BLS entry basenames (glob) for --debug-cmdline-tokens]:pattern:(system-*.conf snapper-*.conf *.conf)' \\
    '--verify-bls-sync[Verify BLS entry options are synchronized with /etc/kernel/cmdline]' \\
    '--verify-bls-nosnapper[Regression check: assert snapper BLS entries are never write targets]' \\
    '--create-fallback-entry[Create/update a non-VFIO fallback BLS entry from the current system entry]' \\
    '--print-effective-config[Print effective Boot-VGA policy decision path]' \\
    '--json[Machine-readable output with --detect or --debug-cmdline-tokens]' \\
    '--self-test[Run self-tests and exit]' \\
    '--health-check[Audit current kernel/logs for VFIO friendliness]' \\
    '--health-check-previous[Audit previous boot for VFIO friendliness]' \\
    '--health-check-all[Audit all detected GPUs]' \\
    '--usb-health-check[Audit USB/xHCI instability markers]' \\
    '--reset[Remove VFIO setup installed by this script]' \\
    '--reset-usb-mitigation[Remove only USB mitigation artifacts]' \\
    '--disable-bootlog[Disable/remove optional VFIO boot-log dumper]' \\
    '--boot-remove[Alias of --disable-bootlog]' \\
    '--remove-bootlog[Alias of --disable-bootlog]' \
    '--install-bootlog[Install/reinstall only optional VFIO boot-log dumper]' \\
    '--install-graphics-daemon[Install/reinstall only VFIO graphics protocol daemon]' \\
    '--install-usb-bt-mitigation[Install only optional USB Bluetooth mitigation]' \
    '--usb-mitigation-status[Show USB mitigation run counts and instability markers]' \\
    '--print-fish-completion[Print fish completion script]' \\
    '--print-bash-completion[Print bash completion script]' \\
    '--print-zsh-completion[Print zsh completion script]'
}
compdef _vfio_sh_complete $cmd
EOF
}

maybe_offer_detect_accountsservice_install() {
  # Detect mode is read-only by default, but when the user explicitly confirms
  # this action we perform the install as a one-off fix because the goal of
  # this mode is troubleshooting and remediation guidance.
  [[ "${MODE:-}" == "detect" ]] || return 0
  lightdm_is_present || return 0
  accountsservice_is_present && return 0

  say
  hdr "Detect action (optional)"
  note "LightDM is installed but org.freedesktop.Accounts is missing."
  note "This is a known cause of LightDM restart-loop failures at boot."
  if ! prompt_yn "Install accountsservice now from detect mode?" N "LightDM dependency"; then
    return 0
  fi
  if ! confirm_phrase "This will install packages on your system now." "INSTALL ACCOUNTSERVICE"; then
    note "Skipping accountsservice install (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0
  if install_accountsservice_pkg; then
    enable_accountsservice_unit || true
    if accountsservice_is_present; then
      say "Installed AccountsService from detect mode."
    else
      note "Install command ran, but AccountsService is still not detected; verify package/service state manually."
    fi
  else
    note "Automatic accountsservice install from detect mode failed."
    note "You can install manually, then re-run --detect."
  fi
  DRY_RUN="$prev_dry"
}

list_stale_vfio_user_audio_units() {
  # Emit TSV: user<TAB>unit_path for user units that reference the
  # optional vfio-set-host-audio service while the helper script is missing.
  [[ -x "$AUDIO_SCRIPT" ]] && return 0

  local d user unit
  for d in /home/*; do
    [[ -d "$d" ]] || continue
    user="$(basename "$d")"
    unit="$d/.config/systemd/user/vfio-set-host-audio.service"
    [[ -f "$unit" ]] || continue
    printf '%s\t%s\n' "$user" "$unit"
  done
}

maybe_offer_detect_stale_user_audio_unit_cleanup() {
  [[ "${MODE:-}" == "detect" ]] || return 0

  local stale
  stale="$(list_stale_vfio_user_audio_units || true)"
  [[ -n "$stale" ]] || return 0

  say
  hdr "Detect action (optional): stale user audio unit cleanup"
  note "Found vfio-set-host-audio user unit(s) but $AUDIO_SCRIPT is missing."
  note "This can spam user-session failures and be mistaken for display-manager issues."
  printf '%s\n' "$stale" | awk -F'\t' '{print "  - user=" $1 " unit=" $2}'

  if ! prompt_yn "Remove stale vfio-set-host-audio user unit(s) now from detect mode?" Y "User audio unit cleanup"; then
    return 0
  fi
  if ! confirm_phrase "This will remove stale user service files now." "REMOVE STALE AUDIO UNIT"; then
    note "Skipping stale unit cleanup (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0

  local user unit uid
  while IFS=$'\t' read -r user unit; do
    [[ -n "$unit" ]] || continue
    [[ -f "$unit" ]] || continue
    if have_cmd runuser; then
      uid="$(id -u "$user" 2>/dev/null || true)"
      if [[ -n "$uid" ]]; then
        runuser -u "$user" -- env XDG_RUNTIME_DIR="/run/user/$uid" systemctl --user disable --now vfio-set-host-audio.service >/dev/null 2>&1 || true
      fi
    fi
    run rm -f "$unit"
    say "Removed stale unit for user '$user': $unit"
  done <<<"$stale"

  DRY_RUN="$prev_dry"
}

list_user_audio_units_missing_condition_guard() {
  # Emit TSV: user<TAB>unit_path for vfio audio user units missing
  # ConditionPathExists guard.
  local d user unit guard
  guard="ConditionPathExists=$AUDIO_SCRIPT"
  for d in /home/*; do
    [[ -d "$d" ]] || continue
    user="$(basename "$d")"
    unit="$d/.config/systemd/user/vfio-set-host-audio.service"
    [[ -f "$unit" ]] || continue
    grep -Fq "$guard" "$unit" 2>/dev/null && continue
    printf '%s\t%s\n' "$user" "$unit"
  done
}

repair_user_audio_unit_condition_guard() {
  local user="$1" unit="$2"
  [[ -n "$unit" && -f "$unit" ]] || return 1

  local guard tmp mode owner group uid
  guard="ConditionPathExists=$AUDIO_SCRIPT"
  tmp="$(mktemp)"

  awk -v guard="$guard" '
    BEGIN { inserted=0; had_guard=0 }
    {
      if ($0 == guard) {
        had_guard=1
      }
      print
      if ($0 ~ /^After=pipewire\.service wireplumber\.service$/ && !inserted && !had_guard) {
        print guard
        inserted=1
      }
    }
    END {
      if (!inserted && !had_guard) {
        print guard
      }
    }
  ' "$unit" >"$tmp"

  mode="$(stat -c '%a' "$unit" 2>/dev/null || echo 644)"
  owner="$(stat -c '%u' "$unit" 2>/dev/null || id -u)"
  group="$(stat -c '%g' "$unit" 2>/dev/null || id -g)"
  run install -o "$owner" -g "$group" -m "$mode" "$tmp" "$unit"
  run rm -f "$tmp"

  if have_cmd runuser; then
    uid="$(id -u "$user" 2>/dev/null || true)"
    if [[ -n "$uid" ]]; then
      runuser -u "$user" -- env XDG_RUNTIME_DIR="/run/user/$uid" systemctl --user daemon-reload >/dev/null 2>&1 || true
      runuser -u "$user" -- env XDG_RUNTIME_DIR="/run/user/$uid" systemctl --user reset-failed vfio-set-host-audio.service >/dev/null 2>&1 || true
    fi
  fi
  return 0
}

maybe_offer_detect_user_audio_unit_guard_repair() {
  [[ "${MODE:-}" == "detect" ]] || return 0

  local missing_guard
  missing_guard="$(list_user_audio_units_missing_condition_guard || true)"
  [[ -n "$missing_guard" ]] || return 0

  say
  hdr "Detect action (optional): repair legacy user audio unit guard"
  note "Found vfio-set-host-audio user unit(s) missing ConditionPathExists guard."
  note "This can fail user session startup after restore/rollback when helper script is absent."
  printf '%s\n' "$missing_guard" | awk -F'\t' '{print "  - user=" $1 " unit=" $2}'

  if ! prompt_yn "Repair these user unit(s) now (add ConditionPathExists guard)?" Y "User audio unit repair"; then
    return 0
  fi
  if ! confirm_phrase "This will edit user service files now." "REPAIR AUDIO UNIT"; then
    note "Skipping unit repair (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0

  local user unit
  while IFS=$'\t' read -r user unit; do
    [[ -n "$unit" ]] || continue
    [[ -f "$unit" ]] || continue
    repair_user_audio_unit_condition_guard "$user" "$unit" || true
    say "Repaired user unit for '$user': $unit"
  done <<<"$missing_guard"

  DRY_RUN="$prev_dry"
}

auto_repair_legacy_user_audio_unit_guards() {
  # Non-interactive self-heal for normal install flow:
  # ensure legacy user audio units have ConditionPathExists guard.
  [[ "${MODE:-install}" == "install" ]] || return 0

  local missing_guard
  missing_guard="$(list_user_audio_units_missing_condition_guard || true)"
  [[ -n "$missing_guard" ]] || return 0

  say
  hdr "Install self-heal: legacy user audio unit guard"
  note "Found legacy vfio-set-host-audio user unit(s) missing ConditionPathExists guard."
  note "Applying automatic repair to reduce user-session failures after restore/rollback."

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0

  local user unit
  while IFS=$'\t' read -r user unit; do
    [[ -n "$unit" ]] || continue
    [[ -f "$unit" ]] || continue
    repair_user_audio_unit_condition_guard "$user" "$unit" || true
    say "Auto-repaired user unit for '$user': $unit"
  done <<<"$missing_guard"

  DRY_RUN="$prev_dry"
}
host_has_amd_gpu() {
  have_cmd lspci || return 1
  lspci -n 2>/dev/null | grep -q '1002:'
}
recent_kernel_logs() {
  # Print current + previous boot kernel logs when available.
  if have_cmd journalctl; then
    journalctl -k -b --no-pager 2>/dev/null || true
    journalctl -k -b -1 --no-pager 2>/dev/null || true
    return 0
  fi
  if have_cmd dmesg; then
    dmesg 2>/dev/null || true
    return 0
  fi
  return 1
}

amd_reset_issue_signatures_present() {
  # Return 0 only when kernel logs show signatures consistent with
  # VFIO/AMD reset failures. This avoids static GPU-family hardcoding.
  local logs
  logs="$(recent_kernel_logs || true)"
  [[ -n "$logs" ]] || return 1

  printf '%s\n' "$logs" \
    | grep -Ei '(vfio-pci|amdgpu).*(reset|flr|d3)' \
    | grep -Ei '(fail|failed|timeout|timed out|not ready|stuck|unable|can.t|error)' \
    >/dev/null 2>&1
}

amd_reset_issue_signatures_present_for_bdf() {
  # BDF-specific variant to scope reset-failure checks to the selected guest GPU.
  local bdf="${1:-}"
  [[ -n "$bdf" ]] || return 1
  local logs slot
  logs="$(recent_kernel_logs || true)"
  [[ -n "$logs" ]] || return 1
  slot="${bdf%.*}"

  printf '%s\n' "$logs" \
    | grep -Ei '(vfio-pci|amdgpu).*(reset|flr|d3)' \
    | grep -Ei '(fail|failed|timeout|timed out|not ready|stuck|unable|can.t|error)' \
    | grep -Ei "($bdf|$slot)" \
    >/dev/null 2>&1
}

vendor_reset_is_present() {
  [[ -d /sys/module/vendor_reset ]] && return 0
  have_cmd modinfo && modinfo vendor_reset >/dev/null 2>&1 && return 0
  return 1
}

install_vendor_reset_pkg() {
  # Best-effort install for common distro package names.
  local use_sudo=0
  if [[ "${EUID:-$(id -u)}" -ne 0 ]] && have_cmd sudo; then
    use_sudo=1
  fi

  if have_cmd apt-get; then
    local -a candidates=(vendor-reset-dkms vendor-reset)
    if have_cmd apt-cache; then
      local p
      while IFS= read -r p; do
        [[ -n "$p" ]] || continue
        candidates+=("$p")
      done < <(apt-cache search -n '^vendor[-]reset' 2>/dev/null | awk '{print $1}')
    fi

    local tried=""
    local pkg
    for pkg in "${candidates[@]}"; do
      [[ -n "$pkg" ]] || continue
      if grep -Eq "(^|[[:space:]])${pkg}([[:space:]]|$)" <<<"$tried"; then
        continue
      fi
      tried="${tried:+$tried }$pkg"
      if (( use_sudo )); then
        if run sudo apt-get -y install "$pkg"; then
          return 0
        fi
      else
        if run apt-get -y install "$pkg"; then
          return 0
        fi
      fi
    done
    return 1
  fi
  if have_cmd dnf; then
    if (( use_sudo )); then
      run sudo dnf -y install kmod-vendor-reset || run sudo dnf -y install vendor-reset
    else
      run dnf -y install kmod-vendor-reset || run dnf -y install vendor-reset
    fi
    return $?
  fi
  if have_cmd zypper; then
    if (( use_sudo )); then
      run sudo zypper --non-interactive in vendor-reset || run sudo zypper --non-interactive in vendor-reset-kmp-default
    else
      run zypper --non-interactive in vendor-reset || run zypper --non-interactive in vendor-reset-kmp-default
    fi
    return $?
  fi
  if have_cmd pacman; then
    if (( use_sudo )); then
      run sudo pacman --noconfirm -S vendor-reset-dkms || run sudo pacman --noconfirm -S vendor-reset
    else
      run pacman --noconfirm -S vendor-reset-dkms || run pacman --noconfirm -S vendor-reset
    fi
    return $?
  fi
  return 1
}

cleanup_tmp_dir_best_effort() {
  local tmp_dir="${1:-}"
  if [[ -n "$tmp_dir" && -d "$tmp_dir" ]]; then
    run rm -rf "$tmp_dir" || true
  fi
  return 0
}
install_vendor_reset_dkms_from_source() {
  # Optional fallback for apt-based systems where vendor-reset packages are
  # unavailable in enabled repositories.
  have_cmd apt-get || return 1
  have_cmd git || return 1
  have_cmd dkms || return 1

  local use_sudo=0
  if [[ "${EUID:-$(id -u)}" -ne 0 ]] && have_cmd sudo; then
    use_sudo=1
  fi

  local krel headers_pkg
  krel="$(uname -r)"
  headers_pkg="linux-headers-$krel"
  if (( use_sudo )); then
    run sudo apt-get -y install "$headers_pkg" || true
  else
    run apt-get -y install "$headers_pkg" || true
  fi

  local tmp src
  tmp="$(mktemp -d /tmp/vendor-reset-dkms.XXXXXX)"
  src="$tmp/vendor-reset"

  if ! run git clone --depth 1 https://github.com/gnif/vendor-reset "$src"; then
    cleanup_tmp_dir_best_effort "$tmp"
    return 1
  fi
  if [[ ! -f "$src/dkms.conf" ]]; then
    cleanup_tmp_dir_best_effort "$tmp"
    return 1
  fi

  local pkg_name pkg_ver
  pkg_name="$(awk -F= '/^PACKAGE_NAME=/{gsub(/[[:space:]"]/, "", $2); print $2; exit}' "$src/dkms.conf")"
  pkg_ver="$(awk -F= '/^PACKAGE_VERSION=/{gsub(/[[:space:]"]/, "", $2); print $2; exit}' "$src/dkms.conf")"
  if [[ -z "$pkg_name" || -z "$pkg_ver" ]]; then
    cleanup_tmp_dir_best_effort "$tmp"
    return 1
  fi

  if (( use_sudo )); then
    run sudo dkms remove "$pkg_name/$pkg_ver" --all 2>/dev/null || true
    run sudo dkms add "$src"
    run sudo dkms install "$pkg_name/$pkg_ver"
  else
    run dkms remove "$pkg_name/$pkg_ver" --all 2>/dev/null || true
    run dkms add "$src"
    run dkms install "$pkg_name/$pkg_ver"
  fi

  cleanup_tmp_dir_best_effort "$tmp"
}

maybe_offer_detect_vendor_reset_install() {
  [[ "${MODE:-}" == "detect" ]] || return 0
  host_has_amd_gpu || return 0
  amd_reset_issue_signatures_present || return 0
  vendor_reset_is_present && return 0

  say
  hdr "Detect action (optional): vendor-reset"
  note "AMD reset-failure markers were detected in kernel logs and vendor-reset is missing."
  note "Installing vendor-reset can help when VFIO GPU reset fails after VM shutdown/restart."
  if ! prompt_yn "Install vendor-reset now from detect mode?" N "AMD reset mitigation"; then
    return 0
  fi
  if ! confirm_phrase "This will install packages on your system now." "INSTALL VENDOR RESET"; then
    note "Skipping vendor-reset install (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0
  if install_vendor_reset_pkg; then
    if have_cmd modprobe; then
      if [[ "${EUID:-$(id -u)}" -ne 0 ]] && have_cmd sudo; then
        run sudo modprobe vendor_reset 2>/dev/null || true
      else
        run modprobe vendor_reset 2>/dev/null || true
      fi
    fi
    if vendor_reset_is_present; then
      say "Installed vendor-reset from detect mode."
    else
      note "Install command ran, but vendor-reset is still not detected for this kernel."
      note "A reboot or matching kernel headers/dkms build may be required."
    fi
  else
    note "Automatic vendor-reset install from detect mode failed."
    if have_cmd apt-get; then
      note "Package not found in enabled apt repositories. Optional fallback: build DKMS module from upstream source."
      if prompt_yn "Try source-based DKMS install for vendor-reset now? (advanced)" N "AMD reset mitigation"; then
        if confirm_phrase "This will clone/build a kernel module from source now." "BUILD VENDOR RESET"; then
          if install_vendor_reset_dkms_from_source; then
            if have_cmd modprobe; then
              if [[ "${EUID:-$(id -u)}" -ne 0 ]] && have_cmd sudo; then
                run sudo modprobe vendor_reset 2>/dev/null || true
              else
                run modprobe vendor_reset 2>/dev/null || true
              fi
            fi
            if vendor_reset_is_present; then
              say "Installed vendor-reset from source (DKMS) in detect mode."
            else
              note "Source DKMS install completed, but module is not yet detected for this kernel."
              note "Reboot, then re-run --detect."
            fi
          else
            note "Source-based DKMS install failed."
            note "Install it manually, then re-run --detect."
          fi
        else
          note "Skipping source-based install (confirmation phrase not provided)."
        fi
      else
        note "Skipping source-based install."
      fi
    else
      note "Install it manually, then re-run --detect."
    fi
  fi
  DRY_RUN="$prev_dry"
}
lightdm_accountsservice_preflight() {
  # Guardrail based on observed failure mode:
  # LightDM exits with status=1 and start-limit-hit when org.freedesktop.Accounts is missing.
  if ! lightdm_is_present; then
    return 0
  fi
  if accountsservice_is_present; then
    return 0
  fi

  say
  hdr "LightDM dependency preflight"
  note "Detected LightDM, but AccountsService appears missing (org.freedesktop.Accounts)."
  note "This can cause a LightDM restart loop at boot (status=1 / start-limit-hit) even when VFIO binding is successful."
  note "Recommended: install accountsservice now."

  if prompt_yn "Install accountsservice now? (recommended)" Y "LightDM dependency"; then
    if install_accountsservice_pkg; then
      enable_accountsservice_unit || true
      if accountsservice_is_present; then
        say "Installed AccountsService for LightDM."
        return 0
      fi
      note "AccountsService install command returned success but service detection is still inconclusive."
    else
      note "Automatic accountsservice install failed (or package manager unavailable)."
    fi
  fi

  note "Applying LightDM fallback configuration to reduce reliance on AccountsService."
  if prompt_yn "Install LightDM fallback config (greeter-hide-users=true)?" Y "LightDM fallback"; then
    install_lightdm_accountsservice_fallback
    note "Fallback installed at $LIGHTDM_FALLBACK_CONF"
    note "If LightDM still fails, install AccountsService manually and reboot."
  fi
}

display_manager_dependency_preflight() {
  # Display-manager guardrail:
  # - LightDM gets explicit AccountsService + fallback checks.
  # - SDDM/GDM/LXDM/XDM are treated as supported without LightDM-specific fallback.
  local dm
  dm="$(detect_display_manager 2>/dev/null || true)"
  [[ -n "$dm" ]] || dm="none"

  case "$dm" in
    lightdm)
      lightdm_accountsservice_preflight
      ;;
    sddm|gdm|lxdm|xdm|plasmalogin)
      say
      hdr "Display manager dependency preflight"
      note "Detected ${dm}; no LightDM-specific AccountsService fallback is required."
      ;;
    none)
      note "No display manager detected; skipping display-manager dependency preflight."
      ;;
    *)
      note "Detected display manager '${dm}'; no specific dependency preflight is implemented for it."
      ;;
  esac
}
graphics_protocol_preflight() {
  # This helper officially supports only X11(Xorg) and Wayland desktop stacks.
  # At least one stack must be fully WORKS for install mode.
  local xorg_status wayland_status support mode
  xorg_status="$(xorg_stack_status)"
  wayland_status="$(wayland_stack_status)"
  support="$(x11_wayland_support_status "$xorg_status" "$wayland_status")"
  mode="$(x11_wayland_supported_mode "$xorg_status" "$wayland_status")"

  say
  hdr "Graphics protocol preflight (X11/Wayland)"
  note "X11 (Xorg): $(format_tri_state_status "$xorg_status")"
  note "Wayland: $(format_tri_state_status "$wayland_status")"
  note "Supported protocol mode: $mode"

  if [[ "$support" != "WORKS" ]]; then
    die "Unsupported desktop stack state. This helper supports only X11 (Xorg) and Wayland, and requires at least one of them to be WORKS."
  fi
}

prompt_yn() {
  # prompt_yn "Question" default(Y/N) [title]
  local q="$1"; local def="${2:-Y}"; local title="${3:-Confirmation}"; local ans

  # TUI path: use whiptail if available.
  if (( HAS_TUI )); then
    local exit_status
    if [[ "$def" =~ ^[Nn]$ ]]; then
      whiptail --title "$title" --defaultno --yesno "$q" 10 60
      exit_status=$?
    else
      whiptail --title "$title" --yesno "$q" 10 60
      exit_status=$?
    fi
    # whiptail exit status: 0 = Yes, 1/255 = No/ESC
    return $exit_status
  fi

  # Fallback: original plain-text logic on /dev/tty.
  # IMPORTANT: don't rely on stdin/stdout being connected to a TTY (sudo/fish/GUI terminals).
  # Also avoid printing prompts to stdout (some callers may capture stdout).
  local in="/dev/stdin"
  local out="/dev/stderr"
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi

  while true; do
    if [[ "$def" =~ ^[Yy]$ ]]; then
      printf '%s [Y/n] ' "$q" >"$out"
    else
      printf '%s [y/N] ' "$q" >"$out"
    fi
    if ! read -r ans <"$in" 2>/dev/null; then
      # /dev/tty open/read failed (setsid, sudo without an allocated tty, CI):
      # fall back to stdin/stderr so piped or redirected input still works.
      if [[ "$in" == "/dev/tty" ]]; then
        in="/dev/stdin"
        out="/dev/stderr"
        read -r ans <"$in" || return 1
      else
        return 1
      fi
    fi
    ans="${ans:-$def}"
    case "$ans" in
      y|Y) return 0;;
      n|N) return 1;;
      *) printf '%s\n' "Please answer y or n." >"$out";;
    esac
  done
}

usage() {
  cat <<EOF
Usage: $SCRIPT_NAME [--debug] [--dry-run] [--no-tui] [--boot-vga-policy auto|strict] [--graphics-protocol auto|x11|wayland] [--graphics-daemon-interval seconds] [--no-graphics-daemon] [--binding-mode early|dynamic] [--stealth-vm-tuning] [--no-stealth-vm-tuning] [--vbios] [--no-vbios] [--verify] [--detect] [--sync-bls-only] [--debug-cmdline-tokens] [--entry pattern] [--verify-bls-sync] [--verify-bls-nosnapper] [--create-fallback-entry] [--print-effective-config] [--json] [--self-test] [--health-check] [--health-check-previous] [--health-check-all] [--usb-health-check] [--reset] [--reset-usb-mitigation] [--disable-bootlog] [--boot-remove] [--remove-bootlog] [--install-bootlog] [--install-graphics-daemon] [--install-dynamic-binding] [--install-early-binding] [--install-live-attach] [--install-virtio-win-guest-agent] [--menu] [--install-self] [--uninstall-self] [--install-stealth-vm-tuning] [--install-ultimate-perf-vm-tuning] [--reset-ultimate-perf-vm-tuning] [--ultimate-perf-hugepages] [--no-ultimate-perf-hugepages] [--ultimate-perf-virtio-disk] [--no-ultimate-perf-virtio-disk] [--ultimate-perf-vm-tuning] [--no-ultimate-perf-vm-tuning] [--install-usb-bt-mitigation] [--usb-mitigation-status] [--print-fish-completion] [--print-bash-completion] [--print-zsh-completion]

  With NO arguments: launches the interactive menu (same as --menu) — pick an
  action (full configure, switch binding, live-attach, verify, reset, …).
  The full guided wizard is menu option 1 (Full configure), or run any
  --install-* flag below to do one thing directly.

  --debug           Enable verbose debug logging (and bash xtrace).
  --dry-run         Show actions but do not write files / run system-changing commands.
  --no-tui          Force plain-text prompts even if whiptail is installed.
  --boot-vga-policy Install-mode override for generated Boot-VGA policy:
                   auto (default behavior, dynamic host-assisted detection) or
                   strict (requires explicit VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1).
  --graphics-protocol
                   Install-mode graphics protocol override:
                   auto (default, protocol-agnostic), x11, or wayland.
  --graphics-daemon-interval
                   Set the independent graphics daemon polling interval in seconds
                   (valid range: 1-3600, default: $GRAPHICS_DAEMON_INTERVAL_DEFAULT).
  --no-graphics-daemon
                   Skip installation of the independent graphics protocol daemon service.
  --amd-runpm       Install-mode override: force-add amdgpu.runpm=0 for AMD guest GPUs (skip prompt).
  --no-amd-runpm    Install-mode override: skip amdgpu.runpm=0 for AMD guest GPUs (skip prompt).
  --amd-noretry     Install-mode override: force-add amdgpu.noretry=0 for AMD guest GPUs (skip prompt).
  --no-amd-noretry  Install-mode override: skip amdgpu.noretry=0 for AMD guest GPUs (skip prompt).
  --amd-disable-idle-d3
                   Install-mode override: force-add vfio-pci.disable_idle_d3=1 for AMD guest GPUs (skip prompt).
  --no-amd-disable-idle-d3
                   Install-mode override: skip vfio-pci.disable_idle_d3=1 for AMD guest GPUs (skip prompt).
  --amd-pcie-port-pm-off
                   Install-mode override: force-add pcie_port_pm=off for AMD guest GPUs (skip prompt).
  --no-amd-pcie-port-pm-off
                   Install-mode override: skip pcie_port_pm=off for AMD guest GPUs (skip prompt).
  --binding-mode early|dynamic
                   Install-mode override for GPU binding strategy:
                   early (default) forces the guest GPU onto vfio-pci at boot via vfio-pci.ids /
                   rd.driver.pre=vfio-pci / the bind systemd unit. dynamic lets amdgpu load first
                   and a libvirt qemu hook switches the GPU to vfio-pci only when a VM that has the
                   GPU attached is started (more reliable for RX 9070 / RDNA4 reset-bug cards).
  --verify          Do not change anything; validate an existing setup (reads $CONF_FILE).
  --detect          Print a detailed report of existing VFIO/passthrough configuration and exit.
  --sync-bls-only   Non-interactive mode: sync BLS entry options from /etc/kernel/cmdline, then run strict drift verification.
                   Intended for openSUSE BLS/systemd-boot workflows and snapshot recovery.
  --debug-cmdline-tokens
                   Non-interactive read-only mode: trace baseline and per-entry root/rootflags source selection
                   used by sync_bls_entries_from_kernel_cmdline().
  --entry          Optional non-empty basename glob filter for --debug-cmdline-tokens (for example: system-*.conf).
  --verify-bls-sync Non-interactive regression check: verify BLS entry options against /etc/kernel/cmdline.
                   Prints final PASS/FAIL summary and exits non-zero on drift.
  --verify-bls-nosnapper
                   Non-interactive regression check: assert sync logic does not attempt writes to snapper-* BLS entries.
                   Prints final PASS/FAIL summary and exits non-zero on any snapper write attempt.
  --create-fallback-entry
                   Non-interactive mode: create or update a dedicated non-VFIO fallback Boot Loader Spec entry
                   from the current system entry by removing VFIO-forcing kernel parameters.
  --print-effective-config
                   Read-only report of effective Boot-VGA policy and runtime decision path
                   using $CONF_FILE plus current sysfs topology.
  --json            With --detect, print machine-readable JSON only (tri-state values: WORKS / NOT_WORK / NOT_PRESENT).
                   With --debug-cmdline-tokens, emit machine-readable JSON debug lines.
  --self-test       Run automated checks for common issues (awk compatibility, PipeWire access) and exit.
  --health-check    Audit the running kernel and logs for VFIO-friendliness (no changes made) and exit.
  --health-check-previous
                     Audit the PREVIOUS boot's kernel logs for VFIO-friendliness (no changes made) and exit.
  --usb-health-check
                   Audit current and previous boot kernel logs for USB/xHCI crash signatures and print optional stability mitigation guidance.
                   Tip: run with full kernel-log access: sudo ./$SCRIPT_NAME --usb-health-check
  --reset           Reset/remove VFIO passthrough settings installed by this script (systemd/modprobe/grub/initramfs/user units).
  --reset-usb-mitigation
                   Reset/remove only USB mitigation artifacts (helper/unit/udev/match policy),
                   including USB Ethernet EEE-off mitigation config, while keeping core VFIO GPU setup.
  --disable-bootlog Disable only the optional VFIO boot log dumper service/unit, keeping the rest of the VFIO setup intact.
  --boot-remove     Alias of --disable-bootlog.
  --remove-bootlog  Alias of --disable-bootlog.
  --install-bootlog Install/reinstall only the optional VFIO boot log dumper helper + systemd unit.
                   Useful after snapshot rollbacks where /etc systemd state differs from user-home helper state.
  --install-graphics-daemon
                   Install/reinstall only the VFIO graphics protocol daemon + systemd unit.
                   Useful for rolling out daemon/watchdog logic updates without re-running the full wizard.
  --install-dynamic-binding
                   Switch an existing early-binding setup to dynamic binding without re-running the
                   full wizard. Sets VFIO_BINDING_MODE=dynamic, installs the libvirt qemu hook, and
                   strips vfio-pci.ids / rd.driver.pre=vfio-pci from the kernel cmdline (BLS sync).
                   Recommended for RX 9070 / RDNA4 cards that hit the "Unknown PCI header type 127"
                   reset bug. Requires libvirt-managed VMs and an existing $CONF_FILE.
  --install-early-binding
                   Switch a dynamic-binding setup back to early binding. Sets VFIO_BINDING_MODE=early,
                   removes the libvirt qemu hook (restoring any pre-existing hook), and re-adds
                   vfio-pci.ids / rd.driver.pre=vfio-pci to the kernel cmdline (BLS sync).
  --stealth-vm-tuning
                   Dynamic-install override: apply stealth/perf VM XML tuning (SMBIOS spoofing,
                   hypervisor CPUID disable, e1000e NIC, randomized disk serials, memballoon=none,
                   iothreads/cputune) to detected guest-GPU VMs without prompting.
                   DISCLAIMER: cosmetic/perf realism ONLY, NOT an anti-cheat/anti-tamper bypass.
  --no-stealth-vm-tuning
                   Dynamic-install override: skip stealth/perf VM XML tuning.
  --vbios           Dynamic-install override: inject a matching vBIOS ROM dump
                   into guest-GPU VMs (skip prompt).
  --no-vbios        Dynamic-install override: skip vBIOS injection AND remove any
                   script-installed vBIOS pin so VMs use the live ROM read (or
                   your manual XML config). Use this if you already have a vBIOS
                   configured in your VM XML manually.
  --install-live-attach
                  Set up the live-attach (hotplug GPU) workflow: the VM starts WITHOUT the
                  GPU, Windows boots on a virtual display, and after a configurable delay the
                  GPU is bound to vfio-pci and hot-attached to the running VM via
                  'virsh attach-device' (live mode). This sidesteps the parked-restart card death
                  on RX 9070 / RDNA4. Requires --install-dynamic-binding to be run first,
                  and the AMD Windows driver MUST be installed in the guest VM.
                  To revert: sudo vfio.sh --install-dynamic-binding (restores the GPU to the VM XML from the per-VM backup)
  --install-virtio-win-guest-agent
                  Attach the virtio-win driver ISO to each guest-GPU VM as a CD-ROM (idempotent) so
                  you can run virtio-win-guest-tools.exe inside Windows to install the QEMU guest
                  agent + virtio drivers. With the agent installed, the live-attach helper hot-
                  attaches the GPU the MOMENT Windows is up (guest-ping) instead of after the blind
                  fixed delay. Resolves the ISO via the distro virtio-win package (dnf/zypper) or
                  downloads the stable ISO from fedorapeople.org. Requires --install-live-attach to
                  be run first. The fixed-delay FALLBACK still works until the agent is installed.
  --menu
                  Interactive menu — pick what to do without running the whole wizard or
                  remembering individual flags. This is also the default when you run vfio
                  with NO arguments. Options: full configure, switch dynamic/early binding,
                  set up live-attach/hotswap, attach virtio-win guest-agent ISO, apply/revert
                  stealth/perf VM tuning, verify, detect/health-check, reset, install/uninstall
                  vfio, exit. Loops back after each action so you can do multiple things in one
                  session. Requires root (most actions write to /etc).
  --install-self
                  Install this script to /usr/local/bin/vfio (so it is on PATH as the vfio command) AND drop the
                  fish/bash/zsh completions into their vendor auto-load directories (so they load
                  with no 'source' step). Idempotent: re-run anytime to update the installed copy
                  + completions to the latest version. The repo copy is never touched. Requires
                  root. Separate from --reset (VFIO config) and --uninstall-self.
  --uninstall-self
                  Remove the self-installed /usr/local/bin/vfio + the 3 completion files
                  (our names only). Idempotent. Does NOT remove the VFIO config (use --reset for
                  that) or your repo copy. Requires root.
  --install-stealth-vm-tuning
                   Re-apply/refresh stealth/perf VM XML tuning on detected guest-GPU VMs without
                   re-running the full wizard. Requires an existing $CONF_FILE and libvirt.
                   Verifies the tuned XML (virt-xml-validate) and prompts before redefining each VM.
                   DISCLAIMER: cosmetic/perf realism ONLY, NOT an anti-cheat/anti-tamper bypass.
  --reset-stealth-vm-tuning
                   Revert stealth/perf VM XML tuning by redefining each shut-off guest-GPU VM
                   from its most recent *_stealth_*.xml backup. Verifies the backup XML and
                   prompts before redefining. Requires an existing $CONF_FILE and libvirt.
  --install-ultimate-perf-vm-tuning
                   Apply ultimate-performance VM XML tuning to each shut-off guest-GPU VM
                   WITHOUT touching stealth (vendor_id/kvm hidden/vmport/SMBIOS/e1000e
                   NIC/disk serials/memballoon/hypervclock/TSC/QEMU -cpu/-smbios stay intact).
                   Knobs: disk cache=none + io=native + discard=unmap + virtio-blk multiqueue;
                   iothreads scaled to min(vcpu,4) with round-robin disk assignment; aggressive
                   cputune pinning (vCPUs to physical cores, emulator to a housekeeping core,
                   iothreadpin) + numatune (ONLY when NUMA-safe, else skipped so the VM still
                   starts); CPU topology matching vCPU count + <cache mode='passthrough'/>;
                   currentMemory=memory (no startup balloon); <pm> S3/S4 disabled. Hugepages is
                   the ONLY host-RAM knob and is opt-in (prompted default N, or
                   --ultimate-perf-hugepages/--no-ultimate-perf-hugepages): when on, adds
                   <memoryBacking><hugepages> and reserves host nr_hugepages (reserve-first +
                   verify the kernel delivered the full count; RAM-change aware so a VM RAM
                   grow/shrink between runs adjusts the pool; reboot-safe re-reserve after a
                   host reboot reset; 1GB page sizes are guarded and skipped with a cmdline
                   hint). Reverted by --reset-ultimate-perf-vm-tuning. Idempotent. Requires an
                   existing $CONF_FILE and libvirt. DISCLAIMER: performance tuning ONLY.
  --reset-ultimate-perf-vm-tuning
                   Revert ultimate-performance VM tuning by redefining each shut-off guest-GPU
                   VM from its most recent *_perf_*.xml backup (which still contains stealth),
                   and restoring the host nr_hugepages that was reserved for it. Verifies the
                   backup XML and prompts before redefining. Requires $CONF_FILE and libvirt.
  --ultimate-perf-hugepages
                   Ultimate-perf override: reserve host hugepages + add <memoryBacking> for
                   each tuned VM (skip the opt-in prompt).
  --no-ultimate-perf-hugepages
                   Ultimate-perf override: skip host hugepages reservation (skip the opt-in
                   prompt). All other perf knobs still apply.
  --ultimate-perf-virtio-disk
                   Ultimate-perf override: convert each non-cdrom disk on a tuned VM from
                   SATA (or other non-virtio bus) to virtio-blk (sdX->vdX) so the disk perf
                   knobs (cache=none/io=native/discard=unmap + multiqueue + iothread) apply.
                   DANGEROUS: Windows needs the virtio-blk (viostor) driver installed FIRST
                   or it will BSOD with INACCESSIBLE_BOOT_DEVICE on the next boot. Install
                   virtio-win-guest-tools.exe in Windows first (run
                   --install-virtio-win-guest-agent to attach the driver ISO, boot, run
                   the installer, shut down), THEN run --install-ultimate-perf-vm-tuning
                   with this flag. Skips the opt-in prompt.
  --no-ultimate-perf-virtio-disk
                   Ultimate-perf override: do NOT convert disk buses (skip the opt-in
                   prompt). SATA/other disks keep their bus and get NO disk perf knobs
                   (only iothreads/cputune/topology/etc. apply).
  --ultimate-perf-vm-tuning
                   Dynamic-install override: apply ultimate-performance VM XML tuning
                   (disk I/O, iothreads, cputune/numatune, topology, hugepages opt-in)
                   to detected guest-GPU VMs during --install-dynamic-binding without
                   prompting. DISCLAIMER: performance tuning ONLY.
  --no-ultimate-perf-vm-tuning
                   Dynamic-install override: skip ultimate-performance VM XML tuning
                   during --install-dynamic-binding.
  --install-usb-bt-mitigation
                   Install ONLY the optional USB Bluetooth reset-spam mitigation (systemd+udev).
                   Default behavior detaches USB Bluetooth adapters from host drivers while keeping devices VM-pass-through eligible.
                   Advanced behavior (MATCH_MODE=include_only with INCLUDE_IDS) can also detach explicitly selected non-Bluetooth USB IDs.
  --usb-mitigation-status
                   Show USB mitigation run counts and per-device kernel reset/timeout/unusual event counters.
                   Reads the mitigation state file and scans recent kernel logs for USB instability markers.
  --print-fish-completion
                   Print fish completion script to stdout (no install required).
                   Example: source ($SCRIPT_NAME --print-fish-completion)
  --print-bash-completion
                   Print bash completion script to stdout (no install required).
                   Example: source <($SCRIPT_NAME --print-bash-completion)
  --print-zsh-completion
                   Print zsh completion script to stdout (no install required).
                   Example: source <($SCRIPT_NAME --print-zsh-completion)
EOF
}

normalize_boot_vga_policy_arg() {
  local raw="${1:-}" val
  val="${raw^^}"
  case "$val" in
    AUTO|STRICT)
      printf '%s\n' "$val"
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}
normalize_graphics_protocol_arg() {
  local raw="${1:-}" val
  val="${raw^^}"
  case "$val" in
    AUTO|X11|WAYLAND)
      printf '%s\n' "$val"
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}
normalize_binding_mode_arg() {
  local raw="${1:-}" val
  val="${raw^^}"
  case "$val" in
    EARLY|DYNAMIC)
      printf '%s\n' "$val"
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}
normalize_graphics_daemon_interval_arg() {
  local raw="${1:-}"
  [[ "$raw" =~ ^[0-9]+$ ]] || return 1
  if (( 10#$raw < 1 || 10#$raw > 3600 )); then
    return 1
  fi
  printf '%s\n' "$((10#$raw))"
}
normalize_debug_cmdline_entry_filter_arg() {
  local raw="${1:-}" trimmed
  trimmed="$(trim "$raw")"
  [[ -n "$trimmed" ]] || return 1
  printf '%s\n' "$raw"
}
parse_args() {
  while (( $# )); do
    case "$1" in
      --debug)
        DEBUG=1
        set -x
        ;;
      --dry-run)
        DRY_RUN=1
        ;;
      --no-tui)
        HAS_TUI=0
        ;;
      --boot-vga-policy)
        shift
        (( $# > 0 )) || die "--boot-vga-policy requires a value: auto|strict"
        BOOT_VGA_POLICY_OVERRIDE="$(normalize_boot_vga_policy_arg "$1")" || die "Invalid --boot-vga-policy value: $1 (expected: auto|strict)"
        ;;
      --boot-vga-policy=*)
        BOOT_VGA_POLICY_OVERRIDE="$(normalize_boot_vga_policy_arg "${1#*=}")" || die "Invalid --boot-vga-policy value: ${1#*=} (expected: auto|strict)"
        ;;
      --graphics-protocol)
        shift
        (( $# > 0 )) || die "--graphics-protocol requires a value: auto|x11|wayland"
        GRAPHICS_PROTOCOL_OVERRIDE="$(normalize_graphics_protocol_arg "$1")" || die "Invalid --graphics-protocol value: $1 (expected: auto|x11|wayland)"
        ;;
      --graphics-protocol=*)
        GRAPHICS_PROTOCOL_OVERRIDE="$(normalize_graphics_protocol_arg "${1#*=}")" || die "Invalid --graphics-protocol value: ${1#*=} (expected: auto|x11|wayland)"
        ;;
      --graphics-daemon-interval)
        shift
        (( $# > 0 )) || die "--graphics-daemon-interval requires a value: 1-3600"
        GRAPHICS_DAEMON_INTERVAL_OVERRIDE="$(normalize_graphics_daemon_interval_arg "$1")" || die "Invalid --graphics-daemon-interval value: $1 (expected integer range 1-3600)"
        ;;
      --graphics-daemon-interval=*)
        GRAPHICS_DAEMON_INTERVAL_OVERRIDE="$(normalize_graphics_daemon_interval_arg "${1#*=}")" || die "Invalid --graphics-daemon-interval value: ${1#*=} (expected integer range 1-3600)"
        ;;
  --no-graphics-daemon)
        INSTALL_GRAPHICS_DAEMON=0
        ;;
      --amd-runpm)
        AMD_RUNPM_OVERRIDE=1
        ;;
      --no-amd-runpm)
        AMD_RUNPM_OVERRIDE=0
        ;;
      --amd-noretry)
        AMD_NORETRY_OVERRIDE=1
        ;;
      --no-amd-noretry)
        AMD_NORETRY_OVERRIDE=0
        ;;
      --amd-disable-idle-d3)
        AMD_D3_OVERRIDE=1
        ;;
      --no-amd-disable-idle-d3)
        AMD_D3_OVERRIDE=0
        ;;
      --amd-pcie-port-pm-off)
        AMD_PORTPM_OVERRIDE=1
        ;;
      --no-amd-pcie-port-pm-off)
        AMD_PORTPM_OVERRIDE=0
        ;;
      --binding-mode)
        shift
        (( $# > 0 )) || die "--binding-mode requires a value: early|dynamic"
        BINDING_MODE_OVERRIDE="$(normalize_binding_mode_arg "$1")" || die "Invalid --binding-mode value: $1 (expected: early|dynamic)"
        ;;
      --binding-mode=*)
        BINDING_MODE_OVERRIDE="$(normalize_binding_mode_arg "${1#*=}")" || die "Invalid --binding-mode value: ${1#*=} (expected: early|dynamic)"
        ;;
      --verify)
        MODE="verify"
        ;;
      --detect)
        MODE="detect"
        ;;
      --sync-bls-only)
        MODE="sync-bls-only"
        ;;
      --debug-cmdline-tokens)
        MODE="debug-cmdline-tokens"
        ;;
      --entry)
        shift
        (( $# > 0 )) || die "--entry requires a basename glob pattern (example: system-*.conf)"
        DEBUG_CMDLINE_TOKENS_ENTRY_FILTER="$(normalize_debug_cmdline_entry_filter_arg "$1")" || die "Invalid --entry value: $1 (expected non-empty basename glob pattern, example: system-*.conf)"
        ;;
      --entry=*)
        DEBUG_CMDLINE_TOKENS_ENTRY_FILTER="$(normalize_debug_cmdline_entry_filter_arg "${1#*=}")" || die "Invalid --entry value: ${1#*=} (expected non-empty basename glob pattern, example: system-*.conf)"
        ;;
      --verify-bls-sync)
        MODE="verify-bls-sync"
        ;;
      --verify-bls-nosnapper)
        MODE="verify-bls-nosnapper"
        ;;
      --create-fallback-entry)
        MODE="create-fallback-entry"
        ;;
      --print-effective-config)
        MODE="print-effective-config"
        ;;
      --json)
        JSON_OUTPUT=1
        ;;
      --self-test)
        MODE="self-test"
        ;;
      --health-check)
        MODE="health-check"
        ;;
      --health-check-previous)
        MODE="health-check-prev"
        ;;
      --health-check-all)
        MODE="health-check-all"
        ;;
      --usb-health-check)
        MODE="usb-health-check"
        ;;
      --reset)
        MODE="reset"
        ;;
      --reset-usb-mitigation)
        MODE="reset-usb-mitigation"
        ;;
      --disable-bootlog)
        MODE="disable-bootlog"
        ;;
      --boot-remove)
        MODE="disable-bootlog"
        ;;
      --remove-bootlog)
        MODE="disable-bootlog"
        ;;
      --install-bootlog)
        MODE="install-bootlog"
        ;;
      --install-graphics-daemon)
        MODE="install-graphics-daemon"
        ;;
      --install-dynamic-binding)
        MODE="install-dynamic-binding"
        ;;
      --install-early-binding)
        MODE="install-early-binding"
        ;;
      --install-stealth-vm-tuning)
        MODE="install-stealth-vm-tuning"
        ;;
      --install-live-attach)
        MODE="install-live-attach"
        ;;
      --install-virtio-win-guest-agent)
        MODE="install-virtio-win-guest-agent"
        ;;
      --menu)
        MODE="menu"
        ;;
      --install-self)
        MODE="install-self"
        ;;
      --uninstall-self)
        MODE="uninstall-self"
        ;;
      --reset-stealth-vm-tuning)
        MODE="reset-stealth-vm-tuning"
        ;;
      --install-ultimate-perf-vm-tuning)
        MODE="install-ultimate-perf-vm-tuning"
        ;;
      --reset-ultimate-perf-vm-tuning)
        MODE="reset-ultimate-perf-vm-tuning"
        ;;
      --ultimate-perf-hugepages)
        ULTIMATE_PERF_HUGEPAGES_OVERRIDE=1
        ;;
      --no-ultimate-perf-hugepages)
        ULTIMATE_PERF_HUGEPAGES_OVERRIDE=0
        ;;
      --ultimate-perf-virtio-disk)
        ULTIMATE_PERF_VIRTIO_DISK_OVERRIDE=1
        ;;
      --no-ultimate-perf-virtio-disk)
        ULTIMATE_PERF_VIRTIO_DISK_OVERRIDE=0
        ;;
      --ultimate-perf-vm-tuning)
        ULTIMATE_PERF_VM_TUNING_OVERRIDE=1
        ;;
      --no-ultimate-perf-vm-tuning)
        ULTIMATE_PERF_VM_TUNING_OVERRIDE=0
        ;;
      --stealth-vm-tuning)
        STEALTH_VM_TUNING_OVERRIDE=1
        ;;
      --no-stealth-vm-tuning)
        STEALTH_VM_TUNING_OVERRIDE=0
        ;;
      --vbios)
        VBIOS_INJECTION_OVERRIDE=1
        ;;
      --no-vbios)
        VBIOS_INJECTION_OVERRIDE=0
        ;;
      --install-usb-bt-mitigation)
        MODE="install-usb-bt-mitigation"
        ;;
      --usb-mitigation-status)
        MODE="usb-mitigation-status"
        ;;
      --print-fish-completion)
        MODE="print-fish-completion"
        ;;
      --print-bash-completion)
        MODE="print-bash-completion"
        ;;
      --print-zsh-completion)
        MODE="print-zsh-completion"
        ;;
      -h|--help)
        usage
        exit 0
        ;;
      *)
        die "Unknown argument: $1 (try --help)"
        ;;
    esac
    shift
  done

  # verify/detect/self-test/print-effective-config/completion modes imply dry-run
  if [[ "$MODE" == "verify" || "$MODE" == "detect" || "$MODE" == "debug-cmdline-tokens" || "$MODE" == "verify-bls-sync" || "$MODE" == "verify-bls-nosnapper" || "$MODE" == "self-test" || "$MODE" == "print-effective-config" || "$MODE" == "print-fish-completion" || "$MODE" == "print-bash-completion" || "$MODE" == "print-zsh-completion" || "$MODE" == "usb-mitigation-status" ]]; then
    DRY_RUN=1
  fi

  if (( JSON_OUTPUT )) && [[ "$MODE" != "detect" && "$MODE" != "debug-cmdline-tokens" ]]; then
    die "--json is currently supported only with --detect or --debug-cmdline-tokens"
  fi
  if [[ -n "${DEBUG_CMDLINE_TOKENS_ENTRY_FILTER:-}" ]] && [[ "$MODE" != "debug-cmdline-tokens" ]]; then
    die "--entry is supported only with --debug-cmdline-tokens"
  fi
}

json_escape() {
  local s="${1:-}"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  s="${s//$'\n'/\\n}"
  s="${s//$'\r'/\\r}"
  s="${s//$'\t'/\\t}"
  printf '%s' "$s"
}

debug_cmdline_tokens_print_json_lines() {
  local raw_output="${1:-}" exit_code="${2:-0}"
  local filter="${DEBUG_CMDLINE_TOKENS_ENTRY_FILTER:-}"
  local -a lines=()
  local idx line
  if [[ -n "$raw_output" ]]; then
    mapfile -t lines <<<"$raw_output"
  fi

  printf '{\n'
  printf '  "mode": "debug-cmdline-tokens",\n'
  printf '  "entry_filter": "%s",\n' "$(json_escape "$filter")"
  printf '  "exit_code": %s,\n' "$exit_code"
  printf '  "lines": [\n'
  for idx in "${!lines[@]}"; do
    line="${lines[$idx]}"
    printf '    "%s"' "$(json_escape "$line")"
    if (( idx + 1 < ${#lines[@]} )); then
      printf ','
    fi
    printf '\n'
  done
  printf '  ]\n'
  printf '}\n'
}

# Disable and remove the optional VFIO boot log dumper without touching the
# rest of the VFIO configuration.
disable_bootlog_dumper() {
  hdr "Disable VFIO boot log dumper"

  local unit="/etc/systemd/system/vfio-dump-boot-log.service"
  local bin
  bin="$(bootlog_bin_path)"

  if ! [[ -f "$unit" || -f "$bin" ]]; then
    note "Boot log dumper unit/script not found; nothing to disable."
    return 0
  fi

  if command -v systemctl >/dev/null 2>&1 && [[ -f "$unit" ]]; then
    note "Disabling and stopping vfio-dump-boot-log.service (VFIO setup will remain active)."
    run systemctl disable --now vfio-dump-boot-log.service 2>/dev/null || true
    run systemctl daemon-reload 2>/dev/null || true
  elif ! command -v systemctl >/dev/null 2>&1; then
    note "systemctl not found; disabling the service automatically is not possible."
  fi

  # Remove the unit and helper script (if present). This mirrors the paths
  # used by install_bootlog_dumper and reset_vfio_all.
  run rm -f "$unit" "$bin" 2>/dev/null || true

  say "Boot log dumper disabled and removed. Existing log files under ~/Desktop/vfio-boot-logs are left untouched."
}

write_file_atomic() {
  # write_file_atomic /path mode owner:group
  local dst="$1" mode="$2" owner_group="$3"
  local tmp
  tmp="$(mktemp)"
  cat >"$tmp"
  if (( DRY_RUN )); then
    rm -f "$tmp" || true
    return 0
  fi
  install -o "${owner_group%%:*}" -g "${owner_group##*:}" -m "$mode" "$tmp" "$dst"
  rm -f "$tmp" || true
}
write_file_atomic_if_changed() {
  # write_file_atomic_if_changed /path mode owner:group [backup_existing]
  # Returns:
  #   0 -> file content changed and was written (or would be written in DRY_RUN)
  #   1 -> destination already had identical content; write skipped
  local dst="$1" mode="$2" owner_group="$3" backup_existing="${4:-0}"
  local tmp
  tmp="$(mktemp)"
  cat >"$tmp"

  if [[ -f "$dst" ]] && have_cmd cmp && cmp -s "$tmp" "$dst"; then
    rm -f "$tmp" || true
    return 1
  fi

  if (( backup_existing )) && [[ -f "$dst" ]]; then
    backup_file "$dst"
  fi
  if (( DRY_RUN )); then
    rm -f "$tmp" || true
    return 0
  fi
  install -o "${owner_group%%:*}" -g "${owner_group##*:}" -m "$mode" "$tmp" "$dst"
  rm -f "$tmp" || true
  return 0
}

assert_pci_bdf_exists() {
  local bdf="$1"
  [[ -n "$bdf" ]] || die "Empty PCI BDF"
  [[ -d "/sys/bus/pci/devices/$bdf" ]] || die "PCI device not present in sysfs: $bdf"
}

assert_not_equal() {
  local a="$1" b="$2" msg="$3"
  [[ "$a" != "$b" ]] || die "$msg"
}

confirm_phrase() {
  # confirm_phrase "Prompt" "PHRASE"
  local prompt="$1" phrase="$2" ans

  # IMPORTANT: do not print prompts to stdout (stdout may be captured).
  local in="/dev/stdin"
  local out="/dev/stderr"
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi

  printf '%s\n' "$prompt" >"$out"
  printf '%s\n' "Type exactly: $phrase" >"$out"
  printf '> ' >"$out"

  read -r ans <"$in"
  [[ "$ans" == "$phrase" ]]
}

pci_slot_of_bdf() {
  # 0000:06:00.1 -> 0000:06:00
  echo "${1%.*}"
}

iommu_group_of_bdf() {
  local bdf="$1"
  local link
  link="/sys/bus/pci/devices/$bdf/iommu_group"
  [[ -e "$link" ]] || return 1
  basename "$(readlink -f "$link")"
}

list_iommu_group_devices() {
  # list_iommu_group_devices <group_num>
  local group="$1"
  local d
  for d in /sys/kernel/iommu_groups/"$group"/devices/*; do
    basename "$d"
  done
}

bdf_driver_name() {
  local bdf="$1"
  local sys="/sys/bus/pci/devices/$bdf/driver"
  [[ -L "$sys" ]] || { echo "<none>"; return 0; }
  basename "$(readlink -f "$sys")"
}

pci_boot_vga_flag() {
  # Returns:
  #   1 / 0 when boot_vga is available for this PCI BDF
  #   unknown when sysfs does not expose boot_vga for this device
  local bdf="$1"
  local f="/sys/bus/pci/devices/$bdf/boot_vga"
  if [[ -f "$f" ]]; then
    cat "$f" 2>/dev/null || echo "unknown"
    return 0
  fi
  echo "unknown"
  return 0
}

host_assisted_boot_vga_policy_default() {
  # Auto-enable host-assisted Boot-VGA bind only when:
  # - guest GPU is Boot VGA (1)
  # - host GPU is a different adapter with boot_vga=0
  local host_gpu="$1"
  local guest_gpu="$2"
  [[ -n "$host_gpu" && -n "$guest_gpu" ]] || { echo "0"; return 0; }
  [[ "$host_gpu" != "$guest_gpu" ]] || { echo "0"; return 0; }

  local host_boot_vga guest_boot_vga
  host_boot_vga="$(pci_boot_vga_flag "$host_gpu")"
  guest_boot_vga="$(pci_boot_vga_flag "$guest_gpu")"

  if [[ "$guest_boot_vga" == "1" && "$host_boot_vga" == "0" ]]; then
    echo "1"
    return 0
  fi
  echo "0"
  return 0
}

drm_card_for_bdf() {
  # Print matching /dev/dri/cardX for a given BDF.
  local bdf="$1" card
  for card in /sys/class/drm/card*; do
    [[ -e "$card/device" ]] || continue
    if [[ "$(basename "$(readlink -f "$card/device")")" == "$bdf" ]]; then
      echo "/dev/dri/${card##*/}"
      return 0
    fi
  done
  return 1
}

gpu_in_use_preflight() {
  local bdf="$1"
  
  # 1. Check for standard DRM drivers (existing logic)
  local drv
  drv="$(bdf_driver_name "$bdf")"
  [[ "$drv" == "vfio-pci" ]] && return 0
  [[ "$drv" == "<none>" ]] && return 0

  local card
  if card="$(drm_card_for_bdf "$bdf" 2>/dev/null)"; then
    say "WARN: Guest GPU $bdf is currently a DRM device: $card (driver: $drv)"
    if command -v lsof >/dev/null 2>&1; then
      if lsof "$card" >/dev/null 2>&1; then
        say "WARN: $card is currently opened by some process(es)."
      fi
    fi

    # 1.5 Check if the HDMI Audio associated with this GPU is in use
    local slot="${bdf%.*}"
    local audio_bdf="${slot}.1"  # Commonly function 1 is the HDMI audio function
    if [[ -d "/sys/bus/pci/devices/$audio_bdf" ]]; then
      local snd card_id
      for snd in /sys/bus/pci/devices/"$audio_bdf"/sound/card*; do
        [[ -d "$snd" ]] || continue
        card_id="${snd##*/card}"
        if command -v fuser >/dev/null 2>&1; then
          if fuser -v /dev/snd/pcmC"${card_id}"D* >/dev/null 2>&1; then
            say "${C_YELLOW}WARN: HDMI Audio device ($audio_bdf) for this GPU appears to be in use (ALSA card $card_id).${C_RESET}"
            note "      PulseAudio/PipeWire is likely holding the HDMI audio device open."
            if ! confirm_phrase "Binding this GPU may crash or restart your audio server. Continue?" "I UNDERSTAND"; then
              die "Aborted due to active audio device lock."
            fi
          fi
        fi
      done
    fi

    if ! confirm_phrase "Refusing to continue by default (binding an in-use GPU can crash your desktop)." "I UNDERSTAND"; then
      die "Aborted: guest GPU appears to be in use"
    fi
  fi

  # 2. Check for EFI/Simple Framebuffer attachment on Boot VGA.
  if [[ -f "/sys/bus/pci/devices/$bdf/boot_vga" ]]; then
    local is_boot_vga
    is_boot_vga="$(cat "/sys/bus/pci/devices/$bdf/boot_vga")"
    
    if [[ "$is_boot_vga" == "1" ]]; then
      # Check if a framebuffer driver is active in iomem
      if grep -qiE '(efifb|simple-framebuffer|vesafb)' /proc/iomem 2>/dev/null; then
        say "${C_YELLOW}WARN: This GPU is marked as Boot VGA and a framebuffer is active.${C_RESET}"
        note "      This can lock the GPU memory, causing VFIO binding to fail (\"Header type 127\" / hangs)."
        
        local fb_param=""
        if grep -qi "simple-framebuffer" /proc/iomem 2>/dev/null; then
          fb_param="video=simplefb:off"
        elif grep -qi "efifb" /proc/iomem 2>/dev/null; then
          fb_param="video=efifb:off"
        else
          fb_param="video=vesafb:off"
        fi

        # IMPORTANT for stability on some systems ("Christmas tree" crash):
        # keep this mitigation explicitly opt-in on openSUSE, because it can
        # over-constrain display init on snapshot-heavy rollback workflows.
        local fb_prompt_default="Y"
        if is_opensuse_like; then
          fb_prompt_default="N"
          note "openSUSE detected: framebuffer-disable flags stay opt-in by default. Enable only if you confirm framebuffer lock symptoms."
        fi
        if prompt_yn "Add '$fb_param' to boot kernel parameters?" "$fb_prompt_default" "Boot framebuffer options"; then
          export GRUB_EXTRA_PARAMS="${GRUB_EXTRA_PARAMS:-} ${fb_param}"
          say "Queued '$fb_param' for GRUB update. It will be applied if you enable IOMMU/GRUB editing."
        else
          if ! prompt_yn "Continue without fixing (higher risk of passthrough failure)?" N "Boot framebuffer options"; then
            die "Aborted due to active framebuffer lock."
          fi
        fi
      fi
    fi
  fi
}

wpctl_cmd() {
  # Run wpctl as the desktop user if invoked via sudo, so it can connect to the user PipeWire instance.
  if have_cmd wpctl; then
    local euid
    euid="${EUID:-$(id -u)}"

    # Best-effort: if running under sudo with a real SUDO_USER and runuser,
    # try to talk to that user's PipeWire instance via /run/user/$uid. If
    # the runtime dir does not exist, fall back to plain wpctl.
    if [[ "$euid" -eq 0 ]]; then
      if [[ -n "${SUDO_USER:-}" ]] && have_cmd runuser; then
        local uid runtime
        uid="$(id -u "$SUDO_USER")"
        runtime="/run/user/$uid"
        if [[ -d "$runtime" ]]; then
          runuser -u "$SUDO_USER" -- env XDG_RUNTIME_DIR="$runtime" wpctl "$@"
          return $?
        fi
      else
        # If running as root without SUDO_USER, warn once that audio
        # auto-detection may be incomplete because there is no obvious
        # desktop user session to talk to.
        if [[ -z "${_VFIO_WPCTL_ROOT_WARNED:-}" ]]; then
          _VFIO_WPCTL_ROOT_WARNED=1
          note "wpctl is running as root without SUDO_USER; PipeWire device detection may be limited. Run this helper via sudo from your desktop user for best results."
        fi
      fi
    fi

    wpctl "$@"
    return $?
  fi
  return 127
}

pipewire_sinks_for_pci_bdf() {
  # Emits TSV: NODE_NAME \t LABEL for sinks that match the PCI tag of this BDF.
  local bdf="$1"
  have_cmd wpctl || return 1

  local pci_tag
  pci_tag="$(echo "$bdf" | sed -E 's/^0000:/pci-0000_/; s/:/_/g')"

  local sid sname slabel
  while IFS=$'\t' read -r sid sname slabel; do
    if wpctl_cmd inspect "$sid" 2>/dev/null | grep -Fq "$pci_tag"; then
      printf '%s\t%s\n' "$sname" "$slabel"
    fi
  done < <(pipewire_sinks_discover)
}

print_kv() {
  # print_kv "Key" "Value"
  printf '  %-28s %s\n' "${1}:" "${2}"
}

readable_file() {
  [[ -f "$1" && -r "$1" ]]
}
resolve_desktop_user_home() {
  # Resolve the primary desktop user and home directory.
  # 1) Prefer SUDO_USER when valid and mapped to an existing home.
  # 2) Fallback to first non-system user with an existing /home/* directory.
  local home user uid shell

  if [[ -n "${SUDO_USER:-}" && "${SUDO_USER}" != "root" ]]; then
    home="$(getent passwd "$SUDO_USER" 2>/dev/null | cut -d: -f6 || true)"
    if [[ -n "$home" && -d "$home" ]]; then
      printf '%s\t%s\n' "$SUDO_USER" "$home"
      return 0
    fi
  fi

  while IFS=: read -r user _ uid _ _ home shell; do
    [[ "$uid" =~ ^[0-9]+$ ]] || continue
    (( uid >= 1000 )) || continue
    [[ "$user" == "nobody" ]] && continue
    [[ -n "$home" && "$home" == /home/* && -d "$home" ]] || continue
    case "$shell" in
      */false|*/nologin) continue ;;
    esac
    printf '%s\t%s\n' "$user" "$home"
    return 0
  done </etc/passwd

  return 1
}

bootlog_bin_path() {
  local pair home
  pair="$(resolve_desktop_user_home 2>/dev/null || true)"
  if [[ -n "$pair" ]]; then
    home="${pair#*$'\t'}"
    [[ -n "$home" ]] && { printf '%s\n' "$home/.local/bin/vfio-dump-boot-log.sh"; return 0; }
  fi
  printf '%s\n' "/home/${SUDO_USER:-root}/.local/bin/vfio-dump-boot-log.sh"
}
report_vm_network_precheck() {
  # Detect a common host-side cause of "VM has no internet":
  # net.ipv4.ip_forward=0 while using libvirt NAT (virbr0/default network).
  # This is informational and does not change system state.
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- VM internet precheck (libvirt / virt-manager) --${C_RESET}"
  else
    say "-- VM internet precheck (libvirt / virt-manager) --"
  fi

  local ip4_fwd="unknown" ip6_fwd="unknown"
  if [[ -r /proc/sys/net/ipv4/ip_forward ]]; then
    read -r ip4_fwd </proc/sys/net/ipv4/ip_forward || ip4_fwd="unknown"
  fi
  if [[ -r /proc/sys/net/ipv6/conf/all/forwarding ]]; then
    read -r ip6_fwd </proc/sys/net/ipv6/conf/all/forwarding || ip6_fwd="unknown"
  fi

  local virbr0_state="missing"
  if [[ -d /sys/class/net/virbr0 ]]; then
    virbr0_state="present"
  fi

  local sysctl_zero_file=""
  if [[ -f /etc/sysctl.d/70-yast.conf ]] && \
     grep -Eq '^[[:space:]]*net\.ipv4\.ip_forward[[:space:]]*=[[:space:]]*0([[:space:]]|$)' /etc/sysctl.d/70-yast.conf; then
    sysctl_zero_file="/etc/sysctl.d/70-yast.conf"
  elif [[ -d /etc/sysctl.d ]]; then
    local sf
    shopt -s nullglob
    for sf in /etc/sysctl.d/*.conf; do
      if grep -Eq '^[[:space:]]*net\.ipv4\.ip_forward[[:space:]]*=[[:space:]]*0([[:space:]]|$)' "$sf"; then
        sysctl_zero_file="$sf"
        break
      fi
    done
    shopt -u nullglob
  fi

  print_kv "virbr0 bridge" "$virbr0_state"
  print_kv "net.ipv4.ip_forward" "$ip4_fwd"
  print_kv "net.ipv6.forwarding" "$ip6_fwd"

  if [[ "$ip4_fwd" == "0" ]]; then
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: net.ipv4.ip_forward=0 can break VM internet on libvirt NAT (guest gets DHCP but no outbound internet)."
    else
      say "WARN: net.ipv4.ip_forward=0 can break VM internet on libvirt NAT (guest gets DHCP but no outbound internet)."
    fi
    note "Fix now (temporary): sudo sysctl -w net.ipv4.ip_forward=1"
    if [[ -n "$sysctl_zero_file" ]]; then
      note "Persistent blocker found: $sysctl_zero_file sets net.ipv4.ip_forward = 0"
      note "Set it to: net.ipv4.ip_forward = 1, then run: sudo sysctl --system"
    else
      note "Persistent fix: set net.ipv4.ip_forward = 1 in /etc/sysctl.d/*.conf, then run: sudo sysctl --system"
    fi
    return 1
  fi

  if [[ "$virbr0_state" == "missing" ]]; then
    note "INFO: virbr0 bridge is missing. If you use virt-manager NAT, start/autostart the default libvirt network."
    note "Try: sudo virsh -c qemu:///system net-start default && sudo virsh -c qemu:///system net-autostart default"
  fi

  if (( ENABLE_COLOR )); then
    say "${C_GREEN}OK${C_RESET}: no obvious host forwarding blocker detected for libvirt NAT networking."
  else
    say "OK: no obvious host forwarding blocker detected for libvirt NAT networking."
  fi
  return 0
}

csv_each() {
  # csv_each "a,b,c" -> prints one per line
  local csv="${1:-}"
  local IFS=','
  local -a arr=()
  read -r -a arr <<<"$csv"
  printf '%s\n' "${arr[@]}"
}

is_service_enabled() {
  local unit="$1"
  command -v systemctl >/dev/null 2>&1 || return 1
  systemctl is-enabled "$unit" >/dev/null 2>&1
}

is_service_active() {
  local unit="$1"
  command -v systemctl >/dev/null 2>&1 || return 1
  systemctl is-active "$unit" >/dev/null 2>&1
}

# Plymouth splash can keep GPUs/DRM devices busy during early boot on some
# desktop setups (especially KDE Plasma + Wayland), which can interfere with
# vfio-pci claiming the guest GPU. We disable Plymouth in two ways:
#  1) kernel cmdline: rd.plymouth=0 plymouth.enable=0 and remove splash tokens
#  2) systemd: mask common plymouth unit names (best-effort)
plymouth_units() {
  # Print a whitespace-separated list of common Plymouth unit names.
  # (Not all distros ship all of these.)
  printf '%s\n' \
    plymouth-start.service \
    plymouth-read-write.service \
    plymouth-quit.service \
    plymouth-quit-wait.service \
    plymouth-switch-root.service \
    plymouth-halt.service \
    plymouth-reboot.service
}

disable_plymouth_services() {
  have_cmd systemctl || return 0

  note "Disabling Plymouth boot splash (masking plymouth systemd units; best-effort)."

  local u
  while IFS= read -r u; do
    [[ -n "$u" ]] || continue
    # Mask each unit individually so one missing unit doesn't prevent the rest.
    run systemctl mask --now "$u" 2>/dev/null || true
  done < <(plymouth_units)

  run systemctl daemon-reload 2>/dev/null || true
}

unmask_plymouth_services() {
  have_cmd systemctl || return 0

  note "Re-enabling Plymouth (unmasking plymouth systemd units; best-effort)."

  local u
  while IFS= read -r u; do
    [[ -n "$u" ]] || continue
    run systemctl unmask "$u" 2>/dev/null || true
  done < <(plymouth_units)

  run systemctl daemon-reload 2>/dev/null || true
}

grub_cmdline_value() {
  # Returns the configured grub cmdline (GRUB_CMDLINE_LINUX_DEFAULT or GRUB_CMDLINE_LINUX)
  [[ -f /etc/default/grub ]] || return 1
  local key
  key="$(grub_get_key 2>/dev/null || true)"
  [[ -n "$key" ]] || return 1
  grub_read_cmdline "$key" 2>/dev/null
}

grub_has_vfio_params() {
  local cmd
  cmd="$(grub_cmdline_value 2>/dev/null || true)"
  [[ -n "$cmd" ]] || return 1
  grep -Eq '(^|[[:space:]])(amd_iommu=on|intel_iommu=on|iommu=pt|pcie_acs_override=downstream,multifunction)([[:space:]]|$)' <<<"$cmd"
}

# CPU virtualization / Secure Boot helpers (non-fatal diagnostics)
check_cpu_features() {
  say
  hdr "CPU Virtualization Support"

  local cpu_flags
  cpu_flags="$(grep -m1 -E '^flags' /proc/cpuinfo 2>/dev/null || true)"

  if echo "$cpu_flags" | grep -qwE 'vmx|svm'; then
    say "OK: CPU virtualization extensions (vmx/svm) detected."
  else
    say "WARN: CPU virtualization extensions (vmx/svm) NOT detected."
    say "      Ensure VT-x (Intel) or SVM/AMD-V (AMD) is enabled in BIOS/UEFI."
  fi
}

check_secure_boot() {
  # Only relevant on UEFI systems.
  if [[ ! -d /sys/firmware/efi/efivars ]]; then
    return 0
  fi

  if command -v mokutil >/dev/null 2>&1; then
    if mokutil --sb-state 2>/dev/null | grep -qi "SecureBoot enabled"; then
      say "WARN: Secure Boot is ENABLED."
      note "      Strict Secure Boot policies may block unsigned modules or lock down the kernel."
      note "      If vfio modules fail to load, consider testing with Secure Boot temporarily disabled."
    fi
  fi
}

# Return 0 if any of the typical early framebuffers (simpledrm/sysfb/efifb/
# vesafb) appear as reserved memory in /proc/iomem. This is a strong hint
# that the boot console is still attached to the GPU and can interfere with
# VFIO binding.
simplefb_lock_active() {
  grep -qiE '(simple-framebuffer|simpledrm|efifb|vesafb|EFI Framebuffer)' /proc/iomem 2>/dev/null
}

# Return 0 if we detect that the GPU's BARs are mapped above the 4G
# boundary. This is a strong indication that "Above 4G Decoding" (a.k.a.
# 64-bit BAR support / Large BAR) is effectively active for this device.
#
# We consider Above 4G Decoding to be effectively enabled when at least
# one Memory BAR for the device has an address whose hex representation
# is longer than 8 characters (i.e. above 0xFFFFFFFF).
above_4g_decoding_enabled_for_bdf() {
  local bdf="$1"
  have_cmd lspci || return 1

  # Use -v (not -vv) to keep output smaller; region lines are the same.
  local line addr raw
  while read -r line; do
    # Typical line: "Region 0: Memory at 380000000000 (64-bit, prefetchable)"
    if [[ "$line" == *"Memory at"* ]]; then
      # Third field is the hex address right after "Memory" and "at".
      raw="$(awk '{print $3}' <<<"$line")"
      # Strip anything after an opening parenthesis, just in case.
      addr="${raw%%(*}"
      # Strip any 0x prefix if present (some lspci builds may add it).
      addr="${addr#0x}"
      # If the hex string is longer than 8 characters, it's above 4G.
      if [[ ${#addr} -gt 8 ]]; then
        return 0
      fi
    fi
  done < <(lspci -v -s "$bdf" 2>/dev/null || true)

  return 1
}

# Human-readable Above 4G Decoding status string for a given BDF.
above_4g_decoding_status_for_bdf() {
  local bdf="$1"
  have_cmd lspci || { echo "unknown (lspci missing)"; return 0; }
  if above_4g_decoding_enabled_for_bdf "$bdf"; then
    echo "ENABLED (GPU BARs mapped above 4GB)"
  else
    echo "DISABLED or not used (all GPU BARs fit under 4GB)"
  fi
}

# Return 0 if lspci reports that Resizable BAR is enabled for this PCI
# device. We use this as a heuristic because large BARs combined with some
# vendor drivers/firmware combinations have been observed to cause black
# screens or other instability when doing GPU passthrough on certain
# consumer platforms.
rebar_enabled_for_bdf() {
  local bdf="$1"
  have_cmd lspci || return 1
  # If capabilities are not readable (for example when bound to vfio-pci),
  # lspci prints "Capabilities: <access denied>" and we cannot reliably
  # determine ReBAR state. In that case we return 1 ("not confirmed") and
  # higher-level callers should avoid claiming it is disabled.
  local out
  out="$(lspci -s "$bdf" -vv 2>/dev/null || true)"
  [[ -n "$out" ]] || return 1
  if grep -q 'Capabilities: <access denied>' <<<"$out"; then
    return 1
  fi
  # Look for a "Resizable BAR" capability block mentioning "Enabled" for
  # at least one BAR on this device.
  if printf '%s\n' "$out" | awk '/Resizable BAR/{flag=1;next} /^[^[:space:]]/{flag=0} flag{print}' | grep -qi 'Enabled'; then
    return 0
  fi
  return 1
}

# Human-readable ReBAR status string for a given BDF. Unlike
# rebar_enabled_for_bdf(), this does not try to return a boolean; instead it
# describes what we can see from lspci in a way that is safe when the device
# is already bound to vfio-pci and capabilities are not readable.
rebar_status_for_bdf() {
  local bdf="$1"
  have_cmd lspci || { echo "unknown (lspci missing)"; return 0; }

  local out
  out="$(lspci -s "$bdf" -vv 2>/dev/null || true)"
  [[ -n "$out" ]] || { echo "unknown (device not found)"; return 0; }

  if grep -q 'Capabilities: <access denied>' <<<"$out"; then
    echo "unknown (PCI capabilities not readable; device is likely bound to vfio-pci)"
    return 0
  fi

  local bar_block
  bar_block="$(printf '%s\n' "$out" | awk '/Resizable BAR/{flag=1;next} /^[^[:space:]]/{flag=0} flag{print}')"
  if [[ -z "$bar_block" ]]; then
    echo "not reported"
    return 0
  fi

  if grep -qi 'Enabled' <<<"$bar_block"; then
    echo "ENABLED"
  else
    # We can see a Resizable BAR capability block but no BAR marked
    # as "Enabled". All we can state with certainty is what lspci
    # shows for this device.
    echo "present (lspci does not show any BAR as Enabled for this device)"
  fi
}
extract_drm_panic_registration_lines() {
  # DRM panic registration lines are informational (panic handler registration),
  # not proof of a real kernel panic.
  local logs="${1:-}"
  [[ -n "$logs" ]] || return 0
  printf '%s\n' "$logs" | grep -E '\[drm\] Registered [0-9]+ planes with drm panic' || true
}

extract_real_kernel_panic_lines() {
  # Strong panic/oops signatures only (avoid broad false positives).
  local logs="${1:-}"
  [[ -n "$logs" ]] || return 0
  printf '%s\n' "$logs" | grep -Ei '(Kernel panic - not syncing|BUG: unable to handle kernel|Oops:|general protection fault:|fatal exception)' || true
}

# Audit whether the *currently running* kernel looks hostile to VFIO for the
# selected guest GPU. This is a diagnostic only; it does not change any
# configuration. Results are summarized in CTX[kernel_vfio_risk]:
#   0 = no obvious risk markers detected
#   1 = one or more risk markers detected (kernel version, IOMMU, logs, etc.)
#
# Additionally CTX[kernel_vfio_log_error]=1 is set if we find concrete
# vfio-pci probe/BAR errors in the logs.
#
# If a GPU BDF is supplied, we also check who currently owns the device.
# This is most useful AFTER you have already tried to boot with VFIO enabled.
audit_vfio_health() {
  local gpu_bdf="${1:-}"

  hdr "VFIO Kernel Health Audit"

  CTX[kernel_vfio_risk]=0
  CTX[kernel_vfio_log_error]=0
  CTX[kernel_vfio_env_ok]=1

  # 1) Kernel version is now treated as informational only. Static
  # version-based "high risk" heuristics (for example ">= 6.13 is bad")
  # are fragile once distributions ship fixes. Real regression detection
  # is handled via the log-based checks further below.
  local kver
  kver="$(uname -r 2>/dev/null || echo unknown)"
  if (( ENABLE_COLOR )); then
    say "${C_GREEN}INFO${C_RESET}: Running kernel: $kver"
  else
    say "INFO: Running kernel: $kver"
  fi

  # 2) Check IOMMU and VFIO module availability.
  say
  say "Checking IOMMU and VFIO module availability ..."

  if [[ -d /sys/kernel/iommu_groups ]] && ls /sys/kernel/iommu_groups/* >/dev/null 2>&1; then
    say "OK: IOMMU groups directory present."
  else
    CTX[kernel_vfio_risk]=1
    CTX[kernel_vfio_env_ok]=0
    say "WARN: /sys/kernel/iommu_groups missing or empty (IOMMU may be disabled in BIOS or kernel cmdline)."
  fi

  if vfio_pci_available; then
    say "OK: vfio-pci module is available for this kernel."
  else
    CTX[kernel_vfio_risk]=1
    CTX[kernel_vfio_env_ok]=0
    say "WARN: vfio-pci module not found by modinfo; VFIO GPU binding cannot work on this kernel."
  fi

  # 3) Runtime owner of the GPU (if a BDF was provided). This is *not* a
  # definitive regression check on its own because before the first reboot
  # we still expect the host driver to own the device. It is mostly useful
  # when you run this audit AFTER a failed VFIO boot.
  if [[ -n "$gpu_bdf" ]]; then
    say
    say "Checking current driver for GPU $gpu_bdf ..."
    if [[ ! -e "/sys/bus/pci/devices/$gpu_bdf" ]]; then
      CTX[kernel_vfio_risk]=1
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}WARN${C_RESET}: PCI device $gpu_bdf not present in sysfs (hot-unplugged or wrong BDF?)."
      else
        say "WARN: PCI device $gpu_bdf not present in sysfs (hot-unplugged or wrong BDF?)."
      fi
    elif [[ ! -e "/sys/bus/pci/devices/$gpu_bdf/driver" ]]; then
      CTX[kernel_vfio_risk]=1
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}WARN${C_RESET}: Device is not bound to ANY driver right now."
      else
        say "WARN: Device is not bound to ANY driver right now."
      fi
    else
      local driver_path driver_name
      driver_path="$(readlink -f "/sys/bus/pci/devices/$gpu_bdf/driver" 2>/dev/null || true)"
      driver_name="${driver_path##*/}"
      if [[ "$driver_name" == "vfio-pci" ]]; then
        if (( ENABLE_COLOR )); then
          say "${C_GREEN}OK${C_RESET}: GPU $gpu_bdf is currently bound to vfio-pci."
        else
          say "OK: GPU $gpu_bdf is currently bound to vfio-pci."
        fi
      else
        # Not necessarily a regression (especially before the first reboot),
        # but worth surfacing.
        if (( ENABLE_COLOR )); then
          say "${C_YELLOW}INFO${C_RESET}: GPU $gpu_bdf is currently bound to '$driver_name' (not vfio-pci)."
        else
          say "INFO: GPU $gpu_bdf is currently bound to '$driver_name' (not vfio-pci)."
        fi
      fi
    fi
  fi

  # 4) Check for active simpledrm/sysfb/efifb/vesafb locks.
  say
  say "Checking for active system framebuffers (simpledrm/sysfb/efifb/vesafb) ..."
  if simplefb_lock_active; then
    CTX[kernel_vfio_risk]=1
    CTX[kernel_vfio_env_ok]=0
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: A system framebuffer (simpledrm/sysfb/efifb/vesafb) is active in /proc/iomem."
    else
      say "WARN: A system framebuffer (simpledrm/sysfb/efifb/vesafb) is active in /proc/iomem."
    fi
    note "This often means the boot console is still attached to the GPU and can block vfio-pci from claiming it."
    note "Consider enabling the framebuffer mitigation options (video=efifb:off video=vesafb:off initcall_blacklist=sysfb_init)."
  else
    say "OK: No obvious simpledrm/sysfb/efifb/vesafb regions in /proc/iomem."
  fi

  # 5) Log scan for typical vfio-pci BAR / probe failures. These are
  # strong indicators that the kernel (or another early driver like
  # simpledrm/sysfb) refused to give vfio-pci ownership of the device.
  say
  say "Scanning kernel logs for vfio-pci probe / BAR reservation errors ..."

  local log_data
  if have_cmd journalctl; then
    # Allow callers to choose which boot to inspect via VFIO_HEALTH_BOOT_OFFSET.
    #  0 or unset: current boot (-b)
    # -1: previous boot (-b -1)
    local boot_opt="-b"
    if [[ -n "${VFIO_HEALTH_BOOT_OFFSET:-}" ]]; then
      if [[ "${VFIO_HEALTH_BOOT_OFFSET}" =~ ^-?[0-9]+$ && "${VFIO_HEALTH_BOOT_OFFSET}" != "0" ]]; then
        boot_opt="-b${VFIO_HEALTH_BOOT_OFFSET}"
      fi
    fi
    log_data="$(journalctl -k "${boot_opt}" --no-pager 2>/dev/null || true)"
  else
    if ! have_cmd dmesg; then
      say "No journalctl or dmesg command available; skipping log-based checks."
      log_data=""
    else
      log_data="$(dmesg 2>/dev/null || true)"
    fi
  fi

  local dmesg_filter dmesg_out
  if [[ -n "$gpu_bdf" ]]; then
    # Match either the full BDF or just the slot (some messages only print slot)
    dmesg_filter="$(printf '%s' "$gpu_bdf" | sed 's/\\./:/')"
  else
    dmesg_filter="vfio-pci"
  fi

  if [[ -n "$log_data" ]]; then
    local drm_panic_lines real_panic_lines
    drm_panic_lines="$(extract_drm_panic_registration_lines "$log_data")"
    real_panic_lines="$(extract_real_kernel_panic_lines "$log_data")"

    if [[ -n "$real_panic_lines" ]]; then
      CTX[kernel_vfio_risk]=1
      CTX[kernel_vfio_log_error]=1
      if (( ENABLE_COLOR )); then
        say "${C_RED}CRITICAL${C_RESET}: Real kernel panic/oops markers were detected in kernel logs."
      else
        say "CRITICAL: Real kernel panic/oops markers were detected in kernel logs."
      fi
      say "--- panic markers ---"
      printf '%s\n' "$real_panic_lines"
      say "---------------------"
    elif [[ -n "$drm_panic_lines" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_BLUE}INFO${C_RESET}: Detected DRM panic-handler registration lines."
      else
        say "INFO: Detected DRM panic-handler registration lines."
      fi
      note "\"[drm] Registered ... with drm panic\" means the DRM panic handler is available; it is not a kernel panic by itself."
    fi
    # Filter for vfio-pci messages that are strongly indicative of BAR or
    # probe failures for this device. We intentionally avoid generic
    # "error" matches here to reduce false positives across distros.
    dmesg_out="$(printf '%s\n' "$log_data" \
      | grep -i "vfio-pci" \
      | grep -Ei "(BAR|cannot reserve|can't reserve|probe|failed to (enable|assign))" \
      | grep -i "$dmesg_filter" || true)"
  else
    dmesg_out=""
  fi

  if [[ -n "$dmesg_out" ]]; then
    CTX[kernel_vfio_risk]=1
    CTX[kernel_vfio_log_error]=1
    if (( ENABLE_COLOR )); then
      say "${C_RED}CRITICAL${C_RESET}: Detected vfio-pci probe/BAR errors in kernel logs that match this GPU/kernel."
    else
      say "CRITICAL: Detected vfio-pci probe/BAR errors in kernel logs that match this GPU/kernel."
    fi
    say "--- log matches ---"
    printf '%s\n' "$dmesg_out"
    say "-------------------"
    note "This strongly suggests the simpledrm/sysfb regression where the kernel refuses to release the GPU BARs to vfio-pci."
  else
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}OK${C_RESET}: No obvious vfio-pci probe/BAR reservation errors found in current boot logs."
    else
      say "OK: No obvious vfio-pci probe/BAR reservation errors found in current boot logs."
    fi
  fi

  # 6) Final summary + exit code grading for --health-check.
  local risk="${CTX[kernel_vfio_risk]:-0}"
  local log_bad="${CTX[kernel_vfio_log_error]:-0}"
  local env_ok="${CTX[kernel_vfio_env_ok]:-1}"

  say
  if (( risk == 0 )); then
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}✔ HEALTH: PASS${C_RESET} (no obvious VFIO-hostile markers detected)"
      say "${C_GREEN}Kernel regression (known VFIO/simpledrm issue): NO${C_RESET}"
      if (( env_ok == 1 )); then
        say "${C_GREEN}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES${C_RESET}"
      else
        say "${C_YELLOW}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO${C_RESET}"
      fi
    else
      say "HEALTH: PASS (no obvious VFIO-hostile markers detected)"
      say "Kernel regression (known VFIO/simpledrm issue): NO"
      if (( env_ok == 1 )); then
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES"
      else
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO"
      fi
    fi
    return 0
  elif (( log_bad == 1 )); then
    if (( ENABLE_COLOR )); then
      say "${C_RED}✖ HEALTH: FAIL${C_RESET} (critical kernel log errors seen: vfio-pci probe/BAR or panic/oops markers)"
      say "${C_RED}Kernel regression (known VFIO/simpledrm issue): YES${C_RESET}"
      if (( env_ok == 1 )); then
        say "${C_GREEN}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES${C_RESET}"
      else
        say "${C_YELLOW}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO${C_RESET}"
      fi
    else
      say "HEALTH: FAIL (critical kernel log errors seen: vfio-pci probe/BAR or panic/oops markers)"
      say "Kernel regression (known VFIO/simpledrm issue): YES"
      if (( env_ok == 1 )); then
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES"
      else
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO"
      fi
    fi
    return 2
  else
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}⚠ HEALTH: WARN${C_RESET} (one or more VFIO risk markers detected; no hard vfio-pci errors yet)"
      say "${C_YELLOW}Kernel regression (known VFIO/simpledrm issue): NO (no vfio-pci BAR/probe failures found for this GPU)${C_RESET}"
      if (( env_ok == 1 )); then
        say "${C_GREEN}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES${C_RESET}"
      else
        say "${C_YELLOW}VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO${C_RESET}"
      fi
    else
      say "HEALTH: WARN (one or more VFIO risk markers detected; no hard vfio-pci errors yet)"
      say "Kernel regression (known VFIO/simpledrm issue): NO (no vfio-pci BAR/probe failures found for this GPU)"
      if (( env_ok == 1 )); then
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): YES"
      else
        say "VFIO environment OK (IOMMU, vfio-pci, no framebuffer lock): NO"
      fi
    fi
    return 1
  fi
}

# Run a VFIO kernel health audit for all detected GPUs. Exit code is the
# worst status across all devices: 0=all PASS, 1=at least one WARN, 2=at
# least one FAIL.
health_check_all() {
  hdr "VFIO Kernel Health Audit (all GPUs)"

  local -a gpu_bdfs=()
  local gpu_bdf gpu_desc vendor_id device_id_unused audio_csv audio_descs
  while IFS=$'\t' read -r gpu_bdf gpu_desc vendor_id device_id_unused audio_csv audio_descs; do
    [[ -n "${gpu_bdf:-}" ]] || continue
    : "${device_id_unused:-}"
    gpu_bdfs+=("$gpu_bdf")
  done < <(gpu_discover_all_sysfs)

  if (( ${#gpu_bdfs[@]} == 0 )); then
    say "No GPUs found via sysfs; nothing to audit."
    return 1
  fi

  local worst=0 ec
  for gpu_bdf in "${gpu_bdfs[@]}"; do
    say
    say "=== GPU ${gpu_bdf} ==="
    if audit_vfio_health "$gpu_bdf"; then
      ec=0
    else
      ec=$?
    fi
    if (( ec > worst )); then
      worst=$ec
    fi
  done

  say
  case "$worst" in
    0)
      say "Overall health (all GPUs): PASS"
      ;;
    1)
      say "Overall health (all GPUs): WARN (at least one GPU reported VFIO risk markers)"
      ;;
    2)
      say "Overall health (all GPUs): FAIL (at least one GPU reported critical kernel log errors: vfio-pci or panic/oops markers)"
      ;;
  esac
  return "$worst"
}
usb_health_check() {
  hdr "USB/xHCI Stability Health Audit"
  note "This audit scans kernel logs for USB host-controller crash signatures and common instability markers."
  if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
    note "Tip: for full log visibility, rerun with sudo: sudo ./$SCRIPT_NAME --usb-health-check"
  fi

  local worst=0
  local inspected=0
  local -a labels=("current boot" "previous boot")
  local -a boot_opts=("-b" "-b -1")
  local i label boot_opt log_data log_source
  local crash_count timeout_count enum_err_count disconnect_count netdev_watchdog_count score

  for i in "${!labels[@]}"; do
    label="${labels[$i]}"
    boot_opt="${boot_opts[$i]}"
    log_data=""
    log_source=""

    if have_cmd journalctl; then
      if [[ "$boot_opt" == "-b -1" ]]; then
        log_data="$(journalctl -k -b -1 --no-pager 2>/dev/null || true)"
        [[ -n "$log_data" ]] && log_source="journalctl -k -b -1"
      else
        log_data="$(journalctl -k -b --no-pager 2>/dev/null || true)"
        [[ -n "$log_data" ]] && log_source="journalctl -k -b"
      fi
    fi

    if [[ -z "$log_data" && "$boot_opt" == "-b" ]] && have_cmd dmesg; then
      # dmesg only covers the current boot.
      log_data="$(dmesg 2>/dev/null || true)"
      [[ -n "$log_data" ]] && log_source="dmesg"
    fi

    if [[ -z "$log_data" ]]; then
      local -a fallback_files=()
      local f
      if [[ "$boot_opt" == "-b -1" ]]; then
        fallback_files=(/var/log/kern.log.1 /var/log/syslog.1)
      else
        fallback_files=(/var/log/kern.log /var/log/syslog)
      fi
      for f in "${fallback_files[@]}"; do
        [[ -r "$f" ]] || continue
        log_data+=$'\n'"$(cat "$f" 2>/dev/null || true)"
        log_source+="${log_source:+, }$f"
      done
    fi

    if [[ -z "$log_data" ]]; then
      note "No kernel log data available for ${label}."
      continue
    fi

    inspected=$((inspected + 1))

    crash_count="$(awk 'BEGIN{IGNORECASE=1} /xHCI host controller not responding|HC died; cleaning up|host controller halted/ {c++} END{print c+0}' <<<"$log_data")"
    timeout_count="$(awk 'BEGIN{IGNORECASE=1} /tx timeout|Read reg16 failed|command 0x[0-9a-f]+ tx timeout/ {c++} END{print c+0}' <<<"$log_data")"
    enum_err_count="$(awk 'BEGIN{IGNORECASE=1} /unable to enumerate USB device|device descriptor read\/64|can.t set config|can.t set address|over-current/ {c++} END{print c+0}' <<<"$log_data")"
    disconnect_count="$(awk 'BEGIN{IGNORECASE=1} /USB disconnect, device number/ {c++} END{print c+0}' <<<"$log_data")"
    netdev_watchdog_count="$(awk 'BEGIN{IGNORECASE=1} /NETDEV WATCHDOG/ {c++} END{print c+0}' <<<"$log_data")"

    score=0
    if (( crash_count > 0 )); then
      score=2
    elif (( timeout_count > 0 || enum_err_count > 0 || netdev_watchdog_count > 0 || disconnect_count >= 8 )); then
      score=1
    fi

    if (( score > worst )); then
      worst=$score
    fi

    say
    say "-- ${label} --"
    [[ -n "$log_source" ]] && print_kv "Log source" "$log_source"
    print_kv "xHCI fatal markers" "$crash_count"
    print_kv "USB/BT timeout markers" "$timeout_count"
    print_kv "USB enumeration errors" "$enum_err_count"
    print_kv "USB disconnect events" "$disconnect_count"
    print_kv "NETDEV WATCHDOG markers" "$netdev_watchdog_count"

    if (( score == 2 )); then
      if (( ENABLE_COLOR )); then
        say "${C_RED}CRITICAL${C_RESET}: USB host-controller crash markers were detected in ${label}."
      else
        say "CRITICAL: USB host-controller crash markers were detected in ${label}."
      fi
    elif (( score == 1 )); then
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}WARN${C_RESET}: USB instability markers were detected in ${label}."
      else
        say "WARN: USB instability markers were detected in ${label}."
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}OK${C_RESET}: No obvious USB/xHCI crash markers detected in ${label}."
      else
        say "OK: No obvious USB/xHCI crash markers detected in ${label}."
      fi
    fi

    if (( score > 0 )); then
      say "Key matching log lines:"
      awk -v max=20 'BEGIN{IGNORECASE=1; n=0} /xHCI host controller not responding|HC died; cleaning up|host controller halted|USB disconnect, device number|tx timeout|NETDEV WATCHDOG|unable to enumerate USB device|device descriptor read\/64|Read reg16 failed|can.t set config|can.t set address|over-current|reset (high-speed|SuperSpeed) USB device/ {print "  " $0; n++; if (n>=max) exit}' <<<"$log_data"
    fi
  done

  if (( inspected == 0 )); then
    say "No usable kernel log source found (journalctl/dmesg unavailable)."
    return 1
  fi

  say
  if (( worst == 2 )); then
    if (( ENABLE_COLOR )); then
      say "${C_RED}✖ USB HEALTH: FAIL${C_RESET} (controller crash signatures detected)"
    else
      say "USB HEALTH: FAIL (controller crash signatures detected)"
    fi
    note "Optional mitigation to test:"
    note "  usbcore.autosuspend=-1 pcie_aspm=off"
    note "These are optional stability workarounds. Trade-off: higher idle power usage."
    return 2
  elif (( worst == 1 )); then
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}⚠ USB HEALTH: WARN${C_RESET} (instability markers detected)"
    else
      say "USB HEALTH: WARN (instability markers detected)"
    fi
    note "Optional mitigation to test:"
    note "  usbcore.autosuspend=-1 pcie_aspm=off"
    note "These are optional stability workarounds. Trade-off: higher idle power usage."
    return 1
  fi

  if (( ENABLE_COLOR )); then
    say "${C_GREEN}✔ USB HEALTH: PASS${C_RESET} (no obvious crash markers detected)"
  else
    say "USB HEALTH: PASS (no obvious crash markers detected)"
  fi
  return 0
}

iommu_enabled_or_die() {
  # Best-effort check that IOMMU groups exist on this boot.
  # This requires both firmware support (VT-d / AMD-Vi) and
  # correct kernel parameters (intel_iommu=on or amd_iommu=on).
  if [[ -d /sys/kernel/iommu_groups ]]; then
    local d
    for d in /sys/kernel/iommu_groups/*; do
      if [[ -d "$d" ]]; then
        # At least one group directory exists → IOMMU active.
        return 0
      fi
    done
  fi

  say
  hdr "IOMMU required for GPU passthrough"
  note "No active IOMMU groups were detected under /sys/kernel/iommu_groups."
  note "This usually means VT-d (Intel) or IOMMU/AMD-Vi (AMD) is disabled in firmware, or kernel parameters are missing."
  note "Enable IOMMU in BIOS/UEFI and ensure kernel parameters like 'intel_iommu=on iommu=pt' or 'amd_iommu=on iommu=pt' are set."
  die "IOMMU must be enabled before running this VFIO GPU passthrough setup."
}

vfio_config_health() {
  # Prints:
  #   STATUS=OK|BAD|WARN
  #   REASON=... (0+)
  #
  # BAD means "very likely broken / dangerous" and should prompt reset.
  local status="OK"

  add_reason() {
    local sev="$1" msg="$2"
    printf 'REASON_SEV=%s\n' "$sev"
    printf 'REASON=%s\n' "$msg"
    if [[ "$sev" == "BAD" ]]; then
      status="BAD"
    elif [[ "$sev" == "WARN" && "$status" != "BAD" ]]; then
      status="WARN"
    fi
  }

  # If nothing is present, it's OK (unless GRUB still has VFIO/IOMMU params).
  local any=0
  readable_file "$CONF_FILE" && any=1
  readable_file "$SYSTEMD_UNIT" && any=1
  readable_file "$MODULES_LOAD" && any=1
  readable_file "$BLACKLIST_FILE" && any=1

  if (( ! any )); then
    if grub_has_vfio_params; then
      add_reason WARN "GRUB cmdline still contains VFIO/IOMMU params (amd_iommu/intel_iommu, iommu=pt, ACS override). Consider reset to remove."
      printf 'STATUS=%s\n' "$status"
      return 0
    fi
    printf 'STATUS=OK\n'
    return 0
  fi

  # systemd service sanity
  if is_service_enabled vfio-bind-selected-gpu.service; then
    if [[ ! -f "$BIND_SCRIPT" ]]; then
      add_reason BAD "vfio-bind-selected-gpu.service is enabled but $BIND_SCRIPT is missing"
    fi
    if [[ ! -f "$CONF_FILE" ]]; then
      add_reason BAD "vfio-bind-selected-gpu.service is enabled but $CONF_FILE is missing"
    fi
  fi

  # Config sanity
  if readable_file "$CONF_FILE"; then
    # shellcheck disable=SC1090
    . "$CONF_FILE"

    if [[ -z "${HOST_GPU_BDF:-}" || -z "${GUEST_GPU_BDF:-}" ]]; then
      add_reason BAD "$CONF_FILE exists but HOST_GPU_BDF or GUEST_GPU_BDF is empty"
    fi

    if [[ -n "${HOST_GPU_BDF:-}" && -n "${GUEST_GPU_BDF:-}" && "$HOST_GPU_BDF" == "$GUEST_GPU_BDF" ]]; then
      add_reason BAD "HOST_GPU_BDF equals GUEST_GPU_BDF ($HOST_GPU_BDF)"
    fi

    if [[ -n "${HOST_GPU_BDF:-}" && ! -d "/sys/bus/pci/devices/$HOST_GPU_BDF" ]]; then
      add_reason BAD "Configured HOST_GPU_BDF not present in sysfs: $HOST_GPU_BDF"
    fi
    if [[ -n "${GUEST_GPU_BDF:-}" && ! -d "/sys/bus/pci/devices/$GUEST_GPU_BDF" ]]; then
      add_reason BAD "Configured GUEST_GPU_BDF not present in sysfs: $GUEST_GPU_BDF"
    fi

    if [[ -n "${HOST_AUDIO_BDFS_CSV:-}" ]]; then
      local d
      while IFS= read -r d; do
        [[ -n "$d" ]] || continue
        if [[ ! -d "/sys/bus/pci/devices/$d" ]]; then
          add_reason BAD "Configured HOST_AUDIO_BDFS_CSV device not present in sysfs: $d"
        fi
      done < <(csv_each "$HOST_AUDIO_BDFS_CSV")
    fi

    if [[ -n "${GUEST_AUDIO_BDFS_CSV:-}" ]]; then
      local d
      while IFS= read -r d; do
        [[ -n "$d" ]] || continue
        if [[ ! -d "/sys/bus/pci/devices/$d" ]]; then
          add_reason BAD "Configured GUEST_AUDIO_BDFS_CSV device not present in sysfs: $d"
        fi
      done < <(csv_each "$GUEST_AUDIO_BDFS_CSV")
    fi

    # Host/guest audio overlap check
    if [[ -n "${HOST_AUDIO_BDFS_CSV:-}" && -n "${GUEST_AUDIO_BDFS_CSV:-}" ]]; then
      local h g
      while IFS= read -r h; do
        [[ -n "$h" ]] || continue
        while IFS= read -r g; do
          [[ -n "$g" ]] || continue
          if [[ "$h" == "$g" ]]; then
            add_reason BAD "Host audio and guest audio overlap (same PCI device selected): $h"
          fi
        done < <(csv_each "$GUEST_AUDIO_BDFS_CSV")
      done < <(csv_each "$HOST_AUDIO_BDFS_CSV")
    fi

    # Runtime binding mismatch hints
    if [[ -n "${GUEST_GPU_BDF:-}" ]]; then
      if [[ "$(bdf_driver_name "$GUEST_GPU_BDF")" != "vfio-pci" ]] && is_service_enabled vfio-bind-selected-gpu.service; then
        add_reason WARN "Service is enabled but guest GPU is not currently bound to vfio-pci (likely needs reboot or Boot-VGA safety policy skipped binding): $GUEST_GPU_BDF"
      fi
      if [[ -n "${HOST_GPU_BDF:-}" ]]; then
        local host_assisted_default boot_vga_policy
        host_assisted_default="$(host_assisted_boot_vga_policy_default "$HOST_GPU_BDF" "$GUEST_GPU_BDF")"
        boot_vga_policy="${VFIO_BOOT_VGA_POLICY:-STRICT}"
        boot_vga_policy="${boot_vga_policy^^}"
        case "$boot_vga_policy" in
          AUTO|STRICT) ;;
          *) boot_vga_policy="STRICT" ;;
        esac
        if [[ "$host_assisted_default" == "1" && "$boot_vga_policy" != "AUTO" && "${VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU:-0}" != "1" ]]; then
          add_reason WARN "Guest GPU is Boot VGA while HOST_GPU_BDF has boot_vga=0; set VFIO_BOOT_VGA_POLICY=AUTO (recommended) or VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1 in $CONF_FILE to allow safe host-assisted binding."
        fi
      fi
    fi
    if [[ -n "${HOST_AUDIO_BDFS_CSV:-}" ]]; then
      local ha="${HOST_AUDIO_BDFS_CSV%%,*}"
      if [[ "$(bdf_driver_name "$ha")" == "vfio-pci" ]]; then
        add_reason BAD "Host audio is currently bound to vfio-pci (host sound will break): $ha"
      fi
    fi
  else
    # If we see other installed artifacts but no config, treat as bad.
    if readable_file "$SYSTEMD_UNIT" || readable_file "$MODULES_LOAD" || readable_file "$BLACKLIST_FILE"; then
      add_reason BAD "VFIO files exist but $CONF_FILE is missing (partial install)"
    fi
  fi

  printf 'STATUS=%s\n' "$status"
}

self_test() {
  say
  hdr "Self-test"

  local fail=0

  # Basic interpreter / syntax
  if bash -n "$0" >/dev/null 2>&1; then
    print_kv "bash -n" "OK"
  else
    print_kv "bash -n" "FAIL"
    fail=1
  fi

  # awk compatibility: ensure our state-var awk pattern works (ins=1)
  if printf 'Sinks:\n  1. foo\nSources:\n' | awk '/Sinks:/{ins=1;next} /Sources:/{ins=0} ins{print}' >/dev/null 2>&1; then
    print_kv "awk (ins state var)" "OK"
  else
    print_kv "awk (ins state var)" "FAIL"
    fail=1
  fi

  # /dev/tty availability (menus rely on this under sudo)
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    print_kv "/dev/tty" "OK"
  else
    print_kv "/dev/tty" "WARN (menus may be invisible under sudo)"
  fi

  # PipeWire: best-effort
  if have_cmd wpctl; then
    if wpctl_cmd status >/dev/null 2>&1; then
      print_kv "PipeWire/wpctl" "OK"
    else
      print_kv "PipeWire/wpctl" "WARN (wpctl cannot connect in current context)"
    fi
  else
    print_kv "PipeWire/wpctl" "SKIP (wpctl not installed)"
  fi

  # GPU discovery (sysfs-based)
  local count
  count="$(gpu_discover_all_sysfs | wc -l | tr -d ' ')"
  print_kv "GPU discovery" "Found ${count} GPU(s)"

  # Openbox monitor parser regression smoke check
  local openbox_parser_sample openbox_parser_out
  openbox_parser_sample=$'Screen 0: minimum 8 x 8, current 4480 x 1440, maximum 32767 x 32767\nHDMI-1 connected primary 2560x1440+0+0\nDP-1 connected 1920x1080+2560+0\nDP-2 disconnected\n'
  openbox_parser_out="$(printf '%s\n' "$openbox_parser_sample" | openbox_connected_outputs_from_xrandr_query | paste -sd',' -)"
  if [[ "$openbox_parser_out" == "HDMI-1,DP-1" ]]; then
    print_kv "Openbox monitor parser" "OK"
  else
    print_kv "Openbox monitor parser" "FAIL (got: ${openbox_parser_out:-<empty>})"
    fail=1
  fi

  # CPU virtualization + Secure Boot checks (non-fatal)
  check_cpu_features
  check_secure_boot

  if (( fail )); then
    say "Self-test result: FAIL"
    return 1
  fi
  say "Self-test result: OK"
  return 0
}

detect_existing_vfio_report() {
  # Basic host state
  local dm_name dm_dep_status xorg_status wayland_status graphics_protocol_support graphics_protocol_mode openbox_status i3_status bspwm_status awesome_status dwm_status qtile_status xfwm4_status
  dm_name="$(detect_display_manager 2>/dev/null || true)"
  [[ -n "$dm_name" ]] || dm_name="none"
  dm_dep_status="$(display_manager_dependency_status "$dm_name")"
  xorg_status="$(xorg_stack_status)"
  wayland_status="$(wayland_stack_status)"
  graphics_protocol_support="$(x11_wayland_support_status "$xorg_status" "$wayland_status")"
  graphics_protocol_mode="$(x11_wayland_supported_mode "$xorg_status" "$wayland_status")"
  openbox_status="$(openbox_stack_status)"
  i3_status="$(i3_stack_status)"
  bspwm_status="$(bspwm_stack_status)"
  awesome_status="$(awesome_stack_status)"
  dwm_status="$(dwm_stack_status)"
  qtile_status="$(qtile_stack_status)"
  xfwm4_status="$(xfwm4_stack_status)"

  if (( JSON_OUTPUT )); then
    local opensuse_like_json accountsservice_present_json configured_graphics_protocol_mode configured_graphics_daemon_interval configured_graphics_watchdog_retention_days configured_graphics_watchdog_max_lines hc status
    local fallback_report fallback_status fallback_reason fallback_source_entry fallback_target_entry fallback_source_name fallback_target_name fallback_applicable_json
    opensuse_like_json=false
    accountsservice_present_json=false
    configured_graphics_protocol_mode="AUTO"
    configured_graphics_daemon_interval="$GRAPHICS_DAEMON_INTERVAL_DEFAULT"
    configured_graphics_watchdog_retention_days="$GRAPHICS_WATCHDOG_RETENTION_DAYS_DEFAULT"
    configured_graphics_watchdog_max_lines="$GRAPHICS_WATCHDOG_MAX_LINES_DEFAULT"
    fallback_status="NOT_APPLICABLE"
    fallback_reason=""
    fallback_source_entry=""
    fallback_target_entry=""
    fallback_source_name=""
    fallback_target_name=""
    fallback_applicable_json=false
    if opensuse_like_detection_reason >/dev/null 2>&1; then
      opensuse_like_json=true
    fi
    if accountsservice_is_present; then
      accountsservice_present_json=true
    fi
    if readable_file "$CONF_FILE"; then
      configured_graphics_protocol_mode="$(awk -F= '/^GRAPHICS_PROTOCOL_MODE=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
      configured_graphics_protocol_mode="$(trim "${configured_graphics_protocol_mode:-}")"
      configured_graphics_protocol_mode="${configured_graphics_protocol_mode^^}"
      case "$configured_graphics_protocol_mode" in
        X11|WAYLAND|AUTO) ;;
        *) configured_graphics_protocol_mode="AUTO" ;;
      esac
      configured_graphics_daemon_interval="$(graphics_daemon_interval_from_conf_or_default)"
      configured_graphics_watchdog_retention_days="$(graphics_watchdog_retention_days_from_conf_or_default)"
      configured_graphics_watchdog_max_lines="$(graphics_watchdog_max_lines_from_conf_or_default)"
    fi
    hc="$(vfio_config_health)"
    status="$(printf '%s\n' "$hc" | awk -F= '/^STATUS=/{print $2; exit}')"
    status="${status:-UNKNOWN}"
    fallback_report="$(bls_fallback_entry_detect_status)"
    local key value
    while IFS='=' read -r key value; do
      case "$key" in
        STATUS) fallback_status="$value" ;;
        REASON) fallback_reason="$value" ;;
        SOURCE_ENTRY) fallback_source_entry="$value" ;;
        TARGET_ENTRY) fallback_target_entry="$value" ;;
      esac
    done <<<"$fallback_report"
    if [[ "$fallback_status" != "NOT_APPLICABLE" ]]; then
      fallback_applicable_json=true
    fi
    if [[ -n "$fallback_source_entry" ]]; then
      fallback_source_name="$(basename "$fallback_source_entry")"
    fi
    if [[ -n "$fallback_target_entry" ]]; then
      fallback_target_name="$(basename "$fallback_target_entry")"
    fi

    printf '{\n'
    printf '  \"mode\": \"detect\",\n'
    printf '  \"bootloader\": \"%s\",\n' "$(detect_bootloader)"
    printf '  \"opensuse_like\": %s,\n' "$opensuse_like_json"
    printf '  \"display_manager\": \"%s\",\n' "$dm_name"
    printf '  \"display_manager_health\": \"%s\",\n' "$dm_dep_status"
    printf '  \"graphics_stack_xorg\": \"%s\",\n' "$xorg_status"
    printf '  \"graphics_stack_wayland\": \"%s\",\n' "$wayland_status"
    printf '  \"graphics_protocol_support\": \"%s\",\n' "$graphics_protocol_support"
    printf '  \"graphics_protocol_mode\": \"%s\",\n' "$graphics_protocol_mode"
    printf '  \"configured_graphics_protocol_mode\": \"%s\",\n' "$configured_graphics_protocol_mode"
    printf '  \"configured_graphics_daemon_interval_seconds\": %s,\n' "$configured_graphics_daemon_interval"
    printf '  \"configured_graphics_watchdog_retention_days\": %s,\n' "$configured_graphics_watchdog_retention_days"
    printf '  \"configured_graphics_watchdog_max_lines\": %s,\n' "$configured_graphics_watchdog_max_lines"
    printf '  \"window_manager_openbox\": \"%s\",\n' "$openbox_status"
    printf '  \"window_manager_i3\": \"%s\",\n' "$i3_status"
    printf '  \"window_manager_bspwm\": \"%s\",\n' "$bspwm_status"
    printf '  \"window_manager_awesome\": \"%s\",\n' "$awesome_status"
    printf '  \"window_manager_dwm\": \"%s\",\n' "$dwm_status"
    printf '  \"window_manager_qtile\": \"%s\",\n' "$qtile_status"
    printf '  \"window_manager_xfwm4\": \"%s\",\n' "$xfwm4_status"
    printf '  \"bls_fallback_applicable\": %s,\n' "$fallback_applicable_json"
    printf '  \"bls_fallback_status\": \"%s\",\n' "${fallback_status:-NOT_APPLICABLE}"
    printf '  \"bls_fallback_reason\": \"%s\",\n' "${fallback_reason:-}"
    printf '  \"bls_fallback_source_entry\": \"%s\",\n' "${fallback_source_name:-}"
    printf '  \"bls_fallback_target_entry\": \"%s\",\n' "${fallback_target_name:-}"
    printf '  \"accountsservice_present\": %s,\n' "$accountsservice_present_json"
    printf '  \"vfio_health\": \"%s\"\n' "$status"
    printf '}\n'
    return 0
  fi
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}${C_BOLD}==== Existing VFIO / Passthrough Detection Report ==== ${C_RESET}"
  else
    say "==== Existing VFIO / Passthrough Detection Report ===="
  fi
  if (( ENABLE_COLOR )); then
    print_kv "Kernel" "${C_GREEN}$(uname -r)${C_RESET}"
    print_kv "Current cmdline" "${C_DIM}$(cat /proc/cmdline 2>/dev/null || true)${C_RESET}"
    print_kv "Bootloader" "${C_GREEN}$(detect_bootloader)${C_RESET}"
    print_kv "openSUSE-like detection" "${C_GREEN}$(opensuse_like_detection_reason)${C_RESET}"
    if [[ "$dm_name" == "none" ]]; then
      print_kv "Display manager" "${C_YELLOW}NOT PRESENT${C_RESET} (none detected)"
    else
      print_kv "Display manager" "${C_GREEN}${dm_name}${C_RESET}"
    fi
    if [[ "$dm_name" == "lightdm" && "$dm_dep_status" == "NOT_WORK" ]]; then
      print_kv "Display manager health" "$(format_tri_state_status "$dm_dep_status") (LightDM detected; AccountsService missing)"
    else
      print_kv "Display manager health" "$(format_tri_state_status "$dm_dep_status")"
    fi
    print_kv "Graphics stack (Xorg)" "$(format_tri_state_status "$xorg_status")"
    print_kv "Graphics stack (Wayland)" "$(format_tri_state_status "$wayland_status")"
    print_kv "Graphics protocol support" "$(format_tri_state_status "$graphics_protocol_support")"
    print_kv "Graphics protocol mode" "$graphics_protocol_mode"
    print_kv "Window manager (Openbox)" "$(format_tri_state_status "$openbox_status")"
    print_kv "Window manager (i3)" "$(format_tri_state_status "$i3_status")"
    print_kv "Window manager (bspwm)" "$(format_tri_state_status "$bspwm_status")"
    print_kv "Window manager (awesome)" "$(format_tri_state_status "$awesome_status")"
    print_kv "Window manager (dwm)" "$(format_tri_state_status "$dwm_status")"
    print_kv "Window manager (qtile)" "$(format_tri_state_status "$qtile_status")"
    print_kv "Window manager (xfwm4)" "$(format_tri_state_status "$xfwm4_status")"
  else
    print_kv "Kernel" "$(uname -r)"
    print_kv "Current cmdline" "$(cat /proc/cmdline 2>/dev/null || true)"
    print_kv "Bootloader" "$(detect_bootloader)"
    print_kv "openSUSE-like detection" "$(opensuse_like_detection_reason)"
    if [[ "$dm_name" == "none" ]]; then
      print_kv "Display manager" "NOT PRESENT (none detected)"
    else
      print_kv "Display manager" "$dm_name"
    fi
    if [[ "$dm_name" == "lightdm" && "$dm_dep_status" == "NOT_WORK" ]]; then
      print_kv "Display manager health" "$(format_tri_state_status "$dm_dep_status") (LightDM detected; AccountsService missing)"
    else
      print_kv "Display manager health" "$(format_tri_state_status "$dm_dep_status")"
    fi
    print_kv "Graphics stack (Xorg)" "$(format_tri_state_status "$xorg_status")"
    print_kv "Graphics stack (Wayland)" "$(format_tri_state_status "$wayland_status")"
    print_kv "Graphics protocol support" "$(format_tri_state_status "$graphics_protocol_support")"
    print_kv "Graphics protocol mode" "$graphics_protocol_mode"
    print_kv "Window manager (Openbox)" "$(format_tri_state_status "$openbox_status")"
    print_kv "Window manager (i3)" "$(format_tri_state_status "$i3_status")"
    print_kv "Window manager (bspwm)" "$(format_tri_state_status "$bspwm_status")"
    print_kv "Window manager (awesome)" "$(format_tri_state_status "$awesome_status")"
    print_kv "Window manager (dwm)" "$(format_tri_state_status "$dwm_status")"
    print_kv "Window manager (qtile)" "$(format_tri_state_status "$qtile_status")"
    print_kv "Window manager (xfwm4)" "$(format_tri_state_status "$xfwm4_status")"
  fi

  # In detect mode, offer immediate remediation interactively.
  maybe_offer_detect_accountsservice_install
  maybe_offer_detect_user_audio_unit_guard_repair
  maybe_offer_detect_stale_user_audio_unit_cleanup
  # Health check
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- Health check --${C_RESET}"
  else
    say "-- Health check --"
  fi
  local hc
  hc="$(vfio_config_health)"
  local status
  status="$(printf '%s\n' "$hc" | awk -F= '/^STATUS=/{print $2; exit}')"
  if (( ENABLE_COLOR )); then
    case "${status:-UNKNOWN}" in
      OK)
        print_kv "Health" "${C_GREEN}${status}${C_RESET}"
        ;;
      WARN)
        print_kv "Health" "${C_YELLOW}${status}${C_RESET}"
        ;;
      BAD)
        print_kv "Health" "${C_RED}${status}${C_RESET}"
        ;;
      *)
        print_kv "Health" "${status:-UNKNOWN}"
        ;;
    esac
  else
    print_kv "Health" "${status:-UNKNOWN}"
  fi
  printf '%s\n' "$hc" | awk -F= '/^REASON=/{print "  - " $2}'

  # Our config
  if readable_file "$CONF_FILE"; then
    if (( ENABLE_COLOR )); then
      print_kv "Config" "${C_GREEN}$CONF_FILE (present)${C_RESET}"
    else
      print_kv "Config" "$CONF_FILE (present)"
    fi
    # shellcheck disable=SC1090
    . "$CONF_FILE"
    local configured_graphics_protocol configured_graphics_daemon_interval_effective configured_graphics_watchdog_retention_days_effective configured_graphics_watchdog_max_lines_effective
    configured_graphics_protocol="${GRAPHICS_PROTOCOL_MODE:-AUTO}"
    configured_graphics_protocol="${configured_graphics_protocol^^}"
    case "$configured_graphics_protocol" in
      X11|WAYLAND|AUTO) ;;
      *) configured_graphics_protocol="AUTO" ;;
    esac
    configured_graphics_daemon_interval_effective="$(graphics_daemon_interval_from_conf_or_default)"
    configured_graphics_watchdog_retention_days_effective="$(graphics_watchdog_retention_days_from_conf_or_default)"
    configured_graphics_watchdog_max_lines_effective="$(graphics_watchdog_max_lines_from_conf_or_default)"
    print_kv "Configured host GPU" "${HOST_GPU_BDF:-<unset>}"
    print_kv "Configured guest GPU" "${GUEST_GPU_BDF:-<unset>}"
    print_kv "Configured host audio" "${HOST_AUDIO_BDFS_CSV:-<unset>}"
    print_kv "Configured guest audio" "${GUEST_AUDIO_BDFS_CSV:-<unset>}"
    print_kv "Configured graphics protocol" "$configured_graphics_protocol"
    print_kv "Configured graphics daemon interval" "${configured_graphics_daemon_interval_effective}s"
    print_kv "Configured watchdog retention" "${configured_graphics_watchdog_retention_days_effective} day(s)"
    print_kv "Configured watchdog max lines" "$configured_graphics_watchdog_max_lines_effective"
    if [[ -n "${GUEST_GPU_BDF:-}" ]]; then
      local rebar_state above4g_state
      rebar_state="$(rebar_status_for_bdf "$GUEST_GPU_BDF")"
      above4g_state="$(above_4g_decoding_status_for_bdf "$GUEST_GPU_BDF")"
      if (( ENABLE_COLOR )); then
        print_kv "Guest GPU ReBAR" "${C_BLUE}${rebar_state}${C_RESET}"
        print_kv "Guest GPU Above 4G" "${C_BLUE}${above4g_state}${C_RESET}"
      else
        print_kv "Guest GPU ReBAR" "$rebar_state"
        print_kv "Guest GPU Above 4G" "$above4g_state"
      fi
    fi
  else
    if (( ENABLE_COLOR )); then
      print_kv "Config" "${C_RED}$CONF_FILE (missing)${C_RESET}"
    else
      print_kv "Config" "$CONF_FILE (missing)"
    fi
  fi

  # systemd unit
  if readable_file "$SYSTEMD_UNIT"; then
    if (( ENABLE_COLOR )); then
      print_kv "Systemd unit" "${C_GREEN}$SYSTEMD_UNIT (present)${C_RESET}"
    else
      print_kv "Systemd unit" "$SYSTEMD_UNIT (present)"
    fi
    if command -v systemctl >/dev/null 2>&1; then
      print_kv "Unit enabled" "$(systemctl is-enabled vfio-bind-selected-gpu.service 2>/dev/null || true)"
      print_kv "Unit active" "$(systemctl is-active vfio-bind-selected-gpu.service 2>/dev/null || true)"
      print_kv "Unit status" "$(systemctl show -p ExecStart vfio-bind-selected-gpu.service 2>/dev/null | sed 's/^ExecStart=//' || true)"
    fi
  else
    if (( ENABLE_COLOR )); then
      print_kv "Systemd unit" "${C_RED}$SYSTEMD_UNIT (missing)${C_RESET}"
    else
      print_kv "Systemd unit" "$SYSTEMD_UNIT (missing)"
    fi
  fi

  # modules-load
  if readable_file "$MODULES_LOAD"; then
    if (( ENABLE_COLOR )); then
      print_kv "Modules-load" "${C_GREEN}$MODULES_LOAD (present)${C_RESET}"
    else
      print_kv "Modules-load" "$MODULES_LOAD (present)"
    fi
    print_kv "Modules-load content" "$(tr '\n' ' ' <"$MODULES_LOAD" 2>/dev/null || true)"
  else
    if (( ENABLE_COLOR )); then
      print_kv "Modules-load" "${C_RED}$MODULES_LOAD (missing)${C_RESET}"
    else
      print_kv "Modules-load" "$MODULES_LOAD (missing)"
    fi
  fi

  # modprobe configs
  local hits=""
  if [[ -d /etc/modprobe.d ]]; then
    hits="$(grep -RIn --no-messages -E 'vfio-pci|vfio_pci|driver_override|blacklist (amdgpu|nouveau|nvidia|i915|radeon)' /etc/modprobe.d 2>/dev/null | head -n 50 || true)"
  fi
  if [[ -n "$hits" ]]; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}-- /etc/modprobe.d matches (first 50) --${C_RESET}"
    else
      say "-- /etc/modprobe.d matches (first 50) --"
    fi
    printf '%s\n' "$hits"
  else
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}-- /etc/modprobe.d matches --${C_RESET}"
    else
      say "-- /etc/modprobe.d matches --"
    fi
    say "  (none found)"
  fi

  # initramfs hints
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- initramfs tooling detected --${C_RESET}"
  else
    say "-- initramfs tooling detected --"
  fi
  if (( ENABLE_COLOR )); then
    local u_i m_i d_i
    u_i="$(command -v update-initramfs >/dev/null 2>&1 && echo yes || echo no)"
    m_i="$(command -v mkinitcpio >/dev/null 2>&1 && echo yes || echo no)"
    d_i="$(command -v dracut >/dev/null 2>&1 && echo yes || echo no)"

    [[ "$u_i" == yes ]] && u_i="${C_GREEN}yes${C_RESET}" || u_i="${C_RED}no${C_RESET}"
    [[ "$m_i" == yes ]] && m_i="${C_GREEN}yes${C_RESET}" || m_i="${C_RED}no${C_RESET}"
    [[ "$d_i" == yes ]] && d_i="${C_GREEN}yes${C_RESET}" || d_i="${C_RED}no${C_RESET}"

    print_kv "update-initramfs" "$u_i"
    print_kv "mkinitcpio" "$m_i"
    print_kv "dracut" "$d_i"
  else
    print_kv "update-initramfs" "$(command -v update-initramfs >/dev/null 2>&1 && echo yes || echo no)"
    print_kv "mkinitcpio" "$(command -v mkinitcpio >/dev/null 2>&1 && echo yes || echo no)"
    print_kv "dracut" "$(command -v dracut >/dev/null 2>&1 && echo yes || echo no)"
  fi
  if readable_file /etc/initramfs-tools/modules; then
    print_kv "/etc/initramfs-tools/modules" "present"
    print_kv "vfio in initramfs-tools/modules" "$(grep -nE '^(vfio|vfio_pci|vfio-iommu-type1|vfio_virqfd)' /etc/initramfs-tools/modules 2>/dev/null | tr '\n' ' ' || true)"
  fi
  if [[ -d /etc/dracut.conf.d ]]; then
    if (( ENABLE_COLOR )); then
      print_kv "/etc/dracut.conf.d" "${C_GREEN}present${C_RESET}"
    else
      print_kv "/etc.dracut.conf.d" "present"
    fi
    print_kv "vfio in dracut conf" "$(grep -RIn --no-messages -E 'vfio|vfio-pci|add_drivers|force_drivers' /etc/dracut.conf.d 2>/dev/null | head -n 20 | tr '\n' ' ' || true)"
  fi

  # vendor-reset module (only recommended when reset-failure markers are seen)
  if [[ -d /sys/module/vendor_reset ]]; then
    if (( ENABLE_COLOR )); then
      print_kv "vendor-reset" "${C_GREEN}Loaded${C_RESET}"
    else
      print_kv "vendor-reset" "Loaded"
    fi
  else
    if host_has_amd_gpu && amd_reset_issue_signatures_present; then
      if (( ENABLE_COLOR )); then
        print_kv "vendor-reset" "${C_YELLOW}MISSING (Recommended: reset-failure markers detected in logs)${C_RESET}"
      else
        print_kv "vendor-reset" "MISSING (Recommended: reset-failure markers detected in logs)"
      fi
    elif host_has_amd_gpu; then
      if (( ENABLE_COLOR )); then
        print_kv "vendor-reset" "${C_DIM}N/A (No AMD reset-failure markers detected in recent logs)${C_RESET}"
      else
        print_kv "vendor-reset" "N/A (No AMD reset-failure markers detected in recent logs)"
      fi
    else
      print_kv "vendor-reset" "Not loaded"
    fi
  fi
  # In detect mode, offer immediate vendor-reset remediation on AMD hosts.
  maybe_offer_detect_vendor_reset_install

  # GRUB defaults
  if readable_file /etc/default/grub; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}-- /etc/default/grub cmdline --${C_RESET}"
    else
      say "-- /etc/default/grub cmdline --"
    fi
    local key
    key="$(grub_get_key 2>/dev/null || true)"
    if [[ -n "$key" ]]; then
      print_kv "$key" "$(grub_read_cmdline "$key" 2>/dev/null || true)"
    else
      say "  Could not locate GRUB_CMDLINE_LINUX(_DEFAULT)"
    fi
  fi

  # BLS / systemd-boot entries (for openSUSE and other BLS users).
  # In full reports (e.g. --detect) we show ALL entries; in brief
  # reports (e.g. --verify) we skip this verbose listing and rely on
  # the dedicated current-entry check instead.
  if [[ -z "${VFIO_BRIEF_REPORT:-}" ]]; then
    local bls_dir
    bls_dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
    if [[ -n "$bls_dir" ]]; then
      say
      if (( ENABLE_COLOR )); then
        say "${C_CYAN}-- Boot Loader Spec entries (IOMMU/VFIO params) --${C_RESET}"
      else
        say "-- Boot Loader Spec entries (IOMMU/VFIO params) --"
      fi
      local f opts
      shopt -s nullglob
      for f in "$bls_dir"/*.conf; do
        opts="$(grep -m1 -E '^options[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
        opts="$(trim "${opts:-}")"
        if [[ -z "$opts" ]]; then
          print_kv "$(basename "$f")" "<no options line>"
          continue
        fi

        local -a missing=()
        if ! grep -qwE 'amd_iommu=on|intel_iommu=on' <<<"$opts"; then
          missing+=("iommu_on")
        fi
        if ! grep -qw "iommu=pt" <<<"$opts"; then
          missing+=("iommu_pt")
        fi
        # On openSUSE dracut systems, rd.driver.pre=vfio-pci is highly
        # recommended, so we flag its absence separately.
        if is_opensuse_like && command -v dracut >/dev/null 2>&1; then
          if ! grep -qw "rd.driver.pre=vfio-pci" <<<"$opts"; then
            missing+=("rd.driver.pre=vfio-pci")
          fi
        fi

        if (( ${#missing[@]} == 0 )); then
          print_kv "$(basename "$f")" "OK (IOMMU + VFIO params present)"
        else
          print_kv "$(basename "$f")" "WARN missing: ${missing[*]}"
        fi
      done
      shopt -u nullglob
    fi
  fi
  # openSUSE-specific BLS fallback recommendation/remediation path.
  maybe_offer_detect_fallback_entry_create

  # Current device bindings
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- Current GPU/Audio bindings (lspci -nnk) --${C_RESET}"
  else
    say "-- Current GPU/Audio bindings (lspci -nnk) --"
  fi
  if command -v lspci >/dev/null 2>&1; then
    lspci -Dnn | awk '/(VGA compatible controller|3D controller|Display controller|Audio device)/ {print $1}' | while read -r bdf; do
      [[ -n "$bdf" ]] || continue
      # Only show AMD/NVIDIA/Intel GPUs + audio
      if lspci -Dnn -s "$bdf" | grep -Eq 'Advanced Micro Devices|AMD/ATI|NVIDIA|Intel|Audio device'; then
        if (( ENABLE_COLOR )); then
          printf '%s\n' "${C_GREEN}  $bdf${C_RESET}"
          lspci -Dnnk -s "$bdf" 2>/dev/null | sed '1d;s/^/  /'
        else
          printf '%s\n' "$(lspci -Dnnk -s "$bdf" 2>/dev/null | sed 's/^/  /')"
        fi
      fi
    done
  fi

  # GPU binding mode + libvirt hook detection (common VFIO stage)
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- GPU binding mode + libvirt hook detection --${C_RESET}"
  else
    say "-- GPU binding mode + libvirt hook detection --"
  fi
  local _detect_binding_mode="early"
  if readable_file "$CONF_FILE"; then
    _detect_binding_mode="$(awk -F= '/^VFIO_BINDING_MODE=/{gsub(/"/,"",$2); print $2; exit}' "$CONF_FILE" 2>/dev/null || echo early)"
  fi
  _detect_binding_mode="${_detect_binding_mode:-early}"
  print_kv "Binding mode" "$_detect_binding_mode"
  if [[ -x "$LIBVIRT_HOOK_SCRIPT" ]]; then
    print_kv "Libvirt hook script" "present ($LIBVIRT_HOOK_SCRIPT)"
  else
    print_kv "Libvirt hook script" "missing"
  fi
  if [[ -f "$LIBVIRT_HOOK_ENTRY" ]]; then
    print_kv "Libvirt qemu entry" "present ($LIBVIRT_HOOK_ENTRY)"
  else
    print_kv "Libvirt qemu entry" "missing"
  fi
  if [[ -d /etc/libvirt/hooks ]]; then
    print_kv "/etc/libvirt/hooks" "present"
    print_kv "hook files" "$(find /etc/libvirt/hooks -maxdepth 1 -type f -printf '%f ' 2>/dev/null || true)"
  else
    print_kv "/etc/libvirt/hooks" "missing"
  fi
  # In detect mode, offer to switch to dynamic binding when AMD reset-bug
  # markers are present and the guest GPU is still on amdgpu with early binding.
  maybe_offer_detect_dynamic_binding
  report_vm_network_precheck || true

  # #4: stealth/perf VM tuning status for guest-GPU VMs (informational).
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- Stealth/perf VM tuning status --${C_RESET}"
  else
    say "-- Stealth/perf VM tuning status --"
  fi
  stealth_vm_tuning_status || true

  # R35: ultimate-performance VM tuning status for guest-GPU VMs (informational).
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- Ultimate-performance VM tuning status --${C_RESET}"
  else
    say "-- Ultimate-performance VM tuning status --"
  fi
  ultimate_perf_vm_tuning_status || true

  say "==== End report ===="
}

print_effective_config() {
  readable_file "$CONF_FILE" || die "Missing or unreadable config: $CONF_FILE"

  # shellcheck disable=SC1090
  . "$CONF_FILE"

  local guest_gpu host_gpu
  guest_gpu="${GUEST_GPU_BDF:-}"
  host_gpu="${HOST_GPU_BDF:-}"

  [[ -n "$guest_gpu" ]] || die "GUEST_GPU_BDF is missing in $CONF_FILE"

  local boot_vga_policy guest_boot_vga host_boot_vga
  local allow_boot_vga allow_boot_vga_if_host
  local host_assisted_default allow_boot_vga_bind
  local decision decision_reason

  boot_vga_policy="${VFIO_BOOT_VGA_POLICY:-STRICT}"
  boot_vga_policy="${boot_vga_policy^^}"
  case "$boot_vga_policy" in
    AUTO|STRICT) ;;
    *) boot_vga_policy="STRICT" ;;
  esac

  allow_boot_vga="${VFIO_ALLOW_BOOT_VGA:-0}"
  allow_boot_vga_if_host="${VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU:-0}"

  guest_boot_vga="$(pci_boot_vga_flag "$guest_gpu")"
  host_boot_vga="n/a"
  if [[ -n "$host_gpu" ]]; then
    host_boot_vga="$(pci_boot_vga_flag "$host_gpu")"
  fi
  host_assisted_default="$(host_assisted_boot_vga_policy_default "$host_gpu" "$guest_gpu")"

  allow_boot_vga_bind=1
  decision_reason="guest_not_boot_vga_or_force_enabled"
  if [[ "$guest_boot_vga" == "1" ]] && [[ "$allow_boot_vga" != "1" ]]; then
    allow_boot_vga_bind=0
    decision_reason="boot_vga_guard"
    if [[ "$host_assisted_default" == "1" ]]; then
      if [[ "$allow_boot_vga_if_host" == "1" ]]; then
        allow_boot_vga_bind=1
        decision_reason="explicit_opt_in"
      fi
      if [[ "$boot_vga_policy" == "AUTO" ]]; then
        allow_boot_vga_bind=1
        decision_reason="auto_detect"
      fi
      if [[ "$allow_boot_vga_bind" != "1" ]]; then
        decision_reason="host_assisted_available_but_not_enabled"
      fi
    else
      decision_reason="no_host_assisted_topology"
    fi
  fi

  if [[ "$allow_boot_vga_bind" == "1" ]]; then
    decision="ALLOW_BIND"
  else
    decision="SKIP_BIND"
  fi

  say
  hdr "Effective Boot-VGA Policy Report"
  print_kv "Config file" "$CONF_FILE"
  print_kv "Host GPU BDF" "${host_gpu:-<unset>}"
  print_kv "Guest GPU BDF" "$guest_gpu"
  print_kv "Guest boot_vga" "$guest_boot_vga"
  print_kv "Host boot_vga" "$host_boot_vga"
  print_kv "Host-assisted topology" "$host_assisted_default"
  print_kv "VFIO_BOOT_VGA_POLICY" "$boot_vga_policy"
  print_kv "VFIO_ALLOW_BOOT_VGA" "$allow_boot_vga"
  print_kv "VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU" "$allow_boot_vga_if_host"
  print_kv "Effective decision" "$decision"
  print_kv "Decision reason" "$decision_reason"

  if [[ "$decision" == "ALLOW_BIND" ]]; then
    note "Result: bind helper would proceed with vfio-pci binding for this boot."
  else
    note "Result: bind helper would skip vfio-pci binding for this boot."
  fi
}

require_root() {
  if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
    if command -v sudo >/dev/null 2>&1; then
      exec sudo -E "$0" "$@"
    fi
    die "Run as root (or install sudo)."
  fi
}

require_systemd() {
  if [[ ! -d /run/systemd/system ]]; then
    say "This helper only supports systems running systemd as PID 1."
    say "Other init systems (for example OpenRC, runit, sysvinit, s6, etc.) are NOT supported."
    die "systemd not detected (/run/systemd/system missing)."
  fi
  need_cmd systemctl
}
require_writable_root_or_die() {
  # Install/reset/disable modes must be able to write system state.
  # openSUSE snapshot boots can be read-only (e.g. /.snapshots/*/snapshot),
  # which would make deployment silently fail later.
  (( DRY_RUN )) && return 0

  local marker="/etc/.vfio-write-test.$$"
  if ! : >"$marker" 2>/dev/null; then
    local cmdline rootflags msg
    cmdline="$(cat /proc/cmdline 2>/dev/null || true)"
    rootflags="$(sed -nE 's/.*rootflags=([^ ]+).*/\1/p' <<<"$cmdline")"
    msg="Root filesystem appears read-only (cannot write to /etc)."
    if [[ -n "$rootflags" ]]; then
      msg+=" Current rootflags=${rootflags}."
    fi
    msg+=" Boot a writable subvolume/snapshot and rerun."
    die "$msg"
  fi
  rm -f "$marker" || true
}

backup_file() {
  local f="$1"
  [[ -f "$f" ]] || return 0

  # Only back up a given file once per run.
  if [[ -n "${BACKUP_MAP[$f]:-}" ]]; then
    return 0
  fi

  local bak
  bak="${f}.bak.${RUN_TS}"

  BACKUP_MAP[$f]="$bak"
  BACKUP_ENTRIES+=("$f::$bak")

  if (( DRY_RUN )); then
    return 0
  fi

  cp -a "$f" "$bak"
}

trim() {
  local s="$1"
  # shellcheck disable=SC2001
  s="$(echo "$s" | sed -e 's/^[[:space:]]\+//' -e 's/[[:space:]]\+$//')"
  printf '%s' "$s"
}

vendor_name() {
  case "${1,,}" in
    1002) echo "AMD";;
    10de) echo "NVIDIA";;
    8086) echo "Intel";;
    *) echo "vendor:$1";;
  esac
}

vendor_label() {
  # Prints vendor name, optionally colorized.
  local vid="${1,,}"
  local name
  name="$(vendor_name "$vid")"

  if (( ! ENABLE_COLOR )); then
    echo "$name"
    return 0
  fi

  case "$vid" in
    1002) echo "${C_BOLD}${C_RED}${name}${C_RESET}";;   # AMD = red
    10de) echo "${C_BOLD}${C_GREEN}${name}${C_RESET}";; # NVIDIA = green
    8086) echo "${C_BOLD}${C_BLUE}${name}${C_RESET}";;  # Intel = blue
    *) echo "${C_BOLD}${name}${C_RESET}";;
  esac
}

hdr() {
  # Header line for steps.
  local title="$1"
  if (( ENABLE_COLOR )); then
    say "${C_BOLD}${C_CYAN}==== ${title} ====${C_RESET}"
  else
    say "==== ${title} ===="
  fi
}

note() {
  # Accept no arguments to emit a blank line.
  local msg="${1:-}"
  if (( ENABLE_COLOR )); then
    say "${C_DIM}${msg}${C_RESET}"
  else
    say "$msg"
  fi
}

short_gpu_desc() {
  # Make lspci GPU description shorter for menus.
  # Keep model info, drop trailing [vvvv:dddd] and (rev ..) when present.
  local d="$1"
  d="$(echo "$d" | sed -E 's/^Advanced Micro Devices, Inc\. \[[^]]+\] //; s/^NVIDIA Corporation //; s/^Intel Corporation //')"
  d="$(echo "$d" | sed -E 's/ \[[0-9a-f]{4}:[0-9a-f]{4}\].*$//; s/ \(rev [^)]+\)$//')"
  printf '%s' "$(trim "$d")"
}

short_audio_desc() {
  local d="$1"
  if grep -Eqi 'HDMI|DP' <<<"$d"; then
    echo "HDMI/DP Audio"
  elif grep -qi 'HD Audio' <<<"$d"; then
    echo "HD Audio"
  else
    echo "Audio"
  fi
}

select_from_list() {
  # select_from_list "Prompt" "Title" options...
  local prompt="$1"; local title="$2"; shift 2
  local -a options=("$@")
  local idx

  # TUI path: use whiptail if available. We keep zero-based indices by using
  # the index as the whiptail TAG and returning it directly.
  if (( HAS_TUI )); then
    local -a menu_args=()
    local i opt first_line
    for i in "${!options[@]}"; do
      opt="${options[$i]}"
      # Use the first line of the option as the menu label.
      first_line="${opt%%$'\n'*}"
      menu_args+=("$i" "$first_line")
    done

    local choice
    choice=$(whiptail --title "$title" --menu "$prompt" 20 75 10 "${menu_args[@]}" 3>&1 1>&2 2>&3) || die "Selection cancelled."
    # choice is already the zero-based index as a string.
    echo "$choice"
    return 0
  fi

  # Fallback: original plain-text menu on /dev/tty.
  # IMPORTANT: stdout is reserved for the return value (index). Print UI to tty/stderr.
  local in="/dev/stdin"
  local out="/dev/stderr"
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi

  while true; do
    printf '\n%s\n' "$prompt" >"$out"
    for i in "${!options[@]}"; do
      printf '  [%d] ' "$((i+1))" >"$out"
      # %b expands backslash escapes in the argument (useful if an option contains \n).
      printf '%b\n' "${options[$i]}" >"$out"
    done
    printf '\nEnter number: ' >"$out"

    read -r idx <"$in"

    [[ "$idx" =~ ^[0-9]+$ ]] || { printf 'Invalid number\n' >"$out"; continue; }
    (( idx >= 1 && idx <= ${#options[@]} )) || { printf 'Out of range\n' >"$out"; continue; }
    echo "$((idx-1))"
    return 0
  done
}

# ---------------- Discovery ----------------

# Helper to read sysfs values (strips leading 0x if present)
sysfs_read() {
  local bdf="$1" file="$2" val
  if [[ -r "/sys/bus/pci/devices/$bdf/$file" ]]; then
    read -r val <"/sys/bus/pci/devices/$bdf/$file"
    val="${val#0x}"
    echo "$val"
  else
    echo ""
  fi
}

# Sysfs-based GPU discovery (more robust than parsing lspci output)
gpu_discover_all_sysfs() {
  # Emits TSV per GPU:
  # GPU_BDF \t GPU_DESC \t VENDOR_ID \t DEVICE_ID \t AUDIO_BDFS(comma) \t AUDIO_DESCS(pipe)
  local dev_path bdf class vendor device desc slot
  local audio_bdfs audio_descs

  # CACHE: Run lspci once to speed up the loop
  local lspci_cache=""
  if have_cmd lspci; then
    lspci_cache="$(lspci -Dnn 2>/dev/null || true)"
  fi

  for dev_path in /sys/bus/pci/devices/*; do
    [[ -e "$dev_path" ]] || continue
    bdf="$(basename "$dev_path")"

    class="$(sysfs_read "$bdf" class)"
    [[ -n "$class" ]] || continue
    # High byte 0x03 = Display controller (VGA/3D/etc).
    local class_base="${class:0:2}"
    [[ "$class_base" == "03" ]] || continue

    vendor="$(sysfs_read "$bdf" vendor)"
    device="$(sysfs_read "$bdf" device)"

    desc=""
    if [[ -n "$lspci_cache" ]]; then
      # Grep from cache instead of running lspci again.
      desc="$(grep -F "$bdf" <<<"$lspci_cache" | head -n1 | sed 's/^[^]]*] *//')"
      desc="$(trim "$desc")"
    fi

    slot="${bdf%.*}"
    audio_bdfs=""
    audio_descs=""

    # Scan functions 1-7 in the same slot for High Definition Audio (class 0x0403xx).
    local func abdf aclass aclass_prefix adesc
    for func in 1 2 3 4 5 6 7; do
      abdf="${slot}.${func}"
      if [[ -d "/sys/bus/pci/devices/$abdf" ]]; then
        aclass="$(sysfs_read "$abdf" class)"
        [[ -n "$aclass" ]] || continue
        aclass_prefix="${aclass:0:4}"
        if [[ "$aclass_prefix" == "0403" ]]; then
          audio_bdfs+="${audio_bdfs:+,}$abdf"
          if [[ -n "$lspci_cache" ]]; then
            adesc="$(grep -F "$abdf" <<<"$lspci_cache" | head -n1 | sed 's/^[^]]*] *//')"
            adesc="$(trim "$adesc")"
          else
            adesc="Audio"
          fi
          audio_descs+="${audio_descs:+|}$adesc"
        fi
      fi
    done

    printf '%s\t%s\t%s\t%s\t%s\t%s\n' \
      "$bdf" "${desc:-Unknown}" "$vendor" "$device" "$audio_bdfs" "$audio_descs"
  done
}

audio_devices_discover_all() {
  # Emits TSV per audio device:
  # AUDIO_BDF \t AUDIO_DESC \t VENDOR_ID \t DEVICE_ID
  local line bdf desc ids vendor dev
  while IFS= read -r line; do
    bdf="$(awk '{print $1}' <<<"$line")"
    desc="$(cut -d']' -f2- <<<"$line" | sed 's/^: *//')"
    ids="$(grep -oE '\[[0-9a-f]{4}:[0-9a-f]{4}\]' <<<"$line" | head -n1 | tr -d '[]')"
    vendor="${ids%%:*}"
    dev="${ids##*:}"
    printf '%s\t%s\t%s\t%s\n' "$bdf" "$(trim "$desc")" "$vendor" "$dev"
  done < <(lspci -Dnn | awk '/Audio device/ {print}')
}

pipewire_sinks_discover() {
  # Emits TSV: SINK_ID \t NODE_NAME \t LABEL
  # Uses wpctl status + wpctl inspect.
  have_cmd wpctl || return 1

  # Silence PipeWire connection noise and handle "wpctl can't connect" gracefully.
  # Use a small timeout if available so we don't hang when PipeWire is unhappy.
  local status
  if have_cmd timeout; then
    status="$(timeout 2s wpctl_cmd status 2>/dev/null || true)"
  else
    status="$(wpctl_cmd status 2>/dev/null || true)"
  fi
  [[ -n "$status" ]] || return 1

  local -a ids=()
  mapfile -t ids < <(
    printf '%s\n' "$status" | awk '
      /Sinks:/{ins=1;next}
      /Sources:/{ins=0}
      ins{
        for(i=1;i<=NF;i++){
          if($i ~ /^[0-9]+\.$/){ gsub("\\.","",$i); print $i; break }
        }
      }
    '
  )

  local id
  for id in "${ids[@]}"; do
    local node_name label
    node_name="$(wpctl_cmd inspect "$id" 2>/dev/null | awk -F' = ' '/node\.name/{gsub(/"/,"",$2); print $2; exit}')"
    label="$(wpctl_cmd inspect "$id" 2>/dev/null | awk -F' = ' '
      /node\.description/{gsub(/"/,"",$2); print $2; exit}
      /device\.description/{gsub(/"/,"",$2); print $2; exit}
    ' | head -n1)"

    [[ -n "$node_name" ]] || continue
    label="${label:-$node_name}"
    printf '%s\t%s\t%s\n' "$id" "$node_name" "$label"
  done
}

# ---------------- Writes ----------------

# Return 0 if the core vfio-pci module is available for this kernel.
# This is used to avoid adding rd.driver.pre=vfio-pci on systems where
# the module is not built at all (which would otherwise cause dracut
# to emit "FATAL: Module vfio-pci not found" during early boot).
vfio_pci_available() {
  if command -v modinfo >/dev/null 2>&1; then
    modinfo vfio-pci >/dev/null 2>&1
    return $?
  fi
  # If modinfo is missing, be conservative and assume not available.
  return 1
}

# Discover which VFIO modules actually exist for the running kernel.
# This avoids asking Dracut or modules-load for modules that are not built
# (for example vfio_virqfd on some Fedora kernels).
discover_vfio_modules() {
  local -a want=(vfio vfio_pci vfio_iommu_type1 vfio_virqfd)
  local -a have=()
  local m

  if command -v modinfo >/dev/null 2>&1; then
    for m in "${want[@]}"; do
      if modinfo "$m" >/dev/null 2>&1; then
        have+=("$m")
      fi
    done
  else
    # Fallback: only the core three, which exist on all modern kernels using VFIO.
    have=(vfio vfio_pci vfio_iommu_type1)
  fi

  printf '%s\n' "${have[@]}"
}

# Idempotently merge any MISSING fixed-default conf keys into an existing
# $CONF_FILE, preserving all existing user-set values. The binding switchers
# (--install-dynamic-binding / --install-early-binding) only flip
# VFIO_BINDING_MODE via rewrite_conf_key; they never call write_conf (which
# needs full wizard context), so advanced keys added to write_conf in later
# releases never land in an older live conf. That drift left keys like
# VFIO_REBIND_VERIFY_TIMEOUT and VFIO_DYNAMIC_SOFT_FLR_ON_BIND absent from the
# live conf even after --install-dynamic-binding regenerated the bind script
# that reads them (they fell back to defaults, which is functional but not
# documented/tunable for the operator).
#
# This helper closes that gap: for each fixed-default KEY in write_conf's
# heredoc that is ABSENT from the live conf, append a short comment +
# KEY="default" at the end. It never edits or reorders existing lines, so a
# user's values and comments are untouched. It is safe to run repeatedly
# (idempotent: only adds keys that are missing). Computed/identity keys
# (HOST_GPU_BDF, GUEST_*, VFIO_BINDING_MODE, GRAPHICS_PROTOCOL_MODE,
# VFIO_GRAPHICS_DAEMON_INTERVAL, VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU,
# VFIO_BOOT_VGA_POLICY, HOST_AUDIO_*) are intentionally NOT merged here --
# those depend on wizard context / topology and are the wizard's job; merging
# a default for them would be wrong.
_sync_conf_defaults() {
  readable_file "$CONF_FILE" || return 0
  # Fixed-default keys -> default value. Keep this set in sync with the
  # write_conf() heredoc below. (A short comment is appended with each missing
  # key so the operator has a hint; the full WHY rationale lives in write_conf.)
  local -A _defs=(
    [VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS]="10"
    [VFIO_GRAPHICS_WATCHDOG_MAX_LINES]="5000"
    [VFIO_GRAPHICS_AUTO_X11_PINNING]="1"
    [VFIO_DYNAMIC_REBIND_HOST]="0"
    [VFIO_DYNAMIC_ALLOW_BOOT_VGA]="0"
    [VFIO_DYNAMIC_SOFT_FLR_ON_BIND]="0"
    [VFIO_DYNAMIC_COOLDOWN_SECONDS]="10"
    [VFIO_RESTORE_D3COLD_ON_RELEASE]="0"
    [VFIO_HOOK_BIND_TIMEOUT]="20"
    [VFIO_REBIND_VERIFY_TIMEOUT]="2"
    [VFIO_AMDGPU_READY_TIMEOUT]="5"
    [VFIO_DYNAMIC_FLR_BEFORE_REBIND]="0"
    [VFIO_DYNAMIC_SBR_BEFORE_REBIND]="0"
    [VFIO_REBOOT_FLR_MAX_GEN]=""
    [STEALTH_VM_BACKUP_DIR]=""
    [VFIO_DYNAMIC_PARK_KEEPALIVE]="1"
    [VFIO_DYNAMIC_PARK_KEEPALIVE_INTERVAL]="10"
    [VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS]="5"
    [VFIO_DYNAMIC_PARK_KEEPALIVE_BACKOFF_MAX]="300"
    [VFIO_DYNAMIC_PARK_KEEPALIVE_NOTIFY]="1"
    [VFIO_DYNAMIC_LIVE_ATTACH]="0"
    [VFIO_DYNAMIC_LIVE_ATTACH_DELAY]="30"
    [VFIO_DYNAMIC_LIVE_ATTACH_TIMEOUT]="60"
  )
  # VFIO_DYNAMIC_PCI_RESET is card-specific (not a fixed 0/1): default 1 for
  # RX 9070 / RDNA4 (Navi 48, device 7550) where the pre-bind FLR is needed to
  # survive VM shutdown, 0 for all other cards. Read the persisted device id
  # from the existing conf so the switcher syncs the right default without
  # needing the full wizard context.
  local _sync_dev_id
  _sync_dev_id="$(awk -F= '/^GUEST_GPU_DEVICE_ID=/{v=$2; gsub(/"/,"",v); gsub(/^0x/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -n "$_sync_dev_id" && "${_sync_dev_id,,}" == "7550" ]]; then
    _defs[VFIO_DYNAMIC_PCI_RESET]="1"
  else
    _defs[VFIO_DYNAMIC_PCI_RESET]="0"
  fi
  local _added=0 _k _val _tmp
  _tmp="$(mktemp)"
  # Copy the existing conf verbatim into the temp, then append any missing
  # fixed-default keys at the end with a short comment.
  cat "$CONF_FILE" >"$_tmp"
  for _k in "${!_defs[@]}"; do
    # Present? (match the key at start of a line).
    if grep -Eq "^${_k}=" "$_tmp" 2>/dev/null; then
      continue
    fi
    _val="${_defs[$_k]}"
    if (( _added == 0 )); then
      printf '\n# --- Synced defaults (added by %s on %s; see write_conf for full rationale) ---\n' \
        "$SCRIPT_NAME" "$(date -Is)" >>"$_tmp"
    fi
    printf '# %s (default; tune here): advanced dynamic-binding/park-keepalive knob.\n' "$_k" >>"$_tmp"
    printf '%s="%s"\n' "$_k" "$_val" >>"$_tmp"
    _added=$((_added+1))
  done
  if (( _added > 0 )); then
    if (( DRY_RUN )); then
      rm -f "$_tmp" 2>/dev/null || true
      note "DRY-RUN: would add $_added missing fixed-default conf key(s) to $CONF_FILE"
      return 0
    fi
    install -o root -g root -m 0644 "$_tmp" "$CONF_FILE" 2>/dev/null || cp -f "$_tmp" "$CONF_FILE"
    rm -f "$_tmp" 2>/dev/null || true
    if (( ENABLE_COLOR )); then
      say "  ${C_GREEN}✔${C_RESET} Synced $_added missing default conf key(s) into $(_link "$CONF_FILE")"
    else
      say "  ✔ Synced $_added missing default conf key(s) into $CONF_FILE"
    fi
  else
    rm -f "$_tmp" 2>/dev/null || true
  fi
  return 0
}

write_conf() {
  local host_gpu="$1"
  local host_audio_bdfs_csv="$2"
  local host_audio_node_name="$3"
  local guest_gpu="$4"
  local guest_audio_bdfs_csv="$5"
  local guest_vendor="$6"
  local graphics_protocol_mode="${7:-AUTO}"
  local boot_vga_policy_mode="${8:-${BOOT_VGA_POLICY_OVERRIDE:-AUTO}}"
  local graphics_daemon_interval="${9:-${GRAPHICS_DAEMON_INTERVAL_OVERRIDE:-$GRAPHICS_DAEMON_INTERVAL_DEFAULT}}"
  local binding_mode="${10:-${BINDING_MODE_OVERRIDE:-early}}"
  local boot_vga_host_assisted_default="0"
  graphics_protocol_mode="${graphics_protocol_mode^^}"
  if [[ "$graphics_protocol_mode" != "X11" && "$graphics_protocol_mode" != "WAYLAND" ]]; then
    graphics_protocol_mode="AUTO"
  fi
  boot_vga_policy_mode="${boot_vga_policy_mode^^}"
  case "$boot_vga_policy_mode" in
    AUTO|STRICT) ;;
    *) boot_vga_policy_mode="AUTO" ;;
  esac
  if [[ ! "$graphics_daemon_interval" =~ ^[0-9]+$ ]] || (( 10#$graphics_daemon_interval < 1 || 10#$graphics_daemon_interval > 3600 )); then
    graphics_daemon_interval="$GRAPHICS_DAEMON_INTERVAL_DEFAULT"
  fi
  binding_mode="${binding_mode^^}"
  case "$binding_mode" in
    EARLY|DYNAMIC) ;;
    *) binding_mode="early" ;;
  esac

  boot_vga_host_assisted_default="$(host_assisted_boot_vga_policy_default "$host_gpu" "$guest_gpu")"

  # Persist the guest GPU device id so _is_guest_rx9070_family can detect a
  # Navi 48 (device 7550) card DURABLY -- even when the card is dead / off the
  # bus at standalone-switcher time (sysfs/lspci return nothing then, so the
  # runtime fallback in the helper cannot fire). Read from sysfs here (the
  # wizard runs while the card is alive). Empty if unreadable; the helper
  # falls back to CTX[guest_vfio_ids] / sysfs / lspci then.
  local guest_device=""
  if [[ -n "$guest_gpu" && -r "/sys/bus/pci/devices/$guest_gpu/device" ]]; then
    guest_device="$(cat "/sys/bus/pci/devices/$guest_gpu/device" 2>/dev/null || true)"
    guest_device="${guest_device#0x}"
  fi

  # RX 9070 / RDNA4 (Navi 48, device 7550) needs a pre-bind function-level
  # reset on the cold-start path (amdgpu -> vfio-pci): without it the card
  # carries amdgpu's residual state into qemu and dies on the detach reset at
  # VM shutdown (observed on Fedora: card survives attach but goes zombie on
  # release). With the FLR (Gen1 downtrain + reset + adaptive link restore)
  # the card enters qemu in a clean state and survives the full session
  # (confirmed on openSUSE where this was default=1). Other cards do NOT need
  # it and a reset on a healthy non-Navi-48 card is unnecessary / potentially
  # harmful, so the default is card-specific: 1 for Navi 48, 0 for everything
  # else. The operator can still override via the conf key.
  local pci_reset_default="0"
  if [[ -n "$guest_device" && "${guest_device,,}" == "7550" ]]; then
    pci_reset_default="1"
  fi

  backup_file "$CONF_FILE"

  write_file_atomic "$CONF_FILE" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
#
# IMPORTANT:
# - Use PCI addresses (BDF) to avoid accidentally binding the wrong device when IDs repeat.
#   Example: both AMD HDMI audio controllers can share the same PCI ID (1002:ab28).
#
# Debug tips:
# - Verify bind status:
#     lspci -nnk -s <BDF>
# - Verify IOMMU groups:
#     find /sys/kernel/iommu_groups -type l | grep <BDF>

HOST_GPU_BDF="$host_gpu"
# Boot-VGA safety policy:
# - 1 allows host-assisted binding when guest GPU is Boot VGA AND host GPU is a different adapter with boot_vga=0.
# - 0 keeps Boot-VGA skip behavior unless fully forced via VFIO_ALLOW_BOOT_VGA=1.
VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU="$boot_vga_host_assisted_default"
# Boot-VGA host-assisted policy mode:
# - AUTO: dynamically allows host-assisted Boot-VGA bind when runtime topology is safe
#         (guest boot_vga=1, host boot_vga=0, different GPUs), and skips otherwise.
# - STRICT: requires explicit VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1.
VFIO_BOOT_VGA_POLICY="$boot_vga_policy_mode"
HOST_AUDIO_BDFS_CSV="$host_audio_bdfs_csv"
HOST_AUDIO_NODE_NAME="$host_audio_node_name"

GUEST_GPU_BDF="$guest_gpu"
GUEST_AUDIO_BDFS_CSV="$guest_audio_bdfs_csv"
GUEST_GPU_VENDOR_ID="$guest_vendor"
# Guest GPU PCI device id (e.g. 7550 for RX 9070 / RDNA4 Navi 48). Persisted
# at wizard time so the Navi 48 disable_idle_d3 gate works without a live card.
GUEST_GPU_DEVICE_ID="$guest_device"
GRAPHICS_PROTOCOL_MODE="$graphics_protocol_mode"
VFIO_GRAPHICS_DAEMON_INTERVAL="$graphics_daemon_interval"
# Watchdog log retention and growth controls for vfio-graphics-protocold:
# - retention days is best-effort timestamp pruning window.
# - max lines is a hard cap after pruning to prevent unbounded growth.
VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS="10"
VFIO_GRAPHICS_WATCHDOG_MAX_LINES="5000"
# AUTO-mode X11 pinning policy:
# - 1 (default): allow X11 host-GPU pinning in AUTO mode for pre-login X11
#                display managers (for example SDDM/LightDM) and active X11 sessions.
#                This avoids \"no screens found\" failures when the guest GPU is
#                already bound to vfio-pci before the display manager starts.
# - 0: keep AUTO conservative for active user sessions; pre-login safety pinning
#      for X11 display managers still applies.
VFIO_GRAPHICS_AUTO_X11_PINNING="1"
# GPU binding strategy:
# - early (default): force the guest GPU onto vfio-pci at boot via vfio-pci.ids /
#   rd.driver.pre=vfio-pci / the vfio-bind-selected-gpu.service systemd unit.
# - dynamic: let amdgpu load first; a libvirt qemu hook switches the guest GPU to
#   vfio-pci only when a VM that has the GPU attached is started. More reliable for
#   RX 9070 / RDNA4 cards that hit the "Unknown PCI header type 127" reset bug when
#   bound to vfio-pci too early. Requires libvirt-managed VMs.
# WHY this value: set by the wizard (or --install-dynamic-binding / --binding-mode).
# dynamic is recommended for RX 9070 / RDNA4 to avoid the reset bug; early works for
# raw qemu and older AMD cards that bind cleanly at boot.
VFIO_BINDING_MODE="$binding_mode"
# Dynamic-mode post-VM-stop behavior:
# - 0 (default): leave the guest GPU on vfio-pci after the VM stops (safer for the
#   RX 9070 reset bug; the host cannot use the GPU between VM sessions without reboot
#   or a manual rebind).
# - 1: rebind the guest GPU back to its normal host driver (amdgpu/snd) on VM stop.
#   reprobe_to_host now binds DIRECTLY to the remembered pre-vfio-pci host driver
#   via /sys/bus/pci/drivers/<prev>/bind (a different kernel code path than the
#   generic /sys/bus/pci/drivers_probe re-probe, which SEGFAULTS on Navi 48 /
#   RX 9070 after vfio-pci), falling back to drivers_probe only if no prior
#   driver was remembered. So REBIND_HOST=1 is now safer on RX 9070 than before.
# WHY this value: 0 keeps the RX 9070 parked on vfio-pci so it cannot fall off the
# bus on a D3cold exit between sessions. Set 1 only on cards that have NEVER hit
# the reset bug AND where you want the host to reuse the GPU between VM runs.
VFIO_DYNAMIC_REBIND_HOST="0"
# Dynamic-mode Boot-VGA safety for --bind-now (libvirt hook):
# - 0 (default): if the guest GPU is Boot VGA, refuse to bind it at VM start
#   UNLESS a host-assisted dual-GPU topology is detected (a different HOST_GPU_BDF
#   with boot_vga=0). Host-assisted is honored when VFIO_BOOT_VGA_POLICY=AUTO
#   (default) or VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1, mirroring the early-binding
#   boot_vga_guard() so dynamic and early paths treat this topology the same way.
#   In a true single-GPU topology (no host GPU / host GPU also boot_vga=1) the hook
#   aborts the VM start cleanly so the host display stays alive.
# - 1: allow binding a Boot-VGA guest GPU at VM start unconditionally (advanced
#   single-GPU/headless setups where losing the host display during the VM session
#   is intentional).
# WHY this value: 0 protects single-GPU/headless-style setups from a mid-session
# black screen while still allowing the normal dual-GPU passthrough case (host
# display on a second GPU). Set 1 only if you intentionally pass your only GPU to
# the VM and do not need the host display while the VM runs.
VFIO_DYNAMIC_ALLOW_BOOT_VGA="0"
# Dynamic-mode optional PCI function-level reset before bind (advanced):
# - 0: do NOT reset the device before binding. A reset on a healthy non-Navi-48
#   card is unnecessary, and on a mid-reset card it can worsen the state.
# - 1: after unbind and before the vfio-pci bind, attempt writing 1 to
#   /sys/bus/pci/devices/<BDF>/reset (only if the sysfs reset file is writable).
#   On RX 9070 / RDNA4 (Navi 48) this clears residual amdgpu state so the card
#   enters qemu in a clean state and survives the detach reset at VM shutdown
#   (without it the card goes zombie on release — observed on Fedora where this
#   was default=0). The reset is gated to the RX 9070 family via the Gen1
#   downtrain + adaptive link restore, so it retrains reliably.
# WHY this value: auto-detected at wizard time — 1 for RX 9070 / RDNA4 (Navi 48,
# device 7550) where it is needed to survive VM shutdown; 0 for all other cards
# where it is unnecessary and potentially harmful. Override here if needed.
VFIO_DYNAMIC_PCI_RESET="$pci_reset_default"
# Dynamic-mode soft FLR on the alive-parked bind path (advanced):
# - 0 (default): when --bind-now finds the guest GPU already on vfio-pci AND alive
#   (the normal shutdown->start case), do NOT do a soft function-level reset +
#   unbind + rebind. The vBIOS file pin (<rom file=.../>, installed by
#   install_vbios_romfile) lets qemu read the GOP ROM from the FILE, so the soft
#   FLR (originally added to clear the live ROM BAR 0xffff) is no longer needed.
#   AND the soft FLR + rebind destabilizes the RX 9070 / RDNA4: the card passes
#   the alive-check right after the rebind but falls off the bus ~3s later
#   (config space -> ff ff ff ff), so qemu's vfio-pci attach hits a dead card
#   ("Unable to power on device, stuck in D3") -> no OVMF/BIOS logo, black until
#   Windows re-initializes the display. Skipping the FLR keeps the card alive so
#   qemu attaches a live card and OVMF POSTs from the file-pinned ROM.
# - 1: opt back into the soft FLR + unbind + rebind on the alive-parked path. Only
#   use this if you have NO vBIOS file pin AND you hit the live-ROM 0xffff on
#   shutdown->start. With a file pin this is never needed and is harmful on RX 9070.
# WHY this value: 0 is correct for any setup with the vBIOS file pin (the default
# after --install-dynamic-binding --vbios). Set 1 ONLY for the no-file-pin +
# live-ROM-0xffff edge case; otherwise leave at 0 to avoid the reset-bug zombie.
VFIO_DYNAMIC_SOFT_FLR_ON_BIND="0"
# Dynamic-mode rapid stop/start cooldown (seconds, read by the bind script at VM start):
# - 0: disable the cooldown (--bind-now proceeds immediately even right after a VM stop).
# - N>0 (default 10): when the libvirt hook calls --bind-now within N seconds of the
#   last --release (VM stop), ACTIVELY probe the guest GPU's liveness (vendor sysfs +
#   live config space) instead of binding immediately. It polls until the card is
#   alive OR the cooldown window expires. A card that recovers early proceeds
#   immediately (no need to wait the full N seconds); a card that is still dead after
#   the window fails with an actionable "card needs a host reboot" message so libvirt
#   aborts the VM start cleanly. This is the PROACTIVE complement to the alive-check:
#   it gives the card time to recover from a rapid stop/start D3cold exit, and only
#   fails if it does NOT recover. Keep N below VFIO_HOOK_BIND_TIMEOUT (default 20).
# WHY this value: 10s is enough for the card to settle out of D3cold and for amdgpu /
# vfio-pci teardown to finish, yet short enough not to get in the way of a normal
# (non-rapid) restart and well under the 20s hook timeout. The alive-check still
# catches a dead card if the cooldown is disabled or the card dies for another
# reason. Set 0 only if you never rapid-fire stop/start and find the probe gets in
# the way.
VFIO_DYNAMIC_COOLDOWN_SECONDS="10"
# Dynamic-mode d3cold_allowed restore on host rebind (advanced):
# - 0 (default): keep d3cold_allowed=0 after --release even when
#   VFIO_DYNAMIC_REBIND_HOST=1 rebinds the GPU to the host driver. The RX 9070 /
#   RDNA4 reset bug means D3cold exit can drop the card off the bus on the host
#   too, so D3cold stays disabled. Safer default.
# - 1: restore d3cold_allowed=1 when handing the card back to the host, for lower
#   host idle power between VM sessions. Only enable if you never hit the reset
#   bug on the host. This also restores power/control=auto so the host driver
#   can runtime-manage the card again (the default keeps power/control=on, i.e.
#   the card pinned in D0, to avoid both D3hot and D3cold reset-bug exits).
# WHY this value: 0 prevents the RX 9070 from dropping off the bus on a D3cold
# exit while the host owns it (and keeps it in D0 via power/control=on, also
# avoiding the D3hot "stuck in D3" wedge at the next VM start). Set 1 only if
# your card has NEVER hit the reset bug and you want lower host idle power
# between VM sessions (do NOT enable just because a guide suggests restoring
# D3cold — that reintroduces the reset bug).
VFIO_RESTORE_D3COLD_ON_RELEASE="0"
# Dynamic-mode libvirt-hook bind timeout (seconds, read by the hook at runtime):
# - default 20 leaves margin under libvirt's ~30s qemu hook timeout.
# - if the vfio-pci bind + verify takes longer than this, the hook aborts the VM
#   start (timeout returns 124) so a hung sysfs write cannot hang libvirt.
# - falls back to a plain call if 'timeout' (coreutils) is unavailable.
# WHY this value: 20s is well above any observed healthy bind (<2s) yet under the
# libvirt hook deadline, so a healthy VM start is never affected and only a truly
# hung bind is aborted. Lower it only if your hook deadline is shorter; raise it
# only if a legitimately slow bind keeps getting aborted (rare).
VFIO_HOOK_BIND_TIMEOUT="20"
# Dynamic-mode host-rebind verify timeout (seconds, read by reprobe_to_host at
# --release when VFIO_DYNAMIC_REBIND_HOST=1): after kicking
# /sys/bus/pci/drivers_probe to make amdgpu/snd re-grab the guest GPU, poll
# this long for the host driver to actually bind. The kernel re-probe is
# async, so without a settle+verify the next step can run on a still-unbound
# card (racing the probe) and a later segfault/hang is invisible. The poll is
# 0.2s ticks, so 2s = 10 ticks.
# WHY this value: 2s is enough for amdgpu to rebind on observed RX 9070
# hardware; raise it if your card is slow to re-probe, lower it if you want the
# release to return faster (the release-time remove+rescan recovery still
# catches a card that fell off regardless of this value).
VFIO_REBIND_VERIFY_TIMEOUT="2"
# Dynamic-mode amdgpu-readiness timeout (seconds, read by _wait_amdgpu_ready
# in the bind script): how long to wait for amdgpu to FINISH probing (DRM card
# node up) after a release rebind or before a --bind-now unbind. amdgpu's probe
# is ASYNC -- the driver symlink appears early but the DRM card appears at the
# END of probe. Unbinding amdgpu mid-probe can hang the kernel in D-state on
# Navi 48 / RX 9070 (observed: --bind-now D-stated 9s after a release rebind).
# The poll is 0.2s ticks, so 5s = 25 ticks. Keep this under VFIO_HOOK_BIND_TIMEOUT
# (default 20) so the readiness wait cannot hit the hook deadline.
# WHY this value: 5s is enough for amdgpu to finish probing on observed RX 9070
# hardware after a direct rebind; raise it if your card is slow to probe, lower
# it if you want the bind to proceed sooner (the bind proceeds anyway on
# timeout -- this is a best-effort settle gate, not a hard fail).
VFIO_AMDGPU_READY_TIMEOUT="5"
# Dynamic-mode opt-in soft FLR before the host-driver rebind at release
# (advanced, read by reprobe_to_host):
# - 0 (default): do NOT do a soft function-level reset before rebinding the
#   card to amdgpu/snd at --release. An FLR can itself destabilize some cards,
#   so it is opt-in.
# - 1: after unbind from vfio-pci + clear driver_override, do a soft FLR
#   (echo 1 > sys/reset, RX 9070 family gated Gen1-downtrain/restore) BEFORE
#   binding amdgpu. This resets the card to a clean state amdgpu expects, which
#   can help if the card is left in a bad state by vfio-pci and amdgpu's probe
#   then hangs/fails. Only enable if the rebind hangs without it.
# WHY this value: 0 avoids an unnecessary FLR on a card that rebinds cleanly.
# Set 1 only if REBIND_HOST=1's amdgpu rebind hangs or leaves the card dead.
VFIO_DYNAMIC_FLR_BEFORE_REBIND="0"
# Dynamic-mode opt-in Secondary Bus Reset before the host-driver rebind at
# release (advanced, read by reprobe_to_host, HEAVIER than the soft FLR above):
# - 0 (default): do NOT do an SBR before rebinding. An SBR pulses RST# on the
#   upstream switch port's secondary bus (setpci Bridge Control 0x3E bit 6),
#   hot-resetting the GPU AND every device behind the same upstream port (e.g.
#   the GPU's audio sibling) -- a heavier reset than the function-level FLR,
#   so it is opt-in.
# - 1: after unbind from vfio-pci + clear driver_override, do an SBR on the
#   upstream port BEFORE binding amdgpu. Resets more of the card's internal
#   state (PSP/MC, which the function-level FLR does not fully clear) so
#   amdgpu's probe can complete. Use this ONLY if REBIND_HOST=1's amdgpu rebind
#   still hangs (D-state / "amdgpu NOT ready after 5s") with the soft FLR
#   (VFIO_DYNAMIC_FLR_BEFORE_REBIND=1) enabled. Takes PRECEDENCE over the soft
#   FLR when both are set (it supersedes the FLR). GPU BDF only -- one SBR
#   resets the audio sibling too, so it runs once on the GPU iteration.
# WHY this value: 0 avoids an unnecessary heavy bus reset (and a sibling-device
# reset) on a card that rebinds cleanly. Set 1 only if the soft FLR did not fix
# the amdgpu rebind hang (the 2b/4 FLR is always the first thing to try).
VFIO_DYNAMIC_SBR_BEFORE_REBIND="0"
# Optional max PCIe generation cap for the post-reset adaptive link restore.
# Originally introduced for the reboot-FLR monitor (guest warm reboot), but now
# shared by EVERY RX 9070 family PCIe Gen1-downtrain/adaptive-restore recovery
# path in this script: the reboot-FLR soft FLR, the bind script's remove+rescan
# and function-level-reset recovery (--release / --bind-now / bind_one), and
# the park-keepalive monitor's remove+rescan and rescan-only recovery. All of
# them normally target the hardware's detected link capability (Gen5 on Gen5
# boards, Gen4 on slower slots). On boards that reliably retrain at a lower gen
# but NOT the card's full capability after a reset, set this to clamp the
# restore target so none of these recovery paths keep failing up to the higher
# gen and falling back every time.
# - empty (default): no cap; restore targets the detected capability.
# - 1..6: clamp the restore target to at most this generation.
# WHY this value: empty lets the adaptive logic pick the best gen per hardware.
# Set 4 (for example) only if your board reliably retrains Gen4 but not Gen5
# after a reset and you want every recovery path to skip the Gen5 attempt.
VFIO_REBOOT_FLR_MAX_GEN=""
# Stealth/perf VM tuning backup directory for *_stealth_*.xml VM XML backups
# (read by install_stealth_vm_tuning / reset_stealth_vm_tuning). Default empty
# = $HOME/Desktop; falls back to /var/lib/vfio-stealth-vm/backups if not writable.
STEALTH_VM_BACKUP_DIR=""
# Ultimate-performance VM tuning backup directory for *_perf_*.xml VM XML backups
# (read by install_ultimate_perf_vm_tuning / reset_ultimate_perf_vm_tuning). Default
# empty = $HOME/Desktop; falls back to /var/lib/vfio-perf-vm/backups if not writable.
# Separate from STEALTH_VM_BACKUP_DIR so the two layers' backups do not collide.
ULTIMATE_PERF_VM_BACKUP_DIR=""
# Ultimate-performance VM tuning: opt-in host hugepages reservation. When the
# perf tuner runs, it prompts (default N) whether to reserve host hugepages and
# add <memoryBacking><hugepages> to each tuned VM. This key forces the choice so
# a non-interactive re-run skips the prompt: 1 = reserve + add memoryBacking,
# 0 = skip (all other perf knobs still apply). Default empty = prompt.
# WHY this value: empty keeps hugepages opt-in so a plain run never touches host
# RAM (nr_hugepages). Set 1 only if you want hugepages every time without asking.
ULTIMATE_PERF_HUGEPAGES=""
# Hugepage size in KiB for ULTIMATE_PERF_HUGEPAGES (read by the perf tuner, and
# written to the libvirt XML <page size=... unit='KiB'/> — KiB is libvirt's
# standard unit for hugepage size). 2048 = 2048 KiB = 2 MiB = the standard 2MB
# hugepage (default, widely available, controlled by /proc/sys/vm/nr_hugepages);
# 1048576 = 1048576 KiB = 1 GiB = 1GB pages (needs the kernel hugepagesz=1G boot
# param + a supporting CPU; CANNOT be reserved at runtime so the tuner skips it
# and warns). The tuner computes the page count from each VM's <memory> (KiB)
# and reserves that many host pages.
ULTIMATE_PERF_HUGEPAGES_SIZE="2048"
# Ultimate-performance VM tuning: opt-in SATA->virtio-blk disk-bus conversion
# (read by the perf tuner). The disk perf knobs (cache=none/io=native/
# discard=unmap + multiqueue + iothread) only apply to virtio/scsi disks, so a
# SATA boot disk gets NONE of them. This converts each non-cdrom disk whose bus
# is not virtio/scsi to bus=virtio (sdX->vdX, drive address dropped so libvirt
# reassigns PCI on define), THEN applies the perf knobs. DANGEROUS: Windows
# needs the viostor (virtio-blk) driver installed first or it BSODs with
# INACCESSIBLE_BOOT_DEVICE on the next boot. 1=convert, 0=skip (default).
# WHY this value: empty keeps it opt-in so a plain run never changes the disk
# bus. Set 1 only AFTER you have installed virtio-win-guest-tools in Windows.
ULTIMATE_PERF_VIRTIO_DISK=""
# Dynamic-mode park-keepalive monitor (read by vfio-gpu-park-keepalive.sh):
# - 1 (default, instant on): while the guest GPU is parked on vfio-pci between
#   VM sessions (VFIO_DYNAMIC_REBIND_HOST=0), periodically probe whether it is
#   still alive and proactively run the remove+rescan bus recovery if it has
#   died (RX 9070 / RDNA4 reset bug). This is the PROACTIVE complement to the
#   reactive recovery already run at --release time: it catches a card that
#   dies while sitting parked, before the next VM start.
# - 0: disable the periodic keepalive probe (rely only on the release-time and
#   bind-time recovery attempts).
VFIO_DYNAMIC_PARK_KEEPALIVE="1"
# Park-keepalive probe interval in seconds (read by vfio-gpu-park-keepalive.sh).
# WHY this value: 10s catches a dead card well before the next VM start on a
# typical workflow, while staying cheap enough (a couple of sysfs reads + a
# virsh ownership check) not to matter even while a VM is actively running.
# Floor is 5s (values below 5, or non-numeric, fall back to this default).
VFIO_DYNAMIC_PARK_KEEPALIVE_INTERVAL="10"
# Park-keepalive consecutive-failure threshold (instant on, read by
# vfio-gpu-park-keepalive.sh). After this many consecutive failed remove+rescan
# recovery attempts on the same zombie card, the monitor (a) backs off its poll
# interval instead of hammering the bus every cycle, and (b) sends a one-time
# best-effort desktop notification (see VFIO_DYNAMIC_PARK_KEEPALIVE_NOTIFY) so
# you know the card needs a host reboot instead of only discovering it at the
# next VM start.
VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS="5"
# Park-keepalive backoff cap in seconds (read by vfio-gpu-park-keepalive.sh).
# Once VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS is reached, the effective poll
# interval grows (base interval * consecutive-failure count) up to this cap,
# instead of retrying a card that needs a host reboot every single interval.
VFIO_DYNAMIC_PARK_KEEPALIVE_BACKOFF_MAX="300"
# Park-keepalive desktop notification (instant on, read by
# vfio-gpu-park-keepalive.sh). 1 = best-effort notify-send to the desktop user
# session once VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS consecutive recovery
# failures is reached (silently no-ops if notify-send / a desktop session is
# unavailable). 0 = never notify (recovery attempts + logging still happen).
VFIO_DYNAMIC_PARK_KEEPALIVE_NOTIFY="1"
# Live-attach (hotplug GPU) mode (advanced, opt-in, read by the libvirt hook):
# - 0 (default): the GPU is bound to vfio-pci BEFORE the VM starts (standard
#   dynamic binding). qemu attaches the GPU at boot, which triggers the attach-
#   time bus reset that kills the RX 9070 / RDNA4 on the second (parked) start.
# - 1: the VM starts WITHOUT the GPU (Windows boots on a virtual display), and
#   after VFIO_DYNAMIC_LIVE_ATTACH_DELAY seconds the GPU is bound to vfio-pci
#   and hot-attached to the running VM via 'virsh attach-device --live'. This
#   sidesteps the parked-restart death: the GPU is hot-added to a running
#   Windows that has already loaded the AMD driver, so the card is properly
#   initialized before qemu's attach reset fires.
# WHY this value: 0 is the safe default (standard dynamic binding). Set 1 ONLY
# if the card dies on the second (parked) VM start and the AMD Windows driver
# is already installed (the driver must be installed first, otherwise the card
# dies during the first session regardless). Use 'sudo vfio.sh --install-live-
# attach' to set up the live-attach workflow (modifies the VM XML, creates the
# GPU device XML, installs the helper script).
VFIO_DYNAMIC_LIVE_ATTACH="0"
# Max seconds to wait after VM start before binding + hot-attaching the GPU
# (read by the live-attach helper). SMART: the helper polls the qemu guest
# agent (guest-ping) every 3s and binds the MOMENT Windows userspace responds —
# so with the virtio-win guest agent installed, the GPU hot-attaches as soon as
# Windows is actually up (often ~15s), not after a blind fixed wait. This value
# is the CEILING: if the agent responds earlier, bind happens earlier; if the
# agent is not installed in Windows (or no channel), the helper waits this full
# value then binds (the old fixed-delay behavior). Default 30s. If the card
# still dies with 30s, increase to 60-90s (Windows may need longer to load the
# AMD driver on the first few boots). install_live_attach auto-injects the
# guest-agent channel; install the virtio-win guest agent inside Windows (via
# the virtio-win guest-tools ISO) to enable the smart early-bind path.
VFIO_DYNAMIC_LIVE_ATTACH_DELAY="30"
# Timeout in seconds for the 'virsh attach-device --live' call (read by the
# live-attach helper). The RX 9070 / RDNA4 vfio attach reset + Gen5 link retrain
# can take >30s, so the default is 60 (a 30s timeout fired on a still-progressing
# attach — the card was alive afterward, so it was slow, not dead). On timeout
# the helper logs and exits non-zero so libvirt is never blocked indefinitely.
# If it still times out at 60s the attach reset is genuinely stuck (not just
# slow) and live-attach won't work for the card — revert with
# --install-dynamic-binding. Floor is 10s.
VFIO_DYNAMIC_LIVE_ATTACH_TIMEOUT="60"
EOF
}

install_vfio_modules_load() {
  backup_file "$MODULES_LOAD"

  # Build the list of VFIO modules that are actually present for this kernel.
  local -a mods=()
  mapfile -t mods < <(discover_vfio_modules)

  write_file_atomic "$MODULES_LOAD" 0644 "root:root" <<EOF
# Load VFIO modules at boot
$(printf '%s
' "${mods[@]}")
EOF
}

# On some openSUSE Tumbleweed systems with recent default kernels, AMD Navi
# GPUs (such as 73bf) may still be claimed by amdgpu even when vfio-pci.ids=
# and rd.driver.pre=vfio-pci are present. In testing, the distribution's
# longterm kernel (package: kernel-longterm) behaved more predictably and
# allowed vfio-pci to bind the GPU at boot. This helper does NOT force a
# kernel switch automatically, but offers to install kernel-longterm so the
# user can choose that entry at boot.
maybe_offer_kernel_longterm() {
  local guest_vendor_b10="$1" guest_gpu_bdf="$2"

  # Only relevant on openSUSE-like systems using zypper.
  if ! is_opensuse_like; then
    return 0
  fi
  if ! have_cmd zypper; then
    return 0
  fi

  # Only makes sense for AMD guest GPUs.
  if [[ "${guest_vendor_b10,,}" != "1002" ]]; then
    return 0
  fi

  # If the guest GPU is already bound to vfio-pci on this boot, there is no
  # need to suggest an alternative kernel.
  if [[ "$(bdf_driver_name "$guest_gpu_bdf")" == "vfio-pci" ]]; then
    return 0
  fi

  # If kernel-longterm is already installed, nothing to do.
  if rpm -q kernel-longterm >/dev/null 2>&1; then
    return 0
  fi

  say
  hdr "Optional: install long-term kernel for more reliable VFIO binding"
  note "On some openSUSE Tumbleweed systems with AMD GPUs, the very newest default kernel can let amdgpu claim the guest GPU even when vfio-pci.ids= is set."
  note "The distribution's long-term support kernel (package: kernel-longterm) often has a more conservative driver stack and has been observed to let vfio-pci bind cleanly."
  note "Installing kernel-longterm keeps your current kernel installed; at boot you can pick either the default or the long-term kernel from the menu."

  # If we detect that the guest GPU is still owned by amdgpu right now,
  # strongly suggest installing the long-term kernel by making YES the
  # default answer. Otherwise keep it as an opt-in.
  local def="N"
  if [[ "$(bdf_driver_name "$guest_gpu_bdf")" == "amdgpu" ]]; then
    def="Y"
    note "Right now the guest GPU ($guest_gpu_bdf) is driven by amdgpu; installing kernel-longterm is RECOMMENDED so vfio-pci can reliably bind it."
  else
    note "If you later find that amdgpu still owns the guest GPU after enabling VFIO, consider installing kernel-longterm manually: zypper in kernel-longterm."
  fi

  if prompt_yn "Install the kernel-longterm package now via zypper (optional, safe alongside the current kernel)?" "$def" "Kernel (optional)"; then
    run zypper --non-interactive in kernel-longterm || \
      note "kernel-longterm install via zypper failed; you can install it manually later with: zypper in kernel-longterm"
  fi
}

# On Fedora systems, the stock Fedora kernel does not ship the ACS override patch.
# This means pcie_acs_override=downstream,multifunction is silently ignored,
# which can leave the guest GPU in the same IOMMU group as other devices (for
# example the PCIe bridge or xHCI controller). Under sustained VFIO passthrough
# load this can destabilize the shared PCIe root complex and cause USB/xHCI
# crashes after long VM sessions. The CachyOS kernel (available via the
# bieszczaders/kernel-cachyos COPR) includes ACS override support and has been
# observed to properly isolate devices. This helper does NOT force a kernel
# switch automatically, but offers to install the CachyOS kernel so the user can
# choose that entry at boot.
maybe_offer_fedora_cachyos_kernel() {
  local guest_vendor_b10="$1" guest_gpu_bdf="$2"

  # Only relevant on Fedora-like systems using dnf.
  if ! is_fedora_like; then
    return 0
  fi
  if ! have_cmd dnf; then
    return 0
  fi

  # Only makes sense for AMD guest GPUs (the most common scenario where ACS
  # override is needed on consumer AMD platforms).
  if [[ "${guest_vendor_b10,,}" != "1002" ]]; then
    return 0
  fi

  # If the guest GPU is already bound to vfio-pci on this boot, there is no
  # need to suggest an alternative kernel.
  if [[ "$(bdf_driver_name "$guest_gpu_bdf")" == "vfio-pci" ]]; then
    return 0
  fi

  # If pcie_acs_override is already active in the running kernel, nothing
  # to do.
  if grep -q 'pcie_acs_override' /proc/cmdline 2>/dev/null; then
    return 0
  fi

  # If the CachyOS kernel is already installed, nothing to do.
  if rpm -q kernel-cachyos >/dev/null 2>&1; then
    return 0
  fi
  # Also check if the running kernel already is a CachyOS kernel.
  local krel
  krel="$(uname -r)"
  if [[ "$krel" == *cachyos* ]]; then
    return 0
  fi

  say
  hdr "Optional: install CachyOS kernel for ACS override support"
  note "The stock Fedora kernel does NOT include the ACS override patch."
  note "When pcie_acs_override=downstream,multifunction is present in the kernel cmdline but the patch is missing, the parameter is silently ignored."
  note "This can leave the guest GPU in the same IOMMU group as other devices (for example the PCIe bridge or xHCI controller), which may destabilize the shared PCIe root complex during long VFIO passthrough sessions and cause USB/xHCI crashes."
  note "The CachyOS kernel (package: kernel-cachyos, COPR: bieszczaders/kernel-cachyos) includes ACS override support and has been observed to properly isolate devices into separate IOMMU groups."
  note "Installing kernel-cachyos keeps your current kernel installed; at boot you can pick either the default Fedora kernel or the CachyOS kernel from the menu."

  # If we detect that the guest GPU is still owned by amdgpu right now,
  # strongly suggest installing the CachyOS kernel by making YES the
  # default answer. Otherwise keep it as an opt-in.
  local def="N"
  if [[ "$(bdf_driver_name "$guest_gpu_bdf")" == "amdgpu" ]]; then
    def="Y"
    note "Right now the guest GPU ($guest_gpu_bdf) is driven by amdgpu; installing the CachyOS kernel is RECOMMENDED so vfio-pci can reliably bind it with proper IOMMU isolation."
  else
    note "If you later find that amdgpu still owns the guest GPU after enabling VFIO, or you experience USB/xHCI instability after long VM sessions, consider installing the CachyOS kernel manually:"
    note "  sudo dnf copr enable bieszczaders/kernel-cachyos"
    note "  sudo dnf install kernel-cachyos kernel-cachyos-devel-matched"
  fi

  if prompt_yn "Install the CachyOS kernel (kernel-cachyos) now via dnf from COPR bieszczaders/kernel-cachyos (optional, safe alongside the current kernel)?" "$def" "Kernel (optional)"; then
    run dnf -y copr enable bieszczaders/kernel-cachyos || \
      note "COPR enable failed; you can enable manually later with: sudo dnf copr enable bieszczaders/kernel-cachyos"
    run dnf -y install kernel-cachyos kernel-cachyos-devel-matched || \
      note "kernel-cachyos install via dnf failed; you can install it manually later with: sudo dnf install kernel-cachyos kernel-cachyos-devel-matched"
  fi
}

install_dracut_config() {
  # Only applies on dracut-based systems.
  [[ -d /etc/dracut.conf.d ]] || return 0

  local file="$DRACUT_VFIO_CONF"
  backup_file "$file"

  # Reuse the same VFIO module list and turn it into a single space-separated string.
  # Be extremely strict about using spaces (not commas) between module names, because
  # a comma-separated list would make dracut look for a single bogus module named
  # "vfio,vfio_pci,..." and fail with:
  #   dracut-install: Failed to find module 'vfio,vfio_pci,vfio_iommu_type1'
  local -a mods=()
  mapfile -t mods < <(discover_vfio_modules)

  # Join with spaces explicitly and sanitize any accidental commas just in case.
  local IFS=' '
  local joined="${mods[*]}"
  joined="${joined//,/ }"

  # Older RHEL/CentOS-style dracut setups tend to be more conservative
  # when using force_drivers; a missing or renamed module can in theory
  # cause early-boot surprises. For those, we prefer add_drivers. On
  # openSUSE we pair rd.driver.pre=vfio-pci with force_drivers so VFIO
  # is definitely present as an early driver.
  local dracut_directive="add_drivers"
  if is_opensuse_like; then
    dracut_directive="force_drivers"
  fi

  write_file_atomic "$file" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Ensure VFIO modules are included in the initramfs image.
# NOTE: this uses ${dracut_directive} so VFIO modules are available early
#       in the initramfs. On openSUSE this combines with rd.driver.pre=vfio-pci
#       so VFIO wins the race against the GPU driver; on other dracut-based
#       systems we keep a slightly more conservative add_drivers default.
${dracut_directive}+=" ${joined} "
EOF

  say "Installed Dracut configuration to ensure early VFIO loading (dracut: ${dracut_directive})."
}

write_optional_blacklist() {
  local vendor_id="$1"; shift
  local -a mods=("$@")

  backup_file "$BLACKLIST_FILE"

  write_file_atomic "$BLACKLIST_FILE" 0644 "root:root" <<EOF
# Optional driver blacklisting for VFIO (generated by $SCRIPT_NAME on $(date -Is))
# Vendor: $(vendor_name "$vendor_id") ($vendor_id)
#
# Safety:
# - This is OPTIONAL and can break host graphics if you blacklist the wrong module.
# - Prefer BDF-based vfio-pci binding (this script's default) over blacklisting.
#
# To undo: remove this file and rebuild initramfs.

$(for m in "${mods[@]}"; do echo "blacklist $m"; done)
EOF
}

install_softdep_config() {
  local guest_vendor="$1"
  local target_driver=""

  case "${guest_vendor,,}" in
    10de) target_driver="nvidia" ;;
    1002) target_driver="amdgpu" ;;
    8086) target_driver="i915" ;;
    *) return 0 ;; # Unknown vendor, skip
  esac

  local file="$SOFTDEP_FILE"
  backup_file "$file"

  write_file_atomic "$file" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Ensures vfio-pci loads before the graphics driver to prevent race conditions.
# Use exact module names only; wildcard module names are not valid in modprobe softdep entries.

softdep $target_driver pre: vfio-pci
EOF

  say "Installed soft dependency to ensure vfio-pci loads before $target_driver."
}

# ---------------- GRUB / kernel params ----------------

cpu_iommu_param() {
  if command -v lscpu >/dev/null 2>&1; then
    if lscpu | grep -qi 'GenuineIntel'; then
      echo "intel_iommu=on"
      return 0
    fi
    if lscpu | grep -qi 'AuthenticAMD'; then
      echo "amd_iommu=on"
      return 0
    fi
  fi
  # fallback
  if grep -qi 'GenuineIntel' /proc/cpuinfo 2>/dev/null; then
    echo "intel_iommu=on"
  else
    echo "amd_iommu=on"
  fi
}

grub_get_key() {
  if grep -q '^GRUB_CMDLINE_LINUX_DEFAULT=' /etc/default/grub; then
    echo 'GRUB_CMDLINE_LINUX_DEFAULT'
    return 0
  fi
  if grep -q '^GRUB_CMDLINE_LINUX=' /etc/default/grub; then
    echo 'GRUB_CMDLINE_LINUX'
    return 0
  fi
  return 1
}

grub_read_cmdline() {
  # Reads existing cmdline string without adding new lines.
  local key="$1"
  local line
  line="$(grep -E "^${key}=" /etc/default/grub)" || true

  # Must be exactly one matching line.
  local count
  count="$(grep -Ec "^${key}=" /etc/default/grub || true)"
  [[ "$count" == "1" ]] || die "Expected exactly 1 ${key}= line in /etc/default/grub, found: $count"

  line="${line#"${key}"=}"
  line="$(trim "$line")"

  # Strip matching quotes if present.
  if [[ "$line" == \"*\" ]]; then
    echo "${line:1:${#line}-2}"
  elif [[ "$line" == \'.*\' ]]; then
    echo "${line:1:${#line}-2}"
  else
    echo "$line"
  fi
}

grub_write_cmdline_in_place() {
  # Modify ONLY the existing cmdline line. Do not add new lines.
  local key="$1" new_cmdline="$2"

  local ln
  ln="$(grep -nE "^${key}=" /etc/default/grub | cut -d: -f1)"
  [[ -n "$ln" ]] || die "Missing ${key}= line in /etc/default/grub (refusing to add new line)"

  # Ensure it's a single line number.
  if grep -nE "^${key}=" /etc/default/grub | cut -d: -f1 | wc -l | grep -qv '^1$'; then
    die "Multiple ${key}= lines found; refusing to edit ambiguously."
  fi

  if (( DRY_RUN )); then
    return 0
  fi

  # SAFETY 1: Verify backup exists and has content.
  local bak="/etc/default/grub.bak.${RUN_TS}"
  if [[ ! -s "$bak" ]]; then
    die "Backup failed or empty ($bak). Aborting GRUB edit."
  fi

  # Apply edit: replace EXACTLY that line number.
  sed -i "${ln}s|^${key}=.*|${key}=\"${new_cmdline//|/\\|}\"|" /etc/default/grub

  # SAFETY 2: Syntax check.
  if ! bash -n /etc/default/grub 2>/dev/null; then
    cp -a "$bak" /etc/default/grub
    die "Syntax error in /etc/default/grub after edit. Reverted to backup."
  fi

  # SAFETY 3: Logic check – ensure the key still exists after edit.
  if ! grep -q "^${key}=" /etc/default/grub; then
    cp -a "$bak" /etc/default/grub
    die "GRUB edit removed ${key} line unexpectedly. Reverted to backup."
  fi
}

# Run a best-effort GRUB syntax check on the generated grub.cfg, if tooling
# is available. This helps catch situations where an edited cmdline or script
# causes lexer errors at boot ("lexer.c:352: syntax error").
#
# We return non-zero when GRUB reports a syntax error so callers can
# automatically roll back to a known-good /etc/default/grub if a backup
# from this run exists.
maybe_check_grub_cfg() {
  local cfg=""

  # Locate grub.cfg in common locations.
  if [[ -f /boot/grub2/grub.cfg ]]; then
    cfg="/boot/grub2/grub.cfg"
  elif [[ -f /boot/grub/grub.cfg ]]; then
    cfg="/boot/grub/grub.cfg"
  fi

  [[ -n "$cfg" ]] || return 0

  # Prefer grub2-script-check if present.
  if command -v grub2-script-check >/dev/null 2>&1; then
    if grub2-script-check "$cfg" >/dev/null 2>&1; then
      return 0
    fi
    note "GRUB syntax check reported issues in $cfg (boot menu may show lexer errors)."
    return 1
  fi

  # Some distros ship grub-script-check instead.
  if command -v grub-script-check >/dev/null 2>&1; then
    if grub-script-check "$cfg" >/dev/null 2>&1; then
      return 0
    fi
    note "GRUB syntax check reported issues in $cfg (boot menu may show lexer errors)."
    return 1
  fi

  return 0
}

add_param_once() {
  local cmdline="$1" param="$2"
  # token match (space or start/end). cmdline is treated as space-separated.
  if grep -Eq "(^|[[:space:]])${param//./\\.}([[:space:]]|$)" <<<"$cmdline"; then
    echo "$cmdline"
  else
    trim "$cmdline $param"
  fi
}

remove_param_all() {
  # Remove a cmdline token (exact token) if present.
  local cmdline="$1" param="$2"
  # Split on spaces to be safe.
  local out="" tok
  local IFS=$' \t\n'
  for tok in $cmdline; do
    if [[ "$tok" == "$param" ]]; then
      continue
    fi
    out+="${out:+ }$tok"
  done
  trim "$out"
}
remove_param_prefix() {
  # Remove cmdline tokens that start with a given prefix (e.g. key=).
  local cmdline="$1" prefix="$2"
  local out="" tok
  local IFS=$' \t\n'
  for tok in $cmdline; do
    if [[ "$tok" == "${prefix}"* ]]; then
      continue
    fi
    out+="${out:+ }$tok"
  done
  trim "$out"
}
preview_cmdline_change_interactive() {
  # preview_cmdline_change_interactive "<current_cmdline>" "<updated_cmdline>" "<target_label>"
  local current="$1"
  local updated="$2"
  local target="$3"
  local current_trim updated_trim
  current_trim="$(trim "${current:-}")"
  updated_trim="$(trim "${updated:-}")"
  [[ "$current_trim" != "$updated_trim" ]] || return 0

  say
  hdr "Preview ${target} update"
  note "Current ${target}:"
  say "  ${current_trim:-<empty>}"
  note "Proposed ${target}:"
  say "  ${updated_trim:-<empty>}"
  if prompt_yn "Apply this ${target} update?" Y "Boot options preview"; then
    return 0
  fi
  note "Skipped ${target} update by user choice."
  return 1
}
append_guest_vfio_ids_with_detect_fallback() {
  # append_guest_vfio_ids_with_detect_fallback "<current_cmdline>" "<target_label>"
  # Always attempts to add vfio-pci.ids for the selected guest GPU.
  # If the selected guest is Boot VGA AND VFIO risk/failure markers were
  # detected in this run, it falls back by removing vfio-pci.ids again.
  local current="$1"
  local target="$2"
  local updated="$current"
  local out guest_ids guest_boot_vga="0" risk_detected=0
  out="/dev/stderr"
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    out="/dev/tty"
  fi

  guest_ids="${CTX[guest_vfio_ids]:-}"
  [[ -n "$guest_ids" ]] || {
    printf '%s\n' "$updated"
    return 0
  }

  updated="$(add_param_once "$updated" "vfio-pci.ids=$guest_ids")"

  if [[ -n "${CTX[guest_gpu]:-}" && -f "/sys/bus/pci/devices/${CTX[guest_gpu]}/boot_vga" ]]; then
    guest_boot_vga="$(cat "/sys/bus/pci/devices/${CTX[guest_gpu]}/boot_vga" 2>/dev/null || echo 0)"
  fi

  if [[ "${CTX[kernel_vfio_risk]:-0}" == "1" || "${CTX[kernel_vfio_log_error]:-0}" == "1" ]]; then
    risk_detected=1
  fi

  if [[ "$guest_boot_vga" == "1" ]]; then
    note "Boot VGA guest detected (${CTX[guest_gpu]:-unknown}); adding vfio-pci.ids in ${target} with automatic risk fallback enabled." >"$out"
    if (( risk_detected )); then
      note "Detected VFIO risk/failure markers in this run; fallback applied in ${target} by removing vfio-pci.ids for safer boot behavior." >"$out"
      updated="$(remove_param_all "$updated" "vfio-pci.ids=$guest_ids")"
      CTX[guest_vfio_ids_fallback]=1
    fi
  fi

  printf '%s\n' "$updated"
  return 0
}
add_custom_kernel_params_interactive() {
  # add_custom_kernel_params_interactive "<current_cmdline>" "<target_label>"
  local current="$1"
  local target="$2"
  local updated="$current"
  local in out extra tok
  in="/dev/stdin"
  out="/dev/stderr"
  if [[ -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi

  # IMPORTANT: this helper is used in command substitution. Keep all UI text
  # off stdout so only the final updated cmdline is returned to the caller.
  printf '\n' >"$out"
  hdr "Custom kernel parameters (optional)" >"$out"
  note "You can append extra kernel parameter(s) for ${target}." >"$out"
  note "This can be useful for distro-specific or X11-specific passthrough tweaks." >"$out"
  note "Leave blank to keep defaults." >"$out"

  if ! prompt_yn "Add custom kernel parameter(s) to ${target} now?" N "Boot options (custom)"; then
    printf '%s\n' "$updated"
    return 0
  fi

  printf '%s' "Enter extra kernel parameter(s), space-separated: " >"$out"
  read -r extra <"$in" || extra=""
  extra="$(trim "${extra:-}")"
  if [[ -z "$extra" ]]; then
    note "No custom kernel parameters entered." >"$out"
    printf '%s\n' "$updated"
    return 0
  fi

  for tok in $extra; do
    updated="$(add_param_once "$updated" "$tok")"
  done
  note "Added custom kernel parameter(s): $extra" >"$out"
  printf '%s\n' "$updated"
  return 0
}

# Return 0 if the running kernel looks like an openSUSE default kernel
# ("*-default") with a version at or above a given threshold. This is used
# to warn users about known/expected VFIO binding issues on very new
# default kernels, and to suggest booting the long-term kernel instead.
opensuse_default_kernel_is_at_least() {
  local min_major="$1" min_minor="$2"
  local kver base major minor

  kver="$(uname -r 2>/dev/null || echo '')"
  [[ -n "$kver" ]] || return 1

  # Only care about -default flavour; -longterm and others are fine.
  case "$kver" in
    *-default*) : ;;
    *) return 1 ;;
  esac

  base="${kver%%-*}"
  major="${base%%.*}"
  minor="${base#*.}"
  minor="${minor%%.*}"

  [[ "$major" =~ ^[0-9]+$ ]] || return 1
  [[ "$minor" =~ ^[0-9]+$ ]] || return 1

  if (( major > min_major )); then
    return 0
  fi
  if (( major == min_major && minor >= min_minor )); then
    return 0
  fi
  return 1
}

detect_bootloader() {
  # 1) Check if systemd-boot is the ACTIVE bootloader (via bootctl)
  # This fixes setups (like openSUSE) where /etc/default/grub exists but isn't used.
  if command -v bootctl >/dev/null 2>&1; then
    # bootctl status prints "Product: systemd-boot" if active
    if bootctl status 2>/dev/null | grep -qi "systemd-boot"; then
      echo "systemd-boot"
      return 0
    fi
  fi

  # 2) openSUSE GRUB2-BLS: uses Boot Loader Spec entries + /etc/kernel/cmdline
  # even though /etc/default/grub may still exist. We detect this explicitly so
  # we DO NOT treat it as classic GRUB (which would incorrectly edit
  # /etc/default/grub and be ignored at boot).
  if is_opensuse_like && [[ -r /etc/sysconfig/bootloader ]]; then
    if grep -qi 'LOADER_TYPE=.*grub2-bls' /etc/sysconfig/bootloader 2>/dev/null; then
      echo "grub2-bls"
      return 0
    fi
  fi
  # Many openSUSE Tumbleweed systems use BLS while still declaring
  # LOADER_TYPE="grub2-efi" in /etc/sysconfig/bootloader, with BLS
  # actually enabled via GRUB_ENABLE_BLSCFG="true" in /etc/default/grub.
  # Detect that configuration as grub2-bls as well so we follow the
  # /etc/kernel/cmdline + sdbootutil path instead of legacy GRUB.
  if is_opensuse_like && [[ -f /etc/default/grub ]]; then
    # Many setups enable BLS via GRUB_ENABLE_BLSCFG="true" (or similar).
    if grep -qi 'GRUB_ENABLE_BLSCFG=.*true' /etc/default/grub 2>/dev/null; then
      echo "grub2-bls"
      return 0
    fi
  fi
  # Some openSUSE GRUB deployments still boot via Boot Loader Spec entries
  # even when GRUB_ENABLE_BLSCFG/LOADER_TYPE markers are absent or stale.
  # If /etc/kernel/cmdline exists and loader entries contain options with
  # root=..., treat this as GRUB2-BLS so we follow the safe cmdline+BLS flow.
  if is_opensuse_like && [[ -f /etc/kernel/cmdline ]] && [[ -d /boot/grub || -d /boot/grub2 ]]; then
    local bls_dir bls_entry
    bls_dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
    if [[ -n "$bls_dir" ]]; then
      shopt -s nullglob
      for bls_entry in "$bls_dir"/system-*.conf "$bls_dir"/grub-*.conf "$bls_dir"/*.conf; do
        [[ -f "$bls_entry" ]] || continue
        if grep -qE '^options[[:space:]]+.*\<root=' "$bls_entry" 2>/dev/null; then
          shopt -u nullglob
          echo "grub2-bls"
          return 0
        fi
      done
      shopt -u nullglob
    fi
  fi

  # 3) Fallback: Check for systemd-boot-style config directories directly
  if [[ -d /boot/loader/entries || -d /efi/loader/entries || -d /boot/efi/loader/entries ]]; then
    # If standard grub dirs are missing, it's definitely systemd-boot
    if [[ ! -d /boot/grub && ! -d /boot/grub2 ]]; then
      echo "systemd-boot"
      return 0
    fi
  fi
  
  # 4) Classic GRUB with /etc/default/grub present (most distros)
  if [[ -f /etc/default/grub ]]; then
    echo "grub"
    return 0
  fi

  # 5) GRUB installed but config missing
  if [[ -d /boot/grub || -d /boot/grub2 ]]; then
    echo "grub"
    return 0
  fi

  # 6) rEFInd
  if [[ -f /boot/refind_linux.conf || -f /efi/EFI/refind/refind.conf || -f /boot/efi/EFI/refind/refind.conf ]]; then
    echo "refind"
    return 0
  fi

  echo "unknown"
}

# Read /etc/os-release fields used by distro gating. Emits:
#   <id>\t<id_like>
# (Both values may be empty when unknown.)
os_release_id_and_like() {
  local os_id="" os_like=""
  if [[ -r /etc/os-release ]]; then
    local k v
    while IFS='=' read -r k v; do
      [[ -n "${k:-}" ]] || continue
      case "$k" in
        ID)
          v="${v%\"}"
          v="${v#\"}"
          os_id="$v"
          ;;
        ID_LIKE)
          v="${v%\"}"
          v="${v#\"}"
          os_like="$v"
          ;;
      esac
    done </etc/os-release
  fi
  printf '%s\t%s\n' "$os_id" "$os_like"
}

# Diagnostic string for openSUSE-family detection used by --detect.
# Example outputs:
#   yes (ID=opensuse-tumbleweed matched opensuse*)
#   yes (ID_LIKE token opensuse matched opensuse*)
#   no (ID=sparky; ID_LIKE=debian)
opensuse_like_detection_reason() {
  local pair os_id os_like tok
  pair="$(os_release_id_and_like)"
  os_id="${pair%%$'\t'*}"
  os_like="${pair#*$'\t'}"
  [[ "$os_like" == "$pair" ]] && os_like=""

  if [[ "${os_id,,}" == opensuse* ]]; then
    printf 'yes (ID=%s matched opensuse*)\n' "${os_id:-<empty>}"
    return 0
  fi
  for tok in $os_like; do
    if [[ "${tok,,}" == opensuse* ]]; then
      printf 'yes (ID_LIKE token %s matched opensuse*)\n' "$tok"
      return 0
    fi
  done
  printf 'no (ID=%s; ID_LIKE=%s)\n' "${os_id:-<empty>}" "${os_like:-<empty>}"
  return 1
}

# Return 0 if this looks like an openSUSE-like system (used to gate /etc/kernel/cmdline edits).
is_opensuse_like() {
  opensuse_like_detection_reason >/dev/null
}

# Diagnostic string for Fedora-family detection used by --detect.
# Example outputs:
#   yes (ID=fedora matched fedora*)
#   yes (ID_LIKE token rhel matched rhel*)
#   no (ID=debian; ID_LIKE=debian)
fedora_like_detection_reason() {
  local pair os_id os_like tok
  pair="$(os_release_id_and_like)"
  os_id="${pair%%$'\t'*}"
  os_like="${pair#*$'\t'}"
  [[ "$os_like" == "$pair" ]] && os_like=""

  if [[ "${os_id,,}" == fedora* ]]; then
    printf 'yes (ID=%s matched fedora*)\n' "${os_id:-<empty>}"
    return 0
  fi
  for tok in $os_like; do
    if [[ "${tok,,}" == fedora* || "${tok,,}" == rhel* ]]; then
      printf 'yes (ID_LIKE token %s matched fedora|rhel*)\n' "$tok"
      return 0
    fi
  done
  printf 'no (ID=%s; ID_LIKE=%s)\n' "${os_id:-<empty>}" "${os_like:-<empty>}"
  return 1
}

# Return 0 if this looks like a Fedora-like system (used to gate CachyOS kernel offers).
is_fedora_like() {
  fedora_like_detection_reason >/dev/null
}

# Locate the systemd-boot / BLS entries directory (if any).
systemd_boot_entries_dir() {
  local d
  for d in /boot/efi/loader/entries /boot/loader/entries /efi/loader/entries; do
    if [[ -d "$d" ]]; then
      echo "$d"
      return 0
    fi
  done
  return 1
}

kernel_cmdline_persistence_file() {
  echo "/etc/kernel/cmdline"
}
kernel_cmdline_rehydrate_boot_metadata_if_missing() {
  # Best-effort safety net: if /etc/kernel/cmdline lost root metadata,
  # recover it from current/backup BLS entry options before any sync/update.
  local cmdline_file="${1:-}"
  if [[ -z "$cmdline_file" ]]; then
    cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  fi
  cmdline_file="$(trim "${cmdline_file:-}")"
  [[ -n "$cmdline_file" ]] || return 1
  [[ -f "$cmdline_file" ]] || return 1

  local current_cmdline
  current_cmdline="$(cat "$cmdline_file" 2>/dev/null || true)"
  current_cmdline="$(trim "${current_cmdline:-}")"
  [[ -n "$current_cmdline" ]] || return 1
  if cmdline_get_key_value_token "$current_cmdline" "root" >/dev/null 2>&1; then
    return 0
  fi

  local metadata_opts recovered_cmdline recovered_root_tok
  metadata_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
  metadata_opts="$(trim "${metadata_opts:-}")"
  [[ -n "$metadata_opts" ]] || return 1

  recovered_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$current_cmdline" "$metadata_opts")"
  recovered_cmdline="$(trim "${recovered_cmdline:-}")"
  recovered_root_tok="$(cmdline_get_key_value_token "$recovered_cmdline" "root" 2>/dev/null || true)"
  [[ -n "$recovered_root_tok" ]] || return 1

  if [[ "$recovered_cmdline" == "$current_cmdline" ]]; then
    return 0
  fi

  backup_file "$cmdline_file"
  if (( ! DRY_RUN )); then
    printf '%s\n' "$recovered_cmdline" >"$cmdline_file"
  fi
  note "Rehydrated missing root boot metadata in $cmdline_file from Boot Loader Spec options."
  return 0
}
kernel_cmdline_reconcile_boot_metadata_with_current_mount() {
  # Align persisted root/rootflags metadata with the currently mounted root.
  # This prevents stale snapshot rootflags from surviving across BLS sync runs.
  local cmdline_file="${1:-}"
  if [[ -z "$cmdline_file" ]]; then
    cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  fi
  cmdline_file="$(trim "${cmdline_file:-}")"
  [[ -n "$cmdline_file" ]] || return 1
  [[ -f "$cmdline_file" ]] || return 1

  local current_cmdline
  current_cmdline="$(cat "$cmdline_file" 2>/dev/null || true)"
  current_cmdline="$(trim "${current_cmdline:-}")"
  [[ -n "$current_cmdline" ]] || return 1

  local mount_root_tok mount_rootflags_tok
  mount_root_tok="$(bls_current_mount_root_token 2>/dev/null || true)"
  mount_rootflags_tok="$(bls_current_mount_rootflags_token 2>/dev/null || true)"
  [[ -n "$mount_root_tok" || -n "$mount_rootflags_tok" ]] || return 1

  local cmdline_root_tok cmdline_rootflags_tok updated_cmdline
  cmdline_root_tok="$(cmdline_get_key_value_token "$current_cmdline" "root" 2>/dev/null || true)"
  cmdline_rootflags_tok="$(cmdline_get_key_value_token "$current_cmdline" "rootflags" 2>/dev/null || true)"
  updated_cmdline="$current_cmdline"

  if [[ -n "$mount_root_tok" ]] && [[ "$cmdline_root_tok" != "$mount_root_tok" ]]; then
    updated_cmdline="$(cmdline_set_key_value_token "$updated_cmdline" "$mount_root_tok")"
  fi
  if [[ -n "$mount_rootflags_tok" ]]; then
    local root_context_matches=1
    if [[ -n "$mount_root_tok" && -n "$cmdline_root_tok" && "$cmdline_root_tok" != "$mount_root_tok" ]]; then
      root_context_matches=0
    fi
    if (( root_context_matches )) && [[ "$cmdline_rootflags_tok" != "$mount_rootflags_tok" ]]; then
      updated_cmdline="$(cmdline_set_key_value_token "$updated_cmdline" "$mount_rootflags_tok")"
    fi
  fi

  updated_cmdline="$(trim "${updated_cmdline:-}")"
  [[ -n "$updated_cmdline" ]] || return 1
  if [[ "$updated_cmdline" == "$current_cmdline" ]]; then
    return 0
  fi

  backup_file "$cmdline_file"
  if (( ! DRY_RUN )); then
    printf '%s\n' "$updated_cmdline" >"$cmdline_file"
  fi
  note "Reconciled root boot metadata in $cmdline_file with the currently mounted root."
  return 0
}

# Extract the first key=value token for a given key from a kernel cmdline
# string. Example:
#   cmdline_get_key_value_token "quiet root=UUID=abcd rw" "root"
#   -> root=UUID=abcd
cmdline_get_key_value_token() {
  local cmdline="$1" key="$2" tok
  local IFS=$' \t\n'
  for tok in $cmdline; do
    case "$tok" in
      "${key}"=*)
        printf '%s\n' "$tok"
        return 0
        ;;
    esac
  done
  return 1
}
cmdline_contains_exact_token() {
  local cmdline="$1" token="$2" tok
  local IFS=$' \t\n'
  [[ -n "$token" ]] || return 1
  for tok in $cmdline; do
    if [[ "$tok" == "$token" ]]; then
      return 0
    fi
  done
  return 1
}
cmdline_remove_key_value_tokens() {
  # Remove all key=value tokens for one key from a cmdline string.
  local cmdline="$1" key="$2" tok out=""
  local IFS=$' \t\n'
  for tok in $cmdline; do
    case "$tok" in
      "${key}"=*) continue ;;
    esac
    out+="${out:+ }$tok"
  done
  trim "$out"
}
cmdline_set_key_value_token() {
  # Replace key=value tokens for this key with the provided token.
  local cmdline="$1" token="$2"
  local key
  key="${token%%=*}"
  local out
  out="$(cmdline_remove_key_value_tokens "$cmdline" "$key")"
  add_param_once "$out" "$token"
}
bls_current_mount_root_token() {
  # Best-effort root= token from current mount metadata.
  # Works in normal boot and inside chroot (where / points at target root).
  have_cmd findmnt || return 1
  local uuid
  uuid="$(findmnt -no UUID / 2>/dev/null || true)"
  uuid="$(trim "${uuid:-}")"
  [[ -n "$uuid" ]] || return 1
  printf 'root=UUID=%s\n' "$uuid"
}
bls_current_mount_rootflags_token() {
  # Best-effort rootflags=subvol=... token from current mount options.
  have_cmd findmnt || return 1
  local opts subvol
  opts="$(findmnt -no OPTIONS / 2>/dev/null || true)"
  opts="$(trim "${opts:-}")"
  [[ -n "$opts" ]] || return 1
  subvol="$(tr ',' '\n' <<<"$opts" | sed -n 's/^subvol=//p' | head -n1)"
  subvol="$(trim "${subvol:-}")"
  [[ -n "$subvol" ]] || return 1
  printf 'rootflags=subvol=%s\n' "$subvol"
}
bls_find_entry_backup_metadata_options() {
  # Return newest backup options for this exact entry path that still contains root=.
  local entry="$1"
  local bak opts
  local best_bak="" best_opts=""
  shopt -s nullglob
  for bak in "${entry}.bak."*; do
    [[ -f "$bak" ]] || continue
    opts="$(bls_entry_options "$bak")"
    opts="$(trim "${opts:-}")"
    [[ -n "$opts" ]] || continue
    if ! cmdline_get_key_value_token "$opts" "root" >/dev/null 2>&1; then
      continue
    fi
    if [[ -z "$best_bak" || "$bak" > "$best_bak" ]]; then
      best_bak="$bak"
      best_opts="$opts"
    fi
  done
  shopt -u nullglob
  [[ -n "$best_opts" ]] || return 1
  printf '%s\n' "$best_opts"
}
bls_find_boot_metadata_options() {
  # Best-effort source for stable boot metadata tokens used by openSUSE BLS:
  # root=, rootflags=, rootfstype=, resume=, systemd.machine_id, ro/rw.
  # Preference order:
  #   1) selected source system entry
  #   2) any current *.conf entry that still contains root=
  #   3) newest backup *.conf.bak.* entry, preferring root/rootflags that
  #      match the currently mounted root subvolume when available
  local dir source opts f
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  [[ -n "$dir" ]] || return 1

  source="$(bls_select_source_system_entry "$dir" 2>/dev/null || true)"
  if [[ -n "$source" && -f "$source" ]]; then
    opts="$(bls_entry_options "$source")"
    opts="$(trim "${opts:-}")"
    if [[ -n "$opts" ]] && cmdline_get_key_value_token "$opts" "root" >/dev/null 2>&1; then
      printf '%s\n' "$opts"
      return 0
    fi
  fi
  shopt -s nullglob
  for f in "$dir"/system-*.conf "$dir"/snapper-*.conf "$dir"/*.conf; do
    [[ -f "$f" ]] || continue
    opts="$(bls_entry_options "$f")"
    opts="$(trim "${opts:-}")"
    [[ -n "$opts" ]] || continue
    if cmdline_get_key_value_token "$opts" "root" >/dev/null 2>&1; then
      printf '%s\n' "$opts"
      shopt -u nullglob
      return 0
    fi
  done
  shopt -u nullglob

  local root_hint_tok rootflags_hint_tok cmdline_file cmdline_opts
  root_hint_tok="$(bls_current_mount_root_token 2>/dev/null || true)"
  rootflags_hint_tok="$(bls_current_mount_rootflags_token 2>/dev/null || true)"
  cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  cmdline_file="$(trim "${cmdline_file:-}")"
  if [[ -n "$cmdline_file" && -f "$cmdline_file" ]]; then
    cmdline_opts="$(cat "$cmdline_file" 2>/dev/null || true)"
    cmdline_opts="$(trim "${cmdline_opts:-}")"
    if [[ -z "$root_hint_tok" ]]; then
      root_hint_tok="$(cmdline_get_key_value_token "$cmdline_opts" "root" 2>/dev/null || true)"
    fi
    if [[ -z "$rootflags_hint_tok" ]]; then
      rootflags_hint_tok="$(cmdline_get_key_value_token "$cmdline_opts" "rootflags" 2>/dev/null || true)"
    fi
  fi

  local best_bak="" best_opts="" best_score=-1 score

  shopt -s nullglob
  for f in "$dir"/system-*.conf.bak.* "$dir"/snapper-*.conf.bak.* "$dir"/*.conf.bak.*; do
    [[ -f "$f" ]] || continue
    opts="$(bls_entry_options "$f")"
    opts="$(trim "${opts:-}")"
    [[ -n "$opts" ]] || continue
    if ! cmdline_get_key_value_token "$opts" "root" >/dev/null 2>&1; then
      continue
    fi
    score=0
    if [[ -n "$rootflags_hint_tok" ]] && cmdline_contains_exact_token "$opts" "$rootflags_hint_tok"; then
      (( score += 2 ))
    fi
    if [[ -n "$root_hint_tok" ]] && cmdline_contains_exact_token "$opts" "$root_hint_tok"; then
      (( score += 1 ))
    fi
    if (( score > best_score )) || { (( score == best_score )) && [[ -z "$best_bak" || "$f" > "$best_bak" ]]; }; then
      best_score="$score"
      best_bak="$f"
      best_opts="$opts"
    fi
  done
  shopt -u nullglob
  if [[ -n "$best_opts" ]]; then
    printf '%s\n' "$best_opts"
    return 0
  fi
  return 1
}
cmdline_add_boot_metadata_tokens_from_options() {
  # Merge boot-metadata tokens from one options string into another cmdline.
  local cmdline="$1" source_opts="$2"
  local out="$cmdline"
  local tok key
  for key in root rootflags rootfstype resume systemd.machine_id; do
    tok="$(cmdline_get_key_value_token "$source_opts" "$key" 2>/dev/null || true)"
    [[ -n "$tok" ]] && out="$(cmdline_set_key_value_token "$out" "$tok")"
  done
  if grep -Eq '(^|[[:space:]])ro([[:space:]]|$)' <<<"$source_opts"; then
    out="$(add_param_once "$out" "ro")"
  fi
  if grep -Eq '(^|[[:space:]])rw([[:space:]]|$)' <<<"$source_opts"; then
    out="$(add_param_once "$out" "rw")"
  fi
  trim "$out"
}
bls_entry_is_vfio_fallback() {
  local entry="$1" base
  base="$(basename "$entry")"
  if [[ "$base" == fallback-* || "$base" == *-fallback.conf || "$base" == *-novfio.conf ]]; then
    return 0
  fi
  grep -Eq '^# vfio-fallback-entry:[[:space:]]*1([[:space:]]*)?$' "$entry" 2>/dev/null
}
bls_entry_options() {
  local entry="$1"
  grep -m1 -E '^options[[:space:]]+' "$entry" 2>/dev/null | sed -E 's/^options[[:space:]]+//'
}
bls_entry_snapshot_id() {
  # Extract trailing snapshot ID from BLS filename, e.g. *-33.conf -> 33.
  local entry="$1" base
  base="$(basename "$entry")"
  if [[ "$base" =~ -([0-9]+)\.conf$ ]]; then
    printf '%s\n' "${BASH_REMATCH[1]}"
    return 0
  fi
  return 1
}
rootflags_snapshot_id_from_token() {
  # Extract snapshot ID from rootflags token when it follows .snapshots/<id>/snapshot.
  local tok="${1:-}" val
  [[ "$tok" == rootflags=* ]] || return 1
  val="${tok#rootflags=}"
  if [[ "$val" =~ \.snapshots/([0-9]+)/snapshot ]]; then
    printf '%s\n' "${BASH_REMATCH[1]}"
    return 0
  fi
  return 1
}
bls_rootflags_token_for_snapshot_id() {
  local snapshot_id="${1:-}"
  [[ "$snapshot_id" =~ ^[0-9]+$ ]] || return 1
  printf 'rootflags=subvol=@/.snapshots/%s/snapshot\n' "$snapshot_id"
}
bls_rd_driver_pre_remove_vfio_pci() {
  # Remove vfio-pci from one rd.driver.pre= token while preserving other drivers.
  local token="$1"
  local value
  value="${token#rd.driver.pre=}"
  local old_ifs="$IFS"
  IFS=','
  local -a drivers=()
  read -r -a drivers <<<"$value"
  IFS="$old_ifs"

  local -a keep=()
  local driver
  for driver in "${drivers[@]}"; do
    [[ -n "$driver" ]] || continue
    if [[ "$driver" == "vfio-pci" ]]; then
      continue
    fi
    keep+=("$driver")
  done
  if (( ${#keep[@]} == 0 )); then
    return 1
  fi
  local joined
  old_ifs="$IFS"
  IFS=','
  joined="${keep[*]}"
  IFS="$old_ifs"
  printf 'rd.driver.pre=%s\n' "$joined"
}
bls_strip_vfio_forcing_tokens_from_options() {
  # Remove known VFIO-forcing cmdline tokens from one BLS options string.
  local opts="$1"
  local out="" tok
  local IFS=$' \t\n'
  for tok in $opts; do
    case "$tok" in
      vfio-pci.ids=*|pcie_acs_override=*)
        continue
        ;;
      rd.driver.pre=*)
        local rewritten
        rewritten="$(bls_rd_driver_pre_remove_vfio_pci "$tok" 2>/dev/null || true)"
        if [[ -z "$rewritten" ]]; then
          continue
        fi
        tok="$rewritten"
        ;;
    esac
    out+="${out:+ }$tok"
  done
  trim "$out"
}
bls_options_has_forbidden_vfio_tokens() {
  local opts="$1" tok
  local IFS=$' \t\n'
  for tok in $opts; do
    case "$tok" in
      vfio-pci.ids=*|pcie_acs_override=*)
        return 0
        ;;
      rd.driver.pre=*)
        local values
        values=",$(printf '%s' "${tok#rd.driver.pre=}" | tr -s ','),"
        if [[ "$values" == *,vfio-pci,* ]]; then
          return 0
        fi
        ;;
    esac
  done
  return 1
}
bls_fallback_entry_target_path() {
  local source="$1" dir base stem
  dir="$(dirname "$source")"
  base="$(basename "$source")"
  stem="${base%.conf}"
  printf '%s/%s-fallback.conf\n' "$dir" "$stem"
}
bls_select_source_system_entry() {
  # Select a non-fallback system-*.conf source, preferring the currently booted root/rootflags.
  local dir="$1"
  local -a entries=()
  local f
  shopt -s nullglob
  for f in "$dir"/system-*.conf; do
    bls_entry_is_vfio_fallback "$f" && continue
    entries+=("$f")
  done
  shopt -u nullglob
  (( ${#entries[@]} > 0 )) || return 1

  local running_cmdline running_root_tok running_rootflags_tok
  running_cmdline="$(cat /proc/cmdline 2>/dev/null || true)"
  running_root_tok="$(cmdline_get_key_value_token "$running_cmdline" "root" 2>/dev/null || true)"
  running_rootflags_tok="$(cmdline_get_key_value_token "$running_cmdline" "rootflags" 2>/dev/null || true)"

  local entry entry_opts entry_root_tok entry_rootflags_tok
  if [[ -n "$running_root_tok" ]]; then
    for entry in "${entries[@]}"; do
      entry_opts="$(bls_entry_options "$entry")"
      entry_opts="$(trim "${entry_opts:-}")"
      [[ -n "$entry_opts" ]] || continue
      entry_root_tok="$(cmdline_get_key_value_token "$entry_opts" "root" 2>/dev/null || true)"
      [[ "$entry_root_tok" == "$running_root_tok" ]] || continue
      if [[ -n "$running_rootflags_tok" ]]; then
        entry_rootflags_tok="$(cmdline_get_key_value_token "$entry_opts" "rootflags" 2>/dev/null || true)"
        [[ "$entry_rootflags_tok" == "$running_rootflags_tok" ]] || continue
      fi
      printf '%s\n' "$entry"
      return 0
    done
  fi

  printf '%s\n' "${entries[0]}"
}
bls_render_fallback_entry_from_source() {
  # Emit fallback entry content from a source BLS entry.
  local source="$1"
  local line marker_written=0 options_seen=0
  local opts sanitized title
  while IFS= read -r line || [[ -n "$line" ]]; do
    # Normalize marker placement by writing one canonical marker ourselves.
    if [[ "$line" =~ ^#\ vfio-fallback-entry: ]]; then
      continue
    fi

    if [[ "$line" =~ ^title[[:space:]]+ ]]; then
      title="$(sed -E 's/^title[[:space:]]+//' <<<"$line")"
      if [[ "$title" != *"(fallback)"* ]]; then
        line="title ${title} (fallback)"
      fi
    fi

    if [[ "$line" =~ ^options[[:space:]]+ ]]; then
      if (( marker_written == 0 )); then
        printf '# vfio-fallback-entry: 1\n'
        marker_written=1
      fi
      opts="$(sed -E 's/^options[[:space:]]+//' <<<"$line")"
      sanitized="$(bls_strip_vfio_forcing_tokens_from_options "$opts")"
      printf 'options %s\n' "$sanitized"
      options_seen=1
      continue
    fi

    printf '%s\n' "$line"
  done <"$source"

  if (( marker_written == 0 )); then
    printf '# vfio-fallback-entry: 1\n'
  fi
  if (( options_seen == 0 )); then
    printf 'options \n'
  fi
}
create_or_update_bls_fallback_entry() {
  local fail_count=0
  local -a fail_assertions=()

  if ! is_opensuse_like; then
    (( fail_count += 1 ))
    fail_assertions+=("opensuse_like_required")
  fi

  local bl
  bl="$(detect_bootloader 2>/dev/null || true)"
  if [[ "$bl" != "grub2-bls" && "$bl" != "systemd-boot" ]]; then
    (( fail_count += 1 ))
    fail_assertions+=("bls_bootloader_required:detected=${bl:-unknown}")
  fi

  local dir
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    (( fail_count += 1 ))
    fail_assertions+=("bls_entries_dir_present")
  fi

  local source_entry=""
  if [[ -n "$dir" ]]; then
    source_entry="$(bls_select_source_system_entry "$dir" 2>/dev/null || true)"
    if [[ -z "$source_entry" || ! -f "$source_entry" ]]; then
      (( fail_count += 1 ))
      fail_assertions+=("source_system_entry_present")
    fi
  fi

  local target_entry=""
  if [[ -n "$source_entry" ]]; then
    target_entry="$(bls_fallback_entry_target_path "$source_entry")"
    if [[ "$target_entry" == "$source_entry" ]]; then
      (( fail_count += 1 ))
      fail_assertions+=("target_entry_distinct_from_source")
    fi
  fi

  local tmp=""
  if [[ -n "$source_entry" ]]; then
    tmp="$(mktemp)"
    bls_render_fallback_entry_from_source "$source_entry" >"$tmp"

    local candidate_opts
    candidate_opts="$(bls_entry_options "$tmp")"
    candidate_opts="$(trim "${candidate_opts:-}")"
    if ! grep -Eq '^# vfio-fallback-entry:[[:space:]]*1([[:space:]]*)?$' "$tmp" 2>/dev/null; then
      (( fail_count += 1 ))
      fail_assertions+=("fallback_marker_present_in_rendered_entry")
    fi
    if [[ -z "$candidate_opts" ]]; then
      (( fail_count += 1 ))
      fail_assertions+=("fallback_options_line_present")
    elif bls_options_has_forbidden_vfio_tokens "$candidate_opts"; then
      (( fail_count += 1 ))
      fail_assertions+=("fallback_options_forbidden_tokens_absent")
    fi
  fi

  if (( fail_count > 0 )); then
    if [[ -n "$tmp" ]]; then
      rm -f "$tmp" || true
    fi
    say "FAIL SUMMARY (${fail_count})"
    local item
    for item in "${fail_assertions[@]}"; do
      say "  - assertion: $item"
    done
    return 1
  fi

  local target_existed=0 changed=1 wrote=0
  if [[ -f "$target_entry" ]]; then
    target_existed=1
    if have_cmd cmp && cmp -s "$tmp" "$target_entry"; then
      changed=0
    fi
  fi

  if (( changed )); then
    if (( DRY_RUN )); then
      if (( target_existed )); then
        say "DRY RUN: would update fallback BLS entry $(basename "$target_entry") from source $(basename "$source_entry")."
      else
        say "DRY RUN: would create fallback BLS entry $(basename "$target_entry") from source $(basename "$source_entry")."
      fi
    else
      local mode owner group
      if (( target_existed )); then
        backup_file "$target_entry"
        mode="$(stat -c '%a' "$target_entry")"
        owner="$(stat -c '%u' "$target_entry")"
        group="$(stat -c '%g' "$target_entry")"
      else
        mode="$(stat -c '%a' "$source_entry" 2>/dev/null || echo 644)"
        owner="$(stat -c '%u' "$source_entry" 2>/dev/null || id -u)"
        group="$(stat -c '%g' "$source_entry" 2>/dev/null || id -g)"
      fi
      install -o "$owner" -g "$group" -m "$mode" "$tmp" "$target_entry"
      wrote=1
    fi
  fi

  local verify_path verify_opts
  verify_path="$tmp"
  if (( ! DRY_RUN )); then
    verify_path="$target_entry"
  fi
  verify_opts="$(bls_entry_options "$verify_path")"
  verify_opts="$(trim "${verify_opts:-}")"
  if ! bls_entry_is_vfio_fallback "$verify_path"; then
    (( fail_count += 1 ))
    fail_assertions+=("fallback_marker_present_in_written_entry")
  fi
  if [[ -z "$verify_opts" ]]; then
    (( fail_count += 1 ))
    fail_assertions+=("written_fallback_options_line_present")
  elif bls_options_has_forbidden_vfio_tokens "$verify_opts"; then
    (( fail_count += 1 ))
    fail_assertions+=("written_fallback_options_forbidden_tokens_absent")
  fi

  rm -f "$tmp" || true

  if (( fail_count > 0 )); then
    say "FAIL SUMMARY (${fail_count})"
    local item
    for item in "${fail_assertions[@]}"; do
      say "  - assertion: $item"
    done
    return 1
  fi

  if (( ! DRY_RUN )); then
    if (( changed )); then
      if (( target_existed )); then
        say "Updated fallback BLS entry: $(basename "$target_entry")"
      else
        say "Created fallback BLS entry: $(basename "$target_entry")"
      fi
    else
      say "Fallback BLS entry already up to date: $(basename "$target_entry")"
    fi
  fi
  say "Source BLS entry: $(basename "$source_entry")"
  say "PASS SUMMARY (1)"
  say "Fallback entry verification passed."
  if (( ! DRY_RUN )) && (( wrote == 0 )) && (( changed == 0 )); then
    return 0
  fi
  return 0
}
bls_fallback_entry_detect_status() {
  # Read-only status report for openSUSE BLS fallback readiness.
  # Emits key=value lines:
  #   BOOTLOADER, STATUS, REASON, SOURCE_ENTRY, TARGET_ENTRY
  local bootloader status reason source_entry target_entry dir target_opts tmp
  local in_sync

  bootloader="$(detect_bootloader 2>/dev/null || true)"
  status="NOT_APPLICABLE"
  reason=""
  source_entry=""
  target_entry=""
  in_sync=0

  if ! is_opensuse_like; then
    reason="openSUSE-like system not detected"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=\n'
    printf 'TARGET_ENTRY=\n'
    return 0
  fi

  if [[ "$bootloader" != "grub2-bls" && "$bootloader" != "systemd-boot" ]]; then
    reason="Boot Loader Spec fallback applies only to grub2-bls/systemd-boot (detected: ${bootloader:-unknown})"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=\n'
    printf 'TARGET_ENTRY=\n'
    return 0
  fi

  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    status="INVALID"
    reason="Boot Loader Spec entries directory not found"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=\n'
    printf 'TARGET_ENTRY=\n'
    return 0
  fi

  source_entry="$(bls_select_source_system_entry "$dir" 2>/dev/null || true)"
  if [[ -z "$source_entry" || ! -f "$source_entry" ]]; then
    status="INVALID"
    reason="Source system BLS entry was not found"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=\n'
    printf 'TARGET_ENTRY=\n'
    return 0
  fi

  target_entry="$(bls_fallback_entry_target_path "$source_entry")"
  if [[ -z "$target_entry" ]]; then
    status="INVALID"
    reason="Could not derive fallback entry path from source"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=%s\n' "$source_entry"
    printf 'TARGET_ENTRY=\n'
    return 0
  fi

  if [[ ! -f "$target_entry" ]]; then
    status="MISSING"
    reason="Fallback entry file is missing"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=%s\n' "$source_entry"
    printf 'TARGET_ENTRY=%s\n' "$target_entry"
    return 0
  fi

  target_opts="$(bls_entry_options "$target_entry")"
  target_opts="$(trim "${target_opts:-}")"
  if ! bls_entry_is_vfio_fallback "$target_entry"; then
    status="INVALID"
    reason="Fallback marker is missing from fallback entry"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=%s\n' "$source_entry"
    printf 'TARGET_ENTRY=%s\n' "$target_entry"
    return 0
  fi
  if [[ -z "$target_opts" ]]; then
    status="INVALID"
    reason="Fallback entry options line is missing"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=%s\n' "$source_entry"
    printf 'TARGET_ENTRY=%s\n' "$target_entry"
    return 0
  fi
  if bls_options_has_forbidden_vfio_tokens "$target_opts"; then
    status="INVALID"
    reason="Fallback entry options still contain VFIO-forcing tokens"
    printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
    printf 'STATUS=%s\n' "$status"
    printf 'REASON=%s\n' "$reason"
    printf 'SOURCE_ENTRY=%s\n' "$source_entry"
    printf 'TARGET_ENTRY=%s\n' "$target_entry"
    return 0
  fi

  tmp="$(mktemp)"
  bls_render_fallback_entry_from_source "$source_entry" >"$tmp"
  if have_cmd cmp; then
    if cmp -s "$tmp" "$target_entry"; then
      in_sync=1
    fi
  elif have_cmd diff; then
    if diff -q "$tmp" "$target_entry" >/dev/null 2>&1; then
      in_sync=1
    fi
  else
    if [[ "$(cat "$tmp" 2>/dev/null || true)" == "$(cat "$target_entry" 2>/dev/null || true)" ]]; then
      in_sync=1
    fi
  fi
  rm -f "$tmp" || true

  if (( in_sync )); then
    status="OK"
    reason="Fallback entry is present and synchronized with source entry"
  else
    status="OUTDATED"
    reason="Fallback entry exists but differs from expected rendered fallback"
  fi

  printf 'BOOTLOADER=%s\n' "${bootloader:-unknown}"
  printf 'STATUS=%s\n' "$status"
  printf 'REASON=%s\n' "$reason"
  printf 'SOURCE_ENTRY=%s\n' "$source_entry"
  printf 'TARGET_ENTRY=%s\n' "$target_entry"
}
maybe_offer_detect_fallback_entry_create() {
  [[ "${MODE:-}" == "detect" ]] || return 0

  local report status reason source_entry target_entry bootloader
  report="$(bls_fallback_entry_detect_status)"
  status=""
  reason=""
  source_entry=""
  target_entry=""
  bootloader=""

  local key value
  while IFS='=' read -r key value; do
    case "$key" in
      BOOTLOADER) bootloader="$value" ;;
      STATUS) status="$value" ;;
      REASON) reason="$value" ;;
      SOURCE_ENTRY) source_entry="$value" ;;
      TARGET_ENTRY) target_entry="$value" ;;
    esac
  done <<<"$report"

  [[ -n "$status" ]] || return 0
  [[ "$status" == "NOT_APPLICABLE" ]] && return 0

  local source_name target_name
  source_name="<unknown>"
  target_name="<unknown>"
  [[ -n "$source_entry" ]] && source_name="$(basename "$source_entry")"
  [[ -n "$target_entry" ]] && target_name="$(basename "$target_entry")"

  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}-- Boot Loader Spec fallback entry (openSUSE-specific) --${C_RESET}"
  else
    say "-- Boot Loader Spec fallback entry (openSUSE-specific) --"
  fi
  print_kv "Bootloader (detected)" "${bootloader:-unknown}"
  print_kv "Source entry" "$source_name"
  print_kv "Fallback entry" "$target_name"

  case "$status" in
    OK)
      print_kv "Fallback status" "OK (synchronized)"
      return 0
      ;;
    MISSING)
      print_kv "Fallback status" "MISSING"
      ;;
    OUTDATED)
      print_kv "Fallback status" "OUTDATED"
      ;;
    INVALID)
      print_kv "Fallback status" "INVALID"
      ;;
    *)
      print_kv "Fallback status" "$status"
      ;;
  esac

  [[ -n "$reason" ]] && note "Reason: $reason"
  note "Recommendation: run $SCRIPT_NAME --create-fallback-entry"

  if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
    note "Run as root to create or update the fallback entry."
    return 0
  fi

  if ! prompt_yn "Create/update fallback BLS entry now from detect mode?" N "BLS fallback entry"; then
    return 0
  fi
  if ! confirm_phrase "This will edit Boot Loader Spec entry files now." "CREATE FALLBACK ENTRY"; then
    note "Skipping fallback entry remediation (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0
  if create_or_update_bls_fallback_entry; then
    say "Fallback entry remediation completed from detect mode."
  else
    note "Fallback entry remediation failed; review FAIL SUMMARY above."
  fi
  DRY_RUN="$prev_dry"
}

# Enforce that every Boot Loader Spec entry options line follows the current
# /etc/kernel/cmdline baseline while preserving per-entry root metadata needed
# for snapshot-aware boots.
sync_bls_entries_from_kernel_cmdline() {
  if ! is_opensuse_like; then
    return 0
  fi

  local bl
  bl="$(detect_bootloader 2>/dev/null || true)"
  if [[ "$bl" != "grub2-bls" && "$bl" != "systemd-boot" ]]; then
    return 0
  fi

  local cmdline_file
  cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  cmdline_file="$(trim "${cmdline_file:-}")"
  if [[ -z "$cmdline_file" ]]; then
    note "Skipping BLS entry sync: kernel cmdline persistence path is empty."
    return 0
  fi

  if [[ ! -f "$cmdline_file" ]]; then
    note "Skipping BLS entry sync: $cmdline_file is missing."
    return 0
  fi
  kernel_cmdline_rehydrate_boot_metadata_if_missing "$cmdline_file" || true
  kernel_cmdline_reconcile_boot_metadata_with_current_mount "$cmdline_file" || true

  local base_cmdline
  base_cmdline="$(cat "$cmdline_file" 2>/dev/null || true)"
  base_cmdline="$(trim "${base_cmdline:-}")"
  if [[ -z "$base_cmdline" ]]; then
    note "Skipping BLS entry sync: $cmdline_file is empty."
    return 0
  fi
  local fallback_metadata_opts
  local base_file_root_tok base_file_rootflags_tok
  local base_fallback_root_tok base_fallback_rootflags_tok
  local mount_root_tok mount_rootflags_tok
  local proc_root_tok proc_rootflags_tok
  local base_root_source base_rootflags_source
  local running_boot_opts running_root_tok
  fallback_metadata_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
  base_file_root_tok="$(cmdline_get_key_value_token "$base_cmdline" "root" 2>/dev/null || true)"
  base_file_rootflags_tok="$(cmdline_get_key_value_token "$base_cmdline" "rootflags" 2>/dev/null || true)"
  base_fallback_root_tok=""
  base_fallback_rootflags_tok=""
  mount_root_tok=""
  mount_rootflags_tok=""
  proc_root_tok=""
  proc_rootflags_tok=""
  base_root_source=""
  base_rootflags_source=""
  running_boot_opts=""
  running_root_tok=""
  if [[ -n "$base_file_root_tok" ]]; then
    base_root_source="kernel_cmdline_file"
  fi
  if [[ -n "$base_file_rootflags_tok" ]]; then
    base_rootflags_source="kernel_cmdline_file"
  fi

  if [[ -n "$fallback_metadata_opts" ]]; then
    base_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$base_cmdline" "$fallback_metadata_opts")"
    base_fallback_root_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "root" 2>/dev/null || true)"
    base_fallback_rootflags_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "rootflags" 2>/dev/null || true)"
    if [[ -n "$base_fallback_root_tok" ]]; then
      base_root_source="bls_metadata_options"
    fi
    if [[ -n "$base_fallback_rootflags_tok" ]]; then
      base_rootflags_source="bls_metadata_options"
    fi
  fi
  if ! cmdline_get_key_value_token "$base_cmdline" "root" >/dev/null 2>&1; then
    mount_root_tok="$(bls_current_mount_root_token 2>/dev/null || true)"
    mount_rootflags_tok="$(bls_current_mount_rootflags_token 2>/dev/null || true)"
    if [[ -n "$mount_root_tok" ]]; then
      base_cmdline="$(cmdline_set_key_value_token "$base_cmdline" "$mount_root_tok")"
      base_root_source="current_mount_metadata"
    fi
    if [[ -n "$mount_rootflags_tok" ]]; then
      base_cmdline="$(cmdline_set_key_value_token "$base_cmdline" "$mount_rootflags_tok")"
      base_rootflags_source="current_mount_metadata"
    fi
  fi
  if ! cmdline_get_key_value_token "$base_cmdline" "root" >/dev/null 2>&1; then
    running_boot_opts="$(cat /proc/cmdline 2>/dev/null || true)"
    if [[ -n "$running_boot_opts" ]]; then
      proc_root_tok="$(cmdline_get_key_value_token "$running_boot_opts" "root" 2>/dev/null || true)"
      proc_rootflags_tok="$(cmdline_get_key_value_token "$running_boot_opts" "rootflags" 2>/dev/null || true)"
      base_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$base_cmdline" "$running_boot_opts")"
      running_root_tok="$(cmdline_get_key_value_token "$base_cmdline" "root" 2>/dev/null || true)"
      if [[ -n "$running_root_tok" ]]; then
        base_root_source="proc_cmdline"
        [[ -n "$proc_rootflags_tok" ]] && base_rootflags_source="proc_cmdline"
        note "Recovered root boot metadata for BLS sync baseline from running /proc/cmdline."
      fi
    fi
  fi
  if ! cmdline_get_key_value_token "$base_cmdline" "root" >/dev/null 2>&1; then
    note "BLS sync baseline has no global root=... metadata after trying $cmdline_file, BLS backups, current mount metadata, and /proc/cmdline."
    note "Continuing with per-entry root preservation; entries without provable root metadata will be skipped for safety."
  fi
  local base_root_tok base_rootflags_tok base_rootfstype_tok base_resume_tok base_machine_id_tok
  base_root_tok="$(cmdline_get_key_value_token "$base_cmdline" "root" 2>/dev/null || true)"
  base_rootflags_tok="$(cmdline_get_key_value_token "$base_cmdline" "rootflags" 2>/dev/null || true)"
  base_rootfstype_tok="$(cmdline_get_key_value_token "$base_cmdline" "rootfstype" 2>/dev/null || true)"
  base_resume_tok="$(cmdline_get_key_value_token "$base_cmdline" "resume" 2>/dev/null || true)"
  base_machine_id_tok="$(cmdline_get_key_value_token "$base_cmdline" "systemd.machine_id" 2>/dev/null || true)"
  if [[ -z "$base_root_source" ]]; then
    [[ -n "$base_root_tok" ]] && base_root_source="unknown"
  fi
  if [[ -z "$base_rootflags_source" ]]; then
    [[ -n "$base_rootflags_tok" ]] && base_rootflags_source="unknown"
  fi
  if (( DEBUG_CMDLINE_TOKENS )); then
    say "DEBUG[BLS baseline-candidate]: kernel_cmdline root=${base_file_root_tok:-<none>} rootflags=${base_file_rootflags_tok:-<none>}"
    say "DEBUG[BLS baseline-candidate]: bls_metadata root=${base_fallback_root_tok:-<none>} rootflags=${base_fallback_rootflags_tok:-<none>}"
    say "DEBUG[BLS baseline-candidate]: current_mount root=${mount_root_tok:-<none>} rootflags=${mount_rootflags_tok:-<none>}"
    say "DEBUG[BLS baseline-candidate]: proc_cmdline root=${proc_root_tok:-<none>} rootflags=${proc_rootflags_tok:-<none>}"
    say "DEBUG[BLS baseline]: root source=${base_root_source:-none} token=${base_root_tok:-<none>}"
    say "DEBUG[BLS baseline]: rootflags source=${base_rootflags_source:-none} token=${base_rootflags_tok:-<none>}"
  fi

  local dir
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    note "Skipping BLS entry sync: loader entries directory was not found."
    return 0
  fi

  local -a entries=()
  local f
  shopt -s nullglob
  for f in "$dir"/*.conf; do
    entries+=("$f")
  done
  shopt -u nullglob

  if (( ${#entries[@]} == 0 )); then
    note "Skipping BLS entry sync: no *.conf entries found under $dir."
    return 0
  fi

  local changed=0 examined=0 snapper_skipped=0 root_examined=0 fallback_skipped=0 root_missing_skipped=0
  local debug_filter_skipped=0
  local current_opts merged_opts root_tok rootflags_tok rootfstype_tok resume_tok machine_id_tok root_source rootflags_source
  local entry_snapshot_id entry_snapshot_rootflags_tok current_rootflags_snapshot_id
  local entry_backup_opts backup_root_tok backup_rootflags_tok backup_rootfstype_tok backup_resume_tok backup_machine_id_tok
  local entry_name
  for f in "${entries[@]}"; do
    entry_name="$(basename "$f")"
    if bls_entry_is_vfio_fallback "$f"; then
      (( fallback_skipped += 1 ))
      continue
    fi
    if [[ "$entry_name" == snapper-* ]]; then
      (( snapper_skipped += 1 ))
      continue
    fi
    if (( DEBUG_CMDLINE_TOKENS )) && [[ -n "${DEBUG_CMDLINE_TOKENS_ENTRY_FILTER:-}" ]]; then
      # shellcheck disable=SC2053
      if [[ "$entry_name" != $DEBUG_CMDLINE_TOKENS_ENTRY_FILTER ]]; then
        (( debug_filter_skipped += 1 ))
        continue
      fi
    fi
    current_opts="$(grep -m1 -E '^options[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
    current_opts="$(trim "${current_opts:-}")"
    [[ -n "$current_opts" ]] || continue
    (( examined += 1 ))
    (( root_examined += 1 ))

    merged_opts="$base_cmdline"
    root_tok="$(cmdline_get_key_value_token "$current_opts" "root" 2>/dev/null || true)"
    rootflags_tok="$(cmdline_get_key_value_token "$current_opts" "rootflags" 2>/dev/null || true)"
    rootfstype_tok="$(cmdline_get_key_value_token "$current_opts" "rootfstype" 2>/dev/null || true)"
    resume_tok="$(cmdline_get_key_value_token "$current_opts" "resume" 2>/dev/null || true)"
    machine_id_tok="$(cmdline_get_key_value_token "$current_opts" "systemd.machine_id" 2>/dev/null || true)"
    root_source=""
    rootflags_source=""
    [[ -n "$root_tok" ]] && root_source="entry_options"
    [[ -n "$rootflags_tok" ]] && rootflags_source="entry_options"
    entry_backup_opts="$(bls_find_entry_backup_metadata_options "$f" 2>/dev/null || true)"
    backup_root_tok=""
    backup_rootflags_tok=""
    backup_rootfstype_tok=""
    backup_resume_tok=""
    backup_machine_id_tok=""
    if [[ -n "$entry_backup_opts" ]]; then
      backup_root_tok="$(cmdline_get_key_value_token "$entry_backup_opts" "root" 2>/dev/null || true)"
      backup_rootflags_tok="$(cmdline_get_key_value_token "$entry_backup_opts" "rootflags" 2>/dev/null || true)"
      backup_rootfstype_tok="$(cmdline_get_key_value_token "$entry_backup_opts" "rootfstype" 2>/dev/null || true)"
      backup_resume_tok="$(cmdline_get_key_value_token "$entry_backup_opts" "resume" 2>/dev/null || true)"
      backup_machine_id_tok="$(cmdline_get_key_value_token "$entry_backup_opts" "systemd.machine_id" 2>/dev/null || true)"

      if [[ -n "$backup_root_tok" ]]; then
        if [[ -z "$root_tok" ]]; then
          root_tok="$backup_root_tok"
          root_source="entry_backup"
        elif [[ -n "$base_root_tok" && "$root_tok" == "$base_root_tok" && "$backup_root_tok" != "$base_root_tok" ]]; then
          root_tok="$backup_root_tok"
          root_source="entry_backup_preferred_over_baseline"
        fi
      fi
      if [[ -n "$backup_rootflags_tok" ]]; then
        if [[ -z "$rootflags_tok" ]]; then
          rootflags_tok="$backup_rootflags_tok"
          rootflags_source="entry_backup"
        elif [[ -n "$base_rootflags_tok" && "$rootflags_tok" == "$base_rootflags_tok" && "$backup_rootflags_tok" != "$base_rootflags_tok" ]]; then
          rootflags_tok="$backup_rootflags_tok"
          rootflags_source="entry_backup_preferred_over_baseline"
        fi
      fi
      if [[ -n "$backup_rootfstype_tok" ]]; then
        if [[ -z "$rootfstype_tok" ]]; then
          rootfstype_tok="$backup_rootfstype_tok"
        elif [[ -n "$base_rootfstype_tok" && "$rootfstype_tok" == "$base_rootfstype_tok" && "$backup_rootfstype_tok" != "$base_rootfstype_tok" ]]; then
          rootfstype_tok="$backup_rootfstype_tok"
        fi
      fi
      if [[ -n "$backup_resume_tok" ]]; then
        if [[ -z "$resume_tok" ]]; then
          resume_tok="$backup_resume_tok"
        elif [[ -n "$base_resume_tok" && "$resume_tok" == "$base_resume_tok" && "$backup_resume_tok" != "$base_resume_tok" ]]; then
          resume_tok="$backup_resume_tok"
        fi
      fi
      if [[ -n "$backup_machine_id_tok" ]]; then
        if [[ -z "$machine_id_tok" ]]; then
          machine_id_tok="$backup_machine_id_tok"
        elif [[ -n "$base_machine_id_tok" && "$machine_id_tok" == "$base_machine_id_tok" && "$backup_machine_id_tok" != "$base_machine_id_tok" ]]; then
          machine_id_tok="$backup_machine_id_tok"
        fi
      fi
    fi
    if [[ -z "$root_tok" && -n "$fallback_metadata_opts" ]]; then
      root_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "root" 2>/dev/null || true)"
      [[ -n "$root_tok" ]] && root_source="bls_metadata_options"
    fi
    if [[ -z "$rootflags_tok" && -n "$fallback_metadata_opts" ]]; then
      rootflags_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "rootflags" 2>/dev/null || true)"
      [[ -n "$rootflags_tok" ]] && rootflags_source="bls_metadata_options"
    fi
    if [[ -z "$rootfstype_tok" && -n "$fallback_metadata_opts" ]]; then
      rootfstype_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "rootfstype" 2>/dev/null || true)"
    fi
    if [[ -z "$resume_tok" && -n "$fallback_metadata_opts" ]]; then
      resume_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "resume" 2>/dev/null || true)"
    fi
    if [[ -z "$machine_id_tok" && -n "$fallback_metadata_opts" ]]; then
      machine_id_tok="$(cmdline_get_key_value_token "$fallback_metadata_opts" "systemd.machine_id" 2>/dev/null || true)"
    fi
    entry_snapshot_id="$(bls_entry_snapshot_id "$f" 2>/dev/null || true)"
    if [[ -n "$entry_snapshot_id" ]]; then
      entry_snapshot_rootflags_tok="$(bls_rootflags_token_for_snapshot_id "$entry_snapshot_id" 2>/dev/null || true)"
      current_rootflags_snapshot_id="$(rootflags_snapshot_id_from_token "${rootflags_tok:-}" 2>/dev/null || true)"
      if [[ -n "$entry_snapshot_rootflags_tok" ]] && [[ "$current_rootflags_snapshot_id" != "$entry_snapshot_id" ]]; then
        rootflags_tok="$entry_snapshot_rootflags_tok"
        rootflags_source="entry_snapshot_filename"
      fi
    fi
    if [[ -z "$root_tok" ]]; then
      if [[ -n "$base_root_tok" ]]; then
        root_tok="$base_root_tok"
        root_source="baseline_cmdline"
      else
        (( root_missing_skipped += 1 ))
        if (( DEBUG_CMDLINE_TOKENS )); then
          say "DEBUG[BLS entry ${entry_name}]: root source=none token=<none> (skipped)"
          say "DEBUG[BLS entry ${entry_name}]: rootflags source=${rootflags_source:-none} token=${rootflags_tok:-<none>}"
        fi
        note "Skipping BLS sync for ${entry_name}: unable to determine root=... metadata for this entry."
        continue
      fi
    fi
    if (( DEBUG_CMDLINE_TOKENS )); then
      local debug_rootflags_tok
      debug_rootflags_tok="${rootflags_tok:-}"
      if [[ -z "$debug_rootflags_tok" && -n "$base_rootflags_tok" ]]; then
        debug_rootflags_tok="$base_rootflags_tok"
        [[ -z "$rootflags_source" ]] && rootflags_source="baseline_cmdline"
      fi
      say "DEBUG[BLS entry ${entry_name}]: root source=${root_source:-none} token=${root_tok:-<none>}"
      say "DEBUG[BLS entry ${entry_name}]: rootflags source=${rootflags_source:-none} token=${debug_rootflags_tok:-<none>}"
    fi

    [[ -n "$root_tok" ]] && merged_opts="$(cmdline_set_key_value_token "$merged_opts" "$root_tok")"
    [[ -n "$rootflags_tok" ]] && merged_opts="$(cmdline_set_key_value_token "$merged_opts" "$rootflags_tok")"
    [[ -n "$rootfstype_tok" ]] && merged_opts="$(cmdline_set_key_value_token "$merged_opts" "$rootfstype_tok")"
    [[ -n "$resume_tok" ]] && merged_opts="$(cmdline_set_key_value_token "$merged_opts" "$resume_tok")"
    [[ -n "$machine_id_tok" ]] && merged_opts="$(cmdline_set_key_value_token "$merged_opts" "$machine_id_tok")"

    if grep -Eq '(^|[[:space:]])ro([[:space:]]|$)' <<<"$current_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "ro")"
    elif [[ -n "$entry_backup_opts" ]] && grep -Eq '(^|[[:space:]])ro([[:space:]]|$)' <<<"$entry_backup_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "ro")"
    elif [[ -n "$fallback_metadata_opts" ]] && grep -Eq '(^|[[:space:]])ro([[:space:]]|$)' <<<"$fallback_metadata_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "ro")"
    fi
    if grep -Eq '(^|[[:space:]])rw([[:space:]]|$)' <<<"$current_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "rw")"
    elif [[ -n "$entry_backup_opts" ]] && grep -Eq '(^|[[:space:]])rw([[:space:]]|$)' <<<"$entry_backup_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "rw")"
    elif [[ -n "$fallback_metadata_opts" ]] && grep -Eq '(^|[[:space:]])rw([[:space:]]|$)' <<<"$fallback_metadata_opts"; then
      merged_opts="$(add_param_once "$merged_opts" "rw")"
    fi

    merged_opts="$(trim "$merged_opts")"
    if [[ "$merged_opts" == "$current_opts" ]]; then
      continue
    fi

    systemd_boot_write_options "$f" "$merged_opts"
    (( changed += 1 ))
  done

  if (( changed == 0 )); then
    if (( root_missing_skipped > 0 )) || (( debug_filter_skipped > 0 )); then
      note "No Boot Loader Spec entries were synchronized from /etc/kernel/cmdline (${examined} root/system entries checked, ${root_missing_skipped} skipped due missing root metadata, ${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped, ${debug_filter_skipped} filtered by --entry)."
    else
      note "Boot Loader Spec options are already synchronized with /etc/kernel/cmdline (${examined} root/system entries checked, ${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped)."
    fi
    return 0
  fi

  local entry_word="entries"
  if (( changed == 1 )); then
    entry_word="entry"
  fi
  if (( DRY_RUN )); then
    say "DRY RUN: would synchronize ${changed} Boot Loader Spec ${entry_word} from $cmdline_file (${examined} root/system entries checked, ${root_missing_skipped} skipped due missing root metadata, ${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped, ${debug_filter_skipped} filtered by --entry)."
  else
    say "Synchronized ${changed} Boot Loader Spec ${entry_word} from $cmdline_file (preserved per-entry root/rootflags/systemd.machine_id metadata; ${examined} root/system entries checked, ${root_missing_skipped} skipped due missing root metadata, ${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped, ${debug_filter_skipped} filtered by --entry)."
  fi
  return 0
}
debug_bls_cmdline_tokens() {
  local prev_debug="${DEBUG_CMDLINE_TOKENS:-0}"
  local prev_dry="${DRY_RUN:-0}"
  local rc=0
  local sync_output=""

  DEBUG_CMDLINE_TOKENS=1
  DRY_RUN=1

  if (( JSON_OUTPUT )); then
    if sync_output="$(sync_bls_entries_from_kernel_cmdline)"; then
      rc=0
    else
      rc=$?
    fi
    debug_cmdline_tokens_print_json_lines "$sync_output" "$rc"
  else
    say
    hdr "BLS cmdline token source debug"
    note "Tracing root/rootflags source selection in read-only dry-run mode."
    if [[ -n "${DEBUG_CMDLINE_TOKENS_ENTRY_FILTER:-}" ]]; then
      note "Applying entry filter: ${DEBUG_CMDLINE_TOKENS_ENTRY_FILTER}"
    fi
    sync_bls_entries_from_kernel_cmdline || rc=$?
  fi

  DRY_RUN="$prev_dry"
  DEBUG_CMDLINE_TOKENS="$prev_debug"
  return "$rc"
}
verify_bls_entries_against_kernel_cmdline() {
  local fail_count=0
  local -a fail_assertions=()

  if ! is_opensuse_like; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: opensuse_like_required"
    say "    detail: this verification mode is intended for openSUSE-style BLS systems"
    return 1
  fi

  local bl
  bl="$(detect_bootloader 2>/dev/null || true)"
  if [[ "$bl" != "grub2-bls" && "$bl" != "systemd-boot" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: bls_bootloader_required"
    say "    detail: detected bootloader '$bl' (expected grub2-bls or systemd-boot)"
    return 1
  fi

  local cmdline_file
  cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  cmdline_file="$(trim "${cmdline_file:-}")"
  if [[ -z "$cmdline_file" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: kernel_cmdline_path_nonempty"
    say "    detail: kernel cmdline persistence path is empty"
    return 1
  fi
  if [[ ! -f "$cmdline_file" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: kernel_cmdline_file_present"
    say "    detail: missing $cmdline_file"
    return 1
  fi

  local base_cmdline
  base_cmdline="$(cat "$cmdline_file" 2>/dev/null || true)"
  base_cmdline="$(trim "${base_cmdline:-}")"
  if [[ -z "$base_cmdline" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: kernel_cmdline_nonempty"
    say "    detail: $cmdline_file is empty"
    return 1
  fi
  if ! cmdline_get_key_value_token "$base_cmdline" "root" >/dev/null 2>&1; then
    (( fail_count += 1 ))
    fail_assertions+=("kernel_cmdline_root_token_present")
  fi
  local mount_root_tok mount_rootflags_tok base_root_tok base_rootflags_tok
  mount_root_tok="$(bls_current_mount_root_token 2>/dev/null || true)"
  mount_rootflags_tok="$(bls_current_mount_rootflags_token 2>/dev/null || true)"
  base_root_tok="$(cmdline_get_key_value_token "$base_cmdline" "root" 2>/dev/null || true)"
  base_rootflags_tok="$(cmdline_get_key_value_token "$base_cmdline" "rootflags" 2>/dev/null || true)"
  if [[ -n "$mount_root_tok" && "$base_root_tok" != "$mount_root_tok" ]]; then
    (( fail_count += 1 ))
    fail_assertions+=("kernel_cmdline_root_matches_current_mount")
  fi
  if [[ -n "$mount_rootflags_tok" && "$base_rootflags_tok" != "$mount_rootflags_tok" ]]; then
    (( fail_count += 1 ))
    fail_assertions+=("kernel_cmdline_rootflags_matches_current_mount")
  fi

  local expected_base_cmdline
  expected_base_cmdline="$base_cmdline"
  local fallback_metadata_opts
  fallback_metadata_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
  if [[ -n "$fallback_metadata_opts" ]]; then
    expected_base_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$expected_base_cmdline" "$fallback_metadata_opts")"
  fi
  if ! cmdline_get_key_value_token "$expected_base_cmdline" "root" >/dev/null 2>&1; then
    (( fail_count += 1 ))
    fail_assertions+=("kernel_cmdline_effective_root_token_present")
  fi

  local dir
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: bls_entries_dir_present"
    say "    detail: loader entries directory was not found"
    return 1
  fi

  local -a entries=()
  local f
  shopt -s nullglob
  for f in "$dir"/*.conf; do
    entries+=("$f")
  done
  shopt -u nullglob
  if (( ${#entries[@]} == 0 )); then
    say "FAIL SUMMARY (1)"
    say "  - assertion: bls_entries_present"
    say "    detail: no *.conf entries found under $dir"
    return 1
  fi

  local examined=0 snapper_skipped=0 root_examined=0 fallback_skipped=0
  local current_opts expected_opts root_tok rootflags_tok rootfstype_tok resume_tok machine_id_tok tok
  local -a missing_tokens=() extra_tokens=()
  for f in "${entries[@]}"; do
    if bls_entry_is_vfio_fallback "$f"; then
      (( fallback_skipped += 1 ))
      continue
    fi
    if [[ "$(basename "$f")" == snapper-* ]]; then
      (( snapper_skipped += 1 ))
      continue
    fi
    current_opts="$(grep -m1 -E '^options[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
    current_opts="$(trim "${current_opts:-}")"
    if [[ -z "$current_opts" ]]; then
      (( fail_count += 1 ))
      fail_assertions+=("options_line_present:$(basename "$f")")
      continue
    fi
    if ! cmdline_get_key_value_token "$current_opts" "root" >/dev/null 2>&1; then
      (( fail_count += 1 ))
      fail_assertions+=("entry_root_token_present:$(basename "$f")")
    fi

    (( examined += 1 ))
    (( root_examined += 1 ))

    expected_opts="$expected_base_cmdline"
    root_tok="$(cmdline_get_key_value_token "$current_opts" "root" 2>/dev/null || true)"
    rootflags_tok="$(cmdline_get_key_value_token "$current_opts" "rootflags" 2>/dev/null || true)"
    rootfstype_tok="$(cmdline_get_key_value_token "$current_opts" "rootfstype" 2>/dev/null || true)"
    resume_tok="$(cmdline_get_key_value_token "$current_opts" "resume" 2>/dev/null || true)"
    machine_id_tok="$(cmdline_get_key_value_token "$current_opts" "systemd.machine_id" 2>/dev/null || true)"
    [[ -n "$root_tok" ]] && expected_opts="$(cmdline_set_key_value_token "$expected_opts" "$root_tok")"
    [[ -n "$rootflags_tok" ]] && expected_opts="$(cmdline_set_key_value_token "$expected_opts" "$rootflags_tok")"
    [[ -n "$rootfstype_tok" ]] && expected_opts="$(cmdline_set_key_value_token "$expected_opts" "$rootfstype_tok")"
    [[ -n "$resume_tok" ]] && expected_opts="$(cmdline_set_key_value_token "$expected_opts" "$resume_tok")"
    [[ -n "$machine_id_tok" ]] && expected_opts="$(cmdline_set_key_value_token "$expected_opts" "$machine_id_tok")"
    if grep -Eq '(^|[[:space:]])ro([[:space:]]|$)' <<<"$current_opts"; then
      expected_opts="$(add_param_once "$expected_opts" "ro")"
    fi
    if grep -Eq '(^|[[:space:]])rw([[:space:]]|$)' <<<"$current_opts"; then
      expected_opts="$(add_param_once "$expected_opts" "rw")"
    fi
    expected_opts="$(trim "$expected_opts")"

    if [[ "$expected_opts" == "$current_opts" ]]; then
      continue
    fi

    (( fail_count += 1 ))
    fail_assertions+=("options_sync_with_kernel_cmdline:$(basename "$f")")
    missing_tokens=()
    extra_tokens=()
    for tok in $expected_opts; do
      if ! cmdline_contains_exact_token "$current_opts" "$tok"; then
        missing_tokens+=("$tok")
      fi
    done
    for tok in $current_opts; do
      if ! cmdline_contains_exact_token "$expected_opts" "$tok"; then
        extra_tokens+=("$tok")
      fi
    done
    say "DRIFT: $(basename "$f")"
    if (( ${#missing_tokens[@]} > 0 )); then
      say "  missing: ${missing_tokens[*]}"
    fi
    if (( ${#extra_tokens[@]} > 0 )); then
      say "  unexpected: ${extra_tokens[*]}"
    fi
  done

  if (( examined == 0 )); then
    say "FAIL SUMMARY (1)"
    say "  - assertion: nonsnapper_nonfallback_bls_entries_present"
    say "    detail: no non-snapper, non-fallback Boot Loader Spec entries were found under $dir (${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped)"
    return 1
  fi

  if (( fail_count > 0 )); then
    say "FAIL SUMMARY (${fail_count})"
    local item
    for item in "${fail_assertions[@]}"; do
      say "  - assertion: $item"
    done
    say "Checked entries: ${examined} root/system (${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped)"
    return 1
  fi

  say "PASS SUMMARY (${examined})"
  say "All Boot Loader Spec root/system entries are synchronized with $cmdline_file (${root_examined} root/system, ${snapper_skipped} snapper skipped, ${fallback_skipped} fallback skipped)."
  return 0
}
verify_bls_no_snapper_writes() {
  # Regression guard: ensure sync logic never targets snapper-* entries for writes.
  if ! is_opensuse_like; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: opensuse_like_required"
    say "    detail: this regression mode is intended for openSUSE-style BLS systems"
    return 1
  fi

  local bl
  bl="$(detect_bootloader 2>/dev/null || true)"
  if [[ "$bl" != "grub2-bls" && "$bl" != "systemd-boot" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: bls_bootloader_required"
    say "    detail: detected bootloader '$bl' (expected grub2-bls or systemd-boot)"
    return 1
  fi

  local dir
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    say "FAIL SUMMARY (1)"
    say "  - assertion: bls_entries_dir_present"
    say "    detail: loader entries directory was not found"
    return 1
  fi

  local -a snapper_entries=()
  local f
  shopt -s nullglob
  for f in "$dir"/snapper-*.conf; do
    [[ -f "$f" ]] || continue
    snapper_entries+=("$f")
  done
  shopt -u nullglob

  VFIO_BLS_SNAPPER_WRITE_ATTEMPTS=0
  VFIO_BLS_SNAPPER_WRITE_ATTEMPT_PATHS=()

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=1
  sync_bls_entries_from_kernel_cmdline || true
  DRY_RUN="$prev_dry"

  if (( VFIO_BLS_SNAPPER_WRITE_ATTEMPTS > 0 )); then
    say "FAIL SUMMARY (1)"
    say "  - assertion: no_snapper_bls_write_attempts"
    say "    detail: detected ${VFIO_BLS_SNAPPER_WRITE_ATTEMPTS} attempted write target(s) under snapper-* entries"
    local p
    for p in "${VFIO_BLS_SNAPPER_WRITE_ATTEMPT_PATHS[@]}"; do
      say "    attempted: $(basename "$p")"
    done
    return 1
  fi

  if (( ${#snapper_entries[@]} == 0 )); then
    say "PASS SUMMARY (1)"
    say "No snapper-* BLS entries were found under $dir, and no snapper write attempts were observed."
    return 0
  fi

  say "PASS SUMMARY (1)"
  say "No snapper BLS write attempts detected (${#snapper_entries[@]} snapper entries observed)."
  return 0
}

# On openSUSE systems that use Boot Loader Spec (systemd-boot or grub2-bls),
# kernel parameters are persisted via /etc/kernel/cmdline and propagated to
# loader entries using sdbootutil. This helper wraps that propagation so we
# don't rely on editing individual *.conf files by hand.
opensuse_sdbootutil_update_all_entries() {
  if ! is_opensuse_like; then
    return 0
  fi
  local bl
  bl="$(detect_bootloader 2>/dev/null || true)"
  if [[ "$bl" != "grub2-bls" && "$bl" != "systemd-boot" ]]; then
    return 0
  fi

  local cmdline_file
  cmdline_file="$(kernel_cmdline_persistence_file 2>/dev/null || true)"
  cmdline_file="$(trim "${cmdline_file:-}")"
  if [[ -n "$cmdline_file" && -f "$cmdline_file" ]]; then
    kernel_cmdline_rehydrate_boot_metadata_if_missing "$cmdline_file" || true
  fi

  local sdbootutil_ok=0
  if have_cmd sdbootutil; then
    say "Updating Boot Loader Spec entries via: sdbootutil add-all-kernels && sdbootutil update-all-entries (errors will be ignored by this helper)"
    # Call sdbootutil directly and silence its stdout/stderr to avoid leaking
    # internal sed errors or similar implementation details to the user.
    # We try add-all-kernels first (to ensure all installed kernels have
    # BLS entries) and then update-all-entries to sync options/initrds.
    if sdbootutil add-all-kernels >/dev/null 2>&1 && \
       sdbootutil update-all-entries >/dev/null 2>&1; then
      sdbootutil_ok=1
    else
      note "sdbootutil add-all-kernels/update-all-entries reported an error; falling back to direct BLS option synchronization from /etc/kernel/cmdline."
    fi
  else
    note "sdbootutil is not available; applying direct BLS option synchronization from /etc/kernel/cmdline."
  fi

  sync_bls_entries_from_kernel_cmdline
  # Keep snapper-* entries untouched; only root/system entries are synchronized.

  if (( sdbootutil_ok == 0 )); then
    note "BLS entry option sync completed without a clean sdbootutil run; review entries if your setup relies on sdbootutil-managed boot artifacts."
  fi
  return 0
}

# Safely rewrite the options line for a single systemd-boot entry.
systemd_boot_write_options() {
  local entry="$1" new_opts="$2"
  [[ -f "$entry" ]] || die "systemd-boot entry not found: $entry"
  if [[ "$(basename "$entry")" == snapper-* ]]; then
    (( VFIO_BLS_SNAPPER_WRITE_ATTEMPTS += 1 ))
    VFIO_BLS_SNAPPER_WRITE_ATTEMPT_PATHS+=("$entry")
  fi

  backup_file "$entry"

  # Preserve original mode/owner/group.
  local mode owner group
  mode="$(stat -c '%a' "$entry")"
  owner="$(stat -c '%u' "$entry")"
  group="$(stat -c '%g' "$entry")"

  local tmp
  tmp="$(mktemp)"
  local done=0 line
  while IFS= read -r line || [[ -n "$line" ]]; do
    if (( ! done )) && [[ "$line" =~ ^options[[:space:]]+ ]]; then
      printf 'options %s\n' "$(trim "$new_opts")" >>"$tmp"
      done=1
    else
      printf '%s\n' "$line" >>"$tmp"
    fi
  done <"$entry"

  if (( ! done )); then
    printf 'options %s\n' "$(trim "$new_opts")" >>"$tmp"
  fi

  if (( DRY_RUN )); then
    rm -f "$tmp" || true
    return 0
  fi

  install -o "$owner" -g "$group" -m "$mode" "$tmp" "$entry"
  rm -f "$tmp" || true
}

systemd_boot_add_kernel_params() {
  local dir
  # Track whether the user chose verbose boot so we can apply it both to
  # /etc/kernel/cmdline (persistence) and the current boot entry options.
  local verbose_persist=0
  dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
  if [[ -z "$dir" ]]; then
    note "systemd-boot detected but no loader entries directory could be found."
    print_manual_iommu_instructions
    return 0
  fi

  # --- openSUSE / sdbootutil persistence layer ---
  # openSUSE (Tumbleweed / MicroOS / Leap with BLS) uses /etc/kernel/cmdline
  # to generate Boot Loader Spec entries. We must edit this file AND rely on
  # sdbootutil to regenerate the per-kernel entry .conf files.
  if is_opensuse_like && [[ -f /etc/kernel/cmdline ]]; then
    hdr "openSUSE Persistence Check"
    note "Detected /etc/kernel/cmdline on an openSUSE-like system. This is used to generate boot entries (GRUB2-BLS / systemd-boot)."
    
    local cmdline_content
    cmdline_content="$(cat /etc/kernel/cmdline)"
    local cmdline_root_tok cmdline_rootflags_tok cmdline_rootfstype_tok cmdline_resume_tok cmdline_machine_id_tok
    cmdline_root_tok="$(cmdline_get_key_value_token "$cmdline_content" "root" 2>/dev/null || true)"
    cmdline_rootflags_tok="$(cmdline_get_key_value_token "$cmdline_content" "rootflags" 2>/dev/null || true)"
    cmdline_rootfstype_tok="$(cmdline_get_key_value_token "$cmdline_content" "rootfstype" 2>/dev/null || true)"
    cmdline_resume_tok="$(cmdline_get_key_value_token "$cmdline_content" "resume" 2>/dev/null || true)"
    cmdline_machine_id_tok="$(cmdline_get_key_value_token "$cmdline_content" "systemd.machine_id" 2>/dev/null || true)"
    # Base params: IOMMU and any extras discovered earlier. Framebuffer
    # mitigation (video=efifb:off, etc.) is handled by a dedicated prompt
    # below so users understand why it is needed and can skip it if they
    # know their boot VGA path is already safe.
    local -a params_to_add=("$(cpu_iommu_param)" "iommu=pt")
    if [[ -n "${GRUB_EXTRA_PARAMS:-}" ]]; then
      local -a extra=()
      read -r -a extra <<<"${GRUB_EXTRA_PARAMS}"
      params_to_add+=("${extra[@]}")
    fi
    local new_cmdline="$cmdline_content"
    
    local p
    for p in "${params_to_add[@]}"; do
      new_cmdline="$(add_param_once "$new_cmdline" "$p")"
    done
    new_cmdline="$(append_guest_vfio_ids_with_detect_fallback "$new_cmdline" "/etc/kernel/cmdline (persistence)")"
    if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
      # Dynamic mode: strip any pre-existing vfio-pci.ids from a prior early-binding run.
      new_cmdline="$(remove_param_prefix "$new_cmdline" "vfio-pci.ids=")"
      note "Dynamic binding mode: skipping vfio-pci.ids (libvirt hook will bind at VM start)."
    fi
    local boot_metadata_opts
    boot_metadata_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
    if [[ -n "$boot_metadata_opts" ]]; then
      new_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$new_cmdline" "$boot_metadata_opts")"
    fi
    # --- Dynamic binding: auto-add the RX 9070 / RDNA4 reset-bug stability
    # params NON-interactively when the guest GPU is AMD. The optional prompts
    # below (USB/xHCI, framebuffer, AMD power-tradeoff pair, SELinux, ACS,
    # verbosity, boot target, custom kernel params) are NOT early-binding-
    # specific — they apply to both modes — so they still run for dynamic too.
    # Only vfio-pci.ids and rd.driver.pre=vfio-pci are early-binding-specific
    # (dynamic strips them, handled above/below). Honors --no-amd-* opt-outs.
    if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" && -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
      note "Dynamic binding + AMD guest GPU: auto-adding vfio-pci.disable_idle_d3=1, pcie_port_pm=off, pcie_aspm=off to /etc/kernel/cmdline (RX 9070 / RDNA4 reset-bug stability; required for both modes)."
      if _should_add_disable_idle_d3; then
        new_cmdline="$(add_param_once "$new_cmdline" "vfio-pci.disable_idle_d3=1")"
      else
        note "  vfio-pci.disable_idle_d3=1 SKIPPED for RX 9070 / RDNA4 (Navi 48, device 7550): it worsens D3 issues there (card drops off the bus mid-session); the bind script's D0-lock (d3cold_allowed=0 + power/control=on) is the correct defense. Use --amd-disable-idle-d3 to force it."
      fi
      [[ "${AMD_PORTPM_OVERRIDE:-}" != "0" ]] && new_cmdline="$(add_param_once "$new_cmdline" "pcie_port_pm=off")"
      new_cmdline="$(add_param_once "$new_cmdline" "pcie_aspm=off")"
    fi
    # Optional: USB/xHCI stability workaround for hosts that can freeze or
    # spam disconnects due to USB runtime PM / PCIe ASPM interactions.
    say
    hdr "USB/xHCI power-management stability (optional)"
    note "If your host shows xHCI hangs, USB disconnect storms, or freezes under USB load, this optional workaround can help."
    note "It adds: usbcore.autosuspend=-1 pcie_aspm=off"
    note "Why optional: it can increase idle power usage and is only needed on affected systems."
    if prompt_yn "Add usbcore.autosuspend=-1 and pcie_aspm=off to /etc/kernel/cmdline? (optional workaround)" N "USB/xHCI stability"; then
      new_cmdline="$(add_param_once "$new_cmdline" "usbcore.autosuspend=-1")"
      new_cmdline="$(add_param_once "$new_cmdline" "pcie_aspm=off")"
    else
      note "Skipping USB/xHCI power workaround parameters."
    fi

    # Optional: boot framebuffer / Boot VGA mitigation. On many systems the
    # EFI/simple framebuffer can "pin" the guest GPU memory and prevent
    # reliable VFIO binding (symptoms include black screens, "Header type 127",
    # or hangs when starting the VM). These parameters tell the kernel not
    # to use those early framebuffers for the console.
    say
    hdr "Boot framebuffer (Boot VGA) mitigation (optional)"
    note "On some setups the EFI/simple framebuffer (efifb/vesafb/sysfb) can lock your guest GPU and cause black screens or hangs when using VFIO."
    note "If you pass your primary/Boot VGA dGPU to a VM, disabling these framebuffers is often recommended."
    note "If your guest GPU is a secondary card and the host only uses an iGPU or a different card for the boot console, you may not need this."
    local fb_default="N"
    if [[ -n "${CTX[guest_gpu]:-}" && "$(pci_boot_vga_flag "${CTX[guest_gpu]}")" == "1" ]]; then
      if is_opensuse_like; then
        fb_default="N"
        note "Detected guest GPU as Boot VGA on this boot, but on openSUSE we default this mitigation to NO for safer first boot behavior."
        note "Enable it only if you confirm early framebuffer locking is causing passthrough failures."
      else
        fb_default="Y"
        note "Detected guest GPU as Boot VGA on this boot; defaulting this mitigation to YES."
      fi
    else
      note "Guest GPU does not appear to be Boot VGA on this boot; defaulting this mitigation to NO."
    fi
    if prompt_yn "Add video=efifb:off video=vesafb:off initcall_blacklist=sysfb_init to /etc/kernel/cmdline?" "$fb_default" "Boot framebuffer mitigation"; then
      new_cmdline="$(add_param_once "$new_cmdline" "video=efifb:off")"
      new_cmdline="$(add_param_once "$new_cmdline" "video=vesafb:off")"
      new_cmdline="$(add_param_once "$new_cmdline" "initcall_blacklist=sysfb_init")"
    else
      note "Keeping existing framebuffer settings. If you later see black screens or "Header type 127" when starting the VM, rerun and enable this option."
    fi

    # Optional: AMD GPU stability workarounds (openSUSE persistence).
    if [[ -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
      say
      hdr "AMD GPU stability workarounds (optional)"
      note "These parameters address two different AMD GPU instability paths that can cascade to PCIe bus hangs (for example xHCI host controller death or USB disconnect storms)."
      note ""
      note "1) amdgpu.runpm=0  — disables runtime power management (D0<->D3 transitions)."
      note "   What it does: prevents the GPU from entering low-power D-states automatically."
      note "   Why it can help: aggressive power-state transitions are a frequent trigger for PCIe link dropouts and reset failures on some AMD cards under VFIO."
      note ""
      note "2) amdgpu.noretry=0 — disables GPU-initiated PCIe transaction retry loops."
      note "   What it does: allows the driver to retry instead of the hardware, which can prevent a wedged GPU from locking up the shared PCIe bus."
      note "   Why it can help: if the driver reports 'amdgpu: device lost from bus' or 'Pageflip timed out', the GPU may be retrying PCIe transactions indefinitely, which can cascade and kill other devices on the same bus (xHCI, USB, audio)."
      note ""
      note "Important: these are WORKAROUNDS, not solutions. They may reduce or eliminate symptoms, but they will NOT fix BIOS/firmware bugs, ReBAR quirks, or fundamental IOMMU group problems."
      note "Trade-off: amdgpu.runpm=0 increases idle power usage and heat because the GPU stays at full power."
      note ""
      note "3) vfio-pci.disable_idle_d3=1 — keeps the vfio-pci-bound GPU out of D3hot idle."
      note "   What it does: prevents the bound GPU from entering D3hot when idle, avoiding D3 entry/exit races."
      note "   Why it can help: D3 entry/exit races during VM start/stop reset are a known source of reset failures and black screens on some AMD cards under VFIO."
      note ""
      note "4) pcie_port_pm=off — disables PCIe port power management."
      note "   What it does: prevents PCIe port runtime power-state transitions on the guest GPU path."
      note "   Why it can help: PCIe port PM can cause link drops on the guest GPU path, contributing to 'device lost from bus' cascades."
      if [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" || "${AMD_NORETRY_OVERRIDE:-}" == "1" || "${AMD_D3_OVERRIDE:-}" == "1" || "${AMD_PORTPM_OVERRIDE:-}" == "1" ]]; then
        note "AMD stability workaround override in effect: force-adding requested parameters without prompt."
        [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" ]] && new_cmdline="$(add_param_once "$new_cmdline" "amdgpu.runpm=0")"
        [[ "${AMD_NORETRY_OVERRIDE:-}" == "1" ]] && new_cmdline="$(add_param_once "$new_cmdline" "amdgpu.noretry=0")"
        [[ "${AMD_D3_OVERRIDE:-}" == "1" ]] && new_cmdline="$(add_param_once "$new_cmdline" "vfio-pci.disable_idle_d3=1")"
        [[ "${AMD_PORTPM_OVERRIDE:-}" == "1" ]] && new_cmdline="$(add_param_once "$new_cmdline" "pcie_port_pm=off")"
      elif [[ "${AMD_RUNPM_OVERRIDE:-}" == "0" && "${AMD_NORETRY_OVERRIDE:-}" == "0" && "${AMD_D3_OVERRIDE:-}" == "0" && "${AMD_PORTPM_OVERRIDE:-}" == "0" ]]; then
        note "AMD stability workaround override in effect: skipping all AMD GPU stability parameters (--no-amd-runpm --no-amd-noretry --no-amd-disable-idle-d3 --no-amd-pcie-port-pm-off)."
      elif prompt_yn "Add amdgpu.runpm=0, amdgpu.noretry=0, vfio-pci.disable_idle_d3=1 and pcie_port_pm=off to /etc/kernel/cmdline for the AMD guest GPU? (optional workarounds)" N "AMD stability workarounds"; then
        new_cmdline="$(add_param_once "$new_cmdline" "amdgpu.runpm=0")"
        new_cmdline="$(add_param_once "$new_cmdline" "amdgpu.noretry=0")"
        new_cmdline="$(add_param_once "$new_cmdline" "vfio-pci.disable_idle_d3=1")"
        new_cmdline="$(add_param_once "$new_cmdline" "pcie_port_pm=off")"
      else
        note "Skipping AMD GPU stability parameters. If you later see PCIe dropouts, 'device lost from bus', or USB/xHCI cascades with the AMD guest GPU, rerun and enable these options."
      fi
    fi

    # Optional: disable SELinux/AppArmor at the kernel level.
    # On openSUSE Tumbleweed with Btrfs rollbacks, enabling SELinux
    # or AppArmor on a rolled-back root can easily cause confusing
    # boot failures (desktop spin+reboot, services denied writes on
    # read-only or mislabelled subvolumes, etc.). This helper is
    # not LSM-policy aware, so the safest default for passthrough
    # debugging is to turn those off via selinux=0 apparmor=0.
    say
    hdr "Kernel security modules (SELinux/AppArmor, optional)"
    note "By default this helper keeps existing SELinux/AppArmor settings unchanged."
    note "Only disable them for troubleshooting if you have confirmed policy denials are causing VFIO boot/login failures."
    if prompt_yn "Disable SELinux and AppArmor in kernel parameters (add selinux=0 apparmor=0 and remove security=selinux/apparmor)?" N "Kernel security modules"; then
      new_cmdline="$(remove_param_all "$new_cmdline" "security=selinux")"
      new_cmdline="$(remove_param_all "$new_cmdline" "security=apparmor")"
      new_cmdline="$(remove_param_all "$new_cmdline" "selinux=1")"
      new_cmdline="$(remove_param_all "$new_cmdline" "apparmor=1")"
      new_cmdline="$(add_param_once "$new_cmdline" "selinux=0")"
      new_cmdline="$(add_param_once "$new_cmdline" "apparmor=0")"
    else
      note "Keeping existing SELinux/AppArmor kernel parameters as-is. If you see spin+reboot or permission errors after rollback, consider rerunning with this option."
    fi
    
    # On openSUSE with dracut, rd.driver.pre=vfio-pci is effectively
    # required for reliable GPU binding because the graphics driver is
    # pulled in very early from the initramfs. Treat it as strongly
    # recommended here (default YES) instead of a hidden "advanced" knob.
    # However, if the vfio-pci module is not present for this kernel,
    # forcing rd.driver.pre=vfio-pci would just cause dracut to fail a
    # modprobe very early in boot, so we skip it in that case.
    if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
      note "Dynamic binding mode: skipping rd.driver.pre=vfio-pci (libvirt hook will bind at VM start)."
      new_cmdline="$(remove_param_all "$new_cmdline" "rd.driver.pre=vfio-pci")"
    elif command -v dracut >/dev/null 2>&1 && vfio_pci_available; then
      say
      hdr "Initramfs early VFIO driver (recommended on openSUSE)"
      note "On openSUSE (dracut-based), rd.driver.pre=vfio-pci helps vfio-pci claim the guest GPU before amdgpu/nvidia/i915 inside the initramfs."
      note "Skipping this can lead to boot loops or the GPU being grabbed by the host before VFIO." 
      if prompt_yn "Add rd.driver.pre=vfio-pci to /etc/kernel/cmdline? (recommended)" Y "Initramfs (openSUSE)"; then
        new_cmdline="$(add_param_once "$new_cmdline" "rd.driver.pre=vfio-pci")"
        CTX[rd_driver_pre]=1
      else
        note "You chose to skip rd.driver.pre=vfio-pci; passthrough may fail if the initramfs grabs the GPU first."
      fi
    elif command -v dracut >/dev/null 2>&1; then
      note "Skipping rd.driver.pre=vfio-pci because vfio-pci module is not available for this kernel."
    fi
    
    # Optional: disable quiet/splash and show verbose boot logs while
    # testing VFIO, just like we do for GRUB. This affects all future
    # entries generated from /etc/kernel/cmdline.
    say
    hdr "Boot verbosity (persistence)"
    note "While you are testing VFIO passthrough it is often useful to see full boot logs instead of a silent splash screen."
    note "This option will remove 'quiet' and 'splash=silent' from the kernel cmdline and add 'systemd.show_status=1 loglevel=7'."
    note "This automatically removes quiet and splash=silent and adds loglevel=7 for you when installing."
    if prompt_yn "Disable boot splash / quiet and enable detailed text logs on boot?" N "Boot verbosity (persistence)"; then
      new_cmdline="$(remove_param_all "$new_cmdline" "quiet")"
      new_cmdline="$(remove_param_all "$new_cmdline" "splash=silent")"
      new_cmdline="$(remove_param_all "$new_cmdline" "splash")"
      new_cmdline="$(remove_param_all "$new_cmdline" "rhgb")"
      new_cmdline="$(add_param_once "$new_cmdline" "systemd.show_status=1")"
      new_cmdline="$(add_param_once "$new_cmdline" "loglevel=7")"
      # Stronger Plymouth disable (initramfs + userspace).
      new_cmdline="$(add_param_once "$new_cmdline" "rd.plymouth=0")"
      new_cmdline="$(add_param_once "$new_cmdline" "plymouth.enable=0")"
      disable_plymouth_services
      verbose_persist=1
    fi

    # Optional: boot into multi-user.target (text mode) for VFIO debugging.
    # This replaces the default graphical target with a console-only
    # environment so that failures in the desktop stack cannot immediately
    # trigger a reboot loop. You can later remove this by running the
    # script with --reset or manually deleting systemd.unit=multi-user.target
    # from /etc/kernel/cmdline.
  say
  hdr "Boot target (persistence, optional)"
  note "By default your system boots to the graphical desktop (graphical.target)."
  note "If your VFIO setup causes the desktop or display manager to crash/reboot, you can instead boot to text mode (multi-user.target)."
  note "In text mode, the system stops at a console login so you can inspect logs and fix things before starting the desktop manually."
  if prompt_yn "Change the DEFAULT boot to multi-user.target (text mode) until you switch it back?" N "Boot target (persistence)"; then
    new_cmdline="$(add_param_once "$new_cmdline" "systemd.unit=multi-user.target")"
  fi
    
    # ACS Override check for cmdline file
    if prompt_yn "Enable ACS override in /etc/kernel/cmdline (persistence)?" N "Boot options (persistence)"; then
      new_cmdline="$(add_param_once "$new_cmdline" "pcie_acs_override=downstream,multifunction")"
    fi
    new_cmdline="$(add_custom_kernel_params_interactive "$new_cmdline" "/etc/kernel/cmdline (persistence)")"
    # Preserve current persisted boot metadata unless explicitly unavailable.
    # This keeps root/rootflags stable across additive parameter updates.
    if [[ -n "$cmdline_root_tok" || -n "$cmdline_rootflags_tok" || -n "$cmdline_rootfstype_tok" || -n "$cmdline_resume_tok" || -n "$cmdline_machine_id_tok" ]]; then
      new_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$new_cmdline" "$cmdline_content")"
    fi
    if ! cmdline_get_key_value_token "$new_cmdline" "root" >/dev/null 2>&1; then
      local mount_root_tok mount_rootflags_tok
      mount_root_tok="$(bls_current_mount_root_token 2>/dev/null || true)"
      mount_rootflags_tok="$(bls_current_mount_rootflags_token 2>/dev/null || true)"
      [[ -n "$mount_root_tok" ]] && new_cmdline="$(cmdline_set_key_value_token "$new_cmdline" "$mount_root_tok")"
      [[ -n "$mount_rootflags_tok" ]] && new_cmdline="$(cmdline_set_key_value_token "$new_cmdline" "$mount_rootflags_tok")"
    fi
    if ! cmdline_get_key_value_token "$new_cmdline" "root" >/dev/null 2>&1; then
      local running_boot_opts running_root_tok
      running_boot_opts="$(cat /proc/cmdline 2>/dev/null || true)"
      if [[ -n "$running_boot_opts" ]]; then
        new_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$new_cmdline" "$running_boot_opts")"
        running_root_tok="$(cmdline_get_key_value_token "$new_cmdline" "root" 2>/dev/null || true)"
        if [[ -n "$running_root_tok" ]]; then
          note "Recovered root boot metadata for /etc/kernel/cmdline candidate from running /proc/cmdline."
        fi
      fi
    fi
    if ! cmdline_get_key_value_token "$new_cmdline" "root" >/dev/null 2>&1; then
      local recovered_boot_opts recovered_cmdline recovered_root_tok
      recovered_boot_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
      if [[ -n "$recovered_boot_opts" ]]; then
        recovered_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$new_cmdline" "$recovered_boot_opts")"
        recovered_root_tok="$(cmdline_get_key_value_token "$recovered_cmdline" "root" 2>/dev/null || true)"
        if [[ -n "$recovered_root_tok" ]]; then
          say
          hdr "openSUSE BLS safety recovery"
          note "Detected missing root=... token in /etc/kernel/cmdline candidate."
          note "Recovered boot metadata from existing Boot Loader Spec entries."
          note "Recovered root token: $recovered_root_tok"
          if [[ -r /dev/tty && -w /dev/tty ]]; then
            if prompt_yn "Apply recovered boot metadata (root/rootflags/rootfstype/resume/systemd.machine_id) and continue?" Y "openSUSE BLS safety"; then
              new_cmdline="$recovered_cmdline"
              note "Applied recovered boot metadata and continuing with persistence update."
            else
              note "Skipped metadata recovery by user choice."
            fi
          else
            new_cmdline="$recovered_cmdline"
            note "Applied recovered boot metadata automatically (non-interactive context)."
          fi
        fi
      fi
    fi
    if ! cmdline_get_key_value_token "$new_cmdline" "root" >/dev/null 2>&1; then
      note "openSUSE BLS safety: /etc/kernel/cmdline has no explicit root=... token."
      note "Skipping /etc/kernel/cmdline write to avoid unsafe persistence and /dev/gpt-auto-root boot hangs."
      note "VFIO setup will continue, but persistent kernel parameter changes were not applied."
      note "Run this helper from the installed target root (with a valid root=... cmdline) to apply persistent kernel parameters safely."
      return 0
    fi

    if [[ "$(trim "$new_cmdline")" != "$(trim "$cmdline_content")" ]]; then
      if preview_cmdline_change_interactive "$cmdline_content" "$new_cmdline" "/etc/kernel/cmdline (persistence)"; then
        backup_file "/etc/kernel/cmdline"
        if (( DRY_RUN )); then
          : # do nothing in dry-run
        else
          printf '%s
' "$new_cmdline" > /etc/kernel/cmdline
        fi
        say "Updated /etc/kernel/cmdline for persistence."
        # NOTE: We defer sdbootutil add-all-kernels/update-all-entries
        # until AFTER a successful initramfs rebuild at the end of
        # apply_configuration() to avoid a window where the bootloader
        # demands rd.driver.pre= without the driver being present in the
        # initramfs.
      fi
    else
      say "/etc/kernel/cmdline already contains VFIO/IOMMU params."
    fi

    # On openSUSE we intentionally STOP here and do not run the
    # generic systemd-boot .conf editing logic below. sdbootutil
    # owns /boot/loader/entries/*.conf; we only manipulate
    # /etc/kernel/cmdline and let sdbootutil regenerate entries.
    return 0
  fi
  # -----------------------------------------------

  # Continue with standard logic to update the CURRENT entry immediately
  local -a entries=()
  local f
  shopt -s nullglob
  for f in "$dir"/*.conf; do
    entries+=("$f")
  done
  shopt -u nullglob

  if (( ${#entries[@]} == 0 )); then
    note "No systemd-boot entry files (*.conf) found under $dir."
    print_manual_iommu_instructions
    return 0
  fi

  local -a opts_list=()
  local i title current_opts

  # Try to auto-detect the currently booted entry by matching root= and
  # rootflags= from /proc/cmdline against each entry's options line.
  local running_cmdline running_root running_rootflags
  local entry_root entry_rootflags
  local auto_idx=""

  running_cmdline="$(cat /proc/cmdline 2>/dev/null || true)"
  if [[ -n "$running_cmdline" ]]; then
    running_root="$(sed -n 's/.*\<root=\([^ ]*\).*/\1/p' <<<"$running_cmdline")"
    # Use extended regex to handle optional quotes around rootflags value
    running_rootflags="$(sed -nE 's/.*rootflags="?([^ "]+)"?.*/\1/p' <<<"$running_cmdline")"
  fi

  for i in "${!entries[@]}"; do
    f="${entries[$i]}"
    title="$(grep -m1 -E '^title[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^title[[:space:]]+//')"
    title="${title:-$(basename "$f")}"
    current_opts="$(grep -m1 -E '^options[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
    current_opts="$(trim "${current_opts:-<none>}")"
    opts_list+=("$title"$'\n'"  file: $(basename "$f")"$'\n'"  options: $current_opts")

    if [[ -n "$running_root" && -n "$running_rootflags" && "$current_opts" != "<none>" ]]; then
      entry_root="$(sed -n 's/.*\<root=\([^ ]*\).*/\1/p' <<<"$current_opts")"
      # Use extended regex to handle optional quotes around rootflags value
      entry_rootflags="$(sed -nE 's/.*rootflags="?([^ "]+)"?.*/\1/p' <<<"$current_opts")"
      # CHECK: Does this entry actually match the running kernel version?
      # We grep the file for the current kernel version (e.g. "6.18.7-1-default").
      local running_kernel
      running_kernel="$(uname -r)"

      if [[ -n "$entry_root" && -n "$entry_rootflags" && \
            "$entry_root" == "$running_root" && "$entry_rootflags" == "$running_rootflags" ]]; then
        # logical_match: 1 if the file contains the kernel version string, 0 otherwise
        local logical_match=0
        if grep -Fq "$running_kernel" "$f"; then
          logical_match=1
        fi

        # If we match root flags AND kernel version, this is definitely our guy.
        if (( logical_match )); then
          auto_idx="$i"
        fi
      fi
    fi
  done

  hdr "Current Boot Entry Update"
  note "This will edit the selected systemd-boot entry in-place for the CURRENT kernel."

  local idx entry_path
  if [[ -n "$auto_idx" ]]; then
    entry_path="${entries[$auto_idx]}"
    note "Auto-detected current boot entry: $(basename "$entry_path")"
  else
    idx="$(select_from_list "Select the systemd-boot entry to modify:" "Boot entry selection" "${opts_list[@]}")"
    entry_path="${entries[$idx]}"
  fi

  current_opts="$(grep -m1 -E '^options[[:space:]]+' "$entry_path" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
  current_opts="$(trim "${current_opts:-}")"

  local -a params_to_add=("$(cpu_iommu_param)" "iommu=pt")
  if [[ -n "${GRUB_EXTRA_PARAMS:-}" ]]; then
    local -a extra=()
    read -r -a extra <<<"${GRUB_EXTRA_PARAMS}"
    params_to_add+=("${extra[@]}")
  fi
  local new_opts="$current_opts"
  for p in "${params_to_add[@]}"; do
    new_opts="$(add_param_once "$new_opts" "$p")"
  done
  new_opts="$(append_guest_vfio_ids_with_detect_fallback "$new_opts" "systemd-boot entry options")"
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
    new_opts="$(remove_param_prefix "$new_opts" "vfio-pci.ids=")"
    note "Dynamic binding mode: skipping vfio-pci.ids for this entry (libvirt hook will bind at VM start)."
  fi

  # --- Dynamic binding: auto-add the RX 9070 / RDNA4 reset-bug stability
  # params NON-interactively when the guest GPU is AMD. The optional prompts
  # below (USB/xHCI, AMD power-tradeoff pair, ACS, custom kernel params) are
  # NOT early-binding-specific — they apply to both modes — so they still run
  # for dynamic too. Only vfio-pci.ids is early-binding-specific (dynamic strips
  # it, handled above). Honors --no-amd-* opt-outs.
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" && -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
    note "Dynamic binding + AMD guest GPU: auto-adding vfio-pci.disable_idle_d3=1, pcie_port_pm=off, pcie_aspm=off to this boot entry (RX 9070 / RDNA4 reset-bug stability; required for both modes)."
    if _should_add_disable_idle_d3; then
      new_opts="$(add_param_once "$new_opts" "vfio-pci.disable_idle_d3=1")"
    else
      note "  vfio-pci.disable_idle_d3=1 SKIPPED for RX 9070 / RDNA4 (Navi 48, device 7550): it worsens D3 issues there; the bind script's D0-lock is the correct defense. Use --amd-disable-idle-d3 to force it."
    fi
    [[ "${AMD_PORTPM_OVERRIDE:-}" != "0" ]] && new_opts="$(add_param_once "$new_opts" "pcie_port_pm=off")"
    new_opts="$(add_param_once "$new_opts" "pcie_aspm=off")"
  fi
  # Optional: USB/xHCI stability workaround for the selected live entry.
  say
  hdr "USB/xHCI power-management stability (optional)"
  note "If your host can freeze or spam USB disconnects because of xHCI/USB power transitions, this optional workaround can help."
  note "It adds: usbcore.autosuspend=-1 pcie_aspm=off"
  note "Trade-off: increased idle power usage."
  if prompt_yn "Add usbcore.autosuspend=-1 and pcie_aspm=off to this boot entry? (optional workaround)" N "USB/xHCI stability (systemd-boot)"; then
    new_opts="$(add_param_once "$new_opts" "usbcore.autosuspend=-1")"
    new_opts="$(add_param_once "$new_opts" "pcie_aspm=off")"
  else
    note "Skipping USB/xHCI power workaround parameters for this entry."
  fi

  # Optional: AMD GPU stability workarounds (generic systemd-boot).
  if [[ -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
    say
    hdr "AMD GPU stability workarounds (optional)"
    note "These parameters address two different AMD GPU instability paths that can cascade to PCIe bus hangs (for example xHCI host controller death or USB disconnect storms)."
    note ""
    note "1) amdgpu.runpm=0  — disables runtime power management (D0<->D3 transitions)."
    note "   What it does: prevents the GPU from entering low-power D-states automatically."
    note "   Why it can help: aggressive power-state transitions are a frequent trigger for PCIe link dropouts and reset failures on some AMD cards under VFIO."
    note ""
    note "2) amdgpu.noretry=0 — disables GPU-initiated PCIe transaction retry loops."
    note "   What it does: allows the driver to retry instead of the hardware, which can prevent a wedged GPU from locking up the shared PCIe bus."
    note "   Why it can help: if the driver reports 'amdgpu: device lost from bus' or 'Pageflip timed out', the GPU may be retrying PCIe transactions indefinitely, which can cascade and kill other devices on the same bus (xHCI, USB, audio)."
    note ""
    note "Important: these are WORKAROUNDS, not solutions. They may reduce or eliminate symptoms, but they will NOT fix BIOS/firmware bugs, ReBAR quirks, or fundamental IOMMU group problems."
    note "Trade-off: amdgpu.runpm=0 increases idle power usage and heat because the GPU stays at full power."
    note ""
    note "3) vfio-pci.disable_idle_d3=1 — keeps the vfio-pci-bound GPU out of D3hot idle."
    note "   What it does: prevents the bound GPU from entering D3hot when idle, avoiding D3 entry/exit races."
    note "   Why it can help: D3 entry/exit races during VM start/stop reset are a known source of reset failures and black screens on some AMD cards under VFIO."
    note ""
    note "4) pcie_port_pm=off — disables PCIe port power management."
    note "   What it does: prevents PCIe port runtime power-state transitions on the guest GPU path."
    note "   Why it can help: PCIe port PM can cause link drops on the guest GPU path, contributing to 'device lost from bus' cascades."
    if [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" || "${AMD_NORETRY_OVERRIDE:-}" == "1" || "${AMD_D3_OVERRIDE:-}" == "1" || "${AMD_PORTPM_OVERRIDE:-}" == "1" ]]; then
      note "AMD stability workaround override in effect: force-adding requested parameters without prompt."
      [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" ]] && new_opts="$(add_param_once "$new_opts" "amdgpu.runpm=0")"
      [[ "${AMD_NORETRY_OVERRIDE:-}" == "1" ]] && new_opts="$(add_param_once "$new_opts" "amdgpu.noretry=0")"
      [[ "${AMD_D3_OVERRIDE:-}" == "1" ]] && new_opts="$(add_param_once "$new_opts" "vfio-pci.disable_idle_d3=1")"
      [[ "${AMD_PORTPM_OVERRIDE:-}" == "1" ]] && new_opts="$(add_param_once "$new_opts" "pcie_port_pm=off")"
    elif [[ "${AMD_RUNPM_OVERRIDE:-}" == "0" && "${AMD_NORETRY_OVERRIDE:-}" == "0" && "${AMD_D3_OVERRIDE:-}" == "0" && "${AMD_PORTPM_OVERRIDE:-}" == "0" ]]; then
      note "AMD stability workaround override in effect: skipping all AMD GPU stability parameters (--no-amd-runpm --no-amd-noretry --no-amd-disable-idle-d3 --no-amd-pcie-port-pm-off)."
    elif prompt_yn "Add amdgpu.runpm=0, amdgpu.noretry=0, vfio-pci.disable_idle_d3=1 and pcie_port_pm=off to this boot entry for the AMD guest GPU? (optional workarounds)" N "AMD stability workarounds"; then
      new_opts="$(add_param_once "$new_opts" "amdgpu.runpm=0")"
      new_opts="$(add_param_once "$new_opts" "amdgpu.noretry=0")"
      new_opts="$(add_param_once "$new_opts" "vfio-pci.disable_idle_d3=1")"
      new_opts="$(add_param_once "$new_opts" "pcie_port_pm=off")"
    else
      note "Skipping AMD GPU stability parameters for this entry. If you later see PCIe dropouts, 'device lost from bus', or USB/xHCI cascades with the AMD guest GPU, rerun and enable these options."
    fi
  fi
  
  # If the user chose verbose boot in the persistence step, mirror that
  # here so the CURRENT entry immediately shows logs instead of splash.
  if (( verbose_persist )); then
    new_opts="$(remove_param_all "$new_opts" "quiet")"
    new_opts="$(remove_param_all "$new_opts" "splash=silent")"
    new_opts="$(remove_param_all "$new_opts" "splash")"
    new_opts="$(remove_param_all "$new_opts" "rhgb")"
    new_opts="$(add_param_once "$new_opts" "systemd.show_status=1")"
    new_opts="$(add_param_once "$new_opts" "loglevel=7")"
    new_opts="$(add_param_once "$new_opts" "rd.plymouth=0")"
    new_opts="$(add_param_once "$new_opts" "plymouth.enable=0")"
  fi
  
  say
  hdr "Advanced (optional): ACS override (systemd-boot)"
  if prompt_yn "Enable ACS override (pcie_acs_override=downstream,multifunction) in this entry?" N "Boot options (systemd-boot)"; then
    new_opts="$(add_param_once "$new_opts" "pcie_acs_override=downstream,multifunction")"
  fi
  new_opts="$(add_custom_kernel_params_interactive "$new_opts" "systemd-boot entry")"

  if [[ "$(trim "$new_opts")" == "$(trim "$current_opts")" ]]; then
    say "systemd-boot entry options unchanged (params already present)."
    return 0
  fi
  if ! preview_cmdline_change_interactive "$current_opts" "$new_opts" "systemd-boot entry options"; then
    return 0
  fi

  systemd_boot_write_options "$entry_path" "$new_opts"
  say "Updated systemd-boot entry: $entry_path"
}

print_manual_iommu_instructions() {
  local param bl
  param="$(cpu_iommu_param)"
  bl="$(detect_bootloader)"
  if [[ "$bl" != "grub" && "$bl" != "systemd-boot" && "$bl" != "grub2-bls" ]]; then
    say "Detected boot loader: $bl"
  fi
  say "Automatic kernel parameter editing is implemented for GRUB, GRUB2-BLS and systemd-boot on systemd-based systems."
  say "Other boot loaders (for example rEFInd or custom UEFI stubs) are NOT auto-edited by this script."
  say "If you use one of those, you must edit your kernel parameters manually. Add these parameters and then reboot:"
  say "  $param iommu=pt"
  say "Optional stability workaround for USB/xHCI crashes/freezes (only if needed):"
  say "  usbcore.autosuspend=-1 pcie_aspm=off"
  say "Optional AMD-specific workarounds for PCIe dropouts / reset failures / bus cascades (only if guest GPU is AMD):"
  say "  amdgpu.runpm=0"
  say "    - Disables AMD GPU runtime power management (D0/D3 transitions)."
  say "    - This is a workaround, not a solution; it increases idle power usage."
  say "  amdgpu.noretry=0"
  say "    - Disables GPU-initiated PCIe transaction retry loops."
  say "    - Can prevent a wedged GPU from locking the shared PCIe bus and cascading to xHCI/USB/audio devices."
  say "  vfio-pci.disable_idle_d3=1"
  say "    - Keeps the vfio-pci-bound GPU out of D3hot idle to avoid D3 entry/exit races during VM start/stop reset."
  say "  pcie_port_pm=off"
  say "    - Disables PCIe port power management to prevent link drops on the guest GPU path."
  say "Advanced (usually NOT recommended): pcie_acs_override=downstream,multifunction"
  say "  - Only consider this if your IOMMU groups are not isolated."
  say "  - It can reduce PCIe isolation and may cause instability on some systems."
}

grub_add_kernel_params() {
  # Merge standard params with any discovered extras. Framebuffer mitigation
  # (video=efifb:off, etc.) is offered via an explicit prompt below so that
  # users understand why it is being added.
  local -a params_to_add=("$(cpu_iommu_param)" "iommu=pt")
  if [[ -n "${GRUB_EXTRA_PARAMS:-}" ]]; then
    local -a extra=()
    read -r -a extra <<<"${GRUB_EXTRA_PARAMS}"
    params_to_add+=("${extra[@]}")
  fi

  if [[ ! -f /etc/default/grub ]]; then
    print_manual_iommu_instructions
    return 0
  fi

  backup_file /etc/default/grub

  local key
  key="$(grub_get_key)" || die "Could not find GRUB_CMDLINE_LINUX_DEFAULT or GRUB_CMDLINE_LINUX in /etc/default/grub"

  local current new
  current="$(grub_read_cmdline "$key")"
  new="$current"
 
  local p
  for p in "${params_to_add[@]}"; do
    new="$(add_param_once "$new" "$p")"
  done
  new="$(append_guest_vfio_ids_with_detect_fallback "$new" "GRUB kernel cmdline")"
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
    new="$(remove_param_prefix "$new" "vfio-pci.ids=")"
    note "Dynamic binding mode: skipping vfio-pci.ids (libvirt hook will bind at VM start)."
  fi

  # --- Dynamic binding: auto-add the RX 9070 / RDNA4 reset-bug stability
  # params NON-interactively when the guest GPU is AMD. The optional prompts
  # below (USB/xHCI, framebuffer, AMD power-tradeoff pair, SELinux, ACS,
  # verbosity, boot target) are NOT early-binding-specific — they apply to both
  # modes — so they still run for dynamic too. Only vfio-pci.ids and
  # rd.driver.pre=vfio-pci are early-binding-specific (dynamic strips them,
  # handled above/below). Honors --no-amd-disable-idle-d3 / --no-amd-pcie-port-pm-off.
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" && -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
    note "Dynamic binding + AMD guest GPU: auto-adding vfio-pci.disable_idle_d3=1, pcie_port_pm=off, pcie_aspm=off to GRUB kernel cmdline (RX 9070 / RDNA4 reset-bug stability; required for both modes)."
    if _should_add_disable_idle_d3; then
      new="$(add_param_once "$new" "vfio-pci.disable_idle_d3=1")"
    else
      note "  vfio-pci.disable_idle_d3=1 SKIPPED for RX 9070 / RDNA4 (Navi 48, device 7550): it worsens D3 issues there; the bind script's D0-lock is the correct defense. Use --amd-disable-idle-d3 to force it."
    fi
    [[ "${AMD_PORTPM_OVERRIDE:-}" != "0" ]] && new="$(add_param_once "$new" "pcie_port_pm=off")"
    new="$(add_param_once "$new" "pcie_aspm=off")"
  fi
  # Optional USB/xHCI power-management workaround.
  say
  hdr "USB/xHCI power-management stability (optional)"
  note "If your host sometimes freezes or logs xHCI/USB disconnect storms, this optional workaround can improve stability."
  note "It adds: usbcore.autosuspend=-1 pcie_aspm=off"
  note "Why optional: it can increase idle power usage and is not needed on all systems."
  if prompt_yn "Add usbcore.autosuspend=-1 and pcie_aspm=off to GRUB kernel parameters? (optional workaround)" N "USB/xHCI stability (GRUB)"; then
    new="$(add_param_once "$new" "usbcore.autosuspend=-1")"
    new="$(add_param_once "$new" "pcie_aspm=off")"
  else
    note "Leaving USB/xHCI power-management parameters unchanged."
  fi

  # Optional: boot framebuffer / Boot VGA mitigation for GRUB systems.
  # This mirrors the openSUSE /etc/kernel/cmdline behavior: we can
  # disable efifb/vesafb/sysfb to avoid early framebuffers pinning the
  # guest GPU.
  say
  hdr "Boot framebuffer (Boot VGA) mitigation (optional)"
  note "On some systems, early EFI/vesa framebuffers can keep the guest GPU busy and interfere with VFIO (black screens, hangs, \"Header type 127\")."
  note "If you are passing your primary dGPU (Boot VGA) to a VM, disabling those framebuffers is usually recommended."
  note "If the host only uses an iGPU or a different card for the console, you may not need this."
  local grub_fb_default="N"
  if [[ -n "${CTX[guest_gpu]:-}" && "$(pci_boot_vga_flag "${CTX[guest_gpu]}")" == "1" ]] && ! is_opensuse_like; then
    grub_fb_default="Y"
  fi
  if prompt_yn "Add video=efifb:off video=vesafb:off initcall_blacklist=sysfb_init to GRUB kernel parameters?" "$grub_fb_default" "Boot framebuffer mitigation"; then
    new="$(add_param_once "$new" "video=efifb:off")"
    new="$(add_param_once "$new" "video=vesafb:off")"
    new="$(add_param_once "$new" "initcall_blacklist=sysfb_init")"
  else
    note "Keeping existing framebuffer parameters unchanged. If you later hit black screens at VM start, rerun and enable this option."
  fi

  # Optional: AMD GPU stability workarounds (GRUB).
  # These address two different AMD GPU instability paths observed under VFIO:
  # 1) Runtime PM (D0<->D3 transitions) causing PCIe link dropouts / reset failures.
  # 2) GPU-initiated PCIe transaction retry loops wedging the shared bus and
  #    cascading to other devices (xHCI death, USB disconnect storms, audio).
  # This is AMD-specific and only offered when the guest GPU vendor is AMD.
  if [[ -n "${CTX[guest_vendor]:-}" && "${CTX[guest_vendor],,}" == "1002" ]]; then
    say
    hdr "AMD GPU stability workarounds (optional)"
    note "These parameters address two different AMD GPU instability paths that can cascade to PCIe bus hangs (for example xHCI host controller death or USB disconnect storms)."
    note ""
    note "1) amdgpu.runpm=0  — disables runtime power management (D0<->D3 transitions)."
    note "   What it does: prevents the GPU from entering low-power D-states automatically."
    note "   Why it can help: aggressive power-state transitions are a frequent trigger for PCIe link dropouts and reset failures on some AMD cards under VFIO."
    note ""
    note "2) amdgpu.noretry=0 — disables GPU-initiated PCIe transaction retry loops."
    note "   What it does: allows the driver to retry instead of the hardware, which can prevent a wedged GPU from locking up the shared PCIe bus."
    note "   Why it can help: if the driver reports 'amdgpu: device lost from bus' or 'Pageflip timed out', the GPU may be retrying PCIe transactions indefinitely, which can cascade and kill other devices on the same bus (xHCI, USB, audio)."
    note ""
    note "Important: these are WORKAROUNDS, not solutions. They may reduce or eliminate symptoms, but they will NOT fix BIOS/firmware bugs, ReBAR quirks, or fundamental IOMMU group problems."
    note "Trade-off: amdgpu.runpm=0 increases idle power usage and heat because the GPU stays at full power."
    note ""
    note "3) vfio-pci.disable_idle_d3=1 — keeps the vfio-pci-bound GPU out of D3hot idle."
    note "   What it does: prevents the bound GPU from entering D3hot when idle, avoiding D3 entry/exit races."
    note "   Why it can help: D3 entry/exit races during VM start/stop reset are a known source of reset failures and black screens on some AMD cards under VFIO."
    note ""
    note "4) pcie_port_pm=off — disables PCIe port power management."
    note "   What it does: prevents PCIe port runtime power-state transitions on the guest GPU path."
    note "   Why it can help: PCIe port PM can cause link drops on the guest GPU path, contributing to 'device lost from bus' cascades."
    note "If your AMD guest GPU works reliably without these, leaving the defaults enabled is preferred for lower power usage."
    if [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" || "${AMD_NORETRY_OVERRIDE:-}" == "1" || "${AMD_D3_OVERRIDE:-}" == "1" || "${AMD_PORTPM_OVERRIDE:-}" == "1" ]]; then
      note "AMD stability workaround override in effect: force-adding requested parameters without prompt."
      [[ "${AMD_RUNPM_OVERRIDE:-}" == "1" ]] && new="$(add_param_once "$new" "amdgpu.runpm=0")"
      [[ "${AMD_NORETRY_OVERRIDE:-}" == "1" ]] && new="$(add_param_once "$new" "amdgpu.noretry=0")"
      [[ "${AMD_D3_OVERRIDE:-}" == "1" ]] && new="$(add_param_once "$new" "vfio-pci.disable_idle_d3=1")"
      [[ "${AMD_PORTPM_OVERRIDE:-}" == "1" ]] && new="$(add_param_once "$new" "pcie_port_pm=off")"
    elif [[ "${AMD_RUNPM_OVERRIDE:-}" == "0" && "${AMD_NORETRY_OVERRIDE:-}" == "0" && "${AMD_D3_OVERRIDE:-}" == "0" && "${AMD_PORTPM_OVERRIDE:-}" == "0" ]]; then
      note "AMD stability workaround override in effect: skipping all AMD GPU stability parameters (--no-amd-runpm --no-amd-noretry --no-amd-disable-idle-d3 --no-amd-pcie-port-pm-off)."
    elif prompt_yn "Add amdgpu.runpm=0, amdgpu.noretry=0, vfio-pci.disable_idle_d3=1 and pcie_port_pm=off to GRUB kernel parameters for the AMD guest GPU? (optional workarounds)" N "AMD stability workarounds"; then
      new="$(add_param_once "$new" "amdgpu.runpm=0")"
      new="$(add_param_once "$new" "amdgpu.noretry=0")"
      new="$(add_param_once "$new" "vfio-pci.disable_idle_d3=1")"
      new="$(add_param_once "$new" "pcie_port_pm=off")"
    else
      note "Skipping AMD GPU stability parameters. If you later see PCIe dropouts, 'device lost from bus', or USB/xHCI cascades with the AMD guest GPU, rerun and enable these options."
    fi
  fi
 
  # Optional: disable SELinux/AppArmor on GRUB-based systems as
  # well to match the openSUSE BLS path.
  say
  hdr "Kernel security modules (SELinux/AppArmor)"
  note "On systems that use Btrfs rollbacks (like openSUSE), SELinux/AppArmor combined with an older root snapshot can cause boot issues."
  note "This helper focuses on VFIO and does not manage LSM policy, so for stable passthrough testing it is often safest to turn them off."
  if prompt_yn "Disable SELinux and AppArmor in GRUB kernel parameters (selinux=0 apparmor=0)?" N "Kernel security modules"; then
    new="$(remove_param_all "$new" "security=selinux")"
    new="$(remove_param_all "$new" "security=apparmor")"
    new="$(remove_param_all "$new" "selinux=1")"
    new="$(remove_param_all "$new" "apparmor=1")"
    new="$(add_param_once "$new" "selinux=0")"
    new="$(add_param_once "$new" "apparmor=0")"
  else
    note "Keeping existing SELinux/AppArmor kernel parameters in GRUB. If rollbacks cause boot loops or denials, rerun and enable this option."
  fi
 
  say
  hdr "Advanced (optional): ACS override"
  note "ACS override can sometimes split up IOMMU groups on motherboards that don't expose proper isolation."
  note "This may help GPU passthrough if your guest GPU shares an IOMMU group with other devices."
  note "Downsides: weaker PCIe isolation/security and possible instability."
  note "Recommended: NO unless you know you need it."

  if prompt_yn "Enable ACS override in GRUB (pcie_acs_override=downstream,multifunction)?" N "Boot options (GRUB)"; then
    new="$(add_param_once "$new" "pcie_acs_override=downstream,multifunction")"
  fi

  # Optional: disable quiet/splash and show verbose boot logs while testing VFIO.
  say
  hdr "Boot verbosity (optional)"
  note "While you are testing VFIO passthrough it is often useful to see full boot logs instead of a silent splash screen."
  note "This option will remove 'quiet' and 'splash=silent' from the kernel cmdline and add 'systemd.show_status=1 loglevel=7'."
  note "This automatically removes quiet and splash=silent and adds loglevel=7 for you when installing."
  note "You can later revert this by running the script with --reset or manually editing /etc/default/grub."
  if prompt_yn "Disable boot splash / quiet and enable detailed text logs on boot?" N "Boot verbosity"; then
    new="$(remove_param_all "$new" "quiet")"
    new="$(remove_param_all "$new" "splash=silent")"
    new="$(remove_param_all "$new" "splash")"
    new="$(remove_param_all "$new" "rhgb")"
    new="$(add_param_once "$new" "systemd.show_status=1")"
    new="$(add_param_once "$new" "loglevel=7")"
    # Stronger Plymouth disable (initramfs + userspace).
    new="$(add_param_once "$new" "rd.plymouth=0")"
    new="$(add_param_once "$new" "plymouth.enable=0")"
    disable_plymouth_services
  fi

  # Optional: boot into multi-user.target (text mode) for VFIO debugging.
  # This replaces the default graphical target with a console-only
  # environment so that failures in the desktop stack cannot immediately
  # trigger a reboot loop. You can later remove this by running the
  # script with --reset or manually deleting systemd.unit=multi-user.target
  # from your GRUB kernel cmdline.
  say
  hdr "Boot target (optional)"
  note "Normally your system boots straight into the graphical desktop (graphical.target)."
  note "If VFIO makes the desktop or display manager unstable, you can boot to text mode instead (multi-user.target)."
  note "In text mode, you'll land at a console login first and can start the desktop manually after checking logs (for example with journalctl -b)."
  if prompt_yn "Change the DEFAULT boot to multi-user.target (text mode) until you switch it back?" N "Boot target"; then
    new="$(add_param_once "$new" "systemd.unit=multi-user.target")"
  fi

  # Dracut-specific early driver ordering (advanced)
  # On dracut-based systems, you can ask dracut to preload vfio-pci before
  # other drivers via rd.driver.pre=vfio-pci. This can help vfio-pci "win"
  # the race against amdgpu/nvidia/i915 when those are pulled into the
  # initramfs. It is still optional because misconfiguration can affect
  # boot if your host depends on those drivers very early.
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
    note "Dynamic binding mode: skipping rd.driver.pre=vfio-pci (libvirt hook will bind at VM start)."
    new="$(remove_param_all "$new" "rd.driver.pre=vfio-pci")"
  elif command -v dracut >/dev/null 2>&1 && vfio_pci_available; then
    say
    # On openSUSE (dracut-based), rd.driver.pre=vfio-pci is strongly
    # recommended; elsewhere we keep it as an advanced optional setting.
    if is_opensuse_like; then
      say
      hdr "Initramfs early VFIO driver (recommended on openSUSE)"
      note "On openSUSE with dracut, rd.driver.pre=vfio-pci helps vfio-pci claim the guest GPU before amdgpu/nvidia/i915 in the initramfs."
      note "Skipping this can cause the host driver to grab the GPU first and break passthrough."
      if prompt_yn "Add rd.driver.pre=vfio-pci to the kernel cmdline? (recommended)" Y "Boot options (dracut/openSUSE)"; then
        new="$(add_param_once "$new" "rd.driver.pre=vfio-pci")"
        CTX[rd_driver_pre]=1
      else
        note "You chose to skip rd.driver.pre=vfio-pci; passthrough may fail if the initramfs grabs the GPU first."
      fi
    else
      hdr "Advanced (optional): rd.driver.pre=vfio-pci (dracut)"
      note "On dracut-based systems this can help vfio-pci bind the guest GPU before display drivers inside the initramfs."
      note "Only enable this if you understand the implications and have a rollback/snapshot available."
      if prompt_yn "Add rd.driver.pre=vfio-pci to the kernel cmdline?" N "Boot options (dracut)"; then
        new="$(add_param_once "$new" "rd.driver.pre=vfio-pci")"
        CTX[rd_driver_pre]=1
      fi
    fi
  elif command -v dracut >/dev/null 2>&1; then
    note "Skipping rd.driver.pre=vfio-pci because vfio-pci module is not available for this kernel."
  fi
  new="$(add_custom_kernel_params_interactive "$new" "GRUB cmdline")"

  # Safety: do not silently rewrite if nothing changed.
  local grub_cmdline_changed=0
  if [[ "$(trim "$new")" == "$(trim "$current")" ]]; then
    say "GRUB cmdline unchanged (params already present)."
  else
    if preview_cmdline_change_interactive "$current" "$new" "GRUB kernel cmdline"; then
      grub_write_cmdline_in_place "$key" "$(trim "$new")"
      grub_cmdline_changed=1
    fi
  fi

  if (( grub_cmdline_changed )); then
    if command -v update-grub >/dev/null 2>&1; then
      say "Updating GRUB config via update-grub..."
      run update-grub
    elif command -v grub-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      elif [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      else
        die "Could not determine grub.cfg output path (no /boot/grub or /boot/grub2)"
      fi
      say "Updating GRUB config via grub-mkconfig -o $out ..."
      run grub-mkconfig -o "$out"
    elif command -v grub2-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      elif [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      else
        die "Could not determine grub.cfg output path (no /boot/grub2 or /boot/grub)"
      fi
      say "Updating GRUB config via grub2-mkconfig -o $out ..."
      run grub2-mkconfig -o "$out"
    else
      die "No supported GRUB update command found (tried update-grub, grub-mkconfig, grub2-mkconfig)"
    fi
  else
    note "Skipping GRUB config regeneration because kernel cmdline was not changed."
  fi
}

maybe_update_initramfs() {
  # Prefer a transparent, verbose path on openSUSE/dracut systems so you
  # can clearly see when dracut is being invoked, while still keeping
  # Boot Loader Spec / ESP in sync via sdbootutil where applicable.

  # 1. openSUSE with dracut: run dracut explicitly, then sync via sdbootutil
  #    if it is available. This guarantees visible dracut output.
  if is_opensuse_like && command -v dracut >/dev/null 2>&1; then
    say "Updating initramfs via dracut (--force) ..."
    if run dracut --force; then
      note "dracut completed; initramfs on the root filesystem is updated."
    else
      note "dracut failed even with --force. Your previous initramfs is still on disk."
      # Even if this fails, we still attempt sdbootutil below so that
      # any partially-updated images are synced as best-effort.
    fi

    if command -v sdbootutil >/dev/null 2>&1; then
      say "Syncing initramfs and boot entries via sdbootutil add-all-kernels ..."
      if run sdbootutil add-all-kernels; then
        return 0
      fi
      note "sdbootutil add-all-kernels failed. Boot entries on the ESP may still point at older initrds."
      # Fall through so we can still try generic tools if present.
    fi
    # If we got here on openSUSE with dracut, we've already made our best
    # effort and printed clear logs, so we don't re-run generic tools.
    return 0
  fi

  # 2. Standard update-initramfs (Debian/Ubuntu)
  if command -v update-initramfs >/dev/null 2>&1 && [[ -d /etc/initramfs-tools ]]; then
    say "Updating initramfs via update-initramfs -u ..."
    if run update-initramfs -u; then
      return 0
    fi
    note "update-initramfs reported an error; initramfs may not have been updated."
    return 1
  fi

  # 3. Standard mkinitcpio (Arch)
  if command -v mkinitcpio >/dev/null 2>&1; then
    say "Updating initramfs via mkinitcpio -P ..."
    if run mkinitcpio -P; then
      return 0
    fi
    note "mkinitcpio reported an error; initramfs may not have been updated."
    return 1
  fi

  # 4. Standard dracut (Fedora/RHEL/legacy systems)
  if command -v dracut >/dev/null 2>&1; then
    say "Updating initramfs via dracut (--force) ..."
    # On many dracut-based systems, overwriting an existing initramfs
    # requires --force; without it, dracut will often refuse to update
    # and silently leave the old image in place.
    if run dracut --force; then
      return 0
    fi
    note "dracut failed even with --force. Your previous initramfs is still on disk."
    return 1
  fi

  say "NOTE: No initramfs update tool detected (sdbootutil, update-initramfs, mkinitcpio, dracut). Skipping."
  return 1
}

# ---------------- VFIO binding service ----------------

install_bind_script() {
  backup_file "$BIND_SCRIPT"

  write_file_atomic "$BIND_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

CONF_FILE="/etc/vfio-gpu-passthrough.conf"
# Timestamp file for the rapid stop/start cooldown guard (dynamic binding mode).
# Written on --release (VM stop), read on --bind-now (VM start) to refuse a
# too-soon restart that can drop the RX 9070 / RDNA4 off the PCI bus.
COOLDOWN_TS_FILE="/var/lib/vfio-dynamic/last-vm-stop.ts"
# State file tracking whether the AMD Windows driver appears to be installed in
# the guest VM. Values: "unknown" (no successful session yet) or
# "likely_installed" (card survived at least one full VM session -> the AMD
# driver is initializing the GPU properly). Used by the release path to decide
# whether to notify the user to install the AMD driver (the card dies ~25s into
# a session without the driver because the Microsoft Basic Display Adapter
# leaves the GPU in an undefined state that crashes the host PCIe bus).
DRIVER_STATUS_FILE="/var/lib/vfio-dynamic/amd-driver-status"

say() { printf '%s\n' "$*"; }

die() {
  say "ERROR: $*" >&2
  exit 1
}

# Best-effort journal tagging so the unbind -> bind -> verify sequence is traceable
# in the system journal (journalctl -t vfio-dynamic). Failures to log are silent.
jlog() {
  command -v logger >/dev/null 2>&1 && logger -t vfio-dynamic -- "$*" 2>/dev/null || true
}

# Best-effort desktop notification (notify-send) to the active desktop user.
# The bind script runs as root (via the libvirt hook), so we must find the
# desktop user's session and send notify-send through runuser with the right
# DBUS_SESSION_BUS_ADDRESS. Silent on failure (no desktop, no notify-send,
# headless, etc.). Used for the AMD-driver-missing warning so the user sees a
# popup instead of having to dig through the journal.
_desktop_notify() {
  local _msg="$1"
  command -v notify-send >/dev/null 2>&1 || return 0
  command -v runuser >/dev/null 2>&1 || return 0
  # Find the first logged-in user with a graphical session.
  local _user _display _bus
  for _user in $(loginctl --no-legend 2>/dev/null | awk '$4=="user"{print $3}' | sort -u); do
    _display="$(loginctl show-session "$(loginctl --no-legend | awk -v u="$_user" '$3==u{print $1; exit}')" -p Display 2>/dev/null | cut -d= -f2)"
    [[ -n "$_display" ]] || continue
    _bus="unix:path=/run/user/$(id -u "$_user")/bus"
    DBUS_SESSION_BUS_ADDRESS="$_bus" runuser -u "$_user" -- notify-send -i dialog-warning "VFIO GPU" "$_msg" 2>/dev/null || true
    return 0
  done
}

[[ -f "$CONF_FILE" ]] || die "Missing $CONF_FILE"
# shellcheck disable=SC1090
. "$CONF_FILE"

: "${GUEST_GPU_BDF:?}"

# Basic sanity: ensure sysfs entries exist.
[[ -d "/sys/bus/pci/devices/$GUEST_GPU_BDF" ]] || die "Guest GPU not present in sysfs: $GUEST_GPU_BDF"

# This script is invoked two ways:
#   1) by vfio-bind-selected-gpu.service at boot (no args) -> ACTION=boot
#   2) by the libvirt qemu hook (vfio-libvirt-hook.sh) with --bind-now or --release
ACTION="boot"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --bind-now) ACTION="bind-now" ;;
    --release)  ACTION="release" ;;
    *) die "Unknown argument: $1" ;;
  esac
  shift
done

binding_mode="${VFIO_BINDING_MODE:-early}"
binding_mode="${binding_mode^^}"
case "$binding_mode" in
  EARLY|DYNAMIC) ;;
  *) binding_mode="EARLY" ;;
esac

csv_to_array() {
  local csv="${1:-}"; shift || true
  local -a out=()
  local IFS=','
  read -r -a out <<<"$csv"
  printf '%s\n' "${out[@]}"
}

# In dynamic mode the boot invocation does NOT bind (amdgpu keeps the card until
# the libvirt hook requests --bind-now at VM start), but it still pins
# d3cold_allowed=0 on the configured guest BDFs (GPU and audio) so the card
# cannot enter D3cold during the amdgpu phase between boot and VM start
# (RX 9070 / RDNA4 reset bug). csv_to_array is defined above so ALL configured
# guest BDFs (GPU + audio functions) are pinned, not just the GPU.
if [[ "$ACTION" == "boot" && "$binding_mode" == "DYNAMIC" ]]; then
  set_d3cold_for_guest_bdfs() {
    local _bdf _sys
    for _bdf in "$GUEST_GPU_BDF" $(csv_to_array "${GUEST_AUDIO_BDFS_CSV:-}"); do
      [[ -n "$_bdf" ]] || continue
      _sys="/sys/bus/pci/devices/$_bdf"
      [[ -d "$_sys" ]] || continue
      echo 0 >"$_sys/d3cold_allowed" 2>/dev/null || true
      # Pin the device in D0 (disable PCI runtime PM) so it cannot slip into
      # D3hot while parked on vfio-pci between VM sessions. d3cold_allowed=0
      # only blocks D3cold; without this, runtime PM (power/control=auto) can
      # still drop the card to D3hot, and on RX 9070 / RDNA4 vfio-pci then
      # fails to power it back on at the next VM start (qemu log: "Unable to
      # power on device, stuck in D3") -> no OVMF/BIOS logo, black until the
      # Windows driver re-initializes the display. vfio-pci.disable_idle_d3=1
      # should do this but is not honored for every device/kernel, so set it
      # explicitly. Writing "on" also forces a runtime resume if the card is
      # already in D3 (pm_runtime_allow -> resume), so bind-time sees D0.
      echo on >"$_sys/power/control" 2>/dev/null || true
    done
  }
  set_d3cold_for_guest_bdfs
  say "Dynamic binding mode: skipping boot-time vfio-pci bind (libvirt hook will bind on VM start); pinned d3cold_allowed=0 + power/control=on (D0) on guest BDFs (GPU + audio)."
  exit 0
fi

modprobe vfio
modprobe vfio-pci
modprobe vfio_iommu_type1

# Returns 0 if the PCI device at $1 is actually alive (config space readable,
# not all 0xff, vendor ID is a real value rather than 0xffff). Returns 1 if the
# device has fallen off the bus / is in a bad reset state — the RX 9070 / RDNA4
# reset bug where a D3cold exit drops the card and its config space reads as all
# 0xff, which qemu surfaces as "Unknown PCI header type 127". A device in that
# state may still show a vfio-pci driver symlink (cached), so the driver link
# alone is NOT a reliable liveness signal.
_pci_dev_alive() {
  local _bdf="$1" _sys _vendor _cfg
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  # vendor sysfs is cached from enumeration; 0xffff means the kernel already
  # knows the device is gone.
  _vendor="$(cat "$_sys/vendor" 2>/dev/null || echo "")"
  [[ -n "$_vendor" ]] || return 1
  [[ "$_vendor" != "0xffff" ]] || return 1
  # Live config-space read is the real liveness test: all 0xff means the card
  # is not responding on the bus even if sysfs still lists it.
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d " \n")"
  [[ -n "$_cfg" ]] || return 1
  [[ "$_cfg" != "ffffffff" ]] || return 1
  return 0
}

# RX 9070 family / RDNA4 (Navi 48, gfx1201) device ID. Gates the PCIe Gen1
# downtrain/adaptive-restore wrapping below (see _pre_reset_gen1_downtrain) to
# this specific card family only — other cards do not need it, or may be
# harmed by it. All 9070 / 9070 XT / 9070 GRE SKUs share device ID 0x7550.
_RX9070_DEVICE_ID="7550"

# Returns 0 if the PCI device at $1 is vendor 1002 / device 7550 (RX 9070
# family). Reads vendor+device straight from live config space (first 4
# bytes) rather than sysfs, so it still works on a device that is mid-recovery.
_is_rx9070() {
  local _bdf="$1" _sys _cfg _vendor _device
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  [[ -n "$_cfg" ]] || return 1
  _vendor="${_cfg:2:2}${_cfg:0:2}"
  _device="${_cfg:6:2}${_cfg:4:2}"
  [[ "${_vendor,,}" == "1002" ]] || return 1
  [[ "${_device,,}" == "$_RX9070_DEVICE_ID" ]]
}

# Read a 16-bit PCI config word via setpci as a clean 4-hex-digit lowercase
# string. Returns 1 on failure/non-hex so callers can bail out safely.
_setpci_word() {
  local _bdf="$1" _off="$2" _v
  _v="$(setpci -s "$_bdf" "$_off" 2>/dev/null || true)"
  [[ -n "$_v" ]] || return 1
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  [[ "$_v" =~ ^[0-9a-fA-F]+$ ]] || return 1
  while (( ${#_v} < 4 )); do _v="0$_v"; done
  printf '%s\n' "${_v,,}"
}

# Map a PCIe link-speed string (e.g. "16 GT/s") to a generation integer
# (1=Gen1 .. 6=Gen6). Returns 1 on unknown/empty.
_speed_to_gen() {
  local _s="${1:-}" _n
  [[ -n "$_s" ]] || return 1
  _n="$(printf '%s' "$_s" | tr -cd '0-9.')"
  [[ -n "$_n" ]] || return 1
  case "$_n" in
    2.5) echo 1 ;;
    5|5.0) echo 2 ;;
    8|8.0) echo 3 ;;
    16|16.0) echo 4 ;;
    32|32.0) echo 5 ;;
    64|64.0) echo 6 ;;
    *) return 1 ;;
  esac
  return 0
}

# Read a sysfs link-speed attribute for a PCI BDF and echo its generation.
_port_speed_gen() {
  local _bdf="$1" _attr="$2" _f _v
  _f="/sys/bus/pci/devices/$_bdf/$_attr"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null)" || _v=""
  [[ -n "$_v" ]] || return 1
  _speed_to_gen "$_v"
}

# Read the current PCIe link width from sysfs for a PCI BDF.
_port_link_width() {
  local _bdf="$1" _f _v
  _f="/sys/bus/pci/devices/$_bdf/current_link_width"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null || true)"
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  printf '%s\n' "$_v"
}

# Find the upstream PCIe switch downstream port for a PCI BDF. Primary: walk
# sysfs (the device is a child of its upstream bridge in the device tree).
# Fallback: if the device's OWN sysfs entry is missing entirely (fell off the
# bus — exactly the case a rescan-only recovery needs this for), resolve the
# upstream bridge via its pci_bus/<domain:bus> subdirectory instead, which
# represents the bus topology independent of whether any downstream device is
# currently enumerated on it.
_gpu_upstream_port() {
  local _gpu="$1" _parent_dir _upstream _dom _bus _p
  [[ -n "$_gpu" ]] || return 1
  _parent_dir="$(ls -d /sys/bus/pci/devices/*/"$_gpu" 2>/dev/null | head -1)"
  if [[ -n "$_parent_dir" ]]; then
    _upstream="$(basename "$(dirname "$_parent_dir")")"
    if [[ -n "$_upstream" ]]; then
      printf '%s\n' "$_upstream"
      return 0
    fi
  fi
  _dom="${_gpu:0:4}"
  _bus="${_gpu:5:2}"
  [[ -n "$_dom" && -n "$_bus" ]] || return 1
  for _p in /sys/bus/pci/devices/*/pci_bus/"${_dom}:${_bus}"; do
    [[ -d "$_p" ]] || continue
    basename "$(dirname "$(dirname "$_p")")"
    return 0
  done
  return 1
}

# Pre-reset Gen1 downtrain, reused from the reboot-FLR monitor's proven fix for
# the SAME underlying issue on this card family (see install_reboot_flr_monitor):
# the on-card PCIe switch's post-reset link retrain at its max gen (Gen5) can
# fail, but forcing the target to Gen1 BEFORE the reset/remove makes the
# retrain reliable (Gen1 retrains fast and succeeds). Applied here to
# remove+rescan / plain function-level-reset recovery at VM-stop/bind time, not
# just the guest-reboot FLR path. Callers gate this to the RX 9070 family via
# _is_rx9070 first (except the fully-missing-directory rescan-only recovery,
# where _is_rx9070 cannot read the device's own config space and this is
# attempted unconditionally instead — see _pci_bus_rescan_only). Stashes
# hardware-detection globals for the matching _post_reset_restore_link call in
# the same recovery attempt.
_pre_reset_gen1_downtrain() {
  local _bdf="$1" _upstream _ctl2 _ctl _sta _i
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  if [[ -z "$_upstream" ]]; then
    jlog "$_bdf: pre-reset Gen1 downtrain skipped (could not find upstream port)"
    return 1
  fi
  if ! command -v setpci >/dev/null 2>&1; then
    jlog "$_bdf: pre-reset Gen1 downtrain skipped (setpci not installed)"
    return 1
  fi
  _RESET_DETECTED_CAP="$(_port_speed_gen "$_upstream" max_link_speed 2>/dev/null || true)"
  _RESET_DETECTED_CUR="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
  _RESET_DETECTED_WIDTH="$(_port_link_width "$_upstream" 2>/dev/null || true)"
  jlog "$_bdf: pre-reset Gen1 downtrain on upstream $_upstream (cap=Gen${_RESET_DETECTED_CAP:-?} cur=Gen${_RESET_DETECTED_CUR:-?} width=x${_RESET_DETECTED_WIDTH:-?})"
  _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
  if [[ -z "$_ctl2" ]]; then
    jlog "$_bdf: pre-reset downtrain aborted (could not read LnkCtl2 from $_upstream)"
    return 1
  fi
  _RESET_SAVED_TARGET="$(printf '%d' "0x${_ctl2:3:1}" 2>/dev/null)" || true
  local _saved_hi="${_ctl2:0:3}"
  local _gen1_ctl2="${_saved_hi}1"
  setpci -s "$_upstream" 88.w="$_gen1_ctl2" 2>/dev/null || true
  jlog "$_bdf: LnkCtl2 set to $_gen1_ctl2 (was $_ctl2) — target Gen1"
  _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
  if [[ -n "$_ctl" ]]; then
    setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
  fi
  jlog "$_bdf: forced link retrain at Gen1 (LnkCtl bit 5 set)"
  for _i in $(seq 1 20); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$_bdf: link active at Gen1 after $(( _i * 100 ))ms"
      return 0
    fi
    sleep 0.1
  done
  jlog "$_bdf: WARN link did not come back at Gen1 within 2s (continuing anyway)"
  return 0
}

# Post-reset adaptive link restore (bounded descent). See
# _pre_reset_gen1_downtrain for the rationale; callers gate this to the RX 9070
# family via _is_rx9070 first, and must call _pre_reset_gen1_downtrain in the
# SAME recovery attempt first so the *_DETECTED_*/_RESET_SAVED_TARGET globals
# are fresh.
_post_reset_restore_link() {
  local _bdf="$1" _upstream _ctl _sta _i _target _neg_gen _g _ctl2 _width _p _best _saved_hi
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  [[ -n "$_upstream" ]] || return 1
  command -v setpci >/dev/null 2>&1 || return 1
  for _i in $(seq 1 50); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$_bdf: link active after reset (waited $(( _i * 100 ))ms)"
      break
    fi
    sleep 0.1
  done
  local _cap="${_RESET_DETECTED_CAP:-}"
  local _cur="${_RESET_DETECTED_CUR:-}"
  local _sav="${_RESET_SAVED_TARGET:-}"
  if [[ -n "$_cap" && -n "$_cur" ]]; then
    if (( _cur < _cap )) 2>/dev/null; then
      _target="$_cur"
      jlog "$_bdf: link was running Gen$_cur < cap Gen$_cap; adapting restore to Gen$_cur"
    else
      _target="$_cap"
      jlog "$_bdf: restoring to detected link capability Gen$_cap"
    fi
  elif [[ -n "$_cap" ]]; then
    _target="$_cap"
  elif [[ -n "$_sav" ]]; then
    _target="$_sav"
  else
    _target=5
  fi
  # Optional operator cap shared with the reboot-FLR monitor: applies to ALL
  # RX 9070 link-retrain recovery now, not just guest reboot.
  local _max="${VFIO_REBOOT_FLR_MAX_GEN:-}"
  if [[ -n "$_max" ]] && (( _max >= 1 && _max <= 6 )) 2>/dev/null; then
    if (( _target > _max )) 2>/dev/null; then
      jlog "$_bdf: VFIO_REBOOT_FLR_MAX_GEN=$_max clamps restore target to Gen$_max"
      _target="$_max"
    fi
  fi
  if ! (( _target >= 1 && _target <= 6 )) 2>/dev/null; then
    _target=5
  fi
  _best=0
  for (( _g = _target; _g >= 1; _g-- )); do
    _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
    if [[ -n "$_ctl2" ]]; then
      _saved_hi="${_ctl2:0:3}"
      setpci -s "$_upstream" 88.w="${_saved_hi}$(printf '%x' "$_g")" 2>/dev/null || true
    fi
    _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
    if [[ -n "$_ctl" ]]; then
      setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
    fi
    jlog "$_bdf: forced link retrain to Gen$_g"
    _neg_gen=""
    for _p in $(seq 1 6); do
      sleep 0.1
      _neg_gen="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
      if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
        break
      fi
    done
    _width="$(_port_link_width "$_upstream" 2>/dev/null || true)"
    if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
      _best="$_neg_gen"
      jlog "$_bdf: restore OK — link back at Gen$_neg_gen x${_width:-?}"
      break
    fi
    if (( _g > 1 )); then
      jlog "$_bdf: WARN link below Gen$_g (got Gen${_neg_gen:-?}); descending to Gen$((_g - 1))"
    fi
  done
  if (( _best == 0 )) 2>/dev/null; then
    jlog "$_bdf: WARN link restore did not settle at any gen >= 1 (cap=Gen${_RESET_DETECTED_CAP:-?}, pre=Gen${_RESET_DETECTED_CUR:-?} x${_RESET_DETECTED_WIDTH:-?}); possible hardware/signal-integrity issue"
  elif (( _best < _target )) 2>/dev/null; then
    jlog "$_bdf: WARN link restore settled at Gen$_best x${_width:-?} (wanted Gen$_target); link up but degraded"
  fi
  return 0
}

# Gated soft function-level reset for the RX 9070 family, wrapping the SAME
# pre-reset Gen1 downtrain + post-reset adaptive link restore already proven in
# the reboot-FLR monitor (see _pre_reset_gen1_downtrain / _post_reset_restore_link).
# Shared by bind_one()'s THREE reset call sites - (1) already-bound-but-ALIVE
# soft FLR to clear a parked-session display wedge after shutdown->start,
# (2) already-bound-but-DEAD recovery (config space unreadable), and (3) the
# opt-in VFIO_DYNAMIC_PCI_RESET=1 pre-bind reset - so the three sites cannot
# drift out of sync. Non-RX-9070 cards get a plain reset (harmless on a healthy
# card). The caller owns the post-reset alive check + logging, since those
# differ per site.
#   $1 = BDF
#   $2 = optional jlog message emitted right after the reset write (empty = none)
#   $3 = guard the reset write behind [[ -w $sys/reset ]] (1=yes [default],
#        0=no, for callers that already verified writability)
#   $4 = post-reset sleep in seconds (default 0.3)
_rx9070_gated_soft_flr() {
  local _bdf="$1" _msg="${2:-}" _guard="${3:-1}" _sleep="${4:-0.3}" _sys _rx=0
  _sys="/sys/bus/pci/devices/$_bdf"
  if _is_rx9070 "$_bdf"; then
    _rx=1
    _pre_reset_gen1_downtrain "$_bdf"
  fi
  if (( _guard )); then
    if [[ -w "$_sys/reset" ]]; then
      echo 1 >"$_sys/reset" 2>/dev/null || true
      if [[ -n "$_msg" ]]; then jlog "$_bdf: $_msg"; fi
      sleep "$_sleep"
    fi
  else
    echo 1 >"$_sys/reset" 2>/dev/null || true
    if [[ -n "$_msg" ]]; then jlog "$_bdf: $_msg"; fi
    sleep "$_sleep"
  fi
  if (( _rx )); then
    _post_reset_restore_link "$_bdf"
  fi
  return 0
}

# Secondary Bus Reset (SBR) of the upstream PCIe switch port for $1 (the GPU).
# A HEAVIER reset than the function-level FLR (_rx9070_gated_soft_flr): it
# pulses RST# on the upstream port's secondary bus (setpci Bridge Control
# register at offset 0x3E, bit 6 = 0x0040), hot-resetting the GPU AND every
# other device behind the same upstream port (e.g. the GPU's audio sibling).
# Used at --release (REBIND_HOST=1) when the pre-rebind soft FLR is NOT enough:
# on Navi 48 / RX 9070 the direct amdgpu/bind after vfio-pci hangs in D-state
# even after a soft FLR (amdgpu's probe never finishes, DRM card never comes up
# -- observed 16:16:25: the FLR fired cleanly but the amdgpu/bind still hung);
# the SBR resets more of the card's internal state (PSP/MC, which the
# function-level FLR does not fully clear) so amdgpu's probe can complete.
#
# Wraps the SAME pre-reset Gen1 downtrain + post-reset adaptive link restore
# already proven for the reboot-FLR / remove+rescan / soft-FLR paths (see
# _pre_reset_gen1_downtrain / _post_reset_restore_link): an SBR drops the PCIe
# link and it must retrain reliably (Gen1 first, then adapt back up to the
# detected capability), exactly the pattern that makes the other resets work on
# this card family. The upstream port is NOT itself reset by the SBR, so its
# LnkCtl2 Gen1 target set by _pre_reset_gen1_downtrain persists across the RST#
# pulse and the link retrains at Gen1 after de-assert.
#
# Caller MUST gate this to the GPU BDF only (reprobe_to_host step 2c/4 checks
# dev == GUEST_GPU_BDF): the audio sibling shares this upstream bridge, and one
# SBR resets BOTH, so running it once on the GPU iteration is enough -- a second
# SBR on the audio iteration would be a redundant double reset of the same bus.
# The caller also owns the unbind + clear_driver_override BEFORE and the direct
# amdgpu bind AFTER. Best-effort: returns 0 even if a setpci step fails (the
# caller proceeds to the bind; a failed SBR is no worse than no SBR).
_secondary_bus_reset() {
  local _bdf="$1" _upstream _brctl _brctl_set _brctl_clr
  [[ -n "$_bdf" ]] || return 1
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  if [[ -z "$_upstream" ]]; then
    jlog "$_bdf: SBR skipped (could not find upstream port)"
    return 1
  fi
  if ! command -v setpci >/dev/null 2>&1; then
    jlog "$_bdf: SBR skipped (setpci not installed)"
    return 1
  fi
  # Pre-reset Gen1 downtrain (stashes detected cap/cur/width globals for the
  # matching _post_reset_restore_link call below -- same as _rx9070_gated_soft_flr).
  _pre_reset_gen1_downtrain "$_bdf"
  # Read the upstream port's Bridge Control register (offset 0x3E, 16-bit).
  _brctl="$(_setpci_word "$_upstream" 3E.w 2>/dev/null || true)"
  if [[ -z "$_brctl" ]]; then
    jlog "$_bdf: SBR aborted (could not read Bridge Control from $_upstream)"
    return 1
  fi
  # Assert Secondary Bus Reset (bit 6 = 0x0040): pulses RST# on the secondary
  # bus, hot-resetting the GPU and every device behind the same upstream port.
  _brctl_set="$(printf '%04x' $(( 0x$_brctl | 0x0040 )) )"
  setpci -s "$_upstream" 3E.w="$_brctl_set" 2>/dev/null || true
  jlog "$_bdf: SBR assert on $_upstream (BridgeCtl 0x$_brctl -> 0x$_brctl_set, bit6 RST# set)"
  # Hold reset: PCIe TPerst must be asserted >= 2ms; give a generous margin.
  sleep 0.05
  # De-assert SBR (clear bit 6 via AND ~0x0040 = 0xFFBF) so the link retrains.
  _brctl_clr="$(printf '%04x' $(( 0x$_brctl & 0xFFBF )) )"
  setpci -s "$_upstream" 3E.w="$_brctl_clr" 2>/dev/null || true
  jlog "$_bdf: SBR de-assert on $_upstream (BridgeCtl -> 0x$_brctl_clr, RST# cleared); link retraining"
  # Post-reset adaptive link restore (bounded descent back to detected cap).
  _post_reset_restore_link "$_bdf"
  jlog "$_bdf: SBR complete (upstream $_upstream reset, link restored)"
  return 0
}

# Last-resort recovery for a dead PCI device: remove it from the bus, rescan
# the whole PCI bus to force re-enumeration, then re-bind to vfio-pci. This is
# the final recovery step before telling the user to reboot the host. On RX
# 9070 / RDNA4 the soft function-level reset often does NOT recover a card that
# fell off the bus on a D3cold exit; remove+rescan forces the kernel to
# re-enumerate the device, which can sometimes bring it back. Empirically this
# does NOT always work on the RX 9070 (the GPU function may stay gone while the
# audio function comes back), but it is worth attempting as a final step before
# requiring a host reboot, since it recovers the card in some borderline cases.
# RX 9070 family: wraps the remove+rescan with the SAME pre/post Gen1-downtrain
# and adaptive link restore already proven for the guest-reboot FLR path (see
# _pre_reset_gen1_downtrain), since a plain `rescan` has no mechanism of its own
# to force the PCIe link to retrain if it is already down when the card zombies.
# Two-phase graduated recovery: Phase 1 is the lighter remove+rescan; if that
# fails (device never reappeared OR reappeared as a config-space-unreadable
# zombie), Phase 2 escalates to a Secondary Bus Reset of the upstream PCIe
# switch port (see _secondary_bus_reset) -- RST# hot-resets the GPU and forces a
# full link retrain, the proven recovery for an RX 9070 / RDNA4 dropped off the
# bus by a force-kill VM (virsh destroy / BSOD). The card is already dead when
# Phase 2 runs, so there is no healthy card to harm. Runs at --release time
# (shared by live-attach and standard dynamic binding) and from the
# park-keepalive monitor, so force-kill survival works both ways.
# Returns 0 if the device is alive and on vfio-pci after recovery, 1 otherwise.
_pci_dev_remove_rescan() {
  local _bdf="$1" _sys _rx9070=0
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  jlog "$_bdf: attempting remove+rescan recovery (last resort before host reboot)"
  say "WARN: $_bdf attempting remove+rescan bus recovery (last resort before requiring a host reboot)." >&2
  if _is_rx9070 "$_bdf"; then
    _rx9070=1
    _pre_reset_gen1_downtrain "$_bdf"
  fi
  # Phase 1 (light): remove the device from the bus, then rescan to re-enumerate.
  if [[ -w "$_sys/remove" ]]; then
    echo 1 >"$_sys/remove" 2>/dev/null || true
    jlog "$_bdf: removed from PCI bus"
    sleep 1
  fi
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  jlog "$_bdf: PCI bus rescan triggered"
  sleep 1
  if [[ -d "$_sys" ]]; then
    # RX 9070 family: adaptively restore the link speed now that the device is
    # back in sysfs, before touching driver binding.
    if (( _rx9070 )); then
      _post_reset_restore_link "$_bdf"
    fi
    echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
    echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
    sleep 0.3
    if _pci_dev_alive "$_bdf"; then
      jlog "$_bdf: recovered after remove+rescan (alive)"
      return 0
    fi
  fi
  # Phase 2 (heavy): the lighter remove+rescan did not recover the device
  # (never reappeared, or reappeared as a config-space-unreadable zombie).
  # Escalate to a Secondary Bus Reset of the upstream PCIe switch port -- RST#
  # hot-resets the GPU (and its audio sibling) and forces a full PCIe link
  # retrain, the proven recovery for an RX 9070 / RDNA4 that dropped off the
  # bus on a force-kill VM (virsh destroy / BSOD) where plain remove+rescan
  # fails. The card is already dead here so there is no healthy card to harm;
  # _secondary_bus_reset resolves the upstream port via the pci_bus fallback
  # even when the GPU's own sysfs entry is gone. After SBR, rescan to
  # re-enumerate then bind vfio-pci. This runs at --release time (zombie
  # detected immediately after a force-kill VM stop) and benefits BOTH
  # live-attach and standard dynamic binding (the release path is shared).
  jlog "$_bdf: did not reappear after rescan (or reappeared dead); escalating to Secondary Bus Reset (RST# on upstream port)"
  say "WARN: $_bdf remove+rescan failed; escalating to Secondary Bus Reset (heavier bus reset) to recover the force-killed card." >&2
  _secondary_bus_reset "$_bdf" || true
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  jlog "$_bdf: PCI bus rescan triggered after SBR"
  sleep 1
  [[ -d "$_sys" ]] || { jlog "$_bdf: did not reappear after SBR+rescan; needs host reboot"; return 1; }
  echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
  echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
  sleep 0.3
  if _pci_dev_alive "$_bdf"; then
    jlog "$_bdf: recovered after SBR+rescan (alive)"
    return 0
  fi
  jlog "$_bdf: still dead after SBR+rescan; needs host reboot"
  return 1
}

bind_one() {
  local dev="$1"
  [[ -n "$dev" ]] || return 0

  local sys="/sys/bus/pci/devices/$dev"
  [[ -d "$sys" ]] || die "PCI device not present in sysfs: $dev"

  # Prevent D3cold entry (RX 9070 / RDNA4 reset bug: card falls off bus on D3cold exit).
  # This is set both at bind time and (in dynamic mode) by the boot unit so the card
  # cannot enter D3cold even while it is still on amdgpu, before VM start.
  echo 0 >"$sys/d3cold_allowed" 2>/dev/null || true
  # Pin in D0 (disable runtime PM). Same rationale as set_d3cold_for_guest_bdfs:
  # d3cold_allowed=0 alone does not stop D3hot, and a D3hot card wedges at the
  # next qemu attach ("stuck in D3"). Writing "on" here ALSO resumes the card if
  # it already slipped to D3 while parked, so the fresh VM start sees D0 and
  # OVMF can run the GPU GOP -> BIOS logo shows on shutdown->start.
  echo on >"$sys/power/control" 2>/dev/null || true

  # Already on vfio-pci: avoid a wasteful unbind -> sleep -> rebind cycle on a
  # rapid VM stop/start. BUT verify the device is actually alive first — the
  # RX 9070 / RDNA4 reset bug can drop the card off the bus between VM stop and
  # the next start, leaving a vfio-pci driver symlink pointing at a dead device
  # whose config space reads all 0xff (qemu then surfaces "Unknown PCI header
  # type 127"). If the card is dead, do NOT report success: attempt a PCI
  # function-level reset + re-probe, and if it is still dead, fail hard so
  # libvirt aborts the VM start cleanly instead of qemu hitting a dead card.
  if [[ -L "$sys/driver" ]]; then
    local _already_drv
    _already_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
    if [[ "$_already_drv" == "vfio-pci" ]]; then
      if _pci_dev_alive "$dev"; then
        # Default (VFIO_DYNAMIC_SOFT_FLR_ON_BIND != 1): the card is alive and
        # already on vfio-pci from a previous VM session. The vBIOS file pin
        # (<rom file=.../>, installed by install_vbios_romfile) lets qemu read
        # the GOP ROM from the FILE, so the soft FLR + unbind + rebind below
        # (originally added to clear the live ROM BAR 0xffff) is NO LONGER
        # NEEDED. And worse: that soft FLR + rebind DESTABILIZES the RX 9070 /
        # RDNA4 -- the card passes the alive-check right after the rebind but
        # falls off the bus ~3s later (config space -> ff ff ff ff), so qemu's
        # vfio-pci attach hits a dead card and reports "Unable to power on
        # device, stuck in D3" -> no OVMF/BIOS logo, black until Windows
        # re-initializes the display. Keeping the card as-is (skip the FLR),
        # re-pinning D0, and returning success lets qemu attach a LIVE card
        # that reads the GOP ROM from the file -> OVMF POSTs -> logo shows on
        # shutdown->start. Set VFIO_DYNAMIC_SOFT_FLR_ON_BIND=1 to opt back into
        # the soft FLR (only if you have NO vBIOS file pin AND you hit the
        # live-ROM 0xffff).
        if [[ "${VFIO_DYNAMIC_SOFT_FLR_ON_BIND:-0}" != "1" ]]; then
          echo on >"$sys/power/control" 2>/dev/null || true
          jlog "$dev: already on vfio-pci (alive); keeping as-is (vBIOS file pin handles the ROM; soft FLR skipped to avoid the RX 9070 reset-bug zombie) so qemu attaches a live card"
          return 0
        fi
        # Opt-in soft FLR (VFIO_DYNAMIC_SOFT_FLR_ON_BIND=1): for setups with NO
        # vBIOS file pin that still hit the live-ROM 0xffff.
        # Card is alive AND already on vfio-pci from a previous VM session
        # (parked after shutdown). BUT the display engine may still be in a
        # stale state from that previous session — OVMF cannot re-POST on a
        # wedged display even though the PCI device itself is alive (config
        # space readable, vendor not 0xffff). This is the exact gap between a
        # warm reboot (where the reboot-FLR monitor does a soft FLR to clear
        # the display wedge) and a normal shutdown→start (where no FLR was
        # done, so the display stays wedged and the monitor gets no signal).
        # Fix: do a soft FLR here — same technique as do_flr() in the
        # reboot-FLR monitor — to clear the display engine so OVMF can re-POST.
        # Gated to RX 9070 family for the Gen1 downtrain/adaptive restore
        # (other cards do a plain reset, which is harmless on a healthy card).
        jlog "$dev: already on vfio-pci (alive); applying soft FLR to clear display state from previous VM session"
        _rx9070_gated_soft_flr "$dev" "soft FLR applied (display wedge clear for next VM session)" 1 0.3
        # Verify still alive after the FLR. If the FLR killed it (rare but
        # possible on a borderline card), fall through to the dead-card
        # recovery path below instead of returning success.
        if _pci_dev_alive "$dev"; then
          # Soft FLR zeroed the ROM BAR, so qemu's live option-ROM read at the
          # fresh VM start returns 0xffff (dmesg: "Invalid PCI ROM header
          # signature: expecting 0xaa55, got 0xffff") -> OVMF cannot run the
          # GPU's UEFI GOP -> no firmware logo / signal but black until the
          # Windows driver loads. This is exactly why a warm reboot (qemu
          # never re-reads the ROM, display already POSTed) works but a
          # shutdown->start does not. Fix: rebind vfio-pci so the PCI core
          # re-enables the device and restores the ROM BAR, the same way a
          # cold amdgpu -> vfio-pci handoff does.
          jlog "$dev: alive after soft FLR; rebinding vfio-pci to restore ROM/BARs (prevents 0xffff ROM read so OVMF can re-POST)"
          if [[ -w "/sys/bus/pci/drivers/vfio-pci/unbind" ]]; then
            echo "$dev" >"/sys/bus/pci/drivers/vfio-pci/unbind" 2>/dev/null || true
            jlog "$dev: unbind from vfio-pci (post-FLR rebind)"
            sleep 0.3
          fi
          echo vfio-pci >"$sys/driver_override" 2>/dev/null || true
          local _rb_att _rb_maxa=3 _rb_bound=0 _rb_drv
          for _rb_att in $(seq 1 "$_rb_maxa"); do
            echo "$dev" >"/sys/bus/pci/drivers/vfio-pci/bind" 2>/dev/null || true
            _rb_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
            if [[ "$_rb_drv" == "vfio-pci" ]]; then
              jlog "$dev: rebound on attempt $_rb_att"
              _rb_bound=1
              break
            fi
            (( _rb_att < _rb_maxa )) && sleep 0.2
          done
          if (( _rb_bound )) && _pci_dev_alive "$dev"; then
            # Re-pin D0 AFTER the rebind: the vfio-pci probe above resets
            # power/control to auto (vfio-pci.disable_idle_d3=1 is NOT honored
            # for this device on this kernel), and with auto the idle card
            # runtime-suspends to D3hot in the ~3s gap before qemu attaches --
            # qemu then reports "Unable to power on device, stuck in D3" and
            # OVMF cannot POST (no BIOS logo, black until the Windows driver
            # re-inits). This re-pin is the LAST write before qemu attaches, so
            # the card stays D0 through qemu's attach-time reset -> OVMF GOP
            # runs -> logo shows on shutdown->start.
            echo on >"$sys/power/control" 2>/dev/null || true
            jlog "$dev: re-pinned power/control=on (D0) after soft-FLR rebind so qemu attaches a powered-on card"
            jlog "$dev: bound to vfio-pci (verified, alive) after soft-FLR rebind"
            return 0
          fi
          jlog "$dev: WARN soft-FLR rebind failed; falling through to dead-card recovery"
        else
          jlog "$dev: WARN dead after soft FLR (borderline card); falling through to dead-card recovery"
        fi
        # Fall through to the dead-card recovery below (do NOT return 0).
      fi
      jlog "$dev: on vfio-pci but config space unreadable (header type 127 / card gone); attempting PCI reset + re-probe"
      say "WARN: $dev is bound to vfio-pci but its config space is unreadable (RX 9070 / RDNA4 reset bug: card fell off the bus). Attempting a PCI function-level reset + re-probe." >&2
      _rx9070_gated_soft_flr "$dev" "" 1 0.3
      if _pci_dev_alive "$dev"; then
        jlog "$dev: recovered after PCI reset (alive); keeping on vfio-pci"
        return 0
      fi
      # Last-resort: remove+rescan bus recovery before giving up.
      if _pci_dev_remove_rescan "$dev"; then
        jlog "$dev: recovered after remove+rescan (alive); keeping on vfio-pci"
        return 0
      fi
      say "ERROR: $dev is bound to vfio-pci but is not alive (config space all 0xff, qemu would report "Unknown PCI header type 127"). A PCI reset and a remove+rescan bus recovery both failed to recover it. The card needs a host reboot to come back. Aborting VM start so the host display stays alive." >&2
      jlog "$dev: FAILED alive-check (header 127); PCI reset + remove+rescan did not recover; aborting VM start"
      return 1
    fi
  fi

  # Unbind from current driver if any (amdgpu/snd), then wait briefly for the
  # driver teardown to settle. Some AMD cards need a short delay between unbind
  # and the vfio-pci bind attempt or the first bind races the async teardown.
  # INSTRUMENTED: the unbind write is bracketed by before/after jlog so a
  # D-state hang (observed: --bind-now wedged in uninterruptible sleep on the
  # amdgpu unbind after a prior failed rebind) shows the EXACT sysfs path that
  # blocked in journalctl -t vfio-dynamic.
  # REMEMBER the pre-vfio-pci host driver: persist it to the state dir so
  # reprobe_to_host (--release, REBIND_HOST=1) can bind DIRECTLY to it later
  # via /sys/bus/pci/drivers/<prev>/bind -- which is a different kernel code
  # path than /sys/bus/pci/drivers_probe and avoids the confirmed SIGSEGV
  # (exit 139) the generic PCI-core re-probe hits on Navi 48 after vfio-pci.
  # Best-effort; never fatal.
  if [[ -L "$sys/driver" ]]; then
    local drv
    drv="$(basename "$(readlink "$sys/driver")")"
    if [[ -n "$drv" && "$drv" != "vfio-pci" ]]; then
      mkdir -p "$(dirname "$COOLDOWN_TS_FILE")" 2>/dev/null || true
      printf '%s\n' "$drv" >"$(dirname "$COOLDOWN_TS_FILE")/$dev.prev_driver" 2>/dev/null || true
      jlog "$dev: remembered pre-vfio-pci host driver=$drv (for direct rebind on release)"
    fi
    if [[ -w "/sys/bus/pci/drivers/$drv/unbind" ]]; then
      jlog "$dev: unbind from $drv (before)"
      echo "$dev" >"/sys/bus/pci/drivers/$drv/unbind" || true
      jlog "$dev: unbind from $drv (after)"
    fi
    sleep 0.3
  fi

  # Optional function-level reset before bind (opt-in via VFIO_DYNAMIC_PCI_RESET=1).
  # On RX 9070 / RDNA4 a reset after amdgpu teardown can clear residual device
  # state that otherwise makes the first vfio-pci bind fail with "Unknown PCI
  # header type 127". Only attempted when the sysfs reset file is writable (the
  # device must be unbound). Default OFF: a reset on a healthy card is unnecessary
  # and on a mid-reset card can worsen the state; enable only on repeated failures.
  if [[ "${VFIO_DYNAMIC_PCI_RESET:-0}" == "1" && -w "$sys/reset" ]]; then
    _rx9070_gated_soft_flr "$dev" "pci reset attempted" 0 0.1
  fi

  echo vfio-pci >"$sys/driver_override"

  # Retry the bind a few times. On the RX 9070 the amdgpu -> vfio-pci handoff
  # can fail transiently even though a retry a moment later succeeds. Total
  # retry budget stays well under libvirt's default hook timeout.
  local _attempt _max_attempts _drv
  _max_attempts=3
  _drv=""
  for _attempt in $(seq 1 "$_max_attempts"); do
    # INSTRUMENTED: bracket the bind write so a D-state hang here (observed on
    # a card left in a bad state by a prior failed rebind) is attributable to
    # this exact sysfs path in journalctl -t vfio-dynamic.
    jlog "$dev: vfio-pci bind attempt $_attempt/$_max_attempts (before)"
    echo "$dev" >"/sys/bus/pci/drivers/vfio-pci/bind" 2>/dev/null || true
    jlog "$dev: vfio-pci bind attempt $_attempt/$_max_attempts (after)"
    _drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
    if [[ "$_drv" == "vfio-pci" ]]; then
      jlog "$dev: bound on attempt $_attempt"
      break
    fi
    if (( _attempt < _max_attempts )); then
      sleep 0.2
    fi
  done

  # Verify the device actually landed on vfio-pci AND is alive. Return non-zero
  # on failure so the libvirt hook (--bind-now) aborts the VM start cleanly
  # instead of letting libvirt continue with a device that is not bound, or a
  # device that is bound but dead (config space all 0xff, which qemu surfaces as
  # "Unknown PCI header type 127").
  if [[ "$_drv" != "vfio-pci" ]]; then
    jlog "$dev: FAILED to bind to vfio-pci (got: ${_drv:-none}) after $_max_attempts attempts"
    say "ERROR: $dev failed to bind to vfio-pci (got: ${_drv:-none}) after $_max_attempts attempts." >&2
    say "ERROR: Aborting VM start. Next steps:" >&2
    say "  - check dmesg:        dmesg | tail -n 50" >&2
    say "  - check libvirt:      journalctl -u libvirtd --no-pager | tail -n 50" >&2
    say "  - confirm device:     lspci -nnk -s $dev" >&2
    say "  - try a manual reset: echo 1 > /sys/bus/pci/devices/$dev/reset" >&2
    say "  - or switch to early: vfio.sh --install-early-binding" >&2
    return 1
  fi
  if ! _pci_dev_alive "$dev"; then
    # Last-resort: remove+rescan bus recovery before giving up.
    if _pci_dev_remove_rescan "$dev"; then
      jlog "$dev: recovered after remove+rescan (alive) post-bind"
    else
      say "ERROR: $dev bound to vfio-pci but its config space is unreadable (RX 9070 / RDNA4 reset bug: "Unknown PCI header type 127"). qemu would fail to start. A PCI reset and a remove+rescan bus recovery both failed. Aborting VM start. Next steps:" >&2
      say "  - reboot the host (the card needs a cold reset to come back on the bus)" >&2
      say "  - then start the VM; avoid rapid stop/start cycles" >&2
      say "  - if it recurs, enable VFIO_DYNAMIC_PCI_RESET=1 in /etc/vfio-gpu-passthrough.conf" >&2
      say "  - keep VFIO_DYNAMIC_COOLDOWN_SECONDS (default 10) above 0 to prevent rapid stop/start" >&2
      return 1
    fi
  fi

  # Re-pin D0 as the LAST write before qemu attaches: the vfio-pci bind above
  # (cold-start path) resets power/control to auto (disable_idle_d3=1 is not
  # honored for this device), and with auto the idle card can runtime-suspend
  # to D3hot before qemu attaches -> "stuck in D3" -> no OVMF logo. Same fix
  # as the alive-parked rebind path above.
  echo on >"$sys/power/control" 2>/dev/null || true
  jlog "$dev: re-pinned power/control=on (D0) after bind so qemu attaches a powered-on card"
  jlog "$dev: bound to vfio-pci (verified, alive)"
}

clear_override() {
  local dev="$1"
  [[ -n "$dev" ]] || return 0
  local sys="/sys/bus/pci/devices/$dev"
  [[ -d "$sys" ]] || return 0
  echo "" >"$sys/driver_override" || true
}

reprobe_to_host() {
  # Best-effort: unbind from vfio-pci, clear the driver_override, and trigger a
  # generic driver re-probe so the normal host driver (amdgpu/snd) can reclaim
  # the device. Used by --release when VFIO_DYNAMIC_REBIND_HOST=1.
  #
  # INSTRUMENTED: every sysfs write is bracketed by a before/after jlog so the
  # journal (journalctl -t vfio-dynamic) shows the EXACT last step that
  # succeeded if a later step segfaults (observed: --release exited 139/SIGSEGV
  # on an RX 9070 during this handoff) or hangs in D-state (observed: a bind-now
  # after a failed rebind wedged libvirt). Without this instrumentation the
  # crash site was invisible.
  #
  # ROBUST: after the drivers_probe kick, the kernel re-probe is ASYNC -- we
  # settle (sleep 0.5s) then VERIFY the host driver (amdgpu/snd) actually bound
  # with a bounded poll (VFIO_REBIND_VERIFY_TIMEOUT, default 2s). Previously the
  # next step ran on a still-unbound card, racing the probe. The caller (the
  # release case) re-checks _pci_dev_alive after this returns and runs
  # remove+rescan recovery if the card fell off.
  #
  # NOTE: d3cold_allowed is deliberately left at 0 by default here. The RX 9070 /
  # RDNA4 reset bug means the card can fall off the bus on D3cold exit even on the
  # host, so D3cold stays disabled after release. Do NOT restore it to 1 unless you
  # opt in via VFIO_RESTORE_D3COLD_ON_RELEASE=1 (see the guarded restore below).
  local dev="$1"
  [[ -n "$dev" ]] || return 0
  local sys="/sys/bus/pci/devices/$dev"
  [[ -d "$sys" ]] || { jlog "$dev: reprobe_to_host: sysfs dir gone, nothing to rebind"; return 0; }
  local _was_drv
  _was_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo none)"
  jlog "$dev: reprobe_to_host start (was driver=${_was_drv:-none})"
  # 1/4. unbind from vfio-pci (bracketed so a crash here is attributable).
  if [[ -L "$sys/driver" ]]; then
    local drv
    drv="$(basename "$(readlink "$sys/driver")")"
    if [[ "$drv" == "vfio-pci" ]] && [[ -w "/sys/bus/pci/drivers/$drv/unbind" ]]; then
      jlog "$dev: reprobe step 1/4 unbind from $drv (before)"
      echo "$dev" >"/sys/bus/pci/drivers/$drv/unbind" 2>/dev/null || true
      jlog "$dev: reprobe step 1/4 unbind from $drv (after)"
      sleep 0.3
    fi
  fi
  # 2/4. clear driver_override so the re-probe is not forced to vfio-pci.
  jlog "$dev: reprobe step 2/4 clear driver_override (before)"
  echo "" >"$sys/driver_override" 2>/dev/null || true
  jlog "$dev: reprobe step 2/4 clear driver_override (after)"
  # 2b/4 + 2c/4. Opt-in pre-rebind reset BEFORE the amdgpu rebind: reset the
  # card to a clean state amdgpu expects before it re-grabs it. Two levels,
  # mutually exclusive (SBR takes precedence -- it is strictly heavier and
  # supersedes the FLR):
  #   - 2c/4 Secondary Bus Reset (VFIO_DYNAMIC_SBR_BEFORE_REBIND=1): pulses RST#
  #     on the upstream port's secondary bus via setpci Bridge Control 0x3E
  #     bit 6, hot-resetting the GPU AND every device behind the same upstream
  #     port (e.g. the audio sibling). HEAVIER than the FLR -- resets more of
  #     the card's internal state (PSP/MC) so amdgpu's probe can complete when
  #     the soft FLR was not enough (observed 16:16:25: FLR fired but amdgpu/bind
  #     still hung in D-state). GPU BDF ONLY: one SBR resets the audio sibling
  #     too, so it runs once on the GPU iteration and is skipped for audio (a
  #     second SBR on the audio iteration would double-reset the same bus).
  #   - 2b/4 soft FLR (VFIO_DYNAMIC_FLR_BEFORE_REBIND=1): function-level reset of
  #     the GPU only (echo 1 > sys/reset). Lighter; the first thing to try. Only
  #     when the device is unbound (reset file writable) -- it is, after step
  #     1/4 unbind + step 2/4 clear override.
  # Both default 0 (opt-in): an unnecessary reset on a card that rebinds cleanly
  # is wasted work and can itself destabilize a borderline card.
  if [[ "${VFIO_DYNAMIC_SBR_BEFORE_REBIND:-0}" == "1" && "$dev" == "${GUEST_GPU_BDF:-}" ]]; then
    jlog "$dev: reprobe step 2c/4 pre-rebind SBR (before)"
    _secondary_bus_reset "$dev"
    jlog "$dev: reprobe step 2c/4 pre-rebind SBR (after)"
  elif [[ "${VFIO_DYNAMIC_FLR_BEFORE_REBIND:-0}" == "1" && -w "$sys/reset" ]]; then
    jlog "$dev: reprobe step 2b/4 pre-rebind soft FLR (before)"
    _rx9070_gated_soft_flr "$dev" "pre-rebind FLR applied (card reset to clean state before amdgpu re-grabs)" 0 0.3
    jlog "$dev: reprobe step 2b/4 pre-rebind soft FLR (after)"
  fi
  # 3/4. Rebind the host driver. PREFER a DIRECT bind to the driver that was
  # bound before vfio-pci (remembered at bind time) via
  # /sys/bus/pci/drivers/<prev>/bind -- a different kernel code path than the
  # generic /sys/bus/pci/drivers_probe re-probe. The generic re-probe
  # SEGFAULTS (exit 139) on Navi 48 after vfio-pci (confirmed: --release at
  # 21:25:21 crashed at the drivers_probe write with SIGSEGV, wedging
  # libvirt). The direct bind avoids the PCI-core bus re-probe wrapper that
  # faults. Fall back to drivers_probe ONLY if no prior driver is remembered
  # or the direct bind did not land a host driver.
  local _prev_drv="" _prev_file
  _prev_file="$(dirname "$COOLDOWN_TS_FILE")/$dev.prev_driver"
  [[ -f "$_prev_file" ]] && _prev_drv="$(cat "$_prev_file" 2>/dev/null || true)"
  local _direct_ok=0
  if [[ -n "$_prev_drv" && -w "/sys/bus/pci/drivers/$_prev_drv/bind" ]]; then
    jlog "$dev: reprobe step 3/4 direct bind to $_prev_drv (before)"
    echo "$dev" >"/sys/bus/pci/drivers/$_prev_drv/bind" 2>/dev/null || true
    jlog "$dev: reprobe step 3/4 direct bind to $_prev_drv (after)"
    sleep 0.5  # let the driver probe settle
    local _direct_drv
    _direct_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
    if [[ "$_direct_drv" == "$_prev_drv" ]]; then
      _direct_ok=1
      jlog "$dev: reprobe step 3/4 direct bind landed on $_prev_drv (no drivers_probe needed)"
    else
      jlog "$dev: reprobe step 3/4 direct bind to $_prev_drv did not land (got ${_direct_drv:-none}); falling back to drivers_probe"
    fi
  else
    jlog "$dev: reprobe step 3/4 no remembered prev driver (${_prev_drv:-none}); using drivers_probe fallback"
  fi
  if (( ! _direct_ok )) && [[ -w /sys/bus/pci/drivers_probe ]]; then
    # FALLBACK: the generic PCI-core re-probe. This is the path that
    # segfaulted on Navi 48; kept as a last resort for cards where no prev
    # driver was remembered (e.g. first run after an upgrade).
    jlog "$dev: reprobe step 3/4 drivers_probe write (before) [CRASH-PRONE on Navi 48]"
    echo "$dev" >/sys/bus/pci/drivers_probe 2>/dev/null || true
    jlog "$dev: reprobe step 3/4 drivers_probe write (after)"
    sleep 0.5  # kernel re-probe is async; let amdgpu/snd probe settle
  fi
  # 3b/4. VERIFY a host driver actually bound, with a bounded poll. The verify
  # is diagnostic + a settle gate; reprobe_to_host stays best-effort (returns 0)
  # so set -e in the caller cannot abort the release -- the caller does its own
  # _pci_dev_alive check and remove+rescan recovery if the card fell off.
  local _vp_att _vp_max _vp_drv=""
  _vp_max=10
  [[ "${VFIO_REBIND_VERIFY_TIMEOUT:-}" =~ ^[0-9]+$ ]] && _vp_max=$(( VFIO_REBIND_VERIFY_TIMEOUT * 5 ))
  for _vp_att in $(seq 1 "$_vp_max"); do
    _vp_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
    [[ "$_vp_drv" == "amdgpu" || "$_vp_drv" == "snd_hda_intel" ]] && break
    sleep 0.2
  done
  if [[ -n "$_vp_drv" ]]; then
    jlog "$dev: reprobe step 3b/4 verified on $_vp_drv (poll $_vp_att/$_vp_max)"
  else
    jlog "$dev: reprobe step 3b/4 WARN no host driver bound after $_vp_max polls (last=${_vp_drv:-none}); card may have fallen off the bus"
  fi
  # 3c/4. amdgpu-readiness settle: if the card landed on amdgpu, do NOT return
  # until amdgpu has FINISHED probing (DRM card node up). amdgpu's probe is
  # async; the driver symlink appears early but the DRM card appears at the
  # END of probe. If the next --bind-now unbinds amdgpu before the DRM card is
  # up, the kernel can hang in D-state (observed 15:36:49 on Navi 48).
  # _wait_amdgpu_ready polls for the DRM card with a bounded window.
  if [[ "$_vp_drv" == "amdgpu" ]]; then
    jlog "$dev: reprobe step 3c/4 amdgpu landed; waiting for amdgpu-readiness (DRM card up) before returning"
    _wait_amdgpu_ready "$dev" || true
  fi
  # 4/4. d3cold_allowed + power/control. Default keeps the card pinned in D0
  # (no D3hot, no D3cold) to avoid the RX 9070 / RDNA4 reset bug on the host.
  if [[ "${VFIO_RESTORE_D3COLD_ON_RELEASE:-0}" == "1" ]]; then
    echo 1 >"$sys/d3cold_allowed" 2>/dev/null || true
    echo auto >"$sys/power/control" 2>/dev/null || true
    jlog "$dev: reprobe step 4/4 d3cold=1 power/control=auto (opt-in RESTORE_D3COLD)"
  else
    echo on >"$sys/power/control" 2>/dev/null || true
    jlog "$dev: reprobe step 4/4 power/control=on (D0 pin default)"
  fi
  local _now_drv
  _now_drv="$(basename "$(readlink "$sys/driver" 2>/dev/null)" 2>/dev/null || echo none)"
  jlog "$dev: reprobe_to_host done (now driver=${_now_drv:-none})"
}

# Safety pre-flight: refuse if the guest GPU or any guest audio BDF is also
# listed as host audio. do_bind re-checks each bind, but failing early gives a
# clearer error before any sysfs writes happen.
for dev in $(csv_to_array "${HOST_AUDIO_BDFS_CSV:-}"); do
  [[ "$dev" != "$GUEST_GPU_BDF" ]] || die "Refusing: guest GPU is also listed as host audio ($dev)"
  if grep -Eq "(^|,)${dev}($|,)" <<<"${GUEST_AUDIO_BDFS_CSV:-}"; then
    die "Refusing: guest audio $dev is also listed as host audio"
  fi
done

do_bind() {
  # Bind guest GPU first.
  bind_one "$GUEST_GPU_BDF" || die "Guest GPU $GUEST_GPU_BDF failed to bind to vfio-pci"

  # Bind selected guest audio functions.
  while IFS= read -r dev; do
    [[ -n "$dev" ]] || continue
    # Do not bind if user accidentally selected same BDF for host audio.
    if grep -Eq "(^|,)${dev}($|,)" <<<"${HOST_AUDIO_BDFS_CSV:-}"; then
      die "Refusing to bind $dev: it is configured as host audio"
    fi
    bind_one "$dev" || die "Guest audio $dev failed to bind to vfio-pci"
  done < <(csv_to_array "${GUEST_AUDIO_BDFS_CSV:-}")

  # Ensure host audio functions are NOT overridden.
  while IFS= read -r dev; do
    clear_override "$dev"
  done < <(csv_to_array "${HOST_AUDIO_BDFS_CSV:-}")

  # Post-check: verify guest GPU is bound to vfio-pci.
  if [[ -L "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver" ]]; then
    local drv
    drv="$(basename "$(readlink "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver")")"
    [[ "$drv" == "vfio-pci" ]] || die "Guest GPU driver is '$drv' (expected vfio-pci)."
  fi
}

# Map a PCI BDF to its primary DRM card device path (e.g. /dev/dri/card1) by
# walking /sys/class/drm/card*/device symlinks. Prints /dev/dri/cardN and
# returns 0 on match, returns 1 if no DRM card is bound to that BDF.
_bdf_to_drm_card() {
  local _bdf="$1" _card _dev_bdf
  [[ -n "$_bdf" ]] || return 1
  for _card in /sys/class/drm/card[0-9]*; do
    [[ -e "$_card" ]] || continue
    case "$(basename "$_card")" in card[0-9]*-*) continue ;; esac
    _dev_bdf="$(basename "$(readlink -f "$_card/device" 2>/dev/null)" 2>/dev/null || true)"
    if [[ "$_dev_bdf" == "$_bdf" ]]; then
      printf '/dev/dri/%s\n' "$(basename "$_card")"
      return 0
    fi
  done
  return 1
}

# Map a PCI BDF to a STABLE DRM card device path that survives card-number
# swaps across reboots. Prefers /dev/dri/by-path/pci-<BDF>-card (keyed by PCI
# address, stable); falls back to _bdf_to_drm_card (cardN) when by-path is
# absent. Used for the bind-now error hint (a persistent recommendation).
_bdf_to_drm_card_stable() {
  local _bdf="$1" _cand
  [[ -n "$_bdf" ]] || return 1
  for _cand in "/dev/dri/by-path/pci-$_bdf-card" "/dev/dri/by-path/pci-${_bdf#0000:}-card"; do
    if [[ -e "$_cand" ]]; then
      printf '%s\n' "$_cand"
      return 0
    fi
  done
  _bdf_to_drm_card "$_bdf"
}

# Returns 0 if the GPU at $1 is on amdgpu AND amdgpu has FINISHED probing --
# i.e. the DRM card node (/dev/dri/cardN) exists for this BDF. "Config space
# readable" (_pci_dev_alive) is NOT enough: amdgpu's probe is ASYNC, and the
# DRM card appears at the END of probe. Unbinding the card from amdgpu before
# the DRM card is up (mid-probe) can hang the kernel in D-state (observed on
# Navi 48 / RX 9070: the 15:36:49 --bind-now D-stated on the amdgpu->vfio-pci
# unbind 9s after a release rebind, because amdgpu had not finished probing).
# This is the readiness gate the release->start handoff needs.
_amdgpu_ready() {
  local _bdf="$1" _sys _drv
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -L "$_sys/driver" ]] || return 1
  _drv="$(basename "$(readlink "$_sys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
  [[ "$_drv" == "amdgpu" ]] || return 1
  _bdf_to_drm_card "$_bdf" >/dev/null 2>&1
}

# Bounded poll for amdgpu-readiness (DRM card up). $1 = BDF. Polls every 0.2s
# up to VFIO_AMDGPU_READY_TIMEOUT seconds (default 5s = 25 ticks). Returns 0 if
# amdgpu finished probing within the window, 1 otherwise. jlogs the outcome so
# the journal shows how long amdgpu took (or that it never finished -- a clear
# signal the card is stuck mid-probe). Never fatal: callers use `|| true` so a
# timeout proceeds with the bind rather than aborting the VM start.
_wait_amdgpu_ready() {
  local _bdf="$1" _max="${VFIO_AMDGPU_READY_TIMEOUT:-5}"
  [[ "$_max" =~ ^[0-9]+$ ]] || _max=5
  (( _max < 1 )) && _max=1
  local _att _ticks
  _ticks=$(( _max * 5 ))  # 0.2s ticks
  for _att in $(seq 1 "$_ticks"); do
    if _amdgpu_ready "$_bdf"; then
      jlog "$_bdf: amdgpu ready (DRM card up) after $((_att * 200))ms (poll $_att/$_ticks)"
      return 0
    fi
    sleep 0.2
  done
  jlog "$_bdf: WARN amdgpu NOT ready after ${_max}s (DRM card not up); proceeding anyway"
  return 1
}

# Returns 0 if a running Wayland compositor (kwin_wayland / sway / weston /
# wlroots / labwc / hyprland) currently has the KMS card node (/dev/dri/cardN)
# of the given BDF open — i.e. it is DRM master / scanning out to that GPU, so
# binding that GPU to vfio-pci would crash the compositor mid-frame
# (kwin_wayland SEGV in GLVertexBuffer::endOfFrame). On match, prints the
# compositor name to stdout (so the caller can name the correct render-device
# env var in its message). Returns 1 otherwise (safe to bind), printing nothing.
#
# NOTE: we check the KMS *card* node, NOT the render node. Mesa opens every
# renderDNN on the system for EGL/PRIME buffer sharing even when the compositor's
# display is on a different GPU, so a render-node check would false-positive on a
# healthy dual-GPU setup. The card node is the device the compositor actually
# holds DRM master on and scans out to — that is the real "display lives here"
# signal.
_wayland_compositor_uses_bdf() {
  local _bdf="$1"
  [[ -n "$_bdf" ]] || return 1
  # Map the BDF to its primary KMS card node (/dev/dri/cardN), if any.
  local _card=""
  _card="$(_bdf_to_drm_card "$_bdf" 2>/dev/null || true)"
  [[ -n "$_card" ]] || return 1
  # Find running Wayland compositors and check their open fds for that card node.
  local _comp _pid _fd _tgt
  for _comp in kwin_wayland sway weston wlroots labwc hyprland; do
    for _pid in $(pgrep -x "$_comp" 2>/dev/null || true); do
      for _fd in /proc/"$_pid"/fd/*; do
        [[ -L "$_fd" ]] || continue
        _tgt="$(readlink "$_fd" 2>/dev/null || true)"
        if [[ "$_tgt" == "$_card" ]]; then
          printf '%s\n' "$_comp"
          return 0
        fi
      done
    done
  done
  return 1
}

# Fail-safe: do not steal the active Boot VGA GPU during normal host boot
# unless the host GPU is explicitly configured as a different non-Boot-VGA
# adapter. Set VFIO_ALLOW_BOOT_VGA=1 to force binding unconditionally.
# Only applied on the boot action path; --bind-now (libvirt hook) explicitly
# skips this because the VM that has the GPU attached was just started.
boot_vga_guard() {
  if [[ -f "/sys/bus/pci/devices/$GUEST_GPU_BDF/boot_vga" ]]; then
    guest_boot_vga="$(cat "/sys/bus/pci/devices/$GUEST_GPU_BDF/boot_vga" 2>/dev/null || echo 0)"
    boot_vga_policy="${VFIO_BOOT_VGA_POLICY:-STRICT}"
    boot_vga_policy="${boot_vga_policy^^}"
    case "$boot_vga_policy" in
      AUTO|STRICT) ;;
      *) boot_vga_policy="STRICT" ;;
    esac
    if [[ "$guest_boot_vga" == "1" ]] && [[ "${VFIO_ALLOW_BOOT_VGA:-0}" != "1" ]]; then
      allow_boot_vga_bind=0
      allow_boot_vga_reason="none"
      host_assisted_boot_vga_bind=0
      if [[ -n "${HOST_GPU_BDF:-}" ]] && [[ "$HOST_GPU_BDF" != "$GUEST_GPU_BDF" ]] && [[ -f "/sys/bus/pci/devices/$HOST_GPU_BDF/boot_vga" ]]; then
        host_boot_vga="$(cat "/sys/bus/pci/devices/$HOST_GPU_BDF/boot_vga" 2>/dev/null || echo 1)"
        if [[ "$host_boot_vga" == "0" ]]; then
          host_assisted_boot_vga_bind=1
          if [[ "${VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU:-0}" == "1" ]]; then
            allow_boot_vga_bind=1
            allow_boot_vga_reason="explicit_opt_in"
          fi
          if [[ "$boot_vga_policy" == "AUTO" ]]; then
            allow_boot_vga_bind=1
            allow_boot_vga_reason="auto_detect"
          fi
        fi
      fi

      if [[ "$allow_boot_vga_bind" == "1" ]]; then
        say "WARN: $GUEST_GPU_BDF is Boot VGA, and HOST_GPU_BDF=${HOST_GPU_BDF:-} has boot_vga=0."
        if [[ "$allow_boot_vga_reason" == "auto_detect" ]]; then
          say "INFO: VFIO_BOOT_VGA_POLICY=AUTO auto-detected a safe host-assisted topology; proceeding with vfio bind."
          say "INFO: Set VFIO_BOOT_VGA_POLICY=STRICT to require explicit VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1."
        else
          say "WARN: VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1 is set; proceeding with host-assisted vfio bind."
          say "INFO: Set VFIO_ALLOW_BOOT_VGA=1 to force this behavior without host GPU checks."
        fi
      else
        say "WARN: $GUEST_GPU_BDF is Boot VGA; skipping vfio-pci bind to keep host graphics alive."
        if [[ "$host_assisted_boot_vga_bind" == "1" ]]; then
          say "INFO: HOST_GPU_BDF=${HOST_GPU_BDF:-} has boot_vga=0."
          say "INFO: Set VFIO_BOOT_VGA_POLICY=AUTO (recommended) or VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1 to allow host-assisted Boot VGA binding."
        else
          say "INFO: Set HOST_GPU_BDF to a different GPU (boot_vga=0) or set VFIO_ALLOW_BOOT_VGA=1 to force binding."
        fi
        exit 0
      fi
    fi
  fi
}

case "$ACTION" in
  release)
    jlog "=== --release start (REBIND_HOST=${VFIO_DYNAMIC_REBIND_HOST:-0}) ==="
    if [[ "${VFIO_DYNAMIC_REBIND_HOST:-0}" == "1" ]]; then
      # INSTRUMENTED + ROBUST: reprobe_to_host logs every step (so a segfault
      # is attributable) and verifies the host driver bound. Here we ALSO
      # re-check _pci_dev_alive after each reprobe and run remove+rescan
      # recovery if the card fell off (RX 9070 / RDNA4 reset bug on the
      # vfio-pci -> amdgpu handoff). Previously a dead card after reprobe was
      # silent until the next --bind-now wedged libvirt in D-state.
      _rh_dead=0
      for _rh_dev in "$GUEST_GPU_BDF" $(csv_to_array "${GUEST_AUDIO_BDFS_CSV:-}"); do
        [[ -n "$_rh_dev" ]] || continue
        reprobe_to_host "$_rh_dev"
        if ! _pci_dev_alive "$_rh_dev"; then
          jlog "$_rh_dev: DEAD after reprobe_to_host (RX 9070 reset bug); attempting remove+rescan recovery at release"
          say "WARN: $_rh_dev is dead after the vfio-pci -> host-driver rebind (RX 9070 / RDNA4 reset bug). Attempting remove+rescan recovery." >&2
          if _pci_dev_remove_rescan "$_rh_dev"; then
            jlog "$_rh_dev: recovered after remove+rescan at release (alive)"
            say "Recovered $_rh_dev after remove+rescan at release."
          else
            jlog "$_rh_dev: still dead after remove+rescan at release; next --bind-now will report it needs a host reboot"
            say "WARN: $_rh_dev is still dead after remove+rescan at release. The next VM start will report it needs a host reboot." >&2
            _rh_dead=1
          fi
        fi
      done
      say "Released guest devices back to host driver: $GUEST_GPU_BDF ${GUEST_AUDIO_BDFS_CSV:-}"
      if (( _rh_dead )); then
        jlog "=== --release done with DEAD device(s); next start may abort ==="
      else
        jlog "=== --release done (all devices alive on host driver) ==="
      fi
    else
      say "Dynamic release: leaving guest GPU on vfio-pci (VFIO_DYNAMIC_REBIND_HOST=0)."
      # Pin the parked guest BDFs in D0 (disable runtime PM) the moment the VM
      # stops, so they cannot slip into D3hot in the gap between VM stop and the
      # next park-keepalive pass. Reasserted every pass by the park-keepalive
      # monitor. d3cold_allowed=0 is re-pinned here too (was set at bind, but
      # reassert in case anything flipped it during the session).
      for _rb in "$GUEST_GPU_BDF" $(csv_to_array "${GUEST_AUDIO_BDFS_CSV:-}"); do
        [[ -n "$_rb" ]] || continue
        [[ -d "/sys/bus/pci/devices/$_rb" ]] || continue
        echo on >"/sys/bus/pci/devices/$_rb/power/control" 2>/dev/null || true
        echo 0 >"/sys/bus/pci/devices/$_rb/d3cold_allowed" 2>/dev/null || true
      done
    fi
    # Zombie-card recovery at release time: the RX 9070 / RDNA4 reset bug can
    # drop the guest GPU off the PCI bus on the D3cold exit that happens DURING
    # the VM stop. Catching the death NOW (immediately after stop) and attempting
    # a remove+rescan recovery may recover the card while it is in a fresher
    # state than after sitting dead until the next --bind-now. ONLY acts when the
    # card is actually dead — a healthy card is never reset (resetting a healthy
    # card can itself trigger the reset bug, and remove+rescan would let amdgpu
    # grab it back, breaking the parked-on-vfio-pci invariant). Non-fatal: even
    # if recovery fails here, the next --bind-now will catch it and report that a
    # host reboot is needed.
    if ! _pci_dev_alive "$GUEST_GPU_BDF"; then
      jlog "$GUEST_GPU_BDF: zombie detected at release time (config space unreadable); attempting immediate remove+rescan recovery"
      say "WARN: $GUEST_GPU_BDF is dead at VM stop time (RX 9070 / RDNA4 reset bug). Attempting immediate remove+rescan recovery." >&2
      if _pci_dev_remove_rescan "$GUEST_GPU_BDF"; then
        jlog "$GUEST_GPU_BDF: recovered at release time after remove+rescan (alive)"
        say "Recovered $GUEST_GPU_BDF after remove+rescan at release time."
      else
        jlog "$GUEST_GPU_BDF: still dead at release time after remove+rescan; next --bind-now will report it needs a host reboot"
        say "WARN: $GUEST_GPU_BDF is still dead after remove+rescan at release time. The next VM start will report it needs a host reboot." >&2
      fi
      # AMD driver status notification (R22): the card died during the VM
      # session. On RX 9070 / RDNA4 this happens when the AMD Windows driver
      # is NOT installed -- without it, Windows uses the Microsoft Basic
      # Display Adapter which leaves the GPU in an undefined state that
      # crashes the host PCIe bus ~25s into the session. If the driver status
      # is still "unknown" (no prior successful session), notify the user to
      # install the AMD driver. If the status is "likely_installed" (a prior
      # session survived), the driver IS installed and this death is from
      # another cause -- do NOT suggest the driver (no false positive).
      if _is_rx9070 "$GUEST_GPU_BDF"; then
        _drv_status="$(cat "$DRIVER_STATUS_FILE" 2>/dev/null || echo "unknown")"
        if [[ "$_drv_status" != "likely_installed" ]]; then
          jlog "$GUEST_GPU_BDF: card died during VM session and AMD driver status is unknown — notifying user to install the AMD Windows driver"
          say "WARN: The guest GPU died during the VM session. On RX 9070 / RDNA4 this is likely because the AMD Windows driver is NOT installed in the guest — the Microsoft Basic Display Adapter leaves the GPU in an undefined state that crashes the PCIe bus. Install the AMD driver (Adrenalin) inside the Windows VM to stabilize the card. The card needs a host reboot to come back on the bus." >&2
          _desktop_notify "VFIO: The guest GPU (RX 9070) died during the VM session. Install the AMD driver inside the Windows VM to stabilize the card. Host reboot needed to bring the card back."
        fi
      fi
    else
      # Card survived the full VM session — the AMD driver is likely installed
      # and properly initializing the GPU. Mark the status so future deaths
      # don't falsely suggest installing the driver (no false positive).
      if _is_rx9070 "$GUEST_GPU_BDF"; then
        _drv_status="$(cat "$DRIVER_STATUS_FILE" 2>/dev/null || echo "unknown")"
        if [[ "$_drv_status" != "likely_installed" ]]; then
          mkdir -p "$(dirname "$DRIVER_STATUS_FILE")" 2>/dev/null || true
          printf 'likely_installed\n' >"$DRIVER_STATUS_FILE" 2>/dev/null || true
          jlog "$GUEST_GPU_BDF: card survived full VM session — marking AMD driver status as likely_installed"
          say "Guest GPU survived the full VM session — the AMD Windows driver appears to be installed. Future card-death notifications will not suggest the driver."
          _desktop_notify "VFIO: The guest GPU survived the full VM session — the AMD Windows driver appears to be installed. Passthrough is working."
        fi
      fi
    fi
    # Record the VM-stop timestamp for the cooldown guard on the next --bind-now.
    # Rapid VM stop -> start can drop the RX 9070 / RDNA4 off the PCI bus via the
    # D3cold reset bug; the cooldown refuses a too-soon restart with an actionable
    # "wait N seconds" message instead of letting qemu hit a dead card.
    _cooldown_seconds="${VFIO_DYNAMIC_COOLDOWN_SECONDS:-10}"
    if [[ ! "$_cooldown_seconds" =~ ^[0-9]+$ ]]; then
      _cooldown_seconds="10"
    fi
    if (( _cooldown_seconds > 0 )); then
      mkdir -p "$(dirname "$COOLDOWN_TS_FILE")" 2>/dev/null || true
      date +%s >"$COOLDOWN_TS_FILE" 2>/dev/null || true
      jlog "VM stopped; cooldown ${_cooldown_seconds}s active -- wait before restarting to avoid the RX 9070 / RDNA4 reset bug (rapid stop/start can drop the card off the bus)"
      say "VM stopped. The guest GPU needs ~${_cooldown_seconds}s to settle out of D3cold; wait before restarting to avoid the reset bug (VFIO_DYNAMIC_COOLDOWN_SECONDS=${_cooldown_seconds})."
    fi
    exit 0
    ;;
  bind-now)
    # Readiness probe: rapid VM stop -> start can drop the RX 9070 / RDNA4 off
    # the PCI bus via the D3cold reset bug. Instead of a dumb fixed-time gate,
    # ACTIVELY probe whether the card is alive. If the VM was stopped less than
    # VFIO_DYNAMIC_COOLDOWN_SECONDS ago, poll the card's liveness (vendor sysfs +
    # live config space via _pci_dev_alive) until it is alive OR the cooldown
    # window expires. A card that recovered early proceeds immediately (no need
    # to wait the full window); a card that is still dead after the window fails
    # with an actionable "card needs a host reboot" message so libvirt aborts the
    # VM start cleanly. This is the PROACTIVE complement to the alive-check: it
    # gives the card time to recover from a rapid stop/start D3cold exit and only
    # fails if it does NOT recover. Keep the cooldown below VFIO_HOOK_BIND_TIMEOUT
    # (default 20) so the probe cannot hit the hook deadline.
    _cooldown_seconds="${VFIO_DYNAMIC_COOLDOWN_SECONDS:-10}"
    if [[ ! "$_cooldown_seconds" =~ ^[0-9]+$ ]]; then
      _cooldown_seconds="10"
    fi
    if (( _cooldown_seconds > 0 )) && [[ -f "$COOLDOWN_TS_FILE" ]]; then
      _last_stop="$(cat "$COOLDOWN_TS_FILE" 2>/dev/null || echo 0)"
      if [[ "$_last_stop" =~ ^[0-9]+$ ]]; then
        _now="$(date +%s)"
        _elapsed=$(( _now - _last_stop ))
        if (( _elapsed < _cooldown_seconds )); then
          jlog "$GUEST_GPU_BDF: --bind-now within cooldown window (${_elapsed}s < ${_cooldown_seconds}s); probing card readiness"
          while (( _elapsed < _cooldown_seconds )); do
            if _pci_dev_alive "$GUEST_GPU_BDF"; then
              jlog "$GUEST_GPU_BDF: card alive during cooldown probe (elapsed ${_elapsed}s); proceeding with bind"
              break
            fi
            sleep 1
            _now="$(date +%s)"
            _elapsed=$(( _now - _last_stop ))
          done
          if ! _pci_dev_alive "$GUEST_GPU_BDF"; then
            say "ERROR: VM stopped ${_elapsed}s ago and the guest GPU ($GUEST_GPU_BDF) is still not alive after the cooldown window (${_cooldown_seconds}s). Its config space is unreadable (RX 9070 / RDNA4 reset bug: Unknown PCI header type 127). The card needs a host reboot to come back on the bus. Aborting VM start." >&2
            jlog "$GUEST_GPU_BDF: FAILED cooldown readiness probe -- card still dead after ${_cooldown_seconds}s; needs host reboot"
            exit 1
          fi
        fi
      fi
    fi
    # Forced bind requested by the libvirt hook (the VM has the GPU attached).
    # Boot-VGA safety: if the guest GPU is Boot VGA (boot_vga=1), binding it to
    # vfio-pci at VM start would kill the host display mid-session in a
    # SINGLE-GPU topology. Three ways through:
    #   (a) host-assisted (dual-GPU, the normal case): a different HOST_GPU_BDF
    #       with boot_vga=0 is configured and the host display runs on it.
    #       Honored when VFIO_BOOT_VGA_POLICY=AUTO (default) OR
    #       VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU=1, mirroring the early-binding
    #       boot_vga_guard() so dynamic and early paths treat this topology the
    #       same way. The host display is on the other GPU, so no black screen.
    #   (b) explicit override: VFIO_DYNAMIC_ALLOW_BOOT_VGA=1 forces the bind
    #       unconditionally (advanced single-GPU/headless setups where losing the
    #       host display during the VM session is intentional).
    #   (c) otherwise refuse (exit 1) so libvirt aborts the VM start cleanly and
    #       the host display stays alive.
    if [[ -f "/sys/bus/pci/devices/$GUEST_GPU_BDF/boot_vga" ]]; then
      _bv="$(cat "/sys/bus/pci/devices/$GUEST_GPU_BDF/boot_vga" 2>/dev/null || echo 0)"
      if [[ "$_bv" == "1" && "${VFIO_DYNAMIC_ALLOW_BOOT_VGA:-0}" != "1" ]]; then
        _bn_allow=0
        _bn_reason=""
        if [[ -n "${HOST_GPU_BDF:-}" ]] && [[ "$HOST_GPU_BDF" != "$GUEST_GPU_BDF" ]] && [[ -f "/sys/bus/pci/devices/$HOST_GPU_BDF/boot_vga" ]]; then
          _hbv="$(cat "/sys/bus/pci/devices/$HOST_GPU_BDF/boot_vga" 2>/dev/null || echo 1)"
          if [[ "$_hbv" == "0" ]]; then
            _bpolicy="${VFIO_BOOT_VGA_POLICY:-STRICT}"
            _bpolicy="${_bpolicy^^}"
            case "$_bpolicy" in AUTO|STRICT) ;; *) _bpolicy="STRICT" ;; esac
            if [[ "$_bpolicy" == "AUTO" ]]; then
              _bn_allow=1
              _bn_reason="auto_detect"
            elif [[ "${VFIO_ALLOW_BOOT_VGA_IF_HOST_GPU:-0}" == "1" ]]; then
              _bn_allow=1
              _bn_reason="explicit_opt_in"
            fi
          fi
        fi
        if [[ "$_bn_allow" == "1" ]]; then
          # Wayland render-device safety: the host-assisted allow above only
          # checks that a second GPU with boot_vga=0 exists. But on KDE/Wayland
          # the compositor renders on the boot_vga=1 (guest) GPU by default, so
          # binding it would crash kwin_wayland mid-frame. If a Wayland
          # compositor currently has the guest GPU's render node open, refuse
          # with an actionable fix instead of letting the compositor segfault.
          # (VFIO_DYNAMIC_ALLOW_BOOT_VGA=1 bypasses this whole block.)
          if _comp="$(_wayland_compositor_uses_bdf "$GUEST_GPU_BDF")"; then
            _host_card=""
            if [[ -n "${HOST_GPU_BDF:-}" ]]; then
              _host_card="$(_bdf_to_drm_card_stable "$HOST_GPU_BDF" 2>/dev/null || true)"
            fi
            # Map the detected compositor to its render-device env var so the
            # fix message names the right knob (KWin vs wlroots-based).
            case "$_comp" in
              kwin_wayland)            _envvar="KWIN_DRM_DEVICES" ;;
              sway|wlroots|labwc|hyprland) _envvar="WLR_DRM_DEVICES" ;;
              weston)                   _envvar="WESTON_DRM_DEVICE" ;;
              *)                        _envvar="KWIN_DRM_DEVICES / WLR_DRM_DEVICES" ;;
            esac
            say "ERROR: $GUEST_GPU_BDF is Boot VGA and the active Wayland compositor ($_comp) is rendering on it; binding it to vfio-pci now would crash the host desktop (compositor SEGV mid-frame). Fix: pin $_comp to the host GPU — run 'sudo $SCRIPT_NAME --install-dynamic-binding' (writes $_envvar=${_host_card:-/dev/dri/cardN} to the session env), or set $_envvar=${_host_card:-/dev/dri/cardN} manually before starting the compositor, or set the host GPU as Primary Display in BIOS. Then log out and back in (or reboot) and start the VM. Aborting VM start." >&2
            jlog "$GUEST_GPU_BDF: refused --bind-now — $_comp is rendering on the guest (Boot VGA) GPU"
            exit 1
          fi
          jlog "$GUEST_GPU_BDF: Boot VGA but host-assisted (HOST_GPU_BDF=$HOST_GPU_BDF boot_vga=0, reason=$_bn_reason); allowing --bind-now"
          say "WARN: $GUEST_GPU_BDF is Boot VGA, but HOST_GPU_BDF=$HOST_GPU_BDF has boot_vga=0 (host display stays on the host GPU). Allowing --bind-now (reason=$_bn_reason)."
        else
          say "ERROR: $GUEST_GPU_BDF is Boot VGA; refusing --bind-now to keep host display alive. For dual-GPU: set HOST_GPU_BDF to a different GPU with boot_vga=0 and VFIO_BOOT_VGA_POLICY=AUTO. For single-GPU/headless: set VFIO_DYNAMIC_ALLOW_BOOT_VGA=1. Aborting VM start." >&2
          exit 1
        fi
    fi
    fi
    # amdgpu-readiness gate: if the guest GPU is currently on amdgpu (cold
    # start, OR shutdown->start with REBIND_HOST=1 where the release just
    # rebind it to amdgpu), wait for amdgpu to FINISH probing (DRM card node
    # up) BEFORE do_bind unbinds it. amdgpu's probe is async; unbinding
    # mid-probe can hang the kernel in D-state (observed on Navi 48: the
    # 15:36:49 --bind-now D-stated on the amdgpu->vfio-pci unbind 9s after a
    # release rebind, because amdgpu had not finished probing). Bounded by
    # VFIO_AMDGPU_READY_TIMEOUT (default 5s) so it cannot hit the hook
    # deadline. No-op if the card is not on amdgpu (e.g. parked on vfio-pci
    # with REBIND_HOST=0).
    if [[ -L "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver" ]]; then
      # NOTE: this runs at the top level of the bind-now) case branch, NOT
      # inside a function, so `local` cannot be used here (bash: "local: can
      # only be used in a function"). Use a plain prefixed var instead.
      _bn_drv="$(basename "$(readlink "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver" 2>/dev/null)" 2>/dev/null || echo "")"
      if [[ "$_bn_drv" == "amdgpu" ]]; then
        jlog "$GUEST_GPU_BDF: --bind-now: guest GPU on amdgpu; waiting for amdgpu-readiness (DRM card up) before bind"
        _wait_amdgpu_ready "$GUEST_GPU_BDF" || true
      fi
    fi
    do_bind
    say "vfio-pci binding complete (--bind-now): $GUEST_GPU_BDF ${GUEST_AUDIO_BDFS_CSV:-}"
    exit 0
    ;;
  boot)
    # Early-binding boot path: respect Boot-VGA safety skip, then bind.
    boot_vga_guard
    do_bind
    say "vfio-pci binding complete: $GUEST_GPU_BDF ${GUEST_AUDIO_BDFS_CSV:-}"
    ;;
esac
EOF
}

install_systemd_unit() {
  backup_file "$SYSTEMD_UNIT"

  write_file_atomic "$SYSTEMD_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=Bind selected GPU (and selected PCI functions) to vfio-pci for passthrough
DefaultDependencies=yes
After=systemd-modules-load.service
Before=display-manager.service
Before=libvirtd.service
Before=virtqemud.service
Before=multi-user.target

[Service]
Type=oneshot
ExecStart=$BIND_SCRIPT
ExecStartPost=/bin/sh -c 'if [ -x /usr/local/sbin/vfio-graphics-protocold.sh ]; then /usr/local/sbin/vfio-graphics-protocold.sh --once --prelogin || true; fi'
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF

  run systemctl daemon-reload
  run systemctl enable vfio-bind-selected-gpu.service
}
# Install a targeted SELinux policy module allowing virtqemud_t to execute
# the libvirt qemu hook and write the PCI sysfs entries the bind script touches
# (driver_override, rescan, unbind, bind, d3cold_allowed, power/control, reset,
# remove). On SELinux-enforcing distros (Fedora/RHEL) the default policy does
# NOT grant virtqemud_t execute_no_trans on virt_hook_t nor sysfs_t write
# access, so EVERY VM start/stop floods the audit log with thousands of AVC
# denials (observed: 9000+ denials per session on Fedora). This module is
# minimal and scoped to vfio only -- it does NOT use the firehose audit2allow
# output (which sweeps up unrelated service domains). Auto-detected: no-op on
# non-SELinux systems or when the policy tools (checkmodule/semodule) are
# missing. Idempotent: re-installing replaces the module in place.
install_selinux_virtqemud_policy() {
  # Only relevant when SELinux is enabled.
  if ! command -v selinuxenabled >/dev/null 2>&1 || ! selinuxenabled 2>/dev/null; then
    return 0
  fi
  local _mode
  _mode="$(getenforce 2>/dev/null || echo "")"
  if [[ "$_mode" != "Enforcing" && "$_mode" != "Permissive" ]]; then
    note "SELinux mode is '$_mode'; skipping virtqemud policy module."
    return 0
  fi
  # Need the policy build/install tools.
  if ! have_cmd checkmodule || ! have_cmd semodule_package || ! have_cmd semodule; then
    note "SELinux is enabled ($_mode) but checkmodule/semodule_package/semodule are not all installed;"
    note "skipping the virtqemud policy module. Install policycoreutils-python-utils / selinux-tools to get it."
    if have_cmd dnf; then
      note "  Fedora/RHEL: sudo dnf install policycoreutils-python-utils checkpolicy"
    elif have_cmd zypper; then
      note "  openSUSE: sudo zypper in selinux-tools checkpolicy"
    elif have_cmd apt-get; then
      note "  Debian/Ubuntu: sudo apt-get install policycoreutils-python-utils checkpolicy"
    fi
    return 0
  fi
  # Confirm virtqemud_t exists in the loaded policy (it does on Fedora/modular
  # libvirt; on classic libvirtd-only systems the type may be libvirtd_t and
  # this module is not needed / would not compile). Skip silently if absent.
  if command -v seinfo >/dev/null 2>&1; then
    if ! seinfo -t virtqemud_t 2>/dev/null | grep -q virtqemud_t; then
      note "SELinux virtqemud_t type not present in the loaded policy (classic libvirtd?); skipping virtqemud policy module."
      return 0
    fi
  fi

  say
  hdr "SELinux: install virtqemud VFIO hook policy (Fedora/RHEL)"
  note "SELinux is $_mode. Installing a targeted policy module so virtqemud can execute"
  note "the libvirt qemu hook and write the PCI sysfs entries the bind script uses,"
  note "instead of flooding the audit log with AVC denials on every VM start/stop."

  local _tmp _te _mod _pp
  _tmp="$(mktemp -d)"
  _te="$_tmp/vfio_virtqemud.te"
  _mod="$_tmp/vfio_virtqemud.mod"
  _pp="$_tmp/vfio_virtqemud.pp"

  write_file_atomic "$_te" 0644 "root:root" <<'EOF'
module vfio_virtqemud 1.0;

require {
    type virtqemud_t;
    type virt_hook_t;
    type sysfs_t;
    type kmod_exec_t;
    type modules_dep_t;
    class file { execute execute_no_trans map create write };
    class dir { add_name write };
}

# Allow virtqemud to execute the libvirt qemu hook script
# (/etc/libvirt/hooks/qemu is labeled virt_hook_t; the default policy does not
# grant virtqemud_t execute_no_trans on it, so every VM start/stop floods the
# audit log with denied execute_no_trans denials).
allow virtqemud_t virt_hook_t:file { execute execute_no_trans };

# Allow the hook (running as virtqemud_t) to exec modprobe (kmod)
# so the bind script can modprobe vfio vfio-pci vfio_iommu_type1.
allow virtqemud_t kmod_exec_t:file { execute execute_no_trans map };

# Allow modprobe to mmap modules.dep.
allow virtqemud_t modules_dep_t:file map;

# Allow the bind script (invoked by the hook as virtqemud_t) to write sysfs
# entries: driver_override, rescan, unbind, bind, d3cold_allowed,
# power/control, reset, remove. Without this, every PCI bind/unbind sysfs
# write floods the audit log with denied add_name/create denials.
allow virtqemud_t sysfs_t:dir { add_name write };
allow virtqemud_t sysfs_t:file { create write };
EOF

  if ! run checkmodule -M -m -o "$_mod" "$_te" 2>/dev/null; then
    note "WARN: checkmodule failed to compile the virtqemud policy .te; skipping SELinux module."
    rm -rf "$_tmp" 2>/dev/null || true
    return 0
  fi
  if ! run semodule_package -m "$_mod" -o "$_pp" 2>/dev/null; then
    note "WARN: semodule_package failed to package the virtqemud policy; skipping SELinux module."
    rm -rf "$_tmp" 2>/dev/null || true
    return 0
  fi
  if ! run semodule -i "$_pp" 2>/dev/null; then
    note "WARN: semodule -i failed to install the virtqemud policy; skipping SELinux module."
    rm -rf "$_tmp" 2>/dev/null || true
    return 0
  fi
  rm -rf "$_tmp" 2>/dev/null || true
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Installed SELinux policy module: vfio_virtqemud (virtqemud_t can exec the qemu hook + write PCI sysfs)"
  else
    say "  ✔ Installed SELinux policy module: vfio_virtqemud"
  fi
  note "  Verify: sudo semodule -l | grep vfio_virtqemud"
  note "  If virtqemud_t was put in permissive mode to work around the denials, you can"
  note "  now return it to enforcing: sudo semanage permissive -d virtqemud_t"
}

install_libvirt_hook() {
  # Installs a generic libvirt qemu hook for dynamic GPU binding.
  # No hardcoded VM/domain names: the hook reads the VM XML from stdin and only
  # switches the guest GPU to vfio-pci when that VM actually has the GPU attached.
  if (( ! DRY_RUN )); then
    mkdir -p "$LIBVIRT_HOOK_DIR"
  fi

  # Preserve a pre-existing user-managed qemu hook so --reset can restore it.
  # Skip the backup if the existing entry is already our managed file.
  if [[ -f "$LIBVIRT_HOOK_ENTRY" && ! -f "$LIBVIRT_HOOK_ENTRY.bak.$RUN_TS" ]]; then
    if ! grep -Fq "# Managed by vfio.sh" "$LIBVIRT_HOOK_ENTRY" 2>/dev/null; then
      run cp -a "$LIBVIRT_HOOK_ENTRY" "$LIBVIRT_HOOK_ENTRY.bak.$RUN_TS"
      note "Backed up existing libvirt qemu hook to $LIBVIRT_HOOK_ENTRY.bak.$RUN_TS"
    fi
  fi

  backup_file "$LIBVIRT_HOOK_SCRIPT"

  write_file_atomic "$LIBVIRT_HOOK_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Managed by vfio.sh — libvirt qemu hook for dynamic GPU binding.
# Invoked by libvirt as: /etc/libvirt/hooks/qemu <domain> <phase> <...>
# with the VM domain XML piped on stdin (for most phases).

CONF_FILE="/etc/vfio-gpu-passthrough.conf"
BIND_SCRIPT="/usr/local/sbin/vfio-bind-selected-gpu.sh"

say() { printf '%s\n' "$*"; }

# Best-effort append-only hook log so dynamic-binding VM start/stop actions are
# traceable without digging through libvirt logs. Failures to write are silent.
HOOK_LOG="/var/log/vfio-libvirt-hook.log"
hook_log() {
  local _msg="$1"
  printf '%s domain=%s phase=%s %s\n' "$(date -Is 2>/dev/null || date)" "${DOMAIN:-}" "${PHASE:-}" "$_msg" >>"$HOOK_LOG" 2>/dev/null || true
}

[[ -f "$CONF_FILE" ]] || exit 0
# shellcheck disable=SC1090
. "$CONF_FILE"

[[ -x "$BIND_SCRIPT" ]] || { say "vfio-libvirt-hook: $BIND_SCRIPT missing or not executable; skipping." >&2; exit 0; }

DOMAIN="${1:-}"
PHASE="${2:-}"

# Comma-separated set of configured guest BDFs (GPU + audio) we care about.
GUEST_BDFS="$GUEST_GPU_BDF"
if [[ -n "${GUEST_AUDIO_BDFS_CSV:-}" ]]; then
  GUEST_BDFS="$GUEST_BDFS,$GUEST_AUDIO_BDFS_CSV"
fi

# Parse libvirt domain XML from stdin and print one BDF per line for every PCI
# <hostdev> address. The "." in the regexes matches either single or double
# quotes around attribute values (libvirt uses ' by default, some tools use ").
extract_hostdev_bdfs() {
  awk '
    /<hostdev/ { in_hostdev=1; is_pci=0 }
    in_hostdev && /type=.pci./ { is_pci=1 }
    in_hostdev && is_pci && /<address/ {
      line=$0; dom=""; bus=""; slot=""; fn=""
      if (match(line, /domain=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^domain=./, "", s); sub(/^0x/, "", s); dom=s
      }
      if (match(line, /bus=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^bus=./, "", s); sub(/^0x/, "", s); bus=s
      }
      if (match(line, /slot=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^slot=./, "", s); sub(/^0x/, "", s); slot=s
      }
      if (match(line, /function=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^function=./, "", s); sub(/^0x/, "", s); fn=s
      }
      if (dom != "" && bus != "" && slot != "" && fn != "") {
        while (length(dom) < 4) dom = "0" dom
        while (length(bus) < 2) bus = "0" bus
        while (length(slot) < 2) slot = "0" slot
        printf "%s:%s:%s.%s\n", dom, bus, slot, fn
      }
    }
    /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
  '
}

# Return 0 if any configured guest BDF appears in the VM's PCI hostdev list.
vm_uses_guest_gpu() {
  local xml_bdfs b
  xml_bdfs="$(extract_hostdev_bdfs)"
  [[ -n "$xml_bdfs" ]] || return 1
  local IFS=','
  for b in $GUEST_BDFS; do
    [[ -n "$b" ]] || continue
    # Case-insensitive match: libvirt XML and lspci emit lowercase hex, but a
    # hand-edited conf may store uppercase BDFs. -F (fixed) + -i keeps it exact
    # yet case-insensitive so a case mismatch never silently skips the bind.
    if grep -Fixq "$b" <<<"$xml_bdfs"; then
      return 0
    fi
  done
  return 1
}

# Return 0 if the configured guest GPU is currently bound to vfio-pci.
guest_gpu_on_vfio() {
  [[ -L "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver" ]] || return 1
  local drv
  drv="$(basename "$(readlink "/sys/bus/pci/devices/$GUEST_GPU_BDF/driver")" 2>/dev/null || echo "")"
  [[ "$drv" == "vfio-pci" ]]
}

# Run --bind-now under a bounded timeout so a hung sysfs write cannot hang the
# libvirt prepare phase indefinitely. Default 20s leaves margin under libvirt's
# ~30s hook timeout; override with VFIO_HOOK_BIND_TIMEOUT. Falls back to a plain
# call if `timeout` (coreutils) is unavailable. `timeout` returns 124 on timeout,
# which the caller logs and propagates as a VM-start abort.
_bind_now() {
  local _to="${VFIO_HOOK_BIND_TIMEOUT:-20}"
  if command -v timeout >/dev/null 2>&1; then
    timeout "$_to" "$BIND_SCRIPT" --bind-now
  else
    "$BIND_SCRIPT" --bind-now
  fi
}

# Run --release under a bounded timeout for the same reason as --bind-now: a hung
# re-probe (/sys/bus/pci/drivers_probe) must not hang the libvirt stopped/release
# phase. Default 20s; override with VFIO_HOOK_RELEASE_TIMEOUT. Falls back to a
# plain call if `timeout` is unavailable.
_release() {
  local _to="${VFIO_HOOK_RELEASE_TIMEOUT:-20}"
  if command -v timeout >/dev/null 2>&1; then
    timeout "$_to" "$BIND_SCRIPT" --release
  else
    "$BIND_SCRIPT" --release
  fi
}

case "$PHASE" in
  prepare)
    # VM is about to start. Only bind if this VM has the guest GPU attached.
    # A non-zero exit from --bind-now is INTENTIONAL and will abort the VM start
    # cleanly (libvirt treats a non-zero qemu hook exit as a fatal error), so a
    # broken/mid-reset device does not get attached to the VM.
    #
    # LIVE-ATTACH MODE (VFIO_DYNAMIC_LIVE_ATTACH=1): the VM XML has the GPU
    # hostdev REMOVED (by --install-live-attach), so vm_uses_guest_gpu will NOT
    # find it. Instead, check if this domain is in the live-attach VM list. If
    # so, do NOT bind the GPU now — launch the live-attach helper in the
    # background, which sleeps VFIO_DYNAMIC_LIVE_ATTACH_DELAY seconds, then
    # binds the GPU to vfio-pci and hot-attaches it to the running VM via
    # `virsh attach-device --live`. This sidesteps the parked-restart death.
    if [[ "${VFIO_DYNAMIC_LIVE_ATTACH:-0}" == "1" ]] && [[ -f "/var/lib/vfio-dynamic/live-attach-vms" ]]; then
      if grep -Fixq "$DOMAIN" /var/lib/vfio-dynamic/live-attach-vms 2>/dev/null; then
        _la_delay="${VFIO_DYNAMIC_LIVE_ATTACH_DELAY:-30}"
        say "vfio-libvirt-hook: VM '$DOMAIN' is in live-attach list; launching background helper (delay=${_la_delay}s)."
        hook_log "action=live-attach-launch domain=$DOMAIN delay=${_la_delay}s"
        # Launch the helper FULLY DETACHED so it does NOT hold this hook's
        # stdout/stderr pipe open. libvirt waits for the hook's stdout/stderr
        # pipe to reach EOF before it starts qemu; a plain `&` child inherits
        # those fds, keeping the pipe open, so libvirt blocks until the helper
        # exits (~60-90s) — and the helper's `virsh attach-device --live` blocks
        # waiting for the VM to be running. That is a DEADLOCK: the VM cannot
        # start until the helper exits, but the helper cannot attach until the
        # VM is running (observed: vnet0 only came up 92s after VM start, the
        # instant the helper timed out and closed the pipe). setsid puts the
        # helper in its own session (survives hook exit, no SIGHUP),
        # </dev/null breaks stdin, >>log 2>&1 moves stdout/stderr OFF the
        # libvirt pipe so the pipe closes immediately and qemu starts at once.
        # The helper then polls guest-ping against the now-running VM, binds,
        # and hot-attaches.
        setsid /usr/local/sbin/vfio-live-attach.sh "$DOMAIN" "$_la_delay" \
          </dev/null >>/var/log/vfio-live-attach.log 2>&1 &
        : # let libvirt proceed — VM starts without the GPU.
      elif vm_uses_guest_gpu; then
        say "vfio-libvirt-hook: VM '$DOMAIN' has guest GPU attached; binding to vfio-pci."
        hook_log "action=bind-now gpu=$GUEST_GPU_BDF"
        if _bind_now; then
          hook_log "action=bind-now-done rc=0"
        else
          _rc=$?
          hook_log "action=bind-now-failed rc=$_rc"
          exit "$_rc"
        fi
      else
        hook_log "action=skip-not-attached"
      fi
    elif vm_uses_guest_gpu; then
      say "vfio-libvirt-hook: VM '$DOMAIN' has guest GPU attached; binding to vfio-pci."
      hook_log "action=bind-now gpu=$GUEST_GPU_BDF"
      # Run under `if` so set -e does not kill the hook before we can log the
      # failure. We still exit non-zero to abort the VM start (see comment above).
      if _bind_now; then
        hook_log "action=bind-now-done rc=0"
      else
        _rc=$?
        hook_log "action=bind-now-failed rc=$_rc"
        exit "$_rc"
      fi
    else
      hook_log "action=skip-not-attached"
      : # unrelated VM; let libvirt proceed untouched.
    fi
    ;;
  stopped|release)
    # VM stopped. If the guest GPU is currently on vfio-pci (we bound it), release
    # it back to the host driver per VFIO_DYNAMIC_REBIND_HOST. No-op otherwise.
    if guest_gpu_on_vfio; then
      say "vfio-libvirt-hook: VM '$DOMAIN' stopped; releasing guest GPU."
      hook_log "action=release gpu=$GUEST_GPU_BDF rebind=${VFIO_DYNAMIC_REBIND_HOST:-0}"
      _release
    else
      hook_log "action=stopped-noop gpu-not-on-vfio"
    fi
    ;;
  *)
    : # ignore start/started/reconnect/etc.
    ;;
esac

exit 0
EOF

  write_file_atomic "$LIBVIRT_HOOK_ENTRY" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
# Managed by vfio.sh — do not edit; this file is regenerated on reinstall.
# Generic libvirt qemu hook entry point (no hardcoded VM names).
exec /usr/local/sbin/vfio-libvirt-hook.sh "$@"
EOF

  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Installed libvirt qemu hook: $(_link "$LIBVIRT_HOOK_ENTRY")"
    say "  ${C_GREEN}✔${C_RESET} Installed libvirt hook script: $(_link "$LIBVIRT_HOOK_SCRIPT")"
  else
    say "  ✔ Installed libvirt qemu hook: $LIBVIRT_HOOK_ENTRY"
    say "  ✔ Installed libvirt hook script: $LIBVIRT_HOOK_SCRIPT"
  fi
  note "Dynamic binding switches the guest GPU to vfio-pci only when a VM that has it attached is started."

  # SELinux: on Fedora/RHEL (SELinux Enforcing), virtqemud_t cannot execute the
  # qemu hook nor write the PCI sysfs entries the bind script uses, so every VM
  # start/stop floods the audit log with AVC denials. Install a targeted policy
  # module to allow exactly that. Auto-detected; no-op on non-SELinux systems.
  install_selinux_virtqemud_policy
}

# Install the live-attach helper script: a background script launched by the
# libvirt hook on VM prepare (when VFIO_DYNAMIC_LIVE_ATTACH=1). It sleeps for a
# configurable delay (so Windows boots and loads the AMD driver), then binds
# the GPU to vfio-pci (via the bind script --bind-now) and hot-attaches it to
# the running VM via `virsh attach-device --live`.
install_live_attach_helper() {
  backup_file "$LIVE_ATTACH_HELPER"
  write_file_atomic "$LIVE_ATTACH_HELPER" 0755 "root:root" <<'HELPEREOF'
#!/usr/bin/env bash
set -euo pipefail

# Managed by vfio.sh — live-attach helper for hotplug GPU binding.
# Launched in the background by the libvirt qemu hook on VM prepare when
# VFIO_DYNAMIC_LIVE_ATTACH=1. Sleeps for the configured delay (so Windows
# boots and the AMD driver loads), then binds the GPU to vfio-pci and
# hot-attaches it to the running VM.
# Usage: vfio-live-attach.sh <domain> <delay_seconds>
# Removed by: sudo vfio.sh --reset  (or sudo vfio.sh --install-early-binding)

DOMAIN="${1:-}"
DELAY="${2:-30}"
CONF_FILE="/etc/vfio-gpu-passthrough.conf"
BIND_SCRIPT="/usr/local/sbin/vfio-bind-selected-gpu.sh"
GPU_XML="/var/lib/vfio-dynamic/live-attach-gpu.xml"
AUDIO_XML="/var/lib/vfio-dynamic/live-attach-audio.xml"

jlog() { command -v logger >/dev/null 2>&1 && logger -t vfio-live-attach -- "$*" 2>/dev/null || true; }

# Best-effort desktop notification (never fatal). This helper runs as root under
# the libvirt hook (setsid-detached), so to reach the desktop user it broadcasts
# to every active session under /run/user/<uid> via runuser + notify-send, the
# same pattern the park-keepalive monitor uses. Used to tell the operator the
# GPU hot-plug is ready to use (or failed) without watching the journal.
_notify_desktop() {
  local _title="$1" _body="$2" _urg="${3:-normal}" _rt _uid _user
  command -v notify-send >/dev/null 2>&1 || return 0
  command -v runuser >/dev/null 2>&1 || return 0
  for _rt in /run/user/*; do
    [[ -d "$_rt" ]] || continue
    _uid="$(basename "$_rt")"
    [[ "$_uid" =~ ^[0-9]+$ ]] || continue
    _user="$(getent passwd "$_uid" 2>/dev/null | cut -d: -f1)"
    [[ -n "$_user" ]] || continue
    runuser -u "$_user" -- env XDG_RUNTIME_DIR="$_rt" DBUS_SESSION_BUS_ADDRESS="unix:path=$_rt/bus" \
      notify-send -u "$_urg" "$_title" "$_body" >/dev/null 2>&1 || true
  done
  return 0
}

[[ -n "$DOMAIN" ]] || { jlog "live-attach: missing domain argument"; exit 1; }
[[ -f "$CONF_FILE" ]] || { jlog "live-attach: missing $CONF_FILE"; exit 0; }
# shellcheck disable=SC1090
. "$CONF_FILE"
[[ -x "$BIND_SCRIPT" ]] || { jlog "live-attach: $BIND_SCRIPT missing"; exit 0; }

# Wait for Windows userspace to be ready before binding + hot-attaching the GPU.
# Smart path: poll the qemu guest agent (guest-ping) — when it responds, Windows
# userspace is up and the AMD driver has loaded, so bind + attach IMMEDIATELY
# instead of waiting the full fixed delay (often ~15s vs the full 30s). Fallback:
# if the agent never responds within DELAY seconds (agent not installed in
# Windows yet, or no channel), bind + attach after the full delay — same
# behavior as before. install_live_attach auto-injects the guest-agent channel,
# but the virtio-win guest agent must still be installed inside Windows (via the
# virtio-win guest-tools ISO) for guest-ping to respond.
# IMPORTANT: use WALL-CLOCK elapsed time (date +%s), not a loop counter — each
# iteration takes up to 8s (5s virsh timeout + 3s sleep), so a counter that
# increments by 3 made a 30s ceiling take ~80s real time (observed in the journal:
# 22:02:34 -> 22:03:54). Wall-clock makes DELAY mean what it says.
jlog "live-attach: waiting for Windows readiness (guest-ping, up to ${DELAY}s) for domain '$DOMAIN'"
_ready=0
_start="$(date +%s)"
while :; do
  _now="$(date +%s)"
  _elapsed=$((_now - _start))
  (( _elapsed < 10#$DELAY )) || break
  if timeout 5 virsh -c qemu:///system qemu-agent-command "$DOMAIN" '{"execute":"guest-ping"}' >/dev/null 2>&1; then
    _ready=1
    jlog "live-attach: guest agent responded after ${_elapsed}s — Windows is up, binding GPU"
    break
  fi
  sleep 3
done
if (( ! _ready )); then
  jlog "live-attach: guest agent did not respond within ${DELAY}s — proceeding with bind (install the virtio-win guest agent inside Windows for a faster handoff)"
fi

# Step 1: bind the GPU to vfio-pci (same as the normal prepare hook does).
# Capture the full output so a failure surfaces the REAL cause in the journal
# (a swallowed stderr left us blind to a bind-script bug for an entire session).
jlog "live-attach: binding GPU $GUEST_GPU_BDF to vfio-pci"
# Capture the bind script real exit code BEFORE the negation, so the FAILED
# message reports the actual exit code (not the negated status, which is
# always 0 inside this branch — the old "rc=0" was meaningless).
# IMPORTANT: pre-initialize _bind_rc=0. On a SUCCESSFUL bind the `||` branch
# never runs, so _bind_rc would be unset — and with `set -u` the `(( ))` on
# the next line then kills the helper SILENTLY before it ever reaches the
# attach step (the swap never initiates). Pre-setting it to 0 fixes that.
_bind_rc=0
_bind_out="$("$BIND_SCRIPT" --bind-now 2>&1)" || _bind_rc=$?
if (( _bind_rc != 0 )); then
  _rc="$_bind_rc"
  jlog "live-attach: FAILED to bind GPU (rc=$_rc) — aborting attach"
  printf '%s\n' "$_bind_out" | while IFS= read -r _line; do
    [[ -n "$_line" ]] && jlog "live-attach: bind: $_line"
  done
  _notify_desktop "GPU hot-plug failed" "Failed to bind the GPU to vfio-pci for VM '$DOMAIN' (rc=$_rc). Check: journalctl -t vfio-live-attach" critical
  exit 1
fi
jlog "live-attach: GPU bound to vfio-pci, proceeding to hot-attach"

# Step 1b: verify every guest audio function is on vfio-pci BEFORE the GPU
# hot-attach. qemu's attach-time bus reset on the GPU requires ALL devices in
# the GPU's IOMMU group to be owned by vfio-pci — if the audio sibling is still
# on snd_hda_intel (e.g. a fresh boot where the boot unit only pinned D0 but
# did not bind vfio-pci, or GUEST_AUDIO_BDFS_CSV was added later), qemu surfaces
# "vfio: Cannot reset device <gpu>, depends on group <N> which is not owned"
# and the GPU is attached in an uninitialized state (contributes to the ~25s
# session death + black screen). do_bind (called by --bind-now above) DOES bind
# the audio, but this is a belt-and-suspenders check: if any audio BDF is NOT
# on vfio-pci after --bind-now returns, bind it explicitly here so the IOMMU
# group is fully owned before the hot-attach fires.
_audio_ok=1
for _abdf in $(printf '%s\n' "${GUEST_AUDIO_BDFS_CSV:-}" | tr ',' '\n'); do
  [[ -n "$_abdf" ]] || continue
  _asys="/sys/bus/pci/devices/$_abdf"
  if [[ ! -d "$_asys" ]]; then
    jlog "live-attach: WARN audio $_abdf not on the PCI bus — skipping (may be off-bus from a prior death); group ownership may fail"
    continue
  fi
  _adrv=""
  if [[ -L "$_asys/driver" ]]; then
    _adrv="$(basename "$(readlink "$_asys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
  fi
  if [[ "$_adrv" != "vfio-pci" ]]; then
    jlog "live-attach: audio $_abdf is on '$_adrv' (not vfio-pci) after --bind-now; binding it explicitly so the IOMMU group is owned before the GPU hot-attach"
    # Unbind from the current driver (snd_hda_intel etc) if any.
    if [[ -n "$_adrv" && -w "/sys/bus/pci/drivers/$_adrv/unbind" ]]; then
      echo "$_abdf" >"/sys/bus/pci/drivers/$_adrv/unbind" 2>/dev/null || true
      sleep 0.2
    fi
    echo 0 >"$_asys/d3cold_allowed" 2>/dev/null || true
    echo on >"$_asys/power/control" 2>/dev/null || true
    echo vfio-pci >"$_asys/driver_override" 2>/dev/null || true
    echo "$_abdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
    sleep 0.2
    _adrv=""
    if [[ -L "$_asys/driver" ]]; then
      _adrv="$(basename "$(readlink "$_asys/driver" 2>/dev/null)" 2>/dev/null || echo "")"
    fi
    if [[ "$_adrv" == "vfio-pci" ]]; then
      jlog "live-attach: audio $_abdf now on vfio-pci (IOMMU group owned)"
    else
      jlog "live-attach: WARN audio $_abdf FAILED to bind to vfio-pci (still on '$_adrv'); qemu's GPU reset may fail with 'depends on group not owned'"
      _audio_ok=0
    fi
  fi
done

# Step 2: hot-attach the GPU to the running VM.
# Use [[ -s ]] (non-empty), not [[ -f ]] — an empty/stale XML file makes virsh
# attach-device hang on empty input and block libvirt's VM lock (observed: a
# stuck attach-device held the lock for minutes so every other virsh call,
# including VM start, queued behind it). Wrap in `timeout` (default 60s, tunable
# via VFIO_DYNAMIC_LIVE_ATTACH_TIMEOUT) so a hung attach (guest PCI address
# conflict, vfio reset hang, etc.) can NEVER block libvirt indefinitely: on
# timeout we log and exit non-zero instead of holding the lock. 60s (not 30s)
# because the RX 9070's vfio attach reset + Gen5 link retrain can take >30s — a
# 30s timeout fired on a still-progressing attach (the card was alive afterward,
# so the attach was slow, not dead). If it still times out at 60s the attach
# reset is genuinely stuck (not just slow) and live-attach won't work for this
# card — revert with --install-dynamic-binding.
_la_timeout="${VFIO_DYNAMIC_LIVE_ATTACH_TIMEOUT:-60}"
if ! [[ "$_la_timeout" =~ ^[0-9]+$ ]] || (( 10#$_la_timeout < 10 )); then
  _la_timeout=60
fi
if [[ -s "$GPU_XML" ]]; then
  jlog "live-attach: attaching GPU to domain '$DOMAIN' via virsh attach-device --live (timeout ${_la_timeout}s)"
  # Best-effort detach FIRST: a rapid stop/start can leave a stale vfio lock
  # (the kernel still thinks the device is owned by the previous qemu process),
  # which makes attach-device fail with "device used by QEMU / driver". A
  # detach-device --live clears that stale lock (no-op if the device isn't
  # attached — the || true swallows the error). Then attach cleanly.
  timeout "$_la_timeout" virsh -c qemu:///system detach-device "$DOMAIN" "$GPU_XML" --live >/dev/null 2>&1 || true
  if timeout "$_la_timeout" virsh -c qemu:///system attach-device "$DOMAIN" "$GPU_XML" --live 2>&1; then
    jlog "live-attach: GPU attached successfully to '$DOMAIN'"
    _notify_desktop "GPU hot-plug ready" "The GPU has been hot-attached to VM '$DOMAIN' — ready to use." normal
  else
    _rc=$?
    if (( _rc == 124 )); then
      jlog "live-attach: FAILED to attach GPU — virsh attach-device timed out after ${_la_timeout}s (vfio reset hang or guest PCI conflict). If this repeats, the RX 9070 attach reset is genuinely stuck; revert with --install-dynamic-binding."
    else
      jlog "live-attach: FAILED to attach GPU to '$DOMAIN' (rc=$_rc)"
    fi
    _notify_desktop "GPU hot-plug failed" "Failed to hot-attach the GPU to VM '$DOMAIN' (rc=$_rc). Check: journalctl -t vfio-live-attach" critical
    exit 1
  fi
else
  jlog "live-attach: FAILED — $GPU_XML missing or empty; the GPU device XML was not saved at install time. Re-run 'sudo vfio.sh --install-live-attach' with the VM shut off."
  _notify_desktop "GPU hot-plug failed" "The GPU device XML is missing for VM '$DOMAIN'. Re-run: sudo vfio.sh --install-live-attach (VM shut off)" critical
  exit 1
fi

# Step 3: hot-attach the audio function (if configured and XML is non-empty).
if [[ -s "$AUDIO_XML" ]]; then
  jlog "live-attach: attaching audio to domain '$DOMAIN'"
  timeout "$_la_timeout" virsh -c qemu:///system detach-device "$DOMAIN" "$AUDIO_XML" --live >/dev/null 2>&1 || true
  timeout "$_la_timeout" virsh -c qemu:///system attach-device "$DOMAIN" "$AUDIO_XML" --live 2>&1 || \
    jlog "live-attach: WARN audio attach failed or timed out (non-fatal)"
fi

jlog "live-attach: complete for domain '$DOMAIN'"
HELPEREOF
  say "Installed live-attach helper: $LIVE_ATTACH_HELPER"
}

# Install the live-attach (hotplug GPU) workflow:
# 1. Extract the GPU + audio hostdev blocks from each shut-off guest-GPU VM's
#    XML into standalone device XML files.
# 2. Remove the GPU + audio hostdev blocks from the VM's persistent XML (so
#    libvirt starts the VM WITHOUT the GPU).
# 3. Write the VM name(s) to the live-attach VM list.
# 4. Install the live-attach helper script.
# 5. Flip VFIO_DYNAMIC_LIVE_ATTACH=1 in the conf.
# 6. Regenerate the bind script (deploys the updated hook with live-attach logic).
# Prerequisites: dynamic binding must already be installed (conf + hook exist).
# The AMD Windows driver MUST be installed first (the card dies without it).
install_live_attach() {
  readable_file "$CONF_FILE" || die "Missing $CONF_FILE. Run the full installer or --install-dynamic-binding first."
  # shellcheck disable=SC1090
  . "$CONF_FILE"
  [[ -n "${GUEST_GPU_BDF:-}" ]] || die "No GUEST_GPU_BDF in $CONF_FILE."
  have_cmd virsh || die "virsh not available."
  have_cmd python3 || die "python3 not available (needed to extract hostdev XML)."

  say
  hdr "Live-attach (hotplug GPU) setup"
  note "This sets up the live-attach workflow: the VM starts WITHOUT the GPU, Windows"
  note "boots on a virtual display, and after a delay the GPU is hot-attached to the"
  note "running VM. This sidesteps the parked-restart card death on RX 9070 / RDNA4."
  note ""
  note "The VM XML is also auto-injected with a qemu guest-agent channel, and the"
  note "helper polls guest-ping so the GPU hot-attaches the MOMENT Windows is up"
  note "(not after a blind fixed wait). For the smart early-bind path, install the"
  note "virtio-win guest agent inside Windows (via the virtio-win guest-tools ISO)."
  note ""
  note "PREREQUISITE: the AMD Windows driver MUST already be installed inside the VM."
  note "Without the driver, the card dies ~25s into the session regardless of method."
  note ""
  note "The VM XML will be modified to REMOVE the GPU hostdev (so libvirt starts"
  note "without it). A full backup of the original XML (with the GPU) is saved per VM."
  note "To revert, run:"
  note "  sudo $SCRIPT_NAME --install-dynamic-binding"
  note "  (restores normal binding AND re-attaches the GPU to the VM XML from the backup)"
  say

  local _delay_default="${VFIO_DYNAMIC_LIVE_ATTACH_DELAY:-30}"
  note "Default attach delay: ${_delay_default}s (time for Windows to boot + load the AMD driver)."
  note "Increase if Windows boots slowly; decrease if it boots fast."
  say

  local _la_dir="/var/lib/vfio-dynamic"
  if (( ! DRY_RUN )); then
    mkdir -p "$_la_dir"
  fi

  # Find shut-off VMs with the guest GPU and set up live-attach for each.
  local _dom _xml _bdfs _state _found=0
  local _gpu_bdf="$GUEST_GPU_BDF"
  local _audio_csv="${GUEST_AUDIO_BDFS_CSV:-}"

  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Parse PCI hostdev BDFs (same awk parser as the hook).
    _bdfs="$(printf '%s' "$_xml" | awk '
      /<hostdev/ { in_hostdev=1; is_pci=0 }
      in_hostdev && /type=.pci./ { is_pci=1 }
      in_hostdev && is_pci && /<address/ {
        line=$0; dom=""; bus=""; slot=""; fn=""
        if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
        if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
        if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
        if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
        if (dom != "" && bus != "" && slot != "" && fn != "") {
          while (length(dom) < 4) dom = "0" dom
          while (length(bus) < 2) bus = "0" bus
          while (length(slot) < 2) slot = "0" slot
          printf "%s:%s:%s.%s\n", dom, bus, slot, fn
        }
      }
      /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
    ')"
    if ! grep -Fixq "$_gpu_bdf" <<<"$_bdfs" 2>/dev/null; then
      continue
    fi
    # Check VM state — can only define shut-off VMs.
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping. Shut it off and re-run."
      continue
    fi
    _found=1
    say "Setting up live-attach for VM '$_dom'..."

    # Use python to extract the GPU + audio hostdev blocks into standalone XML
    # and remove them from the VM XML.
    local _tmp_vm _tmp_gpu _tmp_audio
    _tmp_vm="$(mktemp)"
    _tmp_gpu="$(mktemp)"
    _tmp_audio="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp_vm"

    # Save a full pre-live-attach XML backup (the VM XML WITH the GPU still
    # attached) so remove_live_attach can restore the GPU hostdev on revert.
    # One backup per VM; saved before python3 strips the hostdev below.
    # Atomic (write_file_atomic: temp file + install/rename) so a power loss or
    # full disk mid-write cannot leave a truncated backup on disk — the backup
    # either appears complete or not at all (remove_live_attach still validates
    # it before defining, as a second line of defense).
    local _backup_xml="/var/lib/vfio-dynamic/live-attach-backup-$_dom.xml"
    printf '%s\n' "$_xml" | write_file_atomic "$_backup_xml" 0644 "root:root"
    say "  Saved pre-live-attach VM XML backup (with GPU): $_backup_xml"

    python3 - "$_tmp_vm" "$_tmp_gpu" "$_tmp_audio" "$GUEST_GPU_BDF" "${GUEST_AUDIO_BDFS_CSV:-}" <<'PYEOF' || true
import sys, xml.etree.ElementTree as ET
# Strip a leading 0x prefix. Do NOT use the str.lstrip form with 0x — that
# strips ALL leading 0/x chars, so function 0x0 becomes empty and the BDF match
# silently fails (the GPU is never extracted from the VM XML and qemu attaches
# it at boot anyway, defeating live-attach entirely).
def _strip0x(v):
    return v[2:] if v.startswith('0x') else v
# Strip the fixed GUEST PCI address (<address type='pci'> directly under the
# hostdev, NOT the <address> inside <source> which carries the host BDF and has
# no type= attribute) so libvirt AUTO-assigns a free guest address on hot-
# attach. A fixed guest address can collide with an existing device in the
# running VM and make virsh attach-device hang (observed: attach-device held
# libvirt's VM lock for minutes on a colliding guest address).
def _strip_guest_addr(hd):
    for a in list(hd.findall('address')):
        if a.get('type') == 'pci':
            hd.remove(a)
vm_path, gpu_path, audio_path, gpu_bdf, audio_csv = sys.argv[1:6]
tree = ET.parse(vm_path); root = tree.getroot()
device_type = root.tag.replace('domain', 'devices')
devices = root.find('devices')
if devices is None: sys.exit(1)
# Parse the GPU BDF into domain/bus/slot/function hex components.
parts = gpu_bdf.split(':')
gpu_dom = parts[0]; gpu_bus = parts[1]; gpu_slot_fn = parts[2]
gpu_slot, gpu_func = gpu_slot_fn.split('.')
# Parse audio BDFs (comma-separated).
audio_bdfs = []
for a in audio_csv.split(','):
    a = a.strip()
    if not a: continue
    p = a.split(':')
    if len(p) == 3:
        sf = p[2].split('.')
        audio_bdfs.append((p[0], p[1], sf[0], sf[1] if len(sf) > 1 else '0'))
gpu_hostdev = None
audio_hostdevs = []
for hd in list(devices.findall('hostdev')):
    if hd.get('type') != 'pci': continue
    src = hd.find('source')
    if src is None: continue
    addr = src.find('address')
    if addr is None: continue
    ad = addr.get('domain', ''); ab = addr.get('bus', ''); asl = addr.get('slot', ''); af = addr.get('function', '')
    # Normalize to 4-digit domain, 2-digit bus/slot.
    ad = _strip0x(ad).zfill(4) if ad else ''
    ab = _strip0x(ab).zfill(2) if ab else ''
    asl = _strip0x(asl).zfill(2) if asl else ''
    bdf = f"{ad}:{ab}:{asl}.{_strip0x(af)}"
    if bdf.lower() == gpu_bdf.lower():
        gpu_hostdev = hd
    elif any(bdf.lower() == f"{d}:{b}:{s}.{f}".lower() for d,b,s,f in audio_bdfs):
        audio_hostdevs.append(hd)
# Write the GPU device XML. virsh attach-device wants a BARE <hostdev>
# element, NOT wrapped in <devices> — a <devices> root makes attach-device
# reject it with "unsupported configuration: unknown device type 'devices'"
# (observed: instant rc=1 failure). Write the hostdev directly as the root.
if gpu_hostdev is not None:
    _strip_guest_addr(gpu_hostdev)
    ET.ElementTree(gpu_hostdev).write(gpu_path)
    devices.remove(gpu_hostdev)
# Write the audio device XML (a bare <hostdev> — same rationale). attach-device
# takes one device element per call; write the first audio hostdev (the common
# case is a single audio function). If there are extras they are still removed
# from the VM XML below so libvirt does not attach them at boot.
if audio_hostdevs:
    for ah in audio_hostdevs:
        _strip_guest_addr(ah)
    ET.ElementTree(audio_hostdevs[0]).write(audio_path)
    for ah in audio_hostdevs:
        devices.remove(ah)
# Auto-inject the qemu guest-agent channel (virtio-serial + unix channel) so the
# live-attach helper can poll guest-ping to detect when Windows userspace is
# actually up, instead of a blind fixed delay. Idempotent: skipped if a
# guest-agent channel already exists. The virtio-win guest agent must still be
# installed inside Windows (via the virtio-win guest-tools ISO) for guest-ping
# to respond; until then the helper falls back to the fixed delay.
_has_ga = any(
    (ch.find('target') is not None and ch.find('target').get('name') == 'org.qemu.guest_agent.0')
    for ch in devices.findall('channel')
)
if not _has_ga:
    if not any(c.get('type') == 'virtio-serial' for c in devices.findall('controller')):
        _vs = ET.Element('controller', {'type': 'virtio-serial', 'index': '0'})
        devices.append(_vs)
    _ch = ET.Element('channel', {'type': 'unix'})
    ET.SubElement(_ch, 'target', {'type': 'virtio', 'name': 'org.qemu.guest_agent.0'})
    devices.append(_ch)
tree.write(vm_path)
PYEOF

    # Fail loudly if the GPU was NOT extracted: the awk gate above matched the
    # GPU BDF in the VM XML, so python3 should have written a non-empty GPU
    # device XML. An empty file means the extractor silently failed (e.g. a
    # BDF normalization bug) and the helper would have nothing to hot-attach —
    # better to abort the install here than ship a broken live-attach.
    if [[ ! -s "$_tmp_gpu" ]]; then
      note "ERROR: python3 failed to extract the GPU hostdev for '$_dom' (device XML is empty)."
      note "       The VM XML has the GPU BDF but the extractor wrote nothing. Re-run --install-live-attach."
      rm -f "$_tmp_vm" "$_tmp_gpu" "$_tmp_audio" 2>/dev/null || true
      die "GPU device XML extraction failed for '$_dom' — aborting live-attach install."
    fi

    # Save the device XMLs to the runtime location.
    if [[ -s "$_tmp_gpu" ]]; then
      cp -f "$_tmp_gpu" "$LIVE_ATTACH_GPU_XML" 2>/dev/null || true
      say "  Saved GPU device XML: $LIVE_ATTACH_GPU_XML"
    fi
    if [[ -s "$_tmp_audio" ]]; then
      cp -f "$_tmp_audio" "$LIVE_ATTACH_AUDIO_XML" 2>/dev/null || true
      say "  Saved audio device XML: $LIVE_ATTACH_AUDIO_XML"
    fi

    # Validate and redefine the VM without the GPU.
    if virt-xml-validate "$_tmp_vm" 2>/dev/null; then
      if (( ! DRY_RUN )); then
        virsh -c qemu:///system define "$_tmp_vm" 2>/dev/null
      fi
      say "  Redefined VM '$_dom' WITHOUT the GPU hostdev (backup in XML dump)"
    else
      note "WARN: XML validation failed for '$_dom'; skipping VM XML modification."
    fi

    # Add the VM to the live-attach list.
    if (( ! DRY_RUN )); then
      grep -Fixq "$_dom" "$LIVE_ATTACH_VM_LIST" 2>/dev/null || printf '%s\n' "$_dom" >>"$LIVE_ATTACH_VM_LIST"
    fi
    say "  Added '$_dom' to live-attach VM list"

    rm -f "$_tmp_vm" "$_tmp_gpu" "$_tmp_audio" 2>/dev/null || true
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)

  if (( ! _found )); then
    # Idempotency: a re-run on an ALREADY-active live-attach setup (e.g. the
    # user accepted the R25 dynamic-install prompt, or re-ran
    # --install-live-attach) finds no shut-off VM with the GPU hostdev because a
    # PRIOR install already stripped it from the VM XML(s) and saved the device
    # XML. That is a SUCCESS, not a failure — print the same green confirmation
    # banner the first install prints (so the operator sees the active set
    # instead of a confusing "No shut-off VMs found" error) and return 0.
    # Detected by ALL FOUR together: the conf key is already 1, the helper is
    # installed, the live-attach VM list is non-empty, and the GPU device XML
    # exists (a prior successful install leaves exactly this state). If only
    # some are present (a partial/half-installed state), fall through to the
    # original actionable error so the operator fixes it.
    if [[ -f "$LIVE_ATTACH_HELPER" && -s "$LIVE_ATTACH_VM_LIST" && -s "$LIVE_ATTACH_GPU_XML" ]] && \
       grep -Eq '^VFIO_DYNAMIC_LIVE_ATTACH="1"' "$CONF_FILE" 2>/dev/null; then
      local _la_vms _la_count
      _la_vms="$(tr '\n' ' ' <"$LIVE_ATTACH_VM_LIST" 2>/dev/null | sed 's/ *$//')"
      _la_count="$(grep -cve '^[[:space:]]*$' "$LIVE_ATTACH_VM_LIST" 2>/dev/null || echo 0)"
      say
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}${C_BOLD}✔ Live-attach is already active${C_RESET} for '$_la_vms' ($_la_count VM(s))"
      else
        say "✔ Live-attach is already active for '$_la_vms' ($_la_count VM(s))"
      fi
      note "The VM(s) will start WITHOUT the GPU. After ${_delay_default}s the GPU is"
      note "hot-attached to the running VM. Ensure the AMD driver is installed in Windows."
      note "To revert: sudo $SCRIPT_NAME --install-dynamic-binding (restores normal binding + re-attaches the GPU from the per-VM backup)"
      # Still deploy the latest helper/hook/bind-script code even on a re-run of an
      # already-active setup. The VM-XML surgery above was correctly skipped (the
      # GPU hostdev was already stripped by the prior install), but these three
      # are idempotent overwrites of generated scripts — safe to always run, and
      # the ONLY way the operator gets helper code updates (e.g. the R27 hotplug-
      # ready desktop notification) on a re-run instead of a stale helper on disk.
      # Without this, a re-run that hit the idempotency path shipped an outdated
      # helper (observed: pre-R27 helper with no _notify_desktop, so the GPU
      # attached successfully but no desktop notification ever popped).
      install_live_attach_helper
      install_libvirt_hook
      install_bind_script
      say "Regenerated $BIND_SCRIPT (bind logic for the live-attach helper)"
      return 0
    fi
    note "No shut-off VMs with the guest GPU found. Ensure the VM is shut off and has the GPU in its XML, then re-run."
    return 1
  fi

  # Install the helper script.
  install_live_attach_helper

  # Flip the conf key.
  rewrite_conf_key "VFIO_DYNAMIC_LIVE_ATTACH" "1"
  say "Set VFIO_DYNAMIC_LIVE_ATTACH=1 in $CONF_FILE"

  # Reinstall the libvirt hook so the live-attach branch (gates on
  # VFIO_DYNAMIC_LIVE_ATTACH=1, checks the live-attach VM list, launches the
  # helper in the background) is deployed AND the /etc/libvirt/hooks/qemu entry
  # point exists. Without this, a hook written by an older vfio.sh (pre-R23)
  # would lack the live-attach branch, and a missing qemu entry would mean
  # libvirt never invokes the hook at all — so VM start would never launch the
  # helper and the GPU would never hot-attach.
  install_libvirt_hook

  # Regenerate the bind script: the live-attach helper calls --bind-now, so
  # deploy the latest bind logic (alive-check, D0-lock, recovery, etc.).
  install_bind_script
  say "Regenerated $BIND_SCRIPT (bind logic for the live-attach helper)"

  say
  if (( ENABLE_COLOR )); then
    say "${C_GREEN}${C_BOLD}✔ Live-attach is now active${C_RESET}"
  else
    say "✔ Live-attach is now active"
  fi
  note "The VM will start WITHOUT the GPU. After ${_delay_default}s, the GPU will be"
  note "hot-attached to the running VM. Ensure the AMD driver is installed in Windows."
  note "To revert: sudo $SCRIPT_NAME --install-dynamic-binding (restores normal binding + re-attaches the GPU from the per-VM backup)"
}

# Install the virtio-win guest-agent support so the live-attach helper's smart
# guest-ping detection works: with the QEMU guest agent installed INSIDE Windows,
# the helper hot-attaches the GPU the MOMENT Windows userspace is up (often ~15s
# vs the full VFIO_DYNAMIC_LIVE_ATTACH_DELAY fixed delay) instead of waiting the
# blind fixed delay. install_live_attach already auto-injects the qemu
# guest-agent <channel> into the VM XML; this standalone mode goes one step
# further: it installs the virtio-win package (ships the driver ISO at
# /usr/share/virtio-win/virtio-win.iso) — adding the fedorapeople repo on Fedora
# first since virtio-win is not in the default repos — OR points the operator to
# the stable ISO to download themselves (this script does NOT auto-download the
# 270MB ISO), then attaches that ISO to each guest-GPU VM as a SATA CD-ROM
# (idempotent), so the
# operator can run virtio-win-guest-tools.exe inside Windows to install the
# agent + all virtio drivers. Until the agent is actually installed inside
# Windows, the helper's fixed-delay FALLBACK still works (proceeds after
# VFIO_DYNAMIC_LIVE_ATTACH_DELAY seconds), so this is a pure enhancement —
# nothing breaks if the agent is not installed.
install_virtio_win_guest_agent() {
  readable_file "$CONF_FILE" || die "Missing $CONF_FILE. Run --install-dynamic-binding first."
  # shellcheck disable=SC1090
  . "$CONF_FILE"
  [[ -n "${GUEST_GPU_BDF:-}" ]] || die "No GUEST_GPU_BDF in $CONF_FILE."
  have_cmd virsh || die "virsh not available."
  have_cmd python3 || die "python3 not available (needed to attach the ISO to the VM XML)."

  say
  hdr "virtio-win guest agent setup (smart live-attach handoff)"
  note "The live-attach helper polls the qemu guest agent (guest-ping) so the GPU hot-"
  note "attaches the MOMENT Windows is up instead of after a blind fixed delay. For that,"
  note "the virtio-win guest agent must be installed INSIDE Windows. This helper:"
  note "  1. installs the virtio-win package (adding the fedorapeople repo on Fedora"
  note "     first), or points you to the stable driver ISO to download yourself, and"
  note "  2. attaches that ISO to each guest-GPU VM as a CD-ROM (idempotent),"
  note "so you can run virtio-win-guest-tools.exe inside Windows to install the agent."
  note ""
  note "Until the agent is installed in Windows, the helper's fixed-delay FALLBACK still"
  note "works (proceeds after ${VFIO_DYNAMIC_LIVE_ATTACH_DELAY:-30}s), so nothing breaks."
  say

  # 1. Resolve the virtio-win ISO. Prefer the distro package (adding the fedorapeople
  #    repo on Fedora first, since virtio-win is NOT in the default Fedora repos); if
  #    no package is available, point the operator to the links so THEY download the
  #    ISO themselves to $VIRTIO_WIN_FALLBACK_ISO (this script does NOT auto-download
  #    the 270MB ISO). A user-provided ISO at $VIRTIO_WIN_FALLBACK_ISO is picked up.
  local _iso=""
  if [[ -f "$VIRTIO_WIN_ISO_PATH" ]]; then
    _iso="$VIRTIO_WIN_ISO_PATH"
    say "Found virtio-win ISO: $_iso"
  elif [[ -s "$VIRTIO_WIN_FALLBACK_ISO" ]]; then
    # The operator downloaded the ISO themselves to the fallback path.
    _iso="$VIRTIO_WIN_FALLBACK_ISO"
    say "Found virtio-win ISO (user-provided): $_iso"
  else
    note "virtio-win ISO not found at $VIRTIO_WIN_ISO_PATH (or $VIRTIO_WIN_FALLBACK_ISO)."
    # Distro-aware package resolution. The virtio-win package (which drops
    # the driver ISO at $VIRTIO_WIN_ISO_PATH) ships ONLY on Fedora/RHEL-
    # family (dnf) and openSUSE (zypper), and even there it is NOT in the
    # default repos — the fedorapeople virtio-win repo must be added first.
    # Debian/Ubuntu (apt) and Arch/CachyOS (pacman) have NO official virtio-win
    # package at all, so those skip straight to the link-only fallback (the
    # operator downloads the ISO themselves).
    if is_fedora_like || have_cmd dnf; then
      note "Detected Fedora/RHEL-family (dnf)."
      note "NOTE: virtio-win is NOT in the default Fedora repos. The fedorapeople"
      note "virtio-win repo must be added first (this is the official method)."
      if prompt_yn "Add the virtio-win repo (fedorapeople) and install virtio-win via dnf now (drops the driver ISO at $VIRTIO_WIN_ISO_PATH)?" Y "virtio-win package"; then
        # Add the repo first (the proven fix): curl/wget the .repo file.
        if have_cmd curl; then
          run curl -fsSL -o /etc/yum.repos.d/virtio-win.repo "$VIRTIO_WIN_REPO_URL" || note "Adding the virtio-win repo failed; will point you to the manual links below."
        elif have_cmd wget; then
          run wget -qO /etc/yum.repos.d/virtio-win.repo "$VIRTIO_WIN_REPO_URL" || note "Adding the virtio-win repo failed; will point you to the manual links below."
        fi
        run dnf -y install virtio-win || note "dnf install virtio-win failed. You can also grab a specific ISO version from: $VIRTIO_WIN_ARCHIVE_URL"
        [[ -f "$VIRTIO_WIN_ISO_PATH" ]] && _iso="$VIRTIO_WIN_ISO_PATH"
      fi
    elif is_opensuse_like || have_cmd zypper; then
      note "Detected openSUSE-family (zypper)."
      note "NOTE: virtio-win is NOT in the default openSUSE repos."
      if prompt_yn "Try zypper install virtio-win now (if it fails, download the RPM and install it manually)?" Y "virtio-win package"; then
        run zypper --non-interactive in virtio-win || note "zypper install virtio-win failed. Download the RPM directly and install it: sudo rpm -iv virtio-win.noarch.rpm (from $VIRTIO_WIN_RPM_URL), or grab a specific ISO version from: $VIRTIO_WIN_ARCHIVE_URL"
        [[ -f "$VIRTIO_WIN_ISO_PATH" ]] && _iso="$VIRTIO_WIN_ISO_PATH"
      fi
    elif have_cmd apt-get; then
      note "Detected Debian/Ubuntu-family (apt): there is NO official virtio-win package"
      note "in apt repositories. Download the ISO yourself from fedorapeople.org."
      note "  Stable ISO:  wget -O $VIRTIO_WIN_FALLBACK_ISO $VIRTIO_WIN_STABLE_URL"
      note "  All released ISOs (pick a specific version): $VIRTIO_WIN_ARCHIVE_URL"
      note "(drop it at $VIRTIO_WIN_FALLBACK_ISO, then re-run.)"
    elif have_cmd pacman; then
      note "Detected Arch-family e.g. Arch/CachyOS (pacman): there is NO official virtio-win"
      note "package in the pacman repos (it is only in the AUR). Download the ISO yourself"
      note "from fedorapeople.org."
      note "  Stable ISO:  wget -O $VIRTIO_WIN_FALLBACK_ISO $VIRTIO_WIN_STABLE_URL"
      note "  All released ISOs (pick a specific version): $VIRTIO_WIN_ARCHIVE_URL"
      note "(drop it at $VIRTIO_WIN_FALLBACK_ISO, then re-run.)"
    else
      note "No recognized package manager with a virtio-win package detected."
      note "Download the ISO yourself from fedorapeople.org."
    fi
    if [[ -z "$_iso" ]]; then
      note "Could not obtain the virtio-win ISO via a package. Download it yourself, then re-run:"
      note "  Stable ISO:  wget -O $VIRTIO_WIN_FALLBACK_ISO $VIRTIO_WIN_STABLE_URL"
      note "  All released ISOs (pick a specific version): $VIRTIO_WIN_ARCHIVE_URL"
      note "  Fedora/RHEL RPM (install the package manually): sudo rpm -iv virtio-win.noarch.rpm from $VIRTIO_WIN_RPM_URL"
      return 1
    fi
  fi

  # 2. Attach the ISO as a SATA CD-ROM to each guest-GPU VM (idempotent, shut-off
  #    only). A VM qualifies if it has the GPU BDF in its XML OR it is in the
  #    live-attach VM list (live-attach strips the GPU hostdev, so the BDF grep
  #    alone would miss an already-live-attach-configured VM). Uses python3 +
  #    ElementTree (same approach as install_live_attach) so it works without
  #    virt-xml and auto-assigns a free vdX target. Idempotent: skips a VM that
  #    already has this ISO attached as a cdrom (python exit 3).
  local _dom _xml _bdfs _state _found=0 _updated=0 _skipped_already=0 _skipped_running=0
  local _gpu_bdf="$GUEST_GPU_BDF"
  local _la_list="/var/lib/vfio-dynamic/live-attach-vms"
  say
  note "Attaching the ISO as a CD-ROM to each shut-off guest-GPU VM (idempotent)..."
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    _bdfs="$(printf '%s' "$_xml" | awk '
      /<hostdev/ { in_hostdev=1; is_pci=0 }
      in_hostdev && /type=.pci./ { is_pci=1 }
      in_hostdev && is_pci && /<address/ {
        line=$0; dom=""; bus=""; slot=""; fn=""
        if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
        if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
        if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
        if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
        if (dom != "" && bus != "" && slot != "" && fn != "") {
          while (length(dom) < 4) dom = "0" dom
          while (length(bus) < 2) bus = "0" bus
          while (length(slot) < 2) slot = "0" slot
          printf "%s:%s:%s.%s\n", dom, bus, slot, fn
        }
      }
      /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
    ')"
    local _is_guest=0
    if grep -Fixq "$_gpu_bdf" <<<"$_bdfs" 2>/dev/null; then
      _is_guest=1
    elif [[ -f "$_la_list" ]] && grep -Fixq "$_dom" "$_la_list" 2>/dev/null; then
      _is_guest=1
    fi
    (( _is_guest )) || continue
    _found=1
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping. Shut it off and re-run."
      _skipped_running=1
      continue
    fi
    local _tmp_vm _py_status=0
    _tmp_vm="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp_vm"
    python3 - "$_tmp_vm" "$_iso" <<'PYEOF' || _py_status=$?
import sys, string, xml.etree.ElementTree as ET
vm_path, iso_path = sys.argv[1], sys.argv[2]
tree = ET.parse(vm_path); root = tree.getroot()
devices = root.find('devices')
if devices is None: sys.exit(1)
# Idempotent: skip if a cdrom already uses this ISO as its source file.
for d in devices.findall('disk'):
    if d.get('device') == 'cdrom':
        src = d.find('source')
        if src is not None and src.get('file') == iso_path:
            sys.exit(3)
# Find a free sdX target (sda..sdz) for the SATA bus cdrom. The existing
# disks may use sd* (SATA) or vd* (virtio); only sd* is valid for bus='sata'.
# Using a vd* name on a SATA bus makes libvirt assign a colliding drive address
# and reject the define ('duplicated address for disk ... sda').
used = set()
for d in devices.findall('disk'):
    tgt = d.find('target')
    if tgt is not None and (tgt.get('dev','') or '').startswith('sd'):
        used.add(tgt.get('dev'))
_dev = None
for c in string.ascii_lowercase:
    cand = 'sd' + c
    if cand not in used:
        _dev = cand
        break
if _dev is None: sys.exit(4)
disk = ET.Element('disk', {'type': 'file', 'device': 'cdrom'})
ET.SubElement(disk, 'driver', {'name': 'qemu', 'type': 'raw'})
ET.SubElement(disk, 'source', {'file': iso_path})
ET.SubElement(disk, 'target', {'dev': _dev, 'bus': 'sata'})
ET.SubElement(disk, 'readonly')
devices.append(disk)
tree.write(vm_path)
sys.exit(0)
PYEOF
    if (( _py_status == 3 )); then
      say "VM '$_dom' already has the virtio-win ISO attached as a CD-ROM; skipping (idempotent)."
      _skipped_already=1
      rm -f "$_tmp_vm" 2>/dev/null || true
      continue
    elif (( _py_status == 4 )); then
      note "WARN: no free vdX CD-ROM target for '$_dom' (all vda..vdz used); skipping."
      rm -f "$_tmp_vm" 2>/dev/null || true
      continue
    elif (( _py_status != 0 )); then
      note "WARN: virtio-win ISO attach XML patching failed for '$_dom' (python exit $_py_status); skipping."
      rm -f "$_tmp_vm" 2>/dev/null || true
      continue
    fi
    if virt-xml-validate "$_tmp_vm" 2>/dev/null; then
      local _define_rc=0
      if (( ! DRY_RUN )); then
        virsh -c qemu:///system define "$_tmp_vm" 2>/dev/null || _define_rc=$?
      fi
      if (( _define_rc != 0 )); then
        note "ERROR: virsh define failed for '$_dom' (exit $_define_rc) — the ISO CD-ROM was NOT attached. Re-run --install-virtio-win-guest-agent."
      else
        say "Attached virtio-win ISO to VM '$_dom' as a SATA CD-ROM."
        _updated=1
      fi
    else
      note "WARN: virt-xml-validate failed for '$_dom'; skipping ISO attach."
    fi
    rm -f "$_tmp_vm" 2>/dev/null || true
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)

  if (( ! _found )); then
    note "No guest-GPU VMs found. Ensure a VM has the guest GPU attached (or is in the"
    note "live-attach VM list) and re-run."
    return 1
  fi

  say
  if (( _updated )); then
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}${C_BOLD}✔ virtio-win ISO attached to guest-GPU VM(s)${C_RESET}"
    else
      say "✔ virtio-win ISO attached to guest-GPU VM(s)"
    fi
  elif (( _skipped_already )); then
    say "virtio-win ISO was already attached to all guest-GPU VM(s); nothing to do."
  fi
  say
  hdr "Next: install the agent INSIDE Windows"
  note "Start the VM, open the virtio-win CD in File Explorer, and run:"
  note "  virtio-win-guest-tools.exe   (or virtio-win-gt-x64.msi for a 64-bit silent install)"
  note "This installs the QEMU guest agent + all virtio drivers. Reboot the VM afterward."
  note "Driver ISO archive (all released versions, if you need a specific one):"
  note "  $VIRTIO_WIN_ARCHIVE_URL"
  note ""
  note "Once the agent is running in Windows, the live-attach helper's guest-ping poll"
  note "responds and the GPU hot-attaches the MOMENT Windows is up (often ~15s vs the"
  note "full ${VFIO_DYNAMIC_LIVE_ATTACH_DELAY:-30}s fixed delay). Until then, the fixed-"
  note "delay FALLBACK still works, so nothing breaks."
}

# Remove the virtio-win guest-agent ISO CD-ROM that install_virtio_win_guest_agent
# attached to each guest-GPU VM, plus the downloaded fallback ISO. Called by
# remove_live_attach (so --reset and --install-early-binding both clean it up).
# SAFETY — "how it knows the correct CD": only removes a <disk> whose
# device='cdrom' AND whose <source file=> is EXACTLY one of the two paths this
# script manages (VIRTIO_WIN_ISO_PATH or VIRTIO_WIN_FALLBACK_ISO). A real
# optical-drive passthrough or a different ISO the user attached has a different
# source file, so it is never touched. install_virtio_win_guest_agent only ever
# attached to guest-GPU VMs, so a cdrom sourcing one of these paths is, by
# construction, one we attached (no separate BDF match needed). The distro ISO
# at VIRTIO_WIN_ISO_PATH is owned by the package manager (dnf/zypper) and is
# NEVER deleted; only the downloaded fallback ISO at VIRTIO_WIN_FALLBACK_ISO is
# removed. Idempotent (no-op if the ISO is not attached). Shut-off VMs only
# (virsh define requires it); a running VM is noted + skipped. Best-effort:
# never aborts cleanup.
remove_virtio_win_guest_agent() {
  if ! readable_file "$CONF_FILE"; then
    return 0
  fi
  if ! have_cmd virsh || ! have_cmd python3; then
    return 0
  fi
  local _dom _xml _state _found=0 _removed=0
  say
  note "Detaching the script-attached virtio-win ISO CD-ROM from each shut-off VM (idempotent)..."
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Quick skip: only consider VMs whose XML references one of our managed ISO
    # paths. The python step below further requires device='cdrom' + an exact
    # source-file match, so a real optical drive or a different ISO is never touched.
    if ! grep -Fq "$VIRTIO_WIN_ISO_PATH" <<<"$_xml" 2>/dev/null \
      && ! grep -Fq "$VIRTIO_WIN_FALLBACK_ISO" <<<"$_xml" 2>/dev/null; then
      continue
    fi
    _found=1
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); leaving the virtio-win ISO CD-ROM in place. Shut it off and re-run --reset / --install-early-binding to remove it."
      continue
    fi
    local _tmp_vm _py_status=0
    _tmp_vm="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp_vm"
    python3 - "$_tmp_vm" "$VIRTIO_WIN_ISO_PATH" "$VIRTIO_WIN_FALLBACK_ISO" <<'DETACHEOF' || _py_status=$?
import sys, xml.etree.ElementTree as ET
vm_path = sys.argv[1]
iso_paths = set(sys.argv[2:])  # only the script-managed ISO paths
tree = ET.parse(vm_path); root = tree.getroot()
devices = root.find('devices')
if devices is None: sys.exit(1)
removed = 0
for d in list(devices.findall('disk')):
    if d.get('device') == 'cdrom':
        src = d.find('source')
        if src is not None and src.get('file') in iso_paths:
            devices.remove(d)
            removed += 1
if removed == 0:
    sys.exit(3)  # not attached as a script cdrom (idempotent no-op)
tree.write(vm_path)
sys.exit(0)
DETACHEOF
    if (( _py_status == 3 )); then
      # Not attached as a script cdrom (the path hit was not a matching cdrom).
      rm -f "$_tmp_vm" 2>/dev/null || true
      continue
    elif (( _py_status != 0 )); then
      note "WARN: virtio-win ISO detach XML patching failed for '$_dom' (python exit $_py_status); skipping."
      rm -f "$_tmp_vm" 2>/dev/null || true
      continue
    fi
    if virt-xml-validate "$_tmp_vm" 2>/dev/null; then
      if (( ! DRY_RUN )); then
        virsh -c qemu:///system define "$_tmp_vm" 2>/dev/null
      fi
      say "Detached virtio-win ISO CD-ROM from VM '$_dom'."
      _removed=1
    else
      note "WARN: virt-xml-validate failed for '$_dom' after ISO detach; skipping redefine."
    fi
    rm -f "$_tmp_vm" 2>/dev/null || true
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)

  # Remove the downloaded fallback ISO (ours). NEVER touch the distro ISO at
  # VIRTIO_WIN_ISO_PATH — that is owned by the package manager (dnf/zypper).
  if [[ -f "$VIRTIO_WIN_FALLBACK_ISO" ]]; then
    run rm -f "$VIRTIO_WIN_FALLBACK_ISO" 2>/dev/null || true
    _removed=1
  fi
  (( _removed )) && note "Removed virtio-win guest-agent ISO CD-ROM(s) + the downloaded fallback ISO."
  (( ! _found )) && note "No VM with the script-attached virtio-win ISO found; nothing to detach."
}

# Remove the live-attach workflow (called by --install-dynamic-binding to restore
# normal binding, and by --reset).
remove_live_attach() {
  local _removed=0

  # Restore the GPU hostdev to each VM's XML from the pre-live-attach backup
  # BEFORE deleting the backup + VM list. install_live_attach removed the GPU
  # hostdev from each VM's persistent XML so the VM boots on a virtual display;
  # this re-defines the VM from the saved backup (with the GPU re-attached),
  # undoing that modification so --install-dynamic-binding / --reset leave the
  # VM with its GPU back. Only restores shut-off VMs (virsh define requires it);
  # a running VM is skipped with a note so the user can shut it off and re-run.
  # Best-effort: missing backup / failed validation / no virsh are skipped so
  # cleanup still completes.
  if [[ -f "$LIVE_ATTACH_VM_LIST" ]] && have_cmd virsh; then
    local _dom _backup_xml _state
    while IFS= read -r _dom; do
      [[ -n "$_dom" ]] || continue
      _backup_xml="/var/lib/vfio-dynamic/live-attach-backup-$_dom.xml"
      [[ -f "$_backup_xml" ]] || continue
      _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
      if [[ "$_state" != "shut off" ]]; then
        note "WARN: VM '$_dom' is '$_state' (not shut off); skipping XML restore. Shut it off and re-run to restore the GPU hostdev."
        continue
      fi
      if virt-xml-validate "$_backup_xml" 2>/dev/null; then
        if (( ! DRY_RUN )) && virsh -c qemu:///system define "$_backup_xml" 2>/dev/null; then
          say "Restored GPU hostdev to VM '$_dom' from pre-live-attach backup."
          _removed=1
        fi
      else
        note "WARN: pre-live-attach backup for '$_dom' failed validation; skipping XML restore (backup left in place)."
      fi
    done < "$LIVE_ATTACH_VM_LIST"
  fi

  # Remove the virtio-win guest-agent ISO CD-ROM that install_virtio_win_guest_agent
  # attached to each guest-GPU VM (and the downloaded fallback ISO). Best-effort:
  # never aborts cleanup. Only removes a cdrom whose source is one of the two
  # script-managed ISO paths — never a real optical drive or a different ISO.
  remove_virtio_win_guest_agent

  # Remove the managed artifacts.
  if [[ -f "$LIVE_ATTACH_HELPER" ]]; then
    run rm -f "$LIVE_ATTACH_HELPER" 2>/dev/null || true
    _removed=1
  fi
  if [[ -f "$LIVE_ATTACH_GPU_XML" ]]; then
    run rm -f "$LIVE_ATTACH_GPU_XML" 2>/dev/null || true
    _removed=1
  fi
  if [[ -f "$LIVE_ATTACH_AUDIO_XML" ]]; then
    run rm -f "$LIVE_ATTACH_AUDIO_XML" 2>/dev/null || true
    _removed=1
  fi
  if [[ -f "$LIVE_ATTACH_VM_LIST" ]]; then
    run rm -f "$LIVE_ATTACH_VM_LIST" 2>/dev/null || true
    _removed=1
  fi
  # Remove per-VM pre-live-attach XML backups (glob: one backup per VM).
  local _bxml
  for _bxml in /var/lib/vfio-dynamic/live-attach-backup-*.xml; do
    [[ -f "$_bxml" ]] || continue
    run rm -f "$_bxml" 2>/dev/null || true
    _removed=1
  done
  # Flip the conf key back to 0.
  if readable_file "$CONF_FILE" && grep -Eq '^VFIO_DYNAMIC_LIVE_ATTACH="1"' "$CONF_FILE" 2>/dev/null; then
    rewrite_conf_key "VFIO_DYNAMIC_LIVE_ATTACH" "0"
    _removed=1
  fi
  (( _removed )) && note "Removed live-attach workflow (VM XML restored from pre-live-attach backups where the VM was shut off)."
}
# guest reboot lifecycle events and does a soft function-level reset on the
# guest GPU to clear the display wedge. On RX 9070 / RDNA4 with on_reboot=restart
# (warm reboot), the card survives (qemu never releases the vfio device, link
# stays up), but the GPU's display engine wedges and OVMF can't re-POST (frozen
# screen). The soft FLR clears the display wedge so OVMF re-POSTs and the guest
# reboots cleanly — no host reboot needed for a guest restart.
install_reboot_flr_monitor() {
  if ! have_cmd systemctl; then
    note "systemctl not available; skipping reboot-FLR monitor installation."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; skipping reboot-FLR monitor installation (needs virsh event)."
    return 0
  fi
  # The RX 9070 family pre-FLR Gen1 downtrain + adaptive restore need setpci
  # (pciutils) to read/write LnkCtl2/LnkCtl/LnkSta on the upstream switch port.
  # Without it the warm-reboot display-wedge fix is silently inactive, so make
  # the dependency obvious (with the distro install command) instead of only
  # logging it at FLR time.
  if ! have_cmd setpci; then
    note "setpci (pciutils) is NOT installed: the reboot-FLR monitor's RX 9070 family"
    note "pre-FLR Gen1 downtrain + adaptive PCIe link restore will be SKIPPED."
    if have_cmd zypper; then
      note "Install it with: sudo zypper in pciutils"
    elif have_cmd dnf; then
      note "Install it with: sudo dnf install pciutils"
    elif have_cmd apt-get; then
      note "Install it with: sudo apt-get install pciutils"
    elif have_cmd pacman; then
      note "Install it with: sudo pacman -S pciutils"
    else
      note "Install the pciutils package via your package manager."
    fi
  fi

  if (( ! DRY_RUN )); then
    mkdir -p "$(dirname "$REBOOT_FLR_SCRIPT")" "$(dirname "$REBOOT_FLR_UNIT")"
  fi

  backup_file "$REBOOT_FLR_SCRIPT"
  backup_file "$REBOOT_FLR_UNIT"

  write_file_atomic "$REBOOT_FLR_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Managed by vfio.sh — reboot-FLR monitor for dynamic GPU binding.
# Watches libvirt for guest reboot lifecycle events and does a soft
# function-level reset on the guest GPU to clear the display wedge.
# On RX 9070 / RDNA4 with on_reboot=restart (warm reboot), the card survives
# (qemu never releases the vfio device, PCIe link stays up), but the GPU's
# display engine wedges in the old guest's framebuffer and OVMF cannot re-POST
# (frozen screen). A soft FLR (echo 1 > sys/reset) clears the display wedge
# WITHOUT dropping the PCIe link, allowing OVMF to re-POST on the warm reboot.
# Removed by: sudo vfio.sh --reset  (or sudo vfio.sh --install-early-binding)

CONF_FILE="/etc/vfio-gpu-passthrough.conf"

[[ -f "$CONF_FILE" ]] || exit 0
# shellcheck disable=SC1090
. "$CONF_FILE"

[[ -n "${GUEST_GPU_BDF:-}" ]] || exit 0

jlog() { command -v logger >/dev/null 2>&1 && logger -t vfio-reboot-flr -- "$*" 2>/dev/null || true; }

# RX 9070 family / RDNA4 (Navi 48, gfx1201) device ID — the cards this
# downtrain logic is gated on. The RX 9070, RX 9070 XT, and RX 9070 GRE ALL
# share device ID 0x7550 (same ASIC, differentiated by subsystem/BIOS/revision
# — NOT by base device ID), so this single ID covers the whole consumer 9070
# family. Other AMD cards (or non-AMD) skip the Gen1 downtrain entirely.
# (0x7551 is also Navi 48 silicon — Radeon AI PRO R9700 — same ASIC/FLR
#  behavior, but not a consumer 9070 SKU so it is not in the passthrough gate;
#  the adaptive speed restore below would handle it identically if added.)
_RX9070_DEVICE_ID="7550"

# Best-effort SKU resolver for the RX 9070 family. The RX 9070, 9070 XT, and
# 9070 GRE all share PCI device 0x7550; they are differentiated by PCI revision
# (observed in public probes: rev 0xc0 -> 9070 XT, 0xc2 -> 9070 GRE,
# 0xc3 -> 9070 base) and/or subsystem vendor/device (board-model specific).
# This reads the PCI revision from sysfs and maps known revisions to SKU
# names for diagnostic logging. The mapping is HEURISTIC (sampled from public
# probes) and may not cover every board; unknown revisions fall back to a
# labeled "unknown SKU" string. Returns 0 and echoes the SKU name (always);
# returns 1 only if the revision sysfs file is unreadable.
_rx9070_sku_name() {
  local _sys="/sys/bus/pci/devices/$GUEST_GPU_BDF" _rev _r
  [[ -r "$_sys/revision" ]] || return 1
  _rev="$(cat "$_sys/revision" 2>/dev/null || true)"
  [[ -n "$_rev" ]] || return 1
  _r="$(printf '%s' "$_rev" | tr -d '[:space:]' | sed 's/^0x//' | tr 'A-F' 'a-f')"
  case "$_r" in
    c0) printf '%s\n' "RX 9070 XT" ;;
    c2) printf '%s\n' "RX 9070 GRE" ;;
    c3) printf '%s\n' "RX 9070" ;;
    *) printf '%s\n' "RX 9070 family (unknown SKU, rev 0x${_r:-?})" ;;
  esac
  return 0
}

# Find the upstream PCIe switch downstream port for the GPU BDF by walking
# sysfs. For 0000:0e:00.0 the parent bridge is 0000:0d:00.0 (the AMD Navi 10
# XL Downstream Port of the on-card PCIe switch). Prints the upstream BDF
# (e.g. 0000:0d:00.0) and returns 0, or returns 1 if not found.
_gpu_upstream_port() {
  local _gpu="$1" _parent_dir _upstream
  [[ -n "$_gpu" ]] || return 1
  # sysfs layout: /sys/bus/pci/devices/<upstream>/<gpu>  (the GPU is a child
  # of the upstream bridge in the device tree).
  _parent_dir="$(ls -d /sys/bus/pci/devices/*/"$_gpu" 2>/dev/null | head -1)"
  [[ -n "$_parent_dir" ]] || return 1
  _upstream="$(basename "$(dirname "$_parent_dir")")"
  [[ -n "$_upstream" ]] || return 1
  printf '%s\n' "$_upstream"
}

# Check if the guest GPU is an RX 9070 / RDNA4 (vendor 1002, device 7550).
# Used to gate the pre-FLR Gen1 downtrain so it ONLY runs on this specific
# card family (other cards may not need it, or may be harmed by it).
_is_rx9070() {
  local _sys="/sys/bus/pci/devices/$GUEST_GPU_BDF" _vendor _device _cfg
  [[ -d "$_sys" ]] || return 1
  # Read vendor + device from config space (first 4 bytes: little-endian
  # vendor at 0x00, device at 0x02). 02 10 50 75 = vendor 0x1002, device 0x7550.
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  [[ -n "$_cfg" ]] || return 1
  # vendor = bytes 2:1 (LE), device = bytes 4:3 (LE)
  _vendor="${_cfg:2:2}${_cfg:0:2}"
  _device="${_cfg:6:2}${_cfg:4:2}"
  [[ "${_vendor,,}" == "1002" ]] || return 1
  [[ "${_device,,}" == "$_RX9070_DEVICE_ID" ]]
}

# Read a 16-bit PCI config word via setpci and return it as a clean 4-hex-digit
# lowercase string, trimmed of whitespace and left-padded to 4 digits. Returns
# 1 if setpci fails or the value is not hex. Defensive against setpci output
# formatting variations (leading/trailing whitespace, short values) so the
# LnkCtl2 nibble slicing below is robust regardless of setpci's exact format
# (the raw `${_ctl2:3:1}` slice assumes exactly 4 clean hex chars).
_setpci_word() {
  local _bdf="$1" _off="$2" _v
  _v="$(setpci -s "$_bdf" "$_off" 2>/dev/null || true)"
  [[ -n "$_v" ]] || return 1
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  [[ "$_v" =~ ^[0-9a-fA-F]+$ ]] || return 1
  while (( ${#_v} < 4 )); do _v="0$_v"; done
  printf '%s\n' "${_v,,}"
}

# Map a PCIe link-speed string (as printed by sysfs max_link_speed /
# current_link_speed, e.g. "16 GT/s", "2.5 GT/s") to a generation integer
# (1=Gen1 .. 6=Gen6). Returns 1 on unknown/empty so callers can fall back.
_speed_to_gen() {
  local _s="${1:-}" _n
  [[ -n "$_s" ]] || return 1
  _n="$(printf '%s' "$_s" | tr -cd '0-9.')"
  [[ -n "$_n" ]] || return 1
  case "$_n" in
    2.5) echo 1 ;;
    5|5.0) echo 2 ;;
    8|8.0) echo 3 ;;
    16|16.0) echo 4 ;;
    32|32.0) echo 5 ;;
    64|64.0) echo 6 ;;
    *) return 1 ;;
  esac
  return 0
}

# Read a sysfs link-speed attribute for a PCI BDF and echo its generation
# (1-6). $1 = BDF, $2 = attribute (max_link_speed | current_link_speed).
# Returns 1 if sysfs is absent/unreadable or the value is unrecognized, so the
# caller can fall back to the saved LnkCtl2 target. Uses the kernel-parsed
# value (reliable across config-space layouts) instead of guessing LnkCap
# register offsets.
_port_speed_gen() {
  local _bdf="$1" _attr="$2" _f _v
  _f="/sys/bus/pci/devices/$_bdf/$_attr"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null)" || _v=""
  [[ -n "$_v" ]] || return 1
  _speed_to_gen "$_v"
}

# Read the current PCIe link width from sysfs (e.g. "16", "8", "1") for a PCI
# BDF. Returns 1 if sysfs is absent/unreadable. Used in the restore diagnostics
# so a width degradation (x16->x8 from a bad slot/cable) is visible alongside
# the speed — the speed check alone cannot see a width problem.
_port_link_width() {
  local _bdf="$1" _f _v
  _f="/sys/bus/pci/devices/$_bdf/current_link_width"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null || true)"
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  printf '%s\n' "$_v"
}

# Check that the GPU endpoint itself is alive (vendor sysfs not 0xffff and
# config space not all-ff). Used after the post-FLR link restore to catch the
# case where the LINK is back up at a good gen but the GPU's display engine is
# still wedged (the speed check alone cannot see that). Non-fatal: logs a WARN
# but does not fail the FLR (the display-wedge clear already happened).
_gpu_alive() {
  local _sys="/sys/bus/pci/devices/$GUEST_GPU_BDF" _vendor _cfg
  [[ -d "$_sys" ]] || return 1
  _vendor="$(cat "$_sys/vendor" 2>/dev/null || true)"
  _vendor="$(printf '%s' "$_vendor" | tr -d '[:space:]')"
  [[ -n "$_vendor" ]] || return 1
  [[ "$_vendor" != "0xffff" ]] || return 1
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  [[ -n "$_cfg" ]] || return 1
  [[ "$_cfg" != "ffffffff" ]]
}

# Pre-FLR Gen1 downtrain + post-FLR link-wait + adaptive target restore.
# On the RX 9070 family / RDNA4 the post-FLR link retrain at the card's max gen
# can fail (the on-card switch can't retrain Gen5 after a function reset).
# Forcing the target link speed to Gen1 BEFORE the FLR makes the retrain happen
# at Gen1 (fast + reliable), so the link comes back in milliseconds and OVMF
# re-POSTs on a live GPU. After the link is back, _post_flr_restore_target
# restores the link to the hardware's actual max (Gen5 on Gen5 boards, Gen4 on
# slower slots/mobos) with a degraded-link fallback. Gated to the RX 9070
# family (vendor 1002, device 7550). Uses setpci on the upstream switch port.
# Registers (verified on ASUS TUF X570-PLUS + RX 9070):
#   LnkCtl2 at 0x88: bits[3:0] = Target Link Speed (1=Gen1, 2=Gen2, 5=Gen5)
#   LnkCtl  at 0x68: bit 5 (0x20) = Retrain Link
#   LnkSta  at 0x6A: bit 13 (0x2000) = Data Link Layer Link Active
_pre_flr_gen1_downtrain() {
  local _upstream _ctl2 _ctl _sta _i _sku
  _upstream="$(_gpu_upstream_port "$GUEST_GPU_BDF" 2>/dev/null || true)"
  if [[ -z "$_upstream" ]]; then
    jlog "$GUEST_GPU_BDF: pre-FLR downtrain skipped (could not find upstream port)"
    return 1
  fi
  if ! command -v setpci >/dev/null 2>&1; then
    jlog "$GUEST_GPU_BDF: pre-FLR downtrain skipped (setpci not installed)"
    return 1
  fi

  # Resolve the SKU name for diagnostic logging (best-effort; the 9070 / 9070
  # XT / 9070 GRE share device 0x7550 and are told apart by PCI revision).
  _sku="$(_rx9070_sku_name 2>/dev/null || echo "RX 9070 family")"
  _FLR_SKU_NAME="$_sku"

  # --- Hardware detection: read the upstream switch port's link capability
  # and current negotiated speed/width so the post-FLR restore can ADAPT to
  # the actual hardware (Gen4 slot/mobo vs Gen5 card) instead of blindly
  # forcing Gen5. If the link is already running below its max (slower slot,
  # signal integrity, or a Gen4 board), the restore keeps that proven gen
  # rather than forcing a higher one that may fail to retrain after the FLR.
  # Stashed in globals for _post_flr_restore_target (same do_flr() call).
  _FLR_DETECTED_CAP="$(_port_speed_gen "$_upstream" max_link_speed 2>/dev/null || true)"
  _FLR_DETECTED_CUR="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
  _FLR_DETECTED_WIDTH="$(_port_link_width "$_upstream" 2>/dev/null || true)"
  jlog "$GUEST_GPU_BDF: pre-FLR Gen1 downtrain on upstream $_upstream ($_sku; cap=Gen${_FLR_DETECTED_CAP:-?} cur=Gen${_FLR_DETECTED_CUR:-?} width=x${_FLR_DETECTED_WIDTH:-?})"

  # Read current LnkCtl2 (we will restore it after) via the defensive helper
  # so whitespace/short-value formatting from setpci can't corrupt the slice.
  _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
  if [[ -z "$_ctl2" ]]; then
    jlog "$GUEST_GPU_BDF: pre-FLR downtrain aborted (could not read LnkCtl2 from $_upstream)"
    return 1
  fi
  # Save the ORIGINAL target speed (low nibble) + full LnkCtl2 so the restore
  # can put it back exactly if sysfs hardware detection is unavailable.
  _FLR_SAVED_CTL2="$_ctl2"
  _FLR_SAVED_TARGET="$(printf '%d' "0x${_ctl2:3:1}" 2>/dev/null)" || true

  # Save the upper 12 bits (preserve de-emphasis etc), set low nibble to 1 (Gen1).
  # _ctl2 is now a clean 4-hex-digit string like '0045' — keep bits 15:4, set
  # bits 3:0 to 0001.
  local _saved_hi="${_ctl2:0:3}"  # first 3 hex digits = bits 15:4
  local _gen1_ctl2="${_saved_hi}1"
  setpci -s "$_upstream" 88.w="$_gen1_ctl2" 2>/dev/null || true
  jlog "$GUEST_GPU_BDF: LnkCtl2 set to $_gen1_ctl2 (was $_ctl2) — target Gen1"
  # Force a retrain so the link downtrains to Gen1 NOW (before the FLR).
  _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
  if [[ -n "$_ctl" ]]; then
    setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
  fi
  jlog "$GUEST_GPU_BDF: forced link retrain at Gen1 (LnkCtl bit 5 set)"
  # Wait for the link to come back at Gen1 (poll LnkSta bit 13, up to 2s).
  for _i in $(seq 1 20); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$GUEST_GPU_BDF: link active at Gen1 after $(( _i * 100 ))ms"
      return 0
    fi
    sleep 0.1
  done
  jlog "$GUEST_GPU_BDF: WARN link did not come back at Gen1 within 2s (continuing with FLR anyway)"
  return 0
}

# Post-FLR link restore that ADAPTS to the detected hardware instead of
# blindly forcing Gen5. The restore target is chosen from, in priority order:
#   1. the pre-FLR negotiated speed when it was below the port's capability
#      (the link was already running slower — Gen4 slot / signal integrity /
#      board limit — so keep that proven gen instead of forcing higher),
#   2. the port's detected capability (max_link_speed),
#   3. the saved original LnkCtl2 low nibble (BIOS-configured target),
#   4. Gen5 (last-resort default for the RX 9070 family on Gen5 boards).
# An optional operator cap (VFIO_REBOOT_FLR_MAX_GEN, 1..6) clamps the target
# for boards that reliably retrain at a lower gen but not the card's full cap.
# The restore then does a BOUNDED DESCENT: set LnkCtl2[3:0] = gen and retrain
# from the target down to 1, accepting the highest gen the link actually
# negotiates at. This generalizes the old one-step fallback: a Gen5 target
# that only retrains at Gen4 will also try Gen3 if Gen4 also fails, etc.
# Bounded (<= 6 iterations) so it can never loop forever, and Gen1 is
# guaranteed (the pre-FLR downtrain proved the link works at Gen1). Link WIDTH
# is logged too (x16->x8 degradation from a bad slot/cable is otherwise
# invisible), and a GPU-endpoint alive-check catches a wedged GPU behind a live
# link. Gated to the RX 9070 family.
_post_flr_restore_target() {
  local _upstream _ctl _sta _i _target _neg_gen _g _ctl2 _width _p _best _saved_hi
  _upstream="$(_gpu_upstream_port "$GUEST_GPU_BDF" 2>/dev/null || true)"
  [[ -n "$_upstream" ]] || return 1
  command -v setpci >/dev/null 2>&1 || return 1
  # Wait for the link to come back after the FLR (poll LnkSta bit 13, up to 5s).
  for _i in $(seq 1 50); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$GUEST_GPU_BDF: link active after FLR (waited $(( _i * 100 ))ms)"
      break
    fi
    sleep 0.1
  done
  # --- Choose the restore target adaptively from hardware detection. ---
  local _cap="${_FLR_DETECTED_CAP:-}"
  local _cur="${_FLR_DETECTED_CUR:-}"
  local _sav="${_FLR_SAVED_TARGET:-}"
  if [[ -n "$_cap" && -n "$_cur" ]]; then
    if (( _cur < _cap )) 2>/dev/null; then
      _target="$_cur"
      jlog "$GUEST_GPU_BDF: link was running Gen$_cur < cap Gen$_cap (slower slot/hardware); adapting restore to Gen$_cur"
    else
      _target="$_cap"
      jlog "$GUEST_GPU_BDF: restoring to detected link capability Gen$_cap"
    fi
  elif [[ -n "$_cap" ]]; then
    _target="$_cap"
    jlog "$GUEST_GPU_BDF: restoring to detected link capability Gen$_cap (current speed unavailable)"
  elif [[ -n "$_sav" ]]; then
    _target="$_sav"
    jlog "$GUEST_GPU_BDF: sysfs speed detection unavailable; restoring to saved LnkCtl2 target Gen$_sav"
  else
    _target=5
    jlog "$GUEST_GPU_BDF: no speed detection available; defaulting restore to Gen5"
  fi
  # --- Optional operator cap: VFIO_REBOOT_FLR_MAX_GEN clamps the restore
  # target for boards that reliably retrain at a lower gen but not the card's
  # full capability (e.g. a Gen5 card in a board that only retrains Gen4 after
  # an FLR). Empty/invalid = no cap.
  local _max="${VFIO_REBOOT_FLR_MAX_GEN:-}"
  if [[ -n "$_max" ]] && (( _max >= 1 && _max <= 6 )) 2>/dev/null; then
    if (( _target > _max )) 2>/dev/null; then
      jlog "$GUEST_GPU_BDF: VFIO_REBOOT_FLR_MAX_GEN=$_max clamps restore target from Gen$_target to Gen$_max"
      _target="$_max"
    fi
  fi
  # Clamp to a sane PCIe generation range (defensive).
  if ! (( _target >= 1 && _target <= 6 )) 2>/dev/null; then
    jlog "$GUEST_GPU_BDF: detected target '$_target' out of range; defaulting to Gen5"
    _target=5
  fi
  # --- Bounded descent: set LnkCtl2[3:0] = gen and retrain from _target down
  # to 1, accepting the highest gen the link actually negotiates at. This
  # generalizes the old one-step fallback: a Gen5 target that only retrains at
  # Gen4 will also try Gen3 if Gen4 also fails, etc. Bounded by the gen range
  # (<= 6 iterations) so it can never loop forever, and Gen1 is guaranteed
  # (the pre-FLR downtrain proved the link works at Gen1).
  _best=0
  for (( _g = _target; _g >= 1; _g-- )); do
    _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
    if [[ -n "$_ctl2" ]]; then
      _saved_hi="${_ctl2:0:3}"
      setpci -s "$_upstream" 88.w="${_saved_hi}$(printf '%x' "$_g")" 2>/dev/null || true
      jlog "$GUEST_GPU_BDF: LnkCtl2 target set to Gen$_g (${_saved_hi}$(printf '%x' "$_g"))"
    fi
    _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
    if [[ -n "$_ctl" ]]; then
      setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
    fi
    jlog "$GUEST_GPU_BDF: forced link retrain to Gen$_g"
    # Poll for the link to re-negotiate at this gen (up to ~0.6s).
    _neg_gen=""
    for _p in $(seq 1 6); do
      sleep 0.1
      _neg_gen="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
      if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
        break
      fi
    done
    _width="$(_port_link_width "$_upstream" 2>/dev/null || true)"
    if [[ -n "$_neg_gen" ]]; then
      jlog "$GUEST_GPU_BDF: link negotiated at Gen$_neg_gen x${_width:-?} (target Gen$_g)"
    fi
    if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
      _best="$_neg_gen"
      jlog "$GUEST_GPU_BDF: restore OK — link back at Gen$_neg_gen x${_width:-?}"
      break
    fi
    if (( _g > 1 )); then
      jlog "$GUEST_GPU_BDF: WARN link below Gen$_g (got Gen${_neg_gen:-?}); descending to Gen$((_g - 1))"
    fi
  done
  # Final diagnostics (with width) so a degraded link is easy to spot.
  if (( _best == 0 )) 2>/dev/null; then
    jlog "$GUEST_GPU_BDF: WARN link restore did not settle at any gen >= 1 (cap=Gen${_FLR_DETECTED_CAP:-?}, pre=Gen${_FLR_DETECTED_CUR:-?} x${_FLR_DETECTED_WIDTH:-?}); possible hardware/signal-integrity issue"
  elif (( _best < _target )) 2>/dev/null; then
    jlog "$GUEST_GPU_BDF: WARN link restore settled at Gen$_best x${_width:-?} (wanted Gen$_target, cap=Gen${_FLR_DETECTED_CAP:-?}); possible hardware/signal-integrity issue — link up but degraded"
  fi
  # GPU-endpoint alive-check: the LINK may be back at a good gen while the GPU
  # itself is still wedged. Catch that (non-fatal; the display-wedge clear
  # already happened, but a host reboot may be needed).
  if ! _gpu_alive; then
    jlog "$GUEST_GPU_BDF: WARN GPU endpoint not alive after FLR restore (vendor=0xffff or config all-ff); link may be up but the GPU is still wedged — a host reboot may be needed"
  fi
  return 0
}

# Soft FLR: reset the GPU's display engine without dropping the PCIe link.
# On the RX 9070 family / RDNA4, the FLR drops the link and the on-card switch
# fails to retrain it. The pre-FLR Gen1 downtrain makes the retrain reliable
# (Gen1 retrains fast and succeeds), then _post_flr_restore_target restores the
# link to the hardware's actual max (Gen5 on Gen5 boards, Gen4 on slower
# slots/mobos) with a degraded-link fallback. Gated to the RX 9070 family.
do_flr() {
  local _sys="/sys/bus/pci/devices/$GUEST_GPU_BDF"
  if [[ ! -w "$_sys/reset" ]]; then
    jlog "$GUEST_GPU_BDF: reset sysfs not writable; cannot FLR after guest reboot"
    return 1
  fi
  # Reset the hardware-detection stash so a previous run can't leak in.
  _FLR_DETECTED_CAP=""
  _FLR_DETECTED_CUR=""
  _FLR_DETECTED_WIDTH=""
  _FLR_SAVED_CTL2=""
  _FLR_SAVED_TARGET=""
  _FLR_SKU_NAME=""
  # RX 9070 family only: pre-FLR Gen1 downtrain for a reliable post-FLR retrain.
  if _is_rx9070; then
    _pre_flr_gen1_downtrain
  else
    jlog "$GUEST_GPU_BDF: not RX 9070, skipping pre-FLR Gen1 downtrain"
  fi
  # The soft FLR.
  echo 1 >"$_sys/reset" 2>/dev/null || true
  jlog "$GUEST_GPU_BDF: soft FLR applied after guest reboot (display wedge clear)"
  # RX 9070 family only: wait for link + adaptively restore the target gen.
  if _is_rx9070; then
    _post_flr_restore_target
  fi
}

# Check if a libvirt domain has the guest GPU BDF in its PCI hostdev list.
# virsh dumpxml stores PCI addresses as separate attributes
# (domain='0x0000' bus='0x0e' slot='0x00' function='0x0'), NOT as the combined
# BDF string '0000:0e:00.0'. So we must parse the address attributes out of the
# XML and reconstruct the BDF, then compare. (Mirrors extract_hostdev_bdfs in
# the libvirt hook script, which is already proven to handle this format.)
domain_has_gpu() {
  local _dom="$1" _xml _bdfs
  _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
  if [[ -z "$_xml" ]]; then
    jlog "domain_has_gpu: virsh dumpxml '$_dom' returned EMPTY (domain name may still be quoted or domain not found)"
    return 1
  fi
  _bdfs="$(printf '%s' "$_xml" | awk '
    /<hostdev/ { in_hostdev=1; is_pci=0 }
    in_hostdev && /type=.pci./ { is_pci=1 }
    in_hostdev && is_pci && /<address/ {
      line=$0; dom=""; bus=""; slot=""; fn=""
      if (match(line, /domain=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^domain=./, "", s); sub(/^0x/, "", s); dom=s
      }
      if (match(line, /bus=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^bus=./, "", s); sub(/^0x/, "", s); bus=s
      }
      if (match(line, /slot=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^slot=./, "", s); sub(/^0x/, "", s); slot=s
      }
      if (match(line, /function=.0x[0-9a-fA-F]+/)) {
        s=substr(line, RSTART, RLENGTH); sub(/^function=./, "", s); sub(/^0x/, "", s); fn=s
      }
      if (dom != "" && bus != "" && slot != "" && fn != "") {
        while (length(dom) < 4) dom = "0" dom
        while (length(bus) < 2) bus = "0" bus
        while (length(slot) < 2) slot = "0" slot
        printf "%s:%s:%s.%s\n", dom, bus, slot, fn
      }
    }
    /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
  ')"
  if [[ -z "$_bdfs" ]]; then
    jlog "domain_has_gpu: parsed 0 PCI BDFs from '$_dom' XML (no PCI hostdevs?)"
    return 1
  fi
  jlog "domain_has_gpu: domain='$_dom' parsed BDFs='$_bdfs' looking_for='$GUEST_GPU_BDF'"
  grep -Fixq "$GUEST_GPU_BDF" <<<"$_bdfs" 2>/dev/null
}

jlog "vfio-reboot-flr monitor started (watching for guest reboot of domains with $GUEST_GPU_BDF)"

# Main loop: watch ALL libvirt domains for ALL event types. When a Rebooted
# lifecycle event fires for a domain that has the guest GPU, apply a soft FLR.
# NOTE: `virsh event --all --event lifecycle` is INVALID (--all and --event are
# mutually exclusive). Use `--all --loop` (wait for all event types on all
# domains, loop) and filter for 'reboot' + lifecycle in the output parser.
# virsh event --all --loop keeps running and prints events as they happen.
# We wrap it in a timeout + outer loop so it reconnects if virsh exits.
while true; do
  if ! command -v virsh >/dev/null 2>&1; then
    sleep 60
    continue
  fi
  timeout 86400 virsh -c qemu:///system event --all --loop 2>/dev/null | while IFS= read -r _line; do
    # virsh event --all output: event '<type>' for domain '<name>'[: <detail>]
    # NOTE: virsh wraps the domain name in SINGLE QUOTES, and 'reboot' is a
    # SEPARATE event type (not a lifecycle sub-event) with NO colon after the
    # quoted name:
    #   event 'reboot' for domain 'win11'
    # vs lifecycle which has a colon + detail:
    #   event 'lifecycle' for domain 'win11': Rebooted
    # The sed must (a) handle both formats (colon optional), and (b) STRIP the
    # single quotes from the domain name, or virsh dumpxml ''win11'' fails and
    # domain_has_gpu silently returns false (the "no guest GPU" false negative).
    _dom="$(printf '%s' "$_line" | sed -n "s/.*for domain '\([^:']*\).*/\1/p" 2>/dev/null || true)"
    # Fallback: if the quote-aware sed did not match (unquoted domain name), try
    # the original colon-optional parser.
    if [[ -z "$_dom" ]]; then
      _dom="$(printf '%s' "$_line" | sed -n 's/.*for domain \([^:]*\).*/\1/p' 2>/dev/null || true)"
    fi
    [[ -n "$_dom" ]] || continue
    # Only act on reboot events (case-insensitive). Matches both the 'reboot'
    # event type AND the 'Rebooted' lifecycle detail.
    if printf '%s' "$_line" | grep -qi 'reboot'; then
      jlog "reboot event received for domain '$_dom' (raw line: $_line)"
      if domain_has_gpu "$_dom"; then
        jlog "$GUEST_GPU_BDF: reboot event for domain $_dom (has guest GPU); applying soft FLR to clear display wedge"
        do_flr
      else
        jlog "reboot event for domain $_dom (no guest GPU); skipping FLR"
      fi
    fi
  done
  sleep 10  # reconnect after virsh event exits / times out
  jlog "vfio-reboot-flr monitor reconnecting (virsh event exited)"
done
EOF

  write_file_atomic "$REBOOT_FLR_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=vfio reboot FLR monitor (clears GPU display wedge on guest warm reboot)
After=libvirtd.service virtqemud.service libvirtd.socket virtqemud.socket

[Service]
Type=simple
ExecStart=$REBOOT_FLR_SCRIPT
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
EOF

  run systemctl daemon-reload 2>/dev/null || true
  run systemctl enable vfio-reboot-flr.service 2>/dev/null || true
  run systemctl start vfio-reboot-flr.service 2>/dev/null || true
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Installed reboot-FLR monitor: $(_link "$REBOOT_FLR_SCRIPT")"
    note "    service: $(_link "$REBOOT_FLR_UNIT")"
  else
    say "  ✔ Installed reboot-FLR monitor: $REBOOT_FLR_SCRIPT"
    note "    service: $REBOOT_FLR_UNIT"
  fi
  note "On guest warm reboot (on_reboot=restart), the monitor does a soft FLR on the GPU"
  note "to clear the display wedge so OVMF can re-POST without a host reboot."
}

# Install the park-keepalive monitor: a systemd service (dynamic binding only)
# that periodically checks whether the guest GPU, PARKED on vfio-pci between
# VM sessions (VFIO_DYNAMIC_REBIND_HOST=0, the default), is still alive. If it
# has died (RX 9070 / RDNA4 reset bug — config space reads all 0xff / vendor
# 0xffff) it proactively runs the same remove+rescan bus recovery used at
# --release time, so a card that dies while sitting parked (not right at VM
# stop) is recovered BEFORE the next VM start instead of failing that VM
# start. This is the PROACTIVE complement to the reactive release-time zombie
# recovery already in the bind script.
#
# INSTANT ON: unlike stealth/perf VM tuning, this is installed and enabled
# automatically whenever dynamic binding is installed — there is no prompt.
# Disable it by setting VFIO_DYNAMIC_PARK_KEEPALIVE=0 in $CONF_FILE (the
# running service re-reads that key every poll interval, so no restart is
# required for the change to take effect). Removed by --install-early-binding
# and by --reset.
install_park_keepalive_monitor() {
  if ! have_cmd systemctl; then
    note "systemctl not available; skipping park-keepalive monitor installation."
    return 0
  fi

  if (( ! DRY_RUN )); then
    mkdir -p "$(dirname "$PARK_KEEPALIVE_SCRIPT")" "$(dirname "$PARK_KEEPALIVE_UNIT")" \
             "$(dirname "$PARK_KEEPALIVE_RESUME_HOOK")" "$(dirname "$PARK_KEEPALIVE_UDEV_RULE")" \
             "$(dirname "$PARK_KEEPALIVE_STATE_FILE")"
  fi

  backup_file "$PARK_KEEPALIVE_SCRIPT"
  backup_file "$PARK_KEEPALIVE_UNIT"

  write_file_atomic "$PARK_KEEPALIVE_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
# NOTE: deliberately no `-e` — every sysfs write / recovery step below checks
# its own exit status; failures are expected sometimes (e.g. a still-dead
# card) and must not abort the whole monitor process.
set -uo pipefail

# Managed by vfio.sh — park-keepalive monitor for dynamic GPU binding.
# Periodically checks whether the guest GPU, parked on vfio-pci between VM
# sessions, is still alive; proactively recovers it (remove+rescan) if it has
# died (RX 9070 / RDNA4 reset bug) so the NEXT VM start does not hit a dead
# card. PROACTIVE complement to the reactive --release-time zombie recovery.
# Also serves as the --once single-pass check invoked by the udev rule and by
# the post-resume (suspend/hibernate) systemd-sleep hook — all three trigger
# paths share this same logic.
# Removed by: sudo vfio.sh --reset  (or sudo vfio.sh --install-early-binding)

CONF_FILE="/etc/vfio-gpu-passthrough.conf"
STATE_FILE="/var/lib/vfio-dynamic/park-keepalive.state"

jlog() { command -v logger >/dev/null 2>&1 && logger -t vfio-park-keepalive -- "$*" 2>/dev/null || true; }

[[ -f "$CONF_FILE" ]] || { jlog "missing $CONF_FILE; exiting"; exit 0; }

# Read a single key out of $CONF_FILE without sourcing the whole file (the
# conf is re-read every poll iteration so VFIO_DYNAMIC_PARK_KEEPALIVE / the
# interval / GUEST_GPU_BDF can be changed live without restarting the unit).
_conf_get() {
  local _key="$1"
  awk -F= -v k="$_key" '$1==k{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true
}

# Same liveness test as the bind script's _pci_dev_alive: config space
# readable and not all 0xff, vendor sysfs not 0xffff. Duplicated here (not
# sourced) because each generated helper script is standalone.
_pci_dev_alive() {
  local _bdf="$1" _sys _vendor _cfg
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  _vendor="$(cat "$_sys/vendor" 2>/dev/null || echo "")"
  [[ -n "$_vendor" ]] || return 1
  [[ "$_vendor" != "0xffff" ]] || return 1
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d " \n")"
  [[ -n "$_cfg" ]] || return 1
  [[ "$_cfg" != "ffffffff" ]] || return 1
  return 0
}

# RX 9070 family / RDNA4 device ID. Gates the PCIe Gen1 downtrain/adaptive-
# restore wrapping below (see _pre_reset_gen1_downtrain) to this specific card
# family only. Duplicated from the bind script (each generated helper script
# is standalone, not sourced).
_RX9070_DEVICE_ID="7550"

_is_rx9070() {
  local _bdf="$1" _sys _cfg _vendor _device
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  _cfg="$(head -c 4 "$_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  [[ -n "$_cfg" ]] || return 1
  _vendor="${_cfg:2:2}${_cfg:0:2}"
  _device="${_cfg:6:2}${_cfg:4:2}"
  [[ "${_vendor,,}" == "1002" ]] || return 1
  [[ "${_device,,}" == "$_RX9070_DEVICE_ID" ]]
}

_setpci_word() {
  local _bdf="$1" _off="$2" _v
  _v="$(setpci -s "$_bdf" "$_off" 2>/dev/null || true)"
  [[ -n "$_v" ]] || return 1
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  [[ "$_v" =~ ^[0-9a-fA-F]+$ ]] || return 1
  while (( ${#_v} < 4 )); do _v="0$_v"; done
  printf '%s\n' "${_v,,}"
}

_speed_to_gen() {
  local _s="${1:-}" _n
  [[ -n "$_s" ]] || return 1
  _n="$(printf '%s' "$_s" | tr -cd '0-9.')"
  [[ -n "$_n" ]] || return 1
  case "$_n" in
    2.5) echo 1 ;;
    5|5.0) echo 2 ;;
    8|8.0) echo 3 ;;
    16|16.0) echo 4 ;;
    32|32.0) echo 5 ;;
    64|64.0) echo 6 ;;
    *) return 1 ;;
  esac
  return 0
}

_port_speed_gen() {
  local _bdf="$1" _attr="$2" _f _v
  _f="/sys/bus/pci/devices/$_bdf/$_attr"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null)" || _v=""
  [[ -n "$_v" ]] || return 1
  _speed_to_gen "$_v"
}

_port_link_width() {
  local _bdf="$1" _f _v
  _f="/sys/bus/pci/devices/$_bdf/current_link_width"
  [[ -r "$_f" ]] || return 1
  _v="$(cat "$_f" 2>/dev/null || true)"
  _v="$(printf '%s' "$_v" | tr -d '[:space:]')"
  [[ -n "$_v" ]] || return 1
  printf '%s\n' "$_v"
}

# Primary: walk sysfs (the device is a child of its upstream bridge). Fallback:
# if the device's OWN sysfs entry is missing entirely (fell off the bus --
# exactly the case _pci_bus_rescan_only needs this for), resolve the upstream
# bridge via its pci_bus/<domain:bus> subdirectory instead, which represents
# the bus topology independent of whether any downstream device is currently
# enumerated on it.
_gpu_upstream_port() {
  local _gpu="$1" _parent_dir _upstream _dom _bus _p
  [[ -n "$_gpu" ]] || return 1
  _parent_dir="$(ls -d /sys/bus/pci/devices/*/"$_gpu" 2>/dev/null | head -1)"
  if [[ -n "$_parent_dir" ]]; then
    _upstream="$(basename "$(dirname "$_parent_dir")")"
    if [[ -n "$_upstream" ]]; then
      printf '%s\n' "$_upstream"
      return 0
    fi
  fi
  _dom="${_gpu:0:4}"
  _bus="${_gpu:5:2}"
  [[ -n "$_dom" && -n "$_bus" ]] || return 1
  for _p in /sys/bus/pci/devices/*/pci_bus/"${_dom}:${_bus}"; do
    [[ -d "$_p" ]] || continue
    basename "$(dirname "$(dirname "$_p")")"
    return 0
  done
  return 1
}

# Pre-reset Gen1 downtrain, reused from the reboot-FLR monitor's proven fix for
# the SAME underlying issue on this card family: the on-card PCIe switch's
# post-reset link retrain at its max gen (Gen5) can fail, but forcing the
# target to Gen1 BEFORE the reset/remove makes the retrain reliable. Applied
# here to park-keepalive's remove+rescan / rescan-only recovery. Callers gate
# this to the RX 9070 family via _is_rx9070 first (except the fully-missing-
# directory rescan-only recovery, where _is_rx9070 cannot read the device's own
# config space and this is attempted unconditionally instead -- see
# _pci_bus_rescan_only).
_pre_reset_gen1_downtrain() {
  local _bdf="$1" _upstream _ctl2 _ctl _sta _i
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  if [[ -z "$_upstream" ]]; then
    jlog "$_bdf: pre-reset Gen1 downtrain skipped (could not find upstream port)"
    return 1
  fi
  if ! command -v setpci >/dev/null 2>&1; then
    jlog "$_bdf: pre-reset Gen1 downtrain skipped (setpci not installed)"
    return 1
  fi
  _RESET_DETECTED_CAP="$(_port_speed_gen "$_upstream" max_link_speed 2>/dev/null || true)"
  _RESET_DETECTED_CUR="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
  _RESET_DETECTED_WIDTH="$(_port_link_width "$_upstream" 2>/dev/null || true)"
  jlog "$_bdf: pre-reset Gen1 downtrain on upstream $_upstream (cap=Gen${_RESET_DETECTED_CAP:-?} cur=Gen${_RESET_DETECTED_CUR:-?} width=x${_RESET_DETECTED_WIDTH:-?})"
  _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
  if [[ -z "$_ctl2" ]]; then
    jlog "$_bdf: pre-reset downtrain aborted (could not read LnkCtl2 from $_upstream)"
    return 1
  fi
  _RESET_SAVED_TARGET="$(printf '%d' "0x${_ctl2:3:1}" 2>/dev/null)" || true
  local _saved_hi="${_ctl2:0:3}"
  local _gen1_ctl2="${_saved_hi}1"
  setpci -s "$_upstream" 88.w="$_gen1_ctl2" 2>/dev/null || true
  jlog "$_bdf: LnkCtl2 set to $_gen1_ctl2 (was $_ctl2) — target Gen1"
  _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
  if [[ -n "$_ctl" ]]; then
    setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
  fi
  jlog "$_bdf: forced link retrain at Gen1 (LnkCtl bit 5 set)"
  for _i in $(seq 1 20); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$_bdf: link active at Gen1 after $(( _i * 100 ))ms"
      return 0
    fi
    sleep 0.1
  done
  jlog "$_bdf: WARN link did not come back at Gen1 within 2s (continuing anyway)"
  return 0
}

# Post-reset adaptive link restore (bounded descent). See
# _pre_reset_gen1_downtrain for the rationale; callers gate this to the RX 9070
# family via _is_rx9070 first, and must call _pre_reset_gen1_downtrain in the
# SAME recovery attempt first so the *_DETECTED_*/_RESET_SAVED_TARGET globals
# are fresh.
_post_reset_restore_link() {
  local _bdf="$1" _upstream _ctl _sta _i _target _neg_gen _g _ctl2 _width _p _best _saved_hi
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  [[ -n "$_upstream" ]] || return 1
  command -v setpci >/dev/null 2>&1 || return 1
  for _i in $(seq 1 50); do
    _sta="$(_setpci_word "$_upstream" 6A.w 2>/dev/null || true)"
    if [[ -n "$_sta" ]] && (( (0x$_sta & 0x2000) != 0 )); then
      jlog "$_bdf: link active after reset (waited $(( _i * 100 ))ms)"
      break
    fi
    sleep 0.1
  done
  local _cap="${_RESET_DETECTED_CAP:-}"
  local _cur="${_RESET_DETECTED_CUR:-}"
  local _sav="${_RESET_SAVED_TARGET:-}"
  if [[ -n "$_cap" && -n "$_cur" ]]; then
    if (( _cur < _cap )) 2>/dev/null; then
      _target="$_cur"
      jlog "$_bdf: link was running Gen$_cur < cap Gen$_cap; adapting restore to Gen$_cur"
    else
      _target="$_cap"
      jlog "$_bdf: restoring to detected link capability Gen$_cap"
    fi
  elif [[ -n "$_cap" ]]; then
    _target="$_cap"
  elif [[ -n "$_sav" ]]; then
    _target="$_sav"
  else
    _target=5
  fi
  local _max="${VFIO_REBOOT_FLR_MAX_GEN:-}"
  if [[ -n "$_max" ]] && (( _max >= 1 && _max <= 6 )) 2>/dev/null; then
    if (( _target > _max )) 2>/dev/null; then
      jlog "$_bdf: VFIO_REBOOT_FLR_MAX_GEN=$_max clamps restore target to Gen$_max"
      _target="$_max"
    fi
  fi
  if ! (( _target >= 1 && _target <= 6 )) 2>/dev/null; then
    _target=5
  fi
  _best=0
  for (( _g = _target; _g >= 1; _g-- )); do
    _ctl2="$(_setpci_word "$_upstream" 88.w 2>/dev/null || true)"
    if [[ -n "$_ctl2" ]]; then
      _saved_hi="${_ctl2:0:3}"
      setpci -s "$_upstream" 88.w="${_saved_hi}$(printf '%x' "$_g")" 2>/dev/null || true
    fi
    _ctl="$(_setpci_word "$_upstream" 68.w 2>/dev/null || true)"
    if [[ -n "$_ctl" ]]; then
      setpci -s "$_upstream" 68.w="$(printf '%04x' $(( 0x$_ctl | 0x0020 )))" 2>/dev/null || true
    fi
    jlog "$_bdf: forced link retrain to Gen$_g"
    _neg_gen=""
    for _p in $(seq 1 6); do
      sleep 0.1
      _neg_gen="$(_port_speed_gen "$_upstream" current_link_speed 2>/dev/null || true)"
      if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
        break
      fi
    done
    _width="$(_port_link_width "$_upstream" 2>/dev/null || true)"
    if [[ -n "$_neg_gen" ]] && (( _neg_gen >= _g )) 2>/dev/null; then
      _best="$_neg_gen"
      jlog "$_bdf: restore OK — link back at Gen$_neg_gen x${_width:-?}"
      break
    fi
    if (( _g > 1 )); then
      jlog "$_bdf: WARN link below Gen$_g (got Gen${_neg_gen:-?}); descending to Gen$((_g - 1))"
    fi
  done
  if (( _best == 0 )) 2>/dev/null; then
    jlog "$_bdf: WARN link restore did not settle at any gen >= 1 (cap=Gen${_RESET_DETECTED_CAP:-?}, pre=Gen${_RESET_DETECTED_CUR:-?} x${_RESET_DETECTED_WIDTH:-?}); possible hardware/signal-integrity issue"
  elif (( _best < _target )) 2>/dev/null; then
    jlog "$_bdf: WARN link restore settled at Gen$_best x${_width:-?} (wanted Gen$_target); link up but degraded"
  fi
  return 0
}

# Secondary Bus Reset (SBR) of the upstream PCIe switch port for $1 (the GPU).
# Pulses RST# on the upstream port's secondary bus (setpci Bridge Control
# register at offset 0x3E, bit 6 = 0x0040), hot-resetting the GPU AND every
# other device behind the same upstream port (e.g. the GPU's audio sibling).
# A HEAVIER reset than a plain remove+rescan: it resets more of the card's
# internal state (PSP/MC) and forces a full PCIe link retrain, which is what
# recovers an RX 9070 / RDNA4 that dropped off the bus on a force-kill VM
# (virsh destroy / BSOD) where the lighter remove+rescan fails.
#
# Wraps the SAME pre-reset Gen1 downtrain + post-reset adaptive link restore
# already proven for the park-keepalive remove+rescan / rescan-only paths (see
# _pre_reset_gen1_downtrain / _post_reset_restore_link): an SBR drops the PCIe
# link and it must retrain reliably (Gen1 first, then adapt back up). The
# upstream port is NOT itself reset by the SBR, so its LnkCtl2 Gen1 target set
# by _pre_reset_gen1_downtrain persists across the RST# pulse and the link
# retrains at Gen1 after de-assert. Resolves the upstream port via
# _gpu_upstream_port's pci_bus/<domain:bus> fallback, so this works even when
# the GPU's own sysfs entry is missing (the exact force-kill zombie state).
# Best-effort: returns 0 even if a setpci step fails (the caller proceeds to
# the rescan + bind; a failed SBR is no worse than no SBR).
# Duplicated from the bind script (each generated helper script is standalone).
_secondary_bus_reset() {
  local _bdf="$1" _upstream _brctl _brctl_set _brctl_clr
  [[ -n "$_bdf" ]] || return 1
  _upstream="$(_gpu_upstream_port "$_bdf" 2>/dev/null || true)"
  if [[ -z "$_upstream" ]]; then
    jlog "$_bdf: SBR skipped (could not find upstream port)"
    return 1
  fi
  if ! command -v setpci >/dev/null 2>&1; then
    jlog "$_bdf: SBR skipped (setpci not installed)"
    return 1
  fi
  # Pre-reset Gen1 downtrain (stashes detected cap/cur/width globals for the
  # matching _post_reset_restore_link call below).
  _pre_reset_gen1_downtrain "$_bdf"
  # Read the upstream port's Bridge Control register (offset 0x3E, 16-bit).
  _brctl="$(_setpci_word "$_upstream" 3E.w 2>/dev/null || true)"
  if [[ -z "$_brctl" ]]; then
    jlog "$_bdf: SBR aborted (could not read Bridge Control from $_upstream)"
    return 1
  fi
  # Assert Secondary Bus Reset (bit 6 = 0x0040): pulses RST# on the secondary
  # bus, hot-resetting the GPU and every device behind the same upstream port.
  _brctl_set="$(printf '%04x' $(( 0x$_brctl | 0x0040 )) )"
  setpci -s "$_upstream" 3E.w="$_brctl_set" 2>/dev/null || true
  jlog "$_bdf: SBR assert on $_upstream (BridgeCtl 0x$_brctl -> 0x$_brctl_set, bit6 RST# set)"
  # Hold reset: PCIe TPerst must be asserted >= 2ms; give a generous margin.
  sleep 0.05
  # De-assert SBR (clear bit 6 via AND ~0x0040 = 0xFFBF) so the link retrains.
  _brctl_clr="$(printf '%04x' $(( 0x$_brctl & 0xFFBF )) )"
  setpci -s "$_upstream" 3E.w="$_brctl_clr" 2>/dev/null || true
  jlog "$_bdf: SBR de-assert on $_upstream (BridgeCtl -> 0x$_brctl_clr, RST# cleared); link retraining"
  # Post-reset adaptive link restore (bounded descent back to detected cap).
  _post_reset_restore_link "$_bdf"
  jlog "$_bdf: SBR complete (upstream $_upstream reset, link restored)"
  return 0
}

# Same last-resort recovery as the bind script's _pci_dev_remove_rescan. RX
# 9070 family: wrapped with the SAME pre/post Gen1-downtrain and adaptive link
# restore proven for the guest-reboot FLR path, since a plain `rescan` has no
# mechanism of its own to force the PCIe link to retrain if it is already
# down when the card zombies. Two-phase graduated recovery (kept in sync with
# the bind script's copy): Phase 1 is the lighter remove+rescan; if that fails
# Phase 2 escalates to _secondary_bus_reset (RST# on the upstream port), the
# proven recovery for an RX 9070 / RDNA4 dropped off the bus by a force-kill VM
# (virsh destroy / BSOD). The card is already dead when Phase 2 runs.
_pci_dev_remove_rescan() {
  local _bdf="$1" _sys _rx9070=0
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  [[ -d "$_sys" ]] || return 1
  jlog "$_bdf: park-keepalive attempting remove+rescan recovery"
  if _is_rx9070 "$_bdf"; then
    _rx9070=1
    _pre_reset_gen1_downtrain "$_bdf"
  fi
  # Phase 1 (light): remove the device + rescan the bus to re-enumerate it.
  if [[ -w "$_sys/remove" ]]; then
    echo 1 >"$_sys/remove" 2>/dev/null || true
    sleep 1
  fi
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  sleep 1
  if [[ -d "$_sys" ]]; then
    if (( _rx9070 )); then
      _post_reset_restore_link "$_bdf"
    fi
    echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
    echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
    sleep 0.3
    if _pci_dev_alive "$_bdf"; then
      jlog "$_bdf: park-keepalive recovered device after remove+rescan (alive)"
      return 0
    fi
  fi
  # Phase 2 (heavy): the lighter remove+rescan did not recover the device
  # (either it never reappeared, or it reappeared as a zombie with unreadable
  # config space). Escalate to a Secondary Bus Reset of the upstream PCIe
  # switch port -- RST# hot-resets the GPU (and its audio sibling) and forces a
  # full link retrain, the proven recovery for an RX 9070 / RDNA4 dropped off
  # the bus by a force-kill VM (virsh destroy / BSOD). The card is already dead
  # here, so there is no healthy card to harm; _secondary_bus_reset resolves the
  # upstream port via the pci_bus fallback even when the GPU's own sysfs entry
  # is gone. After SBR, rescan to re-enumerate then bind vfio-pci.
  jlog "$_bdf: park-keepalive did not reappear after rescan (or reappeared dead); escalating to Secondary Bus Reset"
  _secondary_bus_reset "$_bdf" || true
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  jlog "$_bdf: park-keepalive PCI bus rescan triggered after SBR"
  sleep 1
  [[ -d "$_sys" ]] || { jlog "$_bdf: park-keepalive did not reappear after SBR+rescan; needs host reboot"; return 1; }
  echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
  echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
  sleep 0.3
  if _pci_dev_alive "$_bdf"; then
    jlog "$_bdf: park-keepalive recovered device after SBR+rescan (alive)"
    return 0
  fi
  jlog "$_bdf: park-keepalive still dead after SBR+rescan; needs host reboot"
  return 1
}

# Recovery for the case where the guest GPU's sysfs directory is entirely
# missing (not just a zombie with unreadable config space) — i.e. it fell
# completely off the PCI bus. There is nothing to "remove" in this case, so
# unlike _pci_dev_remove_rescan this only triggers a bus rescan and then
# checks whether the device reappeared, binding it to vfio-pci if so. This
# state has been observed on RX 9070 / RDNA4 hardware after a prior
# remove+rescan attempt (the GPU function stays gone while its audio sibling
# comes back) and is NOT guaranteed to recover via rescan alone — a host
# reboot may still be required — but retrying costs nothing and this must not
# be silently skipped forever (see _run_once's directory-missing branch).
# Also wrapped with the pre/post Gen1-downtrain (see _gpu_upstream_port's
# pci_bus/<domain:bus> fallback, which resolves the upstream port even though
# the device's own sysfs entry -- and therefore _is_rx9070's config-space
# read -- is unavailable here). Attempted UNCONDITIONALLY rather than gated on
# _is_rx9070: the device is already missing from the bus in this branch, so
# there is no healthy card to harm, and a non-RX-9070 board simply gets a
# harmless Gen1-then-adaptive-restore retrain attempt on its own already-dead
# slot before the plain rescan.
_pci_bus_rescan_only() {
  local _bdf="$1" _sys
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  jlog "$_bdf: sysfs entry missing (fell off the bus); attempting bus rescan recovery"
  _pre_reset_gen1_downtrain "$_bdf"
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  sleep 1
  if [[ -d "$_sys" ]]; then
    _post_reset_restore_link "$_bdf"
    echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
    echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
    sleep 0.3
    if _pci_dev_alive "$_bdf"; then
      jlog "$_bdf: park-keepalive recovered device after rescan (alive)"
      return 0
    fi
  fi
  # Escalation: plain rescan did not bring the device back. SBR the upstream
  # port (RST# pulse) to force a full hot-reset + link retrain of everything
  # behind the port, then rescan to re-enumerate. Proven heavier recovery for
  # the RX 9070 / RDNA4 force-kill zombie where plain rescan fails (the device
  # is already fully off the bus here, so there is no healthy card to harm).
  jlog "$_bdf: park-keepalive did not reappear after plain rescan; escalating to Secondary Bus Reset"
  _secondary_bus_reset "$_bdf" || true
  echo 1 >/sys/bus/pci/rescan 2>/dev/null || true
  jlog "$_bdf: park-keepalive PCI bus rescan triggered after SBR"
  sleep 1
  [[ -d "$_sys" ]] || { jlog "$_bdf: park-keepalive still did not reappear after SBR+rescan; needs host reboot"; return 1; }
  echo vfio-pci >"$_sys/driver_override" 2>/dev/null || true
  echo "$_bdf" >/sys/bus/pci/drivers/vfio-pci/bind 2>/dev/null || true
  sleep 0.3
  if _pci_dev_alive "$_bdf"; then
    jlog "$_bdf: park-keepalive recovered device after SBR+rescan (alive)"
    return 0
  fi
  jlog "$_bdf: park-keepalive reappeared after SBR+rescan but is not alive/bound correctly; needs host reboot"
  return 1
}

# Returns:
#   0 = a RUNNING libvirt domain owns the BDF (never touch it)
#   1 = virsh connected fine and confirms no running domain owns it
#   2 = cannot determine (virsh missing, OR virsh is installed but failed to
#       connect — e.g. libvirtd itself crashed). Callers must fail safe by
#       default, but see _vfio_device_in_use for the hard-kill-without-
#       release-event fallback used when this returns 2.
_gpu_owned_by_running_domain() {
  local _bdf="$1" _dom _xml _bdfs _list_out _list_rc
  command -v virsh >/dev/null 2>&1 || return 2
  _list_out="$(virsh -c qemu:///system list --name 2>/dev/null)"
  _list_rc=$?
  (( _list_rc == 0 )) || return 2
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    _bdfs="$(printf '%s' "$_xml" | awk '
      /<hostdev/ { in_hostdev=1; is_pci=0 }
      in_hostdev && /type=.pci./ { is_pci=1 }
      in_hostdev && is_pci && /<address/ {
        line=$0; dom=""; bus=""; slot=""; fn=""
        if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
        if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
        if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
        if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
        if (dom != "" && bus != "" && slot != "" && fn != "") {
          while (length(dom) < 4) dom = "0" dom
          while (length(bus) < 2) bus = "0" bus
          while (length(slot) < 2) slot = "0" slot
          printf "%s:%s:%s.%s\n", dom, bus, slot, fn
        }
      }
      /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
    ')"
    if grep -Fixq "$_bdf" <<<"$_bdfs" 2>/dev/null; then
      return 0
    fi
  done <<<"$_list_out"
  return 1
}

# Returns:
#   0 = some process holds the VFIO device node for this BDF open (in use)
#   1 = confirmed NOT in use (device node found, nothing has it open)
#   2 = inconclusive (no /dev/vfio/<iommu_group> node, or /proc unreadable)
# HARD-KILL WATCHDOG FALLBACK: used only when _gpu_owned_by_running_domain
# returns 2 (libvirt unreachable, e.g. libvirtd itself crashed). Lets a true
# "VM died without a clean release event because libvirt is down" scenario
# still be recovered, instead of only ever failing safe until libvirt comes
# back. Mirrors the /proc/<pid>/fd scan already used elsewhere in vfio.sh for
# Wayland-compositor detection.
_vfio_device_in_use() {
  local _bdf="$1" _grp_link _grp _node _pid _fd _tgt
  _grp_link="/sys/bus/pci/devices/$_bdf/iommu_group"
  [[ -e "$_grp_link" ]] || return 2
  _grp="$(basename "$(readlink -f "$_grp_link" 2>/dev/null)" 2>/dev/null || true)"
  [[ -n "$_grp" ]] || return 2
  _node="/dev/vfio/$_grp"
  [[ -e "$_node" ]] || return 1
  [[ -d /proc ]] || return 2
  for _pid in /proc/[0-9]*; do
    [[ -d "$_pid/fd" ]] || continue
    for _fd in "$_pid"/fd/*; do
      [[ -L "$_fd" ]] || continue
      _tgt="$(readlink "$_fd" 2>/dev/null || true)"
      if [[ "$_tgt" == "$_node" ]]; then
        return 0
      fi
    done
  done
  return 1
}

# Consecutive-failure streak, persisted in $STATE_FILE so backoff + the
# one-time notify threshold work correctly across daemon restarts AND
# one-shot invocations (udev rule / resume hook), which are separate processes.
_pk_read_streak() {
  local _v
  [[ -f "$STATE_FILE" ]] || { echo 0; return 0; }
  _v="$(head -n1 "$STATE_FILE" 2>/dev/null || echo 0)"
  [[ "$_v" =~ ^[0-9]+$ ]] && echo "$_v" || echo 0
}
_pk_write_streak() {
  mkdir -p "$(dirname "$STATE_FILE")" 2>/dev/null || true
  printf '%s\n' "$1" >"$STATE_FILE" 2>/dev/null || true
}
_pk_reset_streak() {
  [[ "$(_pk_read_streak)" == "0" ]] || _pk_write_streak 0
  return 0
}
_pk_bump_streak() {
  local _n
  _n=$(( $(_pk_read_streak) + 1 ))
  _pk_write_streak "$_n"
  printf '%s\n' "$_n"
}

# Best-effort desktop notification (never fatal if unavailable). Broadcasts to
# every active desktop session under /run/user/<uid> rather than guessing a
# single "the" desktop user, since this monitor runs as a system service.
_notify_desktop() {
  local _title="$1" _body="$2" _rt _uid _user
  command -v notify-send >/dev/null 2>&1 || return 0
  command -v runuser >/dev/null 2>&1 || return 0
  for _rt in /run/user/*; do
    [[ -d "$_rt" ]] || continue
    _uid="$(basename "$_rt")"
    [[ "$_uid" =~ ^[0-9]+$ ]] || continue
    _user="$(getent passwd "$_uid" 2>/dev/null | cut -d: -f1)"
    [[ -n "$_user" ]] || continue
    runuser -u "$_user" -- env XDG_RUNTIME_DIR="$_rt" DBUS_SESSION_BUS_ADDRESS="unix:path=$_rt/bus" \
      notify-send -u critical "$_title" "$_body" >/dev/null 2>&1 || true
  done
  return 0
}

_warned_no_virsh=0
NEXT_SLEEP=10

# One full check-and-recover pass. Shared by the daemon loop below AND the
# --once entry point (udev rule / post-resume hook), so all three trigger
# paths get identical safety gating and recovery logic.
_run_once() {
  local _enabled _interval _max_fails _backoff_max _notify_enabled
  local _binding_mode _rebind_host _guest_gpu _drv _owned_rc _fb_rc _streak
  local _sys_dir_present

  _enabled="$(_conf_get VFIO_DYNAMIC_PARK_KEEPALIVE)"
  _enabled="${_enabled:-1}"
  _interval="$(_conf_get VFIO_DYNAMIC_PARK_KEEPALIVE_INTERVAL)"
  if [[ ! "$_interval" =~ ^[0-9]+$ ]] || (( _interval < 5 )); then
    _interval=10
  fi
  _max_fails="$(_conf_get VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS)"
  [[ "$_max_fails" =~ ^[0-9]+$ ]] && (( _max_fails >= 1 )) || _max_fails=5
  _backoff_max="$(_conf_get VFIO_DYNAMIC_PARK_KEEPALIVE_BACKOFF_MAX)"
  [[ "$_backoff_max" =~ ^[0-9]+$ ]] && (( _backoff_max >= _interval )) || _backoff_max=300
  _notify_enabled="$(_conf_get VFIO_DYNAMIC_PARK_KEEPALIVE_NOTIFY)"
  _notify_enabled="${_notify_enabled:-1}"
  _binding_mode="$(_conf_get VFIO_BINDING_MODE)"
  _rebind_host="$(_conf_get VFIO_DYNAMIC_REBIND_HOST)"
  _guest_gpu="$(_conf_get GUEST_GPU_BDF)"

  NEXT_SLEEP="$_interval"

  if [[ "$_enabled" != "1" ]]; then
    return 0
  fi
  if [[ "${_binding_mode,,}" != "dynamic" ]]; then
    return 0
  fi
  if [[ "${_rebind_host:-0}" == "1" ]]; then
    # Card is meant to go back to the host driver on VM stop, not stay parked
    # on vfio-pci — nothing for the park-keepalive to watch.
    return 0
  fi
  if [[ -z "$_guest_gpu" ]]; then
    return 0
  fi

  # NOTE: deliberately NOT gated on "sysfs directory exists" here — a fully
  # missing directory (device fell entirely off the bus, worse than a zombie
  # with unreadable config space) must still reach the recovery logic below
  # instead of being silently skipped forever. Ownership determination itself
  # never depends on sysfs (virsh reads libvirt's view of running domains +
  # their defined XML, not sysfs), so it is safe to check ownership before we
  # even know whether the device still exists on the bus at all.
  _owned_rc=0
  _gpu_owned_by_running_domain "$_guest_gpu" || _owned_rc=$?
  if (( _owned_rc == 0 )); then
    # A running VM legitimately owns this device right now; never touch it.
    return 0
  elif (( _owned_rc == 2 )); then
    # virsh missing OR unreachable (e.g. libvirtd itself crashed). Fall back
    # to a direct "does any process hold the VFIO device open" check instead
    # of always failing safe, so a true hard-kill-without-release-event (VM
    # died AND libvirt is down) can still be recovered.
    _fb_rc=0
    _vfio_device_in_use "$_guest_gpu" || _fb_rc=$?
    if (( _fb_rc == 0 )); then
      if (( ! _warned_no_virsh )); then
        jlog "virsh unreachable; /dev/vfio in-use fallback says device IS in use, skipping"
        _warned_no_virsh=1
      fi
      return 0
    elif (( _fb_rc == 2 )); then
      if (( ! _warned_no_virsh )); then
        jlog "virsh unreachable and /dev/vfio in-use fallback is inconclusive; failing safe, skipping recovery checks"
        _warned_no_virsh=1
      fi
      return 0
    fi
    jlog "virsh unreachable but /dev/vfio in-use fallback confirms device is idle; proceeding (hard-kill-without-release watchdog)"
  fi

  _sys_dir_present=0
  [[ -d "/sys/bus/pci/devices/$_guest_gpu" ]] && _sys_dir_present=1

  if (( _sys_dir_present )); then
    _drv=""
    if [[ -L "/sys/bus/pci/devices/$_guest_gpu/driver" ]]; then
      _drv="$(basename "$(readlink "/sys/bus/pci/devices/$_guest_gpu/driver")" 2>/dev/null || echo "")"
    fi
    if [[ "$_drv" != "vfio-pci" ]]; then
      # Not currently parked on vfio-pci (e.g. still on amdgpu pre-first-bind).
      return 0
    fi

    # Cheap prophylactic reassertion: guard against anything (udev, a power
    # daemon, resume from suspend) quietly flipping d3cold_allowed back on
    # while the card sits parked. Best-effort; never fatal.
    echo 0 >"/sys/bus/pci/devices/$_guest_gpu/d3cold_allowed" 2>/dev/null || true
    # Same for runtime PM: keep the parked card pinned in D0 (power/control=on)
    # so it cannot slip into D3hot between sessions. d3cold_allowed=0 alone does
    # NOT prevent D3hot, and a D3hot card wedges at the next qemu attach
    # ("Unable to power on device, stuck in D3" -> no OVMF logo, black until
    # the Windows driver re-inits). Reasserted every pass.
    echo on >"/sys/bus/pci/devices/$_guest_gpu/power/control" 2>/dev/null || true

    if _pci_dev_alive "$_guest_gpu"; then
      _pk_reset_streak
      return 0
    fi

    jlog "$_guest_gpu: zombie detected while parked (config space unreadable); attempting proactive remove+rescan recovery"
    if _pci_dev_remove_rescan "$_guest_gpu"; then
      jlog "$_guest_gpu: park-keepalive recovered parked device (alive again)"
      _pk_reset_streak
      return 0
    fi
  else
    # Sysfs directory is entirely missing — the device fell completely off
    # the bus (worse than a zombie with unreadable config space; observed on
    # RX 9070 / RDNA4 hardware after a prior remove+rescan where the GPU
    # function stays gone while its audio sibling comes back). There is
    # nothing to "remove" here, so try a plain bus rescan instead of silently
    # doing nothing forever.
    if _pci_bus_rescan_only "$_guest_gpu"; then
      _pk_reset_streak
      return 0
    fi
  fi

  jlog "$_guest_gpu: park-keepalive could not recover parked device; may need a host reboot"
  _streak="$(_pk_bump_streak)"
  if (( _streak >= _max_fails )); then
    # Back off instead of hammering remove+rescan on a card that needs a
    # host reboot; each failed attempt itself briefly perturbs the bus.
    local _backed_off=$(( _interval * _streak ))
    (( _backed_off > _backoff_max )) && _backed_off="$_backoff_max"
    NEXT_SLEEP="$_backed_off"
    if (( _streak == _max_fails )) && [[ "$_notify_enabled" == "1" ]]; then
      jlog "$_guest_gpu: $_streak consecutive recovery failures; sending one-time desktop notification and backing off to ${_backed_off}s"
      _notify_desktop "VFIO passthrough" "Guest GPU ($_guest_gpu) needs a host reboot: it has failed to recover $_streak times in a row while parked."
    fi
  fi
  return 0
}

if [[ "${1:-}" == "--once" ]]; then
  _run_once
  exit 0
fi

jlog "vfio-gpu-park-keepalive monitor started"
while true; do
  _run_once
  sleep "$NEXT_SLEEP"
done
EOF

  write_file_atomic "$PARK_KEEPALIVE_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=vfio GPU park-keepalive monitor (proactively recovers a parked guest GPU that dies between VM sessions)
After=libvirtd.service virtqemud.service libvirtd.socket virtqemud.socket

[Service]
Type=simple
ExecStart=$PARK_KEEPALIVE_SCRIPT
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
EOF

  # Oneshot check unit: shares all logic with the daemon via --once. Started
  # on-demand by the udev rule below (ENV{SYSTEMD_WANTS}); not enabled/started
  # here since it has no persistent state of its own.
  write_file_atomic "$PARK_KEEPALIVE_CHECK_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=vfio GPU park-keepalive one-shot check (triggered by udev)
After=libvirtd.service virtqemud.service libvirtd.socket virtqemud.socket

[Service]
Type=oneshot
ExecStart=$PARK_KEEPALIVE_SCRIPT --once
EOF

  # Post-resume (suspend/hibernate) hook: systemd-sleep calls every executable
  # in this directory with ($1=pre|post, $2=suspend|hibernate|...). We only
  # act on "post" so a fresh check runs immediately after resume instead of
  # waiting for the next poll interval (S3/S4 sleep is a common D3cold trigger).
  write_file_atomic "$PARK_KEEPALIVE_RESUME_HOOK" 0755 "root:root" <<EOF
#!/usr/bin/env bash
# Managed by vfio.sh — systemd-sleep hook for the park-keepalive monitor.
# Removed by: sudo vfio.sh --reset  (or sudo vfio.sh --install-early-binding)
case "\${1:-}" in
  post)
    [[ -x "$PARK_KEEPALIVE_SCRIPT" ]] && "$PARK_KEEPALIVE_SCRIPT" --once 2>/dev/null || true
    ;;
esac
exit 0
EOF

  # Best-effort supplementary udev trigger. CAVEAT (documented for the user
  # below too): the RX 9070 / RDNA4 zombie state does NOT emit a PCI "remove"
  # uevent (that is exactly the bug — the kernel does not know the device
  # died), so this only helps for state changes that DO emit uevents (driver
  # bind/unbind, our own remove+rescan reappearing). The poll + resume hook
  # remain the primary defenses; only write this when we know the guest BDF.
  local _pk_guest_gpu
  _pk_guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -n "$_pk_guest_gpu" ]]; then
    write_file_atomic "$PARK_KEEPALIVE_UDEV_RULE" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Best-effort supplementary trigger for the park-keepalive one-shot check.
# CAVEAT: the RX 9070 / RDNA4 zombie state does NOT emit a PCI "remove"
# uevent (that is exactly the bug: the kernel does not know the device
# died), so this rule only helps for state changes that DO emit uevents.
# The periodic poll (vfio-gpu-park-keepalive.service) and the post-resume
# hook ($PARK_KEEPALIVE_RESUME_HOOK) are the primary defenses.
SUBSYSTEM=="pci", KERNELS=="$_pk_guest_gpu", ACTION=="change", TAG+="systemd", ENV{SYSTEMD_WANTS}+="vfio-gpu-park-keepalive-check.service"
SUBSYSTEM=="pci", KERNELS=="$_pk_guest_gpu", ACTION=="bind", TAG+="systemd", ENV{SYSTEMD_WANTS}+="vfio-gpu-park-keepalive-check.service"
EOF
    if have_cmd udevadm; then
      run udevadm control --reload-rules 2>/dev/null || true
    fi
  else
    note "WARN: could not determine GUEST_GPU_BDF from $CONF_FILE; skipping the udev supplementary trigger (poll + resume hook are unaffected)."
  fi

  run systemctl daemon-reload 2>/dev/null || true
  run systemctl enable vfio-gpu-park-keepalive.service 2>/dev/null || true
  run systemctl start vfio-gpu-park-keepalive.service 2>/dev/null || true
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Installed park-keepalive monitor: $(_link "$PARK_KEEPALIVE_SCRIPT")"
    note "    service: $(_link "$PARK_KEEPALIVE_UNIT")"
    say "  ${C_GREEN}✔${C_RESET} Installed post-resume hook: $(_link "$PARK_KEEPALIVE_RESUME_HOOK")"
    say "  ${C_GREEN}✔${C_RESET} Installed one-shot check unit: $(_link "$PARK_KEEPALIVE_CHECK_UNIT")"
  else
    say "  ✔ Installed park-keepalive monitor: $PARK_KEEPALIVE_SCRIPT"
    note "    service: $PARK_KEEPALIVE_UNIT"
    say "  ✔ Installed post-resume hook: $PARK_KEEPALIVE_RESUME_HOOK"
    say "  ✔ Installed one-shot check unit: $PARK_KEEPALIVE_CHECK_UNIT"
  fi
  note "Instant on:"
  note "  - Polls the guest GPU while it is parked on vfio-pci between VM sessions"
  note "    and proactively recovers it if it died (RX 9070 / RDNA4 reset bug),"
  note "    so the NEXT VM start does not hit a dead card."
  note "  - Re-checks right after host suspend/hibernate resume."
  note "  - Falls back to a direct in-use check when libvirt is unreachable"
  note "    (hard-kill-without-release-event)."
  note "  - Backs off + sends a one-time desktop notification after"
  note "    VFIO_DYNAMIC_PARK_KEEPALIVE_MAX_FAILS (default 5) consecutive"
  note "    recovery failures."
  note ""
  note "Disable via VFIO_DYNAMIC_PARK_KEEPALIVE=0 in $CONF_FILE."
}

# Automatically hide the hypervisor on libvirt VMs that have the guest GPU
# attached. The AMD Windows driver detects it is running under a hypervisor
# (via CPUID hypervisor leaves + Hyper-V vendor ID) and refuses to install the
# real display driver — the card shows up as "Microsoft Basic Display Adapter"
# + unknown "PCI Device" / "PCI Simple Communications Controller" with yellow
# marks. Hiding the hypervisor (vendor_id=random + kvm hidden state=on) makes
# the AMD driver install the real Radeon driver. Only acts on shut-off VMs
# (running VMs can't be redefined); skipped with a note for running VMs.
# Gated to AMD guest GPUs (vendor 1002) since that's where the anti-passthrough
# detection matters most.
# NOTE: <hidden state='on'/> INSIDE <hyperv> is NOT supported by older libvirt
# (e.g. 12.5.0 rejects it as "unsupported HyperV Enlightenment feature"). Only
# <vendor_id> inside <hyperv> and <kvm><hidden state='on'/></kvm> are used —
# the kvm hidden is the main CPUID hypervisor-leaf mask, which is the primary
# detection vector the AMD driver checks.
install_hypervisor_hiding() {
  local _guest_gpu _vendor _dom _xml _tmp _changed _bdfs
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 0
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ "${_vendor,,}" != "1002" ]]; then
    note "Guest GPU is not AMD; skipping hypervisor hiding (AMD-driver anti-passthrough detection is AMD-specific)."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; skipping hypervisor hiding."
    return 0
  fi
  say
  hdr "Hypervisor hiding (AMD driver install fix)"
  note "The AMD Windows driver detects the hypervisor and refuses to install the real"
  note "display driver (card shows as Microsoft Basic Display Adapter + unknown PCI devices)."
  note "Hiding the hypervisor (vendor_id=random + kvm hidden) lets the AMD driver install."
  note "Only shut-off VMs with the guest GPU can be updated; running VMs are skipped."
  say
  local _updated=0 _skipped_running=0
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    # Check if this domain has the guest GPU in its XML. virsh dumpxml stores
    # PCI addresses as separate attributes (domain/bus/slot/function), NOT as
    # the combined BDF string — so we must parse them with awk and reconstruct
    # the BDF before comparing (same parser as the reboot-FLR monitor).
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    _bdfs="$(printf '%s' "$_xml" | awk '
      /<hostdev/ { in_hostdev=1; is_pci=0 }
      in_hostdev && /type=.pci./ { is_pci=1 }
      in_hostdev && is_pci && /<address/ {
        line=$0; dom=""; bus=""; slot=""; fn=""
        if (match(line, /domain=.0x[0-9a-fA-F]+/)) {
          s=substr(line, RSTART, RLENGTH); sub(/^domain=./, "", s); sub(/^0x/, "", s); dom=s
        }
        if (match(line, /bus=.0x[0-9a-fA-F]+/)) {
          s=substr(line, RSTART, RLENGTH); sub(/^bus=./, "", s); sub(/^0x/, "", s); bus=s
        }
        if (match(line, /slot=.0x[0-9a-fA-F]+/)) {
          s=substr(line, RSTART, RLENGTH); sub(/^slot=./, "", s); sub(/^0x/, "", s); slot=s
        }
        if (match(line, /function=.0x[0-9a-fA-F]+/)) {
          s=substr(line, RSTART, RLENGTH); sub(/^function=./, "", s); sub(/^0x/, "", s); fn=s
        }
        if (dom != "" && bus != "" && slot != "" && fn != "") {
          while (length(dom) < 4) dom = "0" dom
          while (length(bus) < 2) bus = "0" bus
          while (length(slot) < 2) slot = "0" slot
          printf "%s:%s:%s.%s\n", dom, bus, slot, fn
        }
      }
      /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
    ')"
    if ! grep -Fixq "$_guest_gpu" <<<"$_bdfs" 2>/dev/null; then
      continue
    fi
    # Check if already hidden (idempotent) — vendor_id + kvm hidden both present.
    if grep -Fq "vendor_id state='on'" <<<"$_xml" 2>/dev/null \
      && grep -Fq '<kvm>' <<<"$_xml" 2>/dev/null \
      && grep -Fq "hidden state='on'" <<<"$_xml" 2>/dev/null; then
      note "VM '$_dom' already has hypervisor hiding; skipping."
      continue
    fi
    # Check VM state — can only define shut-off VMs.
    local _state
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping hypervisor hiding. Shut it off and re-run to update it."
      _skipped_running=1
      continue
    fi
    # Add the hypervisor-hiding features to the XML.
    # Only vendor_id (inside <hyperv>) + <kvm><hidden state='on'/></kvm> — NOT
    # <hidden> inside <hyperv> (unsupported by older libvirt like 12.5.0).
    _tmp="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp"
    if ! grep -Fq '<kvm>' "$_tmp" 2>/dev/null; then
      sed -i "s|</hyperv>|      <vendor_id state='on' value='random'/>\n    </hyperv>\n    <kvm>\n      <hidden state='on'/>\n    </kvm>|" "$_tmp" 2>/dev/null || true
    else
      sed -i "s|</hyperv>|      <vendor_id state='on' value='random'/>\n    </hyperv>|" "$_tmp" 2>/dev/null || true
      # Ensure kvm hidden is set if <kvm> block already exists but lacks hidden.
      if ! grep -Fq "hidden state='on'" "$_tmp" 2>/dev/null; then
        sed -i "s|<kvm>|<kvm>\n      <hidden state='on'/>|" "$_tmp" 2>/dev/null || true
      fi
    fi
    # Validate + define.
    if virt-xml-validate "$_tmp" 2>/dev/null; then
      if (( ! DRY_RUN )); then
        virsh -c qemu:///system define "$_tmp" 2>/dev/null
      fi
      say "Updated VM '$_dom' with hypervisor hiding (vendor_id=random, kvm hidden)."
      note "The AMD driver should now install the real display driver on next VM boot."
      _updated=1
    else
      note "WARN: XML validation failed for '$_dom'; skipping hypervisor hiding."
    fi
    rm -f "$_tmp"
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _updated )); then
    if (( _skipped_running )); then
      note "No VMs were updated (running VMs must be shut off first). Shut off the VM and re-run."
    else
      note "No shut-off VMs with the guest GPU found; nothing to update."
    fi
  fi
}

# Stealth/perf VM XML tuning — ports the Stealthy-VM setup_vm_stealth.sh tuning
# (profile=all: stealth + perf) into vfio.sh so a dynamic install can apply it
# directly to the detected guest-GPU VMs. Stealthy-VM is MIT-licensed (Copyright
# (c) 2026 Fredrik Bäckström); the tuning algorithm is ported faithfully below.
# This SUPERSEDES install_hypervisor_hiding() for the dynamic path: it includes
# the hypervisor hide (vendor_id + kvm hidden) as a subset using a realistic
# OEM vendor_id (GENUINE00000) instead of 'random', PLUS SMBIOS spoofing, CPU
# hypervisor-CPUID-bit disable, e1000e NIC, randomized disk serials,
# memballoon=none, hypervclock off, TSC native, QEMU -cpu/-smbios args, and perf
# (iothreads/cputune/disk iothread). Idempotent (rebuilds <qemu:commandline>);
# python exit 3 = no changes needed. AMD-gated (consistent with hypervisor
# hiding). Only acts on shut-off VMs (running VMs are skipped with a note).
# Verifies the tuned XML with virt-xml-validate and prompts before redefining.
install_stealth_vm_tuning() {
  if ! readable_file "$CONF_FILE"; then
    note "Missing $CONF_FILE; skipping stealth/perf VM tuning."
    return 0
  fi
  # shellcheck disable=SC1090
  local _guest_gpu _vendor
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -z "$_guest_gpu" ]]; then
    note "No GUEST_GPU_BDF in $CONF_FILE; skipping stealth/perf VM tuning."
    return 0
  fi
  if [[ "${_vendor,,}" != "1002" ]]; then
    note "Guest GPU is not AMD; skipping stealth/perf VM tuning (AMD-driver anti-passthrough detection is AMD-specific)."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; skipping stealth/perf VM tuning."
    return 0
  fi
  if ! have_cmd python3; then
    note "python3 not available; skipping stealth/perf VM tuning (the XML patcher needs python3)."
    return 0
  fi

  say
  hdr "Stealth/perf VM tuning (SMBIOS / CPU / NIC / disk serials / iothreads)"
  note "This applies the Stealthy-VM tuning to each shut-off VM that has the guest GPU:"
  note "  - hyperv vendor_id=GENUINE00000 + kvm hidden (hypervisor hide for the AMD driver)"
  note "  - cpu host-passthrough + hypervisor CPUID bit disabled"
  note "  - SMBIOS type 0 (BIOS) + type 1 (system) spoofing with randomized serial/UUID"
  note "  - virtio NIC -> e1000e; randomized disk serials; memballoon=none"
  note "  - hypervclock off; TSC native; QEMU -cpu/-smbios commandline args"
  note "  - perf: iothreads=1, host-aware cputune, disk iothread assignment"
  note "Only shut-off VMs are touched; running VMs are skipped. The tuned XML is"
  note "validated (virt-xml-validate) and you are prompted before each redefine."
  if (( ENABLE_COLOR )); then
    note "${C_BOLD}${C_YELLOW}DISCLAIMER:${C_RESET} this is COSMETIC/PERFORMANCE realism tuning ONLY. It is NOT"
  else
    note "DISCLAIMER: this is COSMETIC/PERFORMANCE realism tuning ONLY. It is NOT"
  fi
  note "intended to, and does NOT reliably, defeat or bypass anti-cheat / anti-tamper software."
  note "Using it to evade anti-cheat in an online game may still violate that game's terms of service."
  say

  local _updated=0 _skipped_running=0 _dom _xml _bdfs _state _tmp _backup_dir _backup_xml
  # #6: configurable backup directory. Prefer STEALTH_VM_BACKUP_DIR from conf,
  # then $HOME/Desktop, then a root-writable /var/lib fallback.
  _backup_dir="$(awk -F= '/^STEALTH_VM_BACKUP_DIR=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _backup_dir="$(trim "${_backup_dir:-}")"
  if [[ -z "$_backup_dir" ]]; then
    _backup_dir="${BACKUP_DIR:-$HOME/Desktop}"
  fi
  if ! mkdir -p "$_backup_dir" 2>/dev/null || ! [[ -w "$_backup_dir" ]]; then
    _backup_dir="/var/lib/vfio-stealth-vm/backups"
    mkdir -p "$_backup_dir" 2>/dev/null || true
    note "STEALTH_VM_BACKUP_DIR not writable; using $_backup_dir for VM XML backups."
  fi
  note "Stealth VM XML backups: $_backup_dir"
  # #1: read the host's real DMI identity so the VM's spoofed SMBIOS matches the
  # host hardware (realistic stealth) instead of a generic ASUS B550. Falls back
  # to the hardcoded defaults if DMI is unreadable. Exported for the python tuning.
  local _dmi_sys_vendor _dmi_product _dmi_bios_vendor _dmi_bios_version _dmi_bios_date
  _dmi_sys_vendor="$(cat /sys/class/dmi/id/sys_vendor 2>/dev/null || true)"
  _dmi_product="$(cat /sys/class/dmi/id/product_name 2>/dev/null || true)"
  _dmi_bios_vendor="$(cat /sys/class/dmi/id/bios_vendor 2>/dev/null || true)"
  _dmi_bios_version="$(cat /sys/class/dmi/id/bios_version 2>/dev/null || true)"
  _dmi_bios_date="$(cat /sys/class/dmi/id/bios_date 2>/dev/null || true)"
  export VFIO_STEALTH_DMI_SYS_VENDOR="${_dmi_sys_vendor:-American Megatrends Inc.}"
  export VFIO_STEALTH_DMI_PRODUCT="${_dmi_product:-ROG STRIX B550-F}"
  export VFIO_STEALTH_DMI_BIOS_VENDOR="${_dmi_bios_vendor:-American Megatrends Inc.}"
  export VFIO_STEALTH_DMI_BIOS_VERSION="${_dmi_bios_version:-1802}"
  export VFIO_STEALTH_DMI_BIOS_DATE="${_dmi_bios_date:-12/12/2023}"
  if [[ -n "$_dmi_sys_vendor" || -n "$_dmi_product" ]]; then
    note "Spoofing SMBIOS from host DMI: $_dmi_sys_vendor $_dmi_product (BIOS $_dmi_bios_vendor $_dmi_bios_version)"
  else
    note "DMI unreadable; using hardcoded SMBIOS defaults (ASUS ROG STRIX B550-F / AMI 1802)."
  fi
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match in the XML OR in the live-attach VM list
    # (live-attach strips the GPU hostdev from the persistent XML, so a BDF
    # grep alone would miss an already-live-attach-configured VM).
    if ! _vm_is_guest_gpu_vm "$_dom" "$_xml"; then
      continue
    fi
    # Only define shut-off VMs.
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping stealth/perf tuning. Shut it off and re-run."
      _skipped_running=1
      continue
    fi
    _tmp="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp"
    _backup_xml="$_backup_dir/${_dom}_stealth_$(date +%Y%m%d-%H%M%S).xml"
    # Write the backup XML even in dry-run so the dry-run diff (below) has a
    # baseline to diff against. The tuned temp copy is the "after".
    mkdir -p "$_backup_dir" 2>/dev/null || true
    cp "$_tmp" "$_backup_xml" 2>/dev/null || true
    # Run the python tuning (profile=all) on the temp XML.
    # Exit codes: 0 = changed, 3 = no changes needed (idempotent), 4 = unsupported domain.
    local _py_status=0
    python3 - "$_tmp" <<'PYEOF' || _py_status=$?
import sys, xml.etree.ElementTree as ET, os, uuid, secrets, string
QEMU_NS = 'http://libvirt.org/schemas/domain/qemu/1.0'
ET.register_namespace('qemu', QEMU_NS)
# Register the libosinfo namespace so ElementTree preserves the 'libosinfo:'
# prefix instead of rewriting it to 'ns0:' — libvirt rejects 'ns0:' on define.
ET.register_namespace('libosinfo', 'http://libosinfo.org/xmlns/libvirt/domain/1.0')
path = sys.argv[1]
tree = ET.parse(path); root = tree.getroot()
# NOTE: do NOT root.set('xmlns:qemu', QEMU_NS) — ET.register_namespace above
# already maps the qemu: prefix and the serializer emits xmlns:qemu automatically.
# Setting it explicitly causes a duplicate-attribute ParseError on re-parse
# (idempotent re-run). register_namespace alone is sufficient.
vcpu_el = root.find('vcpu')
if vcpu_el is not None and vcpu_el.text:
    try:
        vc = int(vcpu_el.text.strip())
        if vc > 1 and (vc % 2) == 1:
            sys.stderr.write(f"Warning: vCPU count {vc} is odd (>1); may look unrealistic.\n")
    except ValueError: pass
domain_type = root.get('type')
if domain_type not in (None, 'kvm', 'qemu'):
    sys.stderr.write(f"Unsupported domain type: {domain_type}\n"); sys.exit(4)
changed = False
def get_or_create(parent, tag, attrs=None):
    for c in parent:
        if c.tag == tag: return c
    return ET.SubElement(parent, tag, attrs or {})
def get_or_create_qemu_commandline(root_el):
    # #2: preserve existing <qemu:commandline> args (e.g. Looking Glass kvmfr)
    # instead of wiping them. We only dedupe the stealth -cpu/-smbios pairs
    # below so re-running is idempotent without losing user args.
    for c in root_el:
        if c.tag == f"{{{QEMU_NS}}}commandline": return c
    return ET.SubElement(root_el, f"{{{QEMU_NS}}}commandline")
def remove_qemu_arg_pair(qcmd, flag_value):
    # Remove an <arg value='FLAG'/> and the <arg/> immediately following it
    # (the payload). Idempotent: no-op if the flag is not present.
    kids = list(qcmd)
    i = 0
    while i < len(kids):
        if kids[i].get('value') == flag_value and i + 1 < len(kids):
            qcmd.remove(kids[i+1]); qcmd.remove(kids[i])
            kids = list(qcmd); i = 0
        else:
            i += 1
# --- stealth ---
features = get_or_create(root, 'features')
hyperv = get_or_create(features, 'hyperv', {'mode': 'custom'})
# Set vendor_id to GENUINE00000 — ADD if missing, or REPLACE the existing
# value (e.g. 'random' from a prior install_hypervisor_hiding() run) so the
# stealth-tuned VM uses a realistic OEM string, not the old 'random'.
_vendor_id_el = None
for ch in hyperv:
    if ch.tag == 'vendor_id': _vendor_id_el = ch; break
if _vendor_id_el is None:
    ET.SubElement(hyperv, 'vendor_id', {'state': 'on', 'value': 'GENUINE00000'}); changed = True
elif _vendor_id_el.get('value') != 'GENUINE00000':
    _vendor_id_el.set('value', 'GENUINE00000'); changed = True
if _vendor_id_el is not None and _vendor_id_el.get('state') != 'on':
    _vendor_id_el.set('state', 'on'); changed = True
kvm = get_or_create(features, 'kvm')
hidden = None
for ch in kvm:
    if ch.tag == 'hidden': hidden = ch; break
if hidden is None: hidden = ET.SubElement(kvm, 'hidden')
if hidden.get('state') != 'on': hidden.set('state', 'on'); changed = True
# Disable the VMware backdoor port (vmport) so Windows detection tools that
# probe port 0x5658 ('VMX') don't report "Is Virtual Machine: yes". This is a
# key hypervisor detection vector alongside the CPUID hypervisor bit.
vmport = None
for ch in features:
    if ch.tag == 'vmport': vmport = ch; break
if vmport is None: vmport = ET.SubElement(features, 'vmport')
if vmport.get('state') != 'off': vmport.set('state', 'off'); changed = True
cpu = root.find('cpu')
if cpu is None: cpu = ET.SubElement(root, 'cpu', {'mode': 'host-passthrough', 'check': 'none', 'migratable': 'on'}); changed = True
has_hv = False
for ch in cpu:
    if ch.tag == 'feature' and ch.get('name') == 'hypervisor':
        has_hv = True
        if ch.get('policy') != 'disable': ch.set('policy', 'disable'); changed = True
        break
if not has_hv: ET.SubElement(cpu, 'feature', {'policy': 'disable', 'name': 'hypervisor'}); changed = True
os_el = root.find('os')
if os_el is not None:
    for smb in list(os_el.findall('smbios')): os_el.remove(smb); changed = True
for sysinfo in list(root.findall('sysinfo')): root.remove(sysinfo); changed = True
devices = root.find('devices')
if devices is not None:
    for tag in ('serial', 'console'):
        for el in list(devices):
            if el.tag == tag: devices.remove(el); changed = True
    has_usb_mouse = False
    for el in list(devices):
        if el.tag == 'input':
            itype = el.get('type'); bus = el.get('bus')
            if itype == 'tablet': devices.remove(el); changed = True
            elif itype == 'mouse' and bus == 'usb': has_usb_mouse = True
    if not has_usb_mouse: ET.SubElement(devices, 'input', {'type': 'mouse', 'bus': 'usb'}); changed = True
    for el in list(devices):
        if el.tag == 'controller' and el.get('type') == 'virtio-serial': devices.remove(el); changed = True
    for iface in devices.findall('interface'):
        model = iface.find('model')
        if model is not None and model.get('type') == 'virtio': model.set('type', 'e1000e'); changed = True
        driver = iface.find('driver')
        if driver is not None and driver.get('name') == 'vhost': iface.remove(driver); changed = True
    for disk in devices.findall('disk'):
        if disk.find('serial') is None:
            ds = "Samsung_" + "".join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(8))
            ET.SubElement(disk, 'serial').text = ds; changed = True
for mb in root.findall('.//memballoon'):
    if mb.get('model') != 'none': mb.set('model', 'none'); changed = True
clock = root.find('clock')
if clock is None: clock = ET.SubElement(root, 'clock', {'offset': 'localtime'}); changed = True
ht = None
for t in clock.findall('timer'):
    if t.get('name') == 'hypervclock': ht = t; break
if ht is None: ht = ET.SubElement(clock, 'timer', {'name': 'hypervclock'})
if ht.get('present') != 'no': ht.set('present', 'no'); changed = True
# Disable hyperv enlightenment features that REQUIRE hypervclock — libvirt
# rejects the XML if these are 'on' while hypervclock is 'no' (e.g. "'stimer'
# hyperv feature requires 'hypervclock' timer"). These are deep hyperv
# features (synthetic interrupts / virtual processor index) that a real
# desktop PC wouldn't have anyway, so disabling them is consistent with stealth.
for _hv_feat in ('synic', 'stimer', 'vpindex', 'runtime', 'frequencies', 'tlbflush', 'ipi', 'avic'):
    _fv = None
    for ch in hyperv:
        if ch.tag == _hv_feat: _fv = ch; break
    if _fv is not None and _fv.get('state') != 'off':
        _fv.set('state', 'off'); changed = True
tsc = None
for t in clock.findall('timer'):
    if t.get('name') == 'tsc': tsc = t; break
if tsc is None: tsc = ET.SubElement(clock, 'timer', {'name': 'tsc'})
if tsc.get('mode') != 'native': tsc.set('mode', 'native'); changed = True
if tsc.get('present') not in (None, 'yes'): tsc.set('present', 'yes'); changed = True
# #1: read the host DMI identity (exported by the bash wrapper) so the spoofed
# SMBIOS matches the host hardware. Falls back to hardcoded defaults.
dmi_sv = os.environ.get('VFIO_STEALTH_DMI_SYS_VENDOR', 'ASUS')
dmi_prod = os.environ.get('VFIO_STEALTH_DMI_PRODUCT', 'ROG STRIX B550-F')
dmi_bv = os.environ.get('VFIO_STEALTH_DMI_BIOS_VENDOR', 'American Megatrends Inc.')
dmi_bver = os.environ.get('VFIO_STEALTH_DMI_BIOS_VERSION', '1802')
dmi_bdate = os.environ.get('VFIO_STEALTH_DMI_BIOS_DATE', '12/12/2023')
qemu_cmd = get_or_create_qemu_commandline(root)
# #2: dedupe the stealth -cpu + -smbios pairs (idempotent re-run) WITHOUT
# wiping other user args (Looking Glass kvmfr, vendor-specific, etc.).
remove_qemu_arg_pair(qemu_cmd, "-cpu")
remove_qemu_arg_pair(qemu_cmd, "-smbios")
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': "-cpu"})
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': "host,kvm=off,hypervisor=off,hv_vendor_id=null,invtsc=on"})
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': "-smbios"})
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': f"type=0,vendor={dmi_bv},version={dmi_bver},date={dmi_bdate}"})
smbios_serial = secrets.token_hex(5).upper(); smbios_uuid = uuid.uuid4()
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': "-smbios"})
ET.SubElement(qemu_cmd, f"{{{QEMU_NS}}}arg", {'value': f"type=1,manufacturer={dmi_sv},product={dmi_prod},serial={smbios_serial},uuid={smbios_uuid}"})
changed = True
# --- perf ---
if root.find('iothreads') is None:
    children = list(root); vcpu_el = root.find('vcpu')
    idx = children.index(vcpu_el) + 1 if vcpu_el is not None else len(children)
    it = ET.Element('iothreads'); it.text = '1'; root.insert(idx, it); changed = True
if root.find('cputune') is None:
    vcpu_el = root.find('vcpu'); vcpu_count = 0
    if vcpu_el is not None and vcpu_el.text:
        try: vcpu_count = int(vcpu_el.text.strip())
        except ValueError: vcpu_count = 0
    host_cpus = os.cpu_count() or 1
    if 0 < vcpu_count <= host_cpus:
        cputune = ET.SubElement(root, 'cputune')
        if host_cpus >= vcpu_count + 4:
            for v in range(vcpu_count): ET.SubElement(cputune, 'vcpupin', {'vcpu': str(v), 'cpuset': str(4 + v)})
            ET.SubElement(cputune, 'emulatorpin', {'cpuset': '0-1'})
            ET.SubElement(cputune, 'iothreadpin', {'iothread': '1', 'cpuset': '2-3'})
        elif host_cpus >= vcpu_count + 2:
            for v in range(vcpu_count): ET.SubElement(cputune, 'vcpupin', {'vcpu': str(v), 'cpuset': str(2 + v)})
            ET.SubElement(cputune, 'emulatorpin', {'cpuset': '0'})
            ET.SubElement(cputune, 'iothreadpin', {'iothread': '1', 'cpuset': '1'})
        elif host_cpus >= vcpu_count:
            for v in range(vcpu_count): ET.SubElement(cputune, 'vcpupin', {'vcpu': str(v), 'cpuset': str(v)})
        changed = True
devices = root.find('devices')
if devices is not None:
    for disk in devices.findall('disk'):
        driver = disk.find('driver')
        if driver is None: continue
        target = disk.find('target'); bus = target.get('bus') if target is not None else None
        if (driver.get('name') == 'qemu' and driver.get('type') == 'qcow2' and driver.get('iothread') is None and bus in ('virtio', 'scsi')):
            driver.set('iothread', '1'); changed = True
if not changed: sys.exit(3)
tree.write(path)
PYEOF
    if (( _py_status == 3 )); then
      say "VM '$_dom' is already tuned (no changes needed)."
      _updated=1
      rm -f "$_tmp"
      continue
    elif (( _py_status == 4 )); then
      note "WARN: VM '$_dom' has an unsupported domain type; skipping stealth/perf tuning."
      rm -f "$_tmp"
      continue
    elif (( _py_status != 0 )); then
      note "WARN: stealth/perf XML patching failed for '$_dom' (python exit $_py_status); skipping."
      rm -f "$_tmp"
      continue
    fi
    # Verify the tuned XML before redefining.
    if ! virt-xml-validate "$_tmp" 2>/dev/null; then
      note "WARN: virt-xml-validate failed for tuned '$_dom'; skipping redefine (backup at $_backup_xml)."
      rm -f "$_tmp"
      continue
    fi
    say "Tuned XML for '$_dom' validates. Backup of original: $_backup_xml"
    # #5: in dry-run, show a unified diff of current vs tuned XML before prompting.
    if (( DRY_RUN )); then
      say "Dry run: showing diff (current -> tuned) for '$_dom' (no redefine will happen):"
      if command -v diff >/dev/null 2>&1; then
        diff -u "$_backup_xml" "$_tmp" || true
      else
        say "diff(1) not available; tuned XML is in $_tmp"
      fi
    fi
    # Skip the per-VM confirmation when the user explicitly forced this via
    # --stealth-vm-tuning: that flag is documented as "skip prompt", so a
    # second interactive confirmation here would defeat its purpose (e.g. for
    # scripted/non-interactive re-runs). The interactive full-wizard path
    # (STEALTH_VM_TUNING_OVERRIDE unset, user answered the outer Y/N prompt)
    # still confirms per VM here, since that path is inherently interactive.
    if [[ "${STEALTH_VM_TUNING_OVERRIDE:-}" != "1" ]] && ! prompt_yn "Redefine VM '$_dom' with the stealth/perf tuning now?" N "Stealth/perf VM tuning"; then
      note "Skipped '$_dom' by user choice (tuned XML left in $_tmp; backup at $_backup_xml)."
      rm -f "$_tmp"
      continue
    fi
    local _define_rc=0
    if (( ! DRY_RUN )); then
      local _define_err
      _define_err="$(virsh -c qemu:///system define "$_tmp" 2>&1 >/dev/null)" || _define_rc=$?
    fi
    if (( _define_rc != 0 )); then
      note "ERROR: virsh define failed for '$_dom' (exit $_define_rc): $_define_err"
      note "The tuned XML is in $_tmp; backup at $_backup_xml. You can define it manually:"
      note "  virsh -c qemu:///system define $_tmp"
      rm -f "$_tmp"
      continue
    fi
    say
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}${C_BOLD}✔ Stealth/perf tuning applied to VM '$_dom'${C_RESET}"
    else
      say "✔ Stealth/perf tuning applied to VM '$_dom'"
    fi
    say "  ✔ hyperv vendor_id=GENUINE00000 + kvm hidden (hypervisor hide)"
    say "  ✔ vmport state=off (VMware backdoor port disabled — stops \"Is Virtual Machine: yes\")"
    say "  ✔ CPU host-passthrough + hypervisor CPUID bit disabled"
    say "  ✔ SMBIOS spoofed from host DMI: ${_dmi_sys_vendor:-<default>} ${_dmi_product:-<default>} (BIOS ${_dmi_bios_version:-<default>})"
    say "  ✔ QEMU -cpu host,kvm=off,hypervisor=off + -smbios type=0/type=1 args"
    say "  ✔ NIC -> e1000e; disk serials randomized; memballoon=none"
    say "  ✔ hypervclock off; TSC native; serial/console + tablet removed"
    say "  ✔ perf: iothreads=1, host-aware cputune, disk iothread assignment"
    say "  Backup of original XML: $_backup_xml"
    note "Restore with: sudo $SCRIPT_NAME --reset-stealth-vm-tuning  (or: virsh -c qemu:///system define $_backup_xml)"
    _updated=1
    rm -f "$_tmp"
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _updated )); then
    if (( _skipped_running )); then
      note "No VMs were tuned (running VMs must be shut off first). Shut off the VM and re-run."
    else
      note "No shut-off VMs with the guest GPU found; nothing to tune."
    fi
  fi
}

# #3: Revert stealth/perf VM tuning by redefining each guest-GPU VM from its
# most recent *_stealth_*.xml backup. Standalone mode (--reset-stealth-vm-tuning).
# Only acts on shut-off VMs (running VMs are skipped with a note). Verifies the
# backup XML with virt-xml-validate and prompts before redefining.
reset_stealth_vm_tuning() {
  if ! readable_file "$CONF_FILE"; then
    note "Missing $CONF_FILE; nothing to revert."
    return 0
  fi
  local _guest_gpu _vendor
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -z "$_guest_gpu" ]]; then
    note "No GUEST_GPU_BDF in $CONF_FILE; nothing to revert."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; cannot revert stealth/perf VM tuning."
    return 0
  fi
  # Resolve the backup dir (same logic as install_stealth_vm_tuning).
  local _backup_dir
  _backup_dir="$(awk -F= '/^STEALTH_VM_BACKUP_DIR=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _backup_dir="$(trim "${_backup_dir:-}")"
  if [[ -z "$_backup_dir" ]]; then _backup_dir="${BACKUP_DIR:-$HOME/Desktop}"; fi
  if ! [[ -d "$_backup_dir" ]]; then
    _backup_dir="/var/lib/vfio-stealth-vm/backups"
  fi
  say
  hdr "Revert stealth/perf VM tuning (restore from backup XML)"
  note "This redefines each shut-off guest-GPU VM from its most recent"
  note "${_dom:-<vm>}_stealth_*.xml backup in $_backup_dir."
  note "Only shut-off VMs are touched; running VMs are skipped."
  say
  local _reverted=0 _skipped_running=0 _dom _xml _bdfs _state _backup _newest
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match OR in the live-attach VM list (live-attach
    # strips the GPU hostdev, so a BDF grep alone misses a live-attach VM).
    if ! _vm_is_guest_gpu_vm "$_dom" "$_xml"; then
      continue
    fi
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping revert. Shut it off and re-run."
      _skipped_running=1
      continue
    fi
    # Find the most recent *_stealth_*.xml backup for this VM.
    _newest=""
    for _backup in "$_backup_dir/${_dom}_stealth_"*.xml; do
      [[ -f "$_backup" ]] || continue
      if [[ -z "$_newest" || "$_backup" -nt "$_newest" ]]; then
        _newest="$_backup"
      fi
    done
    if [[ -z "$_newest" ]]; then
      note "No stealth backup XML found for '$_dom' in $_backup_dir; skipping."
      continue
    fi
    if ! virt-xml-validate "$_newest" 2>/dev/null; then
      note "WARN: virt-xml-validate failed for backup '$_newest'; skipping revert of '$_dom'."
      continue
    fi
    say "Found backup for '$_dom': $_newest (validates)."
    if ! prompt_yn "Redefine VM '$_dom' from the pre-tuning backup now?" N "Revert stealth/perf VM tuning"; then
      note "Skipped '$_dom' by user choice."
      continue
    fi
    if (( ! DRY_RUN )); then
      virsh -c qemu:///system define "$_newest" 2>/dev/null
    fi
    say "Reverted VM '$_dom' from backup: $_newest"
    _reverted=1
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _reverted )); then
    if (( _skipped_running )); then
      note "No VMs were reverted (running VMs must be shut off first)."
    else
      note "No stealth backups found for guest-GPU VMs; nothing to revert."
    fi
  fi
}

# #4: Report stealth/perf VM tuning status for each guest-GPU VM (used by
# --detect and --verify). Checks for vendor_id=GENUINE00000 + QEMU -cpu/-smbios
# args in the VM XML. Prints one status line per guest-GPU VM.
stealth_vm_tuning_status() {
  if ! readable_file "$CONF_FILE"; then return 0; fi
  local _guest_gpu _dom _xml _bdfs _has_vendor _has_cpu _has_smbios
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 0
  have_cmd virsh || return 0
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match OR in the live-attach VM list (live-attach
    # strips the GPU hostdev, so a BDF grep alone misses a live-attach VM).
    _vm_is_guest_gpu_vm "$_dom" "$_xml" || continue
    _has_vendor=0; _has_cpu=0; _has_smbios=0
    grep -Fq 'GENUINE00000' <<<"$_xml" 2>/dev/null && _has_vendor=1
    grep -Fq 'kvm=off,hypervisor=off' <<<"$_xml" 2>/dev/null && _has_cpu=1
    grep -Fq 'type=1,manufacturer=' <<<"$_xml" 2>/dev/null && _has_smbios=1
    if (( _has_vendor && _has_cpu && _has_smbios )); then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: VM '$_dom' is stealth-tuned (vendor_id=GENUINE00000, -cpu/-smbios present)"
      else
        say "OK: VM '$_dom' is stealth-tuned (vendor_id=GENUINE00000, -cpu/-smbios present)"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}INFO${C_RESET}: VM '$_dom' is NOT stealth-tuned (use 'sudo $SCRIPT_NAME --install-stealth-vm-tuning')"
      else
        say "INFO: VM '$_dom' is NOT stealth-tuned (use 'sudo $SCRIPT_NAME --install-stealth-vm-tuning')"
      fi
    fi
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
}

# R35: Detect whether a libvirt domain is a guest-GPU VM. A VM qualifies if
# its persistent XML has the guest GPU PCI hostdev (BDF match), OR it is in the
# live-attach VM list. Live-attach strips the GPU hostdev from the persistent
# XML so the VM can boot without the GPU and hot-attach it later — so a BDF
# grep ALONE misses an already-live-attach-configured VM, which would make the
# stealth/perf tuners unable to tune a live-attach VM without reverting
# live-attach first (the wrong UX). This mirrors the proven fallback already
# used by install_virtio_win_guest_agent (which attaches the virtio-win ISO).
# $1 = domain name, $2 = optional pre-fetched dumpxml (avoids a redundant
# virsh dumpxml when the caller already has the XML). Returns 0 if the domain
# is a guest-GPU VM, 1 otherwise. VFIO_LIVE_ATTACH_VM_LIST (env) overrides the
# live-attach list path for regression testing.
_vm_is_guest_gpu_vm() {
  local _dom="$1" _xml="${2:-}" _guest_gpu _bdfs _la_list
  [[ -n "$_xml" ]] || _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
  [[ -n "$_xml" ]] || return 1
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 1
  _bdfs="$(printf '%s' "$_xml" | awk '
    /<hostdev/ { in_hostdev=1; is_pci=0 }
    in_hostdev && /type=.pci./ { is_pci=1 }
    in_hostdev && is_pci && /<address/ {
      line=$0; dom=""; bus=""; slot=""; fn=""
      if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
      if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
      if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
      if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
      if (dom != "" && bus != "" && slot != "" && fn != "") {
        while (length(dom) < 4) dom = "0" dom
        while (length(bus) < 2) bus = "0" bus
        while (length(slot) < 2) slot = "0" slot
        printf "%s:%s:%s.%s\n", dom, bus, slot, fn
      }
    }
    /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
  ')"
  if grep -Fixq "$_guest_gpu" <<<"$_bdfs" 2>/dev/null; then
    return 0
  fi
  _la_list="${VFIO_LIVE_ATTACH_VM_LIST:-/var/lib/vfio-dynamic/live-attach-vms}"
  if [[ -f "$_la_list" ]] && grep -Fixq "$_dom" "$_la_list" 2>/dev/null; then
    return 0
  fi
  return 1
}

# R35: Read the VM's <memory> (KiB) from a dumpxml. $1 = xml. Prints the
# integer KiB, or 0 on failure. Never fails.
_vm_memory_kib() {
  local _xml="$1" _mem_kib
  _mem_kib="$(printf '%s' "$_xml" | grep -oE '<memory[^>]*>[[:space:]]*[0-9]+' | grep -oE '[0-9]+$' | head -n1 2>/dev/null || true)"
  _mem_kib="$(trim "${_mem_kib:-}")"
  [[ "$_mem_kib" =~ ^[0-9]+$ ]] || _mem_kib=0
  printf '%s' "$_mem_kib"
}

# R35: Reserve host hugepages for a VM — RAM-change aware + reserve-first +
# verify + reboot-safe + 1GB-guarded.
# $1 = VM dumpxml, $2 = page size in KiB (matches libvirt <page size=... unit='KiB'/>),
# $3 = backup dir, $4 = domain name. Returns 0 if the host pool now has >= the
# pages this VM needs (safe to add <memoryBacking>), or 1 if not (caller turns
# hugepages OFF for this run so the VM keeps every other perf knob and still
# starts).
#
# Behavior:
#  - Computes the page count from the VM's CURRENT <memory> (KiB) divided by the
#    page size (KiB), so a RAM allocation change between runs is honored (grow =
#    add, shrink = free), instead of only ever adding. The count THIS VM owns is
#    persisted to ${3}/${4}_perf_hugepages_owned.txt so a shrink frees exactly
#    its surplus while preserving other tuned VMs' reservations (target = sum of
#    other VMs' owned + this VM's new need).
#  - RESERVE-FIRST + VERIFY: writes /proc/sys/vm/nr_hugepages, then re-reads the
#    knob — the runtime write can grant FEWER than requested on a fragmented
#    host. On a shortfall it reverts the pool and returns 1 (so no mismatched
#    <memoryBacking> is defined), with a WARN naming the shortfall and the
#    boot-time 'hugepages=N' kernel-cmdline fallback (reboot-safe, can't be
#    fragmented out).
#  - 1GB guard: a 1GB page size (1048576 KiB) CANNOT be reserved at runtime (the
#    runtime knob only controls the 2MB pool); returns 1 + warns and skips the
#    write (the operator must use 'hugepagesz=1G hugepages=N' on the cmdline).
#  - Reboot-safe re-reserve: after a host reboot resets nr_hugepages to 0, the
#    next run re-reserves automatically (target > 0 while the pool is 0).
_reserve_host_hugepages_for_vm() {
  local _xml="$1" _size_kib="$2" _backup_dir="$3" _dom="$4"
  local _mem_kib _page_kib _need _cur _other_owned _want _got _owned_file _f _o _disp_size
  _mem_kib="$(_vm_memory_kib "$_xml")"
  if (( _mem_kib <= 0 )); then
    note "VM '$_dom' memory unreadable or zero; skipping hugepages reservation."
    return 1
  fi
  # 1GB pages guard.
  if (( _size_kib >= 1048576 )); then
    note "WARN: hugepages size ${_size_kib}KiB is 1GB — 1GB pages cannot be reserved at runtime (the /proc/sys/vm/nr_hugepages knob only controls the 2MB pool). Add 'hugepagesz=1G hugepages=<count>' to the kernel cmdline and reboot, then re-run. Skipping hugepages for '$_dom' (no mismatched <memoryBacking> will be added)."
    return 1
  fi
  _page_kib="$_size_kib"
  (( _page_kib > 0 )) || _page_kib=2048
  _need=$(( _mem_kib / _page_kib ))
  (( _need * _page_kib < _mem_kib )) && _need=$(( _need + 1 ))
  if (( _need <= 0 )); then
    note "VM '$_dom' memory smaller than one hugepage; skipping hugepages reservation."
    return 1
  fi
  _cur="$(cat /proc/sys/vm/nr_hugepages 2>/dev/null || echo 0)"
  [[ "$_cur" =~ ^[0-9]+$ ]] || _cur=0
  _owned_file="$_backup_dir/${_dom}_perf_hugepages_owned.txt"
  _other_owned=0
  for _f in "$_backup_dir"/*_perf_hugepages_owned.txt; do
    [[ -f "$_f" ]] || continue
    [[ "$_f" == "$_owned_file" ]] && continue
    _o="$(cat "$_f" 2>/dev/null || echo 0)"
    [[ "$_o" =~ ^[0-9]+$ ]] || _o=0
    _other_owned=$(( _other_owned + _o ))
  done
  _want=$(( _other_owned + _need ))
  (( _want < 0 )) && _want=0
  _disp_size=$(( _size_kib / 1024 ))
  note "Reserving $_need hugepage(s) of ${_disp_size}MiB (${_size_kib}KiB) for '$_dom' (host nr_hugepages: $_cur -> $_want)."
  if (( ! DRY_RUN )); then
    if ! printf '%s\n' "$_want" >/proc/sys/vm/nr_hugepages 2>/dev/null; then
      note "WARN: failed to write /proc/sys/vm/nr_hugepages for '$_dom'. Skipping hugepages for this VM (other perf knobs still apply)."
      return 1
    fi
    _got="$(cat /proc/sys/vm/nr_hugepages 2>/dev/null || echo 0)"
    [[ "$_got" =~ ^[0-9]+$ ]] || _got=0
    if (( _got < _want )); then
      note "WARN: host granted only $_got of $_want hugepage(s) for '$_dom' (fragmented RAM; VM needs $_need). Reverting the pool to $_cur and skipping hugepages for this VM (other perf knobs still apply). Reliable fix: add 'hugepages=$_want' to the kernel cmdline and reboot (boot-time reservation can't be fragmented out)."
      printf '%s\n' "$_cur" >/proc/sys/vm/nr_hugepages 2>/dev/null || true
      return 1
    fi
    printf '%s\n' "$_need" >"$_owned_file" 2>/dev/null || true
    # Register this backup dir in the boot-reserve registry so the boot-time
    # oneshot re-reserves the pool after a host reboot (nr_hugepages resets to
    # 0 on reboot; without this a hugepages-backed VM fails to start until the
    # operator manually re-runs --install-ultimate-perf-vm-tuning).
    _register_perf_hugepages_dir "$_backup_dir"
  fi
  return 0
}

# R35: Restore the host nr_hugepages after reverting a VM (revert helper).
# $1 = backup dir, $2 = domain name. Removes this VM's owned-count file and
# rewrites nr_hugepages to the sum of the REMAINING tuned VMs' owned counts (so
# reverting one VM frees its pages but keeps the others reserved); 0 if none
# remain. Best-effort. Returns 0 even if no owned file exists.
_restore_host_hugepages_for_vm() {
  local _backup_dir="$1" _dom="$2"
  local _owned_file _sum _o _f _cur _left _lf
  _owned_file="$_backup_dir/${_dom}_perf_hugepages_owned.txt"
  [[ -f "$_owned_file" ]] || return 0
  rm -f "$_owned_file" 2>/dev/null || true
  # Unregister this backup dir from the boot-reserve registry when its last
  # owned file is gone, so the boot oneshot's ConditionPathExists cleanly
  # skips once every perf-hugepages VM has been reverted.
  _left=0
  for _lf in "$_backup_dir"/*_perf_hugepages_owned.txt; do
    [[ -f "$_lf" ]] && { _left=1; break; }
  done
  (( _left )) || _unregister_perf_hugepages_dir "$_backup_dir"
  _sum=0
  for _f in "$_backup_dir"/*_perf_hugepages_owned.txt; do
    [[ -f "$_f" ]] || continue
    _o="$(cat "$_f" 2>/dev/null || echo 0)"
    [[ "$_o" =~ ^[0-9]+$ ]] || _o=0
    _sum=$(( _sum + _o ))
  done
  _cur="$(cat /proc/sys/vm/nr_hugepages 2>/dev/null || echo 0)"
  [[ "$_cur" =~ ^[0-9]+$ ]] || _cur=0
  note "Restoring host nr_hugepages to $_sum for '$_dom' (was $_cur; freed this VM's pages, kept other tuned VMs' reservations)."
  if (( ! DRY_RUN )); then
    printf '%s\n' "$_sum" >/proc/sys/vm/nr_hugepages 2>/dev/null \
      || note "WARN: failed to restore /proc/sys/vm/nr_hugepages (left as-is)."
  fi
  return 0
}

# R35: Register a perf-hugepages backup dir in the boot-reserve registry
# (dedup-safe). Called by _reserve_host_hugepages_for_vm after it writes the
# owned file, so the boot-time oneshot can re-reserve the pool after a reboot.
_register_perf_hugepages_dir() {
  local _dir="$1"
  [[ -n "$_dir" ]] || return 0
  mkdir -p "$(dirname "$PERF_HP_DIRS_FILE")" 2>/dev/null || true
  if [[ -f "$PERF_HP_DIRS_FILE" ]] && grep -Fixq "$_dir" "$PERF_HP_DIRS_FILE" 2>/dev/null; then
    return 0
  fi
  printf '%s\n' "$_dir" >>"$PERF_HP_DIRS_FILE" 2>/dev/null || true
}

# R35: Unregister a perf-hugepages backup dir from the boot-reserve registry.
# Called by _restore_host_hugepages_for_vm when its last owned file is removed.
# If the registry empties, remove it so the boot unit's ConditionPathExists
# cleanly skips. Best-effort.
_unregister_perf_hugepages_dir() {
  local _dir="$1" _tmp
  [[ -n "$_dir" && -f "$PERF_HP_DIRS_FILE" ]] || return 0
  _tmp="$(mktemp 2>/dev/null || true)"
  [[ -n "$_tmp" ]] || return 0
  grep -Fixv "$_dir" "$PERF_HP_DIRS_FILE" 2>/dev/null >"$_tmp" || true
  if [[ -s "$_tmp" ]]; then
    cat "$_tmp" >"$PERF_HP_DIRS_FILE" 2>/dev/null || true
  else
    rm -f "$PERF_HP_DIRS_FILE" 2>/dev/null || true
  fi
  rm -f "$_tmp" 2>/dev/null || true
}

# R35: Install + enable the reboot-persistent hugepages re-reserve oneshot
# service. Writes a STANDALONE boot script (it never sources vfio.sh — at boot
# /usr/local/bin/vfio may be absent and sourcing would re-parse args / re-run
# detection) that reads PERF_HP_DIRS_FILE, sums the per-VM owned counts, and
# re-reserves the pool before libvirt starts autostart VMs. Idempotent. Called
# after at least one VM successfully reserves hugepages in
# install_ultimate_perf_vm_tuning. Honors the 1GB-page guard (skip + warn) and
# verifies the kernel delivered the full count (warns on a fragmented shortfall
# without reverting — a partial reservation is better than none at boot).
install_perf_hugepages_boot_service() {
  if ! have_cmd systemctl; then
    note "WARN: systemd not available; cannot install the boot-time hugepages re-reserve service. After each host reboot you must re-run 'sudo $SCRIPT_NAME --install-ultimate-perf-vm-tuning --ultimate-perf-hugepages' (or manually echo the owned count into /proc/sys/vm/nr_hugepages) or hugepages-backed VMs will fail to start."
    return 0
  fi
  local _unit
  _unit="$(basename "$PERF_HP_BOOT_UNIT")"
  mkdir -p "$(dirname "$PERF_HP_DIRS_FILE")" 2>/dev/null || true
  write_file_atomic "$PERF_HP_BOOT_SCRIPT" 0755 "root:root" <<EOF
#!/usr/bin/env bash
# Managed by vfio.sh — reboot-persistent hugepages re-reserve for
# ultimate-perf-tuned VMs. After a host reboot /proc/sys/vm/nr_hugepages resets
# to 0; this reads the registry of perf backup dirs and re-reserves the sum of
# the per-VM owned counts so hugepages-backed VMs can start without a manual
# --install-ultimate-perf-vm-tuning re-run. Standalone (never sources vfio.sh).
# Removed by: sudo vfio.sh --reset  (or sudo vfio.sh --reset-ultimate-perf-vm-tuning when no hugepages VMs remain)
set -o pipefail
CONF_FILE="/etc/vfio-gpu-passthrough.conf"
REGISTRY="$PERF_HP_DIRS_FILE"
NR_HUGEPAGES="/proc/sys/vm/nr_hugepages"
log() { printf '[vfio-perf-hugepages] %s\n' "\$*" >&2; }
[[ -f "\$REGISTRY" ]] || { log "no hugepages registry (\$REGISTRY); nothing to reserve."; exit 0; }
hp_size="\$(awk -F= '/^ULTIMATE_PERF_HUGEPAGES_SIZE=/{v=\$2; gsub(/"/,"",v); print v; exit}' "\$CONF_FILE" 2>/dev/null || true)"
hp_size="\${hp_size:-2048}"
[[ "\$hp_size" =~ ^[0-9]+\$ ]] || hp_size=2048
if (( hp_size >= 1048576 )); then
  log "WARN: configured hugepages size \${hp_size}KiB is 1GB — cannot reserve at runtime. Add 'hugepagesz=1G hugepages=N' to the kernel cmdline. Skipping."
  exit 0
fi
total=0
seen=""
while IFS= read -r dir; do
  [[ -n "\$dir" ]] || continue
  [[ -d "\$dir" ]] || continue
  case ":\$seen:" in *":\$dir:"*) continue ;; esac
  seen="\$seen:\$dir"
  for f in "\$dir"/*_perf_hugepages_owned.txt; do
    [[ -f "\$f" ]] || continue
    n="\$(cat "\$f" 2>/dev/null || echo 0)"
    [[ "\$n" =~ ^[0-9]+\$ ]] || n=0
    total=\$(( total + n ))
  done
done < "\$REGISTRY"
if (( total <= 0 )); then
  log "registry has no owned hugepage counts; nothing to reserve."
  exit 0
fi
cur="\$(cat "\$NR_HUGEPAGES" 2>/dev/null || echo 0)"
[[ "\$cur" =~ ^[0-9]+\$ ]] || cur=0
if (( cur >= total )); then
  log "host already has \$cur hugepages (>= \$total needed); nothing to do."
  exit 0
fi
log "re-reserving \$total hugepage(s) after reboot (host nr_hugepages: \$cur -> \$total)."
if ! printf '%s\n' "\$total" >"\$NR_HUGEPAGES" 2>/dev/null; then
  log "WARN: failed to write \$NR_HUGEPAGES."
  exit 0
fi
got="\$(cat "\$NR_HUGEPAGES" 2>/dev/null || echo 0)"
[[ "\$got" =~ ^[0-9]+\$ ]] || got=0
if (( got < total )); then
  log "WARN: host granted only \$got of \$total hugepage(s) (fragmented RAM at boot). Hugepages-backed VMs may fail to start. Reliable fix: add 'hugepages=\$total' to the kernel cmdline. Leaving the partial reservation in place."
  exit 0
fi
log "OK: reserved \$got hugepage(s) for ultimate-perf-tuned VMs."
exit 0
EOF
  write_file_atomic "$PERF_HP_BOOT_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=Re-reserve host hugepages for ultimate-perf-tuned VMs at boot
Documentation=man:vfio(8)
After=local-fs.target systemd-tmpfiles-setup.service
Before=virtqemud.service libvirtd.service
ConditionPathExists=$PERF_HP_DIRS_FILE

[Service]
Type=oneshot
ExecStart=$PERF_HP_BOOT_SCRIPT
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF
  run systemctl daemon-reload 2>/dev/null || true
  run systemctl enable "$_unit" 2>/dev/null || true
  # Run once now so the current boot is covered too (idempotent: the script
  # no-ops when the pool already satisfies the owned counts).
  run systemctl start "$_unit" 2>/dev/null || true
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Installed reboot-persistent hugepages re-reserve: $(_link "$PERF_HP_BOOT_SCRIPT")"
    note "    service: $(_link "$PERF_HP_BOOT_UNIT")"
  else
    say "  ✔ Installed reboot-persistent hugepages re-reserve: $PERF_HP_BOOT_SCRIPT"
    note "    service: $PERF_HP_BOOT_UNIT"
  fi
  note "After a host reboot this re-reserves nr_hugepages from the owned files so"
  note "hugepages-backed VMs start without a manual re-tune."
}

# R35: Remove + disable the reboot-persistent hugepages re-reserve service.
# Called by --reset-ultimate-perf-vm-tuning (when no owned files remain) and
# --reset. Best-effort.
remove_perf_hugepages_boot_service() {
  local _unit
  _unit="$(basename "$PERF_HP_BOOT_UNIT")"
  if command -v systemctl >/dev/null 2>&1; then
    run systemctl disable --now "$_unit" 2>/dev/null || true
    run systemctl daemon-reload 2>/dev/null || true
  fi
  run rm -f "$PERF_HP_BOOT_SCRIPT" "$PERF_HP_BOOT_UNIT" "$PERF_HP_DIRS_FILE" 2>/dev/null || true
}

# R35: Ultimate-performance VM XML tuning (stealth-safe). A SEPARATE, more
# aggressive perf layer than the basic perf subset bundled inside
# install_stealth_vm_tuning(). Applies maximum-throughput knobs to each shut-off
# guest-GPU VM while NEVER touching the stealth elements (vendor_id, kvm hidden,
# vmport, SMBIOS, e1000e NIC, disk serials, memballoon, hypervclock/TSC, QEMU
# -cpu/-smbios) — so a VM that was stealth-tuned stays stealth-tuned through a
# perf pass, and reverting perf (from the pre-perf XML backup, which still
# contains stealth) leaves stealth intact. Knobs: disk cache=none/io=native/
# discard=unmap + virtio-blk multiqueue queues; iothreads scaled to min(vcpu,4)
# with round-robin disk assignment; aggressive cputune pinning (vcpus to physical
# cores, emulator to a housekeeping core, iothreadpin) + numatune (ONLY when
# NUMA-safe: single node, or all pinned vCPUs fit one node — otherwise skipped
# so the VM never fails to start); CPU topology matching vCPU count + <cache
# mode='passthrough'/>; currentMemory=memory (no startup balloon, synergizes
# with stealth's memballoon=none); <pm> S3/S4 disabled. Hugepages is the ONLY
# host-touching knob and is OPT-IN (prompted default N, or --ultimate-perf-hugepages
# / --no-ultimate-perf-hugepages): when opted in, adds <memoryBacking><hugepages>
# and reserves the matching host nr_hugepages (prior value backed up, reverted by
# --reset-ultimate-perf-vm-tuning). Idempotent (python exit 3 = no changes). Only
# acts on shut-off VMs. AMD-gated (consistency with stealth tuning). Verifies the
# tuned XML with virt-xml-validate + prompts per VM before redefine.
install_ultimate_perf_vm_tuning() {
  if ! readable_file "$CONF_FILE"; then
    note "Missing $CONF_FILE; skipping ultimate-performance VM tuning."
    return 0
  fi
  local _guest_gpu _vendor
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -z "$_guest_gpu" ]]; then
    note "No GUEST_GPU_BDF in $CONF_FILE; skipping ultimate-performance VM tuning."
    return 0
  fi
  if [[ "${_vendor,,}" != "1002" ]]; then
    note "Guest GPU is not AMD; skipping ultimate-performance VM tuning (consistency with stealth tuning, which is AMD-gated)."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; skipping ultimate-performance VM tuning."
    return 0
  fi
  if ! have_cmd python3; then
    note "python3 not available; skipping ultimate-performance VM tuning (the XML patcher needs python3)."
    return 0
  fi

  say
  hdr "Ultimate-performance VM tuning (stealth-safe)"
  note "This applies maximum-throughput tuning to each shut-off VM that has the guest GPU:"
  note "  - disk: cache=none (O_DIRECT) + io=native (Linux AIO) + discard=unmap + virtio-blk multiqueue"
  note "    (disk perf knobs apply ONLY to virtio/scsi disks; SATA disks are skipped unless you
   opt in to the SATA->virtio conversion below — Windows needs the virtio-blk driver first)"
  note "  - iothreads scaled to min(vcpu,4); disks round-robin-assigned across iothreads"
  note "  - cputune: vCPUs pinned to physical cores, emulator to a housekeeping core, iothreadpin"
  note "  - numatune: memory strict pinning (ONLY when NUMA-safe; skipped otherwise so the VM still starts)"
  note "  - CPU topology matching vCPU count + <cache mode='passthrough'/>"
  note "  - currentMemory=memory (no startup balloon; synergizes with stealth's memballoon=none)"
  note "  - <pm> S3/S4 disabled (faster boot; avoids guest suspend breaking passthrough)"
  note "  - hugepages: OPT-IN (default N) — adds <memoryBacking> + reserves host nr_hugepages"
  note "STEALTH-SAFE: this NEVER touches vendor_id/kvm hidden/vmport/SMBIOS/e1000e NIC/"
  note "disk serials/memballoon/hypervclock/TSC/QEMU -cpu/-smbios. A stealth-tuned VM"
  note "stays stealth-tuned through a perf pass; reverting perf restores a backup that"
  note "still contains stealth. Only shut-off VMs are touched; running VMs are skipped."
  note "The tuned XML is validated (virt-xml-validate) and you are prompted before each redefine."
  say

  # Resolve backup dir (same fallback chain as stealth tuning, but a separate dir).
  local _backup_dir
  _backup_dir="$(awk -F= '/^ULTIMATE_PERF_VM_BACKUP_DIR=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _backup_dir="$(trim "${_backup_dir:-}")"
  if [[ -z "$_backup_dir" ]]; then
    _backup_dir="${BACKUP_DIR:-$HOME/Desktop}"
  fi
  if ! mkdir -p "$_backup_dir" 2>/dev/null || ! [[ -w "$_backup_dir" ]]; then
    _backup_dir="/var/lib/vfio-perf-vm/backups"
    mkdir -p "$_backup_dir" 2>/dev/null || true
    note "ULTIMATE_PERF_VM_BACKUP_DIR not writable; using $_backup_dir for VM XML backups."
  fi
  note "Ultimate-perf VM XML backups: $_backup_dir"

  # Hugepages opt-in decision. Default N (never touches host RAM on a plain run).
  local _hp_on=0
  if [[ "${ULTIMATE_PERF_HUGEPAGES_OVERRIDE:-}" == "1" ]]; then
    _hp_on=1
  elif [[ "${ULTIMATE_PERF_HUGEPAGES_OVERRIDE:-}" == "0" ]]; then
    _hp_on=0
  else
    say
    note "Hugepages is the ONLY knob that touches host RAM (reserves nr_hugepages). It is opt-in."
    note "With hugepages OFF, all the other perf knobs still apply and the VM stays startable."
    if prompt_yn "Reserve host hugepages for each tuned VM (adds <memoryBacking> + reserves nr_hugepages)?" N "Ultimate-perf hugepages"; then
      _hp_on=1
    fi
  fi
  local _hp_size
  _hp_size="$(awk -F= '/^ULTIMATE_PERF_HUGEPAGES_SIZE=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _hp_size="$(trim "${_hp_size:-}")"
  [[ "$_hp_size" =~ ^[0-9]+$ ]] || _hp_size="2048"

  # SATA->virtio-blk disk-bus conversion opt-in. Default N. The disk perf knobs
  # (cache=none/io=native/discard=unmap + multiqueue + iothread) only apply to
  # virtio/scsi disks, so a SATA boot disk gets NONE of them without this.
  # DANGEROUS: Windows needs the virtio-blk (viostor) driver installed FIRST or
  # it BSODs with INACCESSIBLE_BOOT_DEVICE on the next boot. The correct sequence:
  #   1. sudo vfio --install-virtio-win-guest-agent   (attaches the driver ISO)
  #   2. boot the VM, run virtio-win-guest-tools.exe inside Windows, shut down
  #   3. sudo vfio --install-ultimate-perf-vm-tuning --ultimate-perf-virtio-disk
  local _vd_on=0
  if [[ "${ULTIMATE_PERF_VIRTIO_DISK_OVERRIDE:-}" == "1" ]]; then
    _vd_on=1
  elif [[ "${ULTIMATE_PERF_VIRTIO_DISK_OVERRIDE:-}" == "0" ]]; then
    _vd_on=0
  else
    _vd_on="$(awk -F= '/^ULTIMATE_PERF_VIRTIO_DISK=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    _vd_on="$(trim "${_vd_on:-}")"
    [[ "$_vd_on" == "1" ]] || _vd_on=0
    if (( ! _vd_on )); then
      say
      note "Disk perf knobs (cache=none/io=native/discard=unmap + multiqueue + iothread) apply"
      note "ONLY to virtio/scsi disks. A SATA boot disk gets NONE of them."
      note "You can OPT IN to convert SATA disks to virtio-blk so the knobs apply."
      if (( ENABLE_COLOR )); then
        note "${C_BOLD}${C_RED}DANGER:${C_RESET} Windows needs the virtio-blk (viostor) driver installed FIRST"
      else
        note "DANGER: Windows needs the virtio-blk (viostor) driver installed FIRST"
      fi
      note "or it will BSOD with INACCESSIBLE_BOOT_DEVICE on the next boot."
      note "If you have NOT installed virtio-win-guest-tools in Windows yet, answer N."
      note "To prepare: sudo $SCRIPT_NAME --install-virtio-win-guest-agent, boot, run"
      note "virtio-win-guest-tools.exe inside Windows, shut down, THEN re-run with this."
      if prompt_yn "Convert SATA disks to virtio-blk on each tuned VM? (viostor must be installed in Windows first!)" N "Ultimate-perf virtio-disk"; then
        _vd_on=1
      fi
    fi
  fi

  # Read host CPU/NUMA topology once (exported to the python patcher). Defensive:
  # if unreadable, the patcher falls back to simple v->v cputune and skips numatune.
  local _host_cpus_csv _numa_csv _n _nid _cl
  _host_cpus_csv="$(lscpu -p=CPU 2>/dev/null | grep -vE '^(#|$)' | paste -sd, 2>/dev/null || true)"
  _numa_csv=""
  if [[ -d /sys/devices/system/node ]]; then
    for _n in /sys/devices/system/node/node*/cpulist; do
      [[ -f "$_n" ]] || continue
      _nid="$(basename "$(dirname "$_n")" | sed 's/^node//')"
      _cl="$(cat "$_n" 2>/dev/null || true)"
      [[ -n "$_cl" ]] || continue
      _numa_csv="${_numa_csv:+${_numa_csv};}${_nid}:${_cl}"
    done
  fi
  export VFIO_PERF_HOST_CPUS="$_host_cpus_csv"
  export VFIO_PERF_NUMA="$_numa_csv"
  export VFIO_PERF_HUGEPAGES="$_hp_on"
  export VFIO_PERF_HUGEPAGES_SIZE="$_hp_size"
  export VFIO_PERF_VIRTIO_DISK="$_vd_on"
  if [[ -n "$_host_cpus_csv" ]]; then
    note "Host CPU topology: $(awk -F, '{print NF}' <<<"$_host_cpus_csv" 2>/dev/null || echo '?') CPUs${_numa_csv:+, NUMA: $_numa_csv}"
  else
    note "Host topology unreadable; cputune will use simple v->v pinning and numatune will be skipped."
  fi

  local _updated=0 _skipped_running=0 _any_hp_reserved=0 _dom _xml _bdfs _state _tmp _backup_xml
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match in the XML OR in the live-attach VM list
    # (live-attach strips the GPU hostdev from the persistent XML, so a BDF
    # grep alone would miss an already-live-attach-configured VM).
    if ! _vm_is_guest_gpu_vm "$_dom" "$_xml"; then
      continue
    fi
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping ultimate-perf tuning. Shut it off and re-run."
      _skipped_running=1
      continue
    fi
    _tmp="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp"
    _backup_xml="$_backup_dir/${_dom}_perf_$(date +%Y%m%d-%H%M%S).xml"
    mkdir -p "$_backup_dir" 2>/dev/null || true
    cp "$_tmp" "$_backup_xml" 2>/dev/null || true
    # Hugepages decision for THIS VM (per-VM so a failed reservation on one VM
    # does not turn it off for the others):
    #   _hp_vm = 1  -> python adds <memoryBacking><hugepages> and we reserve host pages.
    #   _hp_vm = 0  -> python skips <memoryBacking>; all other perf knobs still apply.
    # RESERVE-FIRST: try the host reservation BEFORE the python patcher runs, so a
    # failed/short reservation (fragmented RAM, 1GB size, RAM-change recompute)
    # turns _hp_vm off and the VM is defined WITHOUT a mismatched <memoryBacking>
    # (it still starts). _reserve_host_hugepages_for_vm is RAM-change aware: it
    # recomputes the need from the CURRENT <memory> and adjusts the pool up/down,
    # persisting the count this VM owns. On a re-run where the VM already has
    # <hugepages> it re-reserves (instead of skipping) so a host-reboot reset of
    # nr_hugepages to 0 no longer silently breaks virsh start.
    local _hp_vm=0
    local _have_hp=0
    grep -Fq '<hugepages' <<<"$_xml" 2>/dev/null && _have_hp=1
    if (( _hp_on )); then
      _hp_vm=1
      if (( DRY_RUN )); then
        note "Dry run: would reserve host hugepages for '$_dom' (no nr_hugepages write)."
      else
        if _reserve_host_hugepages_for_vm "$_xml" "$_hp_size" "$_backup_dir" "$_dom"; then
          _any_hp_reserved=1 # reservation OK; _hp_vm stays 1
        else
          _hp_vm=0
          note "Hugepages reservation did not complete for '$_dom'; defining the VM WITHOUT <memoryBacking>hugepages (all other perf knobs still apply)."
        fi
      fi
    elif (( _have_hp )); then
      # Hugepages was opted OUT this run but the VM already has <hugepages> from a
      # prior run: keep the existing backing intact (do not strip it) and leave the
      # host reservation as-is. The python's VFIO_PERF_HUGEPAGES=0 means it will
      # NOT touch the memoryBacking block, so the existing hugepages survives.
      : # _hp_vm stays 0; python preserves the existing block
    fi
    export VFIO_PERF_HUGEPAGES="$_hp_vm"
    local _py_status=0
    python3 - "$_tmp" <<'PYEOF' || _py_status=$?
import sys, xml.etree.ElementTree as ET, os, re
QEMU_NS = 'http://libvirt.org/schemas/domain/qemu/1.0'
ET.register_namespace('qemu', QEMU_NS)
ET.register_namespace('libosinfo', 'http://libosinfo.org/xmlns/libvirt/domain/1.0')
path = sys.argv[1]
tree = ET.parse(path); root = tree.getroot()
domain_type = root.get('type')
if domain_type not in (None, 'kvm', 'qemu'):
    sys.stderr.write(f"Unsupported domain type: {domain_type}\n"); sys.exit(4)
changed = False

def parse_cpulist(s):
    out = []
    if not s: return out
    for part in str(s).split(','):
        part = part.strip()
        if not part: continue
        m = re.match(r'^(\d+)-(\d+)$', part)
        if m: out.extend(range(int(m.group(1)), int(m.group(2)) + 1))
        elif part.isdigit(): out.append(int(part))
    return out

def insert_after(parent, after_tag, new_el):
    kids = list(parent); idx = -1
    for i, c in enumerate(kids):
        if c.tag == after_tag: idx = i
    if idx < 0:
        parent.append(new_el)
    else:
        parent.insert(idx + 1, new_el)

def set_pin_idem(parent, tag, key_attr, key_val, attrs):
    # Set a keyed pin child idempotently; return True if added or changed.
    el = None
    for ch in parent:
        if ch.tag == tag and ch.get(key_attr) == str(key_val):
            el = ch; break
    if el is None:
        ET.SubElement(parent, tag, attrs); return True
    for k, v in attrs.items():
        if el.get(k) != v:
            el.set(k, v); return True
    return False

vcpu_el = root.find('vcpu')
vcpu_count = 0
if vcpu_el is not None and vcpu_el.text:
    try: vcpu_count = int(vcpu_el.text.strip())
    except ValueError: vcpu_count = 0
host_cpus = parse_cpulist(os.environ.get('VFIO_PERF_HOST_CPUS', ''))
if not host_cpus:
    host_cpus = list(range(os.cpu_count() or 4))
if vcpu_count < 1:
    vcpu_count = max(1, min(len(host_cpus), 4))

# --- currentMemory = memory (no startup balloon) ---
mem_el = root.find('memory')
if mem_el is not None and mem_el.text:
    mem_text = mem_el.text.strip()
    mem_unit = mem_el.get('unit', 'KiB')
    cur_el = root.find('currentMemory')
    if cur_el is None:
        cur_el = ET.Element('currentMemory'); cur_el.text = mem_text; cur_el.set('unit', mem_unit)
        insert_after(root, 'memory', cur_el); changed = True
    else:
        if (cur_el.text or '').strip() != mem_text:
            cur_el.text = mem_text; changed = True
        if cur_el.get('unit', 'KiB') != mem_unit:
            cur_el.set('unit', mem_unit); changed = True

# --- pm: disable S3/S4 ---
pm = root.find('pm')
if pm is None:
    pm = ET.Element('pm')
    if root.find('on_crash') is not None:
        insert_after(root, 'on_crash', pm)
    elif root.find('on_reboot') is not None:
        insert_after(root, 'on_reboot', pm)
    else:
        root.append(pm)
    changed = True
for tag in ('suspend-to-mem', 'suspend-to-disk'):
    el = None
    for ch in pm:
        if ch.tag == tag: el = ch; break
    if el is None:
        el = ET.SubElement(pm, tag); changed = True
    if el.get('enabled') != 'no':
        el.set('enabled', 'no'); changed = True

# --- iothreads scaling ---
target_iothreads = max(1, min(vcpu_count, 4))
iothreads_el = root.find('iothreads')
if iothreads_el is None:
    it = ET.Element('iothreads'); it.text = str(target_iothreads)
    insert_after(root, 'vcpu', it); changed = True
else:
    try: cur_it = int(iothreads_el.text.strip())
    except (ValueError, AttributeError): cur_it = 0
    if cur_it != target_iothreads:
        iothreads_el.text = str(target_iothreads); changed = True
n_iothreads = target_iothreads

# --- cpu: topology + cache passthrough (NEVER touch mode/features) ---
cpu = root.find('cpu')
if cpu is not None:
    sockets = 1; threads = 1; cores = vcpu_count
    if vcpu_count % 2 == 0 and vcpu_count >= 2:
        threads = 2; cores = vcpu_count // 2
    want = {'sockets': str(sockets), 'cores': str(cores), 'threads': str(threads)}
    topo = cpu.find('topology')
    if topo is None:
        topo = ET.Element('topology', want)
        anchor = None
        for c in cpu:
            if c.tag in ('model', 'vendor'): anchor = c
        if anchor is not None:
            cpu.insert(list(cpu).index(anchor) + 1, topo)
        else:
            cpu.insert(0, topo)
        changed = True
    else:
        for k, v in want.items():
            if topo.get(k) != v:
                topo.set(k, v); changed = True
    cache_el = cpu.find('cache')
    if cache_el is None:
        cache_el = ET.Element('cache', {'mode': 'passthrough'})
        t = cpu.find('topology')
        if t is not None:
            cpu.insert(list(cpu).index(t) + 1, cache_el)
        else:
            cpu.append(cache_el)
        changed = True
    elif cache_el.get('mode') != 'passthrough':
        cache_el.set('mode', 'passthrough'); changed = True

# --- cputune (aggressive pinning, defensive fallback) ---
reserve_emulator = host_cpus[0] if host_cpus else 0
vcpu_pool = [c for c in host_cpus if c != reserve_emulator]
if len(vcpu_pool) >= vcpu_count:
    pinned_vcpus = vcpu_pool[:vcpu_count]
    iothread_pool = vcpu_pool[vcpu_count:] or pinned_vcpus
else:
    pinned_vcpus = list(range(vcpu_count))
    iothread_pool = list(range(n_iothreads))

# NUMA safety: only add numatune if single node OR all pinned vCPUs fit one node.
numa_csv = os.environ.get('VFIO_PERF_NUMA', '')
nodes = {}
if numa_csv:
    for entry in numa_csv.split(';'):
        entry = entry.strip()
        if not entry or ':' not in entry: continue
        nid, cl = entry.split(':', 1)
        nodes[nid.strip()] = parse_cpulist(cl)
add_numatune = False
node_id_for_mem = None
if len(nodes) <= 1:
    if nodes:
        only_nid = list(nodes.keys())[0]
        only = list(nodes.values())[0]
        if all(c in only for c in pinned_vcpus):
            add_numatune = True; node_id_for_mem = only_nid
else:
    for nid, cl in nodes.items():
        if all(c in cl for c in pinned_vcpus):
            add_numatune = True; node_id_for_mem = nid; break

cputune = root.find('cputune')
if cputune is None:
    cputune = ET.Element('cputune')
    # Canonical libvirt domain order: cputune comes after <pm> (and the
    # on_poweroff/on_reboot/on_crash block), before <numatune>/<resource>/
    # <features>. Placing it after <clock> makes virt-xml-validate fail with
    # "Invalid sequence in interleave", so anchor on <pm> first.
    if root.find('pm') is not None:
        insert_after(root, 'pm', cputune)
    elif root.find('on_crash') is not None:
        insert_after(root, 'on_crash', cputune)
    elif root.find('clock') is not None:
        insert_after(root, 'clock', cputune)
    elif root.find('cpu') is not None:
        insert_after(root, 'cpu', cputune)
    else:
        root.append(cputune)
    changed = True
# Idempotent pin rebuild: update/add only what differs; drop stale pins for
# vcpus/iothreads outside our current range (e.g. after a vCPU count change).
for el in list(cputune.findall('vcpupin')):
    _v = el.get('vcpu')
    if _v is None or not _v.isdigit() or int(_v) >= vcpu_count:
        cputune.remove(el); changed = True
for v in range(vcpu_count):
    if set_pin_idem(cputune, 'vcpupin', 'vcpu', v, {'vcpu': str(v), 'cpuset': str(pinned_vcpus[v])}):
        changed = True
_emp = None
for ch in cputune:
    if ch.tag == 'emulatorpin': _emp = ch; break
if _emp is None:
    ET.SubElement(cputune, 'emulatorpin', {'cpuset': str(reserve_emulator)}); changed = True
elif _emp.get('cpuset') != str(reserve_emulator):
    _emp.set('cpuset', str(reserve_emulator)); changed = True
for el in list(cputune.findall('iothreadpin')):
    _it = el.get('iothread')
    if _it is None or not _it.isdigit() or int(_it) > n_iothreads:
        cputune.remove(el); changed = True
for i in range(n_iothreads):
    c = iothread_pool[i % len(iothread_pool)] if iothread_pool else reserve_emulator
    if set_pin_idem(cputune, 'iothreadpin', 'iothread', i + 1, {'iothread': str(i + 1), 'cpuset': str(c)}):
        changed = True

if add_numatune:
    numatune = root.find('numatune')
    if numatune is None:
        numatune = ET.Element('numatune')
        if root.find('cputune') is not None:
            insert_after(root, 'cputune', numatune)
        else:
            root.append(numatune)
        changed = True
    # numatune <memory> uses `nodeset` (NUMA node IDs, per libvirt RNG), NOT a
    # cpuset of CPU IDs, and has no `cellid` attr (cellid is for <memnode>).
    # Pin VM memory to the single NUMA node that holds all pinned vCPUs.
    # Idempotent: update only if mode/nodeset differ.
    want_mem_attrs = {'mode': 'strict', 'nodeset': str(node_id_for_mem)}
    _nm = None
    for ch in numatune:
        if ch.tag == 'memory': _nm = ch; break
    if _nm is None:
        ET.SubElement(numatune, 'memory', want_mem_attrs); changed = True
    else:
        for k, v in want_mem_attrs.items():
            if _nm.get(k) != v:
                _nm.set(k, v); changed = True

# --- SATA->virtio-blk disk-bus conversion (opt-in, DANGEROUS) ---
# The disk perf knobs below only apply to virtio/scsi disks. When opted in
# (VFIO_PERF_VIRTIO_DISK=1), convert each non-cdrom disk whose bus is NOT
# virtio/scsi to bus=virtio so the knobs apply: target dev sdX->vdX
# (collision-checked against existing vdX targets), bus->virtio, and drop the
# SATA/AHCI <address type='drive'> (bus-specific; libvirt reassigns a PCI
# address on define). Preserves boot/serial/source. Idempotent: a re-run skips
# disks already on virtio/scsi. DANGEROUS: Windows needs the virtio-blk
# (viostor) driver installed first or it BSODs with INACCESSIBLE_BOOT_DEVICE
# — the bash wrapper warns + gates this behind an opt-in prompt.
devices = root.find('devices')
if devices is not None and os.environ.get('VFIO_PERF_VIRTIO_DISK', '0') == '1':
    used_vd = set()
    for d in devices.findall('disk'):
        t = d.find('target')
        if t is not None and (t.get('dev', '') or '').startswith('vd'):
            used_vd.add(t.get('dev'))
    for disk in devices.findall('disk'):
        if disk.get('device', 'disk') == 'cdrom':
            continue
        target = disk.find('target')
        if target is None:
            continue
        bus = target.get('bus')
        if bus in ('virtio', 'scsi'):
            continue
        old_dev = target.get('dev', '')
        new_dev = None
        for i in range(26):
            cand = 'vd' + chr(ord('a') + i)
            if cand not in used_vd:
                new_dev = cand
                break
        if new_dev is None:
            sys.stderr.write(f"Cannot convert disk {old_dev}: no free vdX target\n")
            continue
        target.set('dev', new_dev)
        target.set('bus', 'virtio')
        used_vd.add(new_dev)
        addr = disk.find('address')
        if addr is not None and addr.get('type') == 'drive':
            disk.remove(addr)
        changed = True

# --- disk I/O perf ---
if devices is not None:
    disk_idx = 0
    for disk in devices.findall('disk'):
        if disk.get('device', 'disk') == 'cdrom':
            continue
        target = disk.find('target')
        bus = target.get('bus') if target is not None else None
        if bus not in ('virtio', 'scsi'):
            continue
        driver = disk.find('driver')
        if driver is None:
            driver = ET.Element('driver', {'name': 'qemu', 'type': 'raw'})
            disk.insert(0, driver); changed = True
        if driver.get('cache') != 'none':
            driver.set('cache', 'none'); changed = True
        if driver.get('io') != 'native':
            driver.set('io', 'native'); changed = True
        if driver.get('discard') != 'unmap':
            driver.set('discard', 'unmap'); changed = True
        if bus == 'virtio':
            want_q = str(vcpu_count)
            if driver.get('queues') != want_q:
                driver.set('queues', want_q); changed = True
        want_it = str((disk_idx % n_iothreads) + 1)
        if driver.get('iothread') != want_it:
            driver.set('iothread', want_it); changed = True
        disk_idx += 1

# --- hugepages (opt-in) ---
if os.environ.get('VFIO_PERF_HUGEPAGES', '0') == '1':
    hp_size = os.environ.get('VFIO_PERF_HUGEPAGES_SIZE', '2048')
    mb = root.find('memoryBacking')
    if mb is None:
        mb = ET.Element('memoryBacking')
        if root.find('currentMemory') is not None:
            insert_after(root, 'currentMemory', mb)
        elif root.find('memory') is not None:
            insert_after(root, 'memory', mb)
        else:
            root.append(mb)
        changed = True
    # hugepages/page + locked + nosharepages: idempotent (add/update only on diff).
    hp_el = mb.find('hugepages')
    if hp_el is None:
        hp_el = ET.SubElement(mb, 'hugepages'); changed = True
    _page = None
    for ch in hp_el:
        if ch.tag == 'page': _page = ch; break
    want_page = {'size': str(hp_size), 'unit': 'KiB'}
    if _page is None:
        ET.SubElement(hp_el, 'page', want_page); changed = True
    else:
        for k, v in want_page.items():
            if _page.get(k) != v:
                _page.set(k, v); changed = True
    for tag in ('locked', 'nosharepages'):
        if mb.find(tag) is None:
            ET.SubElement(mb, tag); changed = True

if not changed: sys.exit(3)
tree.write(path)
PYEOF
    # Hugepages rollback: reserve-first already wrote this VM's hugepages
    # ownership file + reserved the host pages. Roll them back ONLY on a path
    # where the VM will NOT be redefined with <memoryBacking>hugepages this run
    # (unsupported domain, patching failed, validate failed, user declined,
    # define failed). The already-tuned path (exit 3) and the SUCCESS path
    # (define succeeded) KEEP the ownership — the VM still has hugepages, so the
    # host pool must keep matching it. (The previous early-rollback fired on
    # _py_status != 3, which included the success exit 0, freeing the pages the
    # VM was just defined to demand — leaving the VM unstartable.)
    if (( _py_status == 3 )); then
      say "VM '$_dom' is already ultimate-perf tuned (no changes needed)."
      _updated=1
      rm -f "$_tmp"
      continue
    elif (( _py_status == 4 )); then
      note "WARN: VM '$_dom' has an unsupported domain type; skipping ultimate-perf tuning."
      if (( _hp_vm )) && (( ! DRY_RUN )); then _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"; fi
      rm -f "$_tmp"
      continue
    elif (( _py_status != 0 )); then
      note "WARN: ultimate-perf XML patching failed for '$_dom' (python exit $_py_status); skipping."
      if (( _hp_vm )) && (( ! DRY_RUN )); then _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"; fi
      rm -f "$_tmp"
      continue
    fi
    if ! virt-xml-validate "$_tmp" 2>/dev/null; then
      note "WARN: virt-xml-validate failed for tuned '$_dom'; skipping redefine (backup at $_backup_xml)."
      if (( _hp_vm )) && (( ! DRY_RUN )); then _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"; fi
      rm -f "$_tmp"
      continue
    fi
    say "Tuned XML for '$_dom' validates. Backup of original: $_backup_xml"
    if (( DRY_RUN )); then
      say "Dry run: showing diff (current -> tuned) for '$_dom' (no redefine will happen):"
      if command -v diff >/dev/null 2>&1; then
        diff -u "$_backup_xml" "$_tmp" || true
      else
        say "diff(1) not available; tuned XML is in $_tmp"
      fi
    fi
    if ! prompt_yn "Redefine VM '$_dom' with the ultimate-perf tuning now?" N "Ultimate-perf VM tuning"; then
      note "Skipped '$_dom' by user choice (tuned XML left in $_tmp; backup at $_backup_xml)."
      if (( _hp_vm )) && (( ! DRY_RUN )); then _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"; fi
      rm -f "$_tmp"
      continue
    fi
    local _define_rc=0 _define_err
    if (( ! DRY_RUN )); then
      _define_err="$(virsh -c qemu:///system define "$_tmp" 2>&1 >/dev/null)" || _define_rc=$?
    fi
    if (( _define_rc != 0 )); then
      note "ERROR: virsh define failed for '$_dom' (exit $_define_rc): $_define_err"
      note "The tuned XML is in $_tmp; backup at $_backup_xml. You can define it manually:"
      note "  virsh -c qemu:///system define $_tmp"
      if (( _hp_vm )) && (( ! DRY_RUN )); then _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"; fi
      rm -f "$_tmp"
      continue
    fi
    # Reservation already happened BEFORE the define (reserve-first). The define
    # succeeded, so the VM now has <memoryBacking>hugepages and the host pool
    # matches; keep the ownership file so a later re-run/RAM-change recompute is
    # accurate and a revert frees exactly these pages.
    say
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}${C_BOLD}✔ Ultimate-performance tuning applied to VM '$_dom'${C_RESET}"
    else
      say "✔ Ultimate-performance tuning applied to VM '$_dom'"
    fi
    if (( _vd_on )); then
      say "  ✔ disk bus converted SATA->virtio-blk (sdX->vdX) + cache=none + io=native + discard=unmap + multiqueue"
    else
      say "  ✔ disk cache=none + io=native + discard=unmap + virtio-blk multiqueue (virtio/scsi disks only)"
    fi
    say "  ✔ iothreads scaled + disks round-robin across iothreads"
    say "  ✔ cputune vCPU/emulator/iothread pinning (+ numatune when NUMA-safe)"
    say "  ✔ CPU topology + <cache mode='passthrough'/>"
    say "  ✔ currentMemory=memory (no startup balloon)"
    say "  ✔ <pm> S3/S4 disabled"
    if (( _hp_vm )); then
      local _disp=$(( _hp_size / 1024 ))
      say "  ✔ hugepages <memoryBacking> + host nr_hugepages reserved (${_disp}MiB = ${_hp_size}KiB pages)"
    elif (( _have_hp )); then
      say "  ✔ hugepages <memoryBacking> preserved (existing, not re-reserved this run)"
    fi
    say "  Backup of original XML: $_backup_xml"
    note "Restore with: sudo $SCRIPT_NAME --reset-ultimate-perf-vm-tuning  (or: virsh -c qemu:///system define $_backup_xml)"
    _updated=1
    rm -f "$_tmp"
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _updated )); then
    if (( _skipped_running )); then
      note "No VMs were tuned (running VMs must be shut off first). Shut off the VM and re-run."
    else
      note "No shut-off VMs with the guest GPU found; nothing to tune."
      note "Ensure a VM has the guest GPU attached (or is in the live-attach VM list) and re-run."
    fi
  fi
  # Install the reboot-persistent hugepages re-reserve service whenever there
  # is any perf-hugepages ownership: this run reserved (_any_hp_reserved) OR a
  # prior run's registry still lists owned files (covers upgrading an existing
  # hugepages setup that predates the boot service). Skipped in dry-run (no
  # reservation writes happen so _any_hp_reserved stays 0; the pre-existing
  # registry is left untouched and the service is not (re)installed).
  if (( ! DRY_RUN )) && { (( _any_hp_reserved )) || [[ -f "$PERF_HP_DIRS_FILE" ]]; }; then
    install_perf_hugepages_boot_service
  fi
}

# R35: Revert ultimate-performance VM tuning by redefining each guest-GPU VM from
# its most recent *_perf_*.xml backup, and restoring the host nr_hugepages that
# was reserved for it. Standalone mode (--reset-ultimate-perf-vm-tuning). Only
# acts on shut-off VMs (running VMs are skipped with a note). Verifies the backup
# XML with virt-xml-validate and prompts before redefining.
reset_ultimate_perf_vm_tuning() {
  if ! readable_file "$CONF_FILE"; then
    note "Missing $CONF_FILE; nothing to revert."
    return 0
  fi
  local _guest_gpu _vendor
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -z "$_guest_gpu" ]]; then
    note "No GUEST_GPU_BDF in $CONF_FILE; nothing to revert."
    return 0
  fi
  if ! have_cmd virsh; then
    note "virsh not available; cannot revert ultimate-performance VM tuning."
    return 0
  fi
  local _backup_dir
  _backup_dir="$(awk -F= '/^ULTIMATE_PERF_VM_BACKUP_DIR=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _backup_dir="$(trim "${_backup_dir:-}")"
  if [[ -z "$_backup_dir" ]]; then _backup_dir="${BACKUP_DIR:-$HOME/Desktop}"; fi
  if ! [[ -d "$_backup_dir" ]]; then
    _backup_dir="/var/lib/vfio-perf-vm/backups"
  fi
  say
  hdr "Revert ultimate-performance VM tuning (restore from backup XML)"
  note "This redefines each shut-off guest-GPU VM from its most recent"
  note "${_dom:-<vm>}_perf_*.xml backup in $_backup_dir (which still contains stealth),"
  note "and restores the host nr_hugepages that was reserved for it. Only shut-off"
  note "VMs are touched; running VMs are skipped."
  say
  local _reverted=0 _skipped_running=0 _dom _xml _bdfs _state _backup _newest
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match OR in the live-attach VM list (live-attach
    # strips the GPU hostdev, so a BDF grep alone misses a live-attach VM).
    if ! _vm_is_guest_gpu_vm "$_dom" "$_xml"; then
      continue
    fi
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping revert. Shut it off and re-run."
      _skipped_running=1
      continue
    fi
    _newest=""
    for _backup in "$_backup_dir/${_dom}_perf_"*.xml; do
      [[ -f "$_backup" ]] || continue
      if [[ -z "$_newest" || "$_backup" -nt "$_newest" ]]; then
        _newest="$_backup"
      fi
    done
    if [[ -z "$_newest" ]]; then
      note "No perf backup XML found for '$_dom' in $_backup_dir; skipping."
      continue
    fi
    if ! virt-xml-validate "$_newest" 2>/dev/null; then
      note "WARN: virt-xml-validate failed for backup '$_newest'; skipping revert of '$_dom'."
      continue
    fi
    say "Found backup for '$_dom': $_newest (validates)."
    if ! prompt_yn "Redefine VM '$_dom' from the pre-perf backup now?" N "Revert ultimate-perf VM tuning"; then
      note "Skipped '$_dom' by user choice."
      continue
    fi
    if (( ! DRY_RUN )); then
      virsh -c qemu:///system define "$_newest" 2>/dev/null
    fi
    say "Reverted VM '$_dom' from backup: $_newest"
    _restore_host_hugepages_for_vm "$_backup_dir" "$_dom"
    _reverted=1
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _reverted )); then
    if (( _skipped_running )); then
      note "No VMs were reverted (running VMs must be shut off first)."
    else
      note "No perf backups found for guest-GPU VMs; nothing to revert."
    fi
  fi
  # Remove the reboot-persistent hugepages re-reserve service once the last
  # perf-hugepages owned dir is gone. _restore_host_hugepages_for_vm calls
  # _unregister_perf_hugepages_dir, which deletes PERF_HP_DIRS_FILE when its
  # last owned file is cleaned up — so an empty/absent registry means no VM
  # still demands hugepages and the boot oneshot is no longer needed. Skipped
  # in dry-run so a dry-run revert does not uninstall the live service.
  if (( ! DRY_RUN )) && ! [[ -f "$PERF_HP_DIRS_FILE" ]]; then
    remove_perf_hugepages_boot_service
  fi
}

# R35: Report ultimate-performance VM tuning status for each guest-GPU VM (used
# by --detect and --verify). Checks for the perf markers (disk cache=none +
# io=native, cputune, pm disabled, optional hugepages) in the VM XML. Prints one
# status line per guest-GPU VM.
ultimate_perf_vm_tuning_status() {
  if ! readable_file "$CONF_FILE"; then return 0; fi
  local _guest_gpu _dom _xml _bdfs _has_cache _has_io _has_cputune _has_pm _has_hp
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/\"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 0
  have_cmd virsh || return 0
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    # Detect guest-GPU VMs: BDF match OR in the live-attach VM list (live-attach
    # strips the GPU hostdev, so a BDF grep alone misses a live-attach VM).
    _vm_is_guest_gpu_vm "$_dom" "$_xml" || continue
    _has_cache=0; _has_io=0; _has_cputune=0; _has_pm=0; _has_hp=0
    grep -Fq "cache='none'" <<<"$_xml" 2>/dev/null && _has_cache=1
    grep -Fq "io='native'" <<<"$_xml" 2>/dev/null && _has_io=1
    grep -Fq '<cputune>' <<<"$_xml" 2>/dev/null && _has_cputune=1
    grep -Fq "suspend-to-mem enabled='no'" <<<"$_xml" 2>/dev/null && _has_pm=1
    grep -Fq '<hugepages' <<<"$_xml" 2>/dev/null && _has_hp=1
    local _hp_marker=""
    (( _has_hp )) && _hp_marker=", hugepages"
    if (( _has_cache && _has_io && _has_cputune )); then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: VM '$_dom' is ultimate-perf tuned (disk cache=none/io=native, cputune pinning${_hp_marker})"
      else
        say "OK: VM '$_dom' is ultimate-perf tuned (disk cache=none/io=native, cputune pinning${_hp_marker})"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}INFO${C_RESET}: VM '$_dom' is NOT ultimate-perf tuned (use 'sudo $SCRIPT_NAME --install-ultimate-perf-vm-tuning')"
      else
        say "INFO: VM '$_dom' is NOT ultimate-perf tuned (use 'sudo $SCRIPT_NAME --install-ultimate-perf-vm-tuning')"
      fi
    fi
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
}

# Remove the reboot-FLR monitor service + script.
remove_reboot_flr_monitor() {
  if command -v systemctl >/dev/null 2>&1; then
    run systemctl disable --now vfio-reboot-flr.service 2>/dev/null || true
  fi
  run rm -f "$REBOOT_FLR_SCRIPT" "$REBOOT_FLR_UNIT" 2>/dev/null || true
  if command -v systemctl >/dev/null 2>&1; then
    run systemctl daemon-reload 2>/dev/null || true
  fi
}

# Remove the park-keepalive monitor service + script (dynamic-binding only),
# plus all its extensions: the post-resume hook, the udev-triggered one-shot
# check unit, the supplementary udev rule, and the persisted failure-streak
# state file.
remove_park_keepalive_monitor() {
  if command -v systemctl >/dev/null 2>&1; then
    run systemctl disable --now vfio-gpu-park-keepalive.service 2>/dev/null || true
    run systemctl disable --now vfio-gpu-park-keepalive-check.service 2>/dev/null || true
  fi
  run rm -f "$PARK_KEEPALIVE_SCRIPT" "$PARK_KEEPALIVE_UNIT" "$PARK_KEEPALIVE_CHECK_UNIT" \
           "$PARK_KEEPALIVE_RESUME_HOOK" "$PARK_KEEPALIVE_UDEV_RULE" "$PARK_KEEPALIVE_STATE_FILE" \
           2>/dev/null || true
  if have_cmd udevadm; then
    run udevadm control --reload-rules 2>/dev/null || true
  fi
  if command -v systemctl >/dev/null 2>&1; then
    run systemctl daemon-reload 2>/dev/null || true
  fi
}

# Two-tier check for whether a ROM dump belongs to the guest GPU at $2.
# Tier 1 (strict): parse the ROM's PCI Data Structure (PCIR), per the standard
# header layout:
#   offset 0x00: 0x55 0xAA                (ROM signature)
#   offset 0x18: 2-byte LE pointer to the PCIR structure
#   PCIR+0x00: 'PCIR' (4 ASCII bytes)     (PCI Data Structure signature)
#   PCIR+0x04: 2-byte LE Vendor ID
#   PCIR+0x06: 2-byte LE Device ID
# and compare against the GPU's live Vendor:Device ID (from config space).
# Tier 2 (fallback): real-world AMD ATOMBIOS dumps routinely leave the legacy
# PCIR pointer at 0 (verified empirically against an actual RX 9070 dump --
# the strict check alone would reject a perfectly valid, correctly-matching
# file). When PCIR is absent, confirm the file is a genuine AMD ATOMBIOS vbios
# via its signature string, then best-effort match its embedded human-readable
# model strings against RX-series model tokens parsed from the GPU's own
# `lspci` description (e.g. "RX9070" from "Radeon RX 9070/9070 XT/9070 GRE").
# This is weaker than a strict PCI ID match (it confirms "looks like the right
# GPU family", not the exact SKU/board), which is reflected in the printed
# description.
# Best-effort scan of a ROM's embedded human-readable identity, used to give
# an ALWAYS-informative "right number for that rom" on every no-match path
# below (not just the PCIR-mismatch case), so a mismatched/unrecognized dump
# never gets reported with just a bare "no match" -- the caller always has
# something concrete to compare/search with. Prints one line per distinct
# GPU-model-like token found (brand + model, e.g. "RX9070", "RTX4090",
# "GTX1080"), deduplicated, or nothing if none were found. Never fails.
_vbios_rom_scan_model_strings() {
  local _rom="$1"
  have_cmd strings || return 0
  strings -n 4 "$_rom" 2>/dev/null \
    | grep -oEi '(RX|RTX|GTX|GT|RADEON|GEFORCE|QUADRO|FIREPRO|VEGA|NAVI)[ _-]?[0-9]{2,5}[ _-]?(XT|TI|SUPER|GRE)?' \
    | tr -d ' _-' | tr '[:lower:]' '[:upper:]' | sort -u
  return 0
}

# Extract a ROM dump's embedded human-readable identity — the ATOMBIOS version
# string (e.g. "023.008.000.068.000001"), its compile date (e.g.
# "12/04/24,02:22:50" -> 2024-12-04, the field techpowerup lists as "Date
# compiled"), and the board PPID / board-part string (e.g. ASUS
# "TUF-RX9070-O16G-I3S" / "ASUS_G2951200_XT_16GB_APM7912_P"). This lets the
# matcher report the EXACT vBIOS version + board SKU a candidate dump carries
# (cross-checkable against a techpowerup listing by version+PPID) instead of
# just the GPU family token — the model token alone cannot distinguish e.g. an
# ASUS TUF OC from the white variant or a non-OC, which share the "RX9070"
# token but carry different subsystem device IDs / PPIDs / versions.
# Prints 4 pipe-delimited fields on stdout: "<ver>|<date>|<ppid>|<board>" (any
# field may be empty if not found in the dump). Never fails (pipefail-safe:
# each extraction is guarded with `|| true` and `strings` output is captured
# into a variable first, not piped live). Requires `strings`.
_vbios_rom_embedded_identity() {
  local _rom="$1" _s _ver _date _ppid _board
  if ! have_cmd strings; then
    printf '|||\n'
    return 0
  fi
  _s="$(strings -a -n 4 "$_rom" 2>/dev/null || true)"
  _ver="$(printf '%s\n' "$_s" | grep -oE 'ATOMBIOSBK-AMD VER[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+' | head -n1 | sed 's/^ATOMBIOSBK-AMD VER//' || true)"
  # The ATOMBIOS compile date is the bare "MM/DD/YY,hh:mm:ss" stamp that matches
  # techpowerup's "Date compiled" field. Several build stamps coexist in a dump
  # (PSP/GOP/ATOM); take the lexicographically latest (sort -u | tail -n1) since
  # the ATOM wrapper compile date is the most recent and the one TPU lists.
  _date="$(printf '%s\n' "$_s" | grep -oE '[0-9]{2}/[0-9]{2}/[0-9]{2},[0-9]{2}:[0-9]{2}:[0-9]{2}' | sort -u | tail -n1 || true)"
  _ppid="$(printf '%s\n' "$_s" | grep -oE 'PPID[A-Z0-9._-]+' | head -n1 | sed 's/^PPID//' || true)"
  _board="$(printf '%s\n' "$_s" | grep -oE 'ASUS_[A-Z0-9_]+' | head -n1 || true)"
  [[ -n "$_board" ]] || _board="$(printf '%s\n' "$_s" | grep -oE '115-[A-Z0-9]+' | head -n1 || true)"
  printf '%s|%s|%s|%s\n' "${_ver:-}" "${_date:-}" "${_ppid:-}" "${_board:-}"
  return 0
}

# Build an EXACT techpowerup vBIOS-collection deep link for the guest GPU at
# $1, derived ENTIRELY from live hardware detection (same technique as the
# rest of this feature) rather than any hardcoded example. techpowerup's
# vgabios search supports a "Device Id" filter of the form
# vendor-device-subvendor-subdevice (confirmed against real techpowerup URLs,
# e.g. ?did=10DE-2206-1043-87AC), which is the most precise possible search:
# it matches the exact GPU chip AND the exact board partner/SKU, not just a
# brand/model keyword guess. Reads vendor/device/subsystem_vendor/
# subsystem_device straight from sysfs. Prints the URL on stdout and returns
# 0, or returns 1 (no stdout) if any of the four IDs cannot be read.
_vbios_techpowerup_url() {
  local _bdf="$1"
  local _sys="/sys/bus/pci/devices/$_bdf" _ven _dev _subven _subdev
  [[ -d "$_sys" ]] || return 1
  _ven="$(cat "$_sys/vendor" 2>/dev/null || true)"; _ven="${_ven#0x}"
  _dev="$(cat "$_sys/device" 2>/dev/null || true)"; _dev="${_dev#0x}"
  _subven="$(cat "$_sys/subsystem_vendor" 2>/dev/null || true)"; _subven="${_subven#0x}"
  _subdev="$(cat "$_sys/subsystem_device" 2>/dev/null || true)"; _subdev="${_subdev#0x}"
  [[ -n "$_ven" && -n "$_dev" && -n "$_subven" && -n "$_subdev" ]] || return 1
  printf 'https://www.techpowerup.com/vgabios/?did=%s-%s-%s-%s\n' "${_ven^^}" "${_dev^^}" "${_subven^^}" "${_subdev^^}"
  return 0
}

# Best-effort resolver: fetch the techpowerup vgabios SEARCH page at $1 and
# extract the FIRST detail-page link + the exact download filename from the
# HTML, so the operator lands on ONE exact ROM instead of a list of duplicate
# uploads of the same BIOS (techpowerup commonly lists 2-3 re-uploads of the
# same dump for a given subsystem, identical version+date, which is confusing).
# Prints "<detail_url>|<filename>" on stdout and returns 0 on success, or
# returns 1 (no stdout) if the fetch fails, the page is unreachable, no
# detail link is found, or no HTTP client is available. Fully guarded for
# `set -euo pipefail`: every network call is wrapped in `|| true`, output is
# captured into a variable before grepping (no live pipe that pipefail can
# trip on), and a 6s timeout bounds the fetch so an unreachable host cannot
# stall the install. Non-fatal: the caller falls back to the raw search URL.
_vbios_techpowerup_resolve_detail() {
  local _search_url="$1" _html _detail _slug _fname
  [[ -n "$_search_url" ]] || return 1
  local _client=""
  if have_cmd curl; then
    _client=curl
  elif have_cmd wget; then
    _client=wget
  else
    return 1
  fi
  if [[ "$_client" == curl ]]; then
    _html="$(curl -sL --max-time 6 -A 'Mozilla/5.0 (vfio-helper)' "$_search_url" 2>/dev/null || true)"
  else
    _html="$(wget -q -T 6 -U 'Mozilla/5.0 (vfio-helper)' -O- "$_search_url" 2>/dev/null || true)"
  fi
  [[ -n "$_html" ]] || return 1
  # First detail-page link of the form vgabios/<id>/<slug> (e.g.
  # vgabios/274210/asus-rx9070-16384-241204). Dedup so re-uploads (_1, _2)
  # don't shadow the canonical first listing.
  _slug="$(printf '%s\n' "$_html" | grep -oE 'vgabios/[0-9]+/[a-z0-9-]+' | sort -u | head -n1 || true)"
  [[ -n "$_slug" ]] || return 1
  _detail="https://www.techpowerup.com/$_slug"
  # The download filename carried by that same listing (e.g.
  # Asus.RX9070.16384.241204.rom). Match the detail id so it belongs to the
  # same upload, not a sibling re-upload.
  local _did="${_slug#vgabios/}"; _did="${_did%%/*}"
  _fname="$(printf '%s\n' "$_html" | grep -oE "vgabios/${_did}/[A-Za-z0-9._-]+\.rom" | head -n1 || true)"
  _fname="$(basename "${_fname:-}")"
  printf '%s|%s\n' "$_detail" "${_fname:-}"
  return 0
}

# Best-effort list: fetch the techpowerup vgabios SEARCH page at $1 and return
# ALL subsystem-compatible detail listings as "<id>|<detail_url>|<filename>"
# per line on stdout. The ?did= filter in the search URL is built by
# _vbios_techpowerup_url from the guest GPU's exact 4-part Device Id
# (vendor-device-subvendor-subdevice), so EVERY listing on that page shares
# the guest GPU's exact subsystem by construction -- no per-listing subsystem
# check is needed (and the detail pages, which carry the subsystem/PPID/MD5,
# are bot-blocked and cannot be fetched automatically). This is the automated
# equivalent of the operator opening the techpowerup search and seeing every
# matching TUF/Prime/EVO upload for their exact card subsystem: the script
# lists them all so the operator can pick any (they are all the same BIOS
# content for that subsystem, just different re-uploads), download it, drop it
# into VBIOS/, and let the auto-repair handle the byte-swap.
# Returns 0 and prints >=1 line on success; returns 1 (no stdout) if the fetch
# fails, the page is unreachable, or no detail link is found. Same pipefail/
# timeout guards as _vbios_techpowerup_resolve_detail (6s timeout, capture-
# then-grep, every network call wrapped in `|| true`).
_vbios_techpowerup_list_all() {
  local _search_url="$1" _html _slug _did _fname _detail _slugs
  [[ -n "$_search_url" ]] || return 1
  local _client=""
  if have_cmd curl; then
    _client=curl
  elif have_cmd wget; then
    _client=wget
  else
    return 1
  fi
  if [[ "$_client" == curl ]]; then
    _html="$(curl -sL --max-time 6 -A 'Mozilla/5.0 (vfio-helper)' "$_search_url" 2>/dev/null || true)"
  else
    _html="$(wget -q -T 6 -U 'Mozilla/5.0 (vfio-helper)' -O- "$_search_url" 2>/dev/null || true)"
  fi
  [[ -n "$_html" ]] || return 1
  # All distinct detail slugs of the form vgabios/<id>/<slug> (e.g.
  # vgabios/274376/asus-rx9070-16384-241204-2). Dedup so the 2-3 re-uploads
  # of the same BIOS appear once each; sort -r so the newest id is first.
  _slugs="$(printf '%s\n' "$_html" | grep -oE 'vgabios/[0-9]+/[a-z0-9-]+' | sort -u || true)"
  [[ -n "$_slugs" ]] || return 1
  while IFS= read -r _slug; do
    [[ -n "$_slug" ]] || continue
    _did="${_slug#vgabios/}"; _did="${_did%%/*}"
    _detail="https://www.techpowerup.com/$_slug"
    _fname="$(printf '%s\n' "$_html" | grep -oE "vgabios/${_did}/[A-Za-z0-9._-]+\.rom" | head -n1 || true)"
    _fname="$(basename "${_fname:-}")"
    printf '%s|%s|%s\n' "$_did" "$_detail" "${_fname:-}"
  done <<<"$_slugs"
  return 0
}

# Two-tier check for whether a ROM dump belongs to the guest GPU at $2.
# Tier 1 (strict): parse the ROM's PCI Data Structure (PCIR), per the standard
# header layout:
#   offset 0x00: 0x55 0xAA                (ROM signature)
#   offset 0x18: 2-byte LE pointer to the PCIR structure
#   PCIR+0x00: 'PCIR' (4 ASCII bytes)     (PCI Data Structure signature)
#   PCIR+0x04: 2-byte LE Vendor ID
#   PCIR+0x06: 2-byte LE Device ID
# and compare against the GPU's live Vendor:Device ID (from config space).
# Tier 2 (fallback): real-world AMD ATOMBIOS dumps routinely leave the legacy
# PCIR pointer at 0 (verified empirically against an actual RX 9070 dump --
# the strict check alone would reject a perfectly valid, correctly-matching
# file). When PCIR is absent, confirm the file is a genuine AMD ATOMBIOS vbios
# via its signature string, then best-effort match its embedded human-readable
# model strings against RX-series model tokens parsed from the GPU's own
# `lspci` description (e.g. "RX9070" from "Radeon RX 9070/9070 XT/9070 GRE").
# This is weaker than a strict PCI ID match (it confirms "looks like the right
# GPU family", not the exact SKU/board), which is reflected in the printed
# description.
# Best-effort scan of a ROM's embedded human-readable identity, used to give
# identity (embedded PCI ID and/or embedded model strings via
# _vbios_rom_scan_model_strings) instead of a bare "no match", so the wrong
# dump is never a dead end -- there is always a concrete "number" to compare
# or search with.
# Prints a human-readable description of the match (or near-miss, to stderr)
# and returns 0 on match / 1 on no match or an unreadable/unrecognized file.
_vbios_rom_matches_gpu() {
  local _rom="$1" _bdf="$2"
  local _sig _ptr_le _ptr_dec _pcir_sig _ven_le _dev_le _ven _dev
  local _gpu_sys="/sys/bus/pci/devices/$_bdf" _gpu_cfg _gpu_ven _gpu_dev
  local _models
  if [[ ! -r "$_rom" ]]; then
    printf 'file is not readable\n' >&2
    return 1
  fi
  _sig="$(head -c 2 "$_rom" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ "$_sig" != "55aa" ]]; then
    _models="$(_vbios_rom_scan_model_strings "$_rom" | tr '\n' ',' | sed 's/,$//')"
    # Detect the techpowerup download byte-swap trap: techpowerup stores some
    # dumps with the first 2 bytes swapped (aa55 instead of 55aa), so a file
    # that LOOKS like the right BIOS (correct embedded model strings / version)
    # fails the PCI expansion ROM signature check and is unusable by vfio-pci
    # as-is. This is the exact failure seen downloading Asus.RX9070.16384.
    # 241204.rom from a techpowerup listing this script resolved — the listing
    # was correct but the download was byte-swapped. Point the operator at the
    # fix (dump your own card, or swap the first 2 bytes) instead of a bare
    # "not a valid option ROM dump" that hides the cause.
    if [[ "$_sig" == "aa55" ]]; then
      printf 'ROM signature is byte-swapped (first 2 bytes are aa 55, expected 55 aa) -- this is the techpowerup download format; the embedded BIOS looks like %s but vfio-pci cannot load a swapped ROM. Fix: dump your own card with amdvbflash/GPU-Z (recommended), or swap the first 2 bytes of this file.\n' "${_models:-an RX 9070 family BIOS}" >&2
    else
      printf 'missing the 55 AA PCI expansion ROM signature (not a valid option ROM dump); embedded model string(s) found: %s\n' "${_models:-none}" >&2
    fi
    return 1
  fi
  _gpu_cfg="$(head -c 4 "$_gpu_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ -z "$_gpu_cfg" || "$_gpu_cfg" == "ffffffff" ]]; then
    printf 'guest GPU config space is currently unreadable; cannot compare\n' >&2
    return 1
  fi
  _gpu_ven="${_gpu_cfg:2:2}${_gpu_cfg:0:2}"
  _gpu_dev="${_gpu_cfg:6:2}${_gpu_cfg:4:2}"

  _ptr_le="$(dd if="$_rom" bs=1 skip=24 count=2 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ -n "$_ptr_le" && "$_ptr_le" != "0000" ]]; then
    _ptr_dec="$(( 16#${_ptr_le:2:2}${_ptr_le:0:2} ))"
    _pcir_sig="$(dd if="$_rom" bs=1 skip="$_ptr_dec" count=4 2>/dev/null | tr -d '\0')"
    if [[ "$_pcir_sig" == "PCIR" ]]; then
      _ven_le="$(dd if="$_rom" bs=1 skip=$(( _ptr_dec + 4 )) count=2 2>/dev/null | od -An -tx1 | tr -d ' \n')"
      _dev_le="$(dd if="$_rom" bs=1 skip=$(( _ptr_dec + 6 )) count=2 2>/dev/null | od -An -tx1 | tr -d ' \n')"
      if [[ -n "$_ven_le" && -n "$_dev_le" ]]; then
        _ven="${_ven_le:2:2}${_ven_le:0:2}"; _dev="${_dev_le:2:2}${_dev_le:0:2}"
        if [[ "${_ven,,}" == "${_gpu_ven,,}" && "${_dev,,}" == "${_gpu_dev,,}" ]]; then
          printf 'PCI ID %s:%s (strict match, from ROM header)\n' "${_ven,,}" "${_dev,,}"
          return 0
        fi
        printf 'ROM header PCI ID is %s:%s -- does NOT match guest GPU %s:%s (this is the WRONG dump for this card)\n' "${_ven,,}" "${_dev,,}" "${_gpu_ven,,}" "${_gpu_dev,,}" >&2
        return 1
      fi
    fi
  fi

  # NOTE: capture `strings` output into a variable FIRST, then grep the
  # variable (not a live pipe). Piping `strings` directly into `grep -q`
  # breaks under `set -o pipefail` (active for the whole of vfio.sh): `grep
  # -q` exits as soon as it finds a match, which can close the pipe while
  # `strings` is still writing the rest of a multi-MB file, killing it with
  # SIGPIPE -- pipefail then reports that nonzero exit as the pipeline's
  # result even though grep genuinely found a match, so the whole ATOMBIOS
  # check would spuriously report "not found" on a real match (verified
  # empirically: this exact pattern silently broke against a real ROM dump).
  local _strings_out=""
  if have_cmd strings; then
    _strings_out="$(strings -n 4 "$_rom" 2>/dev/null || true)"
  fi
  if [[ "${_gpu_ven,,}" == "1002" ]] && grep -q 'AMD ATOMBIOS' <<<"$_strings_out"; then
    local _gpu_desc _rom_strings _tok _ident _iver _idate _ippid _iboard _extra
    _gpu_desc="$(have_cmd lspci && lspci -s "$_bdf" 2>/dev/null || true)"
    _rom_strings="$(tr -d ' ' <<<"$_strings_out" | tr '[:lower:]' '[:upper:]')"
    # Pull the dump's embedded vBIOS version + compile date + board PPID so the
    # match description names the EXACT version/SKU (cross-checkable on
    # techpowerup by version+PPID) instead of just the GPU family token.
    _ident="$(_vbios_rom_embedded_identity "$_rom")"
    IFS='|' read -r _iver _idate _ippid _iboard <<<"$_ident"
    _extra=""
    [[ -n "$_iver" ]]  && _extra+=" VER$_iver"
    [[ -n "$_idate" ]] && _extra+=" compiled $_idate"
    [[ -n "$_ippid" ]] && _extra+=", PPID $_ippid"
    [[ -n "$_iboard" ]] && _extra+=", board $_iboard"
    # Read the guest GPU's live subsystem (subsystem_vendor:subsystem_device)
    # so the family-match WARNING can name the exact subsystem this ROM was
    # NOT independently verified against. AMD ATOMBIOS dumps do NOT carry a
    # readable subsystem field (only the base vendor:device in the PCIR
    # header, which tier 1 already checked), so a tier-2 family match cannot
    # distinguish e.g. an ASUS TUF OC (1043:0614) from a Prime (1043:0618) or
    # Prime EVO (1043:062D) -- they all share 1002:7550 + the RX9070 token.
    # The script's _vbios_techpowerup_list_all search IS subsystem-filtered
    # (?did=...-subven-subdev), so a ROM obtained from that list is safe; a
    # ROM obtained any other way (manually dropped in) is NOT subsystem-
    # verified, and the operator must be told that instead of silently
    # accepting a possibly-wrong-subsystem dump.
    local _gpu_subven _gpu_subdev _gpu_sub
    _gpu_subven="$(cat "$_gpu_sys/subsystem_vendor" 2>/dev/null || true)"; _gpu_subven="${_gpu_subven#0x}"
    _gpu_subdev="$(cat "$_gpu_sys/subsystem_device" 2>/dev/null || true)"; _gpu_subdev="${_gpu_subdev#0x}"
    if [[ -n "$_gpu_subven" && -n "$_gpu_subdev" ]]; then
      _gpu_sub="${_gpu_subven,,}:${_gpu_subdev,,}"
    else
      _gpu_sub="<unreadable>"
    fi
    while read -r _tok; do
      [[ -n "$_tok" ]] || continue
      _tok="$(tr -d ' ' <<<"$_tok" | tr '[:lower:]' '[:upper:]')"
      if grep -Fq "$_tok" <<<"$_rom_strings"; then
        printf 'AMD ATOMBIOS dump, model token "%s" found%s (FAMILY-ONLY match: subsystem %s was NOT independently verified from this ROM -- AMD ATOMBIOS dumps carry no readable subsystem field. SAFE if you got this ROM from the listed downloads this script prints (they are subsystem-filtered); if you dropped it in manually, confirm it is for subsystem %s before relying on it)\n' "$_tok" "$_extra" "$_gpu_sub" "$_gpu_sub"
        return 0
      fi
    done < <(grep -oEi 'RX ?[0-9]{3,4} ?(XT|GRE)?' <<<"$_gpu_desc")
    _models="$(_vbios_rom_scan_model_strings "$_rom" | tr '\n' ',' | sed 's/,$//')"
    printf 'AMD ATOMBIOS dump for model(s) [%s]%s -- does NOT match the guest GPU ("%s"); likely the WRONG board/dump\n' "${_models:-none found}" "$_extra" "$_gpu_desc" >&2
    return 1
  fi

  _models="$(_vbios_rom_scan_model_strings "$_rom" | tr '\n' ',' | sed 's/,$//')"
  if [[ -n "$_models" ]]; then
    printf 'not a recognized AMD ATOMBIOS dump for this GPU; embedded model string(s) found: %s\n' "$_models" >&2
  else
    printf 'no embedded PCI ID and no recognizable GPU model strings found in this ROM\n' >&2
  fi
  return 1
}

# Auto-repair the techpowerup download byte-swap (first 2 bytes aa55 -> 55aa)
# into a temp copy and re-run the full matcher on the repaired copy. Returns 0
# and prints "<repaired_path>|<match_desc>" on stdout if the repaired copy
# matches the guest GPU at $2; returns 1 (no stdout) otherwise. SAFETY: the
# full _vbios_rom_matches_gpu identity check (tier-1 PCI ID or tier-2 ATOMBIOS
# family + PPID/board) runs on the repaired copy, so a WRONG-card ROM that
# merely happens to be aa55-swapped is never repaired-and-used -- only a ROM
# whose content actually belongs to this GPU is accepted. This makes
# techpowerup downloads directly usable: they are systematically byte-swapped
# in storage (verified across 3 different ASUS TUF RX 9070 OC uploads), but
# the embedded content is the correct BIOS for the matching subsystem.
# The repaired copy is written to a temp dir keeping the original basename so
# the caller can copy it to the runtime dir under the right name; the caller
# owns cleanup of the temp dir when _match_repaired is set.
_vbios_autorepair_byteswap() {
  local _rom="$1" _bdf="$2" _sig _fixed_dir _fixed _fdesc
  _sig="$(head -c 2 "$_rom" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  [[ "$_sig" == "aa55" ]] || return 1
  _fixed_dir="$(mktemp -d 2>/dev/null || true)"
  [[ -n "$_fixed_dir" ]] || return 1
  _fixed="$_fixed_dir/$(basename "$_rom")"
  { printf '\x55\xaa'; tail -c +3 "$_rom" 2>/dev/null; } >"$_fixed" 2>/dev/null || { rm -rf "$_fixed_dir" 2>/dev/null; return 1; }
  if _fdesc="$(_vbios_rom_matches_gpu "$_fixed" "$_bdf" 2>/dev/null)"; then
    printf '%s|%s\n' "$_fixed" "$_fdesc"
    return 0
  fi
  rm -rf "$_fixed_dir" 2>/dev/null || true
  return 1
}

# Dump the guest GPU's live option ROM from sysfs to a temp file and echo the
# temp path on stdout. The live ROM is what qemu/vfio-pci reads at VM start
# when no <rom file=.../> pin is set, so comparing a candidate *.rom file
# against it catches a dump that has the RIGHT embedded PCI ID (passes the
# matcher) but WRONG content -- the exact trap seen with a generic/
# mis-extracted tuf-gaming.rom that matched 1002:7550 in the header but was a
# garbage image (doubled 55 aa 55 signature, real image buried at 0x40000,
# different sha256 from the card's actual 116736-byte ROM), which gave a black
# screen when pinned. Best-effort: enabling the ROM BAR needs root and the
# device not exclusively held by a running VM's vfio-pci; on failure prints
# nothing and returns 1 (caller falls back to PCI-ID-only matching with a
# "live ROM comparison skipped" note). Caller owns cleanup of the temp file.
# $1 = BDF.
_vbios_dump_live_rom() {
  local _bdf="$1" _sys _sysrom _romf _sig
  _sys="/sys/bus/pci/devices/$_bdf"
  _sysrom="$_sys/rom"
  [[ -r "$_sysrom" ]] || return 1
  _romf="$(mktemp 2>/dev/null)" || return 1
  # Enable the ROM BAR (maps the option ROM into CPU MMIO), read it, disable.
  # Safe: the ROM BAR is separate from the guest framebuffer / VRAM MMIO
  # aperture, so reading it does not touch a running VM's display memory.
  if ! echo 1 >"$_sysrom" 2>/dev/null; then
    rm -f "$_romf" 2>/dev/null
    return 1
  fi
  cat "$_sysrom" >"$_romf" 2>/dev/null || true
  echo 0 >"$_sysrom" 2>/dev/null || true
  # Validate the dump is a real ROM (55aa signature), not empty/garbage.
  _sig="$(head -c 2 "$_romf" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ "$_sig" != "55aa" ]]; then
    rm -f "$_romf" 2>/dev/null
    return 1
  fi
  printf '%s\n' "$_romf"
  return 0
}

# Compare a candidate *.rom file ($1) against the guest GPU's live option ROM
# (already dumped to $2). Prints a verdict on stdout and returns 0 on an exact
# or padded byte match (safe to pin), 1 on a content mismatch (the file has the
# right PCI ID per the matcher but DIFFERENT bytes -- a wrong-SKU / garbage /
# different-version dump that would give a black screen if pinned). Verdict:
#   EXACT byte match ... -- safe to pin
#   PADDED byte match ... -- safe to pin (live ROM + trailing data)
#   BYTES DIFFER ... -- NOT safe to pin (risks a black screen / 0xffff)
_vbios_compare_rom_to_live() {
  local _file="$1" _live="$2"
  local _fsize _lsize _fsha _lsha
  [[ -r "$_file" && -r "$_live" ]] || return 1
  _fsize="$(stat -c%s "$_file" 2>/dev/null || echo 0)"
  _lsize="$(stat -c%s "$_live" 2>/dev/null || echo 0)"
  _fsha="$(sha256sum "$_file" 2>/dev/null | cut -d' ' -f1)"
  _lsha="$(sha256sum "$_live" 2>/dev/null | cut -d' ' -f1)"
  if [[ "$_fsha" == "$_lsha" ]]; then
    printf 'EXACT byte match to the card live ROM (%s bytes) -- safe to pin\n' "$_fsize"
    return 0
  fi
  # File larger than the live ROM: check if the live ROM is a prefix (a padded
  # dump -- common for ROM dumps zero-padded to a power-of-2 size).
  if (( _fsize > _lsize )); then
    local _fpre_sha
    _fpre_sha="$(head -c "$_lsize" "$_file" 2>/dev/null | sha256sum | cut -d' ' -f1)"
    if [[ "$_fpre_sha" == "$_lsha" ]]; then
      printf 'PADDED byte match (card live ROM %s bytes + trailing data to %s bytes) -- safe to pin\n' "$_lsize" "$_fsize"
      return 0
    fi
  fi
  printf 'BYTES DIFFER from the card live ROM (file %s bytes, live %s bytes) -- NOT safe to pin: this dump has the right PCI ID but wrong content (wrong SKU / garbage / different version); pinning it risks a black screen\n' "$_fsize" "$_lsize"
  return 1
}

# Print the byte-comparison verdict sub-note for a matched candidate. Used by
# verify_vbios_candidates() so each MATCHED dump also shows whether it is a
# BYTE match to the card's live ROM (green EXACT/PADDED = safe to pin) or has
# the right PCI ID but wrong content (red BYTES DIFFER = garbage / wrong-SKU,
# risks a black screen if pinned). $1 = candidate file (or repaired temp),
# $2 = live ROM dump path. No-op if $2 is empty (live ROM could not be read).
_vbios_print_live_rom_verdict() {
  local _file="$1" _live="$2" _bv
  [[ -n "$_live" ]] || return 0
  if _bv="$(_vbios_compare_rom_to_live "$_file" "$_live" 2>/dev/null)"; then
    if (( ENABLE_COLOR )); then
      note "    ${C_GREEN}✔ $_bv"
    else
      note "    + $_bv"
    fi
  else
    if (( ENABLE_COLOR )); then
      note "    ${C_RED}✖ $_bv"
    else
      note "    - $_bv"
    fi
  fi
}

# Print the full list of subsystem-compatible techpowerup vBIOS listings (the
# output of _vbios_techpowerup_list_all) as numbered `note` lines, so the
# operator sees every matching option when no local *.rom is available yet.
# $1 = the list blob ("<id>|<detail_url>|<filename>" per line), $2 = the
# 4-part techpowerup Device Id serial for the header line. No-op if the list
# is empty (e.g. the search page fetch failed / was offline).
_vbios_print_compatible_list() {
  local _list="${1:-}" _did="${2:-}" _ln _lid _lurl _lfname
  [[ -n "$_list" ]] || return 0
  _ln="$(printf '%s\n' "$_list" | grep -c . 2>/dev/null || true)"
  [[ "$_ln" =~ ^[0-9]+$ ]] || _ln=0
  (( _ln > 0 )) || return 0
  note "All ${_ln} compatible vBIOS listing(s) for your exact subsystem ${_did} (download any one, drop the *.rom into a VBIOS/ folder next to this script, then re-run -- this script AUTO-REPAIRS the techpowerup byte-swap):"
  while IFS='|' read -r _lid _lurl _lfname; do
    [[ -n "$_lid" ]] || continue
    note "  - TPU #${_lid}: ${_lfname:-<unknown filename>} -> ${_lurl}"
  done <<<"$_list"
}

# Auto-detect and pin a matching vBIOS ROM dump into the guest GPU's PCI
# hostdev, for every shut-off libvirt VM that has it attached (dynamic binding
# only). Rationale: at --bind-now time, QEMU/vfio-pci reads the GPU's option
# ROM live from sysfs, which can be unreliable after a reset (dmesg: "Invalid
# PCI ROM header signature: expecting 0xaa55, got 0xffff"), leaving the guest
# with a black screen even though the PCI device itself is alive and bound.
# Pinning a known-good dump via <rom file='...'/> avoids that live read.
#
# SAFETY: scans a VBIOS/ folder next to this script for *.rom files, reads
# each candidate's OWN embedded PCI Vendor:Device ID (see _vbios_rom_pci_id)
# and ONLY auto-selects a dump whose embedded ID matches the guest GPU's LIVE
# vendor:device ID (read straight from config space). This means the user
# never has to manually pick a file: unrelated/mismatched dumps are reported
# (with their embedded ID, so the user can share/search with it) but never
# used, so a wrong ROM can never be silently wired in. Instant on (no prompt)
# — mirrors the other dynamic-binding recovery features. Removed by
# --install-early-binding and by --reset (see remove_vbios_romfile).
install_vbios_romfile() {
  if ! readable_file "$CONF_FILE"; then
    note "Missing $CONF_FILE; skipping vBIOS ROM auto-injection."
    return 0
  fi
  local _guest_gpu
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 0
  if ! have_cmd virsh; then
    note "virsh not available; skipping vBIOS ROM auto-injection."
    return 0
  fi

  local _gpu_sys="/sys/bus/pci/devices/$_guest_gpu" _gpu_cfg _gpu_ven _gpu_dev _gpu_id
  if [[ ! -d "$_gpu_sys" ]]; then
    note "Guest GPU $_guest_gpu not present in sysfs; skipping vBIOS ROM auto-injection."
    return 0
  fi
  _gpu_cfg="$(head -c 4 "$_gpu_sys/config" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ -z "$_gpu_cfg" || "$_gpu_cfg" == "ffffffff" ]]; then
    note "Guest GPU $_guest_gpu config space is unreadable right now; skipping vBIOS ROM auto-injection (re-run once it is alive)."
    return 0
  fi
  _gpu_ven="${_gpu_cfg:2:2}${_gpu_cfg:0:2}"
  _gpu_dev="${_gpu_cfg:6:2}${_gpu_cfg:4:2}"
  _gpu_id="${_gpu_ven,,}:${_gpu_dev,,}"
  # Deep link + techpowerup Device Id serial derived ENTIRELY from live
  # hardware detection (vendor + device + subsystem vendor + subsystem device,
  # all read from sysfs) -- NOT a hardcoded example. See _vbios_techpowerup_url
  # for the exact match this gives on techpowerup (chip AND board partner/SKU,
  # not just a keyword).
  local _tpu_url _subven _subdev _tpu_did
  _tpu_url="$(_vbios_techpowerup_url "$_guest_gpu" 2>/dev/null || true)"
  [[ -n "$_tpu_url" ]] || _tpu_url="https://www.techpowerup.com/vgabios/"
  _subven="$(cat "$_gpu_sys/subsystem_vendor" 2>/dev/null || true)"; _subven="${_subven#0x}"
  _subdev="$(cat "$_gpu_sys/subsystem_device" 2>/dev/null || true)"; _subdev="${_subdev#0x}"
  if [[ -n "$_subven" && -n "$_subdev" ]]; then
    _tpu_did="${_gpu_ven^^}-${_gpu_dev^^}-${_subven^^}-${_subdev^^}"
  else
    _tpu_did="${_gpu_ven^^}-${_gpu_dev^^}"
  fi

  # Print the section header + the guest GPU's PCI ID + the techpowerup Device
  # Id serial + a deep link ONCE, up front, so EVERY path below (no VBIOS/
  # folder, no *.rom files, no candidate match, OR a successful match that says
  # "verify by eye") leaves the operator with the concrete serial + URL needed
  # to find/verify a dump. Without this, the skip paths only emitted quiet dim
  # `note` lines with no header, and the success path said "verify by eye" but
  # never printed the URL to actually do so.
  #
  # Best-effort: resolve the techpowerup SEARCH page to its first DETAIL page
  # + exact download filename so the operator lands on ONE exact ROM instead
  # of a list of 2-3 duplicate re-uploads of the same BIOS (identical
  # version+date, confusing to pick from). Non-fatal: if the fetch fails
  # (offline, timeout, page changed), fall back to the raw search URL.
  local _tpu_detail="" _tpu_fname="" _tpu_res
  _tpu_res="$(_vbios_techpowerup_resolve_detail "$_tpu_url" 2>/dev/null || true)"
  if [[ -n "$_tpu_res" ]]; then
    IFS='|' read -r _tpu_detail _tpu_fname <<<"$_tpu_res"
  fi
  # Best-effort: fetch ALL compatible detail listings from the search page so
  # the skip paths below (no VBIOS/ folder / no *.rom / no candidate match)
  # can show the operator every subsystem-matching option to download. The
  # ?did= filter guarantees every listing shares the guest GPU's exact 4-part
  # Device Id. Non-fatal; reused across all skip paths to avoid re-fetching.
  local _tpu_list=""
  _tpu_list="$(_vbios_techpowerup_list_all "$_tpu_url" 2>/dev/null || true)"
  say
  hdr "vBIOS ROM auto-injection (fixes a black screen from an unreliable live ROM read)"
  # GPU + lookup info block: color-keyed labels (cyan key, bold value) so the
  # operator can scan the identity + URLs at a glance instead of reading a wall
  # of same-style dim note lines.
  local _k _v
  _kv() { # _kv <key> <value> -- prints "  key: value" with a cyan key
    if (( ENABLE_COLOR )); then
      say "  ${C_CYAN}${1}${C_RESET}: ${C_BOLD}${2}${C_RESET}"
    else
      say "  ${1}: ${2}"
    fi
  }
  _kv "Guest GPU"        "$_guest_gpu"
  _kv "PCI ID"           "$_gpu_id (share this ID if you need to find/verify a vBIOS dump)"
  _kv "TPU Device Id"    "$_tpu_did"
  if [[ -n "$_tpu_detail" ]]; then
    _kv "Exact listing"    "$_tpu_detail"
    [[ -n "$_tpu_fname" ]] && _kv "Download filename" "$_tpu_fname  (save it as <name>.rom into VBIOS/ next to this script)"
    _kv "Search page"     "$_tpu_url (if the detail link is stale)"
    if (( ENABLE_COLOR )); then
      say "  ${C_YELLOW}CAVEAT${C_RESET}: techpowerup downloads are byte-swapped"
    else
      say "  CAVEAT: techpowerup downloads are byte-swapped"
    fi
    note "    (first 2 bytes aa55 instead of 55aa)."
    note "    This script AUTO-REPAIRS a swapped ROM whose embedded"
    note "    identity (version/PPID) matches your card, so a techpowerup"
    note "    download is usable directly."
    note "    If auto-repair is not possible, dump your own card with"
    note "    amdvbflash (Linux) or GPU-Z (Windows); compare the embedded"
    note "    version/PPID against this listing to confirm."
  else
    _kv "Find/verify at"  "$_tpu_url"
    note "  (could not auto-resolve the exact listing — the search page lists 2-3 duplicate uploads of the same BIOS; pick the one whose version matches your dump)"
  fi

  local _src_dir
  _src_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" && pwd)/VBIOS"
  local -a _candidates=()
  local _f
  while IFS= read -r -d '' _f; do
    _candidates+=("$_f")
  done < <(find "$_src_dir" -maxdepth 1 -iname '*.rom' -print0 2>/dev/null)
  # Dump the guest GPU's live option ROM from sysfs ONCE, up front (best-effort).
  # It serves TWO purposes: (1) byte-compare each PCI-ID-matched candidate
  # BEFORE pinning -- a BYTES-DIFFER candidate (right PCI ID, wrong content) is
  # SKIPPED, the exact tuf-gaming.rom garbage trap that gave a black screen; and
  # (2) the LIVE-ROM FALLBACK below: when NO candidate matches (no VBIOS/ folder,
  # no *.rom files, or all candidates skipped as wrong-content / wrong-card), pin
  # the card's OWN live sysfs ROM. That dump is byte-exact to what qemu reads
  # live on a cold start (when the OVMF/BIOS logo DOES show), and a pinned
  # <rom file=.../> is read by qemu from the FILE -- so it survives qemu's own
  # attach-time function-level reset that otherwise re-zeroes the ROM BAR
  # (0xffff) and leaves no OVMF/BIOS logo on shutdown->start / force-kill->start.
  # If the live ROM cannot be read (not root / device busy under a running VM),
  # _live_rom_skipped=1: the candidate loop falls back to PCI-ID-only matching,
  # and the decision block below skips with guidance (no fallback is possible
  # without a readable live ROM).
  local _live_rom="" _live_rom_skipped=0 _skipped_bytes=0 _skipped_nomatch=0 _bv
  _live_rom="$(_vbios_dump_live_rom "$_guest_gpu" 2>/dev/null || true)"
  if [[ -z "$_live_rom" ]]; then
    _live_rom_skipped=1
  fi
  # Match accumulators (_live_fallback marks the pinned file as the live-ROM
  # named-temp copy so the shared pin logic can clean it up after copying).
  local _match_file="" _match_desc="" _f_desc _f_name _match_err _match_repaired=0 _match_count=0 _live_fallback=0
  _match_err="$(mktemp)"
  # Candidates sub-header + one color-coded verdict line per *.rom (only when
  # there are candidates to verdict; with zero candidates this is skipped and the
  # decision block below handles the no-folder / no-files case directly).
  #   ✔ MATCH (green)          -- direct 55aa match + EXACT/PADDED byte match to the card live ROM
  #   ✔ MATCH (green, repaired) -- aa55 techpowerup download, auto-repaired + EXACT/PADDED byte match
  #   ⚠ SKIPPED (yellow)       -- right PCI ID but WRONG content (BYTES DIFFER from the card live ROM);
  #                              pinning it would give a black screen, so it is skipped + explained
  #   ✖ no match (red)          -- wrong card / not a ROM
  # The embedded identity (VER/PPID/board) follows on the same line so the
  # operator can see WHICH dump matched at a glance. If the live ROM cannot be
  # read (not root / device busy under a running VM), fall back to PCI-ID-only
  # matching with a skip note.
  if (( ${#_candidates[@]} > 0 )); then
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}Candidates in ${_src_dir}${C_RESET} (${#_candidates[@]}):"
    else
      say "Candidates in ${_src_dir} (${#_candidates[@]}):"
    fi
  fi
  for _f in "${_candidates[@]}"; do
    _f_name="$(basename "$_f")"
    if _f_desc="$(_vbios_rom_matches_gpu "$_f" "$_guest_gpu" 2>"$_match_err")"; then
      # PCI-ID match. Gate on the live-ROM byte comparison before counting it.
      if (( _live_rom_skipped )); then
        if (( ENABLE_COLOR )); then
          say "  ${C_GREEN}✔ MATCH${C_RESET}: ${C_BOLD}$_f_name${C_RESET}"
          note "    $_f_desc"
          note "    ${C_YELLOW}(live ROM byte-comparison skipped — could not read sysfs ROM; run as root with the VM shut off to verify content)${C_RESET}"
        else
          say "  ✔ MATCH: $_f_name"
          note "    $_f_desc"
          note "    (live ROM byte-comparison skipped — could not read sysfs ROM; run as root with the VM shut off to verify content)"
        fi
        _match_count=$((_match_count+1))
        if [[ -z "$_match_file" ]]; then
          _match_file="$_f"
          _match_desc="$_f_desc"
          _match_repaired=0
        fi
      elif _bv="$(_vbios_compare_rom_to_live "$_f" "$_live_rom" 2>/dev/null)"; then
        # EXACT or PADDED byte match -- safe to pin.
        if (( ENABLE_COLOR )); then
          say "  ${C_GREEN}✔ MATCH${C_RESET}: ${C_BOLD}$_f_name${C_RESET}"
          note "    $_f_desc"
          note "    ${C_GREEN}✔ $_bv${C_RESET}"
        else
          say "  ✔ MATCH: $_f_name"
          note "    $_f_desc"
          note "    + $_bv"
        fi
        _match_count=$((_match_count+1))
        if [[ -z "$_match_file" ]]; then
          _match_file="$_f"
          _match_desc="$_f_desc"
          _match_repaired=0
        fi
      else
        # BYTES DIFFER -- right PCI ID but wrong content. SKIP pinning this
        # candidate and explain why, so the operator knows their dump is bad
        # (not that the script silently refused or the card is broken).
        _skipped_bytes=$((_skipped_bytes+1))
        if (( ENABLE_COLOR )); then
          say "  ${C_YELLOW}⚠ SKIPPED${C_RESET} (right PCI ID, wrong content): ${C_BOLD}$_f_name${C_RESET}"
          note "    $_f_desc"
          note "    ${C_RED}✖ $_bv${C_RESET}"
          note "    ${C_YELLOW}Pinning this dump would give a black screen (no OVMF/BIOS logo), so it was skipped. Dump your own card with amdvbflash (Linux) or GPU-Z (Windows), or download a subsystem-matching dump from the listings above, then re-run.${C_RESET}"
        else
          say "  SKIPPED (right PCI ID, wrong content): $_f_name"
          note "    $_f_desc"
          note "    - $_bv"
          note "    Pinning this dump would give a black screen (no OVMF/BIOS logo), so it was skipped. Dump your own card with amdvbflash (Linux) or GPU-Z (Windows), or download a subsystem-matching dump from the listings above, then re-run."
        fi
      fi
    else
      # Byte-swap auto-repair: techpowerup downloads are systematically
      # aa55-swapped on the first 2 bytes, but the embedded content is usually
      # the correct BIOS for the matching subsystem. Swap the first 2 bytes
      # back into a temp copy and re-run the full matcher (which re-checks the
      # embedded identity) -- if the repaired copy matches, use it so a
      # techpowerup download works without the user having to dump their own
      # card. SAFETY: the matcher's tier-1/tier-2 identity check runs on the
      # repaired copy, so a wrong-card ROM is never repaired-and-used.
      local _repair_res _repair_path _repair_desc
      if _repair_res="$(_vbios_autorepair_byteswap "$_f" "$_guest_gpu" 2>/dev/null)"; then
        IFS='|' read -r _repair_path _repair_desc <<<"$_repair_res"
        # PCI-ID match on the repaired copy. Gate on the live-ROM byte comparison
        # (compare the REPAIRED temp, which is what would actually be pinned).
        if (( _live_rom_skipped )); then
          if (( ENABLE_COLOR )); then
            say "  ${C_GREEN}✔ MATCH${C_RESET} ${C_YELLOW}(auto-repaired)${C_RESET}: ${C_BOLD}$_f_name${C_RESET}"
            note "    $_repair_desc"
            note "    ${C_YELLOW}(live ROM byte-comparison skipped — could not read sysfs ROM)${C_RESET}"
          else
            say "  ✔ MATCH (auto-repaired): $_f_name"
            note "    $_repair_desc"
            note "    (live ROM byte-comparison skipped — could not read sysfs ROM)"
          fi
          _match_count=$((_match_count+1))
          if [[ -z "$_match_file" ]]; then
            _match_file="$_repair_path"
            _match_desc="$_repair_desc (auto-repaired from byte-swapped $_f_name)"
            _match_repaired=1
          else
            rm -f "$_repair_path" 2>/dev/null || true
            rmdir "$(dirname "$_repair_path")" 2>/dev/null || true
          fi
        elif _bv="$(_vbios_compare_rom_to_live "$_repair_path" "$_live_rom" 2>/dev/null)"; then
          if (( ENABLE_COLOR )); then
            say "  ${C_GREEN}✔ MATCH${C_RESET} ${C_YELLOW}(auto-repaired)${C_RESET}: ${C_BOLD}$_f_name${C_RESET}"
            note "    $_repair_desc"
            note "    ${C_GREEN}✔ $_bv${C_RESET}"
          else
            say "  ✔ MATCH (auto-repaired): $_f_name"
            note "    $_repair_desc"
            note "    + $_bv"
          fi
          _match_count=$((_match_count+1))
          if [[ -z "$_match_file" ]]; then
            _match_file="$_repair_path"
            _match_desc="$_repair_desc (auto-repaired from byte-swapped $_f_name)"
            _match_repaired=1
          else
            rm -f "$_repair_path" 2>/dev/null || true
            rmdir "$(dirname "$_repair_path")" 2>/dev/null || true
          fi
        else
          # Repaired copy has right PCI ID but wrong content -- SKIP + clean up temp.
          _skipped_bytes=$((_skipped_bytes+1))
          rm -f "$_repair_path" 2>/dev/null || true
          rmdir "$(dirname "$_repair_path")" 2>/dev/null || true
          if (( ENABLE_COLOR )); then
            say "  ${C_YELLOW}⚠ SKIPPED${C_RESET} (right PCI ID, wrong content): ${C_BOLD}$_f_name${C_RESET} ${C_YELLOW}(auto-repaired)${C_RESET}"
            note "    $_repair_desc"
            note "    ${C_RED}✖ $_bv${C_RESET}"
            note "    ${C_YELLOW}Pinning this dump would give a black screen (no OVMF/BIOS logo), so it was skipped. Dump your own card with amdvbflash (Linux) or GPU-Z (Windows), or download a subsystem-matching dump from the listings above, then re-run.${C_RESET}"
          else
            say "  SKIPPED (right PCI ID, wrong content): $_f_name (auto-repaired)"
            note "    $_repair_desc"
            note "    - $_bv"
            note "    Pinning this dump would give a black screen (no OVMF/BIOS logo), so it was skipped. Dump your own card with amdvbflash (Linux) or GPU-Z (Windows), or download a subsystem-matching dump from the listings above, then re-run."
          fi
        fi
      else
        # No PCI-ID match (wrong card / not a valid ROM / byte-swap repair
        # also failed). SKIP pinning this candidate and explain why, so the
        # operator knows their dump is for the wrong GPU (or not a ROM at all)
        # instead of wondering why nothing got injected.
        _skipped_nomatch=$((_skipped_nomatch+1))
        local _nomatch_reason
        _nomatch_reason="$(cat "$_match_err" 2>/dev/null || echo "not a recognized GPU vBIOS dump")"
        if (( ENABLE_COLOR )); then
          say "  ${C_RED}✖ SKIPPED${C_RESET} (does not match the guest GPU): ${C_BOLD}$_f_name${C_RESET}"
          note "    $_nomatch_reason"
          note "    ${C_YELLOW}This dump is NOT for your guest GPU (PCI ID $_gpu_id), so it was skipped to avoid pinning a wrong-card ROM. Use a dump whose embedded PCI ID is $_gpu_id (dump your own card, or download a subsystem-matching dump from the listings above), then re-run.${C_RESET}"
        else
          say "  SKIPPED (does not match the guest GPU): $_f_name"
          note "    $_nomatch_reason"
          note "    This dump is NOT for your guest GPU (PCI ID $_gpu_id), so it was skipped to avoid pinning a wrong-card ROM. Use a dump whose embedded PCI ID is $_gpu_id (dump your own card, or download a subsystem-matching dump from the listings above), then re-run."
        fi
      fi
    fi
  done
  rm -f "$_match_err" 2>/dev/null || true

  if [[ -z "$_match_file" && -n "$_live_rom" ]]; then
    # LIVE-ROM FALLBACK: no candidate matched (no VBIOS/ folder, no *.rom files,
    # or every candidate was skipped as wrong-content / wrong-card), BUT the
    # card's own live sysfs ROM was dumped successfully. Pin THAT -- it is
    # byte-exact to what qemu reads live on a cold start (when the OVMF/BIOS
    # logo DOES show), and a pinned <rom file=.../> is read by qemu from the
    # FILE, so it survives qemu's own attach-time function-level reset that
    # otherwise re-zeroes the ROM BAR (0xffff) and leaves no OVMF/BIOS logo on
    # shutdown->start / force-kill->start. This is the "inject your own ROM"
    # path, automated: works with no VBIOS/ folder at all, and rescues a setup
    # whose only dump is garbage. The named temp below is copied to the stable
    # runtime path by the shared pin logic after this block, then cleaned up via
    # _live_fallback. (_match_count stays 0 here, so the >1 REFUSED check below
    # is a no-op for the fallback.)
    local _live_basename="live-$_guest_gpu.rom"
    local _live_named_dir
    _live_named_dir="$(mktemp -d 2>/dev/null || true)"
    if [[ -n "$_live_named_dir" && -f "$_live_rom" ]] \
      && cp -f "$_live_rom" "$_live_named_dir/$_live_basename" 2>/dev/null; then
      _match_file="$_live_named_dir/$_live_basename"
      _match_desc="dumped from the card's live sysfs ROM (byte-exact copy; immune to qemu's attach-time reset that otherwise zeroes the ROM BAR -> 0xffff -> no OVMF/BIOS logo)"
      _match_repaired=0
      _live_fallback=1
      rm -f "$_live_rom" 2>/dev/null || true
      say
      local _live_size _live_sig
      _live_size="$(stat -c%s "$_match_file" 2>/dev/null || echo 0)"
      _live_sig="$(head -c 2 "$_match_file" 2>/dev/null | od -An -tx1 | tr -d ' \n')"
      if (( ENABLE_COLOR )); then
        say "  ${C_YELLOW}⚠ No matching candidate in VBIOS/${C_RESET} — dumping the card's LIVE ROM as the pinned file:"
      else
        say "  WARN: No matching candidate in VBIOS/ — dumping the card's LIVE ROM as the pinned file:"
      fi
      if [[ "$_live_sig" == "55aa" ]]; then
        if (( ENABLE_COLOR )); then
          note "    ${C_GREEN}✔ Live ROM dumped${C_RESET}: $_live_size bytes, valid 55aa signature (this is the same GOP ROM qemu reads on a cold start, when the logo DOES show)"
          note "    ${C_GREEN}✔ EXACT byte match to the card live ROM${C_RESET} -- safe to pin"
        else
          note "    + Live ROM dumped: $_live_size bytes, valid 55aa signature (this is the same GOP ROM qemu reads on a cold start, when the logo DOES show)"
          note "    + EXACT byte match to the card live ROM -- safe to pin"
        fi
      else
        if (( ENABLE_COLOR )); then
          note "    ${C_YELLOW}⚠ Live ROM dumped${C_RESET}: $_live_size bytes, signature $_live_sig (unexpected -- pinning anyway as the byte-exact live copy)"
        else
          note "    ! Live ROM dumped: $_live_size bytes, signature $_live_sig (unexpected -- pinning anyway as the byte-exact live copy)"
        fi
      fi
      note "    Pinning this byte-exact copy so qemu reads it from the file instead of the live sysfs ROM —"
      note "    immune to qemu's attach-time reset that otherwise zeroes the ROM BAR -> 0xffff -> no OVMF/BIOS logo on shutdown->start / force-kill->start."
      if (( _skipped_bytes > 0 )); then
        if (( ENABLE_COLOR )); then
          note "    ${C_YELLOW}($_skipped_bytes candidate(s) in VBIOS/ had the right PCI ID but WRONG content and were skipped — pinning the card's live ROM instead.)${C_RESET}"
        else
          note "    ($_skipped_bytes candidate(s) in VBIOS/ had the right PCI ID but WRONG content and were skipped — pinning the card's live ROM instead.)"
        fi
      elif (( _skipped_nomatch > 0 )); then
        if (( ENABLE_COLOR )); then
          note "    ${C_YELLOW}($_skipped_nomatch candidate(s) in VBIOS/ do NOT match the guest GPU and were skipped — pinning the card's live ROM instead.)${C_RESET}"
        else
          note "    ($_skipped_nomatch candidate(s) in VBIOS/ do NOT match the guest GPU and were skipped — pinning the card's live ROM instead.)"
        fi
      fi
      # Fall through to the shared pin + XML-wire logic below.
    else
      # mktemp -d or the copy failed: clean up any partial temp and fall through
      # to the skip-with-guidance path below (do not pretend a fallback was set up).
      if [[ -n "$_live_named_dir" ]]; then
        rm -f "$_live_named_dir/$_live_basename" 2>/dev/null || true
        rmdir "$_live_named_dir" 2>/dev/null || true
      fi
    fi
  fi

  if [[ -z "$_match_file" ]]; then
    # No candidate matched AND the live-ROM fallback was not set up (either the
    # live ROM could not be read, or the named-temp copy failed). Skip with
    # guidance so the operator knows exactly why nothing was pinned and what to
    # do next. The 5 branches below cover every "no candidate" cause and each
    # prints the full subsystem-compatible techpowerup listing to download.
    if [[ ! -d "$_src_dir" ]]; then
      if (( ENABLE_COLOR )); then
        say "  ${C_YELLOW}⚠ WARN${C_RESET}: no VBIOS/ folder next to $SCRIPT_NAME; vBIOS ROM auto-injection skipped (no dump to pin)."
      else
        say "  WARN: no VBIOS/ folder next to $SCRIPT_NAME; vBIOS ROM auto-injection skipped (no dump to pin)."
      fi
      note "       Dump your own card with amdvbflash (Linux) or GPU-Z (Windows) and drop the *.rom into a VBIOS/ folder next to this script, then re-run — OR re-run as root with the VM shut off so the live-ROM fallback can pin the card's own ROM automatically."
      _vbios_print_compatible_list "$_tpu_list" "$_tpu_did"
      rm -f "$_live_rom" 2>/dev/null || true
      return 0
    fi
    if (( ${#_candidates[@]} == 0 )); then
      if (( ENABLE_COLOR )); then
        say "  ${C_YELLOW}⚠ WARN${C_RESET}: no *.rom files found in $_src_dir; vBIOS ROM auto-injection skipped (no dump to pin)."
      else
        say "  WARN: no *.rom files found in $_src_dir; vBIOS ROM auto-injection skipped (no dump to pin)."
      fi
      note "       Dump your own card with amdvbflash (Linux) or GPU-Z (Windows) and drop the *.rom into $_src_dir, then re-run — OR re-run as root with the VM shut off so the live-ROM fallback can pin the card's own ROM automatically."
      _vbios_print_compatible_list "$_tpu_list" "$_tpu_did"
      rm -f "$_live_rom" 2>/dev/null || true
      return 0
    fi
    if (( _skipped_bytes > 0 )); then
      # A candidate matched the PCI ID but had wrong content (BYTES DIFFER) and
      # was skipped -- give a clearer message than the generic "no match" so the
      # operator knows their dump is bad, not that no dump matched.
      if (( ENABLE_COLOR )); then
        say "  ${C_YELLOW}⚠ WARN${C_RESET}: $_skipped_bytes candidate(s) matched the guest GPU PCI ID ($_gpu_id) but had WRONG content (BYTES DIFFER from the card live ROM) and were SKIPPED to avoid a black screen."
      else
        say "  WARN: $_skipped_bytes candidate(s) matched the guest GPU PCI ID ($_gpu_id) but had WRONG content (BYTES DIFFER from the card live ROM) and were SKIPPED to avoid a black screen."
      fi
      note "       vBIOS ROM auto-injection was skipped this run. Replace the bad dump(s) in $_src_dir with a clean one (dump your own card with amdvbflash/GPU-Z, or download a subsystem-matching dump from the listings below), then re-run — OR re-run as root with the VM shut off so the live-ROM fallback can pin the card's own ROM automatically."
      _vbios_print_compatible_list "$_tpu_list" "$_tpu_did"
      rm -f "$_live_rom" 2>/dev/null || true
      return 0
    fi
    if (( _skipped_nomatch > 0 )); then
      # No candidate matched the guest GPU PCI ID at all (wrong card / not a
      # valid ROM). Explain WHY nothing was pinned so the operator knows their
      # dump is for the wrong GPU, not that the script silently did nothing.
      if (( ENABLE_COLOR )); then
        say "  ${C_YELLOW}⚠ WARN${C_RESET}: $_skipped_nomatch candidate(s) in $_src_dir do NOT match the guest GPU (PCI ID $_gpu_id) and were SKIPPED to avoid pinning a wrong-card ROM."
      else
        say "  WARN: $_skipped_nomatch candidate(s) in $_src_dir do NOT match the guest GPU (PCI ID $_gpu_id) and were SKIPPED to avoid pinning a wrong-card ROM."
      fi
      note "       vBIOS ROM auto-injection was skipped this run. Add a *.rom dump whose embedded PCI ID is $_gpu_id to $_src_dir (dump your own card with amdvbflash/GPU-Z, or download a subsystem-matching dump from the listings below), then re-run — OR re-run as root with the VM shut off so the live-ROM fallback can pin the card's own ROM automatically."
      note "       (techpowerup Device Id $_tpu_did — find/verify at: $_tpu_url)"
      _vbios_print_compatible_list "$_tpu_list" "$_tpu_did"
      rm -f "$_live_rom" 2>/dev/null || true
      return 0
    fi
    # Defensive fallback: _match_file empty with no skip counters incremented
    # should not be reachable (every non-matching candidate increments
    # _skipped_nomatch, and every PCI-ID match either sets _match_file or
    # increments _skipped_bytes), but keep a clear message just in case a
    # future logic change introduces a gap.
    if (( ENABLE_COLOR )); then
      say "  ${C_YELLOW}⚠ WARN${C_RESET}: no candidate ROM could be pinned for the guest GPU (PCI ID $_gpu_id); nothing auto-injected."
    else
      say "  WARN: no candidate ROM could be pinned for the guest GPU (PCI ID $_gpu_id); nothing auto-injected."
    fi
    note "       Add a *.rom dump for this exact GPU to $_src_dir and re-run to enable this automatically."
    note "       (techpowerup Device Id $_tpu_did — find/verify at: $_tpu_url)"
    _vbios_print_compatible_list "$_tpu_list" "$_tpu_did"
    rm -f "$_live_rom" 2>/dev/null || true
    return 0
  fi
  rm -f "$_live_rom" 2>/dev/null || true
  # RESTRICTION: only ONE vBIOS may be pinned per graphics card. If more than
  # one candidate matched (common: several techpowerup re-uploads + the
  # operator's own dump dropped into VBIOS/), REFUSE to pin -- pinning an
  # arbitrary "first" match is a footgun (filesystem order is not guaranteed,
  # and a wrong-subsystem family-only false positive could be wired in). Force
  # the operator to keep exactly one and re-run. The rest of the dynamic
  # binding install still completes; only the vBIOS pin is skipped this run.
  if (( _match_count > 1 )); then
    if (( ENABLE_COLOR )); then
      say "${C_RED}✖ REFUSED${C_RESET}: only ONE vBIOS is allowed per graphics card, but $_match_count candidates in $_src_dir matched the guest GPU ($_guest_gpu)."
    else
      say "REFUSED: only ONE vBIOS is allowed per graphics card, but $_match_count candidates in $_src_dir matched the guest GPU ($_guest_gpu)."
    fi
    note "       vBIOS ROM auto-injection was SKIPPED this run to avoid pinning an ambiguous match."
    note "       Keep exactly ONE matching *.rom in $_src_dir (prefer a clean 55aa dump, or one techpowerup download this script auto-repairs) and delete the rest, then re-run:"
    note "         sudo $SCRIPT_NAME --install-dynamic-binding"
    note "       (The rest of the dynamic binding setup is unaffected; only the vBIOS pin is skipped.)"
    # Clean up any auto-repaired temp copy (or live-ROM fallback named temp)
    # from the matched candidate so we do not leak a temp dir when refusing.
    # (_live_fallback is normally unreachable here since the fallback path has
    # _match_count=0, but the guard is cheap insurance against a future leak.)
    if (( _match_repaired )) || (( _live_fallback )); then
      rm -f "$_match_file" 2>/dev/null || true
      rmdir "$(dirname "$_match_file")" 2>/dev/null || true
    fi
    return 0
  fi
  say
  if (( ENABLE_COLOR )); then
    say "${C_GREEN}✔ Pinned vBIOS${C_RESET}: ${C_BOLD}$(basename "$_match_file")${C_RESET}"
    note "  $_match_desc"
  else
    say "✔ Pinned vBIOS: $(basename "$_match_file")"
    note "  $_match_desc"
  fi

  if (( ! DRY_RUN )); then
    mkdir -p "$VBIOS_RUNTIME_DIR" 2>/dev/null || true
  fi
  local _rom_runtime
  _rom_runtime="$VBIOS_RUNTIME_DIR/$(basename "$_match_file")"
  if (( ! DRY_RUN )); then
    run cp -f "$_match_file" "$_rom_runtime"
    run chmod 0644 "$_rom_runtime"
  fi
  if (( ENABLE_COLOR )) && [[ -e "$_rom_runtime" ]]; then
    say "  ${C_CYAN}Installed to${C_RESET}: $(_link "$_rom_runtime")"
  else
    say "  Installed to: $_rom_runtime"
  fi
  # If the match was an auto-repaired temp copy (not the original candidate),
  # clean up the temp dir now that the repaired content has been copied to the
  # stable runtime path.
  if (( _match_repaired )); then
    rm -f "$_match_file" 2>/dev/null || true
    rmdir "$(dirname "$_match_file")" 2>/dev/null || true
  fi
  # If the pinned file was the LIVE-ROM fallback's named temp copy (not an
  # original candidate and not a byte-swap repair), clean up its temp dir now
  # that the byte-exact content has been copied to the stable runtime path.
  if (( _live_fallback )); then
    rm -f "$_match_file" 2>/dev/null || true
    rmdir "$(dirname "$_match_file")" 2>/dev/null || true
  fi

  local _updated=0 _skipped_running=0 _dom _xml _bdfs _state _tmp
  local _gpu_dom_hex _gpu_bus_hex _gpu_slot_fn _gpu_slot_hex _gpu_fn_hex
  IFS=: read -r _gpu_dom_hex _gpu_bus_hex _gpu_slot_fn <<<"$_guest_gpu"
  _gpu_slot_hex="${_gpu_slot_fn%.*}"
  _gpu_fn_hex="${_gpu_slot_fn#*.}"
  while IFS= read -r _dom; do
    [[ -n "$_dom" ]] || continue
    _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
    [[ -n "$_xml" ]] || continue
    _bdfs="$(printf '%s' "$_xml" | awk '
      /<hostdev/ { in_hostdev=1; is_pci=0 }
      in_hostdev && /type=.pci./ { is_pci=1 }
      in_hostdev && is_pci && /<address/ {
        line=$0; dom=""; bus=""; slot=""; fn=""
        if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
        if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
        if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
        if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
        if (dom != "" && bus != "" && slot != "" && fn != "") {
          while (length(dom) < 4) dom = "0" dom
          while (length(bus) < 2) bus = "0" bus
          while (length(slot) < 2) slot = "0" slot
          printf "%s:%s:%s.%s\n", dom, bus, slot, fn
        }
      }
      /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
    ')"
    if ! grep -Fixq "$_guest_gpu" <<<"$_bdfs" 2>/dev/null; then
      continue
    fi
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); skipping vBIOS ROM injection. Shut it off and re-run to update it."
      _skipped_running=1
      continue
    fi
    _tmp="$(mktemp)"
    printf '%s\n' "$_xml" >"$_tmp"
    local _py_status=0
    python3 - "$_tmp" "$_gpu_bus_hex" "$_gpu_slot_hex" "$_gpu_fn_hex" "$_rom_runtime" <<'PYEOF' || _py_status=$?
import sys, xml.etree.ElementTree as ET
path, want_bus, want_slot, want_fn, romfile = sys.argv[1:6]
def norm(h): return format(int(h, 16), 'x')
want_bus, want_slot, want_fn = norm(want_bus), norm(want_slot), norm(want_fn)
tree = ET.parse(path); root = tree.getroot()
changed = False
found = False
for hostdev in root.findall('.//hostdev'):
    if hostdev.get('type') != 'pci':
        continue
    source = hostdev.find('source')
    if source is None:
        continue
    addr = source.find('address')
    if addr is None:
        continue
    bus = norm(addr.get('bus', '0x0'))
    slot = norm(addr.get('slot', '0x0'))
    fn = norm(addr.get('function', '0x0'))
    if (bus, slot, fn) != (want_bus, want_slot, want_fn):
        continue
    found = True
    rom = hostdev.find('rom')
    if rom is None:
        rom = ET.Element('rom')
        # Schema order inside <hostdev> is source, rom, address (guest-side) —
        # insert right after <source>.
        hostdev.insert(list(hostdev).index(source) + 1, rom)
        changed = True
    if rom.get('file') != romfile:
        rom.set('file', romfile); changed = True
    break
if not found:
    sys.exit(4)
if not changed:
    sys.exit(3)
tree.write(path)
PYEOF
    if (( _py_status == 3 )); then
      say "VM '$_dom' already has this vBIOS ROM wired in (no changes needed)."
      _updated=1
      rm -f "$_tmp"
      continue
    elif (( _py_status == 4 )); then
      note "WARN: could not locate the guest GPU's hostdev in '$_dom' XML; skipping."
      rm -f "$_tmp"
      continue
    elif (( _py_status != 0 )); then
      note "WARN: vBIOS ROM XML patching failed for '$_dom' (python exit $_py_status); skipping."
      rm -f "$_tmp"
      continue
    fi
    if ! virt-xml-validate "$_tmp" 2>/dev/null; then
      note "WARN: virt-xml-validate failed for '$_dom' after adding the vBIOS rom; skipping redefine."
      rm -f "$_tmp"
      continue
    fi
    local _define_rc=0 _define_err=""
    if (( ! DRY_RUN )); then
      _define_err="$(virsh -c qemu:///system define "$_tmp" 2>&1 >/dev/null)" || _define_rc=$?
    fi
    if (( _define_rc != 0 )); then
      note "ERROR: virsh define failed for '$_dom' (exit $_define_rc): $_define_err"
      rm -f "$_tmp"
      continue
    fi
    say "Wired vBIOS ROM into VM '$_dom' — next boot uses the pinned dump ($_rom_runtime) instead of the live sysfs ROM read."
    _updated=1
    rm -f "$_tmp"
  done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
  if (( ! _updated )); then
    if (( _skipped_running )); then
      note "No VMs were updated (running VMs must be shut off first). Shut off the VM and re-run."
    else
      note "No shut-off VMs with the guest GPU found; nothing to update."
    fi
  fi
}

# Remove the vBIOS ROM auto-injection: strips <rom file='...'/> from the guest
# GPU's hostdev in every shut-off guest-GPU VM, but ONLY when that rom file
# path is inside VBIOS_RUNTIME_DIR (never touches a user's own manually
# configured romfile), then removes the runtime copy.
remove_vbios_romfile() {
  if readable_file "$CONF_FILE" && have_cmd virsh; then
    local _guest_gpu
    _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    if [[ -n "$_guest_gpu" ]]; then
      local _dom _xml _bdfs _state _tmp
      local _gpu_dom_hex _gpu_bus_hex _gpu_slot_fn _gpu_slot_hex _gpu_fn_hex
      IFS=: read -r _gpu_dom_hex _gpu_bus_hex _gpu_slot_fn <<<"$_guest_gpu"
      _gpu_slot_hex="${_gpu_slot_fn%.*}"
      _gpu_fn_hex="${_gpu_slot_fn#*.}"
      while IFS= read -r _dom; do
        [[ -n "$_dom" ]] || continue
        _xml="$(virsh -c qemu:///system dumpxml "$_dom" 2>/dev/null || true)"
        [[ -n "$_xml" ]] || continue
        grep -Fq "$VBIOS_RUNTIME_DIR/" <<<"$_xml" 2>/dev/null || continue
        _bdfs="$(printf '%s' "$_xml" | awk '
          /<hostdev/ { in_hostdev=1; is_pci=0 }
          in_hostdev && /type=.pci./ { is_pci=1 }
          in_hostdev && is_pci && /<address/ {
            line=$0; dom=""; bus=""; slot=""; fn=""
            if (match(line, /domain=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^domain=./,"",s); sub(/^0x/,"",s); dom=s }
            if (match(line, /bus=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^bus=./,"",s); sub(/^0x/,"",s); bus=s }
            if (match(line, /slot=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^slot=./,"",s); sub(/^0x/,"",s); slot=s }
            if (match(line, /function=.0x[0-9a-fA-F]+/)) { s=substr(line,RSTART,RLENGTH); sub(/^function=./,"",s); sub(/^0x/,"",s); fn=s }
            if (dom != "" && bus != "" && slot != "" && fn != "") {
              while (length(dom) < 4) dom = "0" dom
              while (length(bus) < 2) bus = "0" bus
              while (length(slot) < 2) slot = "0" slot
              printf "%s:%s:%s.%s\n", dom, bus, slot, fn
            }
          }
          /<\/hostdev>/ { in_hostdev=0; is_pci=0 }
        ')"
        grep -Fixq "$_guest_gpu" <<<"$_bdfs" 2>/dev/null || continue
    _state="$(LC_ALL=C virsh -c qemu:///system domstate "$_dom" 2>/dev/null || echo "")"
    if [[ "$_state" != "shut off" ]]; then
      note "WARN: VM '$_dom' is '$_state' (not shut off); leaving its vBIOS ROM pin in place. Shut it off and re-run --reset / --install-early-binding to remove it."
          continue
        fi
        _tmp="$(mktemp)"
        printf '%s\n' "$_xml" >"$_tmp"
        local _py_status=0
        python3 - "$_tmp" "$_gpu_bus_hex" "$_gpu_slot_hex" "$_gpu_fn_hex" "$VBIOS_RUNTIME_DIR/" <<'PYEOF' || _py_status=$?
import sys, xml.etree.ElementTree as ET
path, want_bus, want_slot, want_fn, romdir = sys.argv[1:6]
def norm(h): return format(int(h, 16), 'x')
want_bus, want_slot, want_fn = norm(want_bus), norm(want_slot), norm(want_fn)
tree = ET.parse(path); root = tree.getroot()
changed = False
for hostdev in root.findall('.//hostdev'):
    if hostdev.get('type') != 'pci':
        continue
    source = hostdev.find('source')
    if source is None:
        continue
    addr = source.find('address')
    if addr is None:
        continue
    bus = norm(addr.get('bus', '0x0'))
    slot = norm(addr.get('slot', '0x0'))
    fn = norm(addr.get('function', '0x0'))
    if (bus, slot, fn) != (want_bus, want_slot, want_fn):
        continue
    rom = hostdev.find('rom')
    if rom is not None and (rom.get('file') or '').startswith(romdir):
        hostdev.remove(rom); changed = True
    break
if not changed:
    sys.exit(3)
tree.write(path)
PYEOF
        if (( _py_status == 0 )) && (( ! DRY_RUN )); then
          virsh -c qemu:///system define "$_tmp" 2>/dev/null || true
          note "Removed vBIOS ROM pin from VM '$_dom'."
        fi
        rm -f "$_tmp"
      done < <(virsh -c qemu:///system list --all --name 2>/dev/null)
    fi
  fi
  run rm -rf "$VBIOS_RUNTIME_DIR" 2>/dev/null || true
}

ensure_graphics_daemon_deployment_safety() {
  # if a unit exists without its daemon script, disable and remove the stale unit.
  local changed=0
  local cond_line="ConditionPathExists=$GRAPHICS_DAEMON_SCRIPT"

  if [[ -f "$GRAPHICS_DAEMON_UNIT" && ! -f "$GRAPHICS_DAEMON_SCRIPT" ]]; then
    note "Detected incomplete graphics daemon deployment (unit present, script missing)."
    if have_cmd systemctl; then
      run systemctl disable --now vfio-graphics-protocold.service 2>/dev/null || true
    fi
    run rm -f "$GRAPHICS_DAEMON_WANTS_LINK" 2>/dev/null || true
    run rm -f "$GRAPHICS_DAEMON_UNIT" 2>/dev/null || true
    changed=1
  fi

  if [[ -f "$GRAPHICS_DAEMON_UNIT" ]] && ! grep -Fqx "$cond_line" "$GRAPHICS_DAEMON_UNIT"; then
    backup_file "$GRAPHICS_DAEMON_UNIT"
    if (( ! DRY_RUN )); then
      local tmp
      tmp="$(mktemp)"
      awk -v cond="$cond_line" '
        {
          print
          if ($0 ~ /^ConditionPathExists=\/etc\/vfio-gpu-passthrough\.conf$/) {
            print cond
          }
        }
      ' "$GRAPHICS_DAEMON_UNIT" >"$tmp"
      install -m 0644 -o root -g root "$tmp" "$GRAPHICS_DAEMON_UNIT"
      rm -f "$tmp" || true
    fi
    changed=1
  fi

  if (( changed )) && have_cmd systemctl; then
    run systemctl daemon-reload 2>/dev/null || true
  fi
}
install_graphics_protocol_daemon() {
  local daemon_interval="${1:-${GRAPHICS_DAEMON_INTERVAL_OVERRIDE:-$GRAPHICS_DAEMON_INTERVAL_DEFAULT}}"
  local desktop_pair watchdog_user watchdog_home watchdog_group watchdog_log
  if [[ ! "$daemon_interval" =~ ^[0-9]+$ ]] || (( 10#$daemon_interval < 1 || 10#$daemon_interval > 3600 )); then
    daemon_interval="$GRAPHICS_DAEMON_INTERVAL_DEFAULT"
  fi
  desktop_pair="$(resolve_desktop_user_home 2>/dev/null || true)"
  watchdog_user="root"
  watchdog_home="/home"
  watchdog_group="root"
  if [[ -n "$desktop_pair" ]]; then
    watchdog_user="${desktop_pair%%$'\t'*}"
    watchdog_home="${desktop_pair#*$'\t'}"
    watchdog_group="$(id -gn "$watchdog_user" 2>/dev/null || true)"
    [[ -n "$watchdog_group" ]] || watchdog_group="$watchdog_user"
  fi
  if [[ -n "$watchdog_home" && -d "$watchdog_home" && "$watchdog_home" != "/home" ]]; then
    watchdog_log="$watchdog_home/.local/state/vfio-graphics-protocol/watchdog.log"
  else
    watchdog_log="/home/vfio-graphics-protocol/watchdog.log"
  fi
  ensure_graphics_daemon_deployment_safety
  if ! have_cmd systemctl; then
    note "systemctl is not available; skipping graphics protocol daemon installation."
    return 0
  fi
  if (( ! DRY_RUN )); then
    mkdir -p "$(dirname "$GRAPHICS_DAEMON_SCRIPT")" "$(dirname "$GRAPHICS_DAEMON_UNIT")"
  fi

  backup_file "$GRAPHICS_DAEMON_SCRIPT"
  backup_file "$GRAPHICS_DAEMON_UNIT"

  write_file_atomic "$GRAPHICS_DAEMON_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

CONF_FILE="/etc/vfio-gpu-passthrough.conf"
XORG_HOST_GPU_CONF="/etc/X11/xorg.conf.d/20-vfio-host-gpu.conf"
LIGHTDM_HOST_GPU_CONF="/etc/lightdm/lightdm.conf.d/90-vfio-host-gpu.conf"
STATE_FILE="/run/vfio-graphics-protocold.state"
WATCHDOG_LOG="__VFIO_GRAPHICS_WATCHDOG_LOG__"
WATCHDOG_TARGET_USER="__VFIO_GRAPHICS_WATCHDOG_USER__"
WATCHDOG_TARGET_GROUP="__VFIO_GRAPHICS_WATCHDOG_GROUP__"
WATCHDOG_LOG_DIR="$(dirname "$WATCHDOG_LOG")"
DEFAULT_SLEEP_SECS=1
DEFAULT_AUTO_X11_PINNING=0
DEFAULT_WATCHDOG_RETENTION_DAYS=10
DEFAULT_WATCHDOG_MAX_LINES=5000

trim() {
  local s="$*"
  s="${s#"${s%%[![:space:]]*}"}"
  s="${s%"${s##*[![:space:]]}"}"
  printf '%s\n' "$s"
}

daemon_sleep_secs() {
  local raw=""
  if [[ -n "${VFIO_GRAPHICS_DAEMON_INTERVAL:-}" ]]; then
    raw="${VFIO_GRAPHICS_DAEMON_INTERVAL}"
  elif [[ -f "$CONF_FILE" ]]; then
    raw="$(awk -F= '/^VFIO_GRAPHICS_DAEMON_INTERVAL=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  fi
  raw="$(trim "$raw")"
  if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 1 && 10#$raw <= 3600 )); then
    printf '%s\n' "$((10#$raw))"
  else
    printf '%s\n' "$DEFAULT_SLEEP_SECS"
  fi
}

auto_x11_pinning_enabled() {
  local raw=""
  if [[ -n "${VFIO_GRAPHICS_AUTO_X11_PINNING:-}" ]]; then
    raw="${VFIO_GRAPHICS_AUTO_X11_PINNING}"
  elif [[ -f "$CONF_FILE" ]]; then
    raw="$(awk -F= '/^VFIO_GRAPHICS_AUTO_X11_PINNING=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  fi
  raw="$(trim "$raw")"
  raw="${raw,,}"
  case "$raw" in
    1|y|yes|true|on) return 0 ;;
    0|n|no|false|off) return 1 ;;
    *)
      (( DEFAULT_AUTO_X11_PINNING == 1 )) && return 0
      return 1
      ;;
  esac
}
watchdog_retention_days() {
  local raw=""
  if [[ -n "${VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS:-}" ]]; then
    raw="${VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS}"
  elif [[ -f "$CONF_FILE" ]]; then
    raw="$(awk -F= '/^VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  fi
  raw="$(trim "$raw")"
  if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 1 && 10#$raw <= 365 )); then
    printf '%s\n' "$((10#$raw))"
  else
    printf '%s\n' "$DEFAULT_WATCHDOG_RETENTION_DAYS"
  fi
}
watchdog_max_lines() {
  local raw=""
  if [[ -n "${VFIO_GRAPHICS_WATCHDOG_MAX_LINES:-}" ]]; then
    raw="${VFIO_GRAPHICS_WATCHDOG_MAX_LINES}"
  elif [[ -f "$CONF_FILE" ]]; then
    raw="$(awk -F= '/^VFIO_GRAPHICS_WATCHDOG_MAX_LINES=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  fi
  raw="$(trim "$raw")"
  if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 200 && 10#$raw <= 500000 )); then
    printf '%s\n' "$((10#$raw))"
  else
    printf '%s\n' "$DEFAULT_WATCHDOG_MAX_LINES"
  fi
}
prune_watchdog_log() {
  [[ -f "$WATCHDOG_LOG" ]] || return 0
  local retention_days max_lines cutoff_epoch line ts ts_epoch line_count
  local tmp
  retention_days="$(watchdog_retention_days)"
  max_lines="$(watchdog_max_lines)"
  cutoff_epoch="$(date -u -d "-${retention_days} days" +%s 2>/dev/null || true)"
  tmp="$(mktemp)"
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    if [[ -n "$cutoff_epoch" ]]; then
      ts="${line%% *}"
      ts_epoch="$(date -u -d "$ts" +%s 2>/dev/null || true)"
      if [[ -n "$ts_epoch" ]] && (( ts_epoch < cutoff_epoch )); then
        continue
      fi
    fi
    printf '%s\n' "$line" >>"$tmp"
  done < "$WATCHDOG_LOG"
  line_count="$(wc -l < "$tmp" 2>/dev/null || echo 0)"
  if [[ "$line_count" =~ ^[0-9]+$ ]] && (( line_count > max_lines )); then
    tail -n "$max_lines" "$tmp" >"${tmp}.tail" 2>/dev/null || true
    mv -f "${tmp}.tail" "$tmp" 2>/dev/null || true
  fi
  if cmp -s "$tmp" "$WATCHDOG_LOG"; then
    rm -f "$tmp" || true
  else
    mv -f "$tmp" "$WATCHDOG_LOG" 2>/dev/null || true
  fi
}

xorg_busid_from_bdf() {
  local bdf="$1"
  local bus_hex dev_hex func_dec
  if [[ ! "$bdf" =~ ^[[:xdigit:]]{4}:([[:xdigit:]]{2}):([[:xdigit:]]{2})\.([0-7])$ ]]; then
    return 1
  fi
  bus_hex="${BASH_REMATCH[1]}"
  dev_hex="${BASH_REMATCH[2]}"
  func_dec="${BASH_REMATCH[3]}"
  printf 'PCI:%d:%d:%d\n' "$((16#$bus_hex))" "$((16#$dev_hex))" "$func_dec"
}

normalize_display_manager_name() {
  local raw="$1"
  raw="${raw##*/}"
  raw="${raw%.service}"
  raw="${raw,,}"
  case "$raw" in
    lightdm|sddm|lxdm|xdm) echo "$raw"; return 0 ;;
    gdm|gdm3) echo "gdm"; return 0 ;;
  esac
  return 1
}
display_manager_name() {
  local dm_link base dm
  if [[ -L /etc/systemd/system/display-manager.service ]]; then
    dm_link="$(readlink -f /etc/systemd/system/display-manager.service 2>/dev/null || true)"
    base="$(basename "${dm_link:-}")"
    if dm="$(normalize_display_manager_name "$base")"; then
      echo "$dm"
      return 0
    fi
  fi
  # openSUSE often uses a display-manager wrapper unit; resolve the active DM
  # from alternatives as a fallback so protocol policy can classify prelogin mode.
  if [[ -L /usr/lib/X11/displaymanagers/default-displaymanager ]]; then
    dm_link="$(readlink -f /usr/lib/X11/displaymanagers/default-displaymanager 2>/dev/null || true)"
    base="$(basename "${dm_link:-}")"
    if dm="$(normalize_display_manager_name "$base")"; then
      echo "$dm"
      return 0
    fi
  fi
  echo "none"
}
display_manager_prefers_x11_prelogin() {
  # Display managers that typically launch an Xorg greeter before login.
  case "$(display_manager_name)" in
    lightdm|sddm|lxdm|xdm) return 0 ;;
    gdm|none|*) return 1 ;;
  esac
}

display_manager_prefers_wayland_prelogin() {
  # GDM commonly defaults to Wayland greeter when available.
  case "$(display_manager_name)" in
    gdm) return 0 ;;
    *) return 1 ;;
  esac
}

active_user_session_exists() {
  local sid state class
  while read -r sid _rest; do
    [[ -n "${sid:-}" ]] || continue
    state="$(loginctl show-session "$sid" -p State --value 2>/dev/null || true)"
    class="$(loginctl show-session "$sid" -p Class --value 2>/dev/null || true)"
    [[ "$class" == "user" ]] || continue
    [[ "$state" == "active" ]] || continue
    return 0
  done < <(loginctl list-sessions --no-legend 2>/dev/null || true)
  return 1
}

infer_prelogin_protocol_mode() {
  if display_manager_prefers_x11_prelogin; then
    echo "x11"
    return 0
  fi
  if display_manager_prefers_wayland_prelogin; then
    echo "wayland"
    return 0
  fi
  echo "unknown"
}

write_file_if_changed() {
  local dst="$1"
  local mode="$2"
  local tmp
  tmp="$(mktemp)"
  cat >"$tmp"
  if [[ -f "$dst" ]] && cmp -s "$tmp" "$dst"; then
    rm -f "$tmp" || true
    return 1
  fi
  install -m "$mode" -o root -g root "$tmp" "$dst"
  rm -f "$tmp" || true
  return 0
}

ensure_x11_host_gpu_pinning() {
  local host_gpu_bdf="$1"
  local guest_gpu_bdf="$2"
  local host_busid changed=0 dm

  [[ -n "$host_gpu_bdf" && -n "$guest_gpu_bdf" ]] || return 0
  [[ "$host_gpu_bdf" != "$guest_gpu_bdf" ]] || return 0

  host_busid="$(xorg_busid_from_bdf "$host_gpu_bdf" 2>/dev/null || true)"
  [[ -n "$host_busid" ]] || return 0

  mkdir -p /etc/X11/xorg.conf.d
  if write_file_if_changed "$XORG_HOST_GPU_CONF" 0644 <<EOF_XORG
# Managed by vfio-graphics-protocold (AUTO/X11 policy)
# Host GPU (Xorg): $host_gpu_bdf
# Guest GPU (VFIO): $guest_gpu_bdf
Section "ServerLayout"
    Identifier "Layout0"
    Screen 0 "Screen0"
EndSection
Section "Device"
    Identifier "HostGPU"
    BusID "$host_busid"
    Option "PrimaryGPU" "true"
EndSection
Section "Screen"
    Identifier "Screen0"
    Device "HostGPU"
EndSection
EOF_XORG
  then
    changed=1
  fi

  dm="$(display_manager_name)"
  if [[ "$dm" == "lightdm" ]]; then
    mkdir -p /etc/lightdm/lightdm.conf.d
    if write_file_if_changed "$LIGHTDM_HOST_GPU_CONF" 0644 <<EOF_LIGHTDM
# Managed by vfio-graphics-protocold (AUTO/X11 policy)
[Seat:*]
xserver-command=X -core -isolateDevice $host_busid
EOF_LIGHTDM
    then
      changed=1
    fi
  fi

  return "$changed"
}

remove_x11_host_gpu_pinning() {
  local removed=0
  if [[ -f "$XORG_HOST_GPU_CONF" ]]; then
    rm -f "$XORG_HOST_GPU_CONF"
    removed=1
  fi
  if [[ -f "$LIGHTDM_HOST_GPU_CONF" ]]; then
    rm -f "$LIGHTDM_HOST_GPU_CONF"
    removed=1
  fi
  return "$removed"
}

detect_active_session_type() {
  local sid state class stype
  while read -r sid _rest; do
    [[ -n "${sid:-}" ]] || continue
    state="$(loginctl show-session "$sid" -p State --value 2>/dev/null || true)"
    class="$(loginctl show-session "$sid" -p Class --value 2>/dev/null || true)"
    stype="$(loginctl show-session "$sid" -p Type --value 2>/dev/null || true)"
    [[ "$class" == "user" ]] || continue
    [[ "$state" == "active" ]] || continue
    case "$stype" in
      x11|wayland) echo "$stype"; return 0 ;;
    esac
  done < <(loginctl list-sessions --no-legend 2>/dev/null || true)
  echo "unknown"
}
current_root_subvolume() {
  local cmdline subvol
  cmdline="$(cat /proc/cmdline 2>/dev/null || true)"
  subvol="$(printf '%s\n' "$cmdline" | sed -n 's/.*rootflags=[^ ]*subvol=\([^ ,]*\).*/\1/p')"
  printf '%s\n' "${subvol:-unknown}"
}
watchdog_log_event() {
  local mode="$1" session_type="$2" action="$3"
  local reason="${4:-unspecified}" dm_name="${5:-none}" prelogin_protocol="${6:-unknown}"
  local host_gpu="${7:-unknown}" guest_gpu="${8:-unknown}"
  local ts root_subvol retention_days max_lines
  reason="$(trim "$reason")"
  reason="${reason//[[:space:]]/-}"
  [[ -n "$reason" ]] || reason="unspecified"
  dm_name="$(trim "$dm_name")"
  [[ -n "$dm_name" ]] || dm_name="none"
  prelogin_protocol="$(trim "$prelogin_protocol")"
  [[ -n "$prelogin_protocol" ]] || prelogin_protocol="unknown"
  host_gpu="$(trim "$host_gpu")"
  [[ -n "$host_gpu" ]] || host_gpu="unknown"
  guest_gpu="$(trim "$guest_gpu")"
  [[ -n "$guest_gpu" ]] || guest_gpu="unknown"
  ts="$(date -Is 2>/dev/null || true)"
  [[ -n "$ts" ]] || ts="unknown-time"
  root_subvol="$(current_root_subvolume)"
  retention_days="$(watchdog_retention_days)"
  max_lines="$(watchdog_max_lines)"
  mkdir -p "$WATCHDOG_LOG_DIR" 2>/dev/null || true
  prune_watchdog_log || true
  printf '%s mode=%s session=%s action=%s reason=%s dm=%s prelogin=%s host=%s guest=%s subvol=%s retention_days=%s max_lines=%s\n' \
    "$ts" "$mode" "$session_type" "$action" "$reason" "$dm_name" "$prelogin_protocol" "$host_gpu" "$guest_gpu" "$root_subvol" "$retention_days" "$max_lines" >>"$WATCHDOG_LOG" 2>/dev/null || true
  prune_watchdog_log || true
  if [[ -n "$WATCHDOG_TARGET_USER" && -n "$WATCHDOG_TARGET_GROUP" ]]; then
    chown "$WATCHDOG_TARGET_USER:$WATCHDOG_TARGET_GROUP" "$WATCHDOG_LOG_DIR" "$WATCHDOG_LOG" 2>/dev/null || true
    chmod u+rwX "$WATCHDOG_LOG_DIR" "$WATCHDOG_LOG" 2>/dev/null || true
  fi
}

apply_policy_once() {
  local prelogin="${1:-0}"
  [[ -f "$CONF_FILE" ]] || return 0
  # shellcheck disable=SC1090
  . "$CONF_FILE"

  local mode host guest session_type inferred_prelogin action reason prev dm_name prelogin_protocol state_key
  mode="$(trim "${GRAPHICS_PROTOCOL_MODE:-AUTO}")"
  mode="${mode^^}"
  host="$(trim "${HOST_GPU_BDF:-}")"
  guest="$(trim "${GUEST_GPU_BDF:-}")"
  dm_name="$(display_manager_name)"
  session_type="unknown"
  action="noop"
  reason="noop"
  prelogin_protocol="unknown"

  if [[ "$prelogin" == "1" ]]; then
    inferred_prelogin="$(infer_prelogin_protocol_mode)"
    prelogin_protocol="$inferred_prelogin"
    case "$mode" in
      X11)
        action="x11"
        session_type="prelogin-x11"
        reason="forced-x11-mode"
        ;;
      WAYLAND)
        action="wayland"
        session_type="prelogin-wayland"
        reason="forced-wayland-mode"
        ;;
      AUTO)
        case "$inferred_prelogin" in
          x11)
            action="x11"
            session_type="prelogin-x11"
            reason="auto-prelogin-x11"
            ;;
          wayland)
            action="wayland"
            session_type="prelogin-wayland"
            reason="auto-prelogin-wayland"
            ;;
          *)
            if auto_x11_pinning_enabled; then
              action="x11"
              session_type="prelogin-auto-x11-fallback"
              reason="auto-prelogin-fallback-x11"
            else
              action="noop"
              session_type="prelogin-unknown"
              reason="auto-prelogin-unknown"
            fi
            ;;
        esac
        ;;
      *)
        action="noop"
        session_type="prelogin-unknown"
        reason="invalid-mode"
        ;;
    esac
  else
    prelogin_protocol="$(infer_prelogin_protocol_mode)"
    session_type="$(detect_active_session_type)"
    if [[ "$session_type" == "unknown" ]] && ! active_user_session_exists; then
      inferred_prelogin="$prelogin_protocol"
      case "$inferred_prelogin" in
        x11) session_type="prelogin-x11" ;;
        wayland) session_type="prelogin-wayland" ;;
        *) session_type="unknown" ;;
      esac
    fi

    case "$mode" in
      X11)
        action="x11"
        reason="forced-x11-mode"
        ;;
      WAYLAND)
        action="wayland"
        reason="forced-wayland-mode"
        ;;
      AUTO)
        case "$session_type" in
          x11|prelogin-x11)
            if auto_x11_pinning_enabled || [[ "$session_type" == "prelogin-x11" ]] || display_manager_prefers_x11_prelogin; then
              action="x11"
              if auto_x11_pinning_enabled; then
                reason="auto-x11-pinning-enabled"
              elif [[ "$session_type" == "prelogin-x11" ]]; then
                reason="auto-prelogin-x11-session"
              else
                reason="auto-dm-prefers-x11-prelogin"
              fi
            else
              # Conservative AUTO default for active X11 sessions when pinning override is disabled.
              action="auto-safe-no-x11"
              reason="auto-x11-pinning-disabled"
            fi
            ;;
          wayland|prelogin-wayland)
            if display_manager_prefers_x11_prelogin; then
              action="x11"
              reason="auto-dm-prefers-x11-prelogin-wayland-session"
            else
              action="wayland"
              reason="auto-wayland-session"
            fi
            ;;
          prelogin-auto-x11-fallback)
            action="x11"
            reason="auto-prelogin-fallback-x11"
            ;;
          *)
            action="noop"
            reason="auto-unknown-session"
            ;;
        esac
        ;;
      *)
        action="noop"
        reason="invalid-mode"
        ;;
    esac
  fi

  case "$action" in
    x11)
      ensure_x11_host_gpu_pinning "$host" "$guest" || true
      ;;
    wayland)
      remove_x11_host_gpu_pinning || true
      ;;
    auto-safe-no-x11)
      remove_x11_host_gpu_pinning || true
      ;;
    noop)
      ;;
  esac

  state_key="$mode:$session_type:$action:$reason:$dm_name:$prelogin_protocol"
  prev="$(cat "$STATE_FILE" 2>/dev/null || true)"
  if [[ "$prev" != "$state_key" ]]; then
    printf '%s\n' "$state_key" >"$STATE_FILE" 2>/dev/null || true
    printf 'vfio-graphics-protocold: mode=%s session=%s action=%s reason=%s dm=%s prelogin=%s\n' "$mode" "$session_type" "$action" "$reason" "$dm_name" "$prelogin_protocol"
    watchdog_log_event "$mode" "$session_type" "$action" "$reason" "$dm_name" "$prelogin_protocol" "$host" "$guest"
  fi
}

main() {
  local once=0 prelogin=0
  while (( $# > 0 )); do
    case "$1" in
      --once) once=1 ;;
      --prelogin) prelogin=1 ;;
      *) ;;
    esac
    shift
  done

  if (( once )); then
    apply_policy_once "$prelogin"
    exit 0
  fi

  apply_policy_once "$prelogin" || true
  while true; do
    sleep "$(daemon_sleep_secs)"
    apply_policy_once 0 || true
  done
}

main "$@"
EOF

  write_file_atomic "$GRAPHICS_DAEMON_UNIT" 0644 "root:root" <<EOF
[Unit]
Description=VFIO graphics protocol adaptation daemon
ConditionPathExists=$CONF_FILE
ConditionPathExists=$GRAPHICS_DAEMON_SCRIPT
After=local-fs.target systemd-logind.service vfio-bind-selected-gpu.service
Wants=systemd-logind.service vfio-bind-selected-gpu.service
Before=display-manager.service

[Service]
Type=simple
Environment=VFIO_GRAPHICS_DAEMON_INTERVAL=$daemon_interval
ExecStart=$GRAPHICS_DAEMON_SCRIPT --prelogin
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
EOF

  if (( ! DRY_RUN )); then
    sed -i "s#__VFIO_GRAPHICS_WATCHDOG_LOG__#$watchdog_log#g" "$GRAPHICS_DAEMON_SCRIPT" || true
    sed -i "s#__VFIO_GRAPHICS_WATCHDOG_USER__#$watchdog_user#g" "$GRAPHICS_DAEMON_SCRIPT" || true
    sed -i "s#__VFIO_GRAPHICS_WATCHDOG_GROUP__#$watchdog_group#g" "$GRAPHICS_DAEMON_SCRIPT" || true
  fi

  if (( ! DRY_RUN )); then
    [[ -f "$GRAPHICS_DAEMON_SCRIPT" ]] || die "Graphics daemon deployment failed: missing script at $GRAPHICS_DAEMON_SCRIPT"
    [[ -x "$GRAPHICS_DAEMON_SCRIPT" ]] || die "Graphics daemon deployment failed: script is not executable at $GRAPHICS_DAEMON_SCRIPT"
    [[ -f "$GRAPHICS_DAEMON_UNIT" ]] || die "Graphics daemon deployment failed: missing unit at $GRAPHICS_DAEMON_UNIT"
    grep -Fqx "ConditionPathExists=$GRAPHICS_DAEMON_SCRIPT" "$GRAPHICS_DAEMON_UNIT" || \
      die "Graphics daemon deployment failed: unit missing script condition guard ($GRAPHICS_DAEMON_SCRIPT)"
  fi
  run systemctl daemon-reload
  run systemctl enable vfio-graphics-protocold.service
  say "Installed graphics protocol daemon: $GRAPHICS_DAEMON_SCRIPT"
  say "Installed graphics protocol unit:   $GRAPHICS_DAEMON_UNIT"
  say "Graphics protocol watchdog log:      $watchdog_log"
  say "Graphics daemon polling interval:    ${daemon_interval}s"
  note "Graphics protocol daemon will activate on next boot (not started immediately)."
}
graphics_daemon_interval_from_conf_or_default() {
  local interval="$GRAPHICS_DAEMON_INTERVAL_DEFAULT"
  if readable_file "$CONF_FILE"; then
    local raw
    raw="$(awk -F= '/^VFIO_GRAPHICS_DAEMON_INTERVAL=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    raw="$(trim "${raw:-}")"
    if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 1 && 10#$raw <= 3600 )); then
      interval="$((10#$raw))"
    fi
  fi
  printf '%s\n' "$interval"
}
graphics_watchdog_retention_days_from_conf_or_default() {
  local retention_days="$GRAPHICS_WATCHDOG_RETENTION_DAYS_DEFAULT"
  if readable_file "$CONF_FILE"; then
    local raw
    raw="$(awk -F= '/^VFIO_GRAPHICS_WATCHDOG_RETENTION_DAYS=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    raw="$(trim "${raw:-}")"
    if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 1 && 10#$raw <= 365 )); then
      retention_days="$((10#$raw))"
    fi
  fi
  printf '%s\n' "$retention_days"
}
graphics_watchdog_max_lines_from_conf_or_default() {
  local max_lines="$GRAPHICS_WATCHDOG_MAX_LINES_DEFAULT"
  if readable_file "$CONF_FILE"; then
    local raw
    raw="$(awk -F= '/^VFIO_GRAPHICS_WATCHDOG_MAX_LINES=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    raw="$(trim "${raw:-}")"
    if [[ "$raw" =~ ^[0-9]+$ ]] && (( 10#$raw >= 200 && 10#$raw <= 500000 )); then
      max_lines="$((10#$raw))"
    fi
  fi
  printf '%s\n' "$max_lines"
}
install_graphics_protocol_daemon_from_existing_config() {
  readable_file "$CONF_FILE" || die "Missing $CONF_FILE. Run the full installer first, or create the config before reinstalling only the graphics daemon."
  local interval
  interval="$(graphics_daemon_interval_from_conf_or_default)"
  install_graphics_protocol_daemon "$interval"
}
# Rewrite a single KEY="value" line in $CONF_FILE, preserving all other lines.
# Used by the standalone binding-mode installers to flip VFIO_BINDING_MODE without
# re-running the full wizard (which would regenerate the whole conf file).
rewrite_conf_key() {
  local key="$1" value="$2"
  readable_file "$CONF_FILE" || return 1
  local tmp
  tmp="$(mktemp)"
  awk -v k="$key" -v v="$value" '
    BEGIN { found=0 }
    {
      if ($0 ~ "^" k "=") {
        printf "%s=\"%s\"\n", k, v
        found=1
      } else {
        print
      }
    }
    END {
      if (!found) {
        printf "%s=\"%s\"\n", k, v
      }
    }
  ' "$CONF_FILE" >"$tmp"
  if (( ! DRY_RUN )); then
    cat "$tmp" >"$CONF_FILE"
  fi
  rm -f "$tmp"
}

# Build a vfio-pci.ids=... value (vendor:device comma-separated) from the guest
# GPU + guest audio BDFs stored in $CONF_FILE, using lspci -n.
# shellcheck disable=SC2178,SC2128
build_vfio_pci_ids_from_conf() {
  readable_file "$CONF_FILE" || return 1
  # shellcheck disable=SC1090
  . "$CONF_FILE"
  local ids=""
  local line vid_pid bdf
  local -a bdfs=()
  [[ -n "${GUEST_GPU_BDF:-}" ]] && bdfs+=("$GUEST_GPU_BDF")
  if [[ -n "${GUEST_AUDIO_BDFS_CSV:-}" ]]; then
    local _old_ifs="$IFS"
    IFS=','
    local -a _audio_arr=()
    read -r -a _audio_arr <<<"$GUEST_AUDIO_BDFS_CSV"
    IFS="$_old_ifs"
    bdfs+=("${_audio_arr[@]}")
  fi
  for bdf in "${bdfs[@]}"; do
    [[ -n "$bdf" ]] || continue
    line="$(lspci -n -s "$bdf" 2>/dev/null || true)"
    # Extract the vendor:device pair (e.g. "1002:7550").
    vid_pid="$(printf '%s' "$line" | grep -oE '[0-9a-fA-F]{4}:[0-9a-fA-F]{4}' | head -n1 || true)"
    [[ -n "$vid_pid" ]] || continue
    ids="${ids:+$ids,}$vid_pid"
  done
  printf '%s' "$ids"
}

# Strip vfio-pci.ids= and rd.driver.pre=vfio-pci from a cmdline string.
strip_early_binding_tokens() {
  local cmdline="$1"
  cmdline="$(remove_param_prefix "$cmdline" "vfio-pci.ids=")"
  cmdline="$(remove_param_all "$cmdline" "rd.driver.pre=vfio-pci")"
  printf '%s' "$(trim "$cmdline")"
}

# Returns 0 (true) if the configured guest GPU is an RX 9070 / RDNA4
# (Navi 48) card: AMD vendor (1002) + device 7550. All 9070 / 9070 XT /
# 9070 GRE SKUs share device 7550. Used to gate OUT vfio-pci.disable_idle_d3=1,
# which two independent working guides for this exact card (CachyOS single-GPU
# RX 9070 XT gist; Proxmox uzumo months-stable recipe) report makes D3 issues
# WORSE on Navi 48, not better -- it triggers a vfio_bar_restore reset-recovery
# loop that ends with the card falling off the host PCIe bus mid-session
# (config space all 0xff, qemu "Unknown PCI header type 127"). The correct D0
# lock -- d3cold_allowed=0 + power/control=on -- is already applied by the bind
# script at boot and bind time, so disable_idle_d3 is not needed on Navi 48.
# Device id is read from CTX[guest_vfio_ids] (wizard context, set at GPU
# selection as "vendor:device") when available, else from sysfs/lspci at
# runtime (card is alive at install/switch time). Returns 1 (false) if the
# device id cannot be determined (conservative: do NOT gate on unknown hw,
# so a non-Navi-48 card keeps the legacy add-disable_idle_d3 behavior).
_is_guest_rx9070_family() {
  local _vid_pid _dev _bdf _sys _line
  # 1. Prefer the persisted device id from conf (DURABLE: works even when the
  #    card is dead / off the bus at standalone-switcher time, since it was
  #    captured at wizard time by write_conf or backfilled by
  #    _ensure_guest_device_id_persisted). This is the primary path.
  if [[ -f "$CONF_FILE" ]]; then
    _dev="$(awk -F= '/^GUEST_GPU_DEVICE_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
    _dev="${_dev#0x}"
    if [[ -n "$_dev" ]]; then
      [[ "${_dev,,}" == "7550" ]]
      return $?
    fi
  fi
  # 2. Wizard context (set at GPU selection as "vendor:device").
  _vid_pid="${CTX[guest_vfio_ids]:-}"
  if [[ -n "$_vid_pid" ]]; then
    _dev="${_vid_pid#*:}"
    _dev="${_dev#0x}"
    [[ "${_dev,,}" == "7550" ]]
    return $?
  fi
  # 3. Runtime sysfs/lspci fallback (card must be alive; used only when the
  #    conf key is absent, e.g. a conf written by an older script version).
  if [[ -f "$CONF_FILE" ]]; then
    _bdf="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  fi
  [[ -n "$_bdf" ]] || return 1
  _sys="/sys/bus/pci/devices/$_bdf"
  _dev="$(cat "$_sys/device" 2>/dev/null || true)"
  _dev="${_dev#0x}"
  if [[ -z "$_dev" ]]; then
    _line="$(lspci -n -s "$_bdf" 2>/dev/null || true)"
    _dev="$(printf '%s' "$_line" | grep -oE '[0-9a-fA-F]{4}:[0-9a-fA-F]{4}' | head -n1 | cut -d: -f2 || true)"
    _dev="${_dev#0x}"
  fi
  [[ -n "$_dev" ]] || return 1
  [[ "${_dev,,}" == "7550" ]]
}

# Returns 0 (true) if vfio-pci.disable_idle_d3=1 should be added to the kernel
# cmdline for the current guest GPU. Decision matrix:
#  - --no-amd-disable-idle-d3 (AMD_D3_OVERRIDE=0): always SKIP (explicit opt-out).
#  - --amd-disable-idle-d3    (AMD_D3_OVERRIDE=1): always ADD  (explicit force,
#    honored even on Navi 48 -- the user explicitly asked for it).
#  - default (unset): ADD for non-Navi-48 AMD cards; SKIP for RX 9070 / RDNA4
#    (Navi 48, device 7550) because disable_idle_d3 worsens D3 issues there
#    (the bind script's D0-lock is the correct reset-bug defense instead).
_should_add_disable_idle_d3() {
  [[ "${AMD_D3_OVERRIDE:-}" != "0" ]] || return 1
  [[ "${AMD_D3_OVERRIDE:-}" == "1" ]] && return 0
  ! _is_guest_rx9070_family
}

# Persist GUEST_GPU_DEVICE_ID into $CONF_FILE if it is missing, using the live
# sysfs device id of the configured guest GPU. Called by the standalone binding
# switchers (--install-dynamic-binding / --install-early-binding), which do NOT
# run the full wizard / write_conf, so the Navi 48 disable_idle_d3 gate stays
# durable across future switcher runs even when the card is later dead / off
# the bus (the _is_guest_rx9070_family sysfs fallback cannot fire then). Best-
# effort: no-op if the conf is missing, the BDF is absent, the card is not
# alive, or the key is already present. Uses rewrite_conf_key (which appends if
# the key is absent, so this only runs once per conf).
_ensure_guest_device_id_persisted() {
  readable_file "$CONF_FILE" || return 0
  if grep -Eq '^GUEST_GPU_DEVICE_ID=' "$CONF_FILE" 2>/dev/null; then
    return 0
  fi
  local _bdf _dev
  _bdf="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_bdf" ]] || return 0
  local _sys="/sys/bus/pci/devices/$_bdf"
  [[ -r "$_sys/device" ]] || return 0
  _dev="$(cat "$_sys/device" 2>/dev/null || true)"
  _dev="${_dev#0x}"
  [[ -n "$_dev" ]] || return 0
  rewrite_conf_key "GUEST_GPU_DEVICE_ID" "$_dev"
}

# Ensure the AMD reset-bug-critical kernel params are present on a cmdline string:
# vfio-pci.disable_idle_d3=1 and pcie_port_pm=off. These prevent the RX 9070 /
# RDNA4 D3cold reset bug (card falls off the bus on a D3cold exit, config space
# all 0xff, qemu reports "Unknown PCI header type 127") and are promised "kept on
# the kernel cmdline for both modes" in the release note / README.
# Non-interactive (NO prompt): used by the standalone binding-mode switchers
# (--install-dynamic-binding / --install-early-binding) so a quick mode switch
# also deploys them without re-running the full wizard's interactive AMD prompt.
# Only the two reset-bug-critical params are force-added; amdgpu.runpm=0 /
# amdgpu.noretry=0 stay optional (power tradeoff) and are NOT forced here.
# Honors --no-amd-disable-idle-d3 / --no-amd-pcie-port-pm-off (AMD_D3_OVERRIDE=0 /
# AMD_PORTPM_OVERRIDE=0) so an explicit opt-out is respected.
# Reads GUEST_GPU_VENDOR_ID from $CONF_FILE. Prints the (possibly augmented)
# cmdline on stdout; emits a `note` on stderr when a param was actually added, so
# the note never pollutes command-substitution stdout.
ensure_amd_reset_bug_params() {
  local cmdline="$1"
  if [[ ! -f "$CONF_FILE" ]]; then
    printf '%s' "$(trim "$cmdline")"
    return 0
  fi
  local _vendor
  _vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  if [[ -z "$_vendor" || "${_vendor,,}" != "1002" ]]; then
    printf '%s' "$(trim "$cmdline")"
    return 0
  fi
  local _before="$cmdline"
  if _should_add_disable_idle_d3; then
    cmdline="$(add_param_once "$cmdline" "vfio-pci.disable_idle_d3=1")"
  fi
  if [[ "${AMD_PORTPM_OVERRIDE:-}" != "0" ]]; then
    cmdline="$(add_param_once "$cmdline" "pcie_port_pm=off")"
  fi
  if [[ "$cmdline" != "$_before" ]]; then
    note "AMD guest GPU: ensured pcie_port_pm=off on the kernel cmdline (prevents the RX 9070 / RDNA4 D3cold reset bug; required for both binding modes)." >&2
    if grep -q 'vfio-pci.disable_idle_d3=1' <<<"$cmdline"; then
      note "  Also ensured vfio-pci.disable_idle_d3=1." >&2
    else
      note "  vfio-pci.disable_idle_d3=1 deliberately SKIPPED for RX 9070 / RDNA4 (Navi 48, device 7550): it worsens D3 issues on Navi 48 (triggers a vfio_bar_restore reset loop that drops the card off the bus mid-session); the D0-lock (d3cold_allowed=0 + power/control=on) already applied by the bind script is the correct defense. Pass --amd-disable-idle-d3 to force it anyway." >&2
    fi
  fi
  printf '%s' "$(trim "$cmdline")"
}

# Map a PCI BDF to its primary DRM card device path (e.g. /dev/dri/card1) by
# walking /sys/class/drm/card*/device symlinks. Prints the /dev/dri/cardN path
# and returns 0 on match, returns 1 if no DRM card is bound to that BDF.
# Skips renderD* and cardN-* (connector) entries: only primary card nodes.
_bdf_to_drm_card() {
  local _bdf="$1" _card _dev_bdf
  [[ -n "$_bdf" ]] || return 1
  for _card in /sys/class/drm/card[0-9]*; do
    [[ -e "$_card" ]] || continue
    case "$(basename "$_card")" in card[0-9]*-*) continue ;; esac
    _dev_bdf="$(basename "$(readlink -f "$_card/device" 2>/dev/null)" 2>/dev/null || true)"
    if [[ "$_dev_bdf" == "$_bdf" ]]; then
      printf '/dev/dri/%s\n' "$(basename "$_card")"
      return 0
    fi
  done
  return 1
}

# Map a PCI BDF to a STABLE DRM card device path that survives card-number
# swaps across reboots (the kernel assigns card0/card1 in enumeration order,
# which can flip between boots). Prefers the /dev/dri/by-path/pci-<BDF>-card
# symlink (keyed by PCI address, stable across reboots). Falls back to the
# cardN walk (_bdf_to_drm_card) on systems without by-path symlinks. Used for
# PERSISTENT artifacts (the Wayland render-device pin file, the bind-now error
# hint) where a stale cardN would point at the wrong GPU after a reboot. For
# runtime /proc/<pid>/fd comparisons use _bdf_to_drm_card (cardN) instead,
# since open fds resolve to the cardN device node.
_bdf_to_drm_card_stable() {
  local _bdf="$1" _cand
  [[ -n "$_bdf" ]] || return 1
  for _cand in "/dev/dri/by-path/pci-$_bdf-card" "/dev/dri/by-path/pci-${_bdf#0000:}-card"; do
    if [[ -e "$_cand" ]]; then
      printf '%s\n' "$_cand"
      return 0
    fi
  done
  _bdf_to_drm_card "$_bdf"
}

# Apply cmdline changes to both /etc/kernel/cmdline (openSUSE/BLS) and
# /etc/default/grub (classic GRUB) when present, then sync BLS entries.
apply_binding_cmdline_change() {
  local new_cmdline_for_persistence="$1"   # set non-empty to write /etc/kernel/cmdline
  local grub_cmdline_change_func="$2"      # function name to apply grub cmdline (or empty)

  # /etc/kernel/cmdline (openSUSE/BLS persistence).
  if [[ -n "$new_cmdline_for_persistence" && -f /etc/kernel/cmdline ]]; then
    local kcur
    kcur="$(cat /etc/kernel/cmdline 2>/dev/null || true)"
    if [[ "$(trim "$new_cmdline_for_persistence")" != "$(trim "$kcur")" ]]; then
      backup_file /etc/kernel/cmdline
      if (( ! DRY_RUN )); then
        printf '%s\n' "$new_cmdline_for_persistence" >/etc/kernel/cmdline
      fi
      say "Updated /etc/kernel/cmdline for binding-mode change."
    fi
  fi

  # /etc/default/grub (classic GRUB).
  if [[ -n "$grub_cmdline_change_func" && -f /etc/default/grub ]]; then
    "$grub_cmdline_change_func"
  fi

  # Sync BLS entries if we are on an openSUSE-like system with sdbootutil.
  if is_opensuse_like && [[ -f /etc/kernel/cmdline ]]; then
    opensuse_sdbootutil_update_all_entries
  fi
}

# Install a Plasma/KWin Wayland session env drop-in that pins the compositor's
# render device to the HOST GPU via KWIN_DRM_DEVICES. This prevents the
# compositor from rendering on the guest GPU when the guest is Boot VGA
# (boot_vga=1): without it, binding the guest GPU to vfio-pci at VM start
# crashes kwin_wayland mid-frame (SEGV in GLVertexBuffer::endOfFrame) and takes
# the whole Wayland session down. No-op unless the guest GPU is Boot VGA.
# Takes effect on next login/reboot. Removed by --reset and by --install-early-binding.
install_wayland_render_device_pin() {
  local host_gpu="$1" guest_gpu="$2"
  [[ -n "$host_gpu" && -n "$guest_gpu" ]] || return 0
  [[ "$host_gpu" != "$guest_gpu" ]] || return 0

  # Only needed when the guest is Boot VGA; otherwise the compositor is not
  # rendering on the guest GPU anyway.
  local _gbv
  _gbv="$(cat "/sys/bus/pci/devices/$guest_gpu/boot_vga" 2>/dev/null || echo 0)"
  if [[ "$_gbv" != "1" ]]; then
    note "Guest GPU is not Boot VGA; skipping Wayland render-device pin."
    return 0
  fi

  # Install-time pre-check: the host BDF must currently map to a DRM card,
  # so we know the BDF is valid before writing a resolver for it. The pin file
  # itself is SELF-RESOLVING (runs at session start), so it adapts to future
  # card0/card1 swaps and never goes stale -- this check only guards against
  # writing a resolver for a bogus/un-enumerated BDF.
  if ! _bdf_to_drm_card "$host_gpu" >/dev/null 2>&1; then
    note "WARN: HOST_GPU_BDF=$host_gpu has no DRM card right now; skipping Wayland render-device pin."
    note "      Re-run the installer once the host GPU is enumerated by amdgpu."
    note "      The bind-now path will still refuse if the compositor is rendering on the guest GPU."
    return 0
  fi

  local _env_dir
  _env_dir="$(dirname "$KWIN_RENDER_PIN_FILE")"
  if (( ! DRY_RUN )); then
    mkdir -p "$_env_dir" 2>/dev/null || true
  fi

  # Self-resolving pin (R17c/R17d): instead of hardcoding /dev/dri/cardN or a
  # by-path path (either of which can go stale after a card-number swap and
  # point KWin at the GUEST GPU -> "Failed to open drm device" -> no graphical
  # login), write a tiny resolver that runs at SESSION START and walks
  # /sys/class/drm to find the host GPU's CURRENT card by PCI BDF, then exports
  # the colon-free /dev/dri/cardN path. The BDF walk makes it swap-safe (it
  # re-resolves every session, so a card0/card1 flip is handled automatically);
  # exporting cardN (NOT the by-path symlink) is REQUIRED because KWIN_DRM_DEVICES
  # and WLR_DRM_DEVICES use ':' as a device-list separator, so a by-path path
  # like /dev/dri/by-path/pci-0000:06:00.0-card gets split into three bogus
  # device paths -> "No suitable DRM devices have been found" -> no graphical
  # login (observed on Fedora). If the host card is not found at session start
  # (e.g. amdgpu still probing), the var stays UNSET and the compositor uses its
  # default device -- it never points at a wrong/nonexistent device, so it can
  # NEVER break login.
  backup_file "$KWIN_RENDER_PIN_FILE"
  write_file_atomic "$KWIN_RENDER_PIN_FILE" 0644 "root:root" <<EOF
# Managed by $SCRIPT_NAME. Self-resolving render-device pin: at session start
# it finds the HOST GPU's current DRM card (by PCI BDF) and points KWin at it,
# so the compositor never renders on the guest (Boot VGA) GPU that gets bound
# to vfio-pci at VM start (kwin_wayland SEGV in GLVertexBuffer::endOfFrame).
# Exports the colon-free /dev/dri/cardN path (NOT by-path: KWIN_DRM_DEVICES
# uses ':' as a device-list separator, so a by-path path with colons in the BDF
# would be split into bogus fragments and break the greeter).
# Self-resolving (re-walks sysfs every session) so it adapts to card0/card1
# enumeration-order swaps across reboots and cannot go stale.
# Takes effect on next login / reboot. Verify with: echo \$KWIN_DRM_DEVICES
# Remove via: sudo $SCRIPT_NAME --reset  (or sudo $SCRIPT_NAME --install-early-binding)
_vfio_host_bdf="$host_gpu"
for _c in /sys/class/drm/card[0-9]; do
  [ -e "\$_c" ] || continue
  _vfio_nm="\$(basename "\$_c")"
  case "\$_vfio_nm" in card[0-9]-*) continue ;; esac
  _vfio_cbdf="\$(basename "\$(readlink -f "\$_c/device" 2>/dev/null)" 2>/dev/null)"
  if [ "\$_vfio_cbdf" = "\$_vfio_host_bdf" ]; then
    export KWIN_DRM_DEVICES="/dev/dri/\$_vfio_nm"
    break
  fi
done
unset _vfio_host_bdf _c _vfio_nm _vfio_cbdf
EOF
  say "Installed self-resolving KWin render-device pin (host $host_gpu) via $KWIN_RENDER_PIN_FILE."

  # Generic login-shell drop-in for wlroots-based compositors (sway / hyprland /
  # labbc / wlroots) AND kwin launched from a shell. Sourced by /etc/profile.d.
  # Same self-resolving logic + colon-free cardN export as the KWin pin above
  # (WLR_DRM_DEVICES also uses ':' as a device-list separator, so by-path paths
  # with colons in the BDF would be split into bogus fragments and break the
  # compositor). Exports both KWIN_DRM_DEVICES and WLR_DRM_DEVICES.
  local _wlr_dir
  _wlr_dir="$(dirname "$WLR_RENDER_PIN_FILE")"
  if (( ! DRY_RUN )); then
    mkdir -p "$_wlr_dir" 2>/dev/null || true
  fi
  backup_file "$WLR_RENDER_PIN_FILE"
  write_file_atomic "$WLR_RENDER_PIN_FILE" 0644 "root:root" <<EOF
# Managed by $SCRIPT_NAME. Self-resolving render-device pin: at session start
# it finds the HOST GPU's current DRM card (by PCI BDF) and points Wayland
# compositors at it, so the compositor never renders on the guest (Boot VGA)
# GPU that gets bound to vfio-pci at VM start.
# Covers: KWin (KWIN_DRM_DEVICES) and wlroots-based compositors (WLR_DRM_DEVICES:
# sway / hyprland / labbc / wlroots). Sourced by login shells via /etc/profile.d.
# Exports the colon-free /dev/dri/cardN path (NOT by-path: both env vars use
# ':' as a device-list separator, so a by-path path with colons in the BDF
# would be split into bogus fragments and break the compositor).
# Self-resolving (re-walks sysfs every session) so it adapts to card0/card1
# swaps and cannot go stale / break login.
# Takes effect on next login / reboot.
# Remove via: sudo $SCRIPT_NAME --reset  (or sudo $SCRIPT_NAME --install-early-binding)
_vfio_host_bdf="$host_gpu"
for _c in /sys/class/drm/card[0-9]; do
  [ -e "\$_c" ] || continue
  _vfio_nm="\$(basename "\$_c")"
  case "\$_vfio_nm" in card[0-9]-*) continue ;; esac
  _vfio_cbdf="\$(basename "\$(readlink -f "\$_c/device" 2>/dev/null)" 2>/dev/null)"
  if [ "\$_vfio_cbdf" = "\$_vfio_host_bdf" ]; then
    export KWIN_DRM_DEVICES="/dev/dri/\$_vfio_nm"
    export WLR_DRM_DEVICES="/dev/dri/\$_vfio_nm"
    break
  fi
done
unset _vfio_host_bdf _c _vfio_nm _vfio_cbdf
EOF
  say "Installed self-resolving Wayland compositor pin (host $host_gpu) via $WLR_RENDER_PIN_FILE."
  note "These take effect on next login (or reboot). The pin resolves the host GPU's current"
  note "card at session start (colon-free cardN, safe for the ':'-separated env vars), so it"
  note "survives card0/card1 swaps and never breaks login."
}

# Remove the render-device pins installed by install_wayland_render_device_pin.
remove_wayland_render_device_pin() {
  local _removed=0
  if [[ -f "$KWIN_RENDER_PIN_FILE" ]]; then
    backup_file "$KWIN_RENDER_PIN_FILE"
    run rm -f "$KWIN_RENDER_PIN_FILE"
    _removed=1
  fi
  if [[ -f "$WLR_RENDER_PIN_FILE" ]]; then
    backup_file "$WLR_RENDER_PIN_FILE"
    run rm -f "$WLR_RENDER_PIN_FILE"
    _removed=1
  fi
  (( _removed )) && note "Removed Wayland render-device pins ($KWIN_RENDER_PIN_FILE, $WLR_RENDER_PIN_FILE)."
}

# Returns 0 if libvirt is reachable for dynamic binding, 1 otherwise.
# Robust to the classic monolithic libvirtd AND the modular virtqemud, and to
# socket-activated setups where the .service stays inactive until first use (the
# .socket is "active" while it is listening). Primary test: can virsh connect to
# qemu:///system (root can always connect) — that is the actual end-to-end path
# the libvirt qemu hook relies on. Fallback when virsh is absent: check the
# daemon/socket units directly via systemctl is-active. Bounded by `timeout`
# when available so a wedged libvirt cannot hang the wizard.
libvirt_runtime_ok() {
  if command -v virsh >/dev/null 2>&1; then
    if command -v timeout >/dev/null 2>&1; then
      if timeout 10 virsh -c qemu:///system list >/dev/null 2>&1; then
        return 0
      fi
    elif virsh -c qemu:///system list >/dev/null 2>&1; then
      return 0
    fi
  fi
  if command -v systemctl >/dev/null 2>&1; then
    if systemctl is-active --quiet libvirtd 2>/dev/null \
      || systemctl is-active --quiet virtqemud 2>/dev/null \
      || systemctl is-active --quiet libvirtd.socket 2>/dev/null \
      || systemctl is-active --quiet virtqemud.socket 2>/dev/null; then
      return 0
    fi
  fi
  return 1
}

# Detect which libvirt systemd unit to enable/start. Prefers the modular
# virtqemud when its unit file exists (openSUSE / modern Fedora), else the
# classic libvirtd. Prints the unit name (without .service) and returns 0, or
# returns 1 if neither unit file is installed.
_libvirt_unit_to_start() {
  if command -v systemctl >/dev/null 2>&1; then
    if systemctl list-unit-files 2>/dev/null | grep -q '^virtqemud\.service'; then
      echo "virtqemud"
      return 0
    fi
    if systemctl list-unit-files 2>/dev/null | grep -q '^libvirtd\.service'; then
      echo "libvirtd"
      return 0
    fi
  fi
  return 1
}

install_dynamic_binding_from_existing_config() {
  readable_file "$CONF_FILE" || die "Missing $CONF_FILE. Run the full installer first."

  say
  hdr "Switch to dynamic GPU binding (libvirt hook)"
  # Intro: color-emphasized summary of what dynamic binding does.
  if (( ENABLE_COLOR )); then
    note "This switches your existing setup from ${C_BOLD}early binding${C_RESET} to ${C_BOLD}${C_GREEN}dynamic binding${C_RESET}."
    note "Dynamic binding lets ${C_BOLD}amdgpu${C_RESET} load first and a libvirt qemu hook switches the"
    note "guest GPU to ${C_BOLD}vfio-pci${C_RESET} only when a VM that has it attached is started."
    note "This is more reliable for ${C_BOLD}RX 9070 / RDNA4${C_RESET} cards that hit the"
    note "${C_YELLOW}\"Unknown PCI header type 127\"${C_RESET} reset bug when bound to vfio-pci too early."
  else
    note "This switches your existing setup from early binding to dynamic binding."
    note "Dynamic binding lets amdgpu load first and a libvirt qemu hook switches the"
    note "guest GPU to vfio-pci only when a VM that has it attached is started."
    note "This is more reliable for RX 9070 / RDNA4 cards that hit the"
    note "\"Unknown PCI header type 127\" reset bug when bound to vfio-pci too early."
  fi
  say
  # "What this will do": numbered steps with green step numbers.
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}What this will do:${C_RESET}"
  else
    say "What this will do:"
  fi
  note "  ${C_GREEN}1${C_RESET}. Set VFIO_BINDING_MODE=dynamic in $CONF_FILE"
  note "  ${C_GREEN}2${C_RESET}. Regenerate $BIND_SCRIPT (deploys the latest bind/hook-runtime logic)"
  note "  ${C_GREEN}3${C_RESET}. Install the libvirt qemu hook ($LIBVIRT_HOOK_SCRIPT + $LIBVIRT_HOOK_ENTRY)"
  note "  ${C_GREEN}4${C_RESET}. Strip vfio-pci.ids= and rd.driver.pre=vfio-pci from the kernel cmdline"
  note "     (so amdgpu is allowed to claim the guest GPU at boot)"
  note "  ${C_GREEN}4b${C_RESET}. Ensure the AMD reset-bug kernel params (vfio-pci.disable_idle_d3=1,"
  note "      pcie_port_pm=off) are on the cmdline when the guest GPU is AMD"
  note "      (prevents the RX 9070 / RDNA4 D3cold reset bug; required for both modes)"
  note "      NOTE: vfio-pci.disable_idle_d3=1 is SKIPPED for RX 9070 / RDNA4 (Navi 48)"
  note "      because it worsens D3 issues there (card drops off the bus mid-session);"
  note "      pcie_port_pm=off is still added. The bind script's D0-lock"
  note "      (d3cold_allowed=0 + power/control=on) is the correct reset-bug defense."
  note "      Use --amd-disable-idle-d3 to force disable_idle_d3=1 anyway."
  note "  ${C_GREEN}5${C_RESET}. Sync BLS boot entries to the updated cmdline"
  note "  ${C_GREEN}6${C_RESET}. Pin Wayland compositors (KDE/KWin + wlroots: sway/hyprland/labwc) to the"
  note "     HOST GPU so binding the guest GPU does not crash the host compositor"
  note "     when the guest is Boot VGA)"
  note "  ${C_GREEN}7${C_RESET}. Install the reboot-FLR monitor (a systemd service that watches for guest"
  note "     warm reboot and does a soft FLR to clear the GPU display wedge so OVMF"
  note "     can re-POST without needing a host reboot — set on_reboot=restart in VM XML)"
  note "  ${C_GREEN}7b${C_RESET}. Install the park-keepalive monitor (instant on, no prompt): a systemd"
  note "      service that periodically checks the guest GPU while parked on vfio-pci"
  note "      between VM sessions and proactively recovers it if it died. Disable via"
  note "      VFIO_DYNAMIC_PARK_KEEPALIVE=0 in $CONF_FILE if you do not want this."
  note "  ${C_GREEN}8${C_RESET}. Stealth/perf VM tuning (optional, opt-in): on shut-off VMs with the guest GPU,"
  note "     apply SMBIOS spoofing + CPU hypervisor-bit disable + e1000e NIC + randomized"
  note "     disk serials + memballoon=none + iothreads/cputune + hypervisor hide"
  note "     (vendor_id=GENUINE00000 + kvm hidden). Verified (virt-xml-validate) + prompted."
  note "     Skipped unless --stealth-vm-tuning or you accept the prompt."
  say
  # "What stays unchanged": dim/blue style to distinguish from action steps.
  if (( ENABLE_COLOR )); then
    say "${C_DIM}What stays unchanged:${C_RESET}"
  else
    say "What stays unchanged:"
  fi
  note "  - IOMMU params (amd_iommu=on / intel_iommu=on, iommu=pt)"
  note "  - Optional AMD power-tradeoff params (amdgpu.runpm=0, amdgpu.noretry=0)"
  note "    are left as-is; only the reset-bug-critical pair is ensured (step 4b)"
  note "  - The vfio-bind-selected-gpu.service unit (becomes a no-op at boot in dynamic mode)"
  say

  # Libvirt presence + liveness check. Dynamic binding only works for
  # libvirt-managed VMs: the qemu hook is invoked by libvirt, not by raw qemu.
  # Stage 1: is any libvirt binary installed at all? (soft warning + continue.)
  if ! have_cmd libvirtd && ! have_cmd virtqemud && ! have_cmd virsh; then
    note "WARN: no libvirt daemon (libvirtd/virtqemud/virsh) detected."
    note "      Dynamic binding only works for libvirt-managed VMs."
    if ! prompt_yn "Continue anyway?" N "Dynamic binding"; then
      die "Aborted by user"
    fi
  elif ! libvirt_runtime_ok; then
    # Stage 2: a libvirt binary is installed but no daemon/socket is reachable.
    # This usually means the service was never enabled/started (common after a
    # fresh libvirt install). Offer to fix it so the qemu hook actually fires
    # when a VM starts; declining is non-fatal (user may start it manually).
    note "WARN: libvirt is installed but no libvirt daemon/socket is active"
    note "      (neither libvirtd nor virtqemud is running or socket-activated)."
    note "      The qemu hook only fires if libvirt is running when a VM starts."
    if prompt_yn "Enable + start the libvirt daemon now?" Y "Dynamic binding"; then
      local _lv_unit
      _lv_unit="$(_libvirt_unit_to_start || true)"
      if [[ -n "$_lv_unit" ]]; then
        run systemctl enable --now "$_lv_unit" 2>/dev/null || true
        if libvirt_runtime_ok; then
          say "libvirt daemon started ($_lv_unit)."
        else
          note "WARN: attempted to start $_lv_unit but libvirt is still not reachable."
          note "      Start it manually (e.g. 'sudo systemctl enable --now $_lv_unit') before launching a VM."
        fi
      else
        note "WARN: could not detect a libvirtd/virtqemud systemd unit to start."
        note "      Start libvirt manually before launching a VM."
      fi
    else
      note "libvirt not started; the qemu hook will not fire until libvirt is running."
    fi
  fi

  # 1. Flip the conf key.
  rewrite_conf_key "VFIO_BINDING_MODE" "dynamic"
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Set VFIO_BINDING_MODE=dynamic in $(_link "$CONF_FILE")"
  else
    say "  ✔ Set VFIO_BINDING_MODE=dynamic in $CONF_FILE"
  fi

  # 1b. Sync any missing fixed-default conf keys (advanced dynamic-binding /
  # park-keepalive / vBIOS knobs added to write_conf in later releases) into the
  # live conf, preserving existing user values. The switcher does not call
  # write_conf (it needs full wizard context), so without this step new keys
  # drift out of the live conf even after the bind script is regenerated.
  _sync_conf_defaults
  _ensure_guest_device_id_persisted

  # 2. Regenerate the bind script so the latest bind/hook-runtime logic (e.g.
  #    Boot-VGA host-assisted escape, d3cold pinning, retry/jlog behavior) is
  #    deployed without needing a full wizard re-run.
  install_bind_script
  if (( ENABLE_COLOR )); then
    say "  ${C_GREEN}✔${C_RESET} Regenerated $(_link "$BIND_SCRIPT")"
  else
    say "  ✔ Regenerated $BIND_SCRIPT"
  fi

  # 3. Install the libvirt hook.
  install_libvirt_hook

  # 3c. Install the reboot-FLR monitor (watches for guest warm reboot and does a
  #     soft FLR to clear the display wedge so OVMF re-POSTs without a host reboot).
  install_reboot_flr_monitor

  # 3c2. Install the park-keepalive monitor (instant on, no prompt): proactively
  #      recovers the guest GPU while it is parked on vfio-pci between VM sessions.
  install_park_keepalive_monitor

  # 3c3. vBIOS ROM auto-injection (opt-in prompt): pin a matching *.rom dump
  #       from VBIOS/ into each shut-off guest-GPU VM's hostdev, fixing a black
  #       screen caused by an unreliable live sysfs ROM read. If the user already
  #       has a vBIOS configured in their VM XML manually (or does not want one),
  #       they can skip this -- and selecting "no" REMOVES any script-installed
  #       vBIOS pin so the VM uses the live ROM read (or their manual config).
  #       Honors --vbios (force on) / --no-vbios (force skip + remove).
  if [[ "${VBIOS_INJECTION_OVERRIDE:-}" == "1" ]]; then
    install_vbios_romfile
  elif [[ "${VBIOS_INJECTION_OVERRIDE:-}" == "0" ]]; then
    note "vBIOS ROM auto-injection skipped (--no-vbios)."
    note "Removing any script-installed vBIOS pin so VMs use the live ROM read (or your manual config)..."
    remove_vbios_romfile
  else
    say
    if prompt_yn "Inject a matching vBIOS ROM dump into detected guest-GPU VMs? (say NO if you already have a vBIOS configured in your VM XML -- selecting NO will remove any script-installed vBIOS pin)" N "vBIOS ROM injection"; then
      install_vbios_romfile
    else
      note "Skipping vBIOS ROM auto-injection."
      note "Removing any script-installed vBIOS pin so VMs use the live ROM read (or your manual config)..."
      remove_vbios_romfile
    fi
  fi

  # 3d. Stealth/perf VM tuning (opt-in) — supersedes the minimal hypervisor-hide
  #     helper for the dynamic path. Applies the full Stealthy-VM tuning (which
  #     includes the hypervisor hide as a subset with a realistic OEM vendor_id)
  #     to each shut-off guest-GPU VM, verified + prompted. If the user selects
  #     "no", any previously-applied stealth tuning is REVERTED from the backup
  #     XML so the VM XML is clean (no leftover stealth config).
  #     Honors --stealth-vm-tuning (force on) / --no-stealth-vm-tuning (force skip + revert).
  if [[ "${STEALTH_VM_TUNING_OVERRIDE:-}" == "1" ]]; then
    install_stealth_vm_tuning
  elif [[ "${STEALTH_VM_TUNING_OVERRIDE:-}" == "0" ]]; then
    note "Stealth/perf VM tuning skipped (--no-stealth-vm-tuning)."
    note "Reverting any previously-applied stealth tuning from backup XML..."
    reset_stealth_vm_tuning
  else
    say
    if (( ENABLE_COLOR )); then
      say "${C_BOLD}${C_YELLOW}DISCLAIMER:${C_RESET} stealth/perf VM tuning is COSMETIC/PERFORMANCE realism only"
    else
      say "DISCLAIMER: stealth/perf VM tuning is COSMETIC/PERFORMANCE realism only"
    fi
    note "(SMBIOS spoofing, CPU/NIC/disk-serial values, hypervisor hide). It is NOT intended to,"
    note "and does NOT reliably, defeat or bypass anti-cheat / anti-tamper software. Using it to"
    note "evade anti-cheat in an online game may still violate that game's terms of service."
    if prompt_yn "Apply stealth/perf VM tuning (SMBIOS/CPU/NIC/disk serials/iothreads + hypervisor hide) to detected guest-GPU VMs now?" N "Stealth/perf VM tuning"; then
      install_stealth_vm_tuning
    else
      note "Skipping stealth/perf VM tuning."
      note "Reverting any previously-applied stealth tuning from backup XML..."
      reset_stealth_vm_tuning
    fi
  fi

  # 3d2. Ultimate-performance VM tuning (opt-in) — a SEPARATE, more aggressive
  #      perf layer than the basic perf subset bundled into stealth tuning above.
  #      Applies maximum-throughput knobs (disk cache=none/io=native/discard=unmap
  #      + virtio-blk multiqueue, scaled iothreads, aggressive cputune/numatune
  #      pinning, CPU topology + cache passthrough, no startup balloon, S3/S4
  #      disabled, optional hugepages + SATA->virtio conversion) to each shut-off
  #      guest-GPU VM WITHOUT touching stealth. Honors --ultimate-perf-vm-tuning
  #      (force on) / --no-ultimate-perf-vm-tuning (force skip). Selecting "no"
  #      just skips (reverting ultimate-perf is a separate explicit action:
  #      --reset-ultimate-perf-vm-tuning). The function prompts internally for
  #      the hugepages + SATA->virtio opt-ins.
  if [[ "${ULTIMATE_PERF_VM_TUNING_OVERRIDE:-}" == "1" ]]; then
    install_ultimate_perf_vm_tuning
  elif [[ "${ULTIMATE_PERF_VM_TUNING_OVERRIDE:-}" == "0" ]]; then
    note "Ultimate-performance VM tuning skipped (--no-ultimate-perf-vm-tuning)."
  else
    say
    note "Ultimate-performance VM tuning is a SEPARATE, more aggressive perf layer (stealth-safe:"
    note "it NEVER touches stealth). Knobs: disk I/O + multiqueue, scaled iothreads, aggressive"
    note "cputune/numatune pinning, CPU topology + cache passthrough, no startup balloon, S3/S4 off."
    note "Hugepages + SATA->virtio disk conversion are opt-in within it (prompted separately)."
    note "DISCLAIMER: performance tuning ONLY."
    if prompt_yn "Apply ultimate-performance VM tuning (stealth-safe) to detected guest-GPU VMs now?" N "Ultimate-perf VM tuning"; then
      install_ultimate_perf_vm_tuning
    else
      note "Skipping ultimate-performance VM tuning. You can apply it later with: sudo $SCRIPT_NAME --install-ultimate-perf-vm-tuning"
    fi
  fi

  # 3b. Pin KDE/KWin Wayland to the HOST GPU so binding the (Boot VGA) guest
  #     GPU at VM start does not crash the host compositor. No-op unless the
  #     guest GPU is Boot VGA.
  local _host_gpu _guest_gpu
  _host_gpu="$(awk -F= '/^HOST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  install_wayland_render_device_pin "$_host_gpu" "$_guest_gpu"

  # 4. Strip early-binding tokens from the kernel cmdline.
  if [[ -f /etc/kernel/cmdline ]]; then
    local kcur knew
    kcur="$(cat /etc/kernel/cmdline 2>/dev/null || true)"
    knew="$(strip_early_binding_tokens "$kcur")"
    knew="$(ensure_amd_reset_bug_params "$knew")"
    apply_binding_cmdline_change "$knew" ""
  elif [[ -f /etc/default/grub ]]; then
    # Classic GRUB only.
    backup_file /etc/default/grub
    local key current new
    key="$(grub_get_key 2>/dev/null || true)"
    if [[ -n "$key" ]]; then
      current="$(grub_read_cmdline "$key" 2>/dev/null || true)"
      new="$(strip_early_binding_tokens "$current")"
      new="$(ensure_amd_reset_bug_params "$new")"
      if [[ "$(trim "$new")" != "$(trim "$current")" ]]; then
        grub_write_cmdline_in_place "$key" "$(trim "$new")"
        if command -v update-grub >/dev/null 2>&1; then
          run update-grub
        elif command -v grub-mkconfig >/dev/null 2>&1; then
          local out
          [[ -d /boot/grub ]] && out=/boot/grub/grub.cfg || out=/boot/grub2/grub.cfg
          run grub-mkconfig -o "$out"
        elif command -v grub2-mkconfig >/dev/null 2>&1; then
          local out
          [[ -d /boot/grub2 ]] && out=/boot/grub2/grub.cfg || out=/boot/grub/grub.cfg
          run grub2-mkconfig -o "$out"
        fi
      fi
    fi
  fi

  say
  if (( ENABLE_COLOR )); then
    say "${C_GREEN}${C_BOLD}✔ Dynamic binding is now active${C_RESET} ${C_DIM}(takes effect on next boot)${C_RESET}"
  else
    say "✔ Dynamic binding is now active (takes effect on next boot)"
  fi
  note "The guest GPU will stay on amdgpu until you start a libvirt VM that has it attached."
  note "Keep pcie_port_pm=off on the kernel cmdline for both modes."
  note "Keep vfio-pci.disable_idle_d3=1 too -- EXCEPT on RX 9070 / RDNA4 (Navi 48), where it is skipped (it worsens D3 issues there; the bind script's D0-lock is the correct defense). Use --amd-disable-idle-d3 to force it."
  # RX 9070 / RDNA4 driver hint (R22b): the card dies ~25s into the first VM
  # session if the AMD Windows driver is not installed (the Microsoft Basic
  # Display Adapter leaves the GPU in an undefined state that crashes the PCIe
  # bus). Make this clear during install so the user knows to install the
  # driver before the first VM start. Only shown for RX 9070 / Navi 48.
  if _is_guest_rx9070_family; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_BOLD}${C_YELLOW}⚠ RX 9070 / RDNA4 driver requirement:${C_RESET}"
    else
      say "⚠ RX 9070 / RDNA4 driver requirement:"
    fi
    note "The guest GPU (RX 9070 / Navi 48) requires the AMD Windows driver to be installed"
    note "inside the VM for the card to survive VM sessions. Without the driver, Windows uses"
    note "the Microsoft Basic Display Adapter, which leaves the GPU in an undefined state that"
    note "crashes the host PCIe bus ~25 seconds into the session."
    note ""
    note "First boot: the card may die during the first VM session (before the driver can be"
    note "installed). This is expected — reboot the host, start the VM, and install the AMD"
    note "driver (Adrenalin) from AMD's website. Once the driver is installed, the card"
    note "stabilizes and survives full VM sessions + shutdown/restart cycles."
    note ""
    note "The bind script will send a desktop notification if it detects the driver is missing"
    note "(card dies during session with no prior successful session). Once a session survives,"
    note "the notification is suppressed (no false positives)."
  fi

  # 3e. Live-attach (hotplug GPU) — RECOMMENDED for RX 9070 / RDNA4. The card
  #     can still die on the first VM start / a parked restart (especially
  #     before the AMD Windows driver is installed); live-attach sidesteps that
  #     by starting the VM WITHOUT the GPU and hot-attaching it to the RUNNING
  #     VM once Windows is up. Complementary to the automatic SBR Phase-2
  #     force-kill recovery (R24): R24 re-enumerates a force-killed card, while
  #     live-attach avoids the cold-attach-at-boot death in the first place.
  #     Opt-in (default N). PREREQUISITE: the AMD Windows driver MUST be
  #     installed in the guest before the hot-attach will survive.
  if _is_guest_rx9070_family; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_BOLD}${C_YELLOW}RECOMMENDED for RX 9070 / RDNA4:${C_RESET} live-attach (hotplug GPU) workflow"
    else
      say "RECOMMENDED for RX 9070 / RDNA4: live-attach (hotplug GPU) workflow"
    fi
    note "The RX 9070 / RDNA4 can still die on the first VM start or a parked restart (the card"
    note "drops off the PCI bus on the D3cold exit before the AMD driver can stabilize it). The"
    note "live-attach (hotplug GPU) workflow sidesteps this: the VM starts WITHOUT the GPU"
    note "(Windows boots on a virtual display), and after a short delay the GPU is bound to"
    note "vfio-pci and hot-attached to the RUNNING VM once Windows is up — handed to a"
    note "driver-ready guest instead of cold-attached at boot. This is complementary to the"
    note "automatic SBR Phase-2 recovery that re-enumerates a force-killed card (virsh destroy"
    note "/ BSOD) via Secondary Bus Reset."
    note ""
    note "PREREQUISITE: the AMD Windows driver MUST already be installed inside the VM, or the"
    note "card dies ~25s after the hot-attach regardless. Setting this up removes the GPU hostdev"
    note "from the VM XML (a full backup is saved per VM); revert with --install-dynamic-binding."
    if prompt_yn "Set up the live-attach (hotplug GPU) workflow for RX 9070 / RDNA4 now?" N "Live-attach (hotplug GPU)"; then
      # `||` so a soft-fail (no shut-off VM with the guest GPU -> install_live_attach
      # returns 1) does NOT trip `set -e` and abort the wizard. Hard prerequisites
      # (missing conf / virsh / python3) call die, which is fatal by design and
      # already satisfied by the wizard above.
      install_live_attach || {
        note "Live-attach setup did not complete (no shut-off VM with the guest GPU was found,"
        note "or a prerequisite was missing). Shut off the VM and re-run:"
        note "  sudo $SCRIPT_NAME --install-live-attach"
      }
    else
      note "Skipping live-attach setup for now."
      note "Once the AMD Windows driver is installed and a VM session survives, enable it with:"
      note "  sudo $SCRIPT_NAME --install-live-attach"
      note "Reversible at any time with: sudo $SCRIPT_NAME --install-dynamic-binding"
    fi
    note ""
    note "Smart handoff (optional): with the virtio-win guest agent installed INSIDE Windows,"
    note "the live-attach helper hot-attaches the GPU the MOMENT Windows is up (guest-ping)"
    note "instead of after a blind fixed delay (often ~15s vs the full 30s)."
    note ""
    # Only offer the ISO attach when live-attach is active (the guest agent only helps the
    # live-attach helper's guest-ping poll). If live-attach is not set up, keep a text hint.
    if [[ -f "$CONF_FILE" ]] && grep -q '^VFIO_DYNAMIC_LIVE_ATTACH="1"' "$CONF_FILE" 2>/dev/null; then
      note "DISCLAIMER: this attaches the virtio-win driver ISO to your shut-off guest-GPU"
      note "VM(s) as a CD-ROM (host-side). It does NOT install the agent into Windows — that"
      note "step is manual: after the ISO is attached, start the VM, open the virtio-win CD in"
      note "File Explorer, and run virtio-win-guest-tools.exe. Until you do that, the fixed-"
      note "delay fallback still works, so nothing breaks. The VM MUST be shut off for the attach."
      note "Driver ISO archive (all released versions): $VIRTIO_WIN_ARCHIVE_URL"
      if prompt_yn "Attach the virtio-win driver ISO to your shut-off guest-GPU VM(s) now?" N "virtio-win guest agent"; then
        # `||` so a soft-fail (no shut-off guest-GPU VM / ISO could not be obtained) does NOT
        # trip `set -e` and abort the wizard. Hard prerequisites (missing conf / virsh /
        # python3) call die, which is fatal by design.
        install_virtio_win_guest_agent || {
          note "virtio-win ISO attach did not complete (no shut-off guest-GPU VM found, or the"
          note "ISO could not be obtained). Shut off the VM and re-run:"
          note "  sudo $SCRIPT_NAME --install-virtio-win-guest-agent"
        }
      else
        note "Skipping the virtio-win ISO attach for now. You can do it later with:"
        note "  sudo $SCRIPT_NAME --install-virtio-win-guest-agent"
      fi
    else
      note "This only helps once live-attach is set up. After enabling live-attach, attach the"
      note "driver ISO with: sudo $SCRIPT_NAME --install-virtio-win-guest-agent"
      note "Driver ISO archive (all released versions): $VIRTIO_WIN_ARCHIVE_URL"
    fi
  fi
}

install_early_binding_from_existing_config() {
  readable_file "$CONF_FILE" || die "Missing $CONF_FILE. Run the full installer first."

  say
  hdr "Switch back to early GPU binding (boot-time)"
  note "This switches your setup from dynamic binding back to early binding."
  note "Early binding forces the guest GPU onto vfio-pci at boot via vfio-pci.ids /"
  note "rd.driver.pre=vfio-pci / the bind systemd unit."
  say
  note "What this will do:"
  note "  1. Set VFIO_BINDING_MODE=early in $CONF_FILE"
  note "  2. Regenerate $BIND_SCRIPT (deploys the latest bind/boot-time logic)"
  note "  3. Remove the libvirt qemu hook (restoring any pre-existing hook from backup)"
  note "  4. Re-add vfio-pci.ids=<guest IDs> and rd.driver.pre=vfio-pci to the kernel cmdline"
  note "  4b. Ensure the AMD reset-bug kernel params (vfio-pci.disable_idle_d3=1,"
  note "      pcie_port_pm=off) are on the cmdline when the guest GPU is AMD"
  note "      (prevents the RX 9070 / RDNA4 D3cold reset bug; required for both modes)"
  note "      NOTE: vfio-pci.disable_idle_d3=1 is SKIPPED for RX 9070 / RDNA4 (Navi 48)"
  note "      because it worsens D3 issues there; pcie_port_pm=off is still added."
  note "      The bind script's D0-lock (d3cold_allowed=0 + power/control=on) is the"
  note "      correct reset-bug defense. Use --amd-disable-idle-d3 to force it anyway."
  note "  5. Sync BLS boot entries to the updated cmdline"
  note "  6. Remove the Wayland HOST-GPU render-device pins (early binding binds the"
  note "     guest GPU at boot, before the compositor starts, so the pins are no"
  note "     longer needed)"
  note "  7. Remove the reboot-FLR monitor (early binding does not use warm-reboot"
  note "     passthrough; the monitor is dynamic-binding-only)"
  note "  7b. Remove the park-keepalive monitor (dynamic-binding-only)"
  say
  # RX 9070 / RDNA4 driver hint (R22b): same as the dynamic switcher above.
  if _is_guest_rx9070_family; then
    if (( ENABLE_COLOR )); then
      say "${C_BOLD}${C_YELLOW}⚠ RX 9070 / RDNA4 driver requirement:${C_RESET}"
    else
      say "⚠ RX 9070 / RDNA4 driver requirement:"
    fi
    note "The guest GPU (RX 9070 / Navi 48) requires the AMD Windows driver to be installed"
    note "inside the VM for the card to survive VM sessions. Without the driver, the card"
    note "dies ~25s into the session (Microsoft Basic Display Adapter crashes the PCIe bus)."
    note "Install the AMD driver (Adrenalin) inside the Windows VM to stabilize the card."
    note "The bind script will notify you if it detects the driver is missing."
    say
  fi

  # 1. Flip the conf key.
  rewrite_conf_key "VFIO_BINDING_MODE" "early"
  say "Set VFIO_BINDING_MODE=early in $CONF_FILE"

  # 1b. Sync any missing fixed-default conf keys (advanced dynamic-binding /
  # park-keepalive / vBIOS knobs added to write_conf in later releases) into the
  # live conf, preserving existing user values. The switcher does not call
  # write_conf (it needs full wizard context), so without this step new keys
  # drift out of the live conf even after the bind script is regenerated.
  _sync_conf_defaults
  _ensure_guest_device_id_persisted

  # 2. Regenerate the bind script so the latest bind/boot-time logic is deployed
  #    without needing a full wizard re-run.
  install_bind_script
  say "Regenerated $BIND_SCRIPT"

  # 3. Remove the libvirt hook (restore pre-existing qemu hook or remove).
  if [[ -f "$LIBVIRT_HOOK_ENTRY" ]]; then
    local _hook_bak="" _hb
    for _hb in "${LIBVIRT_HOOK_ENTRY}".bak.*; do
      [[ -f "$_hb" ]] || continue
      if [[ -z "$_hook_bak" || "$_hb" -nt "$_hook_bak" ]]; then
        _hook_bak="$_hb"
      fi
    done
    if [[ -n "$_hook_bak" ]]; then
      note "Restoring pre-existing libvirt qemu hook from $(basename "$_hook_bak")"
      run cp -a "$_hook_bak" "$LIBVIRT_HOOK_ENTRY"
    else
      run rm -f "$LIBVIRT_HOOK_ENTRY"
    fi
  fi
  run rm -f "$LIBVIRT_HOOK_SCRIPT"
  say "Removed libvirt qemu hook."

  # 3b. Remove the KDE/KWin Wayland HOST-GPU render-device pin: early binding
  #     parks the guest GPU on vfio-pci at boot (before the compositor starts),
  #     so the compositor never renders on it and the pin is no longer needed.
  remove_wayland_render_device_pin

  # 3c. Remove the reboot-FLR monitor (dynamic-binding-only).
  remove_reboot_flr_monitor

  # 3c2. Remove the park-keepalive monitor (dynamic-binding-only).
  remove_park_keepalive_monitor

  # 3c3. Remove the vBIOS ROM auto-injection (dynamic-binding-only).
  remove_vbios_romfile

  # 3c4. Remove the live-attach (hotplug GPU) workflow (dynamic-binding-only).
  remove_live_attach

  # 4. Re-add early-binding tokens to the kernel cmdline.
  local guest_ids
  guest_ids="$(build_vfio_pci_ids_from_conf)"
  if [[ -z "$guest_ids" ]]; then
    note "WARN: could not determine guest GPU vendor:device IDs from $CONF_FILE via lspci."
    note "      Skipping vfio-pci.ids re-add. You may need to re-run the full installer."
  fi

  if [[ -f /etc/kernel/cmdline ]]; then
    local kcur knew
    kcur="$(cat /etc/kernel/cmdline 2>/dev/null || true)"
    knew="$kcur"
    if [[ -n "$guest_ids" ]]; then
      knew="$(add_param_once "$knew" "vfio-pci.ids=$guest_ids")"
    fi
    if command -v dracut >/dev/null 2>&1 && vfio_pci_available; then
      knew="$(add_param_once "$knew" "rd.driver.pre=vfio-pci")"
    fi
    knew="$(ensure_amd_reset_bug_params "$knew")"
    apply_binding_cmdline_change "$knew" ""
  elif [[ -f /etc/default/grub ]]; then
    backup_file /etc/default/grub
    local key current new
    key="$(grub_get_key 2>/dev/null || true)"
    if [[ -n "$key" ]]; then
      current="$(grub_read_cmdline "$key" 2>/dev/null || true)"
      new="$current"
      if [[ -n "$guest_ids" ]]; then
        new="$(add_param_once "$new" "vfio-pci.ids=$guest_ids")"
      fi
      if command -v dracut >/dev/null 2>&1 && vfio_pci_available; then
        new="$(add_param_once "$new" "rd.driver.pre=vfio-pci")"
      fi
      new="$(ensure_amd_reset_bug_params "$new")"
      if [[ "$(trim "$new")" != "$(trim "$current")" ]]; then
        grub_write_cmdline_in_place "$key" "$(trim "$new")"
        if command -v update-grub >/dev/null 2>&1; then
          run update-grub
        elif command -v grub-mkconfig >/dev/null 2>&1; then
          local out
          [[ -d /boot/grub ]] && out=/boot/grub/grub.cfg || out=/boot/grub2/grub.cfg
          run grub-mkconfig -o "$out"
        elif command -v grub2-mkconfig >/dev/null 2>&1; then
          local out
          [[ -d /boot/grub2 ]] && out=/boot/grub2/grub.cfg || out=/boot/grub/grub.cfg
          run grub2-mkconfig -o "$out"
        fi
      fi
    fi
  fi

  say
  say "Early binding is now active (takes effect on next boot)."
  say "The guest GPU will be bound to vfio-pci at boot by vfio-bind-selected-gpu.service."
}

# Detect-mode remediation: offer to switch to dynamic binding when AMD reset-bug
# markers are present and the guest GPU is still on amdgpu with early binding.
maybe_offer_detect_dynamic_binding() {
  [[ "${MODE:-}" == "detect" ]] || return 0
  readable_file "$CONF_FILE" || return 0

  # Only relevant for AMD guest GPUs.
  local guest_vendor
  guest_vendor="$(awk -F= '/^GUEST_GPU_VENDOR_ID=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ "${guest_vendor,,}" == "1002" ]] || return 0

  # Only if current binding mode is early (or unset).
  local current_mode
  current_mode="$(awk -F= '/^VFIO_BINDING_MODE=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  current_mode="${current_mode:-early}"
  current_mode="${current_mode^^}"
  [[ "$current_mode" == "EARLY" ]] || return 0

  # Check if the guest GPU is currently on amdgpu (not yet vfio-pci).
  local guest_gpu guest_drv
  guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$guest_gpu" ]] || return 0
  guest_drv="$(bdf_driver_name "$guest_gpu" 2>/dev/null || echo "")"
  [[ "$guest_drv" == "amdgpu" ]] || return 0

  # Check for AMD reset-bug markers in kernel logs.
  amd_reset_issue_signatures_present || return 0

  say
  hdr "Detect action (optional): switch to dynamic binding"
  note "AMD guest GPU is currently on amdgpu and reset-bug markers were detected in kernel logs."
  note "Dynamic binding (libvirt hook switches GPU at VM start) is more reliable for RX 9070 / RDNA4."
  note "This sets VFIO_BINDING_MODE=dynamic, installs the libvirt hook, and strips vfio-pci.ids /"
  note "rd.driver.pre=vfio-pci from the kernel cmdline."
  if ! prompt_yn "Switch to dynamic binding now from detect mode?" N "Dynamic binding"; then
    return 0
  fi
  if ! confirm_phrase "This will change your binding mode and kernel cmdline now." "SWITCH TO DYNAMIC"; then
    note "Skipping dynamic binding switch (confirmation phrase not provided)."
    return 0
  fi

  local prev_dry="${DRY_RUN:-0}"
  DRY_RUN=0
  install_dynamic_binding_from_existing_config
  DRY_RUN="$prev_dry"
}


# ---------------- Host audio default (PipeWire/PulseAudio) ----------------

install_audio_script() {
  backup_file "$AUDIO_SCRIPT"

  write_file_atomic "$AUDIO_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

CONF_FILE="/etc/vfio-gpu-passthrough.conf"

[[ -f "$CONF_FILE" ]] || exit 0
# shellcheck disable=SC1090
. "$CONF_FILE"

# Prefer stable PipeWire node.name if configured.
if command -v wpctl >/dev/null 2>&1 && [[ -n "${HOST_AUDIO_NODE_NAME:-}" ]]; then
  mapfile -t sink_ids < <(
    wpctl status | awk '
      /Sinks:/{ins=1;next}
      /Sources:/{ins=0}
      ins{
        for(i=1;i<=NF;i++){
          if($i ~ /^[0-9]+\.$/){ gsub("\\.","",$i); print $i; break }
        }
      }
    '
  )

  for id in "${sink_ids[@]}"; do
    node_name="$(wpctl inspect "$id" 2>/dev/null | awk -F' = ' '/node\.name/{gsub(/"/,"",$2); print $2; exit}')"
    if [[ "$node_name" == "$HOST_AUDIO_NODE_NAME" ]]; then
      wpctl set-default "$id" || true
      exit 0
    fi
  done
  exit 0
fi

# Fallback: if configured with PCI BDFs, try to match on pci tag.
if command -v wpctl >/dev/null 2>&1 && [[ -n "${HOST_AUDIO_BDFS_CSV:-}" ]]; then
  host_bdf="${HOST_AUDIO_BDFS_CSV%%,*}"
  if [[ -n "$host_bdf" ]]; then
    pci_tag="$(echo "$host_bdf" | sed -E 's/^0000:/pci-0000_/; s/:/_/g')"

    mapfile -t sink_ids < <(
      wpctl status | awk '
        /Sinks:/{ins=1;next}
        /Sources:/{ins=0}
        ins{
          for(i=1;i<=NF;i++){
            if($i ~ /^[0-9]+\.$/){ gsub("\\.","",$i); print $i; break }
          }
        }
      '
    )

    for id in "${sink_ids[@]}"; do
      if wpctl inspect "$id" 2>/dev/null | grep -Fq "$pci_tag"; then
        wpctl set-default "$id" || true
        exit 0
      fi
    done
  fi
  exit 0
fi

# PulseAudio fallback: set default sink by matching the node name.
if command -v pactl >/dev/null 2>&1 && [[ -n "${HOST_AUDIO_NODE_NAME:-}" ]]; then
  pactl set-default-sink "$HOST_AUDIO_NODE_NAME" || true
  exit 0
fi
EOF
}

install_user_audio_unit() {
  local user="${SUDO_USER:-}"
  if [[ -z "$user" ]]; then
    printf 'Which username should get the user systemd audio unit? (blank to skip) '
    read -r user
  fi
  [[ -n "$user" ]] || { say "Skipping user audio unit."; return 0; }

  local home
  home="$(getent passwd "$user" | cut -d: -f6)"
  [[ -n "$home" && -d "$home" ]] || { say "Skipping user audio unit (no home for $user)"; return 0; }

  local unit_dir="$home/.config/systemd/user"
  local unit_path="$unit_dir/vfio-set-host-audio.service"

  mkdir -p "$unit_dir"

  cat >"$unit_path" <<EOF
[Unit]
Description=Set default audio sink (helps keep host audio stable with VFIO)
After=pipewire.service wireplumber.service
ConditionPathExists=$AUDIO_SCRIPT

[Service]
Type=oneshot
ExecStart=$AUDIO_SCRIPT

[Install]
WantedBy=default.target
EOF

  chown -R "$user:$user" "$home/.config/systemd"
  # Enabling a user unit requires a running user systemd + DBus. If not available, don't spam errors.
  local uid
  uid="$(id -u "$user")"

  if command -v runuser >/dev/null 2>&1; then
    # Try best-effort with XDG_RUNTIME_DIR. If it still fails, we silently skip.
    runuser -u "$user" -- env XDG_RUNTIME_DIR="/run/user/$uid" systemctl --user daemon-reload >/dev/null 2>&1 || true
    runuser -u "$user" -- env XDG_RUNTIME_DIR="/run/user/$uid" systemctl --user enable vfio-set-host-audio.service >/dev/null 2>&1 || true
  fi

  note "User audio unit installed at: $unit_path"
  note "If it isn't enabled automatically, run after login: systemctl --user enable --now vfio-set-host-audio.service"
}
install_openbox_monitor_script() {
  backup_file "$OPENBOX_MONITOR_SCRIPT"

  write_file_atomic "$OPENBOX_MONITOR_SCRIPT" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

openbox_connected_outputs_from_xrandr_query() {
  awk '$2 == "connected" { print $1 }'
}

openbox_activate_all_connected_monitors() {
  command -v xrandr >/dev/null 2>&1 || return 0
  [[ -n "${DISPLAY:-}" ]] || return 0

  local query
  query="$(xrandr --query 2>/dev/null || true)"
  [[ -n "$query" ]] || return 0

  local -a outputs=()
  mapfile -t outputs < <(printf '%s\n' "$query" | openbox_connected_outputs_from_xrandr_query)
  (( ${#outputs[@]} > 0 )) || return 0

  local output
  for output in "${outputs[@]}"; do
    xrandr --output "$output" --auto >/dev/null 2>&1 || true
  done
}

openbox_activate_all_connected_monitors
EOF
}
install_openbox_autostart_hook() {
  local autostart_file="$OPENBOX_AUTOSTART_FILE"
  local autostart_dir
  autostart_dir="$(dirname "$autostart_file")"
  local marker_begin="# BEGIN VFIO OPENBOX MONITOR AUTO-ACTIVATE"
  local marker_end="# END VFIO OPENBOX MONITOR AUTO-ACTIVATE"

  if [[ "$(openbox_stack_status)" == "NOT_PRESENT" && ! -d "$autostart_dir" ]]; then
    note "Openbox stack not detected and $autostart_dir is missing; skipping Openbox monitor hook."
    return 0
  fi

  if (( ! DRY_RUN )); then
    mkdir -p "$autostart_dir"
  fi

  backup_file "$autostart_file"

  local tmp mode owner group
  tmp="$(mktemp)"
  if [[ -f "$autostart_file" ]]; then
    awk -v begin="$marker_begin" -v end="$marker_end" '
      $0 == begin { skip=1; next }
      $0 == end { skip=0; next }
      !skip { print }
    ' "$autostart_file" >"$tmp"
    mode="$(stat -c '%a' "$autostart_file" 2>/dev/null || echo 644)"
    owner="$(stat -c '%u' "$autostart_file" 2>/dev/null || id -u)"
    group="$(stat -c '%g' "$autostart_file" 2>/dev/null || id -g)"
  else
    : >"$tmp"
    mode=644
    owner=0
    group=0
  fi

  {
    if [[ -s "$tmp" ]]; then
      cat "$tmp"
      printf '\n'
    fi
    cat <<EOF
$marker_begin
if [ -x "$OPENBOX_MONITOR_SCRIPT" ]; then
  "$OPENBOX_MONITOR_SCRIPT" >/dev/null 2>&1 &
fi
$marker_end
EOF
  } >"${tmp}.new"
  mv "${tmp}.new" "$tmp"

  if (( DRY_RUN )); then
    rm -f "$tmp" || true
    return 0
  fi

  install -o "$owner" -g "$group" -m "$mode" "$tmp" "$autostart_file"
  rm -f "$tmp" || true
  note "Openbox monitor hook ensured at: $autostart_file"
}
remove_openbox_autostart_hook() {
  local autostart_file="$OPENBOX_AUTOSTART_FILE"
  local marker_begin="# BEGIN VFIO OPENBOX MONITOR AUTO-ACTIVATE"
  local marker_end="# END VFIO OPENBOX MONITOR AUTO-ACTIVATE"
  [[ -f "$autostart_file" ]] || return 0

  backup_file "$autostart_file"

  local tmp mode owner group
  tmp="$(mktemp)"
  awk -v begin="$marker_begin" -v end="$marker_end" '
    $0 == begin { skip=1; next }
    $0 == end { skip=0; next }
    !skip { print }
  ' "$autostart_file" >"$tmp"
  mode="$(stat -c '%a' "$autostart_file" 2>/dev/null || echo 644)"
  owner="$(stat -c '%u' "$autostart_file" 2>/dev/null || id -u)"
  group="$(stat -c '%g' "$autostart_file" 2>/dev/null || id -g)"

  if (( DRY_RUN )); then
    rm -f "$tmp" || true
    return 0
  fi

  install -o "$owner" -g "$group" -m "$mode" "$tmp" "$autostart_file"
  rm -f "$tmp" || true
}
install_openbox_monitor_activation() {
  install_openbox_monitor_script
  install_openbox_autostart_hook
}

install_udev_isolation() {
  local gpu_bdf="$1"
  local audio_csv="$2"

  local rule_file="$UDEV_ISOLATION_RULE"
  backup_file "$rule_file"

  # Base rule for the guest GPU itself.
  write_file_atomic "$rule_file" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Remove Guest GPU from the master seat to prevent the host desktop from grabbing it.

# GPU
ACTION=="add", SUBSYSTEM=="pci", KERNELS=="$gpu_bdf", TAG-="seat", TAG-="master-of-seat"
EOF

  # Append rules for any associated guest audio PCI functions (if provided).
  if [[ -n "$audio_csv" ]]; then
    local IFS=',' aud
    for aud in $audio_csv; do
      [[ -n "$aud" ]] || continue
      if (( DRY_RUN )); then
        continue
      fi
      printf '%s\n' "ACTION==\"add\", SUBSYSTEM==\"pci\", KERNELS==\"$aud\", TAG-=\"seat\", TAG-=\"master-of-seat\"" >>"$rule_file" || true
    done
  fi

  if have_cmd udevadm; then
    run udevadm control --reload-rules
    run udevadm trigger
  fi

  say "Installed udev isolation rules to prevent the host UI from grabbing the guest GPU (and HDMI audio, if selected)."
}
usb_bt_mitigation_status() {
  hdr "USB Mitigation Status"
  local state_file="$USB_BT_STATE_FILE"

  if [[ -f "$state_file" ]]; then
    local total_runs=0
    local last_run=""
    local -A run_counts=()
    local line ts mode targets
    while IFS= read -r line; do
      [[ -n "$line" ]] || continue
      ts="$(printf "%s" "$line" | sed -n 's/^timestamp=\([^ ]*\) mode=.*/\1/p')"
      mode="$(printf "%s" "$line" | sed -n 's/.*mode=\([^ ]*\) targets=.*/\1/p')"
      targets="$(printf "%s" "$line" | sed -n 's/.*targets=\(.*\)/\1/p')"
      [[ -n "$ts" ]] && last_run="$ts"
      total_runs=$((total_runs + 1))
      local dev_id
      for dev_id in $(printf "%s" "$targets" | tr ',' '\n'); do
        [[ -n "$dev_id" ]] || continue
        run_counts["$dev_id"]=$((${run_counts[$dev_id]:-0} + 1))
      done
    done <"$state_file"

    say "Mitigation state file: $state_file"
    say "Total recorded runs: $total_runs"
    [[ -n "$last_run" ]] && say "Last run: $last_run"
    say

    if (( ${#run_counts[@]} > 0 )); then
      hdr "Per-device mitigation run counts"
      local dev_id count
      for dev_id in "${!run_counts[@]}"; do
        count="${run_counts[$dev_id]}"
        if (( ENABLE_COLOR )); then
          say "  ${C_CYAN}$dev_id${C_RESET}: $count run(s)"
        else
          say "  $dev_id: $count run(s)"
        fi
      done
    fi
  else
    note "No mitigation state file found ($state_file). Run the mitigation at least once to collect data."
  fi

  say
  hdr "Recent kernel USB instability markers"
  if ! have_cmd journalctl; then
    note "journalctl not available; skipping kernel log scan."
    return 0
  fi

  local log_data reset_count timeout_count enum_err_count disconnect_count
  log_data="$(journalctl -k -b --no-pager 2>/dev/null || true)"
  if [[ -z "$log_data" ]] && have_cmd dmesg; then
    log_data="$(dmesg 2>/dev/null || true)"
  fi

  if [[ -z "$log_data" ]]; then
    note "No kernel log data available."
    return 0
  fi

  reset_count="$(awk 'BEGIN{IGNORECASE=1} /reset (high-speed|full-speed|SuperSpeed) USB device/ {c++} END{print c+0}' <<<"$log_data")"
  timeout_count="$(awk 'BEGIN{IGNORECASE=1} /tx timeout|Read reg16 failed|command 0x[0-9a-f]+ tx timeout/ {c++} END{print c+0}' <<<"$log_data")"
  enum_err_count="$(awk 'BEGIN{IGNORECASE=1} /unable to enumerate USB device|device descriptor read\/64|can.t set config|can.t set address|over-current/ {c++} END{print c+0}' <<<"$log_data")"
  disconnect_count="$(awk 'BEGIN{IGNORECASE=1} /USB disconnect, device number/ {c++} END{print c+0}' <<<"$log_data")"

  print_kv "USB resets" "$reset_count"
  print_kv "BT/USB timeouts" "$timeout_count"
  print_kv "Enumeration errors" "$enum_err_count"
  print_kv "Disconnect events" "$disconnect_count"

  local score=0
  if (( reset_count > 0 || timeout_count > 0 || enum_err_count > 0 || disconnect_count >= 8 )); then
    score=1
  fi

  if (( score > 0 )); then
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: Unstable USB devices detected; consider mitigation or EEE-off tuning."
    else
      say "WARN: Unstable USB devices detected; consider mitigation or EEE-off tuning."
    fi
  else
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}OK${C_RESET}: No obvious USB instability markers in current boot."
    else
      say "OK: No obvious USB instability markers in current boot."
    fi
  fi
}


usb_bt_mitigation_explain() {
  note "This optional feature targets USB Bluetooth timeout/reset storms that can destabilize other USB devices and hurt passthrough stability."
  note
  note "Typical kernel log pattern:"
  note "  - Bluetooth: hci0: command ... tx timeout"
  note "  - Bluetooth: hci0: Resetting usb device"
  note "  - usb X-Y: reset ... USB device"
  note
  note "Why this matters:"
  note "  - repeated resets are often a real recovery loop, not harmless log noise"
  note "  - instability can spread across the same USB hub/controller path"
  note "  - symptoms may include random disconnects, replug-required devices, and storage glitches"
  note
  note "Advanced fallback knobs in $USB_BT_MATCH_CONF:"
  note "  - USB_BT_STOP_BLUETOOTH_SERVICE=\"1\" (default): stop/start bluetooth.service with mitigation lifecycle"
  note "  - USB_BT_HARD_BLOCK=\"1\": additionally toggle USB authorized=0/1 on matched devices"
  note "    While authorized=0, matched devices are unavailable to both host usage and VM USB passthrough attach."
  note "    Use this only as a last-resort fallback when detach-only mitigation still cannot stop reset/timeout loops."
  note "  - USB_BT_HARD_BLOCK_IDS=\"vid:pid,...\": optional scope for hard-block targets"
}
usb_sysfs_device_is_bluetooth() {
  # Return 0 if the sysfs USB device directory appears to expose Bluetooth
  # interfaces (btusb driver, interface class/subclass e0/01, or Bluetooth
  # product/manufacturer text fallback).
  local dev="$1" intf cls sub drv text_hint
  shopt -s nullglob
  for intf in "$dev":*; do
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      if [[ "$drv" == "btusb" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
    if [[ -f "$intf/bInterfaceClass" && -f "$intf/bInterfaceSubClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      sub="$(tr -d '\n' <"$intf/bInterfaceSubClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "e0" && "$sub" == "01" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
  done
  shopt -u nullglob
  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(bluetooth)' <<<"$text_hint"; then
    return 0
  fi
  return 1
}
usb_sysfs_device_is_ethernet() {
  # Return 0 if the USB device appears to be a network adapter (Ethernet/LAN).
  local dev="$1" intf cls drv text_hint
  shopt -s nullglob
  for intf in "$dev":*; do
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      case "$drv" in
        r8152|asix|ax88179_178a|cdc_ether|rndis_host|cdc_ncm|cdc_mbim|lan78xx|smsc95xx|qmi_wwan|aqc111)
          shopt -u nullglob
          return 0
          ;;
      esac
    fi
    if [[ -f "$intf/bInterfaceClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "02" || "$cls" == "0a" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
  done
  shopt -u nullglob

  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(ethernet|usb ?lan|network adapter|realtek.*lan|gigabit.*lan)' <<<"$text_hint"; then
    return 0
  fi
  return 1
}
usb_sysfs_device_is_printer() {
  # Return 0 if the USB device appears to be a printer.
  local dev="$1" intf cls drv text_hint
  shopt -s nullglob
  for intf in "$dev":*; do
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      if [[ "$drv" == "usblp" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
    if [[ -f "$intf/bInterfaceClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "07" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
  done
  shopt -u nullglob

  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(printer|print device)' <<<"$text_hint"; then
    return 0
  fi
  return 1
}
usb_sysfs_device_is_storage() {
  # Return 0 if the USB device appears to be storage (mass storage/SSD/HDD).
  local dev="$1" intf cls drv text_hint
  shopt -s nullglob
  for intf in "$dev":*; do
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      case "$drv" in
        usb-storage|uas)
          shopt -u nullglob
          return 0
          ;;
      esac
    fi
    if [[ -f "$intf/bInterfaceClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "08" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
  done
  shopt -u nullglob

  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(portable ssd|ssd|hdd|hard ?drive|mass storage|flash drive|thumb drive|external drive|usb disk|portable disk)' <<<"$text_hint"; then
    return 0
  fi
  return 1
}
ensure_usb_bt_match_conf_present() {
  # Ensure USB Bluetooth match policy config exists with safe defaults.
  local conf="$1"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] && return 0

  note "USB Bluetooth match config was missing; recreating defaults at: $conf"
  local conf_dir
  conf_dir="$(dirname "$conf")"
  mkdir -p "$conf_dir" 2>/dev/null || true
  cat >"$conf" <<'EOF'
# Generated by vfio.sh
# Match behavior for /usr/local/sbin/vfio-usb-bluetooth.sh
#
# MATCH_MODE:
#   auto         -> generic Bluetooth detection (btusb or class e0/01),
#                   then apply INCLUDE_IDS (if non-empty) and EXCLUDE_IDS.
#   include_only -> only match INCLUDE_IDS entries.
#
# INCLUDE_IDS / EXCLUDE_IDS entries are comma-separated VID:PID patterns.
# USB_BT_STOP_BLUETOOTH_SERVICE:
#   1 -> stop bluetooth.service when mitigation is active (disable mode),
#        then start it again in enable mode.
#   0 -> never change bluetooth.service state.
#
# USB_BT_HARD_BLOCK:
#   0 -> detach matching interfaces only.
#   1 -> additionally toggle /sys/bus/usb/devices/*/authorized for matching
#        devices (0 on disable, 1 on enable) as an aggressive fallback.
#
# USB_BT_HARD_BLOCK_IDS entries are comma-separated VID:PID patterns.
# Empty means "all matched mitigation targets".
#
# USB_ETHERNET_EEE_OFF:
#   0 -> do not change USB Ethernet EEE settings.
#   1 -> apply ethtool "eee off" on selected USB Ethernet IDs.
#
# USB_ETHERNET_EEE_IDS entries are comma-separated VID:PID patterns.
# Wildcards are supported per component:
#   *:*          (match all)
#   2357:*       (any product for vendor 2357)
#   *:0604       (any vendor with product 0604)
#   2357:0604    (exact match)
MATCH_MODE="auto"
INCLUDE_IDS=""
EXCLUDE_IDS=""
USB_BT_STOP_BLUETOOTH_SERVICE="1"
USB_BT_HARD_BLOCK="0"
USB_BT_HARD_BLOCK_IDS=""
USB_ETHERNET_EEE_OFF="0"
USB_ETHERNET_EEE_IDS=""
EOF
  chmod 0644 "$conf" 2>/dev/null || true
  [[ -f "$conf" ]]
}
ensure_usb_bt_match_conf_keys_present() {
  # Backfill newly introduced match-config keys for existing installs while
  # keeping current values for already-present keys.
  local conf="$1"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] || return 1

  local changed=0
  if ! grep -Eq '^USB_BT_STOP_BLUETOOTH_SERVICE=' "$conf" 2>/dev/null; then
    if (( DRY_RUN )); then
      note "DRY RUN: would append USB_BT_STOP_BLUETOOTH_SERVICE=\"1\" to $conf"
    else
      printf '%s\n' 'USB_BT_STOP_BLUETOOTH_SERVICE="1"' >>"$conf"
    fi
    changed=1
  fi
  if ! grep -Eq '^USB_BT_HARD_BLOCK=' "$conf" 2>/dev/null; then
    if (( DRY_RUN )); then
      note "DRY RUN: would append USB_BT_HARD_BLOCK=\"0\" to $conf"
    else
      printf '%s\n' 'USB_BT_HARD_BLOCK="0"' >>"$conf"
    fi
    changed=1
  fi
  if ! grep -Eq '^USB_BT_HARD_BLOCK_IDS=' "$conf" 2>/dev/null; then
    if (( DRY_RUN )); then
      note "DRY RUN: would append USB_BT_HARD_BLOCK_IDS=\"\" to $conf"
    else
      printf '%s\n' 'USB_BT_HARD_BLOCK_IDS=""' >>"$conf"
    fi
    changed=1
  fi

  if (( changed )); then
    note "Updated USB mitigation policy defaults in: $conf"
  fi
  return 0
}
update_usb_bt_match_conf_values() {
  # Update MATCH_MODE / INCLUDE_IDS / EXCLUDE_IDS keys in-place, preserving
  # unrelated lines and file ownership/mode.
  local conf="$1" mode_value="$2" include_value="$3" exclude_value="$4"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] || return 1

  local tmp file_mode file_owner file_group
  tmp="$(mktemp)"
  awk -v mode_val="$mode_value" -v include_val="$include_value" -v exclude_val="$exclude_value" '
    BEGIN { done_mode=0; done_include=0; done_exclude=0 }
    /^MATCH_MODE=/ {
      print "MATCH_MODE=\"" mode_val "\""
      done_mode=1
      next
    }
    /^INCLUDE_IDS=/ {
      print "INCLUDE_IDS=\"" include_val "\""
      done_include=1
      next
    }
    /^EXCLUDE_IDS=/ {
      print "EXCLUDE_IDS=\"" exclude_val "\""
      done_exclude=1
      next
    }
    { print }
    END {
      if (!done_mode) {
        print "MATCH_MODE=\"" mode_val "\""
      }
      if (!done_include) {
        print "INCLUDE_IDS=\"" include_val "\""
      }
      if (!done_exclude) {
        print "EXCLUDE_IDS=\"" exclude_val "\""
      }
    }
  ' "$conf" >"$tmp"

  file_mode="$(stat -c '%a' "$conf" 2>/dev/null || echo 644)"
  file_owner="$(stat -c '%u' "$conf" 2>/dev/null || id -u)"
  file_group="$(stat -c '%g' "$conf" 2>/dev/null || id -g)"
  install -o "$file_owner" -g "$file_group" -m "$file_mode" "$tmp" "$conf"
  rm -f "$tmp" || true
  return 0
}
normalize_usb_ethernet_eee_flag() {
  local raw="${1:-0}"
  raw="${raw,,}"
  case "$raw" in
    1|y|yes|true|on) printf '1\n' ;;
    *) printf '0\n' ;;
  esac
}
normalize_usb_bt_boolean_flag() {
  local raw="${1:-0}"
  raw="${raw,,}"
  case "$raw" in
    1|y|yes|true|on) printf '1\n' ;;
    *) printf '0\n' ;;
  esac
}
normalize_usb_id_pattern_csv() {
  # Normalize comma/space separated USB VID:PID pattern text to canonical
  # lowercase comma-separated form; invalid tokens are ignored.
  local raw="${1:-}" token out=""
  raw="${raw//,/ }"
  for token in $raw; do
    token="${token,,}"
    token="${token//[[:space:]]/}"
    [[ -n "$token" ]] || continue
    if [[ "$token" =~ ^[0-9a-f\*]+:[0-9a-f\*]+$ ]]; then
      out+="${out:+,}$token"
    else
      note "Ignoring invalid USB ID pattern: $token" >&2
    fi
  done
  printf '%s\n' "$out"
}
normalize_usb_id_component() {
  local v="${1,,}"
  v="${v#0x}"
  printf '%s\n' "$v"
}
usb_id_pattern_matches() {
  local pattern="${1,,}" vid="$2" pid="$3"
  local pvid ppid
  [[ "$pattern" == *:* ]] || return 1
  pvid="$(normalize_usb_id_component "${pattern%%:*}")"
  ppid="$(normalize_usb_id_component "${pattern##*:}")"
  [[ -n "$pvid" && -n "$ppid" ]] || return 1
  [[ "$pvid" == "*" || "$pvid" == "$vid" ]] || return 1
  [[ "$ppid" == "*" || "$ppid" == "$pid" ]] || return 1
  return 0
}
usb_id_in_csv_patterns() {
  local csv="$1" vid="$2" pid="$3" item
  [[ -n "$csv" ]] || return 1
  local IFS=','
  for item in $csv; do
    item="${item//[[:space:]]/}"
    [[ -n "$item" ]] || continue
    if usb_id_pattern_matches "$item" "$vid" "$pid"; then
      return 0
    fi
  done
  return 1
}
usb_bt_device_matches_policy_from_conf() {
  local dev="$1" match_mode="$2" include_ids="$3" exclude_ids="$4" vid pid
  vid="$(normalize_usb_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_usb_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1

  if [[ "$match_mode" == "include_only" ]]; then
    usb_id_in_csv_patterns "$include_ids" "$vid" "$pid" || return 1
  else
    usb_sysfs_device_is_bluetooth "$dev" || return 1
    if [[ -n "$include_ids" ]] && ! usb_id_in_csv_patterns "$include_ids" "$vid" "$pid"; then
      return 1
    fi
  fi
  if usb_id_in_csv_patterns "$exclude_ids" "$vid" "$pid"; then
    return 1
  fi
  return 0
}
usb_bt_device_matches_hard_block_scope_from_conf() {
  local dev="$1" hard_block="$2" hard_block_ids="$3" vid pid
  [[ "$hard_block" == "1" ]] || return 1
  if [[ -z "$hard_block_ids" ]]; then
    return 0
  fi
  vid="$(normalize_usb_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_usb_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1
  usb_id_in_csv_patterns "$hard_block_ids" "$vid" "$pid"
}
restore_usb_bt_authorized_targets_for_hard_block_disable() {
  # When hard-block is switched off, restore authorized=1 for targets that
  # matched the previously active hard-block policy.
  local match_mode="$1" include_ids="$2" exclude_ids="$3" hard_block_ids="$4"
  local usb_devices_glob dev name vid pid auth_before restored_count
  restored_count=0
  usb_devices_glob="${VFIO_USB_SYSFS_GLOB:-/sys/bus/usb/devices/*}"
  for dev in $usb_devices_glob; do
    [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
    name="$(basename "$dev")"
    [[ "$name" =~ ^[0-9]+-[0-9]+(\.[0-9]+)*$ ]] || continue
    if ! usb_bt_device_matches_policy_from_conf "$dev" "$match_mode" "$include_ids" "$exclude_ids"; then
      continue
    fi
    if ! usb_bt_device_matches_hard_block_scope_from_conf "$dev" "1" "$hard_block_ids"; then
      continue
    fi
    [[ -f "$dev/authorized" ]] || continue
    auth_before="$(tr -d '\n' <"$dev/authorized" 2>/dev/null || true)"
    if [[ "$auth_before" == "1" ]]; then
      continue
    fi
    vid="$(normalize_usb_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '?')")"
    pid="$(normalize_usb_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '?')")"
    if (( DRY_RUN )); then
      note "DRY RUN: would restore USB authorized=1 for $name (${vid}:${pid}) while disabling hard-block."
      restored_count=$((restored_count + 1))
      continue
    fi
    if [[ -w "$dev/authorized" ]] && echo "1" >"$dev/authorized" 2>/dev/null; then
      note "Restored USB authorized=1 for $name (${vid}:${pid}) while disabling hard-block."
      restored_count=$((restored_count + 1))
    else
      note "Could not restore USB authorized=1 for $name (${vid}:${pid}); restore manually if needed."
    fi
  done
  if (( restored_count == 0 )); then
    note "No currently hard-blocked USB targets required authorized-state restore."
  fi
  return 0
}
usb_bt_device_matches_eee_scope_from_conf() {
  local dev="$1" eee_off="$2" eee_ids="$3" vid pid
  [[ "$eee_off" == "1" ]] || return 1
  usb_sysfs_device_is_ethernet "$dev" || return 1
  vid="$(normalize_usb_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_usb_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1
  if [[ -n "$eee_ids" ]] && ! usb_id_in_csv_patterns "$eee_ids" "$vid" "$pid"; then
    return 1
  fi
  return 0
}
update_usb_bt_hard_block_conf_values() {
  # Update USB_BT_HARD_BLOCK / USB_BT_HARD_BLOCK_IDS keys in-place,
  # preserving unrelated lines and file ownership/mode.
  local conf="$1" hard_block_value="$2" hard_block_ids_value="$3"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] || return 1

  local tmp file_mode file_owner file_group
  tmp="$(mktemp)"
  awk -v hard_val="$hard_block_value" -v ids_val="$hard_block_ids_value" '
    BEGIN { done_hard=0; done_ids=0 }
    /^USB_BT_HARD_BLOCK=/ {
      print "USB_BT_HARD_BLOCK=\"" hard_val "\""
      done_hard=1
      next
    }
    /^USB_BT_HARD_BLOCK_IDS=/ {
      print "USB_BT_HARD_BLOCK_IDS=\"" ids_val "\""
      done_ids=1
      next
    }
    { print }
    END {
      if (!done_hard) {
        print "USB_BT_HARD_BLOCK=\"" hard_val "\""
      }
      if (!done_ids) {
        print "USB_BT_HARD_BLOCK_IDS=\"" ids_val "\""
      }
    }
  ' "$conf" >"$tmp"

  file_mode="$(stat -c '%a' "$conf" 2>/dev/null || echo 644)"
  file_owner="$(stat -c '%u' "$conf" 2>/dev/null || id -u)"
  file_group="$(stat -c '%g' "$conf" 2>/dev/null || id -g)"
  install -o "$file_owner" -g "$file_group" -m "$file_mode" "$tmp" "$conf"
  rm -f "$tmp" || true
  return 0
}
update_usb_bt_service_guard_conf_value() {
  # Update USB_BT_STOP_BLUETOOTH_SERVICE key in-place, preserving unrelated
  # lines and file ownership/mode.
  local conf="$1" service_guard_value="$2"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] || return 1

  local tmp file_mode file_owner file_group
  tmp="$(mktemp)"
  awk -v guard_val="$service_guard_value" '
    BEGIN { done_guard=0 }
    /^USB_BT_STOP_BLUETOOTH_SERVICE=/ {
      print "USB_BT_STOP_BLUETOOTH_SERVICE=\"" guard_val "\""
      done_guard=1
      next
    }
    { print }
    END {
      if (!done_guard) {
        print "USB_BT_STOP_BLUETOOTH_SERVICE=\"" guard_val "\""
      }
    }
  ' "$conf" >"$tmp"

  file_mode="$(stat -c '%a' "$conf" 2>/dev/null || echo 644)"
  file_owner="$(stat -c '%u' "$conf" 2>/dev/null || id -u)"
  file_group="$(stat -c '%g' "$conf" 2>/dev/null || id -g)"
  install -o "$file_owner" -g "$file_group" -m "$file_mode" "$tmp" "$conf"
  rm -f "$tmp" || true
  return 0
}
update_usb_bt_ethernet_eee_conf_values() {
  # Update USB_ETHERNET_EEE_OFF / USB_ETHERNET_EEE_IDS keys in-place,
  # preserving unrelated lines and file ownership/mode.
  local conf="$1" eee_off_value="$2" eee_ids_value="$3"
  [[ -n "$conf" ]] || return 1
  [[ -f "$conf" ]] || return 1

  local tmp file_mode file_owner file_group
  tmp="$(mktemp)"
  awk -v off_val="$eee_off_value" -v ids_val="$eee_ids_value" '
    BEGIN { done_off=0; done_ids=0 }
    /^USB_ETHERNET_EEE_OFF=/ {
      print "USB_ETHERNET_EEE_OFF=\"" off_val "\""
      done_off=1
      next
    }
    /^USB_ETHERNET_EEE_IDS=/ {
      print "USB_ETHERNET_EEE_IDS=\"" ids_val "\""
      done_ids=1
      next
    }
    { print }
    END {
      if (!done_off) {
        print "USB_ETHERNET_EEE_OFF=\"" off_val "\""
      }
      if (!done_ids) {
        print "USB_ETHERNET_EEE_IDS=\"" ids_val "\""
      }
    }
  ' "$conf" >"$tmp"

  file_mode="$(stat -c '%a' "$conf" 2>/dev/null || echo 644)"
  file_owner="$(stat -c '%u' "$conf" 2>/dev/null || id -u)"
  file_group="$(stat -c '%g' "$conf" 2>/dev/null || id -g)"
  install -o "$file_owner" -g "$file_group" -m "$file_mode" "$tmp" "$conf"
  rm -f "$tmp" || true
  return 0
}
configure_usb_bt_ethernet_eee_interactive() {
  # Configure optional EEE-off policy for USB Ethernet adapters.
  USB_BT_ETH_EEE_CHANGED=0
  local conf="$USB_BT_MATCH_CONF"
  if [[ ! -f "$conf" ]]; then
    if ! ensure_usb_bt_match_conf_present "$conf"; then
      note "No USB Bluetooth match config available at $conf; skipping USB Ethernet EEE tuning."
      return 0
    fi
  fi

  local current_eee_off current_eee_ids
  current_eee_off="$(awk -F= '/^USB_ETHERNET_EEE_OFF=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_eee_ids="$(awk -F= '/^USB_ETHERNET_EEE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_eee_off="$(normalize_usb_ethernet_eee_flag "$current_eee_off")"
  current_eee_ids="${current_eee_ids:-}"

  local -a eth_ids=()
  local -a eth_labels=()
  local -A seen_eth_ids=()
  local usb_devices_glob
  local dev name vid pid manufacturer product line

  usb_devices_glob="${VFIO_USB_SYSFS_GLOB:-/sys/bus/usb/devices/*}"
  for dev in $usb_devices_glob; do
    [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
    name="$(basename "$dev")"
    [[ "$name" =~ ^[0-9]+-[0-9]+(\.[0-9]+)*$ ]] || continue
    if ! usb_sysfs_device_is_ethernet "$dev"; then
      continue
    fi

    vid="$(tr -d '\n' <"$dev/idVendor" 2>/dev/null | tr 'A-F' 'a-f')"
    pid="$(tr -d '\n' <"$dev/idProduct" 2>/dev/null | tr 'A-F' 'a-f')"
    [[ -n "$vid" && -n "$pid" ]] || continue
    [[ -n "${seen_eth_ids[$vid:$pid]:-}" ]] && continue
    seen_eth_ids["$vid:$pid"]=1

    manufacturer="$(cat "$dev/manufacturer" 2>/dev/null || true)"
    product="$(cat "$dev/product" 2>/dev/null || true)"
    line="$(trim "$name $vid:$pid $manufacturer $product")"
    eth_ids+=("$vid:$pid")
    eth_labels+=("$line")
  done

  if (( ${#eth_ids[@]} == 0 )); then
    note "No USB Ethernet devices detected for EEE-off tuning; leaving USB_ETHERNET_EEE_* unchanged."
    return 0
  fi

  say
  hdr "USB Ethernet EEE-off tuning"
  note "Optional: disable EEE on selected USB Ethernet adapters to reduce link-reset/retraining instability."
  note "Safeguard: this applies only to USB NICs (never motherboard/PCI Ethernet devices)."

  local default_choice
  default_choice="N"
  if [[ "$current_eee_off" == "1" ]]; then
    default_choice="Y"
  fi
  if ! prompt_yn "Enable USB Ethernet EEE-off tuning now?" "$default_choice" "USB Ethernet EEE"; then
    if [[ "$current_eee_off" == "0" && -z "$current_eee_ids" ]]; then
      note "USB Ethernet EEE-off tuning unchanged (disabled)."
      return 0
    fi
    if (( DRY_RUN )); then
      note "DRY RUN: would disable USB Ethernet EEE-off tuning in $conf"
      USB_BT_ETH_EEE_CHANGED=1
      return 0
    fi
    update_usb_bt_ethernet_eee_conf_values "$conf" "0" ""
    USB_BT_ETH_EEE_CHANGED=1
    note "Disabled USB Ethernet EEE-off tuning."
    return 0
  fi

  note "Detected USB Ethernet IDs:"
  local i
  for i in "${!eth_ids[@]}"; do
    local eth_idx_text
    eth_idx_text="[$((i+1))]"
    if (( ENABLE_COLOR )); then
      eth_idx_text="${C_BOLD}${C_GREEN}[$((i+1))]${C_RESET}"
    fi
    say "  ${eth_idx_text} ${eth_labels[$i]}"
  done

  local in out answer interactive_in_fd
  interactive_in_fd=""
  in="${VFIO_INTERACTIVE_IN:-/dev/stdin}"
  out="${VFIO_INTERACTIVE_OUT:-/dev/stderr}"
  if [[ -z "${VFIO_INTERACTIVE_IN:-}" && -z "${VFIO_INTERACTIVE_OUT:-}" && -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi
  if [[ -n "${VFIO_INTERACTIVE_IN:-}" ]]; then
    exec {interactive_in_fd}<"$in"
  fi
  printf '%s' "Enter numbers to apply EEE-off (comma/space separated, ENTER for all listed): " >"$out"
  if [[ -n "$interactive_in_fd" ]]; then
    read -r -u "$interactive_in_fd" answer || answer=""
  else
    read -r answer <"$in" || answer=""
  fi
  if [[ -n "$interactive_in_fd" ]]; then
    exec {interactive_in_fd}<&-
  fi
  answer="$(trim "$answer")"

  local target_ids=""
  if [[ -z "$answer" ]]; then
    target_ids="$(IFS=,; printf '%s' "${eth_ids[*]}")"
  else
    answer="${answer//,/ }"
    local token idx id
    local -A selected_eth=()
    for token in $answer; do
      if [[ ! "$token" =~ ^[0-9]+$ ]]; then
        note "Ignoring invalid token: $token"
        continue
      fi
      if (( token < 1 || token > ${#eth_ids[@]} )); then
        note "Ignoring out-of-range selection: $token"
        continue
      fi
      idx=$((token-1))
      id="${eth_ids[$idx]}"
      if [[ -z "${selected_eth[$id]:-}" ]]; then
        selected_eth["$id"]=1
        target_ids+="${target_ids:+,}$id"
      fi
    done
    if [[ -z "$target_ids" ]]; then
      target_ids="$(IFS=,; printf '%s' "${eth_ids[*]}")"
      note "No valid selection entered; defaulting to all detected USB Ethernet IDs."
    fi
  fi

  if [[ "$current_eee_off" == "1" && "$target_ids" == "$current_eee_ids" ]]; then
    note "USB Ethernet EEE-off tuning unchanged; skipping write."
    return 0
  fi
  if (( DRY_RUN )); then
    note "DRY RUN: would set USB_ETHERNET_EEE_OFF=\"1\" and USB_ETHERNET_EEE_IDS=\"$target_ids\" in $conf"
    USB_BT_ETH_EEE_CHANGED=1
    return 0
  fi
  update_usb_bt_ethernet_eee_conf_values "$conf" "1" "$target_ids"
  USB_BT_ETH_EEE_CHANGED=1
  say "Configured USB Ethernet EEE-off IDs: $target_ids"
}
configure_usb_bt_service_guard_interactive() {
  # Configure whether mitigation stop/start hooks manage bluetooth.service.
  USB_BT_SERVICE_GUARD_CHANGED=0
  local conf="$USB_BT_MATCH_CONF"
  if [[ ! -f "$conf" ]]; then
    if ! ensure_usb_bt_match_conf_present "$conf"; then
      note "No USB Bluetooth match config available at $conf; skipping bluetooth.service guard tuning."
      return 0
    fi
  fi

  local current_stop_service target_value default_choice current_status_label
  current_stop_service="$(awk -F= '/^USB_BT_STOP_BLUETOOTH_SERVICE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_stop_service="$(normalize_usb_bt_boolean_flag "$current_stop_service")"
  current_status_label="disabled"
  if [[ "$current_stop_service" == "1" ]]; then
    current_status_label="enabled"
  fi

  say
  hdr "USB mitigation bluetooth.service guard"
  note "When enabled, mitigation stops bluetooth.service before disable flow and starts it again in enable flow."
  note "Disable this only if you want mitigation to leave bluetooth.service untouched."
  note "Current status: bluetooth.service stop/start integration is $current_status_label."

  default_choice="Y"
  if [[ "$current_stop_service" != "1" ]]; then
    default_choice="N"
  fi
  if prompt_yn "Enable bluetooth.service stop/start integration?" "$default_choice" "USB bluetooth service guard"; then
    target_value="1"
  else
    target_value="0"
  fi

  if [[ "$target_value" == "$current_stop_service" ]]; then
    say "bluetooth.service stop/start integration remains <${current_status_label}>."
    return 0
  fi
  if (( DRY_RUN )); then
    note "DRY RUN: would set USB_BT_STOP_BLUETOOTH_SERVICE=\"$target_value\" in $conf"
    USB_BT_SERVICE_GUARD_CHANGED=1
    return 0
  fi
  update_usb_bt_service_guard_conf_value "$conf" "$target_value"
  USB_BT_SERVICE_GUARD_CHANGED=1
  if [[ "$target_value" == "1" ]]; then
    say "Configured bluetooth.service stop/start integration: <enabled>"
  else
    say "Configured bluetooth.service stop/start integration: <disabled>"
  fi
}
configure_usb_bt_hard_block_interactive() {
  # Configure optional aggressive USB authorized=0/1 fallback policy.
  USB_BT_HARD_BLOCK_CHANGED=0
  local conf="$USB_BT_MATCH_CONF"
  if [[ ! -f "$conf" ]]; then
    if ! ensure_usb_bt_match_conf_present "$conf"; then
      note "No USB Bluetooth match config available at $conf; skipping hard-block tuning."
      return 0
    fi
  fi

  local current_hard_block current_hard_block_ids current_match_mode current_include_ids current_exclude_ids
  current_hard_block="$(awk -F= '/^USB_BT_HARD_BLOCK=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_hard_block_ids="$(awk -F= '/^USB_BT_HARD_BLOCK_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_match_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_include_ids="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_exclude_ids="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_hard_block="$(normalize_usb_bt_boolean_flag "$current_hard_block")"
  current_hard_block_ids="${current_hard_block_ids:-}"
  current_match_mode="${current_match_mode:-auto}"
  case "$current_match_mode" in
    auto|include_only) ;;
    *) current_match_mode="auto" ;;
  esac
  current_include_ids="${current_include_ids:-}"
  current_exclude_ids="${current_exclude_ids:-}"

  say
  hdr "USB mitigation hard-block fallback"
  note "Optional aggressive mode: toggles /sys/bus/usb/devices/*/authorized (0 on disable, 1 on enable)."
  note "Passthrough impact: while authorized=0 is active, matched USB devices cannot be attached to VMs."
  note "Why this exists: some unstable adapters keep reset/timeout looping even after detach-only mitigation."
  note "Use only when regular detach is not enough for unstable adapters."

  local default_choice
  default_choice="N"
  if [[ "$current_hard_block" == "1" ]]; then
    default_choice="Y"
  fi
  if ! prompt_yn "Enable aggressive USB hard-block fallback now? (warning: active hard-block can block VM USB passthrough)" "$default_choice" "USB hard-block"; then
    if [[ "$current_hard_block" == "0" && -z "$current_hard_block_ids" ]]; then
      note "USB hard-block settings unchanged (disabled)."
      return 0
    fi
    if [[ "$current_hard_block" == "1" ]]; then
      restore_usb_bt_authorized_targets_for_hard_block_disable "$current_match_mode" "$current_include_ids" "$current_exclude_ids" "$current_hard_block_ids" || true
    fi
    if (( DRY_RUN )); then
      note "DRY RUN: would set USB_BT_HARD_BLOCK=\"0\" and USB_BT_HARD_BLOCK_IDS=\"\" in $conf"
      USB_BT_HARD_BLOCK_CHANGED=1
      return 0
    fi
    update_usb_bt_hard_block_conf_values "$conf" "0" ""
    USB_BT_HARD_BLOCK_CHANGED=1
    note "Disabled aggressive USB hard-block fallback."
    return 0
  fi

  note "Optional: scope hard-block to specific IDs using VID:PID patterns."
  note "Examples: 0a12:0001, 2357:*, *:0604"
  note "Leave empty to apply hard-block to all matched mitigation targets."
  if [[ -n "$current_hard_block_ids" ]]; then
    note "Current hard-block scope: $current_hard_block_ids"
  fi
  local match_mode include_ids exclude_ids
  match_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  include_ids="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  exclude_ids="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  match_mode="${match_mode:-auto}"
  case "$match_mode" in
    auto|include_only) ;;
    *) match_mode="auto" ;;
  esac

  local -a hard_candidate_ids=()
  local -a hard_candidate_labels=()
  local -a hard_candidate_index_colors=()
  local -A seen_hard_candidates=()
  local usb_devices_glob dev name vid pid manufacturer product line hint
  local is_bt is_eth is_prn is_stg
  local bt_hint_plain bt_hint_colored
  local eth_hint_plain eth_hint_colored
  local prn_hint_plain prn_hint_colored
  local stg_hint_plain stg_hint_colored
  bt_hint_plain="[hint: Bluetooth detected]"
  bt_hint_colored="[hint: ${C_BOLD}${C_YELLOW}Bluetooth detected${C_RESET}]"
  eth_hint_plain="[keep-bound: Ethernet]"
  eth_hint_colored="[keep-bound: ${C_BOLD}${C_GREEN}Ethernet${C_RESET}]"
  prn_hint_plain="[keep-bound: Printer]"
  prn_hint_colored="[keep-bound: ${C_BOLD}${C_BLUE}Printer${C_RESET}]"
  stg_hint_plain="[danger: Storage]"
  stg_hint_colored="[danger: ${C_BOLD}${C_RED}Storage${C_RESET}]"

  usb_devices_glob="${VFIO_USB_SYSFS_GLOB:-/sys/bus/usb/devices/*}"
  for dev in $usb_devices_glob; do
    [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
    name="$(basename "$dev")"
    [[ "$name" =~ ^[0-9]+-[0-9]+(\.[0-9]+)*$ ]] || continue
    if ! usb_bt_device_matches_policy_from_conf "$dev" "$match_mode" "$include_ids" "$exclude_ids"; then
      continue
    fi

    vid="$(tr -d '\n' <"$dev/idVendor" 2>/dev/null | tr 'A-F' 'a-f')"
    pid="$(tr -d '\n' <"$dev/idProduct" 2>/dev/null | tr 'A-F' 'a-f')"
    [[ -n "$vid" && -n "$pid" ]] || continue
    [[ -n "${seen_hard_candidates[$vid:$pid]:-}" ]] && continue
    seen_hard_candidates["$vid:$pid"]=1

    manufacturer="$(cat "$dev/manufacturer" 2>/dev/null || true)"
    product="$(cat "$dev/product" 2>/dev/null || true)"
    line="$(trim "$name $vid:$pid $manufacturer $product")"
    hint=""
    is_bt=0
    is_eth=0
    is_prn=0
    is_stg=0
    if usb_sysfs_device_is_bluetooth "$dev"; then
      is_bt=1
      if (( ENABLE_COLOR )); then
        hint+=" $bt_hint_colored"
      else
        hint+=" $bt_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_ethernet "$dev"; then
      is_eth=1
      if (( ENABLE_COLOR )); then
        hint+=" $eth_hint_colored"
      else
        hint+=" $eth_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_printer "$dev"; then
      is_prn=1
      if (( ENABLE_COLOR )); then
        hint+=" $prn_hint_colored"
      else
        hint+=" $prn_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_storage "$dev"; then
      is_stg=1
      if (( ENABLE_COLOR )); then
        hint+=" $stg_hint_colored"
      else
        hint+=" $stg_hint_plain"
      fi
    fi
    line+="$hint"
    hard_candidate_ids+=("$vid:$pid")
    hard_candidate_labels+=("$line")
    if (( is_stg )); then
      hard_candidate_index_colors+=("${C_BOLD}${C_RED}")
    elif (( is_bt )); then
      hard_candidate_index_colors+=("${C_BOLD}${C_YELLOW}")
    elif (( is_eth )); then
      hard_candidate_index_colors+=("${C_BOLD}${C_GREEN}")
    elif (( is_prn )); then
      hard_candidate_index_colors+=("${C_BOLD}${C_BLUE}")
    else
      hard_candidate_index_colors+=("")
    fi
  done

  if (( ${#hard_candidate_ids[@]} > 0 )); then
    note "Detected mitigation-eligible USB targets under current policy:"
    local i idx_text
    for i in "${!hard_candidate_ids[@]}"; do
      idx_text="[$((i+1))]"
      if (( ENABLE_COLOR )) && [[ -n "${hard_candidate_index_colors[$i]:-}" ]]; then
        idx_text="${hard_candidate_index_colors[$i]}[$((i+1))]${C_RESET}"
      fi
      say "  ${idx_text} ${hard_candidate_labels[$i]}"
    done
    note "You can select by number (for example: 1 2) or by direct VID:PID patterns."
  else
    note "No mitigation-eligible USB targets are currently detected under active policy."
    note "You can still enter direct VID:PID patterns manually."
  fi

  local in out answer interactive_in_fd target_ids
  local in out answer interactive_in_fd target_ids
  interactive_in_fd=""
  in="${VFIO_INTERACTIVE_IN:-/dev/stdin}"
  out="${VFIO_INTERACTIVE_OUT:-/dev/stderr}"
  if [[ -z "${VFIO_INTERACTIVE_IN:-}" && -z "${VFIO_INTERACTIVE_OUT:-}" && -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi
  if [[ -n "${VFIO_INTERACTIVE_IN:-}" ]]; then
    exec {interactive_in_fd}<"$in"
  fi
  printf '%s' "Enter hard-block targets (numbers and/or VID:PID patterns, comma/space separated, ENTER for all matched): " >"$out"
  if [[ -n "$interactive_in_fd" ]]; then
    read -r -u "$interactive_in_fd" answer || answer=""
  else
    read -r answer <"$in" || answer=""
  fi
  if [[ -n "$interactive_in_fd" ]]; then
    exec {interactive_in_fd}<&-
  fi
  answer="$(trim "$answer")"

  target_ids=""
  if [[ -n "$answer" ]]; then
    answer="${answer//,/ }"
    local token idx id lhs rhs
    local -A selected_hard=()
    for token in $answer; do
      id=""
      if [[ "$token" =~ ^[0-9]+$ ]]; then
        if (( ${#hard_candidate_ids[@]} == 0 )); then
          note "Ignoring numeric selection without listed targets: $token"
          continue
        fi
        if (( token < 1 || token > ${#hard_candidate_ids[@]} )); then
          note "Ignoring out-of-range selection: $token"
          continue
        fi
        idx=$((token-1))
        id="${hard_candidate_ids[$idx]}"
      elif [[ "$token" =~ ^[0-9A-Fa-fxX\*]+:[0-9A-Fa-fxX\*]+$ ]]; then
        lhs="$(normalize_usb_id_component "${token%%:*}")"
        rhs="$(normalize_usb_id_component "${token##*:}")"
        if [[ -n "$lhs" && -n "$rhs" ]]; then
          id="${lhs}:${rhs}"
        fi
      else
        note "Ignoring invalid token: $token"
        continue
      fi
      [[ -n "$id" ]] || continue
      if [[ -z "${selected_hard[$id]:-}" ]]; then
        selected_hard["$id"]=1
        target_ids+="${target_ids:+,}$id"
      fi
    done
    if [[ -z "$target_ids" ]]; then
      note "No valid hard-block selection entered; defaulting to all matched targets."
    fi
  fi

  if [[ "$current_hard_block" == "1" && "$target_ids" == "$current_hard_block_ids" ]]; then
    note "USB hard-block settings unchanged; skipping write."
    return 0
  fi
  if (( DRY_RUN )); then
    note "DRY RUN: would set USB_BT_HARD_BLOCK=\"1\" and USB_BT_HARD_BLOCK_IDS=\"$target_ids\" in $conf"
    USB_BT_HARD_BLOCK_CHANGED=1
    return 0
  fi
  update_usb_bt_hard_block_conf_values "$conf" "1" "$target_ids"
  USB_BT_HARD_BLOCK_CHANGED=1
  if [[ -n "$target_ids" ]]; then
    say "Configured aggressive USB hard-block IDs: $target_ids"
  else
    say "Configured aggressive USB hard-block IDs: <all matched targets>"
  fi
}
print_usb_bt_mitigation_target_summary() {
  # Print a concrete per-device view of which USB devices are currently
  # considered mitigation targets under the active match-policy config.
  local conf="$USB_BT_MATCH_CONF"
  [[ -f "$conf" ]] || {
    note "USB mitigation target summary unavailable (missing config: $conf)."
    return 0
  }

  local match_mode include_ids exclude_ids stop_service hard_block hard_block_ids eee_off eee_ids
  match_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  include_ids="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  exclude_ids="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  stop_service="$(awk -F= '/^USB_BT_STOP_BLUETOOTH_SERVICE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  hard_block="$(awk -F= '/^USB_BT_HARD_BLOCK=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  hard_block_ids="$(awk -F= '/^USB_BT_HARD_BLOCK_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  eee_off="$(awk -F= '/^USB_ETHERNET_EEE_OFF=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  eee_ids="$(awk -F= '/^USB_ETHERNET_EEE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"

  match_mode="${match_mode:-auto}"
  case "$match_mode" in
    auto|include_only) ;;
    *) match_mode="auto" ;;
  esac
  stop_service="$(normalize_usb_bt_boolean_flag "$stop_service")"
  hard_block="$(normalize_usb_bt_boolean_flag "$hard_block")"
  eee_off="$(normalize_usb_ethernet_eee_flag "$eee_off")"

  say
  hdr "USB mitigation effective targets"
  note "MATCH_MODE=$match_mode INCLUDE_IDS=${include_ids:-<empty>} EXCLUDE_IDS=${exclude_ids:-<empty>}"
  note "USB_BT_STOP_BLUETOOTH_SERVICE=${stop_service}"
  note "USB_BT_HARD_BLOCK=${hard_block} USB_BT_HARD_BLOCK_IDS=${hard_block_ids:-<all matched targets>}"
  note "USB_ETHERNET_EEE_OFF=${eee_off} USB_ETHERNET_EEE_IDS=${eee_ids:-<none>}"
  local tag_mitigate_plain tag_host_bound_plain tag_hard_block_plain tag_eee_off_plain
  local tag_mitigate tag_host_bound tag_hard_block tag_eee_off
  tag_mitigate_plain="[MITIGATE]"
  tag_host_bound_plain="[HOST-BOUND]"
  tag_hard_block_plain="[HARD-BLOCK]"
  tag_eee_off_plain="[EEE-OFF]"
  tag_mitigate="$tag_mitigate_plain"
  tag_host_bound="$tag_host_bound_plain"
  tag_hard_block="$tag_hard_block_plain"
  tag_eee_off="$tag_eee_off_plain"
  if (( ENABLE_COLOR )); then
    tag_mitigate="[${C_BOLD}${C_YELLOW}MITIGATE${C_RESET}]"
    tag_host_bound="[${C_BOLD}${C_GREEN}HOST-BOUND${C_RESET}]"
    tag_hard_block="[${C_BOLD}${C_RED}HARD-BLOCK${C_RESET}]"
    tag_eee_off="[${C_BOLD}${C_BLUE}EEE-OFF${C_RESET}]"
  fi
  note "Legend: ${tag_mitigate}=detach target ${tag_host_bound}=not detached ${tag_hard_block}=authorized 0/1 target ${tag_eee_off}=USB ethernet ethtool target"

  local usb_devices_glob dev name vid pid manufacturer product desc tags
  local scanned matched hard_matched eee_matched
  scanned=0
  matched=0
  hard_matched=0
  eee_matched=0
  usb_devices_glob="${VFIO_USB_SYSFS_GLOB:-/sys/bus/usb/devices/*}"
  for dev in $usb_devices_glob; do
    [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
    name="$(basename "$dev")"
    [[ "$name" =~ ^[0-9]+-[0-9]+(\.[0-9]+)*$ ]] || continue
    vid="$(tr -d '\n' <"$dev/idVendor" 2>/dev/null | tr 'A-F' 'a-f')"
    pid="$(tr -d '\n' <"$dev/idProduct" 2>/dev/null | tr 'A-F' 'a-f')"
    [[ -n "$vid" && -n "$pid" ]] || continue
    manufacturer="$(cat "$dev/manufacturer" 2>/dev/null || true)"
    product="$(cat "$dev/product" 2>/dev/null || true)"
    desc="$(trim "$manufacturer $product")"
    scanned=$((scanned + 1))

    if usb_bt_device_matches_policy_from_conf "$dev" "$match_mode" "$include_ids" "$exclude_ids"; then
      tags="${tag_mitigate}"
      matched=$((matched + 1))
      if usb_bt_device_matches_hard_block_scope_from_conf "$dev" "$hard_block" "$hard_block_ids"; then
        tags="${tags}${tag_hard_block}"
        hard_matched=$((hard_matched + 1))
      fi
      if usb_bt_device_matches_eee_scope_from_conf "$dev" "$eee_off" "$eee_ids"; then
        tags="${tags}${tag_eee_off}"
        eee_matched=$((eee_matched + 1))
      fi
    else
      tags="${tag_host_bound}"
    fi
    if [[ -n "$desc" ]]; then
      note "  - ${tags} ${name} ${vid}:${pid} ${desc}"
    else
      note "  - ${tags} ${name} ${vid}:${pid}"
    fi
  done
  if (( scanned == 0 )); then
    note "No USB devices detected for target summary."
    return 0
  fi
  local matched_display hard_matched_display eee_matched_display
  matched_display="$matched"
  hard_matched_display="$hard_matched"
  eee_matched_display="$eee_matched"
  if (( ENABLE_COLOR )); then
    matched_display="${C_BOLD}${C_YELLOW}${matched}${C_RESET}"
    hard_matched_display="${C_BOLD}${C_RED}${hard_matched}${C_RESET}"
    eee_matched_display="${C_BOLD}${C_BLUE}${eee_matched}${C_RESET}"
  fi
  note "Summary totals: scanned=$scanned mitigate=${matched_display} hard-block=${hard_matched_display} eee-off=${eee_matched_display}"
}
configure_usb_bt_policy_mode_interactive() {
  # Prompt for default Bluetooth-only mode vs advanced include_only mode.
  # Sets USB_BT_POLICY_CHANGED=1 when the selected mode changes.
  local conf="$1"
  USB_BT_POLICY_CHANGED=0
  [[ -f "$conf" ]] || return 0

  local current_mode current_include current_exclude target_mode use_advanced default_choice
  current_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_include="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_exclude="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  current_mode="${current_mode:-auto}"
  current_include="${current_include:-}"
  current_exclude="${current_exclude:-}"

  default_choice="N"
  if [[ "$current_mode" == "include_only" ]]; then
    default_choice="Y"
  fi

  say
  hdr "USB mitigation policy mode"
  note "Bluetooth-only (default): detach only Bluetooth-class adapters."
  note "Include-only (advanced): detach only explicitly selected INCLUDE_IDS (can include non-Bluetooth devices such as a dock LAN adapter)."
  if prompt_yn "Use include-only advanced mode?" "$default_choice" "USB mitigation policy"; then
    use_advanced=1
    target_mode="include_only"
  else
    use_advanced=0
    target_mode="auto"
  fi

  if [[ "$target_mode" == "$current_mode" ]]; then
    note "USB mitigation policy unchanged: MATCH_MODE=\"$current_mode\""
    return 0
  fi

  if (( DRY_RUN )); then
    note "DRY RUN: would set MATCH_MODE=\"$target_mode\" in $conf"
    USB_BT_POLICY_CHANGED=1
    return 0
  fi

  if (( use_advanced )); then
    update_usb_bt_match_conf_values "$conf" "$target_mode" "$current_include" "$current_exclude"
  else
    update_usb_bt_match_conf_values "$conf" "$target_mode" "" "$current_exclude"
  fi
  USB_BT_POLICY_CHANGED=1
  say "Configured USB mitigation MATCH_MODE=\"$target_mode\""
  if (( ! use_advanced )); then
    note "Cleared INCLUDE_IDS for Bluetooth-only auto mode."
  fi
}

configure_usb_bt_exclude_ids_interactive() {
  # Build a numbered USB device list and let the user choose VM-eligible IDs.
  # Selection is VID:PID based. Interactive picks mark VM-eligible IDs and the
  # inverse set is written to EXCLUDE_IDS as host-bound IDs.
  USB_BT_EXCLUDE_CHANGED=0
  local conf="$USB_BT_MATCH_CONF"
  if [[ ! -f "$conf" ]]; then
    if ! ensure_usb_bt_match_conf_present "$conf"; then
      note "No USB Bluetooth match config available at $conf; skipping exclusion picker."
      return 0
    fi
  fi
  local match_mode include_ids storage_interlock_required
  match_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  include_ids="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  match_mode="${match_mode:-auto}"
  storage_interlock_required=0
  if [[ "$match_mode" == "include_only" || -n "$include_ids" ]]; then
    storage_interlock_required=1
  fi

  local -a ids=()
  local -a labels=()
  local -a index_colors=()
  local -a is_bt_flags=()
  local -a unique_ids_order=()
  local -a storage_ids_order=()
  local -A all_ids_seen=()
  local -A storage_id_to_label=()
  local usb_devices_glob
  local dev name vid pid manufacturer product hint line
  local is_bt is_eth is_prn is_stg
  local bt_hint_plain bt_hint_colored bt_hint_note
  local eth_hint_plain eth_hint_colored eth_hint_note
  local prn_hint_plain prn_hint_colored prn_hint_note
  local stg_hint_plain stg_hint_colored stg_hint_note
  local mode_host_plain mode_host_colored mode_host_note
  local mode_vm_plain mode_vm_colored mode_vm_note
  bt_hint_plain="[hint: Bluetooth detected]"
  bt_hint_colored="[hint: ${C_BOLD}${C_YELLOW}Bluetooth detected${C_RESET}]"
  bt_hint_note="$bt_hint_plain"
  eth_hint_plain="[keep-bound: Ethernet]"
  eth_hint_colored="[keep-bound: ${C_BOLD}${C_GREEN}Ethernet${C_RESET}]"
  eth_hint_note="$eth_hint_plain"
  prn_hint_plain="[keep-bound: Printer]"
  prn_hint_colored="[keep-bound: ${C_BOLD}${C_BLUE}Printer${C_RESET}]"
  prn_hint_note="$prn_hint_plain"
  stg_hint_plain="[danger: Storage]"
  stg_hint_colored="[danger: ${C_BOLD}${C_RED}Storage${C_RESET}]"
  stg_hint_note="$stg_hint_plain"
  mode_host_plain="[HOST-BOUND]"
  mode_host_colored="[${C_BOLD}${C_GREEN}HOST-BOUND${C_RESET}]"
  mode_host_note="$mode_host_plain"
  mode_vm_plain="[VM-ELIGIBLE]"
  mode_vm_colored="[${C_BOLD}${C_YELLOW}VM-ELIGIBLE${C_RESET}]"
  mode_vm_note="$mode_vm_plain"
  if (( ENABLE_COLOR )); then
    bt_hint_note="$bt_hint_colored"
    eth_hint_note="$eth_hint_colored"
    prn_hint_note="$prn_hint_colored"
    stg_hint_note="$stg_hint_colored"
    mode_host_note="$mode_host_colored"
    mode_vm_note="$mode_vm_colored"
  fi

  usb_devices_glob="${VFIO_USB_SYSFS_GLOB:-/sys/bus/usb/devices/*}"
  for dev in $usb_devices_glob; do
    [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
    name="$(basename "$dev")"
    # Keep only physical USB device paths and skip interface pseudo-paths.
    [[ "$name" =~ ^[0-9]+-[0-9]+(\.[0-9]+)*$ ]] || continue

    vid="$(tr -d '\n' <"$dev/idVendor" 2>/dev/null | tr 'A-F' 'a-f')"
    pid="$(tr -d '\n' <"$dev/idProduct" 2>/dev/null | tr 'A-F' 'a-f')"
    [[ -n "$vid" && -n "$pid" ]] || continue

    manufacturer="$(cat "$dev/manufacturer" 2>/dev/null || true)"
    product="$(cat "$dev/product" 2>/dev/null || true)"
    hint=""
    is_bt=0
    is_eth=0
    is_prn=0
    is_stg=0
    if usb_sysfs_device_is_bluetooth "$dev"; then
      is_bt=1
      if (( ENABLE_COLOR )); then
        hint+=" $bt_hint_colored"
      else
        hint+=" $bt_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_ethernet "$dev"; then
      is_eth=1
      if (( ENABLE_COLOR )); then
        hint+=" $eth_hint_colored"
      else
        hint+=" $eth_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_printer "$dev"; then
      is_prn=1
      if (( ENABLE_COLOR )); then
        hint+=" $prn_hint_colored"
      else
        hint+=" $prn_hint_plain"
      fi
    fi
    if usb_sysfs_device_is_storage "$dev"; then
      is_stg=1
      if (( ENABLE_COLOR )); then
        hint+=" $stg_hint_colored"
      else
        hint+=" $stg_hint_plain"
      fi
      if [[ -z "${storage_id_to_label[$vid:$pid]:-}" ]]; then
        storage_ids_order+=("$vid:$pid")
        storage_id_to_label["$vid:$pid"]="$(trim "$name $vid:$pid $manufacturer $product")"
      fi
    fi

    line="$name $vid:$pid $manufacturer $product"
    line="$(trim "$line")"
    line+="$hint"
    ids+=("$vid:$pid")
    labels+=("$line")
    is_bt_flags+=("$is_bt")
    if [[ -z "${all_ids_seen[$vid:$pid]:-}" ]]; then
      unique_ids_order+=("$vid:$pid")
      all_ids_seen["$vid:$pid"]=1
    fi
    if (( is_stg )); then
      index_colors+=("${C_BOLD}${C_RED}")
    elif (( is_bt )); then
      index_colors+=("${C_BOLD}${C_YELLOW}")
    elif (( is_eth )); then
      index_colors+=("${C_BOLD}${C_GREEN}")
    elif (( is_prn )); then
      index_colors+=("${C_BOLD}${C_BLUE}")
    else
      index_colors+=("")
    fi
  done

  if (( ${#ids[@]} == 0 )); then
    note "No USB devices discovered for exclusion selection; leaving EXCLUDE_IDS unchanged."
    return 0
  fi
  local show_full_list filtered_view_active bt_entry_count can_toggle_view
  local -a display_indexes=()
  show_full_list=1
  filtered_view_active=0
  can_toggle_view=0
  bt_entry_count=0
  for i in "${!ids[@]}"; do
    if (( ${is_bt_flags[$i]:-0} )); then
      bt_entry_count=$((bt_entry_count + 1))
    fi
  done
  if (( ! storage_interlock_required && bt_entry_count > 0 && bt_entry_count < ${#ids[@]} )); then
    can_toggle_view=1
  fi
  if (( can_toggle_view )); then
    note "Current policy is Bluetooth-only; you can show a Bluetooth-focused list or the full USB list."
    if prompt_yn "Show full USB list (all devices) instead of Bluetooth-focused view?" N "USB picker view"; then
      show_full_list=1
    else
      show_full_list=0
      filtered_view_active=1
    fi
  fi
  for i in "${!ids[@]}"; do
    if (( show_full_list )) || (( ${is_bt_flags[$i]:-0} )); then
      display_indexes+=("$i")
    fi
  done
  if (( ${#display_indexes[@]} == 0 )); then
    show_full_list=1
    filtered_view_active=0
    for i in "${!ids[@]}"; do
      display_indexes+=("$i")
    done
  fi

  say
  hdr "USB Bluetooth mitigation exclusions"
  note "Pick USB devices that should be VM-eligible (this helper may auto-detach them for passthrough)."
  note "Selecting a number means: allow this device ID to be detached for VM passthrough."
  note "If you want a Bluetooth adapter available for VM passthrough, select it here."
  note "If you want a Bluetooth adapter to remain usable on the host, do NOT select it."
  note "Unselected IDs are kept host-bound and saved into EXCLUDE_IDS."
  note "Entries marked '$bt_hint_note' are likely Bluetooth adapters."
  note "Entries marked '$eth_hint_note' or '$prn_hint_note' are usually host devices you should keep host-bound."
  note "Entries marked '$stg_hint_note' are high-risk to detach (can disconnect active host storage)."
  note "When color output is enabled, entry numbers use the strongest matching hint color (Storage > Bluetooth > Ethernet > Printer)."
  note "Multi-select example: type '4 5 6' (or '4,5,6') to mark multiple devices VM-eligible."
  note "Your VM-eligible picks are converted into EXCLUDE_IDS (unselected host-bound IDs) in: $USB_BT_MATCH_CONF"
  if (( can_toggle_view )); then
    note "Type 'full' to show all USB devices, or 'focus' to show Bluetooth-focused entries."
  fi
  local i idx_text display_no render_device_list
  local -A display_num_by_idx=()
  render_device_list=1

  local in out answer interactive_in_fd
  interactive_in_fd=""
  in="${VFIO_INTERACTIVE_IN:-/dev/stdin}"
  out="${VFIO_INTERACTIVE_OUT:-/dev/stderr}"
  if [[ -z "${VFIO_INTERACTIVE_IN:-}" && -z "${VFIO_INTERACTIVE_OUT:-}" && -r /dev/tty && -w /dev/tty ]]; then
    in="/dev/tty"
    out="/dev/tty"
  fi
  if [[ -n "${VFIO_INTERACTIVE_IN:-}" ]]; then
    exec {interactive_in_fd}<"$in"
  fi

  local exclude_csv=""
  local vm_csv=""
  while true; do
    if (( render_device_list )); then
      if (( filtered_view_active )); then
        note "Bluetooth-focused view is active (showing likely detach targets)."
      fi
      display_num_by_idx=()
      display_no=0
      for i in "${display_indexes[@]}"; do
        display_no=$((display_no + 1))
        display_num_by_idx["$i"]="$display_no"
        idx_text="[$display_no]"
        if (( ENABLE_COLOR )) && [[ -n "${index_colors[$i]:-}" ]]; then
          idx_text="${index_colors[$i]}[$display_no]${C_RESET}"
        fi
        say "  ${idx_text} ${labels[$i]}"
      done
      render_device_list=0
    fi
    if (( can_toggle_view )); then
      printf '%s' "Enter numbers to make VM-eligible (comma/space separated, ENTER for none, or type 'full'/'focus'): " >"$out"
    else
      printf '%s' "Enter numbers to make VM-eligible (comma/space separated, ENTER for none): " >"$out"
    fi
    if [[ -n "$interactive_in_fd" ]]; then
      read -r -u "$interactive_in_fd" answer || answer=""
    else
      read -r answer <"$in" || answer=""
    fi
    answer="$(trim "$answer")"
    if (( can_toggle_view )); then
      local answer_lc
      answer_lc="${answer,,}"
      case "$answer_lc" in
        full)
          if (( show_full_list )); then
            note "Full USB list view is already active."
          else
            show_full_list=1
            filtered_view_active=0
            display_indexes=()
            for i in "${!ids[@]}"; do
              display_indexes+=("$i")
            done
            note "Switched to full USB list view."
          fi
          render_device_list=1
          continue
          ;;
        focus|focused|bt|bluetooth)
          if (( ! show_full_list )); then
            note "Bluetooth-focused view is already active."
          else
            show_full_list=0
            filtered_view_active=1
            display_indexes=()
            for i in "${!ids[@]}"; do
              if (( ${is_bt_flags[$i]:-0} )); then
                display_indexes+=("$i")
              fi
            done
            if (( ${#display_indexes[@]} == 0 )); then
              show_full_list=1
              filtered_view_active=0
              for i in "${!ids[@]}"; do
                display_indexes+=("$i")
              done
              note "No Bluetooth-marked entries were found; staying on full USB list view."
            else
              note "Switched to Bluetooth-focused view."
            fi
          fi
          render_device_list=1
          continue
          ;;
      esac
    fi

    exclude_csv=""
    vm_csv=""
    local -A selected_vm_ids=()
    local -a selected_vm_indexes=()
    if [[ -n "$answer" ]]; then
      answer="${answer//,/ }"
      local token disp_idx idx id
      for token in $answer; do
        if [[ ! "$token" =~ ^[0-9]+$ ]]; then
          note "Ignoring invalid token: $token"
          continue
        fi
        if (( token < 1 || token > ${#display_indexes[@]} )); then
          note "Ignoring out-of-range selection: $token"
          continue
        fi
        disp_idx=$((token-1))
        idx="${display_indexes[$disp_idx]}"
        id="${ids[$idx]}"
        if [[ -z "${selected_vm_ids[$id]:-}" ]]; then
          vm_csv+="${vm_csv:+,}$id"
          selected_vm_ids[$id]=1
          selected_vm_indexes+=("$idx")
        fi
      done
    fi

    local uid
    for uid in "${unique_ids_order[@]}"; do
      if [[ -z "${selected_vm_ids[$uid]:-}" ]]; then
        exclude_csv+="${exclude_csv:+,}$uid"
      fi
    done

    local -a selected_storage_ids=()
    local sid
    for sid in "${storage_ids_order[@]}"; do
      if [[ -n "${selected_vm_ids[$sid]:-}" ]]; then
        selected_storage_ids+=("$sid")
      fi
    done

    if (( ${#selected_storage_ids[@]} > 0 )); then
      if (( storage_interlock_required )); then
        say
        if (( ENABLE_COLOR )); then
          say "${C_BOLD}${C_RED}DANGER:${C_RESET} Some storage devices are selected as VM-eligible detach targets."
        else
          say "DANGER: Some storage devices are selected as VM-eligible detach targets."
        fi
        note "Detaching storage-class USB devices can disconnect active host disks and cause data loss."
        note "Storage entries currently selected for VM eligibility:"
        for sid in "${selected_storage_ids[@]}"; do
          note "  - ${storage_id_to_label[$sid]}"
        done

        if prompt_yn "Re-enter numbers now and keep these storage devices host-bound?" Y "Storage safety"; then
          continue
        fi
        if ! confirm_phrase "Proceeding with storage devices marked VM-eligible is risky." "I ACCEPT STORAGE RISK"; then
          note "Risk confirmation not accepted; please choose VM-eligible devices again."
          continue
        fi
      else
        note "Info: some storage devices are selected as VM-eligible."
        note "Current policy is Bluetooth-only (MATCH_MODE=auto with empty INCLUDE_IDS), so non-Bluetooth storage devices are not detach targets."
      fi
    fi

    say
    note "Selection review:"
    if [[ -n "$vm_csv" ]]; then
      note "Selected VM-eligible IDs (detach targets): $vm_csv"
      local selected_idx selected_idx_text selected_idx_num
      note "Selected VM-eligible entries:"
      for selected_idx in "${selected_vm_indexes[@]}"; do
        selected_idx_num="${display_num_by_idx[$selected_idx]:-$((selected_idx+1))}"
        selected_idx_text="[$selected_idx_num]"
        if (( ENABLE_COLOR )) && [[ -n "${index_colors[$selected_idx]:-}" ]]; then
          selected_idx_text="${index_colors[$selected_idx]}[$selected_idx_num]${C_RESET}"
        fi
        note "  - ${selected_idx_text} ${labels[$selected_idx]}"
      done
    else
      note "No entries selected as VM-eligible."
    fi
    if [[ -n "$exclude_csv" ]]; then
      note "Derived EXCLUDE_IDS (kept host-bound): $exclude_csv"
    else
      note "Derived EXCLUDE_IDS (kept host-bound): <empty>"
    fi
    note "Mode summary per listed device:"
    note "  $mode_vm_note = selected here (eligible for automatic detach for VM passthrough)"
    note "  $mode_host_note = not selected (stays on host via EXCLUDE_IDS)"
    if (( ! storage_interlock_required )); then
      note "  Note: in current Bluetooth-only policy, non-Bluetooth devices are not detach targets."
    fi
    local entry_id mode_tag
    for i in "${display_indexes[@]}"; do
      idx_text="[${display_num_by_idx[$i]}]"
      if (( ENABLE_COLOR )) && [[ -n "${index_colors[$i]:-}" ]]; then
        idx_text="${index_colors[$i]}[${display_num_by_idx[$i]}]${C_RESET}"
      fi
      entry_id="${ids[$i]}"
      if [[ -n "${selected_vm_ids[$entry_id]:-}" ]]; then
        mode_tag="$mode_vm_note"
      else
        mode_tag="$mode_host_note"
      fi
      note "  - ${idx_text} ${mode_tag} ${labels[$i]}"
    done

    if prompt_yn "Apply this VM-eligible selection now?" Y "USB exclusion review"; then
      break
    fi
    note "Selection not applied; re-enter numbers to adjust your choices."
    if (( can_toggle_view )); then
      note "Quick view switch: type 'full' for all USB devices or 'focus' for Bluetooth-focused entries."
    fi
  done
  if [[ -n "$interactive_in_fd" ]]; then
    exec {interactive_in_fd}<&-
  fi
  if (( DRY_RUN )); then
    return 0
  fi
  if [[ ! -f "$conf" ]]; then
    if ! ensure_usb_bt_match_conf_present "$conf"; then
      die "Unable to apply EXCLUDE_IDS; match config is missing and could not be recreated: $conf"
    fi
  fi
  local existing_include existing_exclude desired_include
  existing_include="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  existing_exclude="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$conf" 2>/dev/null || true)"
  existing_include="${existing_include:-}"
  existing_exclude="${existing_exclude:-}"
  desired_include="$existing_include"
  if [[ "$match_mode" == "include_only" ]]; then
    desired_include="$vm_csv"
  fi

  if [[ "$existing_exclude" == "$exclude_csv" && "$existing_include" == "$desired_include" ]]; then
    note "INCLUDE_IDS/EXCLUDE_IDS unchanged; skipping write."
    USB_BT_EXCLUDE_CHANGED=0
    if [[ -n "$vm_csv" ]]; then
      say "Configured USB Bluetooth VM-eligible IDs: $vm_csv"
    else
      say "Configured USB Bluetooth VM-eligible IDs: <empty>"
    fi
    if [[ "$match_mode" == "include_only" ]]; then
      if [[ -n "$desired_include" ]]; then
        say "Configured USB Bluetooth INCLUDE_IDS (include-only detach targets): $desired_include"
      else
        say "Configured USB Bluetooth INCLUDE_IDS (include-only detach targets): <empty>"
      fi
    fi
    if [[ -n "$exclude_csv" ]]; then
      say "Configured USB Bluetooth EXCLUDE_IDS (kept host-bound): $exclude_csv"
    else
      say "Configured USB Bluetooth EXCLUDE_IDS (kept host-bound): <empty>"
    fi
    return 0
  fi
  update_usb_bt_match_conf_values "$conf" "$match_mode" "$desired_include" "$exclude_csv"
  USB_BT_EXCLUDE_CHANGED=1

  if [[ -n "$vm_csv" ]]; then
    say "Configured USB Bluetooth VM-eligible IDs: $vm_csv"
  else
    say "Configured USB Bluetooth VM-eligible IDs: <empty>"
  fi
  if [[ "$match_mode" == "include_only" ]]; then
    if [[ -n "$desired_include" ]]; then
      say "Configured USB Bluetooth INCLUDE_IDS (include-only detach targets): $desired_include"
    else
      say "Configured USB Bluetooth INCLUDE_IDS (include-only detach targets): <empty>"
    fi
  fi
  if [[ -n "$exclude_csv" ]]; then
    say "Configured USB Bluetooth EXCLUDE_IDS (kept host-bound): $exclude_csv"
  else
    say "Configured USB Bluetooth EXCLUDE_IDS (kept host-bound): <empty>"
  fi
}

install_usb_bluetooth_disable() {
  local had_unit had_match_conf should_start_now usb_bt_artifacts_changed
  local existing_match_mode existing_include_ids existing_exclude_ids existing_eee_off existing_eee_ids
  local existing_stop_bt_service existing_hard_block existing_hard_block_ids exclusions_preconfigured
  USB_BT_SERVICE_GUARD_CHANGED=0
  USB_BT_HARD_BLOCK_CHANGED=0
  USB_BT_POLICY_CHANGED=0
  had_unit=0
  had_match_conf=0
  should_start_now=1
  usb_bt_artifacts_changed=0
  exclusions_preconfigured=0
  if [[ -f "$USB_BT_SYSTEMD_UNIT" ]]; then
    had_unit=1
  fi
  if [[ -f "$USB_BT_MATCH_CONF" ]]; then
    had_match_conf=1
    backup_file "$USB_BT_MATCH_CONF"
  fi
  ensure_usb_bt_match_conf_present "$USB_BT_MATCH_CONF" || die "Unable to create USB Bluetooth match policy config: $USB_BT_MATCH_CONF"
  if [[ "$had_match_conf" -eq 0 ]]; then
    usb_bt_artifacts_changed=1
  fi
  ensure_usb_bt_match_conf_keys_present "$USB_BT_MATCH_CONF" || die "Unable to update USB Bluetooth match policy defaults: $USB_BT_MATCH_CONF"
  existing_match_mode="$(awk -F= '/^MATCH_MODE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_include_ids="$(awk -F= '/^INCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_exclude_ids="$(awk -F= '/^EXCLUDE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_stop_bt_service="$(awk -F= '/^USB_BT_STOP_BLUETOOTH_SERVICE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_hard_block="$(awk -F= '/^USB_BT_HARD_BLOCK=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_hard_block_ids="$(awk -F= '/^USB_BT_HARD_BLOCK_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_eee_off="$(awk -F= '/^USB_ETHERNET_EEE_OFF=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_eee_ids="$(awk -F= '/^USB_ETHERNET_EEE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  existing_match_mode="${existing_match_mode:-auto}"
  existing_stop_bt_service="$(normalize_usb_bt_boolean_flag "$existing_stop_bt_service")"
  existing_hard_block="$(normalize_usb_bt_boolean_flag "$existing_hard_block")"
  existing_eee_off="$(normalize_usb_ethernet_eee_flag "$existing_eee_off")"
  if [[ "$existing_match_mode" != "auto" || -n "$existing_include_ids" || -n "$existing_exclude_ids" || "$existing_eee_off" == "1" || -n "$existing_eee_ids" || "$existing_stop_bt_service" != "1" || "$existing_hard_block" == "1" || -n "$existing_hard_block_ids" ]]; then
    exclusions_preconfigured=1
  fi

  if write_file_atomic_if_changed "$USB_BT_SCRIPT" 0755 "root:root" 1 <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

MODE="disable"  # disable | enable
if [[ "${1:-}" == "--enable" ]]; then
  MODE="enable"
elif [[ "${1:-}" == "--disable" || -z "${1:-}" ]]; then
  MODE="disable"
else
  echo "Usage: $(basename "$0") [--disable|--enable]" >&2
  exit 2
fi
MATCH_CONF="/etc/vfio-usb-bluetooth-match.conf"
MATCH_MODE="auto"
INCLUDE_IDS=""
EXCLUDE_IDS=""
USB_BT_STOP_BLUETOOTH_SERVICE="1"
USB_BT_HARD_BLOCK="0"
USB_BT_HARD_BLOCK_IDS=""
USB_ETHERNET_EEE_OFF="0"
USB_ETHERNET_EEE_IDS=""
STATE_FILE="/var/lib/vfio-usb-bt-mitigation.state"
if [[ -r "$MATCH_CONF" ]]; then
  # shellcheck disable=SC1091
  source "$MATCH_CONF"
fi

normalize_id_component() {
  local v="${1,,}"
  v="${v#0x}"
  printf '%s' "$v"
}
normalize_bool_flag() {
  local raw="${1:-0}"
  raw="${raw,,}"
  case "$raw" in
    1|y|yes|true|on) printf '1\n' ;;
    *) printf '0\n' ;;
  esac
}

MATCH_MODE="${MATCH_MODE,,}"
case "$MATCH_MODE" in
  auto|include_only) ;;
  *) MATCH_MODE="auto" ;;
esac
USB_ETHERNET_EEE_OFF="$(normalize_bool_flag "${USB_ETHERNET_EEE_OFF:-0}")"
USB_BT_STOP_BLUETOOTH_SERVICE="$(normalize_bool_flag "${USB_BT_STOP_BLUETOOTH_SERVICE:-1}")"
USB_BT_HARD_BLOCK="$(normalize_bool_flag "${USB_BT_HARD_BLOCK:-0}")"

match_id_pattern() {
  local pattern="${1,,}" vid="$2" pid="$3"
  local pvid ppid

  [[ "$pattern" == *:* ]] || return 1
  pvid="$(normalize_id_component "${pattern%%:*}")"
  ppid="$(normalize_id_component "${pattern##*:}")"

  [[ -n "$pvid" && -n "$ppid" ]] || return 1
  [[ "$pvid" == "*" || "$pvid" == "$vid" ]] || return 1
  [[ "$ppid" == "*" || "$ppid" == "$pid" ]] || return 1
  return 0
}

id_in_csv() {
  local csv="$1" vid="$2" pid="$3"
  local item
  [[ -n "$csv" ]] || return 1

  local IFS=','
  for item in $csv; do
    item="${item//[[:space:]]/}"
    [[ -n "$item" ]] || continue
    if match_id_pattern "$item" "$vid" "$pid"; then
      return 0
    fi
  done
  return 1
}
# - interface driver bound to btusb (covers vendor-specific interfaces).
usb_device_is_bluetooth() {
  local dev="$1"
  local intf cls sub drv text_hint

  shopt -s nullglob
  for intf in "$dev":*; do
    # Driver-based detection (best-effort)
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      if [[ "$drv" == "btusb" ]]; then
        return 0
      fi
    fi

    # Class-based detection
    if [[ -f "$intf/bInterfaceClass" && -f "$intf/bInterfaceSubClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      sub="$(tr -d '\n' <"$intf/bInterfaceSubClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "e0" && "$sub" == "01" ]]; then
        return 0
      fi
    fi
  done
  shopt -u nullglob
  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(bluetooth)' <<<"$text_hint"; then
    return 0
  fi

  return 1
}
usb_device_is_ethernet() {
  # USB Ethernet detection by interface driver/class with a text fallback.
  local dev="$1" intf cls drv text_hint
  shopt -s nullglob
  for intf in "$dev":*; do
    if [[ -L "$intf/driver" ]]; then
      drv="$(basename "$(readlink -f "$intf/driver" 2>/dev/null || true)")"
      case "$drv" in
        r8152|asix|ax88179_178a|cdc_ether|rndis_host|cdc_ncm|cdc_mbim|lan78xx|smsc95xx|qmi_wwan|aqc111)
          shopt -u nullglob
          return 0
          ;;
      esac
    fi
    if [[ -f "$intf/bInterfaceClass" ]]; then
      cls="$(tr -d '\n' <"$intf/bInterfaceClass" | tr 'A-F' 'a-f')"
      if [[ "$cls" == "02" || "$cls" == "0a" ]]; then
        shopt -u nullglob
        return 0
      fi
    fi
  done
  shopt -u nullglob

  text_hint="$(printf '%s %s' "$(cat "$dev/manufacturer" 2>/dev/null || true)" "$(cat "$dev/product" 2>/dev/null || true)" | tr '[:upper:]' '[:lower:]')"
  if grep -Eq '(ethernet|usb ?lan|network adapter|realtek.*lan|gigabit.*lan)' <<<"$text_hint"; then
    return 0
  fi
  return 1
}

device_matches_policy() {
  local dev="$1" vid pid
  vid="$(normalize_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1

  if [[ "$MATCH_MODE" == "include_only" ]]; then
    id_in_csv "$INCLUDE_IDS" "$vid" "$pid" || return 1
  else
    usb_device_is_bluetooth "$dev" || return 1
    if [[ -n "$INCLUDE_IDS" ]] && ! id_in_csv "$INCLUDE_IDS" "$vid" "$pid"; then
      return 1
    fi
  fi

  if id_in_csv "$EXCLUDE_IDS" "$vid" "$pid"; then
    return 1
  fi

  return 0
}
device_matches_usb_bt_hard_block_policy() {
  local dev="$1" vid pid
  (( USB_BT_HARD_BLOCK == 1 )) || return 1
  if [[ -z "$USB_BT_HARD_BLOCK_IDS" ]]; then
    return 0
  fi

  vid="$(normalize_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1
  id_in_csv "$USB_BT_HARD_BLOCK_IDS" "$vid" "$pid"
}
set_usb_device_authorized_state() {
  local dev="$1" value="$2"
  [[ "$dev" == /sys/bus/usb/devices/* ]] || return 1
  [[ -w "$dev/authorized" ]] || return 1
  case "$value" in
    0|1) ;;
    *) return 1 ;;
  esac
  echo "$value" >"$dev/authorized" 2>/dev/null || return 1
  return 0
}
bluetooth_service_transition_done=0
maybe_toggle_bluetooth_service() {
  local action="$1"
  (( USB_BT_STOP_BLUETOOTH_SERVICE == 1 )) || return 0
  (( bluetooth_service_transition_done == 0 )) || return 0
  command -v systemctl >/dev/null 2>&1 || return 0
  case "$action" in
    stop)
      systemctl stop bluetooth.service >/dev/null 2>&1 || true
      ;;
    start)
      systemctl start bluetooth.service >/dev/null 2>&1 || true
      ;;
    *)
      return 1
      ;;
  esac
  bluetooth_service_transition_done=1
  return 0
}
device_matches_usb_ethernet_eee_policy() {
  local dev="$1" vid pid
  (( USB_ETHERNET_EEE_OFF == 1 )) || return 1
  usb_device_is_ethernet "$dev" || return 1
  vid="$(normalize_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '')")"
  pid="$(normalize_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '')")"
  [[ -n "$vid" && -n "$pid" ]] || return 1

  if [[ -n "$USB_ETHERNET_EEE_IDS" ]] && ! id_in_csv "$USB_ETHERNET_EEE_IDS" "$vid" "$pid"; then
    return 1
  fi
  return 0
}
apply_usb_ethernet_eee_off_for_device() {
  local dev="$1" dev_real netdir ifname net_dev_real changed
  local vid pid
  changed=0
  command -v ethtool >/dev/null 2>&1 || {
    echo "vfio-usb-bluetooth: ethtool not found; skipping USB Ethernet EEE-off tuning"
    return 1
  }

  dev_real="$(readlink -f "$dev" 2>/dev/null || true)"
  vid="$(normalize_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '?')")"
  pid="$(normalize_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '?')")"

  shopt -s nullglob
  for netdir in "$dev"/net/*; do
    [[ -d "$netdir" ]] || continue
    ifname="$(basename "$netdir")"
    [[ -n "$ifname" ]] || continue
    net_dev_real="$(readlink -f "/sys/class/net/$ifname/device" 2>/dev/null || true)"
    case "$net_dev_real" in
      "$dev_real"|"$dev_real":*|"$dev_real"/*) ;;
      *) continue ;;
    esac

    if ethtool --set-eee "$ifname" eee off >/dev/null 2>&1; then
      echo "vfio-usb-bluetooth: applied usb-ethernet eee=off iface=${ifname} $(basename "$dev") (${vid}:${pid})"
      changed=1
    else
      if ethtool --show-eee "$ifname" >/dev/null 2>&1; then
        echo "vfio-usb-bluetooth: EEE-off not applied for iface=${ifname} (unsupported or driver rejected request)"
      else
        echo "vfio-usb-bluetooth: unable to query/apply EEE for iface=${ifname} (leaving unchanged)"
      fi
    fi
  done
  shopt -u nullglob
  (( changed == 1 ))
}
intf_disable() {
  local intf="$1"
  local name drv drv_path
  name="$(basename "$intf")"
  # Safety: this helper must only operate on USB interface paths.
  [[ "$intf" == /sys/bus/usb/devices/*:* ]] || return 0
  # Prevent automatic rebind while this mitigation is active.
  if [[ -w "$intf/driver_override" ]]; then
    echo "none" >"$intf/driver_override" 2>/dev/null || true
  fi
  # If currently bound, unbind from the current USB interface driver only.
  if [[ -L "$intf/driver" ]]; then
    drv_path="$(readlink -f "$intf/driver" 2>/dev/null || true)"
    [[ "$drv_path" == /sys/bus/usb/drivers/* ]] || return 0
    drv="$(basename "$drv_path")"
    if [[ -n "$drv" && -w "/sys/bus/usb/drivers/$drv/unbind" ]]; then
      echo "$name" >"/sys/bus/usb/drivers/$drv/unbind" 2>/dev/null || true
    fi
  fi
}

intf_enable() {
  local intf="$1"
  local name
  name="$(basename "$intf")"
  # Safety: this helper must only operate on USB interface paths.
  [[ "$intf" == /sys/bus/usb/devices/*:* ]] || return 0

  # Allow drivers to bind again.
  if [[ -w "$intf/driver_override" ]]; then
    echo "" >"$intf/driver_override" 2>/dev/null || true
  fi

  # Best-effort re-probe through generic USB driver matching.
  if [[ -w /sys/bus/usb/drivers_probe ]]; then
    echo "$name" >/sys/bus/usb/drivers_probe 2>/dev/null || true
  elif [[ -w /sys/bus/usb/drivers/btusb/bind ]]; then
    # Fallback for systems where drivers_probe is unavailable.
    echo "$name" >/sys/bus/usb/drivers/btusb/bind 2>/dev/null || true
  fi
}

changed=0
policy_target_found=0
target_count=0
target_devices=""
for dev in /sys/bus/usb/devices/*; do
  [[ -f "$dev/idVendor" && -f "$dev/idProduct" ]] || continue
  if device_matches_policy "$dev"; then
    policy_target_found=1
    if [[ "$MODE" == "disable" ]]; then
      maybe_toggle_bluetooth_service stop
    fi
    is_bt_target=0
    hard_block_state="off"
    target_scope="include-only"
    vid="$(normalize_id_component "$(cat "$dev/idVendor" 2>/dev/null || echo '?')")"
    pid="$(normalize_id_component "$(cat "$dev/idProduct" 2>/dev/null || echo '?')")"
    if usb_device_is_bluetooth "$dev"; then
      is_bt_target=1
      target_scope="bluetooth"
    fi
    if (( is_bt_target )) || [[ "$MATCH_MODE" == "include_only" ]]; then
      if device_matches_usb_bt_hard_block_policy "$dev"; then
        if [[ "$MODE" == "disable" ]]; then
          if set_usb_device_authorized_state "$dev" 0; then
            hard_block_state="authorized=0"
            changed=1
          else
            hard_block_state="authorized=0-failed"
          fi
        else
          if set_usb_device_authorized_state "$dev" 1; then
            hard_block_state="authorized=1"
            changed=1
          else
            hard_block_state="authorized=1-failed"
          fi
        fi
      fi
      shopt -s nullglob
      for intf in "$dev":*; do
        [[ -d "$intf" ]] || continue
        if [[ "$MODE" == "disable" ]]; then
          intf_disable "$intf"
        else
          intf_enable "$intf"
        fi
      done
      shopt -u nullglob
      echo "vfio-usb-bluetooth: ${MODE}d $(basename "$dev") (${vid}:${pid}) mode=${MATCH_MODE} scope=${target_scope} hard_block=${hard_block_state}"
      target_count=$((target_count + 1))
      target_devices+="${target_devices:+,}$(basename "$dev"):${vid}:${pid}"
      changed=1
    fi
  fi
  if [[ "$MODE" == "disable" ]] && device_matches_usb_ethernet_eee_policy "$dev"; then
    if apply_usb_ethernet_eee_off_for_device "$dev"; then
      changed=1
    fi
  fi
done

if [[ "$MODE" == "enable" ]] && (( policy_target_found == 1 )); then
  maybe_toggle_bluetooth_service start
fi

if (( ! changed )); then
  echo "vfio-usb-bluetooth: no matching USB mitigation targets found"
fi
# Write state file for run tracking
if [[ -n "$target_devices" ]]; then
  mkdir -p "$(dirname "$STATE_FILE")" 2>/dev/null || true
  printf "timestamp=%s mode=%s targets=%s
" "$(date -Is)" "$MODE" "$target_devices" >>"$STATE_FILE" 2>/dev/null || true
fi
EOF
  then
    usb_bt_artifacts_changed=1
  fi

  if write_file_atomic_if_changed "$USB_BT_SYSTEMD_UNIT" 0644 "root:root" 1 <<EOF
[Unit]
Description=Detach USB Bluetooth adapters from btusb (VFIO helper)
After=systemd-udevd.service
Wants=systemd-udevd.service
StartLimitIntervalSec=0

[Service]
Type=oneshot
ExecStart=$USB_BT_SCRIPT --disable

[Install]
WantedBy=multi-user.target
EOF
  then
    usb_bt_artifacts_changed=1
  fi

  if write_file_atomic_if_changed "$USB_BT_UDEV_RULE" 0644 "root:root" 1 <<'EOF'
# Generated by vfio.sh
# Trigger the disable service when a USB Bluetooth interface appears.
# - Matches the standard Bluetooth USB interface class/subclass (e0/01)
# - Also matches interfaces that bind to btusb (covers vendor-specific descriptors)

ACTION=="add", SUBSYSTEM=="usb", ENV{DEVTYPE}=="usb_interface", ATTR{bInterfaceClass}=="e0", ATTR{bInterfaceSubClass}=="01", TAG+="systemd", ENV{SYSTEMD_WANTS}+="vfio-disable-usb-bluetooth.service"
ACTION=="add", SUBSYSTEM=="usb", ENV{DEVTYPE}=="usb_interface", DRIVERS=="btusb", TAG+="systemd", ENV{SYSTEMD_WANTS}+="vfio-disable-usb-bluetooth.service"
ACTION=="bind", SUBSYSTEM=="usb", ENV{DEVTYPE}=="usb_interface", DRIVERS=="btusb", TAG+="systemd", ENV{SYSTEMD_WANTS}+="vfio-disable-usb-bluetooth.service"
EOF
  then
    usb_bt_artifacts_changed=1
  fi

  if (( exclusions_preconfigured )) && [[ "$had_unit" -eq 1 && "$had_match_conf" -eq 1 ]]; then
    say
    note "Detected existing USB Bluetooth mitigation configuration in: $USB_BT_MATCH_CONF"
    if prompt_yn "Existing USB Bluetooth exclusions/policy detected. Reconfigure now?" N "USB Bluetooth exclusions"; then
      configure_usb_bt_policy_mode_interactive "$USB_BT_MATCH_CONF"
      configure_usb_bt_exclude_ids_interactive
      configure_usb_bt_service_guard_interactive
      configure_usb_bt_ethernet_eee_interactive
      configure_usb_bt_hard_block_interactive
      if [[ "${USB_BT_EXCLUDE_CHANGED:-0}" == "0" && "${USB_BT_POLICY_CHANGED:-0}" == "0" && "${USB_BT_SERVICE_GUARD_CHANGED:-0}" == "0" && "${USB_BT_ETH_EEE_CHANGED:-0}" == "0" && "${USB_BT_HARD_BLOCK_CHANGED:-0}" == "0" && "$had_unit" -eq 1 && "$usb_bt_artifacts_changed" -eq 0 ]]; then
        should_start_now=0
      fi
    else
      note "Keeping existing USB Bluetooth exclusions/policy without reconfiguration."
      USB_BT_EXCLUDE_CHANGED=0
      USB_BT_POLICY_CHANGED=0
      USB_BT_SERVICE_GUARD_CHANGED=0
      USB_BT_ETH_EEE_CHANGED=0
      USB_BT_HARD_BLOCK_CHANGED=0
      if [[ "$had_unit" -eq 1 && "$usb_bt_artifacts_changed" -eq 0 ]]; then
        should_start_now=0
      fi
    fi
  elif prompt_yn "Configure mitigation policy mode and review USB devices now?" Y "USB Bluetooth exclusions"; then
    configure_usb_bt_policy_mode_interactive "$USB_BT_MATCH_CONF"
    configure_usb_bt_exclude_ids_interactive
    configure_usb_bt_service_guard_interactive
    configure_usb_bt_ethernet_eee_interactive
    configure_usb_bt_hard_block_interactive
    if [[ "${USB_BT_EXCLUDE_CHANGED:-0}" == "0" && "${USB_BT_POLICY_CHANGED:-0}" == "0" && "${USB_BT_SERVICE_GUARD_CHANGED:-0}" == "0" && "${USB_BT_ETH_EEE_CHANGED:-0}" == "0" && "${USB_BT_HARD_BLOCK_CHANGED:-0}" == "0" && "$had_unit" -eq 1 && "$usb_bt_artifacts_changed" -eq 0 ]]; then
      should_start_now=0
    fi
  else
    note "Keeping EXCLUDE_IDS empty (no explicit USB exclusions)."
    USB_BT_POLICY_CHANGED=0
    USB_BT_SERVICE_GUARD_CHANGED=0
    USB_BT_ETH_EEE_CHANGED=0
    USB_BT_HARD_BLOCK_CHANGED=0
    if [[ "$had_unit" -eq 1 && "$usb_bt_artifacts_changed" -eq 0 ]]; then
      should_start_now=0
    fi
  fi

  if have_cmd udevadm; then
    run udevadm control --reload-rules
    # Trigger is best-effort; it can be noisy on some systems, so ignore failures.
    run udevadm trigger --subsystem-match=usb 2>/dev/null || true
  fi

  run systemctl daemon-reload
  say
  if (( should_start_now )); then
    run systemctl enable --now vfio-disable-usb-bluetooth.service
  else
    run systemctl enable vfio-disable-usb-bluetooth.service
    note "USB Bluetooth settings unchanged; skipping immediate service run."
  fi
  say

  say "Installed USB Bluetooth disable helper: $USB_BT_SCRIPT"
  say "Installed systemd unit: $USB_BT_SYSTEMD_UNIT"
  say "Installed udev rule: $USB_BT_UDEV_RULE"
  say "Installed match policy config: $USB_BT_MATCH_CONF"
  local final_stop_bt_service final_hard_block final_hard_block_ids final_eee_off final_eee_ids
  final_stop_bt_service="$(awk -F= '/^USB_BT_STOP_BLUETOOTH_SERVICE=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  final_hard_block="$(awk -F= '/^USB_BT_HARD_BLOCK=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  final_hard_block_ids="$(awk -F= '/^USB_BT_HARD_BLOCK_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  final_eee_off="$(awk -F= '/^USB_ETHERNET_EEE_OFF=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  final_eee_ids="$(awk -F= '/^USB_ETHERNET_EEE_IDS=/{v=$2; gsub(/"/,"",v); gsub(/[[:space:]]/,"",v); print tolower(v); exit}' "$USB_BT_MATCH_CONF" 2>/dev/null || true)"
  final_stop_bt_service="$(normalize_usb_bt_boolean_flag "$final_stop_bt_service")"
  final_hard_block="$(normalize_usb_bt_boolean_flag "$final_hard_block")"
  final_eee_off="$(normalize_usb_ethernet_eee_flag "$final_eee_off")"
  if [[ "$final_stop_bt_service" == "1" ]]; then
    say "Configured bluetooth.service stop/start integration: <enabled>"
  else
    say "Configured bluetooth.service stop/start integration: <disabled>"
  fi
  if [[ "$final_hard_block" == "1" ]]; then
    say "Configured aggressive USB hard-block IDs: ${final_hard_block_ids:-<all matched targets>}"
  else
    say "Configured aggressive USB hard-block IDs: <disabled>"
  fi
  if [[ "$final_eee_off" == "1" ]]; then
    say "Configured USB Ethernet EEE-off IDs: ${final_eee_ids:-<none>}"
  else
    say "Configured USB Ethernet EEE-off IDs: <disabled>"
  fi
  print_usb_bt_mitigation_target_summary
}

# Install a small helper that dumps the current boot's VFIO-related logs to the
# desktop of the primary user. This makes it easy to inspect what happened
# during early boot without having to remember journalctl incantations.
install_bootlog_dumper() {
  local user home user_home user_group
  user_home="$(resolve_desktop_user_home 2>/dev/null || true)"
  if [[ -z "$user_home" ]]; then
    note "Skipping boot log dumper: could not resolve a desktop user home under /home."
    return 0
  fi
  user="${user_home%%$'\t'*}"
  home="${user_home#*$'\t'}"
  user_group="$(id -gn "$user" 2>/dev/null || true)"
  [[ -n "$user_group" ]] || user_group="$user"

  [[ -n "$home" && -d "$home" ]] || {
    note "Skipping boot log dumper: resolved user '$user' has no accessible home directory."
    return 0
  }

  # Place the helper script under the user's home (on /home), so it
  # survives Btrfs root snapshot rollbacks. Only the small systemd
  # unit lives on the root filesystem.
  local bin_dir="$home/.local/bin"
  local bin="$bin_dir/vfio-dump-boot-log.sh"
  local unit="/etc/systemd/system/vfio-dump-boot-log.service"

  mkdir -p "$bin_dir"

  backup_file "$bin"
  backup_file "$unit"

  write_file_atomic "$bin" 0755 "root:root" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

USER_HOME="__VFIO_BOOT_USER_HOME__"
TARGET_USER="__VFIO_BOOT_USER__"
TARGET_GROUP="__VFIO_BOOT_GROUP__"
DESKTOP_DIR="${USER_HOME}/Desktop"

# Try to detect the current Btrfs root subvolume/snapshot from the
# kernel cmdline so logs are snapshot-aware.
CMDLINE="$(cat /proc/cmdline 2>/dev/null || true)"
SNAP_SUBVOL=""
SNAP_ID=""
if [ -n "$CMDLINE" ]; then
  SNAP_SUBVOL="$(printf '%s\n' "$CMDLINE" | sed -n 's/.*rootflags=[^ ]*subvol=\([^ ,]*\).*/\1/p')"
  if [ -n "$SNAP_SUBVOL" ]; then
    SNAP_ID="$(printf '%s\n' "$SNAP_SUBVOL" | sed -n 's#^.*/@/.snapshots/\([0-9]\+\)/snapshot.*#\1#p')"
  fi
fi

# Organize logs under a dedicated tree by date to avoid clutter and
# make it easy to browse: Desktop/vfio-boot-logs/YYYY/MM/DD/
LOG_ROOT="${DESKTOP_DIR}/vfio-boot-logs"
DATE_PATH="$(date +%Y/%m/%d)"
LOG_DIR="${LOG_ROOT}/${DATE_PATH}"
mkdir -p "${LOG_DIR}" || true
# Keep the full log tree user-manageable even though this helper runs as root.
# This allows the desktop user to inspect and delete collected boot logs
# without requiring sudo for routine cleanup.
chown -R "$TARGET_USER:$TARGET_GROUP" "$LOG_ROOT" 2>/dev/null || true
chmod -R u+rwX "$LOG_ROOT" 2>/dev/null || true

# Dump as much information as possible for the current boot, including
# early failures, kernel messages, and systemd unit errors.
TS="$(date +%H%M%S)"
OUT_CUR="${LOG_DIR}/vfio-boot-${TS}-current.log"
OUT_PREV="${LOG_DIR}/vfio-boot-${TS}-previous.log"

# Current boot log
{
  echo "# VFIO boot log dump for $(date -Is) (current boot)"
  echo "# Host: $(hostname)  Kernel: $(uname -r)"
  echo "# Root subvolume: ${SNAP_SUBVOL:-<unknown>}"
  [ -n "$SNAP_ID" ] && echo "# Snapshot ID: ${SNAP_ID}"
  echo
  echo "# Log directory: ${LOG_DIR}"
  echo
  # Full journal for this boot, no pager, with explanatory text.
  journalctl -b -x -a --no-pager || true
} >"$OUT_CUR" 2>&1 || true

# Previous boot log (if available). This is particularly useful when
# the previous boot crashed or rebooted unexpectedly; we can inspect
# it after the next successful boot.
if journalctl -b -1 >/dev/null 2>&1; then
  {
    echo "# VFIO boot log dump for $(date -Is) (previous boot)"
    echo "# Host: $(hostname)  Kernel: $(uname -r)"
    echo "# Root subvolume: ${SNAP_SUBVOL:-<unknown>}"
    [ -n "$SNAP_ID" ] && echo "# Snapshot ID (current): ${SNAP_ID}"
    echo
    echo "# Log directory: ${LOG_DIR}"
    echo
    journalctl -b -1 -x -a --no-pager || true
  } >"$OUT_PREV" 2>&1 || true
fi

# Normalize ownership/perms after writes so newly created files from this run
# are also user-manageable.
chown -R "$TARGET_USER:$TARGET_GROUP" "$LOG_ROOT" 2>/dev/null || true
chmod -R u+rwX "$LOG_ROOT" 2>/dev/null || true
EOF

  # Service: run once each boot as early as practical while still guaranteeing
  # journald and local filesystems are available, and complete BEFORE
  # multi-user.target is reached.
  write_file_atomic "$unit" 0644 "root:root" <<EOF
[Unit]
Description=VFIO Early Boot Log Dumper (current and previous boot)
Wants=local-fs.target systemd-journald.service
After=local-fs.target systemd-journald.service
Before=multi-user.target
ConditionPathExists=$bin

[Service]
Type=oneshot
ExecStart=$bin

[Install]
WantedBy=multi-user.target
EOF

  # Replace placeholder with the actual user home path in the helper script.
  if [[ -n "$home" ]]; then
    if (( ! DRY_RUN )); then
      sed -i "s#__VFIO_BOOT_USER_HOME__#$home#g" "$bin" || true
      sed -i "s#__VFIO_BOOT_USER__#$user#g" "$bin" || true
      sed -i "s#__VFIO_BOOT_GROUP__#$user_group#g" "$bin" || true
    fi
  fi
  if (( ! DRY_RUN )); then
    [[ -x "$bin" ]] || die "Boot log dumper deployment failed: script is not executable at $bin"
    [[ -f "$unit" ]] || die "Boot log dumper deployment failed: missing unit at $unit"
  fi

  if have_cmd systemctl; then
    run systemctl daemon-reload
    run systemctl enable vfio-dump-boot-log.service || true
  fi

  note "Boot log dumper installed. It will run once each boot before multi-user.target and drop vfio-boot-*.log files under ${home}/Desktop/vfio-boot-logs/."
}

# Small helper to set KDE Plasma Wayland as the default SDDM session when desired.
# This is optional and only affects display-manager login, not VFIO itself.
set_plasma_wayland_default_session() {
  # Only attempt this on systems that appear to use SDDM.
  if ! command -v sddm >/dev/null 2>&1 && [[ ! -d /etc/sddm.conf.d && ! -f /etc/sddm.conf ]]; then
    return 0
  fi

  # UPDATED: Search for Plasma 6 specific session files first.
  # plasma6.desktop / plasma.desktop = Plasma 6 defaults
  # plasmawayland.desktop = Plasma 5 legacy
  local session
  for session in plasma6.desktop plasma.desktop plasmawayland.desktop org.kde.plasma.wayland.desktop; do
    if [[ -f "/usr/share/wayland-sessions/$session" ]]; then
      local sddm_dir="/etc/sddm.conf.d"
      local sddm_file="$sddm_dir/10-vfio-plasma-wayland.conf"
      mkdir -p "$sddm_dir"
      backup_file "$sddm_file"
      write_file_atomic "$sddm_file" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Prefer KDE Plasma (Wayland) as the default session. This improves
# compatibility with modern PipeWire-based desktops when using VFIO.
[General]
Session=$session
EOF
      say "Configured SDDM to prefer KDE Plasma Wayland session by default ($session)."
      return 0
    fi
  done

  # If we get here, no known Plasma Wayland session file was found; do nothing.
}

# ---------------- Main ----------------

# Scan the VBIOS/ folder next to this script for *.rom candidates and run the
# full _vbios_rom_matches_gpu matcher (+ byte-swap auto-repair) against each,
# so the operator can see which dump is correct for the configured guest GPU
# when they have dropped multiple candidates into VBIOS/. For each candidate
# that PASSES the PCI-ID matcher, ALSO byte-compares it against the card's
# LIVE sysfs option ROM (see _vbios_dump_live_rom / _vbios_compare_rom_to_live)
# so a dump with the right PCI ID but WRONG content (a garbage / wrong-SKU /
# different-version dump that would give a black screen if pinned) is flagged
# BYTES DIFFER instead of a bare MATCH. Prints one verdict line per candidate
# (MATCH / byte-swap-repaired MATCH / no match) with the embedded identity,
# plus a green EXACT/PADDED or red BYTES-DIFFER sub-line per match, and a
# summary line. Read-only; never writes or defines.
# Called from verify_setup() so `--verify` surfaces this automatically.
verify_vbios_candidates() {
  local _guest_gpu _src_dir _f _f_name _desc _err _n _ok _repaired
  _guest_gpu="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
  [[ -n "$_guest_gpu" ]] || return 0
  _src_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" && pwd)/VBIOS"
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}vBIOS candidate scan (VBIOS/ folder):${C_RESET}"
  else
    say "vBIOS candidate scan (VBIOS/ folder):"
  fi
  if [[ ! -d "$_src_dir" ]]; then
    note "No VBIOS/ folder next to $SCRIPT_NAME (nothing to scan)."
    return 0
  fi
  local -a _cands=()
  while IFS= read -r -d '' _f; do
    _cands+=("$_f")
  done < <(find "$_src_dir" -maxdepth 1 -iname '*.rom' -print0 2>/dev/null)
  _n=${#_cands[@]}
  if (( _n == 0 )); then
    note "No *.rom files found in $_src_dir (nothing to scan)."
    return 0
  fi
  note "Scanning $_n candidate(s) in $_src_dir against guest GPU $_guest_gpu:"
  _ok=0; _repaired=0
  local _err_tmp
  _err_tmp="$(mktemp)"
  # Dump the guest GPU's live option ROM from sysfs ONCE (best-effort) so each
  # matched candidate can be byte-compared against it. This catches a dump that
  # has the RIGHT embedded PCI ID (passes the matcher) but WRONG content -- the
  # exact trap seen with a generic/mis-extracted tuf-gaming.rom that matched
  # 1002:7550 in the header but was a garbage image (different sha256 + size
  # from the card's actual 116736-byte ROM), which gave a black screen when
  # pinned. If the live ROM cannot be read (not root, device busy under a
  # running VM), the byte comparison is skipped and only the PCI-ID match is
  # shown.
  local _live_rom="" _live_rom_note=""
  _live_rom="$(_vbios_dump_live_rom "$_guest_gpu" 2>/dev/null || true)"
  if [[ -z "$_live_rom" ]]; then
    _live_rom_note=" (live ROM byte-comparison skipped — could not read sysfs ROM; run as root with the VM shut off)"
  fi
  for _f in "${_cands[@]}"; do
    _f_name="$(basename "$_f")"
    if _desc="$(_vbios_rom_matches_gpu "$_f" "$_guest_gpu" 2>"$_err_tmp")"; then
      if (( ENABLE_COLOR )); then
        say "  ${C_GREEN}✔ MATCH${C_RESET}: $_f_name -- $_desc"
      else
        say "  MATCH: $_f_name -- $_desc"
      fi
      _ok=$((_ok+1))
      # Byte-compare the matched file against the card's live ROM (best-effort):
      # green EXACT/PADDED = safe to pin; red BYTES DIFFER = right PCI ID but
      # wrong content (garbage / wrong-SKU) — pinning it risks a black screen.
      _vbios_print_live_rom_verdict "$_f" "$_live_rom"
    else
      # Try byte-swap auto-repair (techpowerup downloads are aa55-swapped).
      local _rr _rp _rdesc
      if _rr="$(_vbios_autorepair_byteswap "$_f" "$_guest_gpu" 2>/dev/null)"; then
        IFS='|' read -r _rp _rdesc <<<"$_rr"
        if (( ENABLE_COLOR )); then
          say "  ${C_GREEN}✔ MATCH${C_RESET} (byte-swap auto-repaired): $_f_name -- $_rdesc"
        else
          say "  MATCH (byte-swap auto-repaired): $_f_name -- $_rdesc"
        fi
        _ok=$((_ok+1)); _repaired=$((_repaired+1))
        # Byte-compare the REPAIRED temp (what would actually be pinned) against
        # the card's live ROM before cleaning up the repaired temp.
        _vbios_print_live_rom_verdict "$_rp" "$_live_rom"
        rm -f "$_rp" 2>/dev/null || true
        rmdir "$(dirname "$_rp")" 2>/dev/null || true
      else
        local _emsg
        _emsg="$(cat "$_err_tmp" 2>/dev/null || echo "not a recognized GPU vBIOS dump")"
        if (( ENABLE_COLOR )); then
          say "  ${C_RED}✖ no match${C_RESET}: $_f_name -- $_emsg"
        else
          say "  no match: $_f_name -- $_emsg"
        fi
      fi
    fi
  done
  rm -f "$_err_tmp" "$_live_rom" 2>/dev/null || true
  say
  if (( _ok > 0 )); then
    local _sum_extra=""
    (( _repaired > 0 )) && _sum_extra=" ($_repaired via byte-swap auto-repair)"
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}✔ vBIOS SUMMARY: $_ok/$_n candidate(s) match the guest GPU${C_RESET}$_sum_extra$_live_rom_note"
    else
      say "vBIOS SUMMARY: $_ok/$_n candidate(s) match the guest GPU$_sum_extra$_live_rom_note"
    fi
    note "Any MATCHed candidate is usable -- re-run --install-dynamic-binding to auto-inject the first MATCH."
    # RESTRICTION: only one vBIOS may be pinned per graphics card. When more
    # than one candidate matches (common: the operator dropped several
    # techpowerup re-uploads + their own dump into VBIOS/), tell them to keep
    # exactly one and delete the rest -- the installer pins only the first
    # match anyway, and leaving duplicates is clutter + a footgun if the first
    # match happens to be a wrong-subsystem family-only false positive.
    if (( _ok > 1 )); then
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}⚠ RESTRICTION${C_RESET}: only ONE vBIOS is allowed per graphics card -- $_ok matched. Keep one (prefer a clean 55aa dump, or a techpowerup download this script auto-repairs) and delete the rest from $_src_dir."
      else
        say "RESTRICTION: only ONE vBIOS is allowed per graphics card -- $_ok matched. Keep one (prefer a clean 55aa dump, or a techpowerup download this script auto-repairs) and delete the rest from $_src_dir."
      fi
    fi
  else
    if (( ENABLE_COLOR )); then
      say "${C_RED}✖ vBIOS SUMMARY: 0/$_n candidate(s) match the guest GPU${C_RESET}"
    else
      say "vBIOS SUMMARY: 0/$_n candidate(s) match the guest GPU"
    fi
    note "Drop a subsystem-matching *.rom into $_src_dir (use the listings this script prints at install time) and re-run."
  fi
}

# Print an ASCII-art GPU card showing the role (GUEST/HOST), live card name,
# BDF, boot_vga, and current driver — color-coded so `--verify` output is easy
# to scan at a glance. The GUEST card (passed to the VM) and the HOST card
# (your display) are drawn side by side as little cards with a fan motif.
# $1 = BDF, $2 = role ("GUEST" | "HOST"), $3 = binding_mode (for guest dynamic note)
_print_gpu_card_visual() {
  local _bdf="$1" _role="$2" _mode="${3:-early}"
  [[ -n "$_bdf" ]] || return 0
  # Normalize to uppercase so the DYNAMIC comparisons below are case-insensitive
  # (the conf stores lowercase "dynamic", but the wizard/CTX path uses DYNAMIC).
  _mode="${_mode^^}"
  local _drv _name _bv _status _status_color _role_color _border_color _pad
  _drv="$(bdf_driver_name "$_bdf")"
  _bv="$(pci_boot_vga_flag "$_bdf")"
  # Card name from lspci (best-effort). lspci prints e.g.
  #   "Navi 48 [Radeon RX 9070/9070 XT/9070 GRE]"
  # where the bracket holds the marketing name (more useful than the codename).
  # Strip the PCI-ID bracket and rev, then prefer the marketing bracket content.
  _name=""
  if have_cmd lspci; then
    _name="$(lspci -s "$_bdf" 2>/dev/null | sed 's/^[^]]*] *//' | sed -E 's/ \[[0-9a-f]{4}:[0-9a-f]{4}\].*$//; s/ \(rev [^)]+\)$//')"
    _name="$(trim "$_name")"
    # If there is a [...Radeon/NVIDIA/Intel...] marketing bracket, keep only it.
    _name="$(printf '%s' "$_name" | sed -E 's/^[^[]*\[([^]]+)\]$/\1/')"
  fi
  [[ -n "$_name" ]] || _name="<unknown GPU>"

  # Role + status coloring.
  _role_color="$C_CYAN"
  _border_color="$C_CYAN"
  case "$_role" in
    GUEST)
      if [[ "$_drv" == "vfio-pci" ]]; then
        _status="vfio-pci ✓ (parked)"
        _status_color="$C_GREEN"
        [[ "$_mode" != "DYNAMIC" ]] && _status="vfio-pci ✓"
      elif [[ "$_mode" == "DYNAMIC" && "$_drv" == "amdgpu" ]]; then
        _status="amdgpu ✓ (dynamic)"
        _status_color="$C_GREEN"
      elif [[ "$_mode" == "DYNAMIC" ]]; then
        _status="${_drv} ? (dynamic)"
        _status_color="$C_YELLOW"
      else
        _status="${_drv} ✖ (want vfio-pci)"
        _status_color="$C_RED"
      fi
      ;;
    HOST)
      if [[ "$_drv" == "vfio-pci" ]]; then
        _status="vfio-pci ✖ (stolen!)"
        _status_color="$C_RED"
      else
        _status="${_drv} ✓ (display)"
        _status_color="$C_GREEN"
      fi
      _role_color="$C_BLUE"
      _border_color="$C_BLUE"
      ;;
  esac

  # boot_vga annotation on the BDF line.
  local _bvnote=""
  [[ "$_bv" == "1" ]] && _bvnote="  (Boot VGA)"

  # Fixed-width text area (36 cols) so the right border aligns. Truncate
  # over-long names to keep the box tidy in a monospace terminal.
  _pad() { local _s="$1" _w=36; printf '%s' "$_s"; local _l=${#_s}; (( _l < _w )) && printf '%*s' $((_w - _l)) "" || true; }
  # Truncate to 36 chars (character count; box-drawing is single-width).
  _trunc() { local _s="$1" _w=36; (( ${#_s} > _w )) && printf '%s' "${_s:0:_w}" || printf '%s' "$_s"; }
  local _name_t _bdf_t _status_t
  _name_t="$(_trunc "$_name")"
  _bdf_t="$(_trunc "${_bdf}${_bvnote}")"
  _status_t="$(_trunc "[ ${_role} • ${_status} ]")"

  if (( ENABLE_COLOR )); then
    say "${_border_color}   ┌──────────────────────────────────────────────┐${C_RESET}"
    say "${_border_color}   │${C_RESET}  ╭───╮   ${C_BOLD}$(_pad "$_name_t")${C_RESET}${_border_color}│${C_RESET}"
    say "${_border_color}   │${C_RESET}  │ ◎ │   $(_pad "$_bdf_t")${_border_color}│${C_RESET}"
    say "${_border_color}   │${C_RESET}  ╰───╯   ${_status_color}${C_BOLD}$(_pad "$_status_t")${C_RESET}${_border_color}│${C_RESET}"
    say "${_border_color}   └──────────────────────────────────────────────┘${C_RESET}"
  else
    say "   ┌──────────────────────────────────────────────┐"
    say "   │  ╭───╮   $(_pad "$_name_t")│"
    say "   │  │ ◎ │   $(_pad "$_bdf_t")│"
    say "   │  ╰───╯   $(_pad "$_status_t")│"
    say "   └──────────────────────────────────────────────┘"
  fi
}

verify_setup() {
  hdr "VERIFY VFIO SETUP"
  VFIO_BRIEF_REPORT=1 detect_existing_vfio_report

  [[ -f "$CONF_FILE" ]] || die "Missing $CONF_FILE (nothing to verify)."
  # shellcheck disable=SC1090
  . "$CONF_FILE"

  # Normalize the binding mode to uppercase so the DYNAMIC comparisons below
  # work regardless of how the conf stored it (rewrite_conf_key writes lowercase
  # "dynamic"/"early", but the wizard/CTX path uses uppercase DYNAMIC).
  # Without this, --verify FAILS a dynamic setup because "dynamic" != "DYNAMIC".
  VFIO_BINDING_MODE="${VFIO_BINDING_MODE:-early}"
  VFIO_BINDING_MODE="${VFIO_BINDING_MODE^^}"
  case "$VFIO_BINDING_MODE" in EARLY|DYNAMIC) ;; *) VFIO_BINDING_MODE="EARLY" ;; esac

  local ok=1

  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}Configured devices from $CONF_FILE:${C_RESET}"
  else
    say "Configured devices from $CONF_FILE:"
  fi
  say "  Guest GPU:   ${GUEST_GPU_BDF:-<missing>}"
  say "  Guest audio: ${GUEST_AUDIO_BDFS_CSV:-<none>}"
  say "  Host audio:  ${HOST_AUDIO_BDFS_CSV:-<none>}"
  say "  Binding mode: ${VFIO_BINDING_MODE:-early}"

  # Visual ASCII card layout: GUEST (passed to VM) and HOST (your display),
  # with live card name, BDF, boot_vga, and current driver — color-coded.
  if [[ -n "${GUEST_GPU_BDF:-}" ]]; then
    say
    _print_gpu_card_visual "$GUEST_GPU_BDF" GUEST "${VFIO_BINDING_MODE:-early}"
  fi
  if [[ -n "${HOST_GPU_BDF:-}" ]]; then
    _print_gpu_card_visual "$HOST_GPU_BDF" HOST "${VFIO_BINDING_MODE:-early}"
  fi

  # Basic sanity
  if [[ -z "${GUEST_GPU_BDF:-}" ]]; then
    if (( ENABLE_COLOR )); then
      say "${C_RED}✖ FAIL${C_RESET}: GUEST_GPU_BDF is missing in $CONF_FILE"
    else
      say "FAIL: GUEST_GPU_BDF is missing in $CONF_FILE"
    fi
    ok=0
  else
    local guest_drv
    guest_drv="$(bdf_driver_name "$GUEST_GPU_BDF")"
    if [[ "$guest_drv" != "vfio-pci" ]]; then
      if [[ "${VFIO_BINDING_MODE:-early}" == "DYNAMIC" ]]; then
        if (( ENABLE_COLOR )); then
          local _la_note=""
          if grep -q '^VFIO_DYNAMIC_LIVE_ATTACH="1"' "$CONF_FILE" 2>/dev/null; then
            _la_note=" + live-attach (hotswap: VM starts without GPU, helper hot-attaches at VM start)"
          fi
          say "${C_GREEN}✔ OK${C_RESET}: Guest GPU $GUEST_GPU_BDF on host driver '$guest_drv' (dynamic binding — hook switches at VM start)$_la_note"
        else
          say "OK: Guest GPU $GUEST_GPU_BDF on host driver '$guest_drv' (dynamic binding — hook switches at VM start)$_la_note"
        fi
      else
        if (( ENABLE_COLOR )); then
          say "${C_RED}✖ FAIL${C_RESET}: Guest GPU $GUEST_GPU_BDF is not bound to vfio-pci (driver: $guest_drv)"
        else
          say "FAIL: Guest GPU $GUEST_GPU_BDF is not bound to vfio-pci (driver: $guest_drv)"
        fi
        note "This is expected BEFORE reboot (or if the vfio bind service isn't enabled)."
        ok=0
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Guest GPU $GUEST_GPU_BDF bound to vfio-pci"
      else
        say "OK: Guest GPU $GUEST_GPU_BDF bound to vfio-pci"
      fi
    fi
  fi

  if [[ -n "${GUEST_AUDIO_BDFS_CSV:-}" ]]; then
    local IFS=','
    for dev in $GUEST_AUDIO_BDFS_CSV; do
      [[ -n "$dev" ]] || continue
      local aud_drv
      aud_drv="$(bdf_driver_name "$dev")"
      if [[ "$aud_drv" != "vfio-pci" ]]; then
        if [[ "${VFIO_BINDING_MODE:-early}" == "DYNAMIC" ]]; then
          if (( ENABLE_COLOR )); then
            say "${C_GREEN}✔ OK${C_RESET}: Guest audio $dev on host driver '$aud_drv' (dynamic binding)"
          else
            say "OK: Guest audio $dev on host driver '$aud_drv' (dynamic binding)"
          fi
        else
          if (( ENABLE_COLOR )); then
            say "${C_RED}✖ FAIL${C_RESET}: Guest audio $dev is not bound to vfio-pci (driver: $aud_drv)"
          else
            say "FAIL: Guest audio $dev is not bound to vfio-pci (driver: $aud_drv)"
          fi
          ok=0
        fi
      else
        if (( ENABLE_COLOR )); then
          say "${C_GREEN}✔ OK${C_RESET}: Guest audio $dev bound to vfio-pci"
        else
          say "OK: Guest audio $dev bound to vfio-pci"
        fi
      fi
    done
  fi

  if [[ -n "${HOST_AUDIO_BDFS_CSV:-}" ]]; then
    local host_audio="${HOST_AUDIO_BDFS_CSV%%,*}"
    if [[ "$(bdf_driver_name "$host_audio")" == "vfio-pci" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_RED}✖ FAIL${C_RESET}: Host audio $host_audio is bound to vfio-pci (should remain on host driver)"
      else
        say "FAIL: Host audio $host_audio is bound to vfio-pci (should remain on host driver)"
      fi
      ok=0
    else
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Host audio $host_audio driver: $(bdf_driver_name "$host_audio")"
      else
        say "OK: Host audio $host_audio driver: $(bdf_driver_name "$host_audio")"
      fi
    fi
  fi

  # Check that our files/services exist (best-effort)
  say
  if [[ -f "$BIND_SCRIPT" ]]; then
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}✔ OK${C_RESET}: Bind script present: $BIND_SCRIPT"
    else
      say "OK: Bind script present: $BIND_SCRIPT"
    fi
  else
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: Bind script missing: $BIND_SCRIPT"
    else
      say "WARN: Bind script missing: $BIND_SCRIPT"
    fi
  fi

  if [[ -f "$SYSTEMD_UNIT" ]]; then
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}✔ OK${C_RESET}: Systemd unit present: $SYSTEMD_UNIT"
    else
      say "OK: Systemd unit present: $SYSTEMD_UNIT"
    fi
    if command -v systemctl >/dev/null 2>&1; then
      local enabled active
      enabled="$(systemctl is-enabled vfio-bind-selected-gpu.service 2>/dev/null || true)"
      active="$(systemctl is-active vfio-bind-selected-gpu.service 2>/dev/null || true)"
      if (( ENABLE_COLOR )); then
        say "${C_BLUE}INFO${C_RESET}: vfio-bind-selected-gpu.service is-enabled: ${enabled:-<unknown>}"
        say "${C_BLUE}INFO${C_RESET}: vfio-bind-selected-gpu.service is-active:  ${active:-<unknown>}"
      else
        say "INFO: vfio-bind-selected-gpu.service is-enabled: ${enabled:-<unknown>}"
        say "INFO: vfio-bind-selected-gpu.service is-active:  ${active:-<unknown>}"
      fi
    fi
  else
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: Systemd unit missing: $SYSTEMD_UNIT"
    else
      say "WARN: Systemd unit missing: $SYSTEMD_UNIT"
    fi
  fi

  # Dynamic binding: check libvirt hook script + qemu entry presence.
  if [[ "${VFIO_BINDING_MODE:-early}" == "DYNAMIC" ]]; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}Dynamic binding hook check:${C_RESET}"
    else
      say "Dynamic binding hook check:"
    fi
    if [[ -x "$LIBVIRT_HOOK_SCRIPT" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Libvirt hook script present: $LIBVIRT_HOOK_SCRIPT"
      else
        say "OK: Libvirt hook script present: $LIBVIRT_HOOK_SCRIPT"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_RED}✖ FAIL${C_RESET}: Libvirt hook script missing: $LIBVIRT_HOOK_SCRIPT"
      else
        say "FAIL: Libvirt hook script missing: $LIBVIRT_HOOK_SCRIPT"
      fi
      ok=0
    fi
    if [[ -f "$LIBVIRT_HOOK_ENTRY" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Libvirt qemu hook entry present: $LIBVIRT_HOOK_ENTRY"
      else
        say "OK: Libvirt qemu hook entry present: $LIBVIRT_HOOK_ENTRY"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_RED}✖ FAIL${C_RESET}: Libvirt qemu hook entry missing: $LIBVIRT_HOOK_ENTRY"
      else
        say "FAIL: Libvirt qemu hook entry missing: $LIBVIRT_HOOK_ENTRY"
      fi
      ok=0
    fi
  fi

  # Live-attach (hotswap) artifact check: when VFIO_DYNAMIC_LIVE_ATTACH=1, the
  # live-attach helper + VM list + GPU device XML must be present. The card is
  # EXPECTED on amdgpu when no VM is running (the VM XML was stripped so the VM
  # boots on a virtual display; the helper hot-attaches the GPU at VM start).
  if [[ "$VFIO_BINDING_MODE" == "DYNAMIC" ]] && grep -q '^VFIO_DYNAMIC_LIVE_ATTACH="1"' "$CONF_FILE" 2>/dev/null; then
    say
    if (( ENABLE_COLOR )); then
      say "${C_CYAN}Live-attach (hotswap) check:${C_RESET}"
    else
      say "Live-attach (hotswap) check:"
    fi
    if [[ -x "$LIVE_ATTACH_HELPER" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Live-attach helper present: $LIVE_ATTACH_HELPER"
      else
        say "OK: Live-attach helper present: $LIVE_ATTACH_HELPER"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_RED}✖ FAIL${C_RESET}: Live-attach helper missing: $LIVE_ATTACH_HELPER"
      else
        say "FAIL: Live-attach helper missing: $LIVE_ATTACH_HELPER"
      fi
      ok=0
    fi
    if [[ -s "$LIVE_ATTACH_VM_LIST" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Live-attach VM list present: $LIVE_ATTACH_VM_LIST ($(grep -cve '^[[:space:]]*$' "$LIVE_ATTACH_VM_LIST" 2>/dev/null || echo 0) VM(s))"
      else
        say "OK: Live-attach VM list present: $LIVE_ATTACH_VM_LIST"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_RED}✖ FAIL${C_RESET}: Live-attach VM list missing or empty: $LIVE_ATTACH_VM_LIST"
      else
        say "FAIL: Live-attach VM list missing or empty: $LIVE_ATTACH_VM_LIST"
      fi
      ok=0
    fi
    if [[ -s "$LIVE_ATTACH_GPU_XML" ]]; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Live-attach GPU device XML present: $LIVE_ATTACH_GPU_XML"
      else
        say "OK: Live-attach GPU device XML present: $LIVE_ATTACH_GPU_XML"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}WARN${C_RESET}: Live-attach GPU device XML missing: $LIVE_ATTACH_GPU_XML (re-run --install-live-attach with the VM shut off)"
      else
        say "WARN: Live-attach GPU device XML missing: $LIVE_ATTACH_GPU_XML"
      fi
    fi
  fi

  # IOMMU sanity (best-effort)
  say
  if [[ -d /sys/kernel/iommu_groups ]]; then
    if [[ -n "${GUEST_GPU_BDF:-}" ]]; then
      local g
      g="$(iommu_group_of_bdf "$GUEST_GPU_BDF" 2>/dev/null || true)"
      if [[ -n "$g" ]]; then
        if (( ENABLE_COLOR )); then
          say "${C_GREEN}✔ OK${C_RESET}: IOMMU group exists for guest GPU ($GUEST_GPU_BDF): group $g"
        else
          say "OK: IOMMU group exists for guest GPU ($GUEST_GPU_BDF): group $g"
        fi
      else
        if (( ENABLE_COLOR )); then
          say "${C_YELLOW}WARN${C_RESET}: No IOMMU group found for guest GPU ($GUEST_GPU_BDF). IOMMU may be disabled."
        else
          say "WARN: No IOMMU group found for guest GPU ($GUEST_GPU_BDF). IOMMU may be disabled."
        fi
      fi
    fi
  else
    if (( ENABLE_COLOR )); then
      say "${C_YELLOW}WARN${C_RESET}: /sys/kernel/iommu_groups not present. IOMMU may be disabled in BIOS/kernel."
    else
      say "WARN: /sys/kernel/iommu_groups not present. IOMMU may be disabled in BIOS/kernel."
    fi
  fi

  # Kernel cmdline + bootloader sanity (if available)
  say
  if [[ -r /proc/cmdline ]]; then
    local cmd
    cmd="$(cat /proc/cmdline 2>/dev/null || true)"
    if grep -qw "iommu=pt" <<<"$cmd"; then
      if (( ENABLE_COLOR )); then
        say "${C_GREEN}✔ OK${C_RESET}: Running kernel cmdline contains iommu=pt"
      else
        say "OK: Running kernel cmdline contains iommu=pt"
      fi
    else
      if (( ENABLE_COLOR )); then
        say "${C_YELLOW}WARN${C_RESET}: Running kernel cmdline does NOT contain iommu=pt"
      else
        say "WARN: Running kernel cmdline does NOT contain iommu=pt"
      fi
    fi
  fi

  if [[ -f /etc/default/grub ]]; then
    local key current
    key="$(grub_get_key 2>/dev/null || true)"
    if [[ -n "$key" ]]; then
      current="$(grub_read_cmdline "$key" 2>/dev/null || true)"
      if grep -qw "iommu=pt" <<<"$current"; then
        if (( ENABLE_COLOR )); then
          say "${C_GREEN}✔ OK${C_RESET}: /etc/default/grub contains iommu=pt"
        else
          say "OK: /etc/default/grub contains iommu=pt"
        fi
      else
        if (( ENABLE_COLOR )); then
          say "${C_YELLOW}WARN${C_RESET}: /etc/default/grub missing iommu=pt (did you skip GRUB edit?)"
        else
          say "WARN: /etc/default/grub missing iommu=pt (did you skip GRUB edit?)"
        fi
      fi
    fi
  fi

  # Resizable BAR + Above 4G status for the configured guest GPU (informational only).
  if [[ -n "${GUEST_GPU_BDF:-}" ]]; then
    say
    hdr "GPU BAR layout (guest GPU)"
    local rebar_state above4g_state
    rebar_state="$(rebar_status_for_bdf "$GUEST_GPU_BDF")"
    above4g_state="$(above_4g_decoding_status_for_bdf "$GUEST_GPU_BDF")"
    if (( ENABLE_COLOR )); then
      say "${C_BLUE}INFO${C_RESET}: ReBAR status for $GUEST_GPU_BDF: ${C_BOLD}${rebar_state}${C_RESET}"
      say "${C_BLUE}INFO${C_RESET}: Above 4G Decoding (64-bit BAR) for $GUEST_GPU_BDF: ${C_BOLD}${above4g_state}${C_RESET}"
    else
      say "INFO: ReBAR status for $GUEST_GPU_BDF: ${rebar_state}"
      say "INFO: Above 4G Decoding (64-bit BAR) for $GUEST_GPU_BDF: ${above4g_state}"
    fi
    note "For passthrough, Above 4G Decoding / 64-bit BAR support should typically be ENABLED so large BARs can be mapped into the guest. ReBAR on top is optional and may need to be toggled depending on your platform."
  fi

  # On openSUSE/BLS, also check the CURRENT Boot Loader Spec entry that
  # was used to boot this kernel, so you know whether that exact entry
  # has the expected VFIO/IOMMU flags.
  #
  # IMPORTANT: some users boot non-standard kernels (for example Liquorix)
  # from the same root/subvolume as the distribution kernels. In that
  # case multiple BLS entries can share the same root= and rootflags=
  # values. To avoid falsely reporting the wrong entry, we also require
  # that the BLS file references the *running* kernel version string
  # (uname -r), similar to the logic used in systemd_boot_add_kernel_params().
  if is_opensuse_like && command -v sdbootutil >/dev/null 2>&1; then
    say
    say "-- Current BLS entry (openSUSE) --"
    local running_cmdline bls_dir entry opts running_kernel
    running_cmdline="$(cat /proc/cmdline 2>/dev/null || true)"
    bls_dir="$(systemd_boot_entries_dir 2>/dev/null || true)"
    running_kernel="$(uname -r)"
    if [[ -n "$bls_dir" && -n "$running_cmdline" && -n "$running_kernel" ]]; then
      local running_root running_rootflags
      running_root="$(sed -n 's/.*\<root=\([^ ]*\).*/\1/p' <<<"$running_cmdline")"
      running_rootflags="$(sed -nE 's/.*rootflags="?([^ "]+)"?.*/\1/p' <<<"$running_cmdline")"
      if [[ -n "$running_root" && -n "$running_rootflags" ]]; then
        local f matched=0
        shopt -s nullglob
        for f in "$bls_dir"/*.conf; do
          opts="$(grep -m1 -E '^options[[:space:]]+' "$f" 2>/dev/null | sed -E 's/^options[[:space:]]+//')"
          opts="$(trim "${opts:-}")"
          [[ -n "$opts" ]] || continue
          # Only consider entries whose file content mentions the running
          # kernel version (usually on the linux / initrd lines).
          if ! grep -Fq "$running_kernel" "$f" 2>/dev/null; then
            continue
          fi
          local eroot eflags
          eroot="$(sed -n 's/.*\<root=\([^ ]*\).*/\1/p' <<<"$opts")"
          eflags="$(sed -nE 's/.*rootflags="?([^ "]+)"?.*/\1/p' <<<"$opts")"
          if [[ -n "$eroot" && -n "$eflags" && "$eroot" == "$running_root" && "$eflags" == "$running_rootflags" ]]; then
            matched=1
            say "BLS entry: $(basename "$f")"
            if grep -qwE 'amd_iommu=on|intel_iommu=on' <<<"$opts" && \
               grep -qw "iommu=pt" <<<"$opts" && \
               grep -qw "rd.driver.pre=vfio-pci" <<<"$opts"; then
              if (( ENABLE_COLOR )); then
                say "${C_GREEN}✔ OK${C_RESET}: current BLS options contain IOMMU + rd.driver.pre=vfio-pci"
              else
                say "OK: current BLS options contain IOMMU + rd.driver.pre=vfio-pci"
              fi
            else
              if (( ENABLE_COLOR )); then
                say "${C_YELLOW}WARN${C_RESET}: current BLS options are missing some of: amd_iommu/intel_iommu, iommu=pt, rd.driver.pre=vfio-pci"
              else
                say "WARN: current BLS options are missing some of: amd_iommu/intel_iommu, iommu=pt, rd.driver.pre=vfio-pci"
              fi
              say "      You may want to re-run the installer on this snapshot to update /etc/kernel/cmdline and BLS entries."
            fi
            break
          fi
        done
        shopt -u nullglob
        if (( ! matched )); then
          say "No BLS entry exactly matching the running kernel ($running_kernel) and root/subvolume was found."
          say "This is normal if you booted a custom kernel (for example Liquorix) via a separate entry outside the standard system-* BLS files."
        fi
      fi
    fi
  fi

  # Host-side VM internet sanity for libvirt/virt-manager NAT networking.
  # Informational only; does not affect VFIO PASS/FAIL grading.
  report_vm_network_precheck || true
  # #4: stealth/perf VM tuning status for guest-GPU VMs (informational).
  say
  if (( ENABLE_COLOR )); then
    say "${C_CYAN}Stealth/perf VM tuning status:${C_RESET}"
  else
    say "Stealth/perf VM tuning status:"
  fi
  stealth_vm_tuning_status || true
  # vBIOS candidate scan: run the matcher against every *.rom in VBIOS/ so
  # the operator can see which dump is correct when they have multiple
  # candidates. Read-only; informational (does not affect PASS/FAIL grading).
  verify_vbios_candidates || true
  say
  if (( ok )); then
    if (( ENABLE_COLOR )); then
      say "${C_GREEN}✔ RESULT: PASS${C_RESET} (guest devices are on vfio-pci; host audio is not)"
    else
      say "RESULT: PASS (guest devices are on vfio-pci; host audio is not)"
    fi
    return 0
  fi
  if (( ENABLE_COLOR )); then
    say "${C_RED}✖ RESULT: FAIL${C_RESET} (see messages above)"
  else
    say "RESULT: FAIL (see messages above)"
  fi
  return 1
}

generate_rollback_script() {
  local path="/root/vfio-rollback-${RUN_TS}.sh"
  local bootlog_bin
  bootlog_bin="$(bootlog_bin_path)"

  if (( DRY_RUN )); then
    say "DRY RUN: would write rollback script to: $path"
    return 0
  fi

  # Build restore/remove commands:
  # - If backup for a path exists, restore it.
  # - Otherwise, remove the file (only for files we expect this installer to create/manage).
  # IMPORTANT: never delete /etc/default/grub; only restore if we backed it up.
  local rr=""
  rr+="if [ -f '/etc/default/grub.bak.${RUN_TS}' ]; then cp -a '/etc/default/grub.bak.${RUN_TS}' '/etc/default/grub'; fi\n"

  local managed_paths=(
    "$MODULES_LOAD"
    "$BLACKLIST_FILE"
    "$SOFTDEP_FILE"
    "$BIND_SCRIPT"
    "$GRAPHICS_DAEMON_SCRIPT"
    "$GRAPHICS_DAEMON_UNIT"
    "$UDEV_ISOLATION_RULE"
    "$LIBVIRT_HOOK_SCRIPT"
    "$LIBVIRT_HOOK_ENTRY"
    "$USB_BT_SCRIPT"
    "$USB_BT_SYSTEMD_UNIT"
    "$USB_BT_UDEV_RULE"
    "$USB_BT_MATCH_CONF"
    "$LIGHTDM_FALLBACK_CONF"
    "/etc/systemd/system/vfio-dump-boot-log.service"
    "$bootlog_bin"
    "$CONF_FILE"
    "$DRACUT_VFIO_CONF"
  )

  local p bak
  for p in "${managed_paths[@]}"; do
    bak="${p}.bak.${RUN_TS}"
    rr+="if [ -f '$bak' ]; then cp -a '$bak' '$p'; else rm -f '$p'; fi\n"
  done

  write_file_atomic "$path" 0700 "root:root" <<EOF
#!/usr/bin/env bash
set -euo pipefail

echo "Rolling back VFIO setup from ${RUN_TS}..."

# Disable/stop VFIO-related services (best-effort)
if command -v systemctl >/dev/null 2>&1; then
  systemctl disable --now vfio-bind-selected-gpu.service 2>/dev/null || true
  systemctl disable --now vfio-graphics-protocold.service 2>/dev/null || true
  systemctl disable --now vfio-disable-usb-bluetooth.service 2>/dev/null || true
  systemctl daemon-reload 2>/dev/null || true
fi

# Restore or remove managed files
${rr}

# Remove VFIO Openbox autostart marker block if backup is unavailable.
if [ -f '${OPENBOX_AUTOSTART_FILE}.bak.${RUN_TS}' ]; then
  cp -a '${OPENBOX_AUTOSTART_FILE}.bak.${RUN_TS}' '${OPENBOX_AUTOSTART_FILE}'
elif [ -f '${OPENBOX_AUTOSTART_FILE}' ]; then
  _vfio_tmp_autostart="\$(mktemp)"
  awk '
    \$0 == \"# BEGIN VFIO OPENBOX MONITOR AUTO-ACTIVATE\" { skip=1; next }
    \$0 == \"# END VFIO OPENBOX MONITOR AUTO-ACTIVATE\" { skip=0; next }
    !skip { print }
  ' '${OPENBOX_AUTOSTART_FILE}' >"\$_vfio_tmp_autostart" || true
  cat "\$_vfio_tmp_autostart" >'${OPENBOX_AUTOSTART_FILE}' || true
  rm -f "\$_vfio_tmp_autostart" || true
fi

# Rebuild boot config (best-effort)
if command -v update-grub >/dev/null 2>&1; then
  update-grub || true
elif command -v grub-mkconfig >/dev/null 2>&1; then
  if [ -d /boot/grub ]; then
    grub-mkconfig -o /boot/grub/grub.cfg || true
  elif [ -d /boot/grub2 ]; then
    grub-mkconfig -o /boot/grub2/grub.cfg || true
  fi
elif command -v grub2-mkconfig >/dev/null 2>&1; then
  if [ -d /boot/grub2 ]; then
    grub2-mkconfig -o /boot/grub2/grub.cfg || true
  elif [ -d /boot/grub ]; then
    grub2-mkconfig -o /boot/grub/grub.cfg || true
  fi
fi

# Rebuild initramfs (best-effort)
if command -v update-initramfs >/dev/null 2>&1 && [ -d /etc/initramfs-tools ]; then
  update-initramfs -u || true
elif command -v mkinitcpio >/dev/null 2>&1; then
  mkinitcpio -P || true
elif command -v dracut >/dev/null 2>&1; then
  dracut || true
fi

echo "Rollback finished. Reboot recommended."
EOF

  say "Rollback script written: $path"
}
# Display protocol helpers (X11/Wayland adaptive mode).
xorg_busid_from_bdf() {
  local bdf="$1"
  local bus_hex dev_hex func_dec
  if [[ ! "$bdf" =~ ^[[:xdigit:]]{4}:([[:xdigit:]]{2}):([[:xdigit:]]{2})\.([0-7])$ ]]; then
    return 1
  fi
  bus_hex="${BASH_REMATCH[1]}"
  dev_hex="${BASH_REMATCH[2]}"
  func_dec="${BASH_REMATCH[3]}"
  printf 'PCI:%d:%d:%d' "$((16#$bus_hex))" "$((16#$dev_hex))" "$func_dec"
}

install_xorg_host_gpu_pinning() {
  local host_gpu_bdf="$1"
  local guest_gpu_bdf="$2"
  local host_busid
  host_busid="$(xorg_busid_from_bdf "$host_gpu_bdf" 2>/dev/null || true)"
  [[ -n "$host_busid" ]] || die "Failed to convert host GPU BDF to Xorg BusID: $host_gpu_bdf"

  backup_file "$XORG_HOST_GPU_CONF"
  if (( ! DRY_RUN )); then
    mkdir -p /etc/X11/xorg.conf.d
  fi
  write_file_atomic "$XORG_HOST_GPU_CONF" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Explicit host/guest split for Xorg:
# - Host GPU (Xorg): $host_gpu_bdf
# - Guest GPU (VFIO): $guest_gpu_bdf

Section "ServerLayout"
    Identifier "Layout0"
    Screen 0 "Screen0"
EndSection

Section "Device"
    Identifier "HostGPU"
    BusID "$host_busid"
    Option "PrimaryGPU" "true"
EndSection

Section "Screen"
    Identifier "Screen0"
    Device "HostGPU"
EndSection
EOF
  say "Installed explicit Xorg host-GPU pinning at $XORG_HOST_GPU_CONF"
}

install_lightdm_host_gpu_isolation() {
  local host_gpu_bdf="$1"
  local host_busid
  host_busid="$(xorg_busid_from_bdf "$host_gpu_bdf" 2>/dev/null || true)"
  [[ -n "$host_busid" ]] || die "Failed to convert host GPU BDF to Xorg BusID: $host_gpu_bdf"

  backup_file "$LIGHTDM_HOST_GPU_CONF"
  if (( ! DRY_RUN )); then
    mkdir -p /etc/lightdm/lightdm.conf.d
  fi
  write_file_atomic "$LIGHTDM_HOST_GPU_CONF" 0644 "root:root" <<EOF
# Generated by $SCRIPT_NAME on $(date -Is)
# Keep LightDM/Xorg on host GPU while guest GPU is bound to VFIO.
[Seat:*]
xserver-command=X -core -isolateDevice $host_busid
EOF
  say "Installed LightDM host-GPU isolateDevice override at $LIGHTDM_HOST_GPU_CONF"
}

remove_xorg_host_gpu_pinning() {
  local removed=0
  if [[ -f "$XORG_HOST_GPU_CONF" ]]; then
    backup_file "$XORG_HOST_GPU_CONF"
    run rm -f "$XORG_HOST_GPU_CONF"
    removed=1
  fi
  if [[ -f "$LIGHTDM_HOST_GPU_CONF" ]]; then
    backup_file "$LIGHTDM_HOST_GPU_CONF"
    run rm -f "$LIGHTDM_HOST_GPU_CONF"
    removed=1
  fi
  if (( removed )); then
    note "Removed Xorg/LightDM host-GPU pinning files."
  fi
}

maybe_offer_xorg_explicit_prompt() {
  local host_gpu_bdf="$1"
  local guest_gpu_bdf="$2"
  local selected_mode="${3:-X11}"
  local xorg_status dm
  selected_mode="${selected_mode^^}"
  xorg_status="$(xorg_stack_status)"
  dm="$(detect_display_manager 2>/dev/null || true)"
  [[ -n "$dm" ]] || dm="none"

  if [[ "$selected_mode" != "X11" ]]; then
    note "Skipping explicit Xorg prompt because selected protocol mode is $selected_mode."
    return 0
  fi

  say
  hdr "Xorg explicit prompt (host/guest split)"
  note "Detected Xorg stack status: $(format_tri_state_status "$xorg_status")"
  if [[ "$xorg_status" != "WORKS" ]]; then
    note "Skipping explicit Xorg prompt because Xorg is not fully detected."
    return 0
  fi

  if [[ -z "$host_gpu_bdf" || -z "$guest_gpu_bdf" || "$host_gpu_bdf" == "$guest_gpu_bdf" ]]; then
    note "Skipping explicit Xorg prompt because host/guest GPU mapping is invalid."
    return 0
  fi

  note "Detected Xorg explicitly. You can install host-GPU pinning so Xorg does not select the guest VFIO GPU."
  note "Host GPU: $host_gpu_bdf | Guest GPU: $guest_gpu_bdf"
  if prompt_yn "Detected Xorg explicitly. Install host-GPU Xorg pinning now? (recommended)" Y "Xorg explicit prompt"; then
    install_xorg_host_gpu_pinning "$host_gpu_bdf" "$guest_gpu_bdf"
  else
    note "Skipping explicit Xorg host-GPU pinning."
    return 0
  fi

  if [[ "$dm" == "lightdm" ]]; then
    if prompt_yn "LightDM detected. Install LightDM host-GPU isolateDevice override too?" Y "Xorg explicit prompt"; then
      install_lightdm_host_gpu_isolation "$host_gpu_bdf"
    else
      note "Skipping LightDM isolateDevice override."
    fi
  fi
}
install_prelogin_x11_host_gpu_pinning_failsafe() {
  # Install-time guardrail for black-screen/no-screens failures:
  # when guest GPU is pre-bound to vfio-pci before display-manager startup,
  # X11 greeters can fail unless the host GPU is explicitly pinned.
  #
  # We apply this proactively for:
  # - explicit X11 mode
  # - AUTO mode with X11-prelogin display managers (SDDM/LightDM/LXDM/XDM)
  #
  # This is additive and compatible with the runtime graphics daemon policy.
  local host_gpu_bdf="$1"
  local guest_gpu_bdf="$2"
  local selected_mode="${3:-AUTO}"
  local dm xorg_status should_pin=0

  selected_mode="${selected_mode^^}"
  [[ -n "$host_gpu_bdf" && -n "$guest_gpu_bdf" ]] || return 0
  [[ "$host_gpu_bdf" != "$guest_gpu_bdf" ]] || return 0

  xorg_status="$(xorg_stack_status)"
  if [[ "$xorg_status" != "WORKS" ]]; then
    return 0
  fi

  dm="$(detect_display_manager 2>/dev/null || true)"
  [[ -n "$dm" ]] || dm="none"

  case "$selected_mode" in
    X11)
      should_pin=1
      ;;
    AUTO)
      case "$dm" in
        lightdm|sddm|lxdm|xdm|plasmalogin)
          should_pin=1
          ;;
      esac
      ;;
  esac

  (( should_pin == 1 )) || return 0

  say
  hdr "Prelogin X11 host-GPU failsafe"
  note "Installing persistent host-GPU Xorg pinning to prevent no-screens black-screen failures when the guest GPU is pre-bound to vfio-pci."
  note "Display manager: ${dm} | Graphics mode: ${selected_mode}"
  install_xorg_host_gpu_pinning "$host_gpu_bdf" "$guest_gpu_bdf"
  if [[ "$dm" == "lightdm" ]]; then
    install_lightdm_host_gpu_isolation "$host_gpu_bdf"
  fi
}

install_packages_best_effort() {
  local -a pkgs=("$@")
  local use_sudo=0
  (( ${#pkgs[@]} > 0 )) || return 1

  if [[ "${EUID:-$(id -u)}" -ne 0 ]] && have_cmd sudo; then
    use_sudo=1
  fi

  if have_cmd apt-get; then
    if (( use_sudo )); then
      run sudo apt-get -y install "${pkgs[@]}"
    else
      run apt-get -y install "${pkgs[@]}"
    fi
    return $?
  fi
  if have_cmd dnf; then
    if (( use_sudo )); then
      run sudo dnf -y install "${pkgs[@]}"
    else
      run dnf -y install "${pkgs[@]}"
    fi
    return $?
  fi
  if have_cmd zypper; then
    if (( use_sudo )); then
      run sudo zypper --non-interactive in "${pkgs[@]}"
    else
      run zypper --non-interactive in "${pkgs[@]}"
    fi
    return $?
  fi
  if have_cmd pacman; then
    if (( use_sudo )); then
      run sudo pacman --noconfirm -S "${pkgs[@]}"
    else
      run pacman --noconfirm -S "${pkgs[@]}"
    fi
    return $?
  fi

  return 1
}

protocol_runtime_packages_for_mode() {
  local mode="${1:-}"
  mode="${mode^^}"
  [[ "$mode" == "X11" || "$mode" == "WAYLAND" ]] || return 1

  if have_cmd apt-get; then
    if [[ "$mode" == "X11" ]]; then
      printf '%s\n' xserver-xorg xinit x11-xserver-utils
    else
      printf '%s\n' weston wayland-protocols
    fi
    return 0
  fi
  if have_cmd dnf; then
    if [[ "$mode" == "X11" ]]; then
      printf '%s\n' xorg-x11-server-Xorg xorg-x11-xinit
    else
      printf '%s\n' wayland-protocols weston
    fi
    return 0
  fi
  if have_cmd zypper; then
    if [[ "$mode" == "X11" ]]; then
      printf '%s\n' xorg-x11-server xinit
    else
      printf '%s\n' wayland weston
    fi
    return 0
  fi
  if have_cmd pacman; then
    if [[ "$mode" == "X11" ]]; then
      printf '%s\n' xorg-server xorg-xinit
    else
      printf '%s\n' wayland wayland-protocols weston
    fi
    return 0
  fi

  return 1
}

protocol_stack_status_for_mode() {
  local mode="${1:-}"
  mode="${mode^^}"
  if [[ "$mode" == "X11" ]]; then
    xorg_stack_status
  else
    wayland_stack_status
  fi
}

ensure_graphics_protocol_runtime() {
  local mode="${1:-}"
  mode="${mode^^}"
  [[ "$mode" == "X11" || "$mode" == "WAYLAND" ]] || return 1

  local before after
  before="$(protocol_stack_status_for_mode "$mode")"
  if [[ "$before" == "WORKS" ]]; then
    return 0
  fi

  say
  hdr "Graphics protocol runtime ($mode)"
  note "$mode status before install: $(format_tri_state_status "$before")"

  local -a pkgs=()
  mapfile -t pkgs < <(protocol_runtime_packages_for_mode "$mode" || true)
  if (( ${#pkgs[@]} == 0 )); then
    note "No known package mapping for your package manager. Install $mode runtime manually and re-run."
    return 1
  fi

  note "Suggested packages: ${pkgs[*]}"
  if ! prompt_yn "Install missing $mode runtime packages now?" Y "Graphics protocol runtime"; then
    return 1
  fi

  if ! install_packages_best_effort "${pkgs[@]}"; then
    note "Automatic package installation failed. Install the packages manually and re-run."
    return 1
  fi

  after="$(protocol_stack_status_for_mode "$mode")"
  note "$mode status after install: $(format_tri_state_status "$after")"
  [[ "$after" == "WORKS" ]]
}

select_and_prepare_graphics_protocol_mode() {
  local xorg_status wayland_status support detected_mode selected_mode forced_mode
  xorg_status="$(xorg_stack_status)"
  wayland_status="$(wayland_stack_status)"
  support="$(x11_wayland_support_status "$xorg_status" "$wayland_status")"
  detected_mode="$(x11_wayland_supported_mode "$xorg_status" "$wayland_status")"
  forced_mode="${GRAPHICS_PROTOCOL_OVERRIDE:-}"

  say
  hdr "Graphics protocol auto-detection"
  note "X11 (Xorg): $(format_tri_state_status "$xorg_status")"
  note "Wayland: $(format_tri_state_status "$wayland_status")"
  note "Detected mode availability: $detected_mode"

  if [[ -n "$forced_mode" ]]; then
    selected_mode="$forced_mode"
    note "CLI override applied: --graphics-protocol ${forced_mode,,}"
    case "$selected_mode" in
      X11|WAYLAND)
        if ! ensure_graphics_protocol_runtime "$selected_mode"; then
          die "${selected_mode} mode is required by CLI override but not fully ready. Install/repair ${selected_mode} runtime, then re-run."
        fi
        ;;
      AUTO)
        if [[ "$support" != "WORKS" ]]; then
          die "AUTO mode requested but neither X11 nor Wayland is fully working. Install one runtime stack, then re-run."
        fi
        ;;
    esac
  else
    if [[ "$detected_mode" == "BOTH" ]]; then
      selected_mode="AUTO"
      note "Both X11 and Wayland report WORKS; enabling protocol-agnostic AUTO mode."
      note "No graphics-mode selection is required during install."
    elif [[ "$detected_mode" == "X11" ]]; then
      selected_mode="X11"
      note "Only X11 currently reports WORKS; selecting X11 automatically."
      if ! ensure_graphics_protocol_runtime "$selected_mode"; then
        die "X11 mode is required but not fully ready. Install/repair X11 runtime, then re-run."
      fi
    elif [[ "$detected_mode" == "WAYLAND" ]]; then
      selected_mode="WAYLAND"
      note "Only Wayland currently reports WORKS; selecting Wayland automatically."
      if ! ensure_graphics_protocol_runtime "$selected_mode"; then
        die "Wayland mode is required but not fully ready. Install/repair Wayland runtime, then re-run."
      fi
    else
      # PARTIAL/NONE: no interactive protocol chooser. Try to make one stack
      # ready automatically in a deterministic order.
      if ensure_graphics_protocol_runtime "WAYLAND"; then
        selected_mode="WAYLAND"
        note "Auto-selected Wayland after runtime preparation."
      elif ensure_graphics_protocol_runtime "X11"; then
        selected_mode="X11"
        note "Auto-selected X11 after runtime preparation."
      else
        die "Neither X11 nor Wayland is fully working. Install one runtime stack, then re-run."
      fi
    fi
  fi

  CTX[graphics_protocol_mode]="$selected_mode"
  note "Selected graphics protocol mode: $selected_mode"
  note "VFIO passthrough binding remains persistent and protocol-independent."
  note "Switching between Wayland and X11 later will not require rerunning protocol selection."
}

apply_selected_graphics_protocol_mode() {
  local host_gpu_bdf="$1"
  local guest_gpu_bdf="$2"
  local mode="${CTX[graphics_protocol_mode]:-AUTO}"
  mode="${mode^^}"

  say
  hdr "Graphics protocol activation schedule"
  case "$mode" in
    X11)
      note "X11 mode selected."
      ;;
    WAYLAND)
      note "Wayland mode selected."
      # Ensure next-login/session preference aligns with explicit WAYLAND mode.
      # This writes an additive SDDM config only when supported.
      set_plasma_wayland_default_session
      note "Wayland default-session preference has been refreshed for next login when supported by SDDM."
      ;;
    AUTO)
      note "AUTO mode selected (protocol-agnostic)."
      ;;
    *)
      note "No explicit protocol mode selected; keeping protocol behavior unchanged."
      ;;
  esac
  note "Protocol adaptation is deferred to next boot."
  note "No live Wayland/X11 switching is performed during this install run."
}

iommu_group_preflight() {
  # Hard-gate unsafe IOMMU groups.
  local guest_gpu="$1" guest_audio_csv="$2"

  local group
  group="$(iommu_group_of_bdf "$guest_gpu" 2>/dev/null || true)"
  if [[ -z "$group" ]]; then
    die "No IOMMU group found for $guest_gpu. Is IOMMU enabled in BIOS and kernel params?"
  fi

  say
  say "IOMMU group for guest GPU ($guest_gpu) is: $group"
  say "Devices in group $group:"

  local -a allowed=("$guest_gpu")
  if [[ -n "$guest_audio_csv" ]]; then
    local IFS=','
    for dev in $guest_audio_csv; do
      [[ -n "$dev" ]] || continue
      allowed+=("$dev")
    done
  fi

  local unsafe=0 d
  for d in $(list_iommu_group_devices "$group"); do
    say "  - $d"
    local ok=0 a
    for a in "${allowed[@]}"; do
      if [[ "$d" == "$a" ]]; then ok=1; break; fi
    done
    if (( ! ok )); then
      unsafe=1
    fi
  done

  if (( unsafe )); then
    if ! confirm_phrase "This IOMMU group contains extra devices. Passthrough may be unsafe unless you passthrough *all* of them or have ACS separation." "I UNDERSTAND"; then
      die "Aborted due to unsafe IOMMU group"
    fi
  fi
}

audio_slot_sanity() {
  local host_gpu="$1" host_audio="$2"
  [[ -n "$host_audio" ]] || return 0

  local gpu_slot audio_slot
  gpu_slot="$(pci_slot_of_bdf "$host_gpu")"
  audio_slot="$(pci_slot_of_bdf "$host_audio")"

  if [[ "$gpu_slot" != "$audio_slot" ]]; then
    say "WARN: Selected host audio ($host_audio) is not in the same PCI slot as host GPU ($host_gpu)."
    if ! confirm_phrase "This is often a misconfiguration. Continue anyway?" "I UNDERSTAND"; then
      die "Aborted: host audio does not match host GPU slot"
    fi
  fi
}

remove_user_audio_unit() {
  local user="$1"
  [[ -n "$user" ]] || return 0

  # getent exits non-zero if user does not exist; do not abort reset.
  local home
  home="$(getent passwd "$user" 2>/dev/null | cut -d: -f6 || true)"
  [[ -n "$home" && -d "$home" ]] || return 0

  local unit_path="$home/.config/systemd/user/vfio-set-host-audio.service"
  if [[ -f "$unit_path" ]]; then
    run rm -f "$unit_path"
  fi
}

reset_vfio_all() {
  hdr "RESET / CLEANUP"
  note "This will remove VFIO passthrough settings installed by this script."
  note "It will NOT uninstall libvirt/QEMU, and it will NOT change your VM XMLs."
  note "NOTE: stealth/perf-tuned VM XMLs are NOT reverted by --reset. Use"
  note "      'sudo $SCRIPT_NAME --reset-stealth-vm-tuning' to restore them"
  note "      from their *_stealth_*.xml backups before or after this reset."
  note "      For ultimate-perf (hugepages/iothreads/cputune) revert + host hugepages"
  note "      release + boot-reserve service removal, run:"
  note "      'sudo $SCRIPT_NAME --reset-ultimate-perf-vm-tuning'. (--reset leaves the"
  note "      hugepages boot-reserve service in place so hugepages-backed VMs still"
  note "      start across reboots until you explicitly revert perf.)"

  if ! confirm_phrase "To continue, confirm reset." "RESET VFIO"; then
    die "Reset cancelled"
  fi

  # Disable system services (best-effort)
  if command -v systemctl >/dev/null 2>&1; then
    # Core VFIO bind unit
    run systemctl disable --now vfio-bind-selected-gpu.service 2>/dev/null || true
    # Optional boot log dumper unit
    run systemctl disable --now vfio-dump-boot-log.service 2>/dev/null || true
    # Optional USB Bluetooth disable unit
    run systemctl disable --now vfio-disable-usb-bluetooth.service 2>/dev/null || true
    # Graphics protocol adaptation daemon
    run systemctl disable --now vfio-graphics-protocold.service 2>/dev/null || true
    # Reboot-FLR monitor (dynamic binding only)
    run systemctl disable --now vfio-reboot-flr.service 2>/dev/null || true
    # Park-keepalive monitor (dynamic binding only) + its one-shot check unit
    run systemctl disable --now vfio-gpu-park-keepalive.service 2>/dev/null || true
    run systemctl disable --now vfio-gpu-park-keepalive-check.service 2>/dev/null || true

    # If we previously masked plymouth units as part of "disable splash",
    # unmask them on reset so the system can return to distro defaults.
    # (vBIOS ROM auto-injection has no systemd service of its own; its VM-XML
    # <rom> pins and runtime dir are removed separately below via
    # remove_vbios_romfile, before the CONF_FILE it depends on is deleted.)
    unmask_plymouth_services

    run systemctl daemon-reload 2>/dev/null || true
  fi

  # Remove managed files, including optional helpers
  local bootlog_unit="/etc/systemd/system/vfio-dump-boot-log.service"
  local bootlog_bin
  bootlog_bin="$(bootlog_bin_path)"

  # Remove the vBIOS ROM auto-injection (VM-XML <rom> pins + runtime dir).
  # Must run BEFORE $CONF_FILE is deleted below (it reads GUEST_GPU_BDF from it).
  remove_vbios_romfile
  # Remove the live-attach (hotplug GPU) workflow artifacts. Must run before
  # $CONF_FILE is deleted (it reads VFIO_DYNAMIC_LIVE_ATTACH from it).
  remove_live_attach

  # Libvirt hook cleanup: restore pre-existing user-managed qemu hook or remove our managed entry.
  if [[ -f "$LIBVIRT_HOOK_ENTRY" ]]; then
    local _hook_bak="" _hb
    for _hb in "${LIBVIRT_HOOK_ENTRY}".bak.*; do
      [[ -f "$_hb" ]] || continue
      if [[ -z "$_hook_bak" || "$_hb" -nt "$_hook_bak" ]]; then
        _hook_bak="$_hb"
      fi
    done
    if [[ -n "$_hook_bak" ]]; then
      note "Reset mode: restoring pre-existing libvirt qemu hook from $(basename "$_hook_bak")"
      run cp -a "$_hook_bak" "$LIBVIRT_HOOK_ENTRY"
    else
      run rm -f "$LIBVIRT_HOOK_ENTRY"
    fi
  fi

  run rm -f "$SYSTEMD_UNIT" "$BIND_SCRIPT" "$AUDIO_SCRIPT" \
           "$OPENBOX_MONITOR_SCRIPT" \
           "$LIBVIRT_HOOK_SCRIPT" \
           "$CONF_FILE" "$MODULES_LOAD" "$BLACKLIST_FILE" \
           "$SOFTDEP_FILE" "$DRACUT_VFIO_CONF" \
           "$UDEV_ISOLATION_RULE" \
           "$USB_BT_SCRIPT" "$USB_BT_SYSTEMD_UNIT" "$USB_BT_UDEV_RULE" "$USB_BT_MATCH_CONF" \
           "$GRAPHICS_DAEMON_SCRIPT" "$GRAPHICS_DAEMON_UNIT" \
           "$LIGHTDM_FALLBACK_CONF" "$XORG_HOST_GPU_CONF" "$LIGHTDM_HOST_GPU_CONF" \
           "$KWIN_RENDER_PIN_FILE" "$WLR_RENDER_PIN_FILE" \
           "$REBOOT_FLR_SCRIPT" "$REBOOT_FLR_UNIT" \
           "$PARK_KEEPALIVE_SCRIPT" "$PARK_KEEPALIVE_UNIT" "$PARK_KEEPALIVE_CHECK_UNIT" \
           "$PARK_KEEPALIVE_RESUME_HOOK" "$PARK_KEEPALIVE_UDEV_RULE" "$PARK_KEEPALIVE_STATE_FILE" \
           "$LIVE_ATTACH_HELPER" "$LIVE_ATTACH_GPU_XML" "$LIVE_ATTACH_AUDIO_XML" "$LIVE_ATTACH_VM_LIST" \
           "$bootlog_unit" "$bootlog_bin" 2>/dev/null || true

  remove_openbox_autostart_hook

  if have_cmd udevadm; then
    run udevadm control --reload-rules 2>/dev/null || true
    run udevadm trigger 2>/dev/null || true
  fi

  # Remove user unit for SUDO_USER (and optionally all /home users)
  if [[ -n "${SUDO_USER:-}" ]]; then
    remove_user_audio_unit "$SUDO_USER"
  fi

  note "Reset mode: removing vfio-set-host-audio.service for all users under /home/*."
  local d u
  for d in /home/*; do
    [[ -d "$d" ]] || continue
    u="$(basename "$d")"
    # Some /home entries may not correspond to real user accounts; that's OK.
    remove_user_audio_unit "$u"
  done

  local grub_changed=0
  local opensuse_cmdline_present=0

  # Detect active bootloader so we do not try to "classic GRUB"-reset on
  # systems that actually use systemd-boot/GRUB2-BLS with /etc/kernel/cmdline.
  local reset_bl
  reset_bl="$(detect_bootloader)"

  # Remove GRUB kernel parameters added by this script (classic GRUB only).
  # On GRUB2-BLS/systemd-boot setups, we instead operate on /etc/kernel/cmdline.
  if [[ "$reset_bl" == "grub" && -f /etc/default/grub ]]; then
    note "Reset mode: removing VFIO-related kernel params from /etc/default/grub."
    backup_file /etc/default/grub

    local key current new
    key="$(grub_get_key)" || die "Could not find GRUB_CMDLINE_LINUX(_DEFAULT) in /etc/default/grub"
    current="$(grub_read_cmdline "$key")"
    new="$current"

    # Core IOMMU / ACS params
    new="$(remove_param_all "$new" "amd_iommu=on")"
    new="$(remove_param_all "$new" "intel_iommu=on")"
    new="$(remove_param_all "$new" "iommu=pt")"
    new="$(remove_param_all "$new" "pcie_acs_override=downstream,multifunction")"
    # Optional USB/xHCI stability workarounds
    new="$(remove_param_all "$new" "usbcore.autosuspend=-1")"
    new="$(remove_param_all "$new" "pcie_aspm=off")"
    # Initramfs / VFIO ordering
    new="$(remove_param_all "$new" "rd.driver.pre=vfio-pci")"
    new="$(remove_param_prefix "$new" "vfio-pci.ids=")"
    # LSM knobs we may have added
    new="$(remove_param_all "$new" "selinux=0")"
    new="$(remove_param_all "$new" "apparmor=0")"
    # Boot verbosity and target overrides
    new="$(remove_param_all "$new" "systemd.show_status=1")"
    new="$(remove_param_all "$new" "loglevel=7")"
    new="$(remove_param_all "$new" "rd.plymouth=0")"
    new="$(remove_param_all "$new" "plymouth.enable=0")"
    new="$(remove_param_all "$new" "splash=silent")"
    new="$(remove_param_all "$new" "splash")"
    new="$(remove_param_all "$new" "rhgb")"
    new="$(remove_param_all "$new" "systemd.unit=multi-user.target")"
    # Framebuffer / sysfb related tweaks
    new="$(remove_param_all "$new" "video=efifb:off")"
    new="$(remove_param_all "$new" "video=vesafb:off")"
    new="$(remove_param_all "$new" "initcall_blacklist=sysfb_init")"
    new="$(remove_param_all "$new" "amdgpu.runpm=0")"
    new="$(remove_param_all "$new" "amdgpu.noretry=0")"
    new="$(remove_param_all "$new" "vfio-pci.disable_idle_d3=1")"
    new="$(remove_param_all "$new" "pcie_port_pm=off")"

    if [[ "$(trim "$new")" != "$(trim "$current")" ]]; then
      grub_write_cmdline_in_place "$key" "$new"
      grub_changed=1
    else
      note "No matching VFIO/IOMMU-related params found in GRUB cmdline; leaving it unchanged."
    fi
  fi

  # On openSUSE-like systems using systemd-boot/sdbootutil, also offer to
  # remove VFIO/IOMMU params from /etc/kernel/cmdline so future kernel
  # entries stop inheriting them. This path is also used for GRUB2-BLS.
  if is_opensuse_like && [[ -f /etc/kernel/cmdline ]]; then
    opensuse_cmdline_present=1
    note "Reset mode: removing VFIO-related kernel params from /etc/kernel/cmdline."
    backup_file /etc/kernel/cmdline
    local kcur knew
    kcur="$(cat /etc/kernel/cmdline 2>/dev/null || true)"
    knew="$kcur"
    # Core IOMMU / ACS params
    knew="$(remove_param_all "$knew" "amd_iommu=on")"
    knew="$(remove_param_all "$knew" "intel_iommu=on")"
    knew="$(remove_param_all "$knew" "iommu=pt")"
    knew="$(remove_param_all "$knew" "pcie_acs_override=downstream,multifunction")"
    # Optional USB/xHCI stability workarounds
    knew="$(remove_param_all "$knew" "usbcore.autosuspend=-1")"
    knew="$(remove_param_all "$knew" "pcie_aspm=off")"
    # Initramfs / VFIO ordering
    knew="$(remove_param_all "$knew" "rd.driver.pre=vfio-pci")"
    knew="$(remove_param_prefix "$knew" "vfio-pci.ids=")"
    # LSM knobs we may have added
    knew="$(remove_param_all "$knew" "selinux=0")"
    knew="$(remove_param_all "$knew" "apparmor=0")"
    # Boot verbosity and target overrides
    knew="$(remove_param_all "$knew" "systemd.show_status=1")"
    knew="$(remove_param_all "$knew" "loglevel=7")"
    knew="$(remove_param_all "$knew" "rd.plymouth=0")"
    knew="$(remove_param_all "$knew" "plymouth.enable=0")"
    knew="$(remove_param_all "$knew" "splash=silent")"
    knew="$(remove_param_all "$knew" "splash")"
    knew="$(remove_param_all "$knew" "rhgb")"
    knew="$(remove_param_all "$knew" "systemd.unit=multi-user.target")"
    # Framebuffer / sysfb related tweaks
    knew="$(remove_param_all "$knew" "video=efifb:off")"
    knew="$(remove_param_all "$knew" "video=vesafb:off")"
    knew="$(remove_param_all "$knew" "initcall_blacklist=sysfb_init")"
    knew="$(remove_param_all "$knew" "amdgpu.runpm=0")"
    knew="$(remove_param_all "$knew" "amdgpu.noretry=0")"
    knew="$(remove_param_all "$knew" "vfio-pci.disable_idle_d3=1")"
    knew="$(remove_param_all "$knew" "pcie_port_pm=off")"
    if ! cmdline_get_key_value_token "$knew" "root" >/dev/null 2>&1; then
      local reset_recovered_opts reset_recovered_cmdline reset_recovered_root_tok
      reset_recovered_opts="$(bls_find_boot_metadata_options 2>/dev/null || true)"
      if [[ -n "$reset_recovered_opts" ]]; then
        reset_recovered_cmdline="$(cmdline_add_boot_metadata_tokens_from_options "$knew" "$reset_recovered_opts")"
        reset_recovered_root_tok="$(cmdline_get_key_value_token "$reset_recovered_cmdline" "root" 2>/dev/null || true)"
        if [[ -n "$reset_recovered_root_tok" ]]; then
          knew="$reset_recovered_cmdline"
          note "Reset mode safety: restored missing root boot metadata in /etc/kernel/cmdline."
        fi
      fi
    fi

    if ! cmdline_get_key_value_token "$knew" "root" >/dev/null 2>&1; then
      note "Reset mode safety: refusing to write /etc/kernel/cmdline without root=... token."
      note "Leaving existing /etc/kernel/cmdline unchanged."
    elif [[ "$(trim "$knew")" != "$(trim "$kcur")" ]]; then
      if (( ! DRY_RUN )); then
        printf '%s\n' "$knew" >/etc/kernel/cmdline
      fi
    else
      note "No matching VFIO/IOMMU-related params found in /etc/kernel/cmdline; leaving it unchanged."
    fi
  fi

  # Always refresh openSUSE BLS entries during reset (even when /etc/kernel/cmdline
  # did not change) so stale entry options are reconciled immediately.
  if (( opensuse_cmdline_present )); then
    note "Reset mode: refreshing Boot Loader Spec entries on openSUSE."
    opensuse_sdbootutil_update_all_entries
  fi

  # Always regenerate GRUB config if we changed /etc/default/grub.
  if (( grub_changed )); then
    if command -v update-grub >/dev/null 2>&1; then
      say "Updating GRUB config via update-grub..."
      run update-grub
    elif command -v grub-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      elif [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      else
        out=""
      fi
      if [[ -n "$out" ]]; then
        run grub-mkconfig -o "$out" || true
      fi
    elif command -v grub2-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      elif [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      else
        out=""
      fi
      if [[ -n "$out" ]]; then
        run grub2-mkconfig -o "$out" || true
      fi
    fi

    # After regenerating grub.cfg, run a best-effort syntax check. If GRUB
    # reports a syntax error, we automatically roll back /etc/default/grub
    # to the backup from this run (if present) and regenerate grub.cfg a
    # second time so the user does not get stuck with a broken boot menu.
    if ! maybe_check_grub_cfg; then
      local bak="/etc/default/grub.bak.${RUN_TS}"
      if [[ -f "$bak" ]]; then
        note "GRUB syntax check failed; restoring previous /etc/default/grub from $bak and regenerating grub.cfg."
        cp -a "$bak" /etc/default/grub || true
        if command -v update-grub >/dev/null 2>&1; then
          say "Re-running update-grub after restoring backup..."
          run update-grub || true
        elif command -v grub-mkconfig >/dev/null 2>&1; then
          local out2=""
          if [[ -d /boot/grub ]]; then
            out2=/boot/grub/grub.cfg
          elif [[ -d /boot/grub2 ]]; then
            out2=/boot/grub2/grub.cfg
          fi
          [[ -n "$out2" ]] && { say "Re-running grub-mkconfig -o $out2 after restoring backup..."; run grub-mkconfig -o "$out2" || true; }
        elif command -v grub2-mkconfig >/dev/null 2>&1; then
          local out3=""
          if [[ -d /boot/grub2 ]]; then
            out3=/boot/grub2/grub.cfg
          elif [[ -d /boot/grub ]]; then
            out3=/boot/grub/grub.cfg
          fi
          [[ -n "$out3" ]] && { say "Re-running grub2-mkconfig -o $out3 after restoring backup..."; run grub2-mkconfig -o "$out3" || true; }
        fi
      else
        note "GRUB syntax check failed but no backup /etc/default/grub.bak.${RUN_TS} was found; please review /etc/default/grub manually."
      fi
    fi
  fi

  # Always rebuild initramfs at end of reset (so removed blacklists/modules are fully gone on next boot).
  say
  say "Rebuilding initramfs (recommended after reset)..."
  maybe_update_initramfs

  say
  say "Reset complete. Reboot recommended."
  note "If any devices are currently bound to vfio-pci, a reboot is the cleanest way to restore host drivers."
  note "This removed VFIO config only. To also remove the self-installed vfio.sh + shell completions, run: sudo $SCRIPT_NAME --uninstall-self"

  # Snapshot-aware hint for openSUSE/Btrfs users: each snapshot has its own
  # /etc/kernel/cmdline. If you later roll back to an older snapshot that
  # still contains VFIO-related kernel params, you should run this reset
  # helper again from within that snapshot if you also want it cleaned.
  if is_opensuse_like && [[ -d /.snapshots ]]; then
    note "On Btrfs snapshots, each snapshot keeps its own /etc/kernel/cmdline."
    note "If you roll back to an older snapshot later, run 'sudo sh vfio.sh --reset' again inside that snapshot to clean its VFIO kernel params too."
  fi
}
reset_usb_mitigation_only() {
  hdr "RESET USB MITIGATION"
  note "This will remove USB mitigation artifacts installed by this script:"
  note "  - USB Bluetooth host-detach helper/service/rule"
  note "  - USB mitigation match-policy config (including USB Ethernet EEE-off settings)"
  note "It does NOT remove core VFIO GPU passthrough configuration."

  if ! confirm_phrase "To continue, confirm USB mitigation reset." "RESET USB MITIGATION"; then
    die "USB mitigation reset cancelled"
  fi

  if command -v systemctl >/dev/null 2>&1; then
    run systemctl disable --now vfio-disable-usb-bluetooth.service 2>/dev/null || true
    run systemctl daemon-reload 2>/dev/null || true
  fi

  run rm -f "$USB_BT_SCRIPT" "$USB_BT_SYSTEMD_UNIT" "$USB_BT_UDEV_RULE" "$USB_BT_MATCH_CONF" "$USB_BT_STATE_FILE" 2>/dev/null || true
  if have_cmd udevadm; then
    run udevadm control --reload-rules 2>/dev/null || true
    run udevadm trigger --subsystem-match=usb 2>/dev/null || true
  fi
  say "USB mitigation reset complete."
}

preflight_existing_config_gate() {
  # If we detect existing VFIO configuration, leftover kernel params, or active vfio bindings, offer reset.
  local detected=0

  if readable_file "$CONF_FILE" || readable_file "$SYSTEMD_UNIT" || readable_file "$MODULES_LOAD" || readable_file "$BLACKLIST_FILE"; then
    detected=1
  fi

  # Leftover kernel parameters are also "existing config".
  if grub_has_vfio_params; then
    detected=1
  fi

  if command -v lspci >/dev/null 2>&1; then
    if lspci -Dnnk | grep -q "Kernel driver in use: vfio-pci"; then
      detected=1
    fi
  fi

  if (( detected )); then
    detect_existing_vfio_report

    local hc status
    hc="$(vfio_config_health)"
    status="$(printf '%s\n' "$hc" | awk -F= '/^STATUS=/{print $2; exit}')"

    # UX goal: offer RESET first, but default should be "No" so user can keep going.
    say
    if [[ "$status" == "BAD" ]]; then
      hdr "WARNING"
      note "A BAD VFIO configuration was detected. Reset is recommended."
      if prompt_yn "Reset / cleanup VFIO settings now?" N "Existing VFIO config"; then
        reset_vfio_all
        exit 0
      fi

      # If user refuses reset, require explicit acknowledgement.
      if ! confirm_phrase "Continuing with a BAD config can break boot, graphics, or audio." "I UNDERSTAND"; then
        die "Aborted"
      fi
    else
      # OK/WARN: offer reset, default no, then proceed.
      if prompt_yn "Existing VFIO config detected. Do you want to RESET it before continuing?" N "Existing VFIO config"; then
        reset_vfio_all
        exit 0
      fi
      # Default is to continue to next step with no extra prompts.
      note "Continuing with existing config. (You can run: sudo bash vfio.sh --reset)"
    fi
  fi

  # No live config here. If a prior run left a conf backup (e.g. after --reset
  # removed the live conf, or a fresh repo clone onto a host that had VFIO
  # before), offer to restore the SAME config instead of re-running the wizard.
  maybe_pickup_leftover_conf
}

detect_system() {
  # Detect and record core environment capabilities into CTX.
  CTX[bootloader]="$(detect_bootloader)"

  # For install mode, require IOMMU to be active before continuing.
  iommu_enabled_or_die

  # Early, kernel-wide VFIO risk audit. At this point we do not yet know
  # which GPU will be the guest, so we only run the generic checks (no
  # BDF argument). Later, after GPU selection, we run a targeted audit
  # again for the chosen guest GPU.
  #
  # IMPORTANT: audit_vfio_health returns non-zero for WARN/FAIL, but we
  # treat this as informational here. The hard gate happens later in
  # apply_configuration().
  audit_vfio_health "" || true

  say
  hdr "Environment support"
  note "Init system: systemd (required; other init systems are NOT supported by this helper)."
  note "Boot loader detected: ${CTX[bootloader]}"
  if [[ "${CTX[bootloader]}" == "grub" || "${CTX[bootloader]}" == "systemd-boot" || "${CTX[bootloader]}" == "grub2-bls" ]]; then
    note "Automatic kernel parameter editing is available for ${CTX[bootloader]}."
  else
    note "Automatic kernel parameter editing is ONLY implemented for GRUB and systemd-boot. For ${CTX[bootloader]}, you must apply kernel parameters manually when prompted."
  fi


  # Early detection of existing passthrough config (before user makes changes).
  preflight_existing_config_gate
}

user_selection() {
  say
  hdr "VFIO GPU Passthrough Setup (multi-vendor)"
  note "This wizard will ask you to choose: (1) Guest GPU to passthrough, (2) Host audio device to KEEP on the host."
  note "Anything you choose for the GUEST will be bound to vfio-pci (passthrough). Anything you choose for the HOST stays on host drivers."
  if (( DRY_RUN )); then
    say "- DRY RUN: no files/commands will be applied"
  fi
  if (( DEBUG )); then
    say "- DEBUG enabled"
  fi
  say

  # Discover GPUs (via sysfs; lspci is only used for human-readable descriptions)
  local -a gpu_bdfs=() gpu_descs=() gpu_vendor_ids=() gpu_audio_bdfs_csv=() gpu_audio_descs=()
  local gpu_bdf gpu_desc vendor_id device_id_unused audio_csv audio_descs
  while IFS=$'\t' read -r gpu_bdf gpu_desc vendor_id device_id_unused audio_csv audio_descs; do
    [[ -n "${gpu_bdf:-}" ]] || continue
    : "${device_id_unused:-}"
    gpu_bdfs+=("$gpu_bdf")
    gpu_descs+=("$gpu_desc")
    gpu_vendor_ids+=("$vendor_id")
    gpu_audio_bdfs_csv+=("$audio_csv")
    gpu_audio_descs+=("$audio_descs")
  done < <(gpu_discover_all_sysfs)

  if (( ${#gpu_bdfs[@]} < 2 )); then
    die "Found fewer than 2 GPUs. This script assumes a host GPU + guest GPU."
  fi

  # Sanity: all discovered BDFs must exist.
  for gpu_bdf in "${gpu_bdfs[@]}"; do
    assert_pci_bdf_exists "$gpu_bdf"
  done

  local -a options=()
  local i
  for i in "${!gpu_bdfs[@]}"; do
    local bdf slot vend short
    bdf="${gpu_bdfs[$i]}"
    slot="$(pci_slot_of_bdf "$bdf")"
    vend="$(vendor_label "${gpu_vendor_ids[$i]}")"
    short="$(short_gpu_desc "${gpu_descs[$i]}")"
    options+=("GPU: $bdf  |  Vendor: ${vend}"$'\n'"      Model: ${short}"$'\n'"      PCI slot: ${slot}")
  done

  local guest_idx host_idx
  hdr "Step 1/4: Select GUEST GPU (will be passed through)"
  guest_idx="$(select_from_list "Which GPU should be the GUEST (vfio-pci / passthrough)?" "GPU selection" "${options[@]}")"

  if (( ${#gpu_bdfs[@]} == 2 )); then
    if (( guest_idx == 0 )); then host_idx=1; else host_idx=0; fi
  else
    host_idx="$(select_from_list "Select the GPU to use for HOST display:" "Host GPU selection" "${options[@]}")"
    (( host_idx != guest_idx )) || die "Host GPU and guest GPU cannot be the same."
  fi

  CTX[guest_gpu]="${gpu_bdfs[$guest_idx]}"
  CTX[host_gpu]="${gpu_bdfs[$host_idx]}"
  CTX[guest_vendor]="${gpu_vendor_ids[$guest_idx]}"

  # Resizable BAR status for the selected guest GPU. This is informational
  # but we make it explicit because on some platforms ReBAR being enabled
  # or disabled can be the difference between a black screen and a working
  # guest. The behavior is hardware/firmware specific, so we do NOT force
  # any particular state here.
  #
  # IMPORTANT: For GPU passthrough the **mandatory** BIOS setting is usually
  # "Above 4G Decoding" / "64-bit BAR support" being enabled, so that large
  # PCI BARs can be mapped into the guest address space. ReBAR on top of
  # that is optional/experimental: on some machines it must be ON, on
  # others it must be OFF to avoid black screens once the vendor driver
  # loads inside the VM.
  if rebar_enabled_for_bdf "${CTX[guest_gpu]}"; then
    say
    hdr "Resizable BAR (ReBAR) detected for guest GPU"
    note "lspci reports Resizable BAR as ENABLED for the selected guest GPU (${CTX[guest_gpu]})."
    note "Make sure your BIOS has 'Above 4G Decoding' (sometimes called 'Large BAR' or '64-bit BAR') ENABLED for GPU passthrough; that is the requirement for mapping big BARs into the VM."
    note "ReBAR itself is hardware/firmware specific: on some platforms enabling it fixes black screens, on others you must disable it for the VM to stay stable once the AMD/NVIDIA driver loads."
    note "If you later see black screens or no firmware logo in the guest, one of the first things to try is toggling ReBAR for this GPU in BIOS/UEFI (ON vs OFF) and retesting, with Above 4G Decoding kept enabled."
    if ! confirm_phrase "I understand that ReBAR is optional/experimental and I may need to experiment with it if problems appear." "I UNDERSTAND"; then
      die "Aborted at user request while acknowledging ReBAR status for the guest GPU."
    fi
  fi

  # Track the exact vendor:device ID for the selected guest GPU so we can
  # expose a matching vfio-pci.ids= parameter in the kernel cmdline. This
  # makes sure vfio-pci claims the card as early as possible (initramfs),
  # which is required on some systems (including openSUSE+dracut) to avoid
  # races with amdgpu/nvidia/i915.
  local _guest_vid _guest_did
  _guest_vid="$(sysfs_read "${CTX[guest_gpu]}" vendor)"
  _guest_did="$(sysfs_read "${CTX[guest_gpu]}" device)"
  if [[ -n "$_guest_vid" && -n "$_guest_did" ]]; then
    CTX[guest_vfio_ids]="${_guest_vid}:${_guest_did}"
  fi

  local guest_desc host_desc
  guest_desc="${gpu_descs[$guest_idx]}"
  host_desc="${gpu_descs[$host_idx]}"

  say
  hdr "Selection summary so far"
  say "Host GPU (stays on host):"
  say "  ${CTX[host_gpu]}"
  note "  $(short_gpu_desc "$host_desc")"
  say "Guest GPU (passthrough / vfio-pci):"
  say "  ${CTX[guest_gpu]}"
  note "  $(short_gpu_desc "$guest_desc")"

  assert_not_equal "${CTX[guest_gpu]}" "${CTX[host_gpu]}" "Host GPU and guest GPU are the same (refusing)."
  assert_pci_bdf_exists "${CTX[guest_gpu]}"
  assert_pci_bdf_exists "${CTX[host_gpu]}"

  # Guest audio selection (default: audio functions in the same PCI slot)
  local guest_audio_csv="${gpu_audio_bdfs_csv[$guest_idx]}"
  if [[ -n "$guest_audio_csv" ]]; then
    say
    hdr "Step 2/4: Guest GPU HDMI/DP Audio (strongly recommended)"
    say "Guest GPU: ${CTX[guest_gpu]}"
    note "$(short_gpu_desc "$guest_desc")"
    say "Detected HDMI/DP audio PCI function(s) for this GPU: $guest_audio_csv"
    note "On many systems (including openSUSE Tumbleweed), it is safest to passthrough BOTH the GPU video (..0) and its HDMI/DP audio (..1)."
    note "Leaving the HDMI/DP audio on the host while the GPU is passed through can confuse PipeWire/PulseAudio and cause desktop hangs when the VM starts."
    note "Only skip this if you are sure you do NOT want the GPU's HDMI/DP audio in the guest and understand the risks."

    if ! prompt_yn "Also passthrough HDMI/DP AUDIO for the guest GPU? (recommended)" Y "Guest HDMI/DP audio"; then
      guest_audio_csv=""
    fi
  else
    say
    hdr "Step 2/4: Guest GPU HDMI/DP Audio"
    note "No HDMI/DP audio device found in the same PCI slot as the selected guest GPU (${CTX[guest_gpu]})."
  fi

  # Preflight: detect if the selected guest GPU looks in-use by the host.
  gpu_in_use_preflight "${CTX[guest_gpu]}"

  # Preflight: IOMMU group gate.
  iommu_group_preflight "${CTX[guest_gpu]}" "$guest_audio_csv"

  # Check for AMD Reset Bug mitigation (vendor-reset)
  if [[ "${CTX[guest_vendor],,}" == "1002" ]]; then
    say
    hdr "AMD Reset Bug Check"
    if amd_reset_issue_signatures_present_for_bdf "${CTX[guest_gpu]}"; then
      if [[ -d /sys/module/vendor_reset ]]; then
        say "OK: 'vendor-reset' module is loaded."
        if ! grep -q "vendor-reset" "$MODULES_LOAD" 2>/dev/null; then
          say "Adding vendor-reset to $MODULES_LOAD so it loads at boot..."
          if (( ! DRY_RUN )); then
            printf '%s\n' "vendor-reset" >>"$MODULES_LOAD"
          fi
        fi
      else
        say "${C_YELLOW}WARN: Reset-failure markers were detected for this AMD GPU, but 'vendor-reset' is not loaded.${C_RESET}"
        note "This indicates a real reset issue path (FLR/D3/timeout) where vendor-reset may help."
        note "Recommended: install the 'vendor-reset' kernel module (see vendor-reset project docs) after this script finishes."
      fi
    else
      say "INFO: No reset-failure markers detected for the selected AMD GPU in recent kernel logs."
      note "vendor-reset is not recommended by default unless reset failures are observed."
    fi
  fi

  # Host audio selection (important when AMD HDMI audio IDs repeat, e.g. 1002:ab28)
  local host_audio_bdfs_csv="${gpu_audio_bdfs_csv[$host_idx]}"

  # If the user chose NOT to passthrough any guest HDMI/DP audio, we skip the
  # host audio binding wizard entirely to avoid extra questions. In that
  # scenario the script will not try to manage host audio PCI devices at all.
  if [[ -n "$guest_audio_csv" ]]; then
    say
    hdr "Step 3/4: Select HOST audio device (must stay on host)"
    say "Host GPU is: ${CTX[host_gpu]}"
    note "$(short_gpu_desc "$host_desc")"
    note "Pick the AUDIO device that should KEEP working on the host (for your desktop sound)."
    note "Tip: for HDMI sound from the host GPU, pick the audio device in the SAME PCI slot as the host GPU."
    note "This avoids the common AMD issue where both HDMI audio devices share the same ID (1002:ab28)."

    local host_slot
    host_slot="$(pci_slot_of_bdf "${CTX[host_gpu]}")"

    local -a aud_opts=() aud_bdfs=()
    local abdf adesc avendor adev
    while IFS=$'\t' read -r abdf adesc avendor adev; do
      local aslot atype vend rec_tag
      aslot="$(pci_slot_of_bdf "$abdf")"
      atype="$(short_audio_desc "$adesc")"
      vend="$(vendor_label "$avendor")"

      rec_tag=""
      if [[ "$aslot" == "$host_slot" ]]; then
        rec_tag="${C_BOLD}${C_GREEN}[RECOMMENDED for host GPU]${C_RESET} "
        (( ! ENABLE_COLOR )) && rec_tag="[RECOMMENDED for host GPU] "
      fi

      aud_bdfs+=("$abdf")
      aud_opts+=("${rec_tag}Audio: $abdf  |  Type: ${atype}  |  Vendor: ${vend}"$'\n'"      PCI slot: ${aslot}  |  IDs: ${avendor}:${adev}"$'\n'"      lspci: $(short_gpu_desc "$adesc")")
    done < <(audio_devices_discover_all)

    if (( ${#aud_bdfs[@]} > 0 )); then
      local host_audio_idx
      host_audio_idx="$(select_from_list "Which AUDIO device should stay on the HOST?" "Host audio selection" "${aud_opts[@]}")"
      host_audio_bdfs_csv="${aud_bdfs[$host_audio_idx]}"
      [[ -n "$host_audio_bdfs_csv" ]] && assert_pci_bdf_exists "$host_audio_bdfs_csv"
    else
      say "WARN: No PCI audio devices found via lspci."
      host_audio_bdfs_csv=""
    fi

    # Hard safety: host audio must never equal guest GPU.
    if [[ -n "$host_audio_bdfs_csv" ]]; then
      assert_not_equal "$host_audio_bdfs_csv" "${CTX[guest_gpu]}" "Selected host audio equals guest GPU BDF (refusing)."
    fi

    # Slot sanity: host audio should match host GPU slot unless explicitly overridden.
    audio_slot_sanity "${CTX[host_gpu]}" "$host_audio_bdfs_csv"
  else
    say
    hdr "Step 3/4: Host audio binding"
    note "You chose not to passthrough any HDMI/DP audio for the guest. Skipping host audio PCI binding wizard."
    host_audio_bdfs_csv=""
  fi

  # PipeWire default sink selection (user-session)
  local host_audio_node_name=""
  if command -v wpctl >/dev/null 2>&1; then
    # KDE Plasma users usually manage outputs via the Plasma volume applet. For
    # them we default this to NO so it behaves like an advanced helper instead
    # of a mandatory extra question.
    local sink_prompt_def="Y"
    if [[ "${XDG_CURRENT_DESKTOP:-}" =~ KDE|Plasma|PLASMA ]]; then
      sink_prompt_def="N"
    fi

    if prompt_yn "Do you want to select the DEFAULT AUDIO SINK for the host user session (KDE Plasma / PipeWire / WirePlumber)?" "$sink_prompt_def" "Host audio output"; then
      note "(Tip: this only changes your desktop's default output device in PipeWire; it does NOT affect VFIO binding or the VM.)"
      local -a sink_opts=() sink_node_names=()

      # Prefer sinks that match the selected host audio PCI device.
      if [[ -n "$host_audio_bdfs_csv" ]]; then
        note "Recommended: pick the sink that uses the HOST audio PCI device ($host_audio_bdfs_csv)."
        while IFS=$'\t' read -r sname slabel; do
          sink_node_names+=("$sname")
          if (( ENABLE_COLOR )); then
            sink_opts+=("${C_BOLD}${C_GREEN}[RECOMMENDED: host audio]${C_RESET} $sname  ::  $slabel")
          else
            sink_opts+=("[RECOMMENDED: host audio] $sname  ::  $slabel")
          fi
        done < <(pipewire_sinks_for_pci_bdf "$host_audio_bdfs_csv" 2>/dev/null || true)
      fi

      # Add the rest.
      local sid sname slabel
      while IFS=$'\t' read -r sid sname slabel; do
        # Avoid duplicates.
        local seen=0
        local existing
        for existing in "${sink_node_names[@]}"; do
          [[ "$existing" == "$sname" ]] && { seen=1; break; }
        done
        (( seen )) && continue

        sink_node_names+=("$sname")
        sink_opts+=("$sname  ::  $slabel")
      done < <(pipewire_sinks_discover || true)

      if (( ${#sink_node_names[@]} > 0 )); then
        local sink_idx
        hdr "Step 4/4: Choose default HOST audio output (PipeWire)"
        note "This only sets your desktop's default sound output after login."
        note "It does NOT change what gets passed through to the VM."
        sink_idx="$(select_from_list "Which host audio OUTPUT should be default?" "Host audio output selection" "${sink_opts[@]}")"
        host_audio_node_name="${sink_node_names[$sink_idx]}"
      else
        note "Could not enumerate PipeWire sinks (common if PipeWire isn't running for that user yet). Skipping."
      fi
    fi
  fi

  CTX[guest_audio_csv]="$guest_audio_csv"
  CTX[host_audio_bdfs_csv]="$host_audio_bdfs_csv"
  CTX[host_audio_node_name]="$host_audio_node_name"
}

apply_configuration() {
  local guest_gpu="${CTX[guest_gpu]}"
  local host_gpu="${CTX[host_gpu]}"
  local guest_vendor="${CTX[guest_vendor]}"
  local guest_audio_csv="${CTX[guest_audio_csv]}"
  local host_audio_bdfs_csv="${CTX[host_audio_bdfs_csv]}"
  local host_audio_node_name="${CTX[host_audio_node_name]}"
  local boot_vga_policy_mode="${BOOT_VGA_POLICY_OVERRIDE:-AUTO}"
  boot_vga_policy_mode="${boot_vga_policy_mode^^}"
  case "$boot_vga_policy_mode" in
    AUTO|STRICT) ;;
    *) boot_vga_policy_mode="AUTO" ;;
  esac

  # Track whether we actually installed a dracut config for vfio modules
  # and whether we added rd.driver.pre=vfio-pci to the kernel cmdline.
  CTX[dracut_vfio]=0
  CTX[rd_driver_pre]=0

  say
  say "Summary:"
  say "  Host GPU:   $host_gpu"
  say "  Guest GPU:  $guest_gpu (vendor: $(vendor_name "$guest_vendor"))"
  say "  Host audio PCI:  ${host_audio_bdfs_csv:-<none>}"
  say "  Guest audio PCI: ${guest_audio_csv:-<none>}"
  say "  Host default sink node.name: ${host_audio_node_name:-<not set>}"
  say "  Boot-VGA host-assisted policy: ${boot_vga_policy_mode}"
  if [[ -n "${BOOT_VGA_POLICY_OVERRIDE:-}" ]]; then
    note "CLI override applied: --boot-vga-policy ${BOOT_VGA_POLICY_OVERRIDE,,}"
  fi
  if [[ "${XDG_CURRENT_DESKTOP:-}" =~ KDE|Plasma|PLASMA ]]; then
    note "Desktop session: KDE Plasma detected; these settings are tuned for Plasma + Wayland + PipeWire."
  fi
  # Targeted VFIO kernel audit for the selected guest GPU before we write
  # any configuration. If the kernel looks hostile (CTX[kernel_vfio_risk]=1),
  # we warn loudly and require explicit confirmation to continue.
  #
  # IMPORTANT: ignore the function's exit status here so that set -e does
  # not abort before we can show the warning and ask for confirmation.
  say
  audit_vfio_health "$guest_gpu" || true
  if [[ "${CTX[kernel_vfio_risk]:-0}" == "1" ]]; then
    say
    hdr "Kernel appears hostile to VFIO (proceed with caution)"
    note "The checks above indicate that this running kernel is likely affected by a VFIO/simpledrm regression or similar issue."
    note "Recommended: switch to a known-good kernel (for example the distribution's long-term kernel) before relying on this configuration."
    if ! confirm_phrase "Continuing on a hostile kernel can lead to black screens or failed passthrough even with correct settings." "I UNDERSTAND"; then
      die "Aborted due to high-risk kernel for VFIO. Boot a safer kernel (e.g. longterm) and re-run this helper."
    fi
  fi

  say

  hdr "Apply changes"
  note "If you continue, this script will install the core VFIO binding setup:" 
  note "  - Write $CONF_FILE (your selected PCI BDFs)"
  note "  - Write $MODULES_LOAD (load vfio modules at boot)"
  note "  - Write $BIND_SCRIPT (bind ONLY the selected guest BDF(s) to vfio-pci)"
  note "  - Write + enable $SYSTEMD_UNIT (runs the bind script early at boot)"
  note "On dracut-based systems (including openSUSE), it will also install a VFIO dracut config so rd.driver.pre=vfio-pci cannot cause a boot hang."
  note "It will then ASK about remaining optional steps (GRUB/IOMMU, ACS override, host audio unit, udev isolation, etc.)."
  note "On KDE Plasma systems, it can also (optionally) set Plasma Wayland as the default SDDM session to better match these settings."
  note "Important: The VFIO binding will fully take effect AFTER a reboot."

  prompt_yn "Apply these changes now?" N "Apply VFIO configuration" || die "Aborted by user"

  # Preflight sanity checks before writing anything.
  assert_pci_bdf_exists "$host_gpu"
  assert_pci_bdf_exists "$guest_gpu"
  if [[ -n "$host_audio_bdfs_csv" ]]; then
    assert_pci_bdf_exists "$host_audio_bdfs_csv"
  fi

  # Display-manager guardrail:
  # - LightDM: enforce AccountsService/fallback check
  # - SDDM/GDM/LXDM/XDM: recognized and treated as supported
  display_manager_dependency_preflight
  # Graphics protocol guardrail:
  # This helper supports only X11(Xorg)/Wayland and requires at least
  # one stack in WORKS state before installation proceeds.
  graphics_protocol_preflight
  select_and_prepare_graphics_protocol_mode
  local graphics_protocol_mode="${CTX[graphics_protocol_mode]:-AUTO}"
  local graphics_daemon_interval="${GRAPHICS_DAEMON_INTERVAL_OVERRIDE:-$GRAPHICS_DAEMON_INTERVAL_DEFAULT}"
  if [[ "$graphics_protocol_mode" == "AUTO" ]]; then
    say "  Graphics protocol: AUTO (X11 + Wayland compatible, no manual mode selection)"
  else
    say "  Graphics protocol: $graphics_protocol_mode (auto-detected)"
  fi
  if [[ -n "${GRAPHICS_PROTOCOL_OVERRIDE:-}" ]]; then
    note "Graphics protocol override in effect: --graphics-protocol ${GRAPHICS_PROTOCOL_OVERRIDE,,}"
  fi
  if (( INSTALL_GRAPHICS_DAEMON == 0 )); then
    note "CLI override applied: --no-graphics-daemon (independent graphics daemon will not be installed)."
  elif [[ -n "${GRAPHICS_DAEMON_INTERVAL_OVERRIDE:-}" ]]; then
    note "CLI override in effect: --graphics-daemon-interval ${graphics_daemon_interval}s"
  fi

  # Self-heal legacy user audio units that were created before the
  # ConditionPathExists guard was introduced.
  auto_repair_legacy_user_audio_unit_guards

  # Optional: if running under KDE Plasma, offer to set Plasma Wayland as the
  # default login session for SDDM so the desktop matches these VFIO-friendly
  # settings (PipeWire, Wayland, etc.).
  if [[ "${XDG_CURRENT_DESKTOP:-}" =~ KDE|Plasma|PLASMA ]]; then
    say
    hdr "KDE Plasma session integration"
    note "KDE Plasma detected. Using Plasma Wayland as the default login session usually works best with modern PipeWire + VFIO setups."
    if prompt_yn "Set KDE Plasma Wayland as the DEFAULT SDDM login session?" N "KDE Plasma session"; then
      set_plasma_wayland_default_session
    fi
  fi
  local openbox_runtime_status
  openbox_runtime_status="$(openbox_stack_status)"
  if [[ "$openbox_runtime_status" == "WORKS" || -d /etc/xdg/openbox ]]; then
    say
    hdr "Openbox monitor activation"
    note "Openbox integration can auto-detect connected monitors and activate all of them at session startup."
    note "This installs $OPENBOX_MONITOR_SCRIPT and additively updates $OPENBOX_AUTOSTART_FILE."
    if prompt_yn "Install/refresh Openbox auto-activate-all-monitors helper?" Y "Openbox monitor activation"; then
      install_openbox_monitor_activation
    else
      note "Skipping Openbox monitor activation helper."
    fi
  else
    note "Openbox stack not detected; skipping Openbox monitor activation integration."
  fi
  if [[ -n "$guest_audio_csv" ]]; then
    local IFS=',' dev
    for dev in $guest_audio_csv; do
      [[ -n "$dev" ]] || continue
      assert_pci_bdf_exists "$dev"
      assert_not_equal "$dev" "$host_audio_bdfs_csv" "Guest audio BDF equals host audio BDF (refusing)."
    done
  fi

  # Determine GPU binding mode (early vs dynamic).
  # early: force the guest GPU onto vfio-pci at boot (current default behavior).
  # dynamic: let amdgpu load first; a libvirt qemu hook switches the GPU to
  # vfio-pci only when a VM that has it attached is started. More reliable for
  # RX 9070 / RDNA4 cards that hit the "Unknown PCI header type 127" reset bug.
  local binding_mode="${BINDING_MODE_OVERRIDE:-}"
  if [[ -n "$binding_mode" ]]; then
    binding_mode="${binding_mode^^}"
    note "CLI override applied: --binding-mode ${binding_mode,,}"
  else
    say
    hdr "GPU binding mode"
    note "Choose how the guest GPU is handed to the VM:"
    say
    # Two labeled bullet blocks are easier to scan than a cramped two-column
    # table whose cells wrap mid-phrase. One complete thought per bullet, and
    # bold mode labels (with a plain-text fallback when color is disabled).
    local _early_lbl _dyn_lbl
    if (( ENABLE_COLOR )); then
      _early_lbl="${C_BOLD}early binding${C_RESET}"
      _dyn_lbl="${C_BOLD}dynamic binding${C_RESET} ${C_DIM}(libvirt hook)${C_RESET}"
    else
      _early_lbl="early binding"
      _dyn_lbl="dynamic binding (libvirt hook)"
    fi
    say "  $_early_lbl"
    say "    - vfio-pci claims the GPU at boot (vfio-pci.ids + rd.driver.pre + systemd unit)"
    say "    - GPU is NOT usable by the host between reboots"
    say "    - works with raw qemu too"
    say "    - can trigger \"header type 127\" on some AMD cards"
    say
    say "  $_dyn_lbl"
    say "    - amdgpu loads first; a libvirt qemu hook switches the GPU to vfio-pci"
    say "      only when a VM that has it attached is started"
    say "    - GPU stays usable by the host until VM start (and after VM stop if REBIND_HOST=1)"
    say "    - requires libvirt-managed VMs"
    say "    - more reliable for RX 9070 / RDNA4 reset bug"
    say
    note "Both modes keep vfio-pci.disable_idle_d3=1 and pcie_port_pm=off."
    note "(RX 9070 / RDNA4 Navi 48 skips disable_idle_d3=1: it worsens D3 issues there; the bind script's D0-lock handles the reset bug.)"
    note "dynamic is the recommended default for RX 9070 / RDNA4 cards."
    local binding_default="N"
    if [[ "${guest_vendor,,}" == "1002" ]]; then
      local guest_drv
      guest_drv="$(bdf_driver_name "$guest_gpu" 2>/dev/null || echo "")"
      if [[ "$guest_drv" == "amdgpu" ]]; then
        binding_default="Y"
        note "AMD guest GPU is currently on amdgpu; defaulting to dynamic binding."
      fi
    fi
    if prompt_yn "Use dynamic binding (libvirt hook switches GPU at VM start) instead of early binding?" "$binding_default" "GPU binding mode"; then
      binding_mode="DYNAMIC"
    else
      binding_mode="EARLY"
    fi
  fi
  if [[ "$binding_mode" == "DYNAMIC" ]]; then
    if ! have_cmd libvirtd && ! have_cmd virtqemud && ! have_cmd virsh; then
      note "WARN: dynamic binding was selected but no libvirt daemon (libvirtd/virtqemud/virsh) was detected."
      note "      Dynamic binding only works for libvirt-managed VMs. If you use raw qemu, choose early binding instead."
    fi
  fi
  CTX[binding_mode]="$binding_mode"

  write_conf "$host_gpu" "$host_audio_bdfs_csv" "$host_audio_node_name" "$guest_gpu" "$guest_audio_csv" "$guest_vendor" "$graphics_protocol_mode" "$boot_vga_policy_mode" "$graphics_daemon_interval" "$binding_mode"
  install_vfio_modules_load

  # Optional: on openSUSE Tumbleweed offer to install the distribution's
  # long-term kernel. In real-world testing this kernel can make VFIO
  # binding more reliable for some AMD Navi GPUs by avoiding very recent
  # amdgpu changes that aggressively claim the device even when vfio-pci
  # is requested. We only suggest this for AMD guest GPUs and when the
  # current boot still shows amdgpu as the active driver for the guest
  # BDF, and in that case we default the prompt to YES.
  maybe_offer_kernel_longterm "$guest_vendor" "$guest_gpu"

  # Optional: on Fedora offer to install the CachyOS kernel from COPR.
  # The stock Fedora kernel does not include the ACS override patch, which
  # can cause IOMMU group sharing and PCIe instability during long VFIO
  # passthrough sessions. The CachyOS kernel includes this patch and has
  # been observed to properly isolate devices.
  maybe_offer_fedora_cachyos_kernel "$guest_vendor" "$guest_gpu"

  # EXTRA (advanced, openSUSE-only): if kernel-longterm is installed,
  # offer to UNINSTALL the default kernel package so only the long-term
  # kernel remains. This is dangerous if the long-term kernel ever
  # becomes unbootable, so the default answer is NO and the prompt is
  # explicit about the risks. To avoid accidental "yes" presses, this
  # requires typing a confirmation phrase instead of a single key.
  if is_opensuse_like && rpm -q kernel-longterm >/dev/null 2>&1; then
    say
    hdr "Advanced: openSUSE default kernel removal (optional)"
    note "You are running on an openSUSE-like system and the 'kernel-longterm' package is installed."
    note "For VFIO, some users prefer to keep ONLY the long-term kernel and uninstall the default kernel package."
    if (( ENABLE_COLOR )); then
      say "${C_BOLD}${C_RED}DANGER:${C_RESET} Removing the default kernel means you will NOT have a fallback kernel if kernel-longterm ever fails to boot."
    else
      say "DANGER: Removing the default kernel means you will NOT have a fallback kernel if kernel-longterm ever fails to boot."
    fi
    note "Recommended for most users: NO (keep both kernels so you always have a rescue/fallback entry)."
    note "If you really want to uninstall the default kernel, type: REMOVE DEFAULT KERNEL"
    note "Or press ENTER to skip and keep both kernels."

    local in="/dev/stdin" out="/dev/stderr" ans
    if [[ -r /dev/tty && -w /dev/tty ]]; then
      in="/dev/tty"; out="/dev/tty"
    fi

    printf '%s' "> " >"$out"
    read -r ans <"$in" || ans=""

    if [[ "$ans" == "REMOVE DEFAULT KERNEL" ]]; then
      if have_cmd zypper; then
        say "Attempting to uninstall default kernel packages via zypper..."
        # We target the common default-kernel patterns. If some are not
        # installed, zypper will simply ignore them.
        run zypper --non-interactive rm kernel-default kernel-default-base kernel-default-extra 2>/dev/null || \
          note "zypper could not remove one or more default kernel packages automatically. You may need to adjust packages manually."
        # After changing installed kernels, refresh BLS entries if applicable.
        opensuse_sdbootutil_update_all_entries
      else
        note "zypper is not available; cannot manage kernel packages automatically."
      fi
    else
      note "Keeping both default and long-term kernels installed (safer for recovery)."
    fi
  fi

  say
  hdr "Initramfs integration"

  if command -v dracut >/dev/null 2>&1; then
    # OPENSUSE FIX: On openSUSE (dracut-based), including VFIO modules in the
    # initramfs is **mandatory** if we are going to use rd.driver.pre=vfio-pci,
    # otherwise the kernel may hang waiting for a driver that is not present
    # in the early initramfs. We therefore install the dracut config
    # unconditionally on openSUSE instead of asking.
    if is_opensuse_like; then
      say "${C_YELLOW}openSUSE detected:${C_RESET} automatically installing Dracut VFIO config."
      note "This ensures 'rd.driver.pre=vfio-pci' does not hang your boot process by requesting a driver that is missing from the initramfs."
      install_dracut_config
      CTX[dracut_vfio]=1
    else
      note "By default, VFIO modules will load from the root filesystem via $MODULES_LOAD after it is mounted."
      note "You can also pre-load them in the initramfs via dracut config; this is more invasive and can affect very early boot."

      local prompt title
      title="Initramfs integration"
      prompt="Install dracut config to include VFIO modules in the initramfs now? (advanced)"
      if prompt_yn "$prompt" N "$title"; then
        install_dracut_config
        CTX[dracut_vfio]=1
      else
        note "Skipping dracut VFIO initramfs config. You can add it later by re-running this helper."
      fi
    fi
  else
    note "dracut not detected; skipping initramfs-specific VFIO config."
  fi

  say
  hdr "Module load ordering (optional soft dependency)"
  note "To reduce race conditions where the GPU driver (amdgpu/nvidia/i915) grabs the card before vfio-pci,"
  note "you can install a softdep rule so vfio-pci is always loaded first for the guest GPU vendor."
  note "This is usually safe, but if you have unusual driver setups you may prefer to skip it."
  if prompt_yn "Install vfio-pci softdep for $(vendor_name "$guest_vendor") now?" Y "Module load ordering"; then
    install_softdep_config "$guest_vendor"
  else
    note "Skipping vfio softdep installation. You can add it later in /etc/modprobe.d/vfio-softdep.conf if needed."
  fi

  install_bind_script
  install_systemd_unit
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
    install_libvirt_hook
    # Pin KDE/KWin Wayland to the HOST GPU so binding the (Boot VGA) guest GPU
    # at VM start does not crash the host compositor. No-op unless the guest
    # GPU is Boot VGA. (Early binding binds at boot, before the compositor
    # starts, so the pin is only needed for dynamic binding.)
    install_wayland_render_device_pin "$host_gpu" "$guest_gpu"
    # Install the reboot-FLR monitor (watches for guest warm reboot and does a
    # soft FLR to clear the display wedge so OVMF re-POSTs without a host reboot).
    install_reboot_flr_monitor
    # Install the park-keepalive monitor (instant on, no prompt): proactively
    # recovers the guest GPU while it is parked on vfio-pci between VM sessions.
    install_park_keepalive_monitor
    # vBIOS ROM auto-injection (opt-in prompt): pin a matching *.rom dump
    # from VBIOS/ into each shut-off guest-GPU VM's hostdev. If the user
    # already has a vBIOS configured manually (or does not want one), they can
    # skip -- selecting "no" removes any script-installed pin.
    # Honors --vbios / --no-vbios overrides.
    if [[ "${VBIOS_INJECTION_OVERRIDE:-}" == "1" ]]; then
      install_vbios_romfile
    elif [[ "${VBIOS_INJECTION_OVERRIDE:-}" == "0" ]]; then
      note "vBIOS ROM auto-injection skipped (--no-vbios)."
      note "Removing any script-installed vBIOS pin..."
      remove_vbios_romfile
    else
      if prompt_yn "Inject a matching vBIOS ROM dump into detected guest-GPU VMs? (say NO if you already have a vBIOS in your VM XML -- NO will remove any script-installed pin)" N "vBIOS ROM injection"; then
        install_vbios_romfile
      else
        note "Skipping vBIOS ROM auto-injection."
        note "Removing any script-installed vBIOS pin..."
        remove_vbios_romfile
      fi
    fi
    # Stealth/perf VM tuning (opt-in) — asks the user if they want the VM to
    # look like a real desktop PC (SMBIOS spoofing, CPU hypervisor-bit disable,
    # e1000e NIC, randomized disk serials, vmport off, iothreads/cputune).
    # Honors --stealth-vm-tuning / --no-stealth-vm-tuning overrides.
    # Selecting "no" reverts any previously-applied stealth tuning.
    if [[ "${STEALTH_VM_TUNING_OVERRIDE:-}" == "1" ]]; then
      install_stealth_vm_tuning
    elif [[ "${STEALTH_VM_TUNING_OVERRIDE:-}" == "0" ]]; then
      note "Stealth/perf VM tuning skipped (--no-stealth-vm-tuning)."
      note "Reverting any previously-applied stealth tuning..."
      reset_stealth_vm_tuning
    else
      say
      if (( ENABLE_COLOR )); then
        say "${C_BOLD}${C_YELLOW}DISCLAIMER:${C_RESET} stealth/perf VM tuning is COSMETIC/PERFORMANCE realism only"
      else
        say "DISCLAIMER: stealth/perf VM tuning is COSMETIC/PERFORMANCE realism only"
      fi
      note "(SMBIOS spoofing, CPU/NIC/disk-serial values, hypervisor hide). It is NOT intended to,"
      note "and does NOT reliably, defeat or bypass anti-cheat / anti-tamper software. Using it to"
      note "evade anti-cheat in an online game may still violate that game's terms of service."
      if prompt_yn "Apply stealth/perf VM tuning to detected guest-GPU VMs? (SMBIOS spoofing, CPU/NIC/disk serials, vmport off, iothreads — makes the VM look like a real desktop PC)" N "Stealth/perf VM tuning"; then
        install_stealth_vm_tuning
      else
        note "Skipping stealth/perf VM tuning. You can apply it later with: sudo $SCRIPT_NAME --install-stealth-vm-tuning"
        note "Reverting any previously-applied stealth tuning..."
        reset_stealth_vm_tuning
      fi
    fi
    # Ultimate-performance VM tuning (opt-in) — a SEPARATE, more aggressive perf
    # layer than the basic perf subset bundled into stealth tuning above. Applies
    # maximum-throughput knobs to each shut-off guest-GPU VM WITHOUT touching
    # stealth. Honors --ultimate-perf-vm-tuning / --no-ultimate-perf-vm-tuning.
    # Selecting "no" just skips (reverting is a separate explicit action:
    # --reset-ultimate-perf-vm-tuning). The function prompts internally for the
    # hugepages + SATA->virtio opt-ins.
    if [[ "${ULTIMATE_PERF_VM_TUNING_OVERRIDE:-}" == "1" ]]; then
      install_ultimate_perf_vm_tuning
    elif [[ "${ULTIMATE_PERF_VM_TUNING_OVERRIDE:-}" == "0" ]]; then
      note "Ultimate-performance VM tuning skipped (--no-ultimate-perf-vm-tuning)."
    else
      say
      note "Ultimate-performance VM tuning is a SEPARATE, more aggressive perf layer (stealth-safe:"
      note "it NEVER touches stealth). Knobs: disk I/O + multiqueue, scaled iothreads, aggressive"
      note "cputune/numatune pinning, CPU topology + cache passthrough, no startup balloon, S3/S4 off."
      note "Hugepages + SATA->virtio disk conversion are opt-in within it (prompted separately)."
      note "DISCLAIMER: performance tuning ONLY."
      if prompt_yn "Apply ultimate-performance VM tuning (stealth-safe) to detected guest-GPU VMs now?" N "Ultimate-perf VM tuning"; then
        install_ultimate_perf_vm_tuning
      else
        note "Skipping ultimate-performance VM tuning. You can apply it later with: sudo $SCRIPT_NAME --install-ultimate-perf-vm-tuning"
      fi
    fi
  fi
  if (( INSTALL_GRAPHICS_DAEMON )); then
    install_graphics_protocol_daemon "$graphics_daemon_interval"
  else
    note "Skipping graphics protocol daemon installation by user request (--no-graphics-daemon)."
  fi
  install_prelogin_x11_host_gpu_pinning_failsafe "$host_gpu" "$guest_gpu" "$graphics_protocol_mode"

  say
  hdr "Boot log capture (optional)"
  note "You can automatically dump the current boot's journal to a vfio-boot-*.log file on your desktop after each boot."
  note "This is mainly useful when you are actively debugging passthrough problems and want to keep per-boot logs around."
  note "On a stable setup it is usually not necessary and can create a lot of log files over time."
  if prompt_yn "Install a small helper that saves a VFIO boot log to your Desktop on every boot?" N "Boot log capture"; then
    install_bootlog_dumper
  else
    note "Skipping boot log dumper; you can always inspect logs manually with journalctl -b when needed."
  fi

  say
  hdr "Display manager / seat isolation (optional)"
  note "A udev rule can remove the guest GPU (and its HDMI audio) from the host seat so the display manager does not grab it."
  note "This is usually helpful on multi-GPU systems where the host desktop should ignore the passthrough card."
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
    note "Skipping udev seat isolation in dynamic binding mode (the host display manager may use the guest GPU until VM start)."
  elif prompt_yn "Install udev rule to isolate the guest GPU from the host seat? (recommended)" Y "Seat isolation"; then
    install_udev_isolation "$guest_gpu" "$guest_audio_csv"
  else
    note "Skipping udev isolation; the host display manager may still see the guest GPU."
  fi

  say
  hdr "USB mitigation (optional)"
  note "Optional feature: most systems do NOT need this."
  note "Enable only when a USB Bluetooth adapter (dongle/dock) is causing timeout/reset instability."
  usb_bt_mitigation_explain
  note
  note "Install scope:"
  note "  - systemd + udev helper to detach USB Bluetooth interfaces from host btusb"
  note "  - uses unbind + driver_override=none flow"
  note "  - default service guard: stops/starts bluetooth.service during mitigation lifecycle"
  note "  - optional USB Ethernet EEE-off for selected USB NIC IDs (ethtool eee off)"
  note "  - optional aggressive hard-block via USB_BT_HARD_BLOCK=1 (authorized 0/1 toggle)"
  note "Expected result:"
  note "  - host Bluetooth side is disabled (reset-spam reduced)"
  note "  - USB device still enumerates and remains VM-pass-through eligible"
  note "Advanced mode:"
  note "  - MATCH_MODE=include_only with INCLUDE_IDS detaches only explicitly selected USB IDs"
  note "  - useful for targeted unstable devices (for example a flaky dock LAN adapter)"
  note "  - USB Ethernet EEE-off selection is scoped only to chosen USB Ethernet IDs"
  note "Safety guardrails:"
  note "  - operates only on /sys/bus/usb/devices interfaces + USB drivers"
  note "  - never unbinds motherboard PCI ethernet/Wi-Fi devices"
  note "  - selecting storage-class devices as VM-eligible detach targets is risky"
  note "Recovery: run $USB_BT_SCRIPT --enable, or remove mitigation via --reset-usb-mitigation (or full --reset)."
  if prompt_yn "Install and enable automatic USB mitigation (Bluetooth host detach + optional USB Ethernet EEE-off)?" N "USB mitigation"; then
    install_usb_bluetooth_disable
  else
    note "Skipping USB mitigation helper."
  fi

  say
  hdr "Boot configuration (IOMMU / boot loader)"
  local bl2="${CTX[bootloader]}"
  note "IOMMU must be enabled for PCI passthrough to work."
  note "Boot loader detected: ${bl2}"
  if [[ "$bl2" == "grub" ]]; then
    note "Recommended: YES (adds amd_iommu=on or intel_iommu=on + iommu=pt to GRUB)."
    note "If you answer NO, passthrough may fail unless you already configured IOMMU another way."
  elif [[ "$bl2" == "systemd-boot" || "$bl2" == "grub2-bls" ]]; then
    note "Recommended: YES (adds amd_iommu=on or intel_iommu=on + iommu=pt to the Boot Loader Spec entry and /etc/kernel/cmdline)."
    note "If you answer NO, passthrough may fail unless you already configured IOMMU another way."
  else
    note "Automatic kernel parameter editing is ONLY supported for GRUB and systemd-boot. For ${bl2}, you must add the parameters manually."
    note "If you skip the manual instructions, passthrough may fail."
  fi
  note "If you enable IOMMU, you will also be offered an optional 'ACS override' (advanced; usually NO)."

  local q
  if [[ "$bl2" == "grub" ]]; then
    q="Enable IOMMU kernel parameters in GRUB now? (recommended)"
  elif [[ "$bl2" == "systemd-boot" || "$bl2" == "grub2-bls" ]]; then
    q="Enable IOMMU kernel parameters in a Boot Loader Spec entry now? (recommended)"
  else
    q="Show recommended IOMMU kernel parameters and MANUAL instructions now? (recommended)"
  fi

  # Dynamic binding: auto-proceed the IOMMU gateway (IOMMU is mandatory for
  # passthrough in both modes) and let the bootloader function's streamlined
  # dynamic path auto-add the AMD reset-bug stability params + skip the optional
  # prompts. Early binding still asks the gateway prompt (default Y).
  if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]] || prompt_yn "$q" Y "Boot options"; then
    if [[ "${CTX[binding_mode]:-EARLY}" == "DYNAMIC" ]]; then
      note "Dynamic binding mode: auto-proceeding to kernel-cmdline update (IOMMU + AMD reset-bug stability params); optional prompts are skipped."
    fi
    if [[ "$bl2" == "grub" ]]; then
      grub_add_kernel_params
    elif [[ "$bl2" == "systemd-boot" || "$bl2" == "grub2-bls" ]]; then
      systemd_boot_add_kernel_params
    else
      print_manual_iommu_instructions
    fi
  else
    note "Skipping automatic/manual IOMMU helper. Ensure your kernel parameters enable IOMMU, or passthrough may fail."
  fi

  # Even if systemd-boot is the active loader, many openSUSE systems keep
  # GRUB installed as a fallback. As a final step, if GRUB tooling and
  # config are present, regenerate grub.cfg so any previous cmdline edits
  # (whether made by this script or manually) are reflected.
  if [[ -f /etc/default/grub ]]; then
    if command -v update-grub >/dev/null 2>&1; then
      say "(Post-install) Updating GRUB config via update-grub..."
      run update-grub || true
    elif command -v grub-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      elif [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      else
        out=""
      fi
      [[ -n "$out" ]] && { say "(Post-install) Updating GRUB config via grub-mkconfig -o $out ..."; run grub-mkconfig -o "$out" || true; }
    elif command -v grub2-mkconfig >/dev/null 2>&1; then
      local out
      if [[ -d /boot/grub2 ]]; then
        out=/boot/grub2/grub.cfg
      elif [[ -d /boot/grub ]]; then
        out=/boot/grub/grub.cfg
      else
        out=""
      fi
      [[ -n "$out" ]] && { say "(Post-install) Updating GRUB config via grub2-mkconfig -o $out ..."; run grub2-mkconfig -o "$out" || true; }
    fi
  fi

  # Guard against the "dracut trap": rd.driver.pre=vfio-pci on the
  # kernel cmdline without including vfio modules in the initramfs.
  if command -v dracut >/dev/null 2>&1; then
    if [[ "${CTX[rd_driver_pre]:-0}" == "1" && "${CTX[dracut_vfio]:-0}" != "1" ]]; then
      say
      hdr "Dracut / rd.driver.pre sanity check"
      note "You enabled rd.driver.pre=vfio-pci in the kernel cmdline, but did not install a dracut config to include vfio modules in the initramfs."
      note "On dracut-based systems (such as openSUSE), this mismatch can cause boot failures if the requested driver is missing from the early initramfs."
      if prompt_yn "Write dracut config to include VFIO modules in the initramfs now? (recommended)" Y "Initramfs (dracut)"; then
        install_dracut_config
        CTX[dracut_vfio]=1
      else
        note "You chose to keep rd.driver.pre=vfio-pci without adding vfio modules to the initramfs; this may break boot. Make sure you know how to recover (snapshots, rescue media)."
      fi
    fi
  fi

  # Optional driver blacklisting
  say
  hdr "Optional: driver blacklisting (advanced)"
  note "Blacklisting prevents the host from loading a GPU vendor's kernel modules at boot."
  note "This can help passthrough on some systems, but it can also break host graphics if you blacklist the wrong thing."
  note "This script does NOT require blacklisting (it binds by PCI BDF to vfio-pci instead)."

  local -a suggested_mods=()
  local suggested_note=""
  case "${guest_vendor,,}" in
    10de)
      suggested_mods=(nouveau nvidia nvidia_drm nvidia_modeset nvidia_uvm)
      ;;
    1002)
      # Many people prefer NOT to blacklist amdgpu on dual-GPU systems.
      suggested_mods=(radeon)
      suggested_note="AMD note: 'amdgpu' is the modern driver and is often used by the host GPU on dual-AMD systems. Blacklisting amdgpu is usually NOT recommended unless you're sure the host does not need it."
      ;;
    8086)
      suggested_mods=(i915)
      ;;
    *)
      suggested_mods=()
      ;;
  esac

  if (( ${#suggested_mods[@]} > 0 )); then
    note "If you choose YES, this script will offer to write: $BLACKLIST_FILE"
    note "Suggested modules to blacklist for vendor $(vendor_name "$guest_vendor") ($guest_vendor):"
    local m
    for m in "${suggested_mods[@]}"; do
      note "  - blacklist $m"
    done
    [[ -n "$suggested_note" ]] && note "$suggested_note"
  else
    note "No suggested modules for vendor $(vendor_name "$guest_vendor") ($guest_vendor)."
  fi

  # Extra safety: require an explicit BLACKLIST confirmation before entering the submenu.
  if prompt_yn "Open advanced driver blacklist submenu for $(vendor_name "$guest_vendor") drivers?" N "Driver blacklist"; then
    if ! confirm_phrase "WARNING: Driver blacklisting is OPTIONAL and can break host graphics if misused. To continue and create $BLACKLIST_FILE, type BLACKLIST." "BLACKLIST"; then
      note "Skipping driver blacklist (confirmation failed)."
    else
      # User typed BLACKLIST; give them one last chance to cancel and proceed without any blacklist.
      if ! prompt_yn "You typed BLACKLIST. Do you still want to create a driver blacklist file now?" N "Driver blacklist"; then
        note "Skipping driver blacklist (user cancelled after confirmation)."
      else
        write_optional_blacklist "$guest_vendor" "${suggested_mods[@]}"
        maybe_update_initramfs
      fi
    fi
  else
    note "Skipping driver blacklist submenu."
  fi

  say
  hdr "Initramfs update (recommended)"
  if prompt_yn "Update initramfs now? (recommended after VFIO and/or blacklisting changes)" Y "Initramfs update"; then
    if maybe_update_initramfs; then
      # Only refresh Boot Loader Spec entries AFTER a successful
      # initramfs rebuild to keep kernel cmdline and initramfs content
      # in sync when using rd.driver.pre=vfio-pci on openSUSE.
      if is_opensuse_like; then
        say "Refreshing Boot Loader Spec entries via sdbootutil update-all-entries ..."
        opensuse_sdbootutil_update_all_entries
      fi
    else
      say "WARNING: Initramfs update failed or no tool was found. Boot loader entries were NOT refreshed via sdbootutil to avoid a broken boot configuration."
    fi
  else
    note "Skipping initramfs rebuild; remember to update it yourself before relying on VFIO settings."
  fi

  say
  if prompt_yn "Install a user systemd unit to set the host default audio sink after login?" Y "Host audio output"; then
    install_audio_script
    install_user_audio_unit
  else
    note "Skipping user systemd audio helper. You can install it later by re-running this helper."
  fi
  apply_selected_graphics_protocol_mode "$host_gpu" "$guest_gpu"

  say
  say "Done. Next steps:"
  say "  1) Reboot."
  say "  2) Verify guest devices are bound to vfio-pci:"
  say "       lspci -nnk -s ${guest_gpu}"
  if [[ -n "$guest_audio_csv" ]]; then
    say "       lspci -nnk -s ${guest_audio_csv//,/ }"
  fi
  if [[ -n "$host_audio_bdfs_csv" ]]; then
    say "  3) Verify host audio device is NOT on vfio-pci:"
    say "       lspci -nnk -s ${host_audio_bdfs_csv%%,*}"
  fi
  say "  4) In your VM manager, passthrough the guest GPU and any selected guest audio PCI functions."
}

# Self-install: copy this script to /usr/local/bin/vfio (on PATH as the vfio command) and drop
# the fish/bash/zsh completions into their vendor auto-load directories so they
# load with no 'source' step. Idempotent: re-run to update the installed copy +
# completions. Root + writable-root are enforced by the main() --install-self /
# --uninstall-self dispatch (preserves the flag across the sudo re-exec). The
# repo copy is never touched.
install_self() {
  hdr "Install vfio to a stable PATH location (/usr/local/bin/vfio)"

  # Resolve the source script we are installing. $0 may be a relative path
  # (./vfio.sh) or an absolute one; canonicalize it. Refuse if it is not a
  # regular readable file (e.g. piped via curl|bash has no file to copy).
  local src
  src="$(readlink -f "$0" 2>/dev/null || echo "$0")"
  if [[ ! -f "$src" || ! -r "$src" ]]; then
    die "Cannot self-install: '$0' is not a regular readable file (self-install needs the script file on disk, not a pipe)."
  fi

  note "Source: $(_link "$src")"
  note "Target: $(_link "$SELF_INSTALL_BIN")"

  if (( DRY_RUN )); then
    note "DRY-RUN: would copy $src -> $SELF_INSTALL_BIN (0755) and install 3 completion files (command name: $(basename "$SELF_INSTALL_BIN"))"
    return 0
  fi

  # Same-file guard: running the already-installed copy re-installs idempotently
  # (refresh completions only) instead of cp-erroring "same file".
  if [[ "$src" -ef "$SELF_INSTALL_BIN" ]]; then
    note "Source is already the installed copy; refreshing completions only."
  else
    run mkdir -p "$(dirname "$SELF_INSTALL_BIN")"
    if [[ -f "$SELF_INSTALL_BIN" ]]; then
      backup_file "$SELF_INSTALL_BIN"
    fi
    run cp -a "$src" "$SELF_INSTALL_BIN"
    run chmod 0755 "$SELF_INSTALL_BIN"
    say "Installed: $(_link "$SELF_INSTALL_BIN")"
  fi

  # Install the 3 shell completions into the vendor auto-load directories so
  # they load with no 'source' step. Idempotent: overwrite = update.
  # The completions must target the INSTALLED command name (basename of
  # SELF_INSTALL_BIN = "vfio"), not the source script name (vfio.sh), and the
  # completion FILE names must match what fish/bash/zsh look up by command
  # name. print_*_completion read $SCRIPT_NAME, so override it locally here.
  local _fc _installed_cmd _saved_script_name
  _installed_cmd="$(basename "$SELF_INSTALL_BIN")"
  _saved_script_name="$SCRIPT_NAME"
  SCRIPT_NAME="$_installed_cmd"

  run mkdir -p "$FISH_COMPLETION_DIR"
  _fc="${FISH_COMPLETION_DIR}/${_installed_cmd}.fish"
  print_fish_completion >"$_fc"
  say "Installed fish completion: $(_link "$_fc")"

  run mkdir -p "$BASH_COMPLETION_DIR"
  _fc="${BASH_COMPLETION_DIR}/${_installed_cmd}"
  print_bash_completion >"$_fc"
  say "Installed bash completion: $(_link "$_fc")"

  run mkdir -p "$ZSH_COMPLETION_DIR"
  _fc="${ZSH_COMPLETION_DIR}/_${_installed_cmd}"
  print_zsh_completion >"$_fc"
  say "Installed zsh completion: $(_link "$_fc")"

  SCRIPT_NAME="$_saved_script_name"

  say
  say "Done. Next steps:"
  say "  - vfio is now on PATH as $(basename "$SELF_INSTALL_BIN") (open a new shell or 'hash -r' / 'rehash')."
  say "  - Fish/bash/zsh completions auto-load from the vendor dirs (no 'source' needed)."
  say "  - Re-run anytime to update the installed copy + completions to the latest version."
}

# Uninstaller for the self-installed script + completions (separate from --reset,
# which stays scoped to VFIO config). Removes only our 4 files (by name); never
# touches the repo copy or the VFIO config.
uninstall_self() {
  hdr "Uninstall the self-installed vfio"

  # Completion files are filed by the INSTALLED command name (basename of
  # SELF_INSTALL_BIN = "vfio"), not the source script name (vfio.sh).
  local _found=0 _installed_cmd
  _installed_cmd="$(basename "$SELF_INSTALL_BIN")"
  if [[ -f "$SELF_INSTALL_BIN" ]] \
    || [[ -f "${FISH_COMPLETION_DIR}/${_installed_cmd}.fish" ]] \
    || [[ -f "${BASH_COMPLETION_DIR}/${_installed_cmd}" ]] \
    || [[ -f "${ZSH_COMPLETION_DIR}/_${_installed_cmd}" ]]; then
    _found=1
  fi

  if (( ! _found )); then
    note "No self-installed vfio or completion files found; nothing to uninstall."
    note "(This does NOT touch the VFIO config — use --reset for that.)"
    return 0
  fi

  note "This removes:"
  note "  - $SELF_INSTALL_BIN"
  note "  - ${FISH_COMPLETION_DIR}/${_installed_cmd}.fish"
  note "  - ${BASH_COMPLETION_DIR}/${_installed_cmd}"
  note "  - ${ZSH_COMPLETION_DIR}/_${_installed_cmd}"
  note "It does NOT remove the VFIO config (use --reset) or your repo copy."

  if ! prompt_yn "Uninstall the self-installed vfio + completions now?" N "Uninstall self"; then
    note "Uninstall cancelled."
    return 0
  fi

  if (( DRY_RUN )); then
    note "DRY-RUN: would remove $SELF_INSTALL_BIN + 3 completion files"
    return 0
  fi

  run rm -f "$SELF_INSTALL_BIN" \
    "${FISH_COMPLETION_DIR}/${_installed_cmd}.fish" \
    "${BASH_COMPLETION_DIR}/${_installed_cmd}" \
    "${ZSH_COMPLETION_DIR}/_${_installed_cmd}"
  say "Removed self-installed vfio + completion files."
  say
  note "If vfio was on PATH, run 'hash -r' (bash) / 'rehash' (zsh) so the shell forgets it."
  note "The VFIO config ($CONF_FILE) is untouched — use --reset to remove it."
}

# Config pickup: when the install wizard (or --menu option 0) starts and the
# live $CONF_FILE is missing but a prior run left a $CONF_FILE.bak.<ts> backup
# on disk (e.g. after --reset removed the live conf, or a fresh repo clone onto
# a host that had VFIO before), offer to restore the SAME config (guest/host GPU
# BDFs + binding mode) and re-apply the binding instead of re-running the whole
# wizard. Self-gates: no-op unless MODE=install, $CONF_FILE missing, and a .bak
# exists. Called from preflight_existing_config_gate. On a successful restore it
# exits 0 so the wizard is skipped (the config is already re-applied).
maybe_pickup_leftover_conf() {
  [[ "${MODE:-install}" == "install" ]] || return 0
  readable_file "$CONF_FILE" && return 0

  # Newest backup first (mtime comparison). Globs sort lexically by default;
  # the .bak.<RUN_TS> timestamps are YYYYmmdd-HHMMSS so lexical ~= time order,
  # but prefer an explicit mtime comparison for robustness.
  local _bak="" _f
  for _f in "${CONF_FILE}".bak.*; do
    [[ -f "$_f" ]] || continue
    if [[ -z "$_bak" || "$_f" -nt "$_bak" ]]; then
      _bak="$_f"
    fi
  done
  [[ -n "$_bak" ]] || return 0

  # One-line summary of what the backup contains (read without sourcing, same
  # awk pattern used elsewhere in this script to read a quoted KEY="value" line).
  local _gg _hg _bm _ts
  _gg="$(awk -F= '/^GUEST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$_bak" 2>/dev/null || true)"
  _hg="$(awk -F= '/^HOST_GPU_BDF=/{v=$2; gsub(/"/,"",v); print v; exit}' "$_bak" 2>/dev/null || true)"
  _bm="$(awk -F= '/^VFIO_BINDING_MODE=/{v=$2; gsub(/"/,"",v); print v; exit}' "$_bak" 2>/dev/null || true)"
  [[ -n "$_bm" ]] || _bm="early"
  _ts="${_bak##*.bak.}"

  say
  hdr "Backed-up VFIO config found"
  note "A previous $SCRIPT_NAME run left a config backup, but $CONF_FILE is missing."
  note "Backup: $(_link "$_bak") (from $_ts)"
  note "  Guest GPU:    ${_gg:-<missing>}"
  note "  Host GPU:     ${_hg:-<missing>}"
  note "  Binding mode: $_bm"

  if ! prompt_yn "Restore this config (pick up the same GPU selection) instead of re-running the wizard?" Y "Config pickup"; then
    note "Skipping pickup; continuing to the guided wizard."
    return 0
  fi

  if (( DRY_RUN )); then
    note "DRY-RUN: would restore $_bak -> $CONF_FILE and re-apply $_bm binding"
    return 0
  fi

  run cp -a "$_bak" "$CONF_FILE"
  run chmod 0644 "$CONF_FILE"
  say "Restored config: $(_link "$CONF_FILE")"

  # Re-apply the binding so the bind script/hook/cmdline match the restored
  # config (the switchers regenerate the bind script + sync cmdline without
  # re-running the full wizard). Both already exist and check $CONF_FILE.
  require_systemd
  if [[ "$_bm" == "dynamic" ]]; then
    say
    note "Re-applying dynamic binding from the restored config..."
    install_dynamic_binding_from_existing_config
  else
    say
    note "Re-applying early binding from the restored config..."
    install_early_binding_from_existing_config
  fi
  say
  say "Config picked up. Verify with: sudo $SCRIPT_NAME --verify"
  say "(Re-run --menu if you want to do more, e.g. enable live-attach.)"
  # Skip the wizard: we just restored + re-applied everything it would have.
  exit 0
}

# Interactive menu: pick what to do without running the whole wizard or
# remembering individual flags. Uses select_from_list (whiptail TUI + plain-text
# fallback), loops back after each action so the operator can do multiple things
# in one session. Root + writable-root are enforced by the main() --menu dispatch
# (most actions write to /etc; that also preserves --menu across the sudo re-exec
# that require_root performs). Read-only actions (verify/detect) run inside.
vfio_menu() {
  local _menu_opts _choice _conf_present _bmode

  while :; do
    # Refresh each iteration so the header reflects state changes (e.g. after a
    # reset removes $CONF_FILE, or after switching binding mode).
    _conf_present="no"
    readable_file "$CONF_FILE" && _conf_present="yes"
    _bmode="none"
    if readable_file "$CONF_FILE"; then
      # Read without sourcing (avoids SC1090 + scope leaks); same awk pattern
      # used elsewhere in this script to read a quoted KEY="value" conf line.
      _bmode="$(awk -F= '/^VFIO_BINDING_MODE=/{v=$2; gsub(/"/,"",v); print v; exit}' "$CONF_FILE" 2>/dev/null || true)"
      [[ -n "$_bmode" ]] || _bmode="none"
    fi

    _menu_opts=(
      "Full configure (the guided wizard — pick GPUs, audio, binding mode)"
      "Switch to dynamic binding (RX 9070 / RDNA4 recommended)"
      "Switch to early binding (boot-time, classic)"
      "Set up live-attach / hotswap (VM starts without GPU, then hot-attached)"
      "Attach virtio-win guest-agent ISO (smart handoff via guest-ping)"
      "Apply stealth/perf VM tuning (SMBIOS/CPU/NIC/disk serials)"
      "Revert stealth/perf VM tuning (from backup XML)"
      "Apply ultimate-perf VM tuning (stealth-safe: disk I/O, iothreads, pinning, hugepages opt-in)"
      "Revert ultimate-perf VM tuning (from backup XML, restores nr_hugepages)"
      "Verify setup (read-only check)"
      "Detect / health check (read-only report)"
      "Reset everything (full cleanup, removes all VFIO config)"
      "Install vfio to /usr/local/bin (+ shell completions)"
      "Uninstall the self-installed vfio (+ completions)"
      "Exit menu"
    )
    say
    hdr "vfio.sh menu"
    note "Config present: $_conf_present | Binding mode: $_bmode"
    note "Pick an action (or Exit to quit):"
    _choice="$(select_from_list "What do you want to do?" "vfio.sh menu" "${_menu_opts[@]}")"
    case "$_choice" in
      0)
        # Full configure — the existing wizard (mirrors the main() fallthrough).
        say
        note "Starting full guided configure..."
        require_systemd
        detect_system
        user_selection
        apply_configuration
        ;;
      1)
        # Switch to dynamic binding.
        say
        note "Switching to dynamic binding..."
        require_systemd
        install_dynamic_binding_from_existing_config
        ;;
      2)
        # Switch to early binding.
        say
        note "Switching to early binding..."
        require_systemd
        install_early_binding_from_existing_config
        ;;
      3)
        # Set up live-attach / hotswap.
        say
        note "Setting up live-attach / hotswap..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 (Full configure) or option 2 (Switch to dynamic binding) first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; live-attach needs libvirt to modify VM XML."
          if prompt_yn "Continue anyway?" N "Live-attach"; then
            install_live_attach
          fi
        else
          install_live_attach
        fi
        ;;
      4)
        # Attach virtio-win guest-agent ISO.
        say
        note "Attaching virtio-win guest-agent ISO..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 or 2 first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; virtio-win guest-agent setup needs libvirt to attach the ISO to VM XML."
          if prompt_yn "Continue anyway?" N "virtio-win guest agent"; then
            install_virtio_win_guest_agent
          fi
        else
          install_virtio_win_guest_agent
        fi
        ;;
      5)
        # Apply stealth/perf VM tuning.
        say
        note "Applying stealth/perf VM tuning..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 or 2 first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; stealth/perf VM tuning needs libvirt to dump/define VM XML."
          if prompt_yn "Continue anyway?" N "Stealth/perf VM tuning"; then
            install_stealth_vm_tuning
          fi
        else
          install_stealth_vm_tuning
        fi
        ;;
      6)
        # Revert stealth/perf VM tuning.
        say
        note "Reverting stealth/perf VM tuning..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 or 2 first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; stealth/perf VM revert needs libvirt to dump/define VM XML."
          if prompt_yn "Continue anyway?" N "Revert stealth/perf VM tuning"; then
            reset_stealth_vm_tuning
          fi
        else
          reset_stealth_vm_tuning
        fi
        ;;
      7)
        # Apply ultimate-perf VM tuning (stealth-safe).
        say
        note "Applying ultimate-performance VM tuning..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 or 2 first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; ultimate-perf VM tuning needs libvirt to dump/define VM XML."
          if prompt_yn "Continue anyway?" N "Ultimate-perf VM tuning"; then
            install_ultimate_perf_vm_tuning
          fi
        else
          install_ultimate_perf_vm_tuning
        fi
        ;;
      8)
        # Revert ultimate-perf VM tuning.
        say
        note "Reverting ultimate-performance VM tuning..."
        if ! readable_file "$CONF_FILE"; then
          note "Missing $CONF_FILE. Run option 1 or 2 first."
        elif ! libvirt_runtime_ok; then
          note "WARN: libvirt is not reachable; ultimate-perf VM revert needs libvirt to dump/define VM XML."
          if prompt_yn "Continue anyway?" N "Revert ultimate-perf VM tuning"; then
            reset_ultimate_perf_vm_tuning
          fi
        else
          reset_ultimate_perf_vm_tuning
        fi
        ;;
      9)
        # Verify setup (read-only).
        say
        note "Verifying setup..."
        verify_setup
        ;;
      10)
        # Detect / health check (read-only). Subshell isolates the conf source.
        say
        note "Running detect + health check..."
        detect_existing_vfio_report
        say
        hdr "Health check"
        (
          if readable_file "$CONF_FILE"; then
            # shellcheck disable=SC1090
            . "$CONF_FILE"
            audit_vfio_health "${GUEST_GPU_BDF:-}"
          else
            audit_vfio_health ""
          fi
        )
        ;;
      11)
        # Reset everything.
        say
        note "Resetting everything..."
        require_systemd
        if prompt_yn "This will remove ALL VFIO config installed by this script. Continue?" N "Reset"; then
          if confirm_phrase "To continue, confirm reset." "RESET VFIO"; then
            reset_vfio_all
          else
            note "Reset cancelled (confirmation phrase not provided)."
          fi
        else
          note "Reset cancelled."
        fi
        ;;
      12)
        # Install vfio.sh to a stable PATH location + shell completions.
        say
        note "Installing vfio.sh to /usr/local/sbin + shell completions..."
        install_self
        ;;
      13)
        # Uninstall the self-installed vfio.sh + completions.
        say
        note "Uninstalling the self-installed vfio.sh + completions..."
        uninstall_self
        ;;
      14)
        # Exit.
        say
        say "Exiting vfio.sh menu."
        return 0
        ;;
      *)
        note "Invalid selection."
        ;;
    esac
    say
    note "Returning to menu..."
  done
}

main() {
  # Ensure this helper is marked executable so it can be run as ./vfio.sh
  # even if the user originally invoked it via "sh vfio.sh" or similar.
  # Best-effort only: ignore failures (read-only filesystem, etc.).
  if [[ -f "$0" && ! -x "$0" ]]; then
    chmod +x "$0" 2>/dev/null || true
  fi

  # Capture the original argument count before parse_args so we can detect a
  # bare invocation (no flags at all) and route it to the interactive menu
  # instead of auto-running the full wizard. parse_args shifts its own copy;
  # main's "$@" is unchanged after it returns, but capture upfront for clarity.
  local _VFIO_ORIG_ARGC=$#

  parse_args "$@"

  if [[ "$MODE" == "print-fish-completion" ]]; then
    print_fish_completion
    exit 0
  fi
  if [[ "$MODE" == "print-bash-completion" ]]; then
    print_bash_completion
    exit 0
  fi
  if [[ "$MODE" == "print-zsh-completion" ]]; then
    print_zsh_completion
    exit 0
  fi

  # Core tools used across modes
  need_cmd lspci
  need_cmd sed
  need_cmd awk
  need_cmd grep
  need_cmd install
  need_cmd mktemp
  need_cmd stat

  # modprobe is only required for modes that actually manipulate
  # kernel modules / bindings. Self-test, detect and health-check
  # variants should be able to run in "thin" environments (containers,
  # chroots) where modprobe may be absent.
  if [[ "$MODE" != "verify" && "$MODE" != "self-test" && "$MODE" != "detect" && "$MODE" != "print-effective-config" && "$MODE" != "sync-bls-only" && "$MODE" != "debug-cmdline-tokens" && "$MODE" != "verify-bls-sync" && "$MODE" != "verify-bls-nosnapper" && "$MODE" != "create-fallback-entry" && "$MODE" != "health-check" && "$MODE" != "health-check-prev" && "$MODE" != "health-check-all" && "$MODE" != "usb-health-check" && "$MODE" != "install-bootlog" && "$MODE" != "install-usb-bt-mitigation" && "$MODE" != "reset-usb-mitigation" ]]; then
    need_cmd modprobe
  fi

  # Optional but improves UX for PipeWire enumeration under sudo
  have_cmd runuser || true

  if [[ "$MODE" == "verify" ]]; then
    verify_setup
    exit $?
  fi

  if [[ "$MODE" == "detect" ]]; then
    detect_existing_vfio_report
    exit 0
  fi
  if [[ "$MODE" == "verify-bls-sync" ]]; then
    verify_bls_entries_against_kernel_cmdline
    exit $?
  fi
  if [[ "$MODE" == "verify-bls-nosnapper" ]]; then
    verify_bls_no_snapper_writes
    exit $?
  fi

  if [[ "$MODE" == "sync-bls-only" ]]; then
    require_root "$@"
    require_writable_root_or_die
    sync_bls_entries_from_kernel_cmdline
    verify_bls_entries_against_kernel_cmdline
    exit $?
  fi
  if [[ "$MODE" == "debug-cmdline-tokens" ]]; then
    debug_bls_cmdline_tokens
    exit $?
  fi
  if [[ "$MODE" == "create-fallback-entry" ]]; then
    require_root "$@"
    require_writable_root_or_die
    create_or_update_bls_fallback_entry
    exit $?
  fi

  if [[ "$MODE" == "print-effective-config" ]]; then
    print_effective_config
    exit 0
  fi

  if [[ "$MODE" == "self-test" ]]; then
    self_test
    exit $?
  fi

  if [[ "$MODE" == "health-check" ]]; then
    # If a config exists, prefer to audit the configured guest GPU; otherwise
    # fall back to a generic audit.
    local guest_bdf=""
    if readable_file "$CONF_FILE"; then
      # shellcheck disable=SC1090
      . "$CONF_FILE"
      guest_bdf="${GUEST_GPU_BDF:-}"
    fi
    if [[ -n "$guest_bdf" ]]; then
      audit_vfio_health "$guest_bdf"
    else
      audit_vfio_health ""
    fi
    exit $?
  fi

  if [[ "$MODE" == "health-check-prev" ]]; then
    # Same as --health-check but using the PREVIOUS boot's kernel logs
    # (journalctl -k -b -1) when available.
    local guest_bdf=""
    if readable_file "$CONF_FILE"; then
      # shellcheck disable=SC1090
      . "$CONF_FILE"
      guest_bdf="${GUEST_GPU_BDF:-}"
    fi
    VFIO_HEALTH_BOOT_OFFSET=-1
    if [[ -n "$guest_bdf" ]]; then
      audit_vfio_health "$guest_bdf"
    else
      audit_vfio_health ""
    fi
    exit $?
  fi

  if [[ "$MODE" == "health-check-all" ]]; then
    health_check_all
    exit $?
  fi

  if [[ "$MODE" == "usb-health-check" ]]; then
    usb_health_check
    exit $?
  fi

  if [[ "$MODE" == "reset" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    reset_vfio_all
    exit 0
  fi
  if [[ "$MODE" == "reset-usb-mitigation" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    reset_usb_mitigation_only
    exit 0
  fi

  if [[ "$MODE" == "disable-bootlog" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    disable_bootlog_dumper
    exit 0
  fi

  if [[ "$MODE" == "install-bootlog" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    install_bootlog_dumper
    exit 0
  fi

  if [[ "$MODE" == "install-graphics-daemon" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    install_graphics_protocol_daemon_from_existing_config
    exit 0
  fi

  if [[ "$MODE" == "install-dynamic-binding" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    install_dynamic_binding_from_existing_config
    exit 0
  fi

  if [[ "$MODE" == "install-early-binding" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die
    install_early_binding_from_existing_config
    exit 0
  fi

  if [[ "$MODE" == "install-stealth-vm-tuning" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run the full installer first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; stealth/perf VM tuning needs libvirt to dump/define VM XML."
      if ! prompt_yn "Continue anyway?" N "Stealth/perf VM tuning"; then
        die "Aborted by user"
      fi
    fi
    install_stealth_vm_tuning
    exit 0
  fi

  if [[ "$MODE" == "reset-stealth-vm-tuning" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run the full installer first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; stealth/perf VM revert needs libvirt to dump/define VM XML."
      if ! prompt_yn "Continue anyway?" N "Revert stealth/perf VM tuning"; then
        die "Aborted by user"
      fi
    fi
    reset_stealth_vm_tuning
    exit 0
  fi

  if [[ "$MODE" == "install-ultimate-perf-vm-tuning" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run the full installer first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; ultimate-perf VM tuning needs libvirt to dump/define VM XML."
      if ! prompt_yn "Continue anyway?" N "Ultimate-perf VM tuning"; then
        die "Aborted by user"
      fi
    fi
    install_ultimate_perf_vm_tuning
    exit 0
  fi

  if [[ "$MODE" == "reset-ultimate-perf-vm-tuning" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run the full installer first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; ultimate-perf VM revert needs libvirt to dump/define VM XML."
      if ! prompt_yn "Continue anyway?" N "Revert ultimate-perf VM tuning"; then
        die "Aborted by user"
      fi
    fi
    reset_ultimate_perf_vm_tuning
    exit 0
  fi

  if [[ "$MODE" == "install-live-attach" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run --install-dynamic-binding first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; live-attach needs libvirt to modify VM XML."
      if ! prompt_yn "Continue anyway?" N "Live-attach"; then
        die "Aborted by user"
      fi
    fi
    install_live_attach
    exit 0
  fi

  if [[ "$MODE" == "install-virtio-win-guest-agent" ]]; then
    require_root "$@"
    require_writable_root_or_die
    if ! readable_file "$CONF_FILE"; then
      die "Missing $CONF_FILE. Run --install-dynamic-binding first."
    fi
    if ! libvirt_runtime_ok; then
      note "WARN: libvirt is not reachable; virtio-win guest-agent setup needs libvirt to attach the ISO to VM XML."
      if ! prompt_yn "Continue anyway?" N "virtio-win guest agent"; then
        die "Aborted by user"
      fi
    fi
    install_virtio_win_guest_agent
    exit 0
  fi

  if [[ "$MODE" == "menu" ]]; then
    require_root "$@"
    require_writable_root_or_die
    vfio_menu
    exit 0
  fi

  if [[ "$MODE" == "install-self" ]]; then
    require_root "$@"
    require_writable_root_or_die
    install_self
    exit 0
  fi

  if [[ "$MODE" == "uninstall-self" ]]; then
    require_root "$@"
    require_writable_root_or_die
    uninstall_self
    exit 0
  fi

  if [[ "$MODE" == "install-usb-bt-mitigation" ]]; then
    require_root "$@"
    require_systemd
    require_writable_root_or_die

    say
    hdr "USB mitigation (standalone install)"
    usb_bt_mitigation_explain
    say
    note "This standalone mode installs only USB mitigation artifacts:"
    note "  - $USB_BT_SCRIPT"
    note "  - $USB_BT_SYSTEMD_UNIT"
    note "  - $USB_BT_UDEV_RULE"
    note "  - $USB_BT_MATCH_CONF"
    note "It also supports optional USB Ethernet EEE-off targeting for selected USB NIC IDs."
    note "Safety scope: USB interface drivers only (never motherboard PCI NIC/Wi-Fi)."
    say
    if prompt_yn "Install USB mitigation now? (Bluetooth host-detach + optional USB Ethernet EEE-off)" Y "USB mitigation"; then
      install_usb_bluetooth_disable
      say "Done."
    else
      die "Aborted by user"
    fi
    exit 0
  fi

  if [[ "$MODE" == "usb-mitigation-status" ]]; then
    usb_bt_mitigation_status
    exit 0
  fi

  # No-arguments default: launch the interactive menu instead of auto-running
  # the full wizard. The full wizard is still reachable via menu option 0
  # (Full configure) or any --install-* flag. Matches the R33/R34 menu-first UX.
  if [[ "$MODE" == "install" && "${_VFIO_ORIG_ARGC:-0}" -eq 0 ]]; then
    require_root "$@"
    require_writable_root_or_die
    vfio_menu
    exit 0
  fi

  require_root "$@"
  require_systemd
  require_writable_root_or_die

  detect_system
  user_selection
  apply_configuration
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  main "$@"
fi
